import Darwin
import Foundation
import CryptoKit

/// Closed binary layout only. Successful parsing is DATA, never a replay,
/// generation, content-effect or completed-Erase admission.
enum ColdEraseControlBinaryV1 {
    enum Kind: UInt64 { case continuation = 1, terminal = 2 }
    static let headerBytes: UInt64 = 128
    static let metadataBytes: UInt64 = 16_384
    static let maximumCatalogBytes: UInt64 = 1_190_405_184
    static let maximumContinuationBytes: UInt64 = 1_193_567_424
    static let maximumTerminalBytes: UInt64 = 104_415_360
    static let maximumProgressBytes: UInt64 = 55_542_890_560
    static let maximumTaskCount: UInt64 = 1_500_040
    static let maximumGeneratedTaskCount: UInt64 = 200_003
    static let maximumFramePayloadBytes: UInt64 = 864
    static let maximumRecipeBytes: UInt64 = 33_554_432
    static let maximumCatalogSources: UInt64 = 100_000
    static let maximumRangeWindowBytes: UInt64 = 33_554_432
    static let readChunkBytes = 65_536
    private static let coreMagic = padded("FE_COLD_CONTROL_BINARY_V1", count: 32)
    private static let frameMagic = padded("FE_COLD_FRAME_V1", count: 16)
    private static let progressMagic = padded("FE_COLD_PROG_V1", count: 16)
    private static let catalogMagic = padded("FE_COLD_CAT_V1", count: 16)

    /// Fixed-size comparison DATA only. Slot meanings are the V4 table;
    /// decoding never substitutes for the actual named/held/owner proof.
    struct Metadata: Equatable {
        let facts: [[UInt64]] // 64 * 11 words, in incumbent full-fact order.
        let digests: [Data] // 64 * 32 raw bytes; no hex/Base64 expansion.
        let identifiers: [Data] // 16 * 16 UUID bytes.
        let words: [UInt64] // 64 fixed role-labelled count words.
        let flags: Data // 64 fact modes, 16 state flags, terminal request1, 47 zero.
    }

    struct CatalogHeader: Equatable {
        let sourceCount: UInt64 // V2 physical-node count, never selected-source count.
        let encodedByteCount: UInt64
    }

    struct CatalogSourceHeader: Equatable {
        let pathByteCount: UInt64
        let rawByteCount: UInt64
        let sourceRole: UInt64
        let semanticVersion: UInt64
        let fullFact: [UInt64]
        let sha256: Data
        let policyCode: UInt64
    }

    enum CatalogSourceRole: UInt64 {
        case physicalOnly = 0
        case leaseMetadata = 1, ingressRecord = 2, leaseDirectory = 3, ingressMarker = 4
    }

    static func policyCode(_ value: TemporalPolicyObservationV1) throws -> UInt64 {
        func protection(_ value: String) throws -> UInt64 {
            switch value {
            case "unknown": return 0
            case "complete": return 1
            case "completeUnlessOpen": return 2
            case "completeUntilFirstUserAuthentication": return 3
            case "none": return 4
            case "other": return 5
            default: throw EraseIntentStoreError.invalidAuthority
            }
        }
        func boolean(_ value: Bool?) -> UInt64 {
            guard let value else { return 0 }
            return value ? 2 : 1
        }
        let state: UInt64 = value.state == .strictComplete ? 1 : 2
        return try state | (protection(value.urlProtection) << 8)
            | (protection(value.fileManagerProtection) << 16)
            | (boolean(value.backupExcluded) << 24)
            | (boolean(value.isDirectory) << 32)
            | (boolean(value.volumeSupportsProtection) << 40)
    }

    static func policy(_ code: UInt64, fact: [UInt64]) throws -> TemporalPolicyObservationV1 {
        guard fact.count == 11, code >> 48 == 0,
              let mode = UInt16(exactly: fact[2]) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let state: TemporalPolicyObservationV1.State
        switch code & 255 {
        case 1: state = .strictComplete
        case 2: state = .pendingSimulatorRequest
        default: throw EraseIntentStoreError.invalidAuthority
        }
        func protection(_ value: UInt64) throws -> String {
            switch value {
            case 0: return "unknown"
            case 1: return "complete"
            case 2: return "completeUnlessOpen"
            case 3: return "completeUntilFirstUserAuthentication"
            case 4: return "none"
            case 5: return "other"
            default: throw EraseIntentStoreError.invalidAuthority
            }
        }
        func boolean(_ value: UInt64) throws -> Bool? {
            switch value {
            case 0: return nil
            case 1: return false
            case 2: return true
            default: throw EraseIntentStoreError.invalidAuthority
            }
        }
        guard let device = UInt64(exactly: Int64(bitPattern: fact[0])) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let result = TemporalPolicyObservationV1(state: state, device: device,
            inode: fact[1], linkCount: fact[5], mode: mode,
            urlProtection: try protection((code >> 8) & 255),
            fileManagerProtection: try protection((code >> 16) & 255),
            backupExcluded: try boolean((code >> 24) & 255),
            isDirectory: try boolean((code >> 32) & 255),
            volumeSupportsProtection: try boolean((code >> 40) & 255))
        guard try policyCode(result) == code else { throw EraseIntentStoreError.invalidAuthority }
        return result // observation DATA, never a live policy receipt
    }

    struct Header: Equatable {
        let kind: Kind
        let ranges: [UInt64]
        let encodedByteCount: UInt64
    }
    struct FrameHeader: Equatable {
        enum Kind: UInt64 { case request = 1, observation = 2 }
        let kind: Kind
        let sequence: UInt64
        let taskKind: UInt64
        let payloadBytes: UInt64
        let recipeBytes: UInt64
        let changedFactCount: UInt64
        let previousFrameSHA256: Data
        var totalBytes: UInt64 {
            // The decoder/encoder proved this exact sum before construction.
            128 + payloadBytes + recipeBytes + 32
        }
    }

    /// Fixed logical Scratch selector only. No path/UUID/date is chosen here.
    /// Field order: kind, first-tree ordinal(0), source/request ordinal,
    /// erase-role tag, erase-role first ordinal, occurrence(0).
    static func taskKey(_ kind: ColdEraseScratchTaskKindV1) throws -> Data {
        var tag: UInt64 = 0, ordinal: UInt64 = 0
        var roleTag: UInt64 = 0, roleOrdinal: UInt64 = 0
        func role(_ value: ColdEraseScratchEraseRoleV1) {
            switch value {
            case .firstPrepare(let source): roleTag = 1; roleOrdinal = source
            case .firstHygiene(let source): roleTag = 2; roleOrdinal = source
            case .global: roleTag = 3
            }
        }
        switch kind {
        case .pendingRepair(let source): tag = 1; ordinal = source
        case .hygieneReceipt(let source): tag = 2; ordinal = source
        case .hygieneFinalization(let source): tag = 3; ordinal = source
        case .terminalPublication(let source, let eraseRole): tag = 4; ordinal = source; role(eraseRole)
        case .abortedPublication(let source, let eraseRole): tag = 5; ordinal = source; role(eraseRole)
        case .oldEraseCompletion(let source): tag = 6; ordinal = source
        case .globalErasePreparation: tag = 7
        case .globalEraseCompletion: tag = 8
        case .scratchControlMarker: tag = 9
        case .leaseDirectoryRename(let source): tag = 10; ordinal = source
        case .firstLeafRemoval(let source): tag = 11; ordinal = source
        case .generatedLeafRemoval(let request): tag = 12; ordinal = request
        case .firstDirectoryRemoval(let source): tag = 13; ordinal = source
        case .scratchRootRemoval: tag = 14
        case .ingressRootRemoval: tag = 15
        }
        if tag == 12 {
            guard ordinal > 0, ordinal <= maximumTaskCount else { throw EraseIntentStoreError.invalidAuthority }
        } else {
            guard ordinal < maximumCatalogSources, roleOrdinal < maximumCatalogSources else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        var result = Data(capacity: 48)
        for word in [tag, 0, ordinal, roleTag, roleOrdinal, 0] { appendWord(word, to: &result) }
        guard result.count == 48 else { throw EraseIntentStoreError.invalidAuthority }
        return result
    }

    static func decodeTaskKey(_ data: Data) throws -> ColdEraseScratchTaskKindV1 {
        guard data.count == 48 else { throw EraseIntentStoreError.invalidAuthority }
        var cursor = Cursor(data: data)
        let tag = try cursor.word()
        guard try cursor.word() == 0 else { throw EraseIntentStoreError.invalidAuthority }
        let ordinal = try cursor.word(), roleTag = try cursor.word(), roleOrdinal = try cursor.word()
        guard try cursor.word() == 0, cursor.offset == 48 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        func role() throws -> ColdEraseScratchEraseRoleV1 {
            switch roleTag {
            case 1: return .firstPrepare(sourceOrdinal: roleOrdinal)
            case 2: return .firstHygiene(sourceOrdinal: roleOrdinal)
            case 3:
                guard roleOrdinal == 0 else { throw EraseIntentStoreError.invalidAuthority }
                return .global
            default: throw EraseIntentStoreError.invalidAuthority
            }
        }
        let kind: ColdEraseScratchTaskKindV1
        switch tag {
        case 1: kind = .pendingRepair(sourceOrdinal: ordinal)
        case 2: kind = .hygieneReceipt(sourceOrdinal: ordinal)
        case 3: kind = .hygieneFinalization(sourceOrdinal: ordinal)
        case 4: kind = .terminalPublication(sourceOrdinal: ordinal, eraseRole: try role())
        case 5: kind = .abortedPublication(sourceOrdinal: ordinal, eraseRole: try role())
        case 6: kind = .oldEraseCompletion(sourceOrdinal: ordinal)
        case 7: kind = .globalErasePreparation
        case 8: kind = .globalEraseCompletion
        case 9: kind = .scratchControlMarker
        case 10: kind = .leaseDirectoryRename(sourceOrdinal: ordinal)
        case 11: kind = .firstLeafRemoval(sourceOrdinal: ordinal)
        case 12: kind = .generatedLeafRemoval(requestSequence: ordinal)
        case 13: kind = .firstDirectoryRemoval(sourceOrdinal: ordinal)
        case 14: kind = .scratchRootRemoval
        case 15: kind = .ingressRootRemoval
        default: throw EraseIntentStoreError.invalidAuthority
        }
        guard try taskKey(kind) == data else { throw EraseIntentStoreError.invalidAuthority }
        return kind
    }

    /// This key is only for once-per-first-P lookup. REQUEST keeps its full
    /// actual terminal/aborted role provenance; neither eraseRole nor response
    /// case opens another allocatable response for the same authenticated P.
    static func sameTaskFamily(_ lhs: ColdEraseScratchTaskKindV1,
        _ rhs: ColdEraseScratchTaskKindV1) -> Bool {
        func responseSource(_ value: ColdEraseScratchTaskKindV1) -> UInt64? {
            switch value {
            case .terminalPublication(let source, _), .abortedPublication(let source, _): return source
            default: return nil
            }
        }
        if let left = responseSource(lhs), let right = responseSource(rhs) { return left == right }
        return lhs == rhs
    }

    static func adding(_ values: UInt64...) throws -> UInt64 {
        var result: UInt64 = 0
        for value in values {
            let next = result.addingReportingOverflow(value)
            guard !next.overflow, next.partialValue <= UInt64(Int.max),
                  off_t(exactly: next.partialValue) != nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
            result = next.partialValue
        }
        return result
    }

    static func multiplying(_ lhs: UInt64, _ rhs: UInt64) throws -> UInt64 {
        let value = lhs.multipliedReportingOverflow(by: rhs)
        guard !value.overflow else { throw EraseIntentStoreError.invalidAuthority }
        return try adding(value.partialValue)
    }

    private static func padded(_ string: String, count: Int) -> Data {
        var value = Data(string.utf8)
        precondition(value.count <= count)
        value.append(Data(repeating: 0, count: count - value.count))
        return value
    }

    private static func appendWord(_ word: UInt64, to data: inout Data) {
        var value = word.littleEndian
        withUnsafeBytes(of: &value) { data.append(contentsOf: $0) }
    }

    private struct Cursor {
        let data: Data
        var offset = 0
        mutating func bytes(_ count: Int) throws -> Data {
            guard count >= 0, offset <= data.count,
                  count <= data.count - offset else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let start = data.startIndex + offset
            offset += count
            return Data(data[start..<(start + count)])
        }
        mutating func word() throws -> UInt64 {
            let value = try bytes(8)
            return value.enumerated().reduce(UInt64(0)) {
                $0 | (UInt64($1.element) << UInt64(8 * $1.offset))
            }
        }
    }

    static func header(kind: Kind, ranges: [UInt64]) throws -> Data {
        guard ranges.count == 6 else { throw EraseIntentStoreError.invalidAuthority }
        let caps: [UInt64] = kind == .continuation
            ? [maximumCatalogBytes, 1_048_576, 1_048_576, 1_048_576, 0, 0]
            : [100_663_296, 65_536, 524_288, 1_048_576, 1_048_576, 1_048_576]
        guard zip(ranges, caps).allSatisfy({ $0 <= $1 }) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var count = try adding(headerBytes, metadataBytes)
        for size in ranges { count = try adding(count, size) }
        guard count <= (kind == .continuation
                ? maximumContinuationBytes : maximumTerminalBytes) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var data = coreMagic
        for value in [UInt64(1), kind.rawValue, 0, 6] { appendWord(value, to: &data) }
        for value in ranges { appendWord(value, to: &data) }
        data.append(Data(repeating: 0, count: 16))
        guard data.count == Int(headerBytes) else { throw EraseIntentStoreError.invalidAuthority }
        return data
    }

    static func decodeHeader(_ data: Data) throws -> Header {
        guard data.count == Int(headerBytes) else { throw EraseIntentStoreError.invalidAuthority }
        var cursor = Cursor(data: data)
        guard try cursor.bytes(32) == coreMagic, try cursor.word() == 1,
              let kind = Kind(rawValue: try cursor.word()),
              try cursor.word() == 0, try cursor.word() == 6 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var ranges: [UInt64] = []
        for _ in 0..<6 { ranges.append(try cursor.word()) }
        guard try cursor.bytes(16) == Data(repeating: 0, count: 16),
              cursor.offset == data.count, try header(kind: kind, ranges: ranges) == data else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var count = try adding(headerBytes, metadataBytes)
        for size in ranges { count = try adding(count, size) }
        return Header(kind: kind, ranges: ranges, encodedByteCount: count)
    }

    static func progressHeader(coreSHA256: Data) throws -> Data {
        guard coreSHA256.count == 32 else { throw EraseIntentStoreError.invalidAuthority }
        var data = progressMagic
        appendWord(1, to: &data); appendWord(1, to: &data)
        data.append(coreSHA256)
        guard data.count == 64 else { throw EraseIntentStoreError.invalidAuthority }
        return data
    }

    static func decodeProgressHeader(_ data: Data,
        expectedCoreSHA256: Data) throws {
        guard data.count == 64, expectedCoreSHA256.count == 32,
              try progressHeader(coreSHA256: expectedCoreSHA256) == data else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    static func rawSHA256(_ hex: String) throws -> Data {
        let value = Array(hex.utf8)
        guard value.count == 64 else { throw EraseIntentStoreError.invalidAuthority }
        func digit(_ byte: UInt8) throws -> UInt8 {
            switch byte {
            case 48...57: return byte - 48
            case 97...102: return byte - 97 + 10
            default: throw EraseIntentStoreError.invalidAuthority
            }
        }
        var result = Data(capacity: 32)
        for index in stride(from: 0, to: 64, by: 2) {
            result.append(try (digit(value[index]) << 4) | digit(value[index + 1]))
        }
        return result
    }

    static func hexSHA256(_ bytes: Data) throws -> String {
        guard bytes.count == 32 else { throw EraseIntentStoreError.invalidAuthority }
        return bytes.map { String(format: "%02x", $0) }.joined()
    }

    /// The only binary fact order is device/inode/mode/UID/GID/nlink/size/
    /// mtime seconds/nanoseconds/ctime seconds/nanoseconds. Signed values use
    /// their Int64 bit pattern. A fact remains DATA until separately reproved.
    static func factWords(_ fact: EraseColdControlLeafFactV1,
        immutableParent: Bool = false) throws -> [UInt64] {
        guard let device = Int64(exactly: fact.device),
              let inode = UInt64(exactly: fact.inode),
              let mode = UInt64(exactly: fact.mode),
              let user = UInt64(exactly: fact.user),
              let group = UInt64(exactly: fact.group),
              let links = UInt64(exactly: fact.links),
              let size = Int64(exactly: fact.size),
              (0..<1_000_000_000).contains(fact.modifiedNanoseconds),
              (0..<1_000_000_000).contains(fact.changedNanoseconds) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return [UInt64(bitPattern: device), inode, mode, user, group,
            immutableParent ? 0 : links,
            immutableParent ? 0 : UInt64(bitPattern: size),
            immutableParent ? 0 : UInt64(bitPattern: fact.modifiedSeconds),
            immutableParent ? 0 : UInt64(bitPattern: fact.modifiedNanoseconds),
            immutableParent ? 0 : UInt64(bitPattern: fact.changedSeconds),
            immutableParent ? 0 : UInt64(bitPattern: fact.changedNanoseconds)]
    }

    static func metadata(_ value: Metadata, kind: Kind) throws -> Data {
        guard value.facts.count == 64, value.facts.allSatisfy({ $0.count == 11 }),
              value.digests.count == 64, value.digests.allSatisfy({ $0.count == 32 }),
              value.identifiers.count == 16, value.identifiers.allSatisfy({ $0.count == 16 }),
              value.words.count == 64, value.flags.count == 128 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let flags = Array(value.flags)
        // Fact mode: 0 absent, 1 full, 2 immutable parent. Policy selectors
        // derive from the fixed slot role; no caller policy bit is accepted.
        guard flags[0..<64].allSatisfy({ $0 <= 2 }),
              flags[64] <= 2, flags[65] <= 1,
              flags[66..<73].allSatisfy({ $0 <= 1 }),
              flags[73] <= 2, flags[74..<80].allSatisfy({ $0 <= 1 }),
              flags[80] <= 1, flags[81..<128].allSatisfy({ $0 == 0 }),
              flags[33..<64].allSatisfy({ $0 == 0 }),
              value.facts[33..<64].allSatisfy({ $0.allSatisfy({ $0 == 0 }) }),
              value.digests[18..<64].allSatisfy({ $0.allSatisfy({ $0 == 0 }) }),
              value.identifiers[7..<16].allSatisfy({ $0.allSatisfy({ $0 == 0 }) }) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        for index in 0..<64 {
            switch flags[index] {
            case 0:
                guard value.facts[index].allSatisfy({ $0 == 0 }) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            case 2:
                guard index < 6 || index == 6 || index == 7,
                      Int64(bitPattern: value.facts[index][0]) >= 0,
                      value.facts[index][1] > 0,
                      value.facts[index][2] > 0,
                      value.facts[index][2] <= UInt64(mode_t.max),
                      value.facts[index][3] <= UInt64(uid_t.max),
                      value.facts[index][4] <= UInt64(gid_t.max),
                      value.facts[index][5..<11].allSatisfy({ $0 == 0 }) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            case 1:
                let fact = value.facts[index]
                guard Int64(bitPattern: fact[0]) >= 0, fact[1] > 0,
                      fact[2] > 0, fact[2] <= UInt64(mode_t.max),
                      fact[3] <= UInt64(uid_t.max), fact[4] <= UInt64(gid_t.max),
                      fact[5] > 0, Int64(bitPattern: fact[6]) >= 0,
                      (0..<1_000_000_000).contains(Int64(bitPattern: fact[8])),
                      (0..<1_000_000_000).contains(Int64(bitPattern: fact[10])) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            default: throw EraseIntentStoreError.invalidAuthority
            }
        }
        if kind == .continuation {
            guard value.facts[30..<33].allSatisfy({ $0.allSatisfy({ $0 == 0 }) }),
                  flags[30..<33].allSatisfy({ $0 == 0 }),
                  value.words[30..<64].allSatisfy({ $0 == 0 }) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            if flags[80] == 0 {
                guard flags[28..<30].allSatisfy({ $0 == 0 }),
                      value.facts[28..<30].allSatisfy({ $0.allSatisfy({ $0 == 0 }) }),
                      value.words[22..<30].allSatisfy({ $0 == 0 }) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            } else {
                // Ingress V1/V2/V3's single immutable pre-Initial request.
                // The original V4 count words0...21 remain untouched; the
                // request uses only the eight truly unused words22...29.
                // A parser never supplies a current root or live setter.
                guard flags[28] == 1, flags[29] == 1, flags[6] == 1 || flags[6] == 2,
                      value.words[22] == 1, value.words[23] == 1,
                      value.words[24] == 1, value.words[26] == 1,
                      value.words[27] == 2, value.words[28] == 1,
                      value.words[29] == 1,
                      value.facts[28][2] & UInt64(S_IFMT) == UInt64(S_IFDIR),
                      value.facts[29][2] & UInt64(S_IFMT) == UInt64(S_IFDIR),
                      value.facts[28][5] >= 2, value.facts[29][5] >= 2,
                      value.facts[28][0] == value.facts[29][0],
                      value.facts[29][0..<5].elementsEqual(value.facts[6][0..<5]) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                // V4's fact6 is the authentic original first roster parent.
                // Fact29's mutable words are the genuine notification-after
                // CORE-BIRTH base, proved in full by the actual maker. This
                // pure codec compares only their identical stable identity.
                let firstPolicy = try policy(value.words[25], fact: value.facts[28])
                guard firstPolicy.isDirectory == true else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
        } else {
            guard value.facts[6..<8].allSatisfy({ $0.allSatisfy({ $0 == 0 }) }),
                  flags[6..<8].allSatisfy({ $0 == 0 }),
                  value.words[20..<64].allSatisfy({ $0 == 0 }) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            if flags[80] == 0 {
                guard flags[31..<33].allSatisfy({ $0 == 0 }),
                      value.facts[31..<33].allSatisfy({ $0.allSatisfy({ $0 == 0 }) }),
                      value.words[9..<20].allSatisfy({ $0 == 0 }) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            } else {
                // V6/V7's one closed completed-Diagnostics policy REQUEST.
                // This remains DATA: only the genuine terminal issuer may
                // admit a physical prefix or request a current-process setter.
                guard flags[31] == 1, flags[32] == 1,
                      flags[65] == 1, flags[77] == 1,
                      value.words[9] == 1, value.words[10] == 1,
                      value.words[11] == 1, value.words[14] == 1,
                      value.words[15] == 1, value.words[16] == 1,
                      value.words[17] == 2, value.words[18] == 1,
                      value.words[19] == 2,
                      value.words[4] > 0, value.words[4] <= 524_288,
                      value.facts[31][2] & UInt64(S_IFMT) == UInt64(S_IFDIR),
                      value.facts[32][2] & UInt64(S_IFMT) == UInt64(S_IFREG),
                      value.facts[31][5] >= 2, value.facts[32][5] == 1,
                      value.facts[32][6] == value.words[4],
                      value.facts[31] == value.facts[20],
                      value.facts[32] == value.facts[27],
                      value.digests[0] == value.digests[17],
                      !value.digests[0].allSatisfy({ $0 == 0 }),
                      !value.digests[16].allSatisfy({ $0 == 0 }) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                let rootPolicy = try policy(value.words[12], fact: value.facts[31])
                let leafPolicy = try policy(value.words[13], fact: value.facts[32])
                guard rootPolicy.isDirectory == true, leafPolicy.isDirectory == false else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
        }
        var result = Data(capacity: Int(metadataBytes))
        for fact in value.facts { for word in fact { appendWord(word, to: &result) } }
        for digest in value.digests { result.append(digest) }
        for identifier in value.identifiers { result.append(identifier) }
        for word in value.words { appendWord(word, to: &result) }
        result.append(value.flags)
        guard result.count == 8_576 else { throw EraseIntentStoreError.invalidAuthority }
        result.append(Data(repeating: 0, count: 7_808))
        guard result.count == Int(metadataBytes) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return result
    }

    static func decodeMetadata(_ data: Data, kind: Kind) throws -> Metadata {
        guard data.count == Int(metadataBytes) else { throw EraseIntentStoreError.invalidAuthority }
        var cursor = Cursor(data: data)
        var facts: [[UInt64]] = []
        facts.reserveCapacity(64)
        for _ in 0..<64 {
            var words: [UInt64] = []
            words.reserveCapacity(11)
            for _ in 0..<11 { words.append(try cursor.word()) }
            facts.append(words)
        }
        var digests: [Data] = [], identifiers: [Data] = [], words: [UInt64] = []
        digests.reserveCapacity(64); identifiers.reserveCapacity(16); words.reserveCapacity(64)
        for _ in 0..<64 { digests.append(try cursor.bytes(32)) }
        for _ in 0..<16 { identifiers.append(try cursor.bytes(16)) }
