              value.rawByteCount <= maximumRangeWindowBytes,
              let role = CatalogSourceRole(rawValue: value.sourceRole),
              value.fullFact.count == 11, value.sha256.count == 32 else {
            throw EraseIntentStoreError.invalidAuthority
        }
