              value.fullFact[4] <= UInt64(gid_t.max),
              Int64(bitPattern: value.fullFact[6]) >= 0,
              (0..<1_000_000_000).contains(Int64(bitPattern: value.fullFact[8])),
              (0..<1_000_000_000).contains(Int64(bitPattern: value.fullFact[10])) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        if role == .leaseDirectory || (role == .physicalOnly && mode & UInt64(S_IFMT) == UInt64(S_IFDIR)) {
            guard mode & UInt64(S_IFMT) == UInt64(S_IFDIR), value.fullFact[5] >= 2 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            guard value.sha256.allSatisfy({ $0 == 0 }) else { throw EraseIntentStoreError.invalidAuthority }
        } else {
            guard mode & UInt64(S_IFMT) == UInt64(S_IFREG), value.fullFact[5] == 1,
