        appendWord(value.policyCode, to: &result)
        guard result.count == 160 else { throw EraseIntentStoreError.invalidAuthority }
        return result
    }

    /// Mirrors only the incumbent closed filename vocabulary for catalog
    /// DATA. Actual canonical codecs/first ownership are separately proved.
    static func catalogRole(path: String) throws -> (role: CatalogSourceRole, version: UInt64) {
        let components = path.split(separator: "/", omittingEmptySubsequences: false)
        func canonicalUUID(_ value: String) -> Bool {
            guard let identifier = UUID(uuidString: value) else { return false }
            return identifier.uuidString.lowercased() == value
        }
        func leaseDirectory(_ component: Substring) -> Bool {
            let name = String(component)
            let original = name.hasPrefix(".deleting-") ? String(name.dropFirst(".deleting-".count)) : name
            for purpose in ScratchDataPurposeV1.allCases {
                let prefix = purpose.rawValue.lowercased() + "-"
                if original.hasPrefix(prefix), canonicalUUID(String(original.dropFirst(prefix.count))) { return true }
            }
            return false
        }
        if (components.count == 2 || components.count == 3), components[0] == "ScratchDataV1",
           leaseDirectory(components[1]) {
            if components.count == 2 { return (.leaseDirectory, 1) }
            if components[2] == "lease.json" { return (.leaseMetadata, 1) }
        }
        guard components.count == 2, components[0] == "ProtectedIngressReceiptsV1" else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let name = String(components[1])
        if name == "scratch-erase.json" { return (.ingressMarker, 1) }
        let families: [(String, [String])] = [
            ("ingress-", [".pending.json.replacement", ".prepare.json", ".claim.json", ".published.json", ".pending.json", ".terminal.json", ".aborted.json"]),
            ("erase-", [".prepare.json", ".complete.json"]),
            ("hygiene-", [".prepare.json.finalizing", ".prepare.json", ".json"])
        ]
        for (prefix, suffixes) in families where name.hasPrefix(prefix) {
            for suffix in suffixes where name.hasSuffix(suffix) {
                guard name.count >= prefix.count + suffix.count else { continue }
                let identifier = String(name.dropFirst(prefix.count).dropLast(suffix.count))
                if canonicalUUID(identifier) {
                    return (.ingressRecord,
                        prefix == "hygiene-" && suffix != ".json" ? 2 : 1)
                }
            }
        }
        throw EraseIntentStoreError.invalidAuthority
    }

    /// A selected catalog range keeps the incumbent reader's own limit.
    /// The coarse role ceiling cannot widen a specific canonical codec.
    static func catalogReaderLimit(path: String) throws -> UInt64 {
        let selected = try catalogRole(path: path)
        switch selected.role {
        case .leaseMetadata: return 65_536
        case .leaseDirectory: return 0
        case .ingressMarker: return maximumRecipeBytes
        case .ingressRecord:
            let name = path.split(separator: "/", omittingEmptySubsequences: false).last!
            if name.hasPrefix("hygiene-"), name.hasSuffix(".json"),
               !name.hasSuffix(".prepare.json") { return 4_096 }
            return 262_144
        case .physicalOnly: throw EraseIntentStoreError.invalidAuthority
        }
    }

    static func decodeCatalogSourceHeader(_ data: Data) throws -> CatalogSourceHeader {
        guard data.count == 160 else { throw EraseIntentStoreError.invalidAuthority }
        var cursor = Cursor(data: data)
        let path = try cursor.word(), raw = try cursor.word()
        let role = try cursor.word(), version = try cursor.word()
        var fact: [UInt64] = []
        fact.reserveCapacity(11)
        for _ in 0..<11 { fact.append(try cursor.word()) }
        let sha = try cursor.bytes(32)
        let policyCode = try cursor.word()
        guard cursor.offset == 160 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let result = CatalogSourceHeader(pathByteCount: path, rawByteCount: raw,
            sourceRole: role, semanticVersion: version, fullFact: fact, sha256: sha,
            policyCode: policyCode)
        guard try catalogSourceHeader(result) == data else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return result
    }

    static func frameHeader(kind: FrameHeader.Kind, sequence: UInt64,
        taskKind: UInt64, payloadBytes: UInt64, recipeBytes: UInt64,
        changedFactCount: UInt64, previousFrameSHA256: Data) throws -> Data {
        guard sequence > 0, sequence <= maximumTaskCount,
              (1...15).contains(taskKind),
              payloadBytes <= maximumFramePayloadBytes,
              recipeBytes <= maximumRecipeBytes,
              (kind == .request || recipeBytes == 0),
              changedFactCount <= 4, previousFrameSHA256.count == 32 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        _ = try adding(128, payloadBytes, recipeBytes, 32)
        var data = frameMagic
        for value in [UInt64(1), kind.rawValue, sequence, taskKind,
                payloadBytes, recipeBytes, changedFactCount, 0] {
            appendWord(value, to: &data)
        }
        data.append(previousFrameSHA256)
        data.append(Data(repeating: 0, count: 16))
        guard data.count == 128 else { throw EraseIntentStoreError.invalidAuthority }
        return data
    }

    static func decodeFrameHeader(_ data: Data) throws -> FrameHeader {
        guard data.count == 128 else { throw EraseIntentStoreError.invalidAuthority }
        var cursor = Cursor(data: data)
        guard try cursor.bytes(16) == frameMagic, try cursor.word() == 1,
              let kind = FrameHeader.Kind(rawValue: try cursor.word()) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let sequence = try cursor.word(), task = try cursor.word()
        let payload = try cursor.word(), recipe = try cursor.word(), facts = try cursor.word()
        guard try cursor.word() == 0 else { throw EraseIntentStoreError.invalidAuthority }
        let prior = try cursor.bytes(32)
        guard try cursor.bytes(16) == Data(repeating: 0, count: 16),
              cursor.offset == 128,
              try frameHeader(kind: kind, sequence: sequence, taskKind: task,
                payloadBytes: payload, recipeBytes: recipe, changedFactCount: facts,
                previousFrameSHA256: prior) == data else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return FrameHeader(kind: kind, sequence: sequence, taskKind: task,
            payloadBytes: payload, recipeBytes: recipe, changedFactCount: facts,
            previousFrameSHA256: prior)
    }
}

