        expectedCoreSHA256: Data) throws {
        guard data.count == 64, expectedCoreSHA256.count == 32,
              try progressHeader(coreSHA256: expectedCoreSHA256) == data else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    private static func requireFrameFields(kind: ColdEraseControlBinaryV1.FrameHeader.Kind,
        sequence: UInt64, domain: Domain, taskKind: UInt64,
        payloadBytes: UInt64, recipeBytes: UInt64, changedFactCount: UInt64,
        previousFrameSHA256: Data) throws -> UInt64 {
        guard sequence > 0, sequence <= maximumTaskCount,
              payloadBytes == UInt64(payloadByteCount),
              (1...4).contains(changedFactCount), previousFrameSHA256.count == 32 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        switch domain {
        case .reader:
            guard taskKind == 1 || taskKind == 2 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            if kind == .request && taskKind == 1 {
                guard recipeBytes > 0, recipeBytes <= maximumReaderRecipeBytes else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            } else {
                guard recipeBytes == 0 else { throw EraseIntentStoreError.invalidAuthority }
            }
        case .namespace:
            guard taskKind == 1, recipeBytes == 0 else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        return try ColdEraseControlBinaryV1.adding(128, payloadBytes, recipeBytes, 32)
    }

    static func frameHeader(kind: ColdEraseControlBinaryV1.FrameHeader.Kind,
        sequence: UInt64, domain: Domain, taskKind: UInt64,
        payloadBytes: UInt64, recipeBytes: UInt64, changedFactCount: UInt64,
        previousFrameSHA256: Data) throws -> Data {
        _ = try requireFrameFields(kind: kind, sequence: sequence, domain: domain,
            taskKind: taskKind, payloadBytes: payloadBytes, recipeBytes: recipeBytes,
            changedFactCount: changedFactCount, previousFrameSHA256: previousFrameSHA256)
        var data = frameMagic
        for word in [UInt64(1), kind.rawValue, sequence, taskKind,
                payloadBytes, recipeBytes, changedFactCount, domain.rawValue] {
            appendWord(word, to: &data)
        }
        data.append(previousFrameSHA256)
        data.append(Data(repeating: 0, count: 16))
        guard data.count == 128 else { throw EraseIntentStoreError.invalidAuthority }
        return data
    }

    static func decodeFrameHeader(_ data: Data) throws -> FrameHeader {
        guard data.count == 128 else { throw EraseIntentStoreError.invalidAuthority }
        var cursor = Cursor(data: data)
        guard try cursor.bytes(16) == frameMagic, try cursor.word() == 1,
              let kind = ColdEraseControlBinaryV1.FrameHeader.Kind(rawValue: try cursor.word()) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let sequence = try cursor.word(), task = try cursor.word()
        let payload = try cursor.word(), recipe = try cursor.word(), facts = try cursor.word()
        guard let domain = Domain(rawValue: try cursor.word()) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let prior = try cursor.bytes(32)
        guard try cursor.bytes(16).allSatisfy({ $0 == 0 }), cursor.offset == 128,
              try frameHeader(kind: kind, sequence: sequence, domain: domain,
                taskKind: task, payloadBytes: payload, recipeBytes: recipe,
                changedFactCount: facts, previousFrameSHA256: prior) == data else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return try FrameHeader(kind: kind, sequence: sequence, domain: domain,
            taskKind: task, payloadBytes: payload, recipeBytes: recipe,
            changedFactCount: facts, previousFrameSHA256: prior)
    }

    /// Successful shape serialization/decoding is comparison DATA only. This
    /// does not check role semantics, Request identity, after-state, parent
    /// selector, actual fact/digest provenance, acceptance or unused-slot rules.
    static func payloadFields(_ value: PayloadFields) throws -> Data {
        guard value.words.count == 16, value.facts.count == 4,
              value.facts.allSatisfy({ $0.count == 11 }), value.digests.count == 12,
              value.digests.allSatisfy({ $0.count == 32 }) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var data = Data(capacity: payloadByteCount)
        for word in value.words { appendWord(word, to: &data) }
        for fact in value.facts {
            for word in fact { appendWord(word, to: &data) }
        }
        for digest in value.digests { data.append(digest) }
        guard data.count == payloadByteCount else { throw EraseIntentStoreError.invalidAuthority }
        return data
    }

    static func decodePayloadFields(_ data: Data) throws -> PayloadFields {
        guard data.count == payloadByteCount else { throw EraseIntentStoreError.invalidAuthority }
        var cursor = Cursor(data: data)
        var words: [UInt64] = []
        words.reserveCapacity(16)
        for _ in 0..<16 { words.append(try cursor.word()) }
        var facts: [[UInt64]] = []
        facts.reserveCapacity(4)
        for _ in 0..<4 {
            var fact: [UInt64] = []
            fact.reserveCapacity(11)
            for _ in 0..<11 { fact.append(try cursor.word()) }
            facts.append(fact)
        }
        var digests: [Data] = []
        digests.reserveCapacity(12)
        for _ in 0..<12 { digests.append(try cursor.bytes(32)) }
        let result = PayloadFields(words: words, facts: facts, digests: digests)
        guard cursor.offset == payloadByteCount, try payloadFields(result) == data else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return result
    }

    private static func padded(_ value: String, count: Int) -> Data {
        // Called only for the three fixed literals above, never caller text.
        var data = Data(value.utf8)
        precondition(data.count <= count)
        data.append(Data(repeating: 0, count: count - data.count))
        return data
    }

    private static func appendWord(_ word: UInt64, to data: inout Data) {
        var value = word.littleEndian
        withUnsafeBytes(of: &value) { data.append(contentsOf: $0) }
    }

    private struct Cursor {
        let data: Data
        var offset = 0

        mutating func bytes(_ count: Int) throws -> Data {
            guard count >= 0, offset >= 0, offset <= data.count,
                  count <= data.count - offset else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let start = data.index(data.startIndex, offsetBy: offset)
            let end = data.index(start, offsetBy: count)
            offset += count
            return Data(data[start..<end])
        }

        mutating func word() throws -> UInt64 {
            guard offset >= 0, offset <= data.count, data.count - offset >= 8 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            var value: UInt64 = 0
            for byte in 0..<8 {
                let index = data.index(data.startIndex, offsetBy: offset + byte)
                value |= UInt64(data[index]) << UInt64(8 * byte)
            }
            offset += 8
            return value
        }
    }
}

/// Specialized cold comparison DATA. Only the retained range owner can mint
/// a selector; interpreting these fields never grants a primitive or close.
enum ColdEraseScratchTaskFactSelectorV1: Equatable {
    case scratchRoot, ingressRoot, operationsParent
    case firstPhysicalNode(UInt64), firstCanonicalSource(UInt64)
    case taskTemporary(UInt64), taskResult(UInt64), hygieneIntermediate(UInt64)

    func encodedWord() throws -> UInt64 {
        let domain: UInt64, ordinal: UInt64
        switch self {
        case .scratchRoot: domain = 1; ordinal = 0
        case .ingressRoot: domain = 2; ordinal = 0
        case .operationsParent: domain = 3; ordinal = 0
        case .firstPhysicalNode(let value): domain = 4; ordinal = value
        case .firstCanonicalSource(let value): domain = 5; ordinal = value
        case .taskTemporary(let value): domain = 6; ordinal = value
        case .taskResult(let value): domain = 7; ordinal = value
        case .hygieneIntermediate(let value): domain = 8; ordinal = value
        }
        if domain == 4 || domain == 5 {
            guard ordinal < ColdEraseControlBinaryV1.maximumCatalogSources else {
                throw EraseIntentStoreError.invalidAuthority
            }
        } else if domain >= 6 {
            guard ordinal > 0, ordinal <= ColdEraseControlBinaryV1.maximumTaskCount else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        return domain | (ordinal << 8)
    }

    init(encodedWord: UInt64) throws {
        let ordinal = encodedWord >> 8
        switch encodedWord & 255 {
        case 1: self = .scratchRoot
        case 2: self = .ingressRoot
        case 3: self = .operationsParent
        case 4: self = .firstPhysicalNode(ordinal)
        case 5: self = .firstCanonicalSource(ordinal)
        case 6: self = .taskTemporary(ordinal)
        case 7: self = .taskResult(ordinal)
        case 8: self = .hygieneIntermediate(ordinal)
        default: throw EraseIntentStoreError.invalidAuthority
        }
        guard try self.encodedWord() == encodedWord else { throw EraseIntentStoreError.invalidAuthority }
    }
}

/// Fixed primitive comparison storage, not a caller proof or authority.
/// Actual retained Attempt alone supplies the four ordered semantic slots.
struct ColdEraseScratchTaskProgressFactV1 {
    let selector: UInt64
    fileprivate let fact: ColdEraseCatalogSourceIndexV1.Fact?
    fileprivate let digest: ColdEraseCatalogSourceIndexV1.Digest
    let policyCode: UInt64
    let isPresent: Bool

    init(selector: UInt64, fullFact: String?, contentSHA256: String?,
        policy: TemporalPolicyObservationV1?) throws {
        let selected = try ColdEraseScratchTaskFactSelectorV1(encodedWord: selector)
        self.selector = selector
        if let fullFact {
            let fields = fullFact.split(separator: "|", omittingEmptySubsequences: false)
            guard fields.count == 11 else { throw EraseIntentStoreError.invalidAuthority }
            var words: [UInt64] = []
            words.reserveCapacity(11)
            for index in 0..<11 {
                if [0, 6, 7, 8, 9, 10].contains(index) {
                    guard let value = Int64(fields[index]), String(value) == fields[index],
                          (index != 0 && index != 6) || value >= 0 else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    words.append(UInt64(bitPattern: value))
                } else {
                    guard let value = UInt64(fields[index]), String(value) == fields[index] else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    words.append(value)
                }
            }
            let parsed = try ColdEraseCatalogSourceIndexV1.Fact(words)
            guard parsed.rendered == fullFact, parsed.inode > 0, parsed.links > 0,
                  parsed.mode & UInt64(S_IFMT) == UInt64(S_IFDIR)
                    || parsed.mode & UInt64(S_IFMT) == UInt64(S_IFREG) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let directory = parsed.mode & UInt64(S_IFMT) == UInt64(S_IFDIR)
            if directory {
                guard contentSHA256 == nil else { throw EraseIntentStoreError.invalidAuthority }
                digest = try .init(Data(repeating: 0, count: 32))
            } else {
                guard parsed.links == 1, let contentSHA256 else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                digest = try .init(ColdEraseControlBinaryV1.rawSHA256(contentSHA256))
            }
            if selected == .operationsParent {
                guard directory, policy == nil else { throw EraseIntentStoreError.invalidAuthority }
                policyCode = 0 // explicitly unrepresented comparison policy only
            } else {
                guard let policy, policy.device == words[0], policy.inode == parsed.inode,
                      policy.linkCount == parsed.links, UInt64(policy.mode) == parsed.mode,
                      policy.isDirectory == directory else { throw EraseIntentStoreError.invalidAuthority }
                policyCode = try ColdEraseControlBinaryV1.policyCode(policy)
                guard policyCode != 0 else { throw EraseIntentStoreError.invalidAuthority }
            }
            fact = parsed; isPresent = true
        } else {
            guard contentSHA256 == nil, policy == nil, selected != .operationsParent else {
                throw EraseIntentStoreError.invalidAuthority
            }
            fact = nil; digest = try .init(Data(repeating: 0, count: 32))
            policyCode = 0; isPresent = false
        }
    }

    fileprivate func encodedSlot() throws -> Data {
        _ = try ColdEraseScratchTaskFactSelectorV1(encodedWord: selector)
        var data = Data(capacity: 144)
        func word(_ value: UInt64) {
            var value = value.littleEndian
            withUnsafeBytes(of: &value) { data.append(contentsOf: $0) }
        }
        word(selector)
        for value in fact?.words ?? Array(repeating: UInt64(0), count: 11) { word(value) }
        for value in [digest.first, digest.second, digest.third, digest.fourth] { word(value) }
        word(policyCode); word(isPresent ? 1 : 0)
        guard data.count == 144 else { throw EraseIntentStoreError.invalidAuthority }
        return data
    }
}

/// Exactly four fixed slots; canonical unused slots are zero. A successful
/// construction only validates DATA. The actual semantic producer proves
/// required slot ordering/presence against its genuine current prefix.
struct ColdEraseScratchTaskPhysicalPayloadV1 {
    let count: UInt64
    let flags: UInt64 = 0
    private let first: ColdEraseScratchTaskProgressFactV1
    private let second: ColdEraseScratchTaskProgressFactV1?
    private let third: ColdEraseScratchTaskProgressFactV1?
    private let fourth: ColdEraseScratchTaskProgressFactV1?

    init(facts: [ColdEraseScratchTaskProgressFactV1]) throws {
        guard !facts.isEmpty, facts.count <= 4 else { throw EraseIntentStoreError.invalidAuthority }
        count = UInt64(facts.count); first = facts[0]
        second = facts.count > 1 ? facts[1] : nil
        third = facts.count > 2 ? facts[2] : nil
        fourth = facts.count > 3 ? facts[3] : nil
    }

    fileprivate func encodedFacts() throws -> Data {
        var data = Data(capacity: 576)
        for fact in [Optional(first), second, third, fourth] {
            if let fact { data.append(try fact.encodedSlot()) }
            else { data.append(Data(repeating: 0, count: 144)) }
        }
        guard flags == 0, data.count == 576 else { throw EraseIntentStoreError.invalidAuthority }
        return data
    }
}

// BEGIN PRIVATE INSERTABLE COLD SCRATCH PROGRESS PAYLOAD CODEC V1
// Insert after ColdEraseScratchTaskPhysicalPayloadV1, in EraseIntentStore.swift.
// Pure bounded comparison DATA only; this fragment constructs no live owner,
// Plan, Pending, settlement, primitive permission or completed-Erase proof.

extension ColdEraseScratchTaskProgressFactV1 {
    /// Scalar decoding preserves the existing full-fact/policy representation.
    /// A selected absence is distinct from a canonical unused all-zero slot.
    fileprivate init(coldEncodedSlot data: Data) throws {
        guard data.count == 144 else { throw EraseIntentStoreError.invalidAuthority }
        var cursor = ColdEraseScratchProgressPayloadCodecV1.Cursor(data: data)
        let selector = try cursor.word()
        let selected = try ColdEraseScratchTaskFactSelectorV1(encodedWord: selector)
        var words: [UInt64] = []
        words.reserveCapacity(11)
        for _ in 0..<11 { words.append(try cursor.word()) }
        let digestBytes = try cursor.bytes(32)
        let policyCode = try cursor.word(), presence = try cursor.word()
        guard cursor.offset == 144, presence <= 1 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        self.selector = selector
        self.policyCode = policyCode
        self.isPresent = presence == 1
        self.digest = try .init(digestBytes)
        if presence == 0 {
            guard selected != .operationsParent,
                  words.allSatisfy({ $0 == 0 }),
                  digestBytes.allSatisfy({ $0 == 0 }), policyCode == 0 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            self.fact = nil
        } else {
            let fact = try ColdEraseCatalogSourceIndexV1.Fact(words)
            let directory = fact.mode & UInt64(S_IFMT) == UInt64(S_IFDIR)
            let regular = fact.mode & UInt64(S_IFMT) == UInt64(S_IFREG)
            guard Int64(bitPattern: fact.device) >= 0,
                  fact.inode > 0, fact.links > 0, directory || regular,
                  !regular || fact.links == 1 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            switch selected {
            case .scratchRoot, .ingressRoot, .operationsParent:
                guard directory else { throw EraseIntentStoreError.invalidAuthority }
            case .taskTemporary, .taskResult, .hygieneIntermediate:
                guard regular else { throw EraseIntentStoreError.invalidAuthority }
            case .firstPhysicalNode, .firstCanonicalSource: break
            }
            if directory {
                guard digestBytes.allSatisfy({ $0 == 0 }) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            } else {
                guard digestBytes.contains(where: { $0 != 0 }) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            if selected == .operationsParent {
                guard policyCode == 0 else { throw EraseIntentStoreError.invalidAuthority }
            } else {
                let policy = try ColdEraseControlBinaryV1.policy(policyCode, fact: words)
                guard policy.isDirectory == directory else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            self.fact = fact
        }
        guard try encodedSlot() == data else { throw EraseIntentStoreError.invalidAuthority }
    }
}

enum ColdEraseScratchProgressPayloadCodecV1 {
    static let payloadBytes = 864
    static let fixedBytes = 288
    static let factBytes = 144
    private static let postDomain = Data("FE_COLD_SCRATCH_POST_V1\0".utf8)

    enum SourceDomain: UInt64 { case absent = 0, catalog = 1, progress = 2 }

    /// Fixed payload scalars. sequence comes from the separately checked
    /// frame header, not an additional encoded field or allocatable task ID.
    struct Request {
        let kind: ColdEraseScratchTaskKindV1
        let sequence: UInt64
        let sourceDomain: SourceDomain
        let sourceRangeKey: UInt64
        let sourceSHA256: Data
        let stateBeforeSHA256: Data
        let sourceSelector: UInt64
        let targetSelector: UInt64
        let choiceWord: UInt64
        let operationID: UUID
        let publicationTempID: UUID
        let selectedDateBits: UInt64
        let recipeLength: UInt64
        let recipeSHA256: Data
        let generatedRangeKey: UInt64
        let substepGrammar: UInt64
        let facts: ColdEraseScratchTaskPhysicalPayloadV1
    }

    struct Observation {
        let kind: ColdEraseScratchTaskKindV1
        let sequence: UInt64
        let requestSHA256: Data
        let stateAfterSHA256: Data
        let generatedRangeKey: UInt64
        let flags: UInt64
        let facts: ColdEraseScratchTaskPhysicalPayloadV1
    }

    /// Own bounded cursor: Binary's private cursor is deliberately untouched.
    fileprivate struct Cursor {
        let data: Data
        var offset = 0
        mutating func bytes(_ count: Int) throws -> Data {
            guard count >= 0, offset <= data.count, count <= data.count - offset else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let start = data.startIndex + offset
            offset += count
            return Data(data[start..<(start + count)])
        }
        mutating func word() throws -> UInt64 {
            let bytes = try bytes(8)
            return bytes.enumerated().reduce(UInt64(0)) {
                $0 | (UInt64($1.element) << UInt64(8 * $1.offset))
            }
        }
    }

    private static func appendWord(_ word: UInt64, to data: inout Data) {
        var value = word.littleEndian
        withUnsafeBytes(of: &value) { data.append(contentsOf: $0) }
    }

    private static func uuidBytes(_ value: UUID) throws -> Data {
        var tuple = value.uuid
        let bytes = withUnsafeBytes(of: &tuple) { Data($0) }
        guard bytes.count == 16, bytes.contains(where: { $0 != 0 }) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return bytes
    }

    private static func uuid(_ bytes: Data) throws -> UUID {
        guard bytes.count == 16, bytes.contains(where: { $0 != 0 }) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let b = Array(bytes) // exactly sixteen bytes, never an input-sized copy
        let value = UUID(uuid: (b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7],
            b[8], b[9], b[10], b[11], b[12], b[13], b[14], b[15]))
        guard try uuidBytes(value) == bytes else { throw EraseIntentStoreError.invalidAuthority }
        return value
    }

    private static func requireDigest(_ value: Data, nonzero: Bool) throws {
        guard value.count == 32, !nonzero || value.contains(where: { $0 != 0 }) else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    private static func taskTag(_ kind: ColdEraseScratchTaskKindV1) throws -> UInt64 {
        var cursor = Cursor(data: try ColdEraseControlBinaryV1.taskKey(kind))
        return try cursor.word()
    }

    private static func requireHeader(_ header: ColdEraseControlBinaryV1.FrameHeader,
        kind: ColdEraseControlBinaryV1.FrameHeader.Kind, sequence: UInt64,
        task: ColdEraseScratchTaskKindV1, factCount: UInt64, recipeBytes: UInt64,
        previousSHA256: Data? = nil) throws {
        let encoded = try ColdEraseControlBinaryV1.frameHeader(kind: header.kind,
            sequence: header.sequence, taskKind: header.taskKind,
            payloadBytes: header.payloadBytes, recipeBytes: header.recipeBytes,
            changedFactCount: header.changedFactCount,
            previousFrameSHA256: header.previousFrameSHA256)
        guard try ColdEraseControlBinaryV1.decodeFrameHeader(encoded) == header,
              header.kind == kind, header.sequence == sequence,
              header.taskKind == (try taskTag(task)),
              header.payloadBytes == UInt64(payloadBytes),
              header.recipeBytes == recipeBytes, header.changedFactCount == factCount,
              previousSHA256 == nil || header.previousFrameSHA256 == previousSHA256 else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    private static func decodeFacts(_ bytes: Data, count: UInt64) throws
        -> (ColdEraseScratchTaskPhysicalPayloadV1, [ColdEraseScratchTaskProgressFactV1]) {
        guard bytes.count == 576, (1...4).contains(count) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var cursor = Cursor(data: bytes)
        var facts: [ColdEraseScratchTaskProgressFactV1] = []
        facts.reserveCapacity(4)
        for index in UInt64(0)..<4 {
            let slot = try cursor.bytes(factBytes)
            if index < count {
                facts.append(try .init(coldEncodedSlot: slot))
            } else {
                guard slot.allSatisfy({ $0 == 0 }) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
        }
        guard cursor.offset == 576 else { throw EraseIntentStoreError.invalidAuthority }
        let wrapped = try ColdEraseScratchTaskPhysicalPayloadV1(facts: facts)
        guard try wrapped.encodedFacts() == bytes else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return (wrapped, facts)
    }

    private static func checkedFacts(_ value: ColdEraseScratchTaskPhysicalPayloadV1) throws
        -> [ColdEraseScratchTaskProgressFactV1] {
        guard value.flags == 0 else { throw EraseIntentStoreError.invalidAuthority }
        return try decodeFacts(value.encodedFacts(), count: value.count).1
    }

    private static func requireChoice(_ value: Request) throws {
        guard value.choiceWord & ~UInt64(0x7ff) == 0,
              (value.choiceWord & 255) <= 2 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let disposition = value.choiceWord & 255
        let hasDate = value.choiceWord & 256 != 0
        let inherited = value.choiceWord & 512 != 0
        let exclusive = value.choiceWord & 1024 != 0
        if hasDate {
            guard Double(bitPattern: value.selectedDateBits).isFinite else {
                throw EraseIntentStoreError.invalidAuthority
            }
        } else {
            guard value.selectedDateBits == 0 else { throw EraseIntentStoreError.invalidAuthority }
        }
        switch value.kind {
        case .pendingRepair, .abortedPublication, .oldEraseCompletion, .globalEraseCompletion:
            guard disposition == 0, !hasDate, inherited, !exclusive else {
                throw EraseIntentStoreError.invalidAuthority
            }
        case .hygieneReceipt, .hygieneFinalization:
            guard disposition == 0, hasDate, inherited, !exclusive else {
                throw EraseIntentStoreError.invalidAuthority
            }
        case .terminalPublication:
            guard (disposition == 1 && !hasDate) || (disposition == 2 && hasDate),
                  !exclusive else { throw EraseIntentStoreError.invalidAuthority }
        case .scratchControlMarker:
            guard disposition == 0, !hasDate, !inherited, exclusive else {
                throw EraseIntentStoreError.invalidAuthority
            }
        case .globalErasePreparation, .leaseDirectoryRename, .firstLeafRemoval,
             .generatedLeafRemoval, .firstDirectoryRemoval, .scratchRootRemoval,
             .ingressRootRemoval:
            guard disposition == 0, !hasDate, !inherited, !exclusive else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        _ = try uuidBytes(value.operationID)
        _ = try uuidBytes(value.publicationTempID)
    }

    private static func requireRequest(_ value: Request) throws {
        guard value.sequence > 0, value.sequence <= ColdEraseControlBinaryV1.maximumTaskCount,
              value.substepGrammar == (try taskTag(value.kind)) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try requireDigest(value.stateBeforeSHA256, nonzero: false)
        try requireDigest(value.sourceSHA256, nonzero: value.sourceDomain != .absent)
        try requireDigest(value.recipeSHA256, nonzero: value.recipeLength != 0)
        try requireChoice(value)
        switch value.kind {
        case .pendingRepair(let source), .hygieneReceipt(let source),
             .hygieneFinalization(let source), .terminalPublication(let source, _),
             .abortedPublication(let source, _), .oldEraseCompletion(let source):
            guard value.sourceDomain == .catalog, value.sourceRangeKey == source + 1 else {
                throw EraseIntentStoreError.invalidAuthority
            }
        case .generatedLeafRemoval(let origin):
            guard origin < value.sequence, value.sourceDomain == .progress,
                  value.sourceRangeKey == origin + 1 else {
                throw EraseIntentStoreError.invalidAuthority
            }
        case .globalErasePreparation, .globalEraseCompletion, .scratchControlMarker,
             .leaseDirectoryRename, .firstLeafRemoval, .firstDirectoryRemoval,
             .scratchRootRemoval, .ingressRootRemoval:
            guard value.sourceDomain == .absent, value.sourceRangeKey == 0,
                  value.sourceSHA256.allSatisfy({ $0 == 0 }) else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        let tag = try taskTag(value.kind)
        if tag <= 9 {
            let cap: UInt64 = tag == 9 ? ColdEraseControlBinaryV1.maximumRecipeBytes : 262_144
            guard value.recipeLength > 0, value.recipeLength <= cap,
                  value.generatedRangeKey == value.sequence else {
                throw EraseIntentStoreError.invalidAuthority
            }
        } else {
            guard value.recipeLength == 0, value.generatedRangeKey == 0,
                  value.recipeSHA256.allSatisfy({ $0 == 0 }) else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        let facts = try checkedFacts(value.facts)
        guard facts.count >= 2, value.sourceSelector == facts[0].selector,
              value.targetSelector == facts[1].selector else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try requireFactTable(kind: value.kind, sequence: value.sequence,
            facts: facts, postimage: false)
    }

    /// Closed ordered facts; actual first parent/path, source role and all
    /// unchanged/current-prefix associations remain the genuine owner's job.
    private static func requireFactTable(kind: ColdEraseScratchTaskKindV1,
        sequence: UInt64, facts: [ColdEraseScratchTaskProgressFactV1],
        postimage: Bool) throws {
        func word(_ selector: ColdEraseScratchTaskFactSelectorV1) throws -> UInt64 {
            try selector.encodedWord()
        }
        func directory(_ index: Int) -> Bool {
            guard facts.indices.contains(index), let fact = facts[index].fact else { return false }
            return fact.mode & UInt64(S_IFMT) == UInt64(S_IFDIR)
        }
        func regular(_ index: Int) -> Bool {
            guard facts.indices.contains(index), let fact = facts[index].fact else { return false }
            return fact.mode & UInt64(S_IFMT) == UInt64(S_IFREG)
        }
        let expectedSelectors: [UInt64]
        let expectedPresence: [Bool]
        switch kind {
        case .pendingRepair, .hygieneReceipt, .terminalPublication,
             .abortedPublication, .oldEraseCompletion, .globalErasePreparation,
             .globalEraseCompletion, .scratchControlMarker:
            expectedSelectors = try [word(.taskTemporary(sequence)), word(.taskResult(sequence)), word(.ingressRoot)]
            expectedPresence = postimage ? [false, true, true] : [false, false, true]
            guard directory(2), !postimage || regular(1) else { throw EraseIntentStoreError.invalidAuthority }
        case .hygieneFinalization:
            expectedSelectors = try [word(.taskTemporary(sequence)), word(.taskResult(sequence)),
                word(.ingressRoot), word(.hygieneIntermediate(sequence))]
            expectedPresence = [false, true, true, false]
            guard directory(2), regular(1) else { throw EraseIntentStoreError.invalidAuthority }
        case .leaseDirectoryRename(let ordinal):
            expectedSelectors = try [word(.firstPhysicalNode(ordinal)), word(.firstPhysicalNode(ordinal)), word(.scratchRoot)]
            expectedPresence = postimage ? [false, true, true] : [true, false, true]
            guard directory(postimage ? 1 : 0), directory(2) else { throw EraseIntentStoreError.invalidAuthority }
        case .firstLeafRemoval(let ordinal), .firstDirectoryRemoval(let ordinal):
            guard facts.count == 2 else { throw EraseIntentStoreError.invalidAuthority }
            let parent = try ColdEraseScratchTaskFactSelectorV1(encodedWord: facts[1].selector)
            switch parent {
            case .scratchRoot, .ingressRoot: break
            case .firstPhysicalNode(let parentOrdinal):
                guard parentOrdinal != ordinal else { throw EraseIntentStoreError.invalidAuthority }
            default: throw EraseIntentStoreError.invalidAuthority
            }
            expectedSelectors = try [word(.firstPhysicalNode(ordinal)), facts[1].selector]
            expectedPresence = [!postimage, true]
            guard directory(1) else { throw EraseIntentStoreError.invalidAuthority }
            if !postimage {
                if case .firstDirectoryRemoval = kind {
                    guard directory(0) else { throw EraseIntentStoreError.invalidAuthority }
                } else {
                    guard regular(0) else { throw EraseIntentStoreError.invalidAuthority }
                }
            }
        case .generatedLeafRemoval(let origin):
            expectedSelectors = try [word(.taskResult(origin)), word(.ingressRoot)]
            expectedPresence = [!postimage, true]
            guard directory(1), postimage || regular(0) else { throw EraseIntentStoreError.invalidAuthority }
        case .scratchRootRemoval, .ingressRootRemoval:
            expectedSelectors = try [word(kind == .scratchRootRemoval ? .scratchRoot : .ingressRoot), word(.operationsParent)]
            expectedPresence = [!postimage, true]
            guard directory(1), postimage || directory(0) else { throw EraseIntentStoreError.invalidAuthority }
        }
        guard facts.count == expectedSelectors.count,
              facts.map(\.selector) == expectedSelectors,
              facts.map(\.isPresent) == expectedPresence else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    static func requestPayload(_ value: Request) throws -> Data {
        try requireRequest(value)
        var data = try ColdEraseControlBinaryV1.taskKey(value.kind)
        appendWord(value.sourceRangeKey, to: &data)
        data.append(value.sourceSHA256); data.append(value.stateBeforeSHA256)
        for word in [value.sourceSelector, value.targetSelector, value.choiceWord] { appendWord(word, to: &data) }
        data.append(try uuidBytes(value.operationID)); data.append(try uuidBytes(value.publicationTempID))
        appendWord(value.selectedDateBits, to: &data); appendWord(value.recipeLength, to: &data)
        data.append(value.recipeSHA256)
        for word in [value.generatedRangeKey, value.substepGrammar, value.facts.count, value.sourceDomain.rawValue] {
            appendWord(word, to: &data)
        }
        data.append(Data(repeating: 0, count: 32))
        guard data.count == fixedBytes else { throw EraseIntentStoreError.invalidAuthority }
        data.append(try value.facts.encodedFacts())
        guard data.count == payloadBytes else { throw EraseIntentStoreError.invalidAuthority }
        return data
    }

    static func decodeRequestPayload(_ data: Data,
        header: ColdEraseControlBinaryV1.FrameHeader) throws -> Request {
        guard data.count == payloadBytes else { throw EraseIntentStoreError.invalidAuthority }
        var cursor = Cursor(data: data)
        let kind = try ColdEraseControlBinaryV1.decodeTaskKey(cursor.bytes(48))
        let sourceKey = try cursor.word(), sourceSHA = try cursor.bytes(32), beforeSHA = try cursor.bytes(32)
        let sourceSelector = try cursor.word(), targetSelector = try cursor.word(), choice = try cursor.word()
        let operation = try uuid(cursor.bytes(16)), temporary = try uuid(cursor.bytes(16))
        let dateBits = try cursor.word(), recipeLength = try cursor.word(), recipeSHA = try cursor.bytes(32)
        let generatedKey = try cursor.word(), grammar = try cursor.word(), count = try cursor.word()
        guard let domain = SourceDomain(rawValue: try cursor.word()),
              try cursor.bytes(32) == Data(repeating: 0, count: 32) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let facts = try decodeFacts(cursor.bytes(576), count: count).0
        let value = Request(kind: kind, sequence: header.sequence, sourceDomain: domain,
            sourceRangeKey: sourceKey, sourceSHA256: sourceSHA, stateBeforeSHA256: beforeSHA,
            sourceSelector: sourceSelector, targetSelector: targetSelector, choiceWord: choice,
            operationID: operation, publicationTempID: temporary, selectedDateBits: dateBits,
            recipeLength: recipeLength, recipeSHA256: recipeSHA, generatedRangeKey: generatedKey,
            substepGrammar: grammar, facts: facts)
        try requireHeader(header, kind: .request, sequence: value.sequence, task: kind,
            factCount: count, recipeBytes: recipeLength)
        guard cursor.offset == payloadBytes, try requestPayload(value) == data else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return value
    }

    private static func requireObservation(_ value: Observation, request: Request,
        requestSHA256: Data) throws {
        try requireRequest(request)
        try requireDigest(requestSHA256, nonzero: false)
        try requireDigest(value.requestSHA256, nonzero: false)
        try requireDigest(value.stateAfterSHA256, nonzero: false)
        guard value.kind == request.kind, value.sequence == request.sequence,
              value.requestSHA256 == requestSHA256, value.flags == 0,
              value.generatedRangeKey == request.generatedRangeKey else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let facts = try checkedFacts(value.facts), before = try checkedFacts(request.facts)
        guard facts.count == before.count,
              facts.map(\.selector) == before.map(\.selector) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try requireFactTable(kind: value.kind, sequence: value.sequence, facts: facts, postimage: true)
    }

    private static func observationBytes(_ value: Observation, zeroStateAfter: Bool) throws -> Data {
        var data = try ColdEraseControlBinaryV1.taskKey(value.kind)
        data.append(value.requestSHA256)
        data.append(zeroStateAfter ? Data(repeating: 0, count: 32) : value.stateAfterSHA256)
        for word in [value.generatedRangeKey, value.flags, value.facts.count] { appendWord(word, to: &data) }
        data.append(Data(repeating: 0, count: 152))
        guard data.count == fixedBytes else { throw EraseIntentStoreError.invalidAuthority }
        data.append(try value.facts.encodedFacts())
        guard data.count == payloadBytes else { throw EraseIntentStoreError.invalidAuthority }
        return data
    }

    /// Acyclic DATA calculation: P contains a zero D-after. The caller must
    /// independently bind Rq to the complete actual REQUEST frame+raw recipe.
    static func stateAfterSHA256(request: Request, requestSHA256: Data,
        facts: ColdEraseScratchTaskPhysicalPayloadV1) throws -> Data {
        let value = Observation(kind: request.kind, sequence: request.sequence,
            requestSHA256: requestSHA256, stateAfterSHA256: Data(repeating: 0, count: 32),
            generatedRangeKey: request.generatedRangeKey, flags: 0, facts: facts)
        try requireObservation(value, request: request, requestSHA256: requestSHA256)
        var hash = SHA256()
        hash.update(data: postDomain)
        hash.update(data: request.stateBeforeSHA256)
        hash.update(data: requestSHA256)
        hash.update(data: try observationBytes(value, zeroStateAfter: true))
        return Data(hash.finalize())
    }

    static func observationPayload(_ value: Observation, request: Request,
        requestSHA256: Data) throws -> Data {
        try requireObservation(value, request: request, requestSHA256: requestSHA256)
        guard value.stateAfterSHA256 == (try stateAfterSHA256(request: request,
                requestSHA256: requestSHA256, facts: value.facts)) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return try observationBytes(value, zeroStateAfter: false)
    }

    static func decodeObservationPayload(_ data: Data,
        header: ColdEraseControlBinaryV1.FrameHeader, request: Request,
        requestSHA256: Data) throws -> Observation {
        guard data.count == payloadBytes else { throw EraseIntentStoreError.invalidAuthority }
        var cursor = Cursor(data: data)
        let kind = try ColdEraseControlBinaryV1.decodeTaskKey(cursor.bytes(48))
        let requestSHA = try cursor.bytes(32), afterSHA = try cursor.bytes(32)
        let generatedKey = try cursor.word(), flags = try cursor.word(), count = try cursor.word()
        guard try cursor.bytes(152) == Data(repeating: 0, count: 152) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let facts = try decodeFacts(cursor.bytes(576), count: count).0
        let value = Observation(kind: kind, sequence: header.sequence,
            requestSHA256: requestSHA, stateAfterSHA256: afterSHA,
            generatedRangeKey: generatedKey, flags: flags, facts: facts)
        try requireHeader(header, kind: .observation, sequence: request.sequence,
            task: request.kind, factCount: count, recipeBytes: 0, previousSHA256: requestSHA256)
        guard cursor.offset == payloadBytes,
              try observationPayload(value, request: request, requestSHA256: requestSHA256) == data else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return value
    }
}
// END PRIVATE INSERTABLE COLD SCRATCH PROGRESS PAYLOAD CODEC V1


struct ColdEraseScratchPayloadRangeV1: Equatable {
    let ownerIdentity: ObjectIdentifier
    let rangeID: UInt64
    let sourceOrdinal: UInt64
    let roleOrdinal: UInt64
    let byteCount: UInt64
    let sha256: String
    let originalPath: String
    let firstFullFact: String
    let isDirectory: Bool
    fileprivate let offset: UInt64
    fileprivate let storage: Storage
    fileprivate let physicalOrdinal: UInt64?
    private let requestSequence: UInt64?
    var progressSequence: UInt64? { storage == .progress ? requestSequence : nil }
    fileprivate enum Storage: Equatable { case catalog, progress }

    fileprivate init(owner: ColdEraseScratchPayloadRangesV1,
        rangeID: UInt64, sourceOrdinal: UInt64, roleOrdinal: UInt64,
        byteCount: UInt64, sha256: String, originalPath: String,
        firstFullFact: String, isDirectory: Bool, offset: UInt64,
        storage: Storage, physicalOrdinal: UInt64? = nil, requestSequence: UInt64? = nil) {
        ownerIdentity = ObjectIdentifier(owner)
        self.rangeID = rangeID; self.sourceOrdinal = sourceOrdinal
        self.roleOrdinal = roleOrdinal; self.byteCount = byteCount
        self.sha256 = sha256; self.originalPath = originalPath
        self.firstFullFact = firstFullFact; self.isDirectory = isDirectory
        self.offset = offset; self.storage = storage
        self.physicalOrdinal = physicalOrdinal
        self.requestSequence = requestSequence
    }
}

/// Primitive catalog index. It retains no Foundation payload/path/fact
/// container per source. Only one selected path/full-fact string is decoded
/// for the actual charged semantic caller; raw source bytes remain on disk.
fileprivate struct ColdEraseCatalogSourceIndexV1 {
    struct Fact {
        let device: UInt64, inode: UInt64, mode: UInt64, user: UInt64, group: UInt64
        let links: UInt64, size: UInt64
        let modifiedSeconds: UInt64, modifiedNanoseconds: UInt64
        let changedSeconds: UInt64, changedNanoseconds: UInt64
        init(_ words: [UInt64]) throws {
            guard words.count == 11 else { throw EraseIntentStoreError.invalidAuthority }
            device = words[0]; inode = words[1]; mode = words[2]
            user = words[3]; group = words[4]; links = words[5]; size = words[6]
            modifiedSeconds = words[7]; modifiedNanoseconds = words[8]
            changedSeconds = words[9]; changedNanoseconds = words[10]
            guard mode <= UInt64(mode_t.max), user <= UInt64(uid_t.max),
                  group <= UInt64(gid_t.max), Int64(bitPattern: size) >= 0,
                  (0..<1_000_000_000).contains(Int64(bitPattern: modifiedNanoseconds)),
                  (0..<1_000_000_000).contains(Int64(bitPattern: changedNanoseconds)) else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        var rendered: String {
            "\(Int64(bitPattern: device))|\(inode)|\(mode)|\(user)|\(group)|\(links)|\(Int64(bitPattern: size))|\(Int64(bitPattern: modifiedSeconds))|\(Int64(bitPattern: modifiedNanoseconds))|\(Int64(bitPattern: changedSeconds))|\(Int64(bitPattern: changedNanoseconds))"
        }
        var words: [UInt64] {
            [device, inode, mode, user, group, links, size,
                modifiedSeconds, modifiedNanoseconds, changedSeconds, changedNanoseconds]
        }
    }
    struct Digest {
        let first: UInt64, second: UInt64, third: UInt64, fourth: UInt64
        init(_ bytes: Data) throws {
            guard bytes.count == 32 else { throw EraseIntentStoreError.invalidAuthority }
            func word(_ start: Int) -> UInt64 {
                (0..<8).reduce(UInt64(0)) {
                    $0 | (UInt64(bytes[bytes.startIndex + start + $1]) << UInt64($1 * 8))
                }
            }
            first = word(0); second = word(8); third = word(16); fourth = word(24)
        }
        func hex() throws -> String {
            var bytes = Data(capacity: 32)
            for word in [first, second, third, fourth] {
                var value = word.littleEndian
                withUnsafeBytes(of: &value) { bytes.append(contentsOf: $0) }
            }
            return try ColdEraseControlBinaryV1.hexSHA256(bytes)
        }
    }
    let physicalOrdinal: UInt64
    // UInt64.max is the internal absent selected-source sentinel. Numeric
    // equality across these two selector domains never proves a task role.
    let sourceOrdinal: UInt64
    let selectedOrdinalBefore: UInt64
    let pathOffset: UInt64
    let pathByteCount: UInt64
    let rawOffset: UInt64
    let rawByteCount: UInt64
    let role: ColdEraseControlBinaryV1.CatalogSourceRole
    let semanticVersion: UInt64
    let policyCode: UInt64
    let fact: Fact
    let digest: Digest
    var isDirectory: Bool { fact.mode & UInt64(S_IFMT) == UInt64(S_IFDIR) }
    var isSelected: Bool { role != .physicalOnly && sourceOrdinal != UInt64.max }
}

/// Comparison DATA issued only from the actual immutable first catalog.
/// The synchronous structural call graph keeps every alias inside the one
/// charged callback window. No node/range/ordinal is an effect capability.
@MainActor struct ColdEraseScratchFirstNodeV1 {
    let ownerIdentity: ObjectIdentifier
    let physicalOrdinal: UInt64
    let path: String
    let fullFact: String
    let contentSHA256: String?
    let policy: TemporalPolicyObservationV1
    let selectedRange: ColdEraseScratchPayloadRangeV1?
    let isDirectory: Bool

    fileprivate init(owner: ColdEraseScratchPayloadRangesV1,
        index: ColdEraseCatalogSourceIndexV1, path: String,
        policy: TemporalPolicyObservationV1,
        selectedRange: ColdEraseScratchPayloadRangeV1?) throws {
        ownerIdentity = ObjectIdentifier(owner)
        physicalOrdinal = index.physicalOrdinal
        self.path = path; fullFact = index.fact.rendered
        contentSHA256 = index.isDirectory ? nil : try index.digest.hex()
        self.policy = policy; self.selectedRange = selectedRange
        isDirectory = index.isDirectory
    }
}


// BIRTH_FIRST_NODE_DATA_INITIALIZER_V3_BEGIN
extension ColdEraseScratchFirstNodeV1 {
    /// BIRTH-only comparison initializer. The true private borrower supplies
    /// its scalar-rendered canonical digest; no existing hex formatter is used.
    fileprivate init(birthOwner: ColdEraseScratchPayloadRangesV1,
        index: ColdEraseCatalogSourceIndexV1, path: String,
        policy: TemporalPolicyObservationV1, canonicalContentSHA256: String?) throws {
        guard index.fact.rendered.utf8.count <= 241 else { throw EraseIntentStoreError.invalidAuthority }
        if index.isDirectory {
            guard canonicalContentSHA256 == nil else { throw EraseIntentStoreError.invalidAuthority }
        } else {
            guard let sha = canonicalContentSHA256,
                  StoreMigrationCanonicalJSONV1.isLowercaseSHA256(sha) else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        ownerIdentity = ObjectIdentifier(birthOwner); physicalOrdinal = index.physicalOrdinal
        self.path = path; fullFact = index.fact.rendered
        contentSHA256 = canonicalContentSHA256; self.policy = policy
        selectedRange = nil; isDirectory = index.isDirectory
    }
}
// BIRTH_FIRST_NODE_DATA_INITIALIZER_V3_END

struct ColdEraseScratchTaskCutV1: Equatable {
    enum Stage: Equatable {
        case preimage
        case temporary(prefixCount: UInt64, policyAccepted: Bool)
        case linked
        case renamed
        case postimage
    }
    let stage: Stage
    fileprivate init(stage: Stage) { self.stage = stage }
}

// BEGIN PRIVATE INSERTABLE SETTLED LINEAGE INDEX MECHANICS V1
// Pure DATA mechanics. No allocation, IO, reservation, replay or authority issuance.
// Owner supplies exclusively borrowed, FULLY INITIALIZED scalar storage, including
// the zero-row tail. initializedCount names only its strict sorted/unique prefix.
// Owner validates that prefix after genuine complete replay/reconstruction and
// before lookup. These helpers cannot prove memory ownership or durable settlement.

fileprivate struct ColdEraseScratchSettledIndexRowV1 {
    let normalizedKey: UInt64
    let requestFrameOffset: UInt64
    let observationFrameOffset: UInt64
}

fileprivate struct ColdEraseScratchGeneratedIndexRowV1 {
    let sequence: UInt64
    let requestFrameOffset: UInt64
}

fileprivate enum ColdEraseScratchLineageIndexMechanicsV1 {
    private static let maximumSettledCapacity = 600_008
    private static let maximumGeneratedCapacity = 200_003

    static func normalizedFamilyKey(for kind: ColdEraseScratchTaskKindV1) throws -> UInt64 {
        let tag: UInt64
        let ordinal: UInt64
        switch kind {
        case .pendingRepair(let source): tag = 1; ordinal = source
        case .hygieneReceipt(let source): tag = 2; ordinal = source
        case .hygieneFinalization(let source): tag = 3; ordinal = source
        case .terminalPublication(let source, let role),
             .abortedPublication(let source, let role):
            try requireEraseRole(role)
            tag = 4; ordinal = source
        case .oldEraseCompletion(let source): tag = 6; ordinal = source
        case .globalErasePreparation: tag = 7; ordinal = 0
        case .globalEraseCompletion: tag = 8; ordinal = 0
        case .scratchControlMarker: tag = 9; ordinal = 0
        case .leaseDirectoryRename(let source): tag = 10; ordinal = source
        case .firstLeafRemoval(let source): tag = 11; ordinal = source
        case .generatedLeafRemoval(let request): tag = 12; ordinal = request
        case .firstDirectoryRemoval(let source): tag = 13; ordinal = source
        case .scratchRootRemoval: tag = 14; ordinal = 0
        case .ingressRootRemoval: tag = 15; ordinal = 0
        }
        let shifted = ordinal.multipliedReportingOverflow(by: 16)
        let packed = shifted.partialValue.addingReportingOverflow(tag)
        guard !shifted.overflow, !packed.overflow,
              packed.partialValue >> 4 == ordinal,
              packed.partialValue & 15 == tag else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try requireNormalizedKey(packed.partialValue)
        return packed.partialValue
    }

    static func validateSettledPrefix(
        in storage: UnsafeBufferPointer<ColdEraseScratchSettledIndexRowV1>,
        initializedCount: Int
    ) throws {
        try requireSettledStorage(storage, initializedCount: initializedCount)
        var position = 0
        var previousKey: UInt64 = 0
        while position < initializedCount {
            let row = storage[position]
            try requireSettledRow(row)
            guard position == 0 || previousKey < row.normalizedKey else {
                throw EraseIntentStoreError.invalidAuthority
            }
            previousKey = row.normalizedKey
            position += 1
        }
    }

    static func validateGeneratedPrefix(
        in storage: UnsafeBufferPointer<ColdEraseScratchGeneratedIndexRowV1>,
        initializedCount: Int
    ) throws {
        try requireGeneratedStorage(storage, initializedCount: initializedCount)
        var position = 0
        var previousSequence: UInt64 = 0
        while position < initializedCount {
            let row = storage[position]
            try requireGeneratedRow(row)
            guard position == 0 || previousSequence < row.sequence else {
                throw EraseIntentStoreError.invalidAuthority
            }
            previousSequence = row.sequence
            position += 1
        }
    }

    static func findSettled(key: UInt64,
        in storage: UnsafeBufferPointer<ColdEraseScratchSettledIndexRowV1>,
        initializedCount: Int
    ) throws -> ColdEraseScratchSettledIndexRowV1? {
        try requireSettledStorage(storage, initializedCount: initializedCount)
        try requireNormalizedKey(key)
        let position = try settledLowerBound(key: key, in: storage, count: initializedCount)
        try requireSettledBoundary(key: key, position: position,
            in: storage, count: initializedCount)
        guard position < initializedCount else { return nil }
        let row = storage[position]
        return row.normalizedKey == key ? row : nil
    }

    static func insertSettled(_ row: ColdEraseScratchSettledIndexRowV1,
        into storage: UnsafeMutableBufferPointer<ColdEraseScratchSettledIndexRowV1>,
        initializedCount: inout Int
    ) throws {
        let borrowed = UnsafeBufferPointer(storage)
        let count = initializedCount
        try requireSettledStorage(borrowed, initializedCount: count)
        try requireSettledRow(row)
        let nextCount = count.addingReportingOverflow(1)
        guard !nextCount.overflow, nextCount.partialValue <= storage.count else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let position = try settledLowerBound(key: row.normalizedKey, in: borrowed, count: count)
        try requireSettledBoundary(key: row.normalizedKey, position: position,
            in: borrowed, count: count)
        guard position == count || borrowed[position].normalizedKey != row.normalizedKey else {
            throw EraseIntentStoreError.invalidAuthority
        }
        // Every explicit throwing refusal is above the first assignment. Full storage is
        // already initialized; no initialize/deinitialize/allocation occurs.
        var cursor = count
        while cursor > position {
            storage[cursor] = storage[cursor - 1]
            cursor -= 1
        }
        storage[position] = row
        initializedCount = nextCount.partialValue
    }

    static func findGenerated(sequence: UInt64,
        in storage: UnsafeBufferPointer<ColdEraseScratchGeneratedIndexRowV1>,
        initializedCount: Int
    ) throws -> ColdEraseScratchGeneratedIndexRowV1? {
        try requireGeneratedStorage(storage, initializedCount: initializedCount)
        try requireGeneratedSequence(sequence)
        let position = try generatedLowerBound(sequence: sequence, in: storage, count: initializedCount)
        try requireGeneratedBoundary(sequence: sequence, position: position,
            in: storage, count: initializedCount)
        guard position < initializedCount else { return nil }
        let row = storage[position]
        return row.sequence == sequence ? row : nil
    }

    static func insertGenerated(_ row: ColdEraseScratchGeneratedIndexRowV1,
        into storage: UnsafeMutableBufferPointer<ColdEraseScratchGeneratedIndexRowV1>,
        initializedCount: inout Int
    ) throws {
        let borrowed = UnsafeBufferPointer(storage)
        let count = initializedCount
        try requireGeneratedStorage(borrowed, initializedCount: count)
        try requireGeneratedRow(row)
        let nextCount = count.addingReportingOverflow(1)
        guard !nextCount.overflow, nextCount.partialValue <= storage.count else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let position = try generatedLowerBound(sequence: row.sequence, in: borrowed, count: count)
        try requireGeneratedBoundary(sequence: row.sequence, position: position,
            in: borrowed, count: count)
        guard position == count || borrowed[position].sequence != row.sequence else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var cursor = count
        while cursor > position {
            storage[cursor] = storage[cursor - 1]
            cursor -= 1
        }
        storage[position] = row
        initializedCount = nextCount.partialValue
    }

    private static func requireEraseRole(_ role: ColdEraseScratchEraseRoleV1) throws {
        switch role {
        case .firstPrepare(let ordinal), .firstHygiene(let ordinal):
            guard ordinal < ColdEraseControlBinaryV1.maximumCatalogSources else {
                throw EraseIntentStoreError.invalidAuthority
            }
        case .global: break
        }
    }

    private static func requireNormalizedKey(_ key: UInt64) throws {
        let tag = key & 15
        let ordinal = key >> 4
        switch tag {
        case 1, 2, 3, 4, 6, 10, 11, 13:
            guard ordinal < ColdEraseControlBinaryV1.maximumCatalogSources else {
                throw EraseIntentStoreError.invalidAuthority
            }
        case 7, 8, 9, 14, 15:
            guard ordinal == 0 else { throw EraseIntentStoreError.invalidAuthority }
        case 12:
            try requireGeneratedSequence(ordinal)
        default:
            throw EraseIntentStoreError.invalidAuthority
        }
        let shifted = ordinal.multipliedReportingOverflow(by: 16)
        let packed = shifted.partialValue.addingReportingOverflow(tag)
        guard !shifted.overflow, !packed.overflow, packed.partialValue == key else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    private static func requireGeneratedSequence(_ sequence: UInt64) throws {
        guard sequence > 0, sequence <= ColdEraseControlBinaryV1.maximumTaskCount else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    private static func requireFrameOffset(_ offset: UInt64) throws {
        // 128-byte header plus 32-byte trailer is the existing minimum frame.
        guard offset >= 64,
              offset <= ColdEraseControlBinaryV1.maximumProgressBytes - 160 else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    private static func requireSettledRow(_ row: ColdEraseScratchSettledIndexRowV1) throws {
        try requireNormalizedKey(row.normalizedKey)
        try requireFrameOffset(row.requestFrameOffset)
        try requireFrameOffset(row.observationFrameOffset)
        guard row.observationFrameOffset > row.requestFrameOffset else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    private static func requireGeneratedRow(_ row: ColdEraseScratchGeneratedIndexRowV1) throws {
        try requireGeneratedSequence(row.sequence)
        try requireFrameOffset(row.requestFrameOffset)
    }

    private static func requireSettledStorage(
        _ storage: UnsafeBufferPointer<ColdEraseScratchSettledIndexRowV1>,
        initializedCount: Int
    ) throws {
        guard MemoryLayout<ColdEraseScratchSettledIndexRowV1>.size == 24,
              MemoryLayout<ColdEraseScratchSettledIndexRowV1>.stride == 24,
              storage.count <= maximumSettledCapacity,
              initializedCount >= 0, initializedCount <= storage.count,
              storage.count == 0 || storage.baseAddress != nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    private static func requireGeneratedStorage(
        _ storage: UnsafeBufferPointer<ColdEraseScratchGeneratedIndexRowV1>,
        initializedCount: Int
    ) throws {
        guard MemoryLayout<ColdEraseScratchGeneratedIndexRowV1>.size == 16,
              MemoryLayout<ColdEraseScratchGeneratedIndexRowV1>.stride == 16,
              storage.count <= maximumGeneratedCapacity,
              initializedCount >= 0, initializedCount <= storage.count,
              storage.count == 0 || storage.baseAddress != nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    private static func settledLowerBound(key: UInt64,
        in storage: UnsafeBufferPointer<ColdEraseScratchSettledIndexRowV1>, count: Int
    ) throws -> Int {
        var lower = 0
        var upper = count
        while lower < upper {
            let middle = lower + (upper - lower) / 2
            let row = storage[middle]
            try requireSettledRow(row)
            if row.normalizedKey < key { lower = middle + 1 } else { upper = middle }
        }
        return lower
    }

    private static func generatedLowerBound(sequence: UInt64,
        in storage: UnsafeBufferPointer<ColdEraseScratchGeneratedIndexRowV1>, count: Int
    ) throws -> Int {
        var lower = 0
        var upper = count
        while lower < upper {
            let middle = lower + (upper - lower) / 2
            let row = storage[middle]
            try requireGeneratedRow(row)
            if row.sequence < sequence { lower = middle + 1 } else { upper = middle }
        }
        return lower
    }

    private static func requireSettledBoundary(key: UInt64, position: Int,
        in storage: UnsafeBufferPointer<ColdEraseScratchSettledIndexRowV1>, count: Int
    ) throws {
        guard position >= 0, position <= count else { throw EraseIntentStoreError.invalidAuthority }
        if position > 0 {
            let previous = storage[position - 1]
            try requireSettledRow(previous)
            guard previous.normalizedKey < key else { throw EraseIntentStoreError.invalidAuthority }
        }
        if position < count {
            let next = storage[position]
            try requireSettledRow(next)
            guard next.normalizedKey >= key else { throw EraseIntentStoreError.invalidAuthority }
            if next.normalizedKey == key && position + 1 < count {
                let following = storage[position + 1]
                try requireSettledRow(following)
                guard following.normalizedKey > key else { throw EraseIntentStoreError.invalidAuthority }
            }
        }
    }

    private static func requireGeneratedBoundary(sequence: UInt64, position: Int,
        in storage: UnsafeBufferPointer<ColdEraseScratchGeneratedIndexRowV1>, count: Int
    ) throws {
        guard position >= 0, position <= count else { throw EraseIntentStoreError.invalidAuthority }
        if position > 0 {
            let previous = storage[position - 1]
            try requireGeneratedRow(previous)
            guard previous.sequence < sequence else { throw EraseIntentStoreError.invalidAuthority }
        }
        if position < count {
            let next = storage[position]
            try requireGeneratedRow(next)
            guard next.sequence >= sequence else { throw EraseIntentStoreError.invalidAuthority }
            if next.sequence == sequence && position + 1 < count {
                let following = storage[position + 1]
                try requireGeneratedRow(following)
                guard following.sequence > sequence else { throw EraseIntentStoreError.invalidAuthority }
            }
        }
    }
}
// END PRIVATE INSERTABLE SETTLED LINEAGE INDEX MECHANICS V1

// BEGIN PRIVATE ADDITIVE APPEND AND HEAPSORT MECHANICS V2
// V1 is an exact prefix. Unsorted replay DATA must never be searched before
// genuine complete replay and the owner's explicit strict-prefix validation.
fileprivate extension ColdEraseScratchLineageIndexMechanicsV1 {
    static func appendSettled(_ row: ColdEraseScratchSettledIndexRowV1,
        into storage: UnsafeMutableBufferPointer<ColdEraseScratchSettledIndexRowV1>,
        initializedCount: inout Int
    ) throws {
        let count = initializedCount
        try requireSettledStorage(UnsafeBufferPointer(storage), initializedCount: count)
        try requireSettledRow(row)
        let nextCount = count.addingReportingOverflow(1)
        guard !nextCount.overflow, nextCount.partialValue <= storage.count else {
            throw EraseIntentStoreError.invalidAuthority
        }
        // Duplicates are not hidden or replaced. After authentic stream append,
        // the owner sorts and invokes validateSettledPrefix before any lookup.
        storage[count] = row
        initializedCount = nextCount.partialValue
    }

    static func sortSettled(
        in storage: UnsafeMutableBufferPointer<ColdEraseScratchSettledIndexRowV1>,
        initializedCount: Int
    ) throws {
        let borrowed = UnsafeBufferPointer(storage)
        try requireSettledStorage(borrowed, initializedCount: initializedCount)
        // Ensures every later two-times-parent +1 calculation fits Int, even
        // independently of the unchanged maximum600008-capacity guard.
        guard initializedCount <= (Int.max - 1) / 2 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var checked = 0
        while checked < initializedCount {
            try requireSettledRow(borrowed[checked])
            checked += 1
        }
        // All explicit throwing validation is before the first assignment.
        // Sorted uniqueness is checked separately by the existing validator;
        // a duplicate retains the reordered backing and cannot authorize use.
        guard initializedCount > 1 else { return }
        var parent = initializedCount / 2
        while parent > 0 {
            parent -= 1
            let value = storage[parent]
            siftSettledValue(value, into: storage, from: parent, count: initializedCount)
        }
        var remaining = initializedCount
        while remaining > 1 {
            remaining -= 1
            let value = storage[remaining]
            storage[remaining] = storage[0]
            siftSettledValue(value, into: storage, from: 0, count: remaining)
        }
    }

    static func appendGenerated(_ row: ColdEraseScratchGeneratedIndexRowV1,
        into storage: UnsafeMutableBufferPointer<ColdEraseScratchGeneratedIndexRowV1>,
        initializedCount: inout Int
    ) throws {
        let count = initializedCount
        let borrowed = UnsafeBufferPointer(storage)
        try requireGeneratedStorage(borrowed, initializedCount: count)
        try requireGeneratedRow(row)
        let nextCount = count.addingReportingOverflow(1)
        guard !nextCount.overflow, nextCount.partialValue <= storage.count else {
            throw EraseIntentStoreError.invalidAuthority
        }
        if count > 0 {
            let previous = borrowed[count - 1]
            try requireGeneratedRow(previous)
            guard previous.sequence < row.sequence else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        // Real REQUEST sequence order permits O(1) append, even with gaps.
        // Entry count is bounded by J; sequence values remain bounded by T.
        storage[count] = row
        initializedCount = nextCount.partialValue
    }

    private static func siftSettledValue(_ value: ColdEraseScratchSettledIndexRowV1,
        into storage: UnsafeMutableBufferPointer<ColdEraseScratchSettledIndexRowV1>,
        from start: Int, count: Int
    ) {
        // Only sortSettled calls this nonthrowing helper after whole-prefix
        // validation. start<count<=initializedCount<=600008; all memory is
        // fully initialized and exclusively borrowed throughout the call.
        var position = start
        while position < count / 2 {
            let left = position * 2 + 1
            let right = left + 1
            var child = left
            if right < count && storage[left].normalizedKey < storage[right].normalizedKey {
                child = right
            }
            if value.normalizedKey >= storage[child].normalizedKey { break }
            storage[position] = storage[child]
            position = child // strictly increases; bounded binary-tree depth
        }
        storage[position] = value
    }
}
// END PRIVATE ADDITIVE APPEND AND HEAPSORT MECHANICS V2


// BEGIN PRIVATE INCREMENTAL SCRATCH PROGRESS COMPARISON PARSER V1
// Pure byte/chain/state comparison. Caller allocation, initialized/exclusive
// buffers, real first operands/current namespace and all authority remain DUE.
fileprivate enum ColdEraseScratchProgressHeaderFormatV1 { case v1, v2, v3, v4 }

fileprivate struct ColdEraseScratchProgressParserDigestV1: Equatable {
    let first: UInt64
    let second: UInt64
    let third: UInt64
    let fourth: UInt64

    fileprivate init(bytes: UnsafeRawBufferPointer) throws {
        guard bytes.count == 32, bytes.baseAddress != nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        func word(_ start: Int) -> UInt64 {
            var value: UInt64 = 0
            for offset in 0..<8 { value |= UInt64(bytes[start + offset]) << UInt64(offset * 8) }
            return value
        }
        first = word(0); second = word(8); third = word(16); fourth = word(24)
    }

    fileprivate init(data: Data) throws {
        self = try data.withUnsafeBytes { try Self(bytes: $0) }
    }

    fileprivate func codecData() -> Data {
        var result = Data(capacity: 32)
        func append(_ word: UInt64) {
            var value = word.littleEndian
            withUnsafeBytes(of: &value) { result.append(contentsOf: $0) }
        }
        append(first); append(second); append(third); append(fourth)
        return result // fixed32 logical bytes; allocator/COW/VM not measured
    }
}

fileprivate struct ColdEraseScratchProgressParserInputV1 {
    let format: ColdEraseScratchProgressHeaderFormatV1
    let expectedCoreSHA256: ColdEraseScratchProgressParserDigestV1
    let expectedProgressSHA256: ColdEraseScratchProgressParserDigestV1
    let initialPreviousFrameSHA256: ColdEraseScratchProgressParserDigestV1
    let initialStateSHA256: ColdEraseScratchProgressParserDigestV1
    let progressByteCount: UInt64
    let totalTaskSequenceCeiling: UInt64
    let scratchTaskCeiling: UInt64
    let generatedRecipeCeiling: UInt64
    let physicalCatalogCount: UInt64
    let selectedSourceCount: UInt64
}

fileprivate struct ColdEraseScratchProgressParserPendingV1 {
    let normalizedKey: UInt64
    let sequence: UInt64
    let requestFrameOffset: UInt64
    let requestByteCount: UInt64
    let recipeOffset: UInt64
    let recipeByteCount: UInt64
    let requestSHA256: ColdEraseScratchProgressParserDigestV1
    let recipeSHA256: ColdEraseScratchProgressParserDigestV1
    let stateBeforeSHA256: ColdEraseScratchProgressParserDigestV1
}

fileprivate enum ColdEraseScratchProgressParserPartialPhaseV1 {
    case header, payload, recipe, trailer
}

fileprivate struct ColdEraseScratchProgressParserTailV1 {
    let frameStartOffset: UInt64
    let availableByteCount: UInt64
    let phase: ColdEraseScratchProgressParserPartialPhaseV1
    let knownKind: ColdEraseControlBinaryV1.FrameHeader.Kind?
    let knownSequence: UInt64?
}

fileprivate struct ColdEraseScratchProgressParserCompletionV1 {
    let consumedByteCount: UInt64
    let completePrefixByteCount: UInt64
    let progressSHA256: ColdEraseScratchProgressParserDigestV1
    let completePrefixSHA256: ColdEraseScratchProgressParserDigestV1
    let lastCompleteFrameSHA256: ColdEraseScratchProgressParserDigestV1?
    let settledStateSHA256: ColdEraseScratchProgressParserDigestV1
    let settledCount: Int
    let generatedCount: Int
    let completeRequestCount: UInt64
    let pending: ColdEraseScratchProgressParserPendingV1?
    let tail: ColdEraseScratchProgressParserTailV1?
}

@MainActor fileprivate final class ColdEraseScratchProgressParserV1 {
    private enum Phase: Equatable { case progress, header, payload, recipe, trailer, finished, poisoned }
    private struct BufferLayout: Equatable {
        let scratchStart: UInt
        let scratchEnd: UInt
        let settledStart: UInt
        let settledEnd: UInt
        let settledCount: Int
        let generatedStart: UInt
        let generatedEnd: UInt
        let generatedCount: Int
    }
    private struct Storage {
        let input: ColdEraseScratchProgressParserInputV1
        var phase: Phase = .progress
        var entered = false
        var layout: BufferLayout?
        var consumed: UInt64 = 0
        var progressFilled = 0
        var headerFilled = 0
        var payloadFilled = 0
        var trailerFilled = 0
        var recipeConsumed: UInt64 = 0
        var frameStart: UInt64 = 64
        var wholeHash = SHA256()
        var frameHash = SHA256()
        var recipeHash = SHA256()
        var prefixHash = SHA256()
        var completePrefixByteCount: UInt64 = 0
        var lastCompleteFrameSHA256: ColdEraseScratchProgressParserDigestV1?
        var currentState: ColdEraseScratchProgressParserDigestV1
        var header: ColdEraseControlBinaryV1.FrameHeader?
        var request: ColdEraseScratchProgressPayloadCodecV1.Request?
        var observation: ColdEraseScratchProgressPayloadCodecV1.Observation?
        var pendingRequest: ColdEraseScratchProgressPayloadCodecV1.Request?
        var pending: ColdEraseScratchProgressParserPendingV1?
        var settledCount = 0
        var generatedCount = 0
        var completeRequestCount: UInt64 = 0
        var completion: ColdEraseScratchProgressParserCompletionV1?
    }
    private var storage: Storage
    fileprivate static var fixedScratchByteCount: Int { 2112 }

    fileprivate static func declaredStoredBackingBytes() throws -> UInt64 {
        // Actual Storage plus named simultaneous lexical value cells. Caller
        // raw/index buffers and decoder heap/codec/crypto transients are separate
        // SOURCE_DUE operands, never a successful whole-footprint reservation.
        try ColdEraseControlBinaryV1.adding(
            UInt64(MemoryLayout<Storage>.stride),
            UInt64(MemoryLayout<ColdEraseScratchProgressParserInputV1>.stride),
            UInt64(MemoryLayout<ColdEraseScratchProgressParserCompletionV1>.stride),
            UInt64(MemoryLayout<ColdEraseScratchProgressParserPendingV1>.stride),
            UInt64(MemoryLayout<ColdEraseScratchProgressParserTailV1>.stride),
            UInt64(MemoryLayout<ColdEraseControlBinaryV1.FrameHeader>.stride),
            UInt64(MemoryLayout<ColdEraseScratchProgressPayloadCodecV1.Request>.stride),
            UInt64(MemoryLayout<ColdEraseScratchProgressPayloadCodecV1.Observation>.stride),
            UInt64(MemoryLayout<ColdEraseScratchTaskPhysicalPayloadV1>.stride),
            UInt64(MemoryLayout<BufferLayout>.stride),
            UInt64(4 * MemoryLayout<ColdEraseScratchProgressParserDigestV1>.stride),
            UInt64(3 * MemoryLayout<Data>.stride),
            UInt64(MemoryLayout<ColdEraseScratchSettledIndexRowV1>.stride),
            UInt64(MemoryLayout<ColdEraseScratchGeneratedIndexRowV1>.stride),
            UInt64(MemoryLayout<SHA256>.stride),
            UInt64(MemoryLayout<SHA256.Digest>.stride))
    }

    fileprivate init(input: ColdEraseScratchProgressParserInputV1) throws {
        try Self.validateInput(input)
        storage = Storage(input: input, currentState: input.initialStateSHA256)
    }

    private static func formatLimits(_ format: ColdEraseScratchProgressHeaderFormatV1)
        -> (progress: UInt64, tasks: UInt64) {
        switch format {
        case .v1: return (ColdEraseControlBinaryV1.maximumProgressBytes, ColdEraseControlBinaryV1.maximumTaskCount)
        case .v2: return (ColdErasePostContentBinaryV2.maximumProgressBytes, ColdErasePostContentBinaryV2.maximumTaskCount)
        case .v3: return (ColdErasePostContentBinaryV3.maximumProgressBytes, ColdErasePostContentBinaryV3.maximumTaskCount)
        case .v4: return (ColdErasePostContentBinaryV4.maximumProgressBytes, ColdErasePostContentBinaryV4.maximumTaskCount)
        }
    }

    private static func validateInput(_ input: ColdEraseScratchProgressParserInputV1) throws {
        let limits = formatLimits(input.format)
        guard input.progressByteCount >= 64, input.progressByteCount <= limits.progress,
              input.totalTaskSequenceCeiling <= limits.tasks,
              input.scratchTaskCeiling <= 600_008,
              input.generatedRecipeCeiling <= 200_003,
              input.physicalCatalogCount <= ColdEraseControlBinaryV1.maximumCatalogSources,
              input.selectedSourceCount <= input.physicalCatalogCount,
              MemoryLayout<ColdEraseScratchSettledIndexRowV1>.size == 24,
              MemoryLayout<ColdEraseScratchSettledIndexRowV1>.stride == 24,
              MemoryLayout<ColdEraseScratchGeneratedIndexRowV1>.size == 16,
              MemoryLayout<ColdEraseScratchGeneratedIndexRowV1>.stride == 16 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        _ = try ColdEraseControlBinaryV1.adding(input.progressByteCount)
    }

    private func requireBuffers(scratch: UnsafeMutableRawBufferPointer,
        settled: UnsafeMutableBufferPointer<ColdEraseScratchSettledIndexRowV1>,
        generated: UnsafeMutableBufferPointer<ColdEraseScratchGeneratedIndexRowV1>,
        source: UnsafeRawBufferPointer? = nil) throws {
        guard scratch.count == Self.fixedScratchByteCount, scratch.baseAddress != nil,
              settled.count >= 0, UInt64(settled.count) >= storage.input.scratchTaskCeiling,
              settled.count <= 600_008,
              generated.count >= 0, UInt64(generated.count) >= storage.input.generatedRecipeCeiling,
              generated.count <= 200_003,
              settled.count == 0 || settled.baseAddress != nil,
              generated.count == 0 || generated.baseAddress != nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        func interval(_ base: UnsafeRawPointer?, _ count: Int, _ stride: Int) throws -> (UInt, UInt) {
            guard count >= 0, stride > 0 else { throw EraseIntentStoreError.invalidAuthority }
            let length = count.multipliedReportingOverflow(by: stride)
            guard !length.overflow, count == 0 || base != nil else { throw EraseIntentStoreError.invalidAuthority }
            let start = base.map { UInt(bitPattern: $0) } ?? 0
            let end = start.addingReportingOverflow(UInt(length.partialValue))
            guard !end.overflow else { throw EraseIntentStoreError.invalidAuthority }
            return (start, end.partialValue)
        }
        func disjoint(_ a: (UInt, UInt), _ b: (UInt, UInt)) -> Bool {
            a.0 == a.1 || b.0 == b.1 || a.1 <= b.0 || b.1 <= a.0
        }
        let a = try interval(scratch.baseAddress.map { UnsafeRawPointer($0) }, scratch.count, 1)
        let b = try interval(settled.baseAddress.map { UnsafeRawPointer($0) }, settled.count, 24)
        let c = try interval(generated.baseAddress.map { UnsafeRawPointer($0) }, generated.count, 16)
        guard disjoint(a, b), disjoint(a, c), disjoint(b, c),
              b.0 % UInt(MemoryLayout<ColdEraseScratchSettledIndexRowV1>.alignment) == 0,
              c.0 % UInt(MemoryLayout<ColdEraseScratchGeneratedIndexRowV1>.alignment) == 0 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let layout = BufferLayout(scratchStart: a.0, scratchEnd: a.1,
            settledStart: b.0, settledEnd: b.1, settledCount: settled.count,
            generatedStart: c.0, generatedEnd: c.1, generatedCount: generated.count)
        if let previous = storage.layout {
            guard layout == previous else { throw EraseIntentStoreError.invalidAuthority }
        } else { storage.layout = layout }
        if let source {
            let d = try interval(source.baseAddress, source.count, 1)
            guard disjoint(d, a), disjoint(d, b), disjoint(d, c) else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        // Pointer geometry does not prove initialization, lifetime, exclusive
        // ownership or the real precharge; those caller obligations stay DUE.
    }

    fileprivate func consume(absoluteOffset: UInt64, bytes: UnsafeRawBufferPointer,
        scratch: UnsafeMutableRawBufferPointer,
        settled: UnsafeMutableBufferPointer<ColdEraseScratchSettledIndexRowV1>,
        generated: UnsafeMutableBufferPointer<ColdEraseScratchGeneratedIndexRowV1>) throws {
        guard !storage.entered, storage.phase != .finished, storage.phase != .poisoned else {
            storage.phase = .poisoned; throw EraseIntentStoreError.invalidAuthority
        }
        storage.entered = true
        do {
            guard absoluteOffset == storage.consumed, bytes.count > 0,
                  bytes.count <= ColdEraseControlBinaryV1.readChunkBytes, bytes.baseAddress != nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let end = try ColdEraseControlBinaryV1.adding(absoluteOffset, UInt64(bytes.count))
            guard end <= storage.input.progressByteCount else { throw EraseIntentStoreError.invalidAuthority }
            try requireBuffers(scratch: scratch, settled: settled, generated: generated, source: bytes)
            var position = 0
            while position < bytes.count {
                let remaining: Int
                let destination: Int?
                switch storage.phase {
                case .progress: remaining = 64 - storage.progressFilled; destination = storage.progressFilled
                case .header: remaining = 128 - storage.headerFilled; destination = 64 + storage.headerFilled
                case .payload: remaining = 864 - storage.payloadFilled; destination = 192 + storage.payloadFilled
                case .recipe:
                    guard let header = storage.header, storage.recipeConsumed < header.recipeBytes else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    remaining = Int(min(UInt64(bytes.count - position), header.recipeBytes - storage.recipeConsumed))
                    destination = nil
                case .trailer: remaining = 32 - storage.trailerFilled; destination = 1056 + storage.trailerFilled
                case .finished, .poisoned: throw EraseIntentStoreError.invalidAuthority
                }
                let count = min(remaining, bytes.count - position)
                guard count > 0 else { throw EraseIntentStoreError.invalidAuthority }
                let next = try ColdEraseControlBinaryV1.adding(storage.consumed, UInt64(count))
                guard next <= storage.input.progressByteCount else { throw EraseIntentStoreError.invalidAuthority }
                let piece = UnsafeRawBufferPointer(rebasing: bytes[position..<(position + count)])
                if let destination {
                    guard destination >= 0, count <= scratch.count - destination else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    for offset in 0..<count { scratch[destination + offset] = piece[offset] }
                }
                storage.wholeHash.update(bufferPointer: piece)
                switch storage.phase {
                case .header, .payload, .recipe: storage.frameHash.update(bufferPointer: piece)
                default: break
                }
                if storage.phase == .recipe { storage.recipeHash.update(bufferPointer: piece) }
                storage.consumed = next; position += count
                switch storage.phase {
                case .progress:
                    storage.progressFilled += count
                    if storage.progressFilled == 64 { try completeProgressHeader(scratch) }
                case .header:
                    storage.headerFilled += count
                    if storage.headerFilled == 128 { try completeFrameHeader(scratch) }
                case .payload:
                    storage.payloadFilled += count
                    if storage.payloadFilled == 864 { try completePayload(scratch) }
                case .recipe:
                    storage.recipeConsumed += UInt64(count)
                    guard let recipeHeader = storage.header else { throw EraseIntentStoreError.invalidAuthority }
                    if storage.recipeConsumed == recipeHeader.recipeBytes {
                        guard let request = storage.request,
                              try digest(storage.recipeHash) == ColdEraseScratchProgressParserDigestV1(data: request.recipeSHA256) else {
                            throw EraseIntentStoreError.invalidAuthority
                        }
                        storage.phase = .trailer
                    }
                case .trailer:
                    storage.trailerFilled += count
                    if storage.trailerFilled == 32 {
                        try completeFrame(scratch: scratch, settled: settled, generated: generated)
                    }
                case .finished, .poisoned: throw EraseIntentStoreError.invalidAuthority
                }
            }
            storage.entered = false
        } catch { storage.phase = .poisoned; storage.entered = false; throw error }
    }

    private func data(_ scratch: UnsafeMutableRawBufferPointer, offset: Int, count: Int) -> Data {
        Data(bytes: scratch.baseAddress!.advanced(by: offset), count: count)
    }
    private func digest(_ hash: SHA256) throws -> ColdEraseScratchProgressParserDigestV1 {
        var snapshot = hash
        return try ColdEraseScratchProgressParserDigestV1(data: Data(snapshot.finalize()))
    }
    private func completeProgressHeader(_ scratch: UnsafeMutableRawBufferPointer) throws {
        let header = data(scratch, offset: 0, count: 64)
        let core = storage.input.expectedCoreSHA256.codecData()
        switch storage.input.format {
        case .v1: try ColdEraseControlBinaryV1.decodeProgressHeader(header, expectedCoreSHA256: core)
        case .v2: try ColdErasePostContentBinaryV2.decodeProgressHeader(header, expectedCoreSHA256: core)
        case .v3: try ColdErasePostContentBinaryV3.decodeProgressHeader(header, expectedCoreSHA256: core)
        case .v4: try ColdErasePostContentBinaryV4.decodeProgressHeader(header, expectedCoreSHA256: core)
        }
        storage.completePrefixByteCount = 64; storage.prefixHash = storage.wholeHash
        storage.phase = .header
    }
    private func completeFrameHeader(_ scratch: UnsafeMutableRawBufferPointer) throws {
        let header = try ColdEraseControlBinaryV1.decodeFrameHeader(data(scratch, offset: 64, count: 128))
        storage.header = header // returned model BEFORE additional comparison
        guard header.payloadBytes == 864, header.sequence <= storage.input.totalTaskSequenceCeiling,
