                second: try .init(bytes: UnsafeRawBufferPointer(rebasing: progressHeader[32..<64])))
            try ColdErasePostContentBinaryV4.decodeProgressHeader(Data(progressHeader),
                expectedCoreSHA256: storage.input.coreSHA256.codecData())
            Self.updateDomain(.image, hash: &storage.imageHash)
            Self.updateWord(1, hash: &storage.imageHash); Self.updateWord(4, hash: &storage.imageHash)
            Self.updateWord(storage.input.coreByteCount, hash: &storage.imageHash)
            Self.updateWord(storage.input.catalogByteCount, hash: &storage.imageHash)
            Self.updateWord(storage.input.physicalCount, hash: &storage.imageHash)
            Self.updateWord(storage.input.selectedCount, hash: &storage.imageHash)
            storage.imageHash.update(bufferPointer: coreHeader)
            storage.imageHash.update(bufferPointer: metadata)
            storage.imageHash.update(bufferPointer: catalogHeader)
            storage.imageByteCount = 16_656 // fixed prefix, excluding final M32
            Self.updateDomain(.map, hash: &storage.mapHash)
            Self.updateWord(1, hash: &storage.mapHash)
            Self.updateWord(storage.input.selectedCount, hash: &storage.mapHash)
            storage.mapByteCount = 48
            storage.phase = .rows; storage.entered = false
        } catch { failed(); throw error }
    }

    fileprivate func beginRow(physicalOrdinal: UInt64, sourceOrdinal: UInt64,
        headerOffset: UInt64, header: UnsafeRawBufferPointer) throws {
        try enter(.rows)
        do {
            try Self.requireBytes(header, count: 160)
            guard storage.row == nil, physicalOrdinal == storage.recordedPhysical,
                  physicalOrdinal < storage.input.physicalCount,
                  headerOffset == storage.nextHeaderOffset else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let row = try ColdEraseControlBinaryV1.decodeCatalogSourceHeader(Data(header))
            storage.row = row // actual full11/policy/Data model BEFORE lower proof
            guard let role = ColdEraseControlBinaryV1.CatalogSourceRole(rawValue: row.sourceRole) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            if role == .physicalOnly {
                guard sourceOrdinal == UInt64.max else { throw EraseIntentStoreError.invalidAuthority }
            } else {
                guard sourceOrdinal == storage.recordedSelected,
                      sourceOrdinal < storage.input.selectedCount else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            let path = try ColdEraseControlBinaryV1.adding(headerOffset, 160)
            let raw = try ColdEraseControlBinaryV1.adding(path, row.pathByteCount)
            let end = try ColdEraseControlBinaryV1.adding(raw, row.rawByteCount)
            let catalogEnd = try ColdEraseControlBinaryV1.adding(16_512, storage.input.catalogByteCount)
            let pathTotal = try ColdEraseControlBinaryV1.adding(storage.totalPathBytes, row.pathByteCount)
            guard row.pathByteCount > 0, row.pathByteCount <= 16_640,
                  pathTotal <= 100_663_296, end <= catalogEnd,
                  end <= storage.input.coreByteCount else { throw EraseIntentStoreError.invalidAuthority }
            storage.rowPhysicalOrdinal = physicalOrdinal; storage.rowSourceOrdinal = sourceOrdinal
            storage.rowPathOffset = path; storage.rowRawOffset = raw; storage.pathFilled = 0
            storage.nextHeaderOffset = end
            Self.updateWord(physicalOrdinal, hash: &storage.imageHash)
            Self.updateWord(sourceOrdinal, hash: &storage.imageHash)
            storage.imageHash.update(bufferPointer: header)
            storage.imageByteCount = try ColdEraseControlBinaryV1.adding(storage.imageByteCount, 176)
            storage.phase = .path; storage.entered = false
        } catch { failed(); throw error }
    }

    fileprivate func consumePath(absoluteOffset: UInt64, bytes: UnsafeRawBufferPointer) throws {
        try enter(.path)
        do {
            guard let row = storage.row, bytes.count > 0,
                  bytes.count <= ColdEraseControlBinaryV1.readChunkBytes, bytes.baseAddress != nil,
                  absoluteOffset == (try ColdEraseControlBinaryV1.adding(storage.rowPathOffset, storage.pathFilled)),
                  storage.pathFilled <= row.pathByteCount,
                  UInt64(bytes.count) <= row.pathByteCount - storage.pathFilled else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let filled = try ColdEraseControlBinaryV1.adding(storage.pathFilled, UInt64(bytes.count))
            let total = try ColdEraseControlBinaryV1.adding(storage.totalPathBytes, UInt64(bytes.count))
            let hashed = try ColdEraseControlBinaryV1.adding(storage.imageByteCount, UInt64(bytes.count))
            guard total <= 100_663_296, hashed <= 118_279_984 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            // Canonical UTF8/path order/role/raw referents must come from the
            // real checked source; lexical hash input never creates that proof.
            storage.imageHash.update(bufferPointer: bytes)
            storage.pathFilled = filled; storage.totalPathBytes = total; storage.imageByteCount = hashed
            storage.entered = false
        } catch { failed(); throw error }
    }

    fileprivate func finishRow() throws {
        try enter(.path)
        do {
            guard let row = storage.row, storage.pathFilled == row.pathByteCount,
                  storage.recordedPhysical < storage.input.physicalCount else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let physical = try ColdEraseControlBinaryV1.adding(storage.recordedPhysical, 1)
            var selected = storage.recordedSelected
            var mapCount = storage.mapByteCount
            if row.sourceRole != ColdEraseControlBinaryV1.CatalogSourceRole.physicalOnly.rawValue {
                guard selected < storage.input.selectedCount, storage.rowSourceOrdinal == selected else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                selected = try ColdEraseControlBinaryV1.adding(selected, 1)
                mapCount = try ColdEraseControlBinaryV1.adding(mapCount, 96)
                guard mapCount <= 9_600_048 else { throw EraseIntentStoreError.invalidAuthority }
                let content = try ColdEraseScratchProgressParserDigestV1(data: row.sha256)
                Self.updateWord(storage.rowSourceOrdinal, hash: &storage.mapHash)
                Self.updateWord(storage.rowPhysicalOrdinal, hash: &storage.mapHash)
                Self.updateWord(row.sourceRole, hash: &storage.mapHash)
                Self.updateWord(row.semanticVersion, hash: &storage.mapHash)
                Self.updateWord(storage.rowPathOffset, hash: &storage.mapHash)
                Self.updateWord(row.pathByteCount, hash: &storage.mapHash)
                Self.updateWord(storage.rowRawOffset, hash: &storage.mapHash)
                Self.updateWord(row.rawByteCount, hash: &storage.mapHash)
                Self.updateDigest(content, hash: &storage.mapHash)
            }
            storage.recordedPhysical = physical; storage.recordedSelected = selected
            storage.mapByteCount = mapCount
            storage.row = nil; storage.pathFilled = 0
            storage.phase = .rows; storage.entered = false
        } catch { failed(); throw error }
    }

    fileprivate func finish() throws -> ColdEraseScratchFirstIdentityEncoderCompletionV1 {
        try enter(.rows)
        do {
            guard storage.row == nil, let progress = storage.progressHeader,
                  storage.recordedPhysical == storage.input.physicalCount,
                  storage.recordedSelected == storage.input.selectedCount,
                  storage.nextHeaderOffset == (try ColdEraseControlBinaryV1.adding(16_512, storage.input.catalogByteCount)),
                  storage.mapByteCount == (try ColdEraseControlBinaryV1.adding(48,
                    ColdEraseControlBinaryV1.multiplying(storage.input.selectedCount, 96))) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let map = try Self.digest(storage.mapHash)
            let expectedImage = try ColdEraseControlBinaryV1.adding(16_688,
                ColdEraseControlBinaryV1.multiplying(storage.input.physicalCount, 176), storage.totalPathBytes)
            let finalImageCount = try ColdEraseControlBinaryV1.adding(storage.imageByteCount, 32)
            guard finalImageCount == expectedImage, finalImageCount <= 118_279_984 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            Self.updateDigest(map, hash: &storage.imageHash)
            storage.imageByteCount = finalImageCount
            let identity = try Self.digest(storage.imageHash)
            var stateHash = SHA256()
            Self.updateDomain(.state, hash: &stateHash)
            Self.updateDigest(storage.input.coreSHA256, hash: &stateHash)
            Self.updateDigest(identity, hash: &stateHash)
            let state = try Self.digest(stateHash)
            var anchorHash = SHA256()
            Self.updateDomain(.anchor, hash: &anchorHash)
            Self.updateWord(1, hash: &anchorHash); Self.updateWord(3, hash: &anchorHash)
            Self.updateDigest(progress.first, hash: &anchorHash)
            Self.updateDigest(progress.second, hash: &anchorHash)
            Self.updateDigest(state, hash: &anchorHash)
            let anchor = try Self.digest(anchorHash)
            let result = ColdEraseScratchFirstIdentityEncoderCompletionV1(selectedMapSHA256: map,
                firstIdentitySHA256: identity, initialStateSHA256: state, firstAnchorSHA256: anchor,
                physicalCount: storage.recordedPhysical, selectedCount: storage.recordedSelected,
                pathByteCount: storage.totalPathBytes, identityHashedByteCount: storage.imageByteCount,
                selectedMapHashedByteCount: storage.mapByteCount)
            storage.completion = result // actual fixed comparison BEFORE final return
            storage.phase = .finished; storage.entered = false
            return result
        } catch { failed(); throw error }
    }
}
