/// Actual one-way ownership transfer of the identical retained capsule
/// resources. The release-gap association below grants no IO permission;
/// activation independently requires the real checked loan and G releases.
@MainActor final class ColdEraseSchema2PostContentTransferReceiptV1 {
    private enum State { case prepared, transferred }
    fileprivate struct Backing {
        let ranges: ColdEraseScratchPayloadRangesV1
        let store: EraseIntentStore
        let operation: EraseColdPreparationOperationV1
        let from: ColdEraseScratchCleanupHeldGScopeV1
        let to: ColdEraseSchema2PostContentScopeV1
        let loan: ColdEraseScratchBorrowedParentsV1
        let contentReceipt: ColdEraseScratchCleanupReceiptV1
        let catalog: ColdEraseRetainedControlFileV1
        let progress: ColdEraseRetainedControlFileV1
        let cut: ColdEraseScratchCapsuleControlCutV1
    }
    fileprivate let backing: Backing
    private var state = State.prepared
    fileprivate static var backingBytes: UInt64 {
        UInt64(MemoryLayout<Backing>.stride + MemoryLayout<State>.stride)
    }
    fileprivate init(_ backing: Backing) { self.backing = backing }

    func requirePrepared(ranges: ColdEraseScratchPayloadRangesV1,
        store: EraseIntentStore, operation: EraseColdPreparationOperationV1,
        from: ColdEraseScratchCleanupHeldGScopeV1,
        to: ColdEraseSchema2PostContentScopeV1) throws {
        guard state == .prepared else { throw EraseIntentStoreError.invalidAuthority }
        try ranges.requirePreparedPostContentTransfer(self, store: store,
            operation: operation, from: from, to: to)
    }
    fileprivate func requireCommitAssociation(ranges: ColdEraseScratchPayloadRangesV1,
        store: EraseIntentStore, operation: EraseColdPreparationOperationV1,
        from: ColdEraseScratchCleanupHeldGScopeV1,
        to: ColdEraseSchema2PostContentScopeV1) throws {
        guard state == .prepared, backing.ranges === ranges,
              backing.store === store, backing.operation === operation,
              backing.from === from, backing.to === to else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try backing.contentReceipt.requireCheckedSettlement()
    }
    fileprivate func recordTransferred(ranges: ColdEraseScratchPayloadRangesV1,
        store: EraseIntentStore, operation: EraseColdPreparationOperationV1,
        from: ColdEraseScratchCleanupHeldGScopeV1,
        to: ColdEraseSchema2PostContentScopeV1) throws {
        try requireCommitAssociation(ranges: ranges, store: store,
            operation: operation, from: from, to: to)
        state = .transferred
    }
    func requireTransferred(to: ColdEraseSchema2PostContentScopeV1) throws {
        guard state == .transferred, backing.to === to else {
            throw EraseIntentStoreError.invalidAuthority
        }
        // Pure same-object receipt/resource association during the release
        // gap. No old loan descriptor, Registry or G predicate is entered.
        try backing.ranges.requireTransferredPostContentAssociation(self, to: to)
        try backing.contentReceipt.requireCheckedSettlement()
    }
    func requireActivated(to: ColdEraseSchema2PostContentScopeV1) throws {
        try requireTransferred(to: to)
        try to.requireCheckedTransferActivation(ranges: backing.ranges,
            store: backing.store, operation: backing.operation)
    }
}

/// Retained infrastructure for the cold engine. All constructors and range
/// registration remain in this file. Dispatch DATA never substitutes for the
/// exact operation, actual scope, retained Attempt and checked resource owner.
/// Closed namespace comparison storage. A lease is not a filesystem permit.
enum ColdEraseSchema2NamespaceMetadataKindV1: CaseIterable {
    case nodeTable, memberUTF8, childOrdinals, pathUTF8, readWindow, descriptorSlots
}

@MainActor final class ColdEraseSchema2NamespaceMetadataLeaseV1 {
    fileprivate struct Storage {
        let reservation: ColdEraseSchema2NamespaceCaptureReservationV1
        let capture: ColdEraseSchema2NamespaceCaptureOwnerV1
        let kind: ColdEraseSchema2NamespaceMetadataKindV1
        let reservedElementCount: UInt64
        let elementStride: UInt64
        let reservedBytes: UInt64
        var backing: ColdEraseSchema2NamespaceMetadataBackingV1?
        var actualCapacity: UInt64?
        var released = false
        var uncertain = false
    }
    private var storage: Storage
    var kind: ColdEraseSchema2NamespaceMetadataKindV1 { storage.kind }
    var reservedElementCount: UInt64 { storage.reservedElementCount }
    fileprivate var reservedBytes: UInt64 { storage.reservedBytes }
    fileprivate var isReleased: Bool { storage.released && !storage.uncertain }

    fileprivate init(reservation: ColdEraseSchema2NamespaceCaptureReservationV1,
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        kind: ColdEraseSchema2NamespaceMetadataKindV1, elementCount: UInt64,
        elementStride: UInt64, reservedBytes: UInt64) {
        storage = Storage(reservation: reservation, capture: capture, kind: kind,
            reservedElementCount: elementCount, elementStride: elementStride,
            reservedBytes: reservedBytes)
    }

    func recordAllocation(capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        backing: ColdEraseSchema2NamespaceMetadataBackingV1) throws {
        do {
            guard storage.capture === capture, !storage.released, !storage.uncertain,
                  storage.backing == nil, storage.actualCapacity == nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
            // Preserve the actual allocation before any throwing association,
            // capacity or full-current-prefix check.
            storage.backing = backing; storage.actualCapacity = backing.actualCapacity
            try storage.reservation.requireCaptureFrame(capture: capture)
            try backing.requireReservationAssociation(lease: self, capture: capture, kind: kind)
            guard backing.kind == kind, backing.actualCapacity == reservedElementCount,
                  backing.elementCount <= reservedElementCount else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try storage.reservation.requireMetadataLease(self, capture: capture)
        } catch { storage.uncertain = true; storage.reservation.poison(); throw error }
    }

    fileprivate func requireRelease(backing: ColdEraseSchema2NamespaceMetadataBackingV1,
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1) throws {
        guard storage.capture === capture, storage.backing === backing,
              !storage.released, !storage.uncertain,
              storage.actualCapacity == reservedElementCount else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try storage.reservation.requireCaptureFrame(capture: capture)
        try backing.requireReservationAssociation(lease: self, capture: capture, kind: kind)
        try backing.requireCheckedReleased(lease: self, capture: capture)
        guard backing.elementCount == 0 else { throw EraseIntentStoreError.invalidAuthority }
    }

    fileprivate func recordReleased() { storage.released = true }
}

/// One charged comparison window over the authentic immutable Operations
/// roster. No current inode/UID/GID/policy is derived from these first9 DATA.
/// Only the transferred range owner can construct this value; the closed
/// synchronous scanner callback consumes it into separately charged scalars.
@MainActor struct ColdEraseSchema2NamespaceOriginalNodeV1 {
    let ordinal: UInt64
    let path: String
    let kind: String
    let firstNineFact: String
    let byteCount: UInt64
    let sha256: String?

    fileprivate static var declaredBackingBytes: UInt64 {
        // Active storage plus callback/local value aliases, one bounded path,
        // first9 text, kind and SHA. Original roster backing stays retained.
        UInt64(3 * MemoryLayout<Self>.stride
            + 2 * MemoryLayout<[EraseSchema2ColdAuxiliaryPhysicalRosterV1.Node]>.stride
            + 16_640 + 197 + 9 + 64)
    }
    fileprivate init(ordinal: UInt64,
        first: EraseSchema2ColdAuxiliaryPhysicalRosterV1.Node) throws {
        guard first.path.utf8.count <= 16_640, first.fact.utf8.count <= 197,
              first.kind == "directory" || first.kind == "file" else {
            throw EraseIntentStoreError.invalidAuthority
        }
        self.ordinal = ordinal; path = first.path; kind = first.kind
        firstNineFact = first.fact
        byteCount = try Self.firstByteCount(first.fact, kind: first.kind)
        sha256 = first.sha256
        if first.kind == "directory" {
            guard first.sha256 == nil, first.members != nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
        } else {
            guard first.members == nil, let sha = first.sha256,
                  StoreMigrationCanonicalJSONV1.isLowercaseSHA256(sha),
                  byteCount <= 1_073_741_824 else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
    }

    /// Canonical first9 parsing uses scalar accumulators only, no split/path
    /// arrays or guessed full11 conversion. Negative timestamp seconds are
    /// preserved comparison fields, never a chosen task date.
    private static func firstByteCount(_ text: String, kind: String) throws -> UInt64 {
        var field = 0, magnitude: UInt64 = 0, digits = 0
        var negative = false, leadingZero = false
        var size: UInt64 = 0, mode: UInt64 = 0, links: UInt64 = 0
        func finish() throws {
            guard digits > 0, field < 9, !(negative && magnitude == 0) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            if field == 5 || field == 7 {
                let ceiling = negative ? UInt64(Int64.max) + 1 : UInt64(Int64.max)
                guard magnitude <= ceiling else { throw EraseIntentStoreError.invalidAuthority }
            } else {
                guard !negative else { throw EraseIntentStoreError.invalidAuthority }
            }
            switch field {
            case 0: guard magnitude <= UInt64(Int64.max) else { throw EraseIntentStoreError.invalidAuthority }
            case 1: guard magnitude > 0 else { throw EraseIntentStoreError.invalidAuthority }
            case 2:
                guard magnitude > 0, magnitude <= UInt64(mode_t.max) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                mode = magnitude
            case 3:
                guard magnitude > 0 else { throw EraseIntentStoreError.invalidAuthority }
                links = magnitude
            case 4:
                guard magnitude <= UInt64(Int64.max) else { throw EraseIntentStoreError.invalidAuthority }
                size = magnitude
            case 6, 8:
                guard magnitude < 1_000_000_000 else { throw EraseIntentStoreError.invalidAuthority }
            default: break
            }
            field += 1; magnitude = 0; digits = 0; negative = false; leadingZero = false
        }
        for byte in text.utf8 {
            if byte == 124 { try finish(); continue }
            if byte == 45 && digits == 0 && !negative {
                negative = true; continue
            }
            guard byte >= 48, byte <= 57, digits < 20, !(digits > 0 && leadingZero) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            if digits == 0 { leadingZero = byte == 48 }
            let multiplied = magnitude.multipliedReportingOverflow(by: 10)
            let added = multiplied.partialValue.addingReportingOverflow(UInt64(byte - 48))
            guard !multiplied.overflow, !added.overflow else { throw EraseIntentStoreError.invalidAuthority }
            magnitude = added.partialValue; digits += 1
        }
        try finish()
        guard field == 9 else { throw EraseIntentStoreError.invalidAuthority }
        if kind == "directory" {
            guard mode & UInt64(S_IFMT) == UInt64(S_IFDIR), links > 0 else {
                throw EraseIntentStoreError.invalidAuthority
            }
        } else {
            guard mode & UInt64(S_IFMT) == UInt64(S_IFREG), links == 1 else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        return size
    }
}

/// Actual pre-capture reservation, retained before the Registry allocates its
/// private capture owner. All stored identities are genuine producer objects;
/// checked storage accounting is not RSS or cached filesystem authority.
// NAMESPACE_AUTHENTIC_AUXILIARY_DIGEST_V1_BEGIN
/// Immutable raw-source identity DATA. A hash never grants current IO,
/// inventory settlement, a durable range, selected policy or unlink.
@MainActor final class ColdEraseSchema2NamespaceAuthenticatedAuxiliaryDigestV1 {
    fileprivate struct Storage {
        let ranges: ColdEraseScratchPayloadRangesV1
        let reservation: ColdEraseSchema2NamespaceCaptureReservationV1
        let capture: ColdEraseSchema2NamespaceCaptureOwnerV1
        let preparation: ColdEraseSchema2NamespaceRemovalPreparationV1
        let roster: EraseSchema2ColdAuxiliaryPhysicalRosterV1
        let identity: ColdEraseScratchBirthIdentityInitializationV1
        let bytes: Data
        let digest: Data
    }
    fileprivate let storage: Storage
    var sha256: Data { storage.digest }
    fileprivate static var declaredBackingBytes: UInt64 {
        UInt64(MemoryLayout<Storage>.stride + 6 * MemoryLayout<Data>.stride
            + 2 * MemoryLayout<SHA256>.stride + 2 * MemoryLayout<SHA256.Digest>.stride)
            + 8 * 32 + 4 * 64
        // The already retained auxiliary raw bytes are aliased, not cloned.
        // No tree/JSON decoder or recipe-sized Data allocation exists here.
    }
    fileprivate init(ranges: ColdEraseScratchPayloadRangesV1,
        reservation: ColdEraseSchema2NamespaceCaptureReservationV1,
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        preparation: ColdEraseSchema2NamespaceRemovalPreparationV1,
        roster: EraseSchema2ColdAuxiliaryPhysicalRosterV1,
        identity: ColdEraseScratchBirthIdentityInitializationV1,
        bytes: Data, digest: Data) {
        storage = .init(ranges: ranges, reservation: reservation, capture: capture,
            preparation: preparation, roster: roster, identity: identity, bytes: bytes, digest: digest)
    }
    func requireAssociation(preparation: ColdEraseSchema2NamespaceRemovalPreparationV1) throws {
        guard storage.preparation === preparation, preparation.capture === storage.capture,
              storage.digest.count == 32, storage.identity.storage.phase == .installed,
              storage.identity.storage.retainedFailure == nil,
              storage.roster.canonicalBytes == storage.bytes else { throw EraseIntentStoreError.invalidAuthority }
        try preparation.requireCaptureAssociation(capture: storage.capture)
        try storage.reservation.requireCompletedNamespaceCaptureMemory(storage.capture)
        try storage.ranges.requireNamespaceAuxiliaryDigestMemory(self)
    }
}
