// NAMESPACE_V4_EXPLICIT_BINARY_CODEC_V1_BEGIN
/// Pure new-format DATA; all old codec bytes remain unchanged.
enum ColdErasePostContentBinaryV4 {
    static let maximumProgressBytes: UInt64 = 55_568_624_768
    static let maximumTaskCount: UInt64 = 1_500_134
    // Pure explicitly discriminated V4 DATA only. Genuine emission and
    // admissions require separate actual Source/current/resource producers.
    // V1-V3 decoders/caps and domain0 Scratch/catalog2 remain untouched.
    // No fallback, old-core upgrade or post-transfer Scratch rearm.
    private static let maximumReaderRecipeBytes: UInt64 = 12_648_512
    private static let payloadByteCount = 864
    private static let coreMagic = padded("FE_COLD_CONTROL_BINARY_V4", count: 32)
    private static let progressMagic = padded("FE_COLD_PROG_V4", count: 16)
    private static let frameMagic = padded("FE_COLD_FRAME_V1", count: 16)

    enum Domain: UInt64 { case reader = 1, namespace = 2 }

    struct FrameHeader: Equatable {
        let kind: ColdEraseControlBinaryV1.FrameHeader.Kind
        let sequence: UInt64
        let taskKind: UInt64
        let payloadBytes: UInt64
        let recipeBytes: UInt64
        let changedFactCount: UInt64
        let domain: Domain
        let previousFrameSHA256: Data

        // The only initializer proves this exact sum, including Int/off_t bounds.
        var totalBytes: UInt64 { 128 + payloadBytes + recipeBytes + 32 }

        fileprivate init(kind: ColdEraseControlBinaryV1.FrameHeader.Kind,
            sequence: UInt64, domain: Domain, taskKind: UInt64,
            payloadBytes: UInt64, recipeBytes: UInt64, changedFactCount: UInt64,
            previousFrameSHA256: Data) throws {
            _ = try ColdErasePostContentBinaryV4.requireFrameFields(kind: kind,
                sequence: sequence, domain: domain, taskKind: taskKind,
                payloadBytes: payloadBytes, recipeBytes: recipeBytes,
                changedFactCount: changedFactCount,
                previousFrameSHA256: previousFrameSHA256)
            self.kind = kind
            self.sequence = sequence
            self.domain = domain
            self.taskKind = taskKind
            self.payloadBytes = payloadBytes
            self.recipeBytes = recipeBytes
            self.changedFactCount = changedFactCount
            self.previousFrameSHA256 = previousFrameSHA256
        }
    }

    static func header(kind: ColdEraseControlBinaryV1.Kind,
        ranges: [UInt64]) throws -> Data {
        // Reuse the unchanged V1 encoder's closed kind/range/cap arithmetic.
        // Only the two explicitly versioned fields change in this private DATA.
        var data = try ColdEraseControlBinaryV1.header(kind: kind, ranges: ranges)
        guard data.count == 128 else { throw EraseIntentStoreError.invalidAuthority }
        let start = data.startIndex
        data.replaceSubrange(start..<(start + 32), with: coreMagic)
        var version = Data(capacity: 8)
        appendWord(4, to: &version)
        data.replaceSubrange((start + 32)..<(start + 40), with: version)
        guard data.count == 128 else { throw EraseIntentStoreError.invalidAuthority }
        return data
    }

    static func decodeHeader(_ data: Data) throws -> ColdEraseControlBinaryV1.Header {
        guard data.count == 128 else { throw EraseIntentStoreError.invalidAuthority }
        var cursor = Cursor(data: data)
        guard try cursor.bytes(32) == coreMagic, try cursor.word() == 4,
              let kind = ColdEraseControlBinaryV1.Kind(rawValue: try cursor.word()),
              try cursor.word() == 0, try cursor.word() == 6 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var ranges: [UInt64] = []
        ranges.reserveCapacity(6)
        for _ in 0..<6 { ranges.append(try cursor.word()) }
        guard try cursor.bytes(16).allSatisfy({ $0 == 0 }),
              cursor.offset == 128,
              try header(kind: kind, ranges: ranges) == data else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var count = try ColdEraseControlBinaryV1.adding(
            ColdEraseControlBinaryV1.headerBytes, ColdEraseControlBinaryV1.metadataBytes)
        for length in ranges { count = try ColdEraseControlBinaryV1.adding(count, length) }
        return ColdEraseControlBinaryV1.Header(kind: kind, ranges: ranges,
            encodedByteCount: count)
    }

    static func progressHeader(coreSHA256: Data) throws -> Data {
        guard coreSHA256.count == 32 else { throw EraseIntentStoreError.invalidAuthority }
        var data = progressMagic
        appendWord(4, to: &data)
        appendWord(1, to: &data)
        data.append(coreSHA256)
        guard data.count == 64 else { throw EraseIntentStoreError.invalidAuthority }
        return data
    }

    static func decodeProgressHeader(_ data: Data,
        expectedCoreSHA256: Data) throws {
        guard data.count == 64, expectedCoreSHA256.count == 32,
              try progressHeader(coreSHA256: expectedCoreSHA256) == data else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    private static func requireFrameFields(kind: ColdEraseControlBinaryV1.FrameHeader.Kind,
        sequence: UInt64, domain: Domain, taskKind: UInt64,
        payloadBytes: UInt64, recipeBytes: UInt64, changedFactCount: UInt64,
        previousFrameSHA256: Data) throws -> UInt64 {
        guard sequence > 0, sequence <= maximumTaskCount,
              payloadBytes == UInt64(payloadByteCount),
              (1...4).contains(changedFactCount), previousFrameSHA256.count == 32 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        switch domain {
        case .reader:
            guard taskKind == 1 || taskKind == 2 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            if kind == .request && taskKind == 1 {
                guard recipeBytes > 0, recipeBytes <= maximumReaderRecipeBytes else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            } else {
                guard recipeBytes == 0 else { throw EraseIntentStoreError.invalidAuthority }
            }
        case .namespace:
            switch taskKind {
            case 1:
                guard recipeBytes == 0 else { throw EraseIntentStoreError.invalidAuthority }
            case 2:
                // V3's sole metadata prerequisite, comparison framing only.
                // Authentic selected ordinals/full11/policy/recipe chain and
                // the real two-scan consumer remain the genuine owner checks.
                guard changedFactCount == 2 else { throw EraseIntentStoreError.invalidAuthority }
                if kind == .request {
                    guard recipeBytes >= 128, recipeBytes <= 2_400_128 else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                } else {
                    guard recipeBytes == 0 else { throw EraseIntentStoreError.invalidAuthority }
                }
            case 3:
                // Exactly one once-pinned Creator comparison baseline, never
                // an unlink or caller-index extension. Authentic recipe and
                // Source/resource admission are separate owner consumers.
                guard changedFactCount == 2 else { throw EraseIntentStoreError.invalidAuthority }
                if kind == .request {
                    guard recipeBytes >= 128, recipeBytes <= 10_493_056 else { throw EraseIntentStoreError.invalidAuthority }
                } else {
                    guard recipeBytes == 0 else { throw EraseIntentStoreError.invalidAuthority }
                }
            default: throw EraseIntentStoreError.invalidAuthority
            }
        }
        return try ColdEraseControlBinaryV1.adding(128, payloadBytes, recipeBytes, 32)
    }

    static func frameHeader(kind: ColdEraseControlBinaryV1.FrameHeader.Kind,
        sequence: UInt64, domain: Domain, taskKind: UInt64,
        payloadBytes: UInt64, recipeBytes: UInt64, changedFactCount: UInt64,
        previousFrameSHA256: Data) throws -> Data {
        _ = try requireFrameFields(kind: kind, sequence: sequence, domain: domain,
            taskKind: taskKind, payloadBytes: payloadBytes, recipeBytes: recipeBytes,
            changedFactCount: changedFactCount, previousFrameSHA256: previousFrameSHA256)
        var data = frameMagic
        for word in [UInt64(1), kind.rawValue, sequence, taskKind,
                payloadBytes, recipeBytes, changedFactCount, domain.rawValue] {
            appendWord(word, to: &data)
        }
        data.append(previousFrameSHA256)
        data.append(Data(repeating: 0, count: 16))
        guard data.count == 128 else { throw EraseIntentStoreError.invalidAuthority }
        return data
    }

    static func decodeFrameHeader(_ data: Data) throws -> FrameHeader {
        guard data.count == 128 else { throw EraseIntentStoreError.invalidAuthority }
        var cursor = Cursor(data: data)
        guard try cursor.bytes(16) == frameMagic, try cursor.word() == 1,
              let kind = ColdEraseControlBinaryV1.FrameHeader.Kind(rawValue: try cursor.word()) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let sequence = try cursor.word(), task = try cursor.word()
        let payload = try cursor.word(), recipe = try cursor.word(), facts = try cursor.word()
        guard let domain = Domain(rawValue: try cursor.word()) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let prior = try cursor.bytes(32)
        guard try cursor.bytes(16).allSatisfy({ $0 == 0 }), cursor.offset == 128,
              try frameHeader(kind: kind, sequence: sequence, domain: domain,
                taskKind: task, payloadBytes: payload, recipeBytes: recipe,
                changedFactCount: facts, previousFrameSHA256: prior) == data else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return try FrameHeader(kind: kind, sequence: sequence, domain: domain,
            taskKind: task, payloadBytes: payload, recipeBytes: recipe,
            changedFactCount: facts, previousFrameSHA256: prior)
    }

    static func payloadFields(_ value: ColdErasePostContentBinaryV2.PayloadFields) throws -> Data {
        try ColdErasePostContentBinaryV2.payloadFields(value)
    }
    static func decodePayloadFields(_ data: Data) throws -> ColdErasePostContentBinaryV2.PayloadFields {
        try ColdErasePostContentBinaryV2.decodePayloadFields(data)
    }

    /// Complete V4 namespace shape/re-encoding DATA. SAME private Source,
    /// parent, range, pending Request and current raw resource admission must
    /// still be checked by the controller; this decoder grants no effects.
    static func decodeNamespacePayload(_ bytes: Data, header: FrameHeader)
        throws -> ColdErasePostContentBinaryV2.PayloadFields {
        guard header.domain == .namespace else { throw EraseIntentStoreError.invalidAuthority }
        let value = try decodePayloadFields(bytes)
        let words = value.words
        guard words.count == 16, value.facts.count == 4, value.digests.count == 12,
              words[0] == 1, words[2] == 1, words[15] == 0,
              words[9] == (header.kind == .request ? 1 : 2),
              value.facts[2].allSatisfy({ $0 == 0 }), value.facts[3].allSatisfy({ $0 == 0 }),
              value.digests[7].allSatisfy({ $0 == 0 }), value.digests[11].allSatisfy({ $0 == 0 }),
              header.kind != .request || value.digests[2].allSatisfy({ $0 == 0 }),
              try payloadFields(value) == bytes else { throw EraseIntentStoreError.invalidAuthority }
        switch header.taskKind {
        case 1:
            guard (1...3).contains(words[1]), words[6] == 1 || words[6] == 2,
                  words[10] > 0, words[11] == words[10] - 1,
                  (1...4).contains(words[4]), header.recipeBytes == 0,
                  value.facts[1][2] & UInt64(S_IFMT) == UInt64(S_IFDIR),
                  header.kind != .request || value.facts[0][2] & UInt64(S_IFMT)
                    == (words[6] == 2 ? UInt64(S_IFDIR) : UInt64(S_IFREG)),
                  words[14] == (header.kind == .request ? 2 : 1),
                  header.changedFactCount == words[14],
                  !value.facts[1].allSatisfy({ $0 == 0 }),
                  header.kind == .request ? !value.facts[0].allSatisfy({ $0 == 0 })
                    : value.facts[0].allSatisfy({ $0 == 0 }),
                  words[6] != 2 || value.digests[6].allSatisfy({ $0 == 0 }),
                  header.kind != .observation || value.digests[6].allSatisfy({ $0 == 0 }) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            switch words[1] {
            case 1:
                guard words[12] == 0, words[13] == 0, value.digests[4].allSatisfy({ $0 == 0 }),
                      words[4] == 1 || (words[4] == 3 && words[5] == 0 && words[6] == 2) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            case 2:
                guard words[12] >= 64, words[13] > 0, words[13] <= maximumReaderRecipeBytes,
                      words[4] == 1 || words[4] == 2,
                      words[4] != 1 || words[6] == 2 else { throw EraseIntentStoreError.invalidAuthority }
            case 3:
                guard (1...12).contains(words[3]), words[12] >= 64,
                      words[13] >= 128, words[13] <= 10_493_056 else { throw EraseIntentStoreError.invalidAuthority }
                if words[3] == 1 || words[3] == 2 {
                    guard words[4] == 1, words[3] != 1 || words[6] == 2,
                          words[3] != 2 || words[6] == 1 else { throw EraseIntentStoreError.invalidAuthority }
                } else {
                    guard words[4] == 4, words[5] == 1, words[6] == 1 else { throw EraseIntentStoreError.invalidAuthority }
                }
            default: throw EraseIntentStoreError.invalidAuthority
            }
            if header.kind == .request { _ = try ColdEraseControlBinaryV1.policy(words[7], fact: value.facts[0]) }
            _ = try ColdEraseControlBinaryV1.policy(words[8], fact: value.facts[1])
        case 2, 3:
            let recipeMaximum: UInt64 = header.taskKind == 2 ? 2_400_128 : 10_493_056
            guard words[1] == (header.taskKind == 2 ? 1 : 3),
                  words[3] <= (header.taskKind == 2 ? 99_999 : 12),
                  words[4] == 3, words[5] == 0, words[6] == 2,
                  words[10] == words[11], words[12] >= 64, words[13] >= 128,
                  words[13] <= recipeMaximum, words[14] == 2, header.changedFactCount == 2,
                  !value.facts[0].allSatisfy({ $0 == 0 }), !value.facts[1].allSatisfy({ $0 == 0 }),
                  value.facts[0][2] & UInt64(S_IFMT) == UInt64(S_IFDIR),
                  value.facts[1][2] & UInt64(S_IFMT) == UInt64(S_IFDIR),
                  value.digests[6].allSatisfy({ $0 == 0 }),
                  header.kind == .request ? header.recipeBytes == words[13] : header.recipeBytes == 0 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            if header.taskKind == 2 {
                guard words[13] == (try ColdEraseControlBinaryV1.adding(128,
                    ColdEraseControlBinaryV1.multiplying(words[3], 24))) else { throw EraseIntentStoreError.invalidAuthority }
            }
            _ = try ColdEraseControlBinaryV1.policy(words[7], fact: value.facts[0])
            _ = try ColdEraseControlBinaryV1.policy(words[8], fact: value.facts[1])
        default: throw EraseIntentStoreError.invalidAuthority
        }
        let rangeEnd = try ColdEraseControlBinaryV1.adding(words[12], words[13])
        guard rangeEnd <= maximumProgressBytes else { throw EraseIntentStoreError.invalidAuthority }
        return value
    }

    private static func padded(_ value: String, count: Int) -> Data {
        // Called only for the three fixed literals above, never caller text.
        var data = Data(value.utf8)
        precondition(data.count <= count)
        data.append(Data(repeating: 0, count: count - data.count))
        return data
    }

    private static func appendWord(_ word: UInt64, to data: inout Data) {
        var value = word.littleEndian
        withUnsafeBytes(of: &value) { data.append(contentsOf: $0) }
    }

    private struct Cursor {
        let data: Data
        var offset = 0

        mutating func bytes(_ count: Int) throws -> Data {
            guard count >= 0, offset >= 0, offset <= data.count,
                  count <= data.count - offset else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let start = data.index(data.startIndex, offsetBy: offset)
            let end = data.index(start, offsetBy: count)
            offset += count
            return Data(data[start..<end])
        }

        mutating func word() throws -> UInt64 {
            guard offset >= 0, offset <= data.count, data.count - offset >= 8 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            var value: UInt64 = 0
            for byte in 0..<8 {
                let index = data.index(data.startIndex, offsetBy: offset + byte)
                value |= UInt64(data[index]) << UInt64(8 * byte)
            }
            offset += 8
            return value
        }
    }
}
