// NAMESPACE_V4_REQUEST_OBSERVATION_CODEC_V1_BEGIN
/// Canonical DATA only. The genuine private Request supplies every selected
/// value from its retained Source/Reader origin and actual current resource.
fileprivate enum ColdEraseSchema2NamespaceJournalCodecV4 {
    struct Selector: Equatable {
        let domain: UInt64
        let ordinal: UInt64
        let parentDomain: UInt64
        let parentOrdinal: UInt64
        let kind: UInt64
        let selectedPolicy: UInt64
        let parentPolicy: UInt64
        let parentCountBefore: UInt64
        let readerRecipeOffset: UInt64
        let readerRecipeCount: UInt64
    }
    static func word(_ value: UInt64, at offset: Int, into bytes: inout Data) throws {
        guard offset >= 0, offset <= bytes.count, bytes.count - offset >= 8 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        for index in 0..<8 {
            bytes[bytes.startIndex + offset + index] = UInt8(truncatingIfNeeded: value >> UInt64(index * 8))
        }
    }
    static func digest(_ value: Data, at ordinal: Int, into bytes: inout Data) throws {
        guard value.count == 32, ordinal >= 0, ordinal < 12, bytes.count == 864 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let first = bytes.startIndex + 480 + ordinal * 32
        bytes.replaceSubrange(first..<(first + 32), with: value)
    }
    static func fact(_ value: EraseColdControlLeafFactV1, at ordinal: Int,
        into bytes: inout Data) throws {
        guard ordinal >= 0, ordinal < 2, bytes.count == 864,
              let device = UInt64(exactly: value.device), let inode = UInt64(exactly: value.inode),
              let mode = UInt64(exactly: value.mode), let user = UInt64(exactly: value.user),
              let group = UInt64(exactly: value.group), let links = UInt64(exactly: value.links),
              value.size >= 0, value.modifiedNanoseconds >= 0, value.modifiedNanoseconds < 1_000_000_000,
              value.changedNanoseconds >= 0, value.changedNanoseconds < 1_000_000_000 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try word(device, at: 128 + ordinal * 88, into: &bytes)
        try word(inode, at: 136 + ordinal * 88, into: &bytes)
        try word(mode, at: 144 + ordinal * 88, into: &bytes)
        try word(user, at: 152 + ordinal * 88, into: &bytes)
        try word(group, at: 160 + ordinal * 88, into: &bytes)
        try word(links, at: 168 + ordinal * 88, into: &bytes)
        try word(UInt64(value.size), at: 176 + ordinal * 88, into: &bytes)
        try word(UInt64(bitPattern: value.modifiedSeconds), at: 184 + ordinal * 88, into: &bytes)
        try word(UInt64(value.modifiedNanoseconds), at: 192 + ordinal * 88, into: &bytes)
        try word(UInt64(bitPattern: value.changedSeconds), at: 200 + ordinal * 88, into: &bytes)
        try word(UInt64(value.changedNanoseconds), at: 208 + ordinal * 88, into: &bytes)
    }
    static func selectedPayload(selector: Selector, selected: EraseColdControlLeafFactV1?,
        parent: EraseColdControlLeafFactV1, before: Bool,
        priorState: Data, currentPrefix: Data, recipeSHA: Data, auxiliarySHA: Data,
        selectedSHA: Data, targetBindingSHA: Data, controlSHA: Data, coreSHA: Data) throws -> Data {
        guard selector.domain == 1 || selector.domain == 2 || selector.domain == 3,
              (1...4).contains(selector.parentDomain),
              selector.kind == 1 || selector.kind == 2, selector.parentCountBefore > 0,
              selector.parentDomain != 3 || (selector.parentOrdinal == 0 && selector.kind == 2),
              (selector.domain == 1 && selector.readerRecipeOffset == 0 && selector.readerRecipeCount == 0)
                || ((selector.domain == 2 || selector.domain == 3) && selector.readerRecipeOffset >= 64 && selector.readerRecipeCount > 0),
              before ? selected != nil : selected == nil,
              selector.kind != 2 || selectedSHA.allSatisfy({ $0 == 0 }) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var bytes = Data(repeating: 0, count: 864)
        let words = [UInt64(1), selector.domain, UInt64(1), selector.ordinal,
            selector.parentDomain, selector.parentOrdinal, selector.kind,
            selector.selectedPolicy, selector.parentPolicy, before ? UInt64(1) : UInt64(2),
            selector.parentCountBefore, selector.parentCountBefore - 1,
            selector.readerRecipeOffset, selector.readerRecipeCount, before ? UInt64(2) : UInt64(1), UInt64(0)]
        for index in 0..<16 { try word(words[index], at: index * 8, into: &bytes) }
        if let selected { try fact(selected, at: 0, into: &bytes) }
        try fact(parent, at: 1, into: &bytes)
        let zero = Data(repeating: 0, count: 32)
        for (ordinal, value) in [(0, priorState), (1, zero), (2, zero), (3, currentPrefix),
            (4, recipeSHA), (5, auxiliarySHA), (6, before ? selectedSHA : zero),
            (7, zero), (8, targetBindingSHA), (9, controlSHA), (10, coreSHA), (11, zero)] {
            try digest(value, at: ordinal, into: &bytes)
        }
        let headerBytes = try ColdErasePostContentBinaryV4.frameHeader(kind: before ? .request : .observation,
            sequence: 1, domain: .namespace, taskKind: 1, payloadBytes: 864, recipeBytes: 0,
            changedFactCount: before ? 2 : 1, previousFrameSHA256: Data(repeating: 0, count: 32))
        let shape = try ColdErasePostContentBinaryV4.decodeFrameHeader(headerBytes)
        _ = try ColdErasePostContentBinaryV4.decodeNamespacePayload(bytes, header: shape)
        return bytes
    }
    /// The metadata task has its own closed kind2 payload; it never aliases
    /// a selected deletion ordinal. Both REQUEST and OBS retain present roots.
    enum Baseline: UInt64 { case coldFirstMetadata = 2, creatorInventory = 3 }
    static func metadataPayload(baseline: Baseline, selectedCount: UInt64, operations: EraseColdControlLeafFactV1,
        support: EraseColdControlLeafFactV1, operationsPolicy: UInt64, supportPolicy: UInt64,
        supportCount: UInt64, recipeOffset: UInt64, recipeCount: UInt64, before: Bool,
        priorState: Data, currentPrefix: Data, recipeSHA: Data, auxiliarySHA: Data,
        targetBindingSHA: Data, controlSHA: Data, coreSHA: Data) throws -> Data {
        guard selectedCount <= (baseline == .coldFirstMetadata ? 99_999 : 12), operations.mode & mode_t(S_IFMT) == mode_t(S_IFDIR),
              support.mode & mode_t(S_IFMT) == mode_t(S_IFDIR), recipeOffset >= 64,
              (baseline == .coldFirstMetadata ? recipeCount == 128 + 24 * selectedCount : recipeCount >= 128),
              recipeCount <= (baseline == .coldFirstMetadata ? 2_400_128 : 10_493_056) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var bytes = Data(repeating: 0, count: 864)
        let words = [UInt64(1), baseline == .coldFirstMetadata ? UInt64(1) : UInt64(3), UInt64(1), selectedCount,
            UInt64(3), UInt64(0), UInt64(2), operationsPolicy, supportPolicy,
            before ? UInt64(1) : UInt64(2), supportCount, supportCount,
            recipeOffset, recipeCount, UInt64(2), UInt64(0)]
        for index in 0..<16 { try word(words[index], at: index * 8, into: &bytes) }
        try fact(operations, at: 0, into: &bytes); try fact(support, at: 1, into: &bytes)
        let zero = Data(repeating: 0, count: 32)
        for (ordinal, value) in [(0, priorState), (1, zero), (2, zero), (3, currentPrefix),
            (4, recipeSHA), (5, auxiliarySHA), (6, zero), (7, zero),
            (8, targetBindingSHA), (9, controlSHA), (10, coreSHA), (11, zero)] {
            try digest(value, at: ordinal, into: &bytes)
        }
        let headerBytes = try ColdErasePostContentBinaryV4.frameHeader(kind: before ? .request : .observation,
            sequence: 1, domain: .namespace, taskKind: baseline.rawValue, payloadBytes: 864,
            recipeBytes: before ? recipeCount : 0, changedFactCount: 2,
            previousFrameSHA256: Data(repeating: 0, count: 32))
        let shape = try ColdErasePostContentBinaryV4.decodeFrameHeader(headerBytes)
        _ = try ColdErasePostContentBinaryV4.decodeNamespacePayload(bytes, header: shape)
        return bytes
    }
    static func requestIdentity(taskKind: UInt64, payload: Data, priorState: Data,
        recipeOffset: UInt64, recipeCount: UInt64, recipeSHA: Data) throws -> Data {
        guard (1...3).contains(taskKind), payload.count == 864, priorState.count == 32, recipeSHA.count == 32,
              payload[(payload.startIndex + 512)..<(payload.startIndex + 576)].allSatisfy({ $0 == 0 }) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var hash = SHA256(); hash.update(data: try domain("FE_COLD_NS_REQID_V4"))
        update(2, hash: &hash); update(taskKind, hash: &hash)
        hash.update(data: payload); hash.update(data: priorState)
        var offset = recipeOffset.littleEndian, count = recipeCount.littleEndian
        withUnsafeBytes(of: &offset) { hash.update(bufferPointer: $0) }
        withUnsafeBytes(of: &count) { hash.update(bufferPointer: $0) }
        hash.update(data: recipeSHA); return Data(hash.finalize())
    }
    static func afterState(taskKind: UInt64, payload: Data, priorState: Data, requestIdentity: Data) throws -> Data {
        guard (1...3).contains(taskKind), payload.count == 864, priorState.count == 32, requestIdentity.count == 32,
              payload[(payload.startIndex + 512)..<(payload.startIndex + 576)].allSatisfy({ $0 == 0 }) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var hash = SHA256(); hash.update(data: try domain("FE_COLD_NS_POST_V4"))
        update(2, hash: &hash); update(taskKind, hash: &hash)
        hash.update(data: priorState); hash.update(data: requestIdentity)
        hash.update(data: payload); return Data(hash.finalize())
    }
    private static func domain(_ text: String) throws -> Data {
        let bytes = Data(text.utf8)
        guard bytes.count <= 32 else { throw EraseIntentStoreError.invalidAuthority }
        var result = bytes; result.append(Data(repeating: 0, count: 32 - bytes.count)); return result
    }
    private static func update(_ value: UInt64, hash: inout SHA256) {
        var raw = value.littleEndian
        withUnsafeBytes(of: &raw) { hash.update(bufferPointer: $0) }
    }
    /// Pure canonical target comparison bytes. The only eventual issuer must
    /// supply SAME authentic core/current OP/Main/Manifest/empty-target origin;
    /// this function cannot validate or grant their physical authority.
    static func targetBinding(metadata: ColdEraseControlBinaryV1.Metadata) throws -> Data {
        guard metadata.identifiers.count == 16, metadata.digests.count == 64,
              [0, 2, 5, 6].allSatisfy({ metadata.identifiers[$0].count == 16 }),
              metadata.digests[6].count == 32, metadata.digests[8].count == 32 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var hash = SHA256(); hash.update(data: try domain("FE_COLD_NS_TARG_BIND_V4"))
        update(2, hash: &hash) // actual schema2 comparison vocabulary
        for ordinal in [0, 2, 5, 6] { hash.update(data: metadata.identifiers[ordinal]) }
        hash.update(data: metadata.digests[6]); hash.update(data: metadata.digests[8])
        return Data(hash.finalize())
    }
}
