// POSTCONTENT_NAMESPACE_CURRENT_PREFIX_SCOPE_V1_BEGIN
// Private candidate. Target typed source/profile/resource producers are exact
// external dependencies; this is never a registered BIRTH or pre-Seed route.
@MainActor final class ColdEraseSchema2NamespaceCurrentPrefixScopeV1 {
    fileprivate enum Phase { case profiling, ready, first, between, second,
        bothChecked, unlockChecked, completed, uncertain }
    fileprivate struct Construction {
        let pass: UInt8
        let ordinal: UInt64
        let pathBytes: UInt64
        let memberBytes: UInt64
        let declaredBytes: UInt64
    }
    /// SAME prepaid ordering/hash owner. Token bytes are streamed from the
    /// retained rows; no token String/array/Data copy is constructed. Its
    /// initialized index pointer and finalized value remain strongly retained.
    /// Canonical order/digest are DATA and grant no current authority.
    @MainActor fileprivate final class TokenSet {
        struct Storage {
            var ordinals: UnsafeMutablePointer<UInt64>?
            var initialized: Int = 0
            var requestedCapacity: Int = 0
            var hash = SHA256()
            var pendingBytes: (UInt64, UInt64, UInt64, UInt64, UInt64, UInt64, UInt64, UInt64) = (0, 0, 0, 0, 0, 0, 0, 0)
            var pendingByteCount: Int = 0
            var finalized: SHA256.Digest?
            var digest: String?
            var hashRowCount: UInt64 = 0
            var returned = false
        }
        var storage = Storage()
        static func requiredFixedBackingBytes() throws -> UInt64 {
            try ColdEraseControlBinaryV1.adding(UInt64(MemoryLayout<Storage>.stride),
                UInt64(MemoryLayout<SHA256.Digest>.stride), 2 * 64,
                UInt64(MemoryLayout<(UInt64, UInt64, UInt64, UInt64, UInt64, UInt64, UInt64, UInt64)>.stride
                    + 2 * MemoryLayout<UnsafeRawBufferPointer>.stride),
                UInt64(12 * MemoryLayout<UInt64>.stride
                    + 2 * MemoryLayout<String.UTF8View.Iterator>.stride
                    + MemoryLayout<UInt8>.stride))
            // Actual stored/result/scalar/iterator layouts and lowercase64
            // result payload operands. Allocator/crypto/VM internals are DUE.
        }
    }
    fileprivate struct Storage {
        let reservation: ColdEraseSchema2NamespaceCaptureReservationV1
        let capture: ColdEraseSchema2NamespaceCaptureOwnerV1
        let ranges: ColdEraseScratchPayloadRangesV1
        let owner: ColdEraseSchema2TerminalOwnerV1
        let basis: ColdEraseSchema2NamespacePreparationBasisV1
        let registry: GenerationLeaseRegistryV1
        let operation: EraseColdPreparationOperationV1
        let activity: GenerationTemporalActivityHandleV1
        let exclusion: EraseRetirementExclusionV1
        let binding: EraseRetirementBindingV1
        let witness: EraseSessionDrainWitnessV1
        let manifest: EraseSchema2ColdManifestOwnerV1
        let transfer: ColdEraseSchema2PostContentTransferReceiptV1
        let cut: ColdEraseScratchCapsuleControlCutV1
        let stateSHA256: String
        let progressOffset: UInt64
        let lastCompleteFrameSHA256: String?
        // NAMESPACE_READER_CURRENT_PREFIX_VERSION_V4_BEGIN
        var currentJournalOwnerV4: ColdEraseSchema2PostContentCurrentJournalOwnerV4?
        var readerOriginV4: ColdEraseSchema2ReaderNamespaceJournalOriginV4?
        var currentProgressProjectionV4: ColdEraseSchema2PostContentCurrentJournalOwnerV4.CurrentProgressProjection?
        // NAMESPACE_READER_CURRENT_PREFIX_VERSION_V4_END
        var phase: Phase = .profiling
        var profile: ColdEraseSchema2NamespaceCurrentSourceProfileV1?
        var profileCallbackEntered = false
        var profileCallbackReturned = false
        var profileHelperReturned = false
        var firstSnapshot: EraseSchema2ColdAuxiliaryFirstObserverV1.Snapshot?
        var afterSnapshot: EraseSchema2ColdAuxiliaryFirstObserverV1.Snapshot?
        var manifestBorrowEntered = false
        var manifestBorrowReturned = false
        var snapshotsBorrowEntered = false
        var snapshotsBorrowActive = false
        var snapshotsBorrowReturned = false
        var rows: UnsafeMutablePointer<ColdEraseSchema2NamespaceCurrentObservedNodeV1?>?
        var rowCapacity: Int = 0
        var rowInitialized: Int = 0
        var firstCount: UInt64 = 0
        var secondCount: UInt64 = 0
        var firstTokens: TokenSet?
        var secondTokens: TokenSet?
        var firstDigestHelperReturned = false
        var secondDigestHelperReturned = false
        var construction: Construction?
        var firstPathBytes: UInt64 = 0
        var secondPathBytes: UInt64 = 0
        var firstMemberBytes: UInt64 = 0
        var secondMemberBytes: UInt64 = 0
        var declaredConstructedRowBytes: UInt64 = 0
        var retainedBytes: UInt64 = 0
        var retainedExcessBytes: UInt64 = 0
        var failure: Error?
    }
    fileprivate var storage: Storage

    fileprivate static func fixedBackingBytes() throws -> UInt64 {
        // These are actual stored layouts and the closed profile/borrow value
        // cells, not a class-pointer mirror or an allocator/RSS measurement.
        try ColdEraseControlBinaryV1.adding(
            UInt64(MemoryLayout<Storage>.stride),
            ColdEraseSchema2NamespaceCurrentSourceProfileV1.requiredBackingBytes(),
            UInt64(MemoryLayout<Construction>.stride),
            UInt64(2 * MemoryLayout<EraseSchema2ColdAuxiliaryFirstObserverV1.Snapshot>.stride),
            UInt64(2 * MemoryLayout<stat>.stride), 3 * 64)
    }
    fileprivate init(reservation: ColdEraseSchema2NamespaceCaptureReservationV1,
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        ranges: ColdEraseScratchPayloadRangesV1, owner: ColdEraseSchema2TerminalOwnerV1,
        basis: ColdEraseSchema2NamespacePreparationBasisV1, registry: GenerationLeaseRegistryV1,
        operation: EraseColdPreparationOperationV1, activity: GenerationTemporalActivityHandleV1,
        exclusion: EraseRetirementExclusionV1, binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1, manifest: EraseSchema2ColdManifestOwnerV1,
        transfer: ColdEraseSchema2PostContentTransferReceiptV1,
        cut: ColdEraseScratchCapsuleControlCutV1, stateSHA256: String,
        progressOffset: UInt64, lastCompleteFrameSHA256: String?, chargedBytes: UInt64) {
        storage = Storage(reservation: reservation, capture: capture, ranges: ranges,
            owner: owner, basis: basis, registry: registry, operation: operation,
            activity: activity, exclusion: exclusion, binding: binding, witness: witness,
            manifest: manifest, transfer: transfer, cut: cut, stateSHA256: stateSHA256,
            progressOffset: progressOffset, lastCompleteFrameSHA256: lastCompleteFrameSHA256,
            retainedBytes: chargedBytes)
    }

    /// Memory only. Never calls Capture.requireBound, a G acquisition, PFP,
    /// the whole traversal, an old Scratch loan or any live frame callback.
    func requireAssociation(reservation: ColdEraseSchema2NamespaceCaptureReservationV1,
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        owner: ColdEraseSchema2TerminalOwnerV1,
        basis: ColdEraseSchema2NamespacePreparationBasisV1, registry: GenerationLeaseRegistryV1,
        operation: EraseColdPreparationOperationV1, activity: GenerationTemporalActivityHandleV1,
        exclusion: EraseRetirementExclusionV1, binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws {
        guard storage.phase != .uncertain, storage.failure == nil,
              storage.reservation === reservation, storage.capture === capture,
              storage.owner === owner, storage.basis === basis, storage.registry === registry,
              storage.operation === operation, storage.activity === activity,
              storage.exclusion === exclusion, storage.binding == binding,
              storage.witness === witness else { throw EraseIntentStoreError.invalidAuthority }
        try reservation.requireCurrentPrefixScopeAssociation(self, capture: capture)
        try capture.requireWholeCurrentScopeAssociation(self)
    }
    fileprivate func memoryFrame(capture: ColdEraseSchema2NamespaceCaptureOwnerV1) throws {
        try requireAssociation(reservation: storage.reservation, capture: capture,
            owner: storage.owner, basis: storage.basis, registry: storage.registry,
            operation: storage.operation, activity: storage.activity, exclusion: storage.exclusion,
            binding: storage.binding, witness: storage.witness)
    }
    func requireManifestOrigin(manifest: EraseSchema2ColdManifestOwnerV1,
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1) throws {
        try memoryFrame(capture: capture)
        guard storage.manifest === manifest else { throw EraseIntentStoreError.invalidAuthority }
        try storage.ranges.requireCurrentPrefixManifestOrigin(self, manifest: manifest)
    }
    func withManifestForProfile(capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        _ body: (EraseSchema2ColdManifestOwnerV1) throws -> Void) throws {
        do {
            try memoryFrame(capture: capture)
            guard storage.phase == .profiling, !storage.manifestBorrowEntered else {
                throw EraseIntentStoreError.invalidAuthority
            }
            storage.manifestBorrowEntered = true
            try requireManifestOrigin(manifest: storage.manifest, capture: capture)
            try Self.invokeManifest(storage.manifest, body)
            storage.manifestBorrowReturned = true
            try requireManifestOrigin(manifest: storage.manifest, capture: capture)
        } catch { fail(error); throw error }
    }
    private static func invokeManifest(_ value: EraseSchema2ColdManifestOwnerV1,
        _ body: (EraseSchema2ColdManifestOwnerV1) throws -> Void) throws { try body(value) }
    func withManifestSnapshots(manifest: EraseSchema2ColdManifestOwnerV1,
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        _ body: (EraseSchema2ColdAuxiliaryFirstObserverV1.Snapshot,
                 EraseSchema2ColdAuxiliaryFirstObserverV1.Snapshot) throws -> Void) throws {
        do {
            try requireManifestOrigin(manifest: manifest, capture: capture)
            guard !storage.snapshotsBorrowActive else { throw EraseIntentStoreError.invalidAuthority }
            storage.snapshotsBorrowActive = true // no nested borrow, even if its error is caught
            storage.snapshotsBorrowEntered = true
            try storage.ranges.retainCurrentPrefixSnapshots(self, manifest: manifest)
            guard let first = storage.firstSnapshot, let after = storage.afterSnapshot else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try Self.invokeSnapshots(first, after, body)
            storage.snapshotsBorrowReturned = true
            try requireManifestOrigin(manifest: manifest, capture: capture)
            storage.snapshotsBorrowActive = false // real private Void return + same origin proof
        } catch { fail(error); throw error }
    }
    private static func invokeSnapshots(_ first: EraseSchema2ColdAuxiliaryFirstObserverV1.Snapshot,
        _ after: EraseSchema2ColdAuxiliaryFirstObserverV1.Snapshot,
        _ body: (EraseSchema2ColdAuxiliaryFirstObserverV1.Snapshot,
                 EraseSchema2ColdAuxiliaryFirstObserverV1.Snapshot) throws -> Void) throws {
        try body(first, after)
    }

    /// Separate live fence. The transferred control observer reads only its
    /// own retained controls/parents; Target's checker is memory-only. There
    /// is no nested Registry G or recursive whole/PFP observation.
    func requireCurrentBinding(capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        heldG: Bool) throws {
        do {
            try memoryFrame(capture: capture)
            guard storage.phase != .profiling, storage.profileHelperReturned,
                  storage.profileCallbackEntered, storage.profileCallbackReturned,
                  storage.rowCapacity > 0, storage.rowInitialized == storage.rowCapacity,
                  storage.rows != nil else { throw EraseIntentStoreError.invalidAuthority }
            try capture.requireWholeCurrentContextAssociation(scope: self, heldG: heldG)
            try storage.ranges.withTransferredCurrentPrefixFence(self, heldG: heldG) {
                try storage.ranges.requireCurrentPrefixLiveFrame(self)
            }
            try capture.requireWholeCurrentContextAssociation(scope: self, heldG: heldG)
        } catch { fail(error); throw error }
    }
    fileprivate func prepareProfile() throws {
        do {
            try memoryFrame(capture: storage.capture)
            guard storage.phase == .profiling, storage.profile == nil,
                  !storage.profileCallbackEntered, !storage.profileHelperReturned else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try storage.capture.withWholeCurrentSourceProfile(scope: self) { actual in
                guard !self.storage.profileCallbackEntered else { throw EraseIntentStoreError.invalidAuthority }
                self.storage.profileCallbackEntered = true
                self.storage.profile = actual // SAME privately produced source profile BEFORE proof/capacity
                try actual.requireAssociation(scope: self, capture: self.storage.capture)
                self.storage.profileCallbackReturned = true
            }
            storage.profileHelperReturned = true // actual synchronous Target helper returned
            guard let profile = storage.profile, profile.maximumNodeCount > 0,
                  profile.maximumNodeCount <= UInt64(Int.max / 2),
                  storage.profileCallbackEntered, storage.profileCallbackReturned,
                  storage.manifestBorrowEntered, storage.manifestBorrowReturned,
                  storage.snapshotsBorrowEntered, storage.snapshotsBorrowReturned else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try profile.requireAssociation(scope: self, capture: storage.capture)
            let slots = try ColdEraseControlBinaryV1.multiplying(profile.maximumNodeCount, 2)
            let bytes = try ColdEraseControlBinaryV1.adding(profile.declaredTargetBackingBytes,
                ColdEraseControlBinaryV1.multiplying(slots,
                    UInt64(MemoryLayout<ColdEraseSchema2NamespaceCurrentObservedNodeV1?>.stride)),
                ColdEraseControlBinaryV1.multiplying(slots, UInt64(MemoryLayout<UInt64>.stride)),
                ColdEraseControlBinaryV1.multiplying(2, TokenSet.requiredFixedBackingBytes()))
            try storage.ranges.reserveCurrentPrefixBacking(self, bytes: bytes)
            guard let capacity = Int(exactly: slots) else { throw EraseIntentStoreError.invalidAuthority }
            storage.rowCapacity = capacity
            storage.rows = .allocate(capacity: capacity) // retained BEFORE initialization/postproof
            guard let rows = storage.rows else { throw EraseIntentStoreError.invalidAuthority }
            rows.initialize(repeating: nil, count: capacity)
            storage.rowInitialized = capacity
            try memoryFrame(capture: storage.capture)
            storage.phase = .ready // limits/initialized ownership only; no node/policy/current result
        } catch { fail(error); throw error }
    }

    /// Pure SAME-profile preallocation check for Target's real constructors.
    /// The first actual Context does not yet exist. This grants no G, policy,
    /// IO or role and calls no live Range/current-frame observer.
    func requirePreparedTargetBacking(capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        profile: ColdEraseSchema2NamespaceCurrentSourceProfileV1) throws {
        do {
            try memoryFrame(capture: capture)
            guard storage.profile === profile, storage.profileHelperReturned,
                  storage.profileCallbackEntered, storage.profileCallbackReturned,
                  storage.phase == .ready || storage.phase == .first
                    || storage.phase == .between || storage.phase == .second,
                  storage.rowCapacity > 0, storage.rowInitialized == storage.rowCapacity,
                  storage.rows != nil else { throw EraseIntentStoreError.invalidAuthority }
            try profile.requireAssociation(scope: self, capture: capture)
        } catch { fail(error); throw error }
    }

    func requireObservedNodeConstructionCapacity(capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        pass: UInt8, ordinal: UInt64, pathUTF8Count: UInt64, memberUTF8Count: UInt64) throws {
        do {
            try requireCurrentBinding(capture: capture, heldG: true)
            guard let profile = storage.profile, pass < 2, storage.construction == nil,
                  ordinal < profile.maximumNodeCount,
                  (pass == 0 && (storage.phase == .ready || storage.phase == .first) && ordinal == storage.firstCount)
                    || (pass == 1 && (storage.phase == .between || storage.phase == .second) && ordinal == storage.secondCount),
                  pathUTF8Count <= profile.maximumPathUTF8Count,
                  memberUTF8Count <= profile.maximumMemberUTF8Count else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let priorPaths = pass == 0 ? storage.firstPathBytes : storage.secondPathBytes
            let priorMembers = pass == 0 ? storage.firstMemberBytes : storage.secondMemberBytes
            let paths = try ColdEraseControlBinaryV1.adding(priorPaths, pathUTF8Count)
            let members = try ColdEraseControlBinaryV1.adding(priorMembers, memberUTF8Count)
            let maximumPaths = try ColdEraseControlBinaryV1.multiplying(
                profile.maximumNodeCount, profile.maximumPathUTF8Count)
            guard paths <= maximumPaths, members <= profile.maximumMemberUTF8Count else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let declared = try ColdEraseSchema2NamespaceCurrentObservedNodeV1.requiredBackingBytes(
                pathUTF8Count: pathUTF8Count, memberUTF8Count: memberUTF8Count)
            let total = try ColdEraseControlBinaryV1.adding(storage.declaredConstructedRowBytes, declared)
            guard total <= profile.declaredTargetBackingBytes else { throw EraseIntentStoreError.invalidAuthority }
            storage.construction = Construction(pass: pass, ordinal: ordinal,
                pathBytes: pathUTF8Count, memberBytes: memberUTF8Count, declaredBytes: declared)
            storage.declaredConstructedRowBytes = total // prepaid actual Target profile, no new caller grant
            if pass == 0 { storage.phase = .first; storage.firstPathBytes = paths; storage.firstMemberBytes = members }
            else { storage.phase = .second; storage.secondPathBytes = paths; storage.secondMemberBytes = members }
            try requireCurrentBinding(capture: capture, heldG: true)
        } catch { fail(error); throw error }
    }

    func recordObservedNode(_ actual: ColdEraseSchema2NamespaceCurrentObservedNodeV1,
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1) throws {
        do {
            guard let profile = storage.profile, let request = storage.construction,
                  let rows = storage.rows else { throw EraseIntentStoreError.invalidAuthority }
            let offset = try ColdEraseControlBinaryV1.adding(
                ColdEraseControlBinaryV1.multiplying(UInt64(request.pass), profile.maximumNodeCount), request.ordinal)
            guard let slot = Int(exactly: offset), slot < storage.rowInitialized, rows[slot] == nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
            rows[slot] = actual // retain SAME issued row BEFORE all fallible getters/source/current proofs
            try memoryFrame(capture: capture) // actual supplied Capture before getters/excess-capacity IO
            guard request.pass == actual.pass, request.ordinal == actual.ordinal else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let actualBytes = try actual.actualBackingBytes()
            if actualBytes > request.declaredBytes {
                let excess = actualBytes - request.declaredBytes
                storage.retainedExcessBytes = try ColdEraseControlBinaryV1.adding(storage.retainedExcessBytes, excess)
                try storage.ranges.reserveCurrentPrefixBacking(self, bytes: excess)
                throw EraseIntentStoreError.invalidAuthority // excess remains retained/charged even if capacity refuses
            }
            try actual.requireAssociation(scope: self, capture: capture, pass: request.pass, ordinal: request.ordinal)
            try actual.requireCheckedResourceReturn(scope: self, capture: capture)
            guard UInt64(actual.path.utf8.count) == request.pathBytes else { throw EraseIntentStoreError.invalidAuthority }
            var actualMembers: UInt64 = 0
            if let names = actual.members {
                for name in names { actualMembers = try ColdEraseControlBinaryV1.adding(actualMembers, UInt64(name.utf8.count)) }
            }
            guard actualMembers == request.memberBytes else { throw EraseIntentStoreError.invalidAuthority }
            try requireCurrentBinding(capture: capture, heldG: true)
            try capture.requireWholeCurrentObservedNodeOrigin(actual, scope: self)
            if request.pass == 1 {
                guard let first = rows[Int(request.ordinal)], Self.same(first, actual) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            if request.pass == 0 { storage.firstCount += 1 } else { storage.secondCount += 1 }
            storage.construction = nil // actual proof/capacity/close consumer returned; metadata stays charged
            try requireCurrentBinding(capture: capture, heldG: true)
        } catch { fail(error); throw error }
    }
    private static func same(_ left: ColdEraseSchema2NamespaceCurrentObservedNodeV1,
        _ right: ColdEraseSchema2NamespaceCurrentObservedNodeV1) -> Bool {
        let a = left.information, b = right.information
        guard left.path.utf8.elementsEqual(right.path.utf8),
              a.st_dev == b.st_dev, a.st_ino == b.st_ino, a.st_mode == b.st_mode,
              a.st_uid == b.st_uid, a.st_gid == b.st_gid, a.st_nlink == b.st_nlink,
              a.st_size == b.st_size, a.st_mtimespec.tv_sec == b.st_mtimespec.tv_sec,
