    private static func appendCanonicalByte(_ value: UInt8, into set: TokenSet) {
        let offset = set.storage.pendingByteCount
        withUnsafeMutableBytes(of: &set.storage.pendingBytes) { $0[offset] = value }
        set.storage.pendingByteCount += 1
