    private static func appendCanonicalSigned(_ value: Int64, into set: TokenSet) {
        if value < 0 {
            appendCanonicalByte(45, into: set)
            appendCanonicalUnsigned(0 &- UInt64(bitPattern: value), into: set)
        } else { appendCanonicalUnsigned(UInt64(value), into: set) }
    }
    private static func appendCanonicalHex<C: Collection>(_ bytes: C, into set: TokenSet) where C.Element == UInt8 {
        for byte in bytes {
            let high = byte >> 4, low = byte & 15
            appendCanonicalByte(high < 10 ? high + 48 : high + 87, into: set)
            appendCanonicalByte(low < 10 ? low + 48 : low + 87, into: set)
