        appendCanonicalHex(row.path.utf8, into: set); appendCanonicalByte(124, into: set)
        appendCanonicalSigned(Int64(fact.st_dev), into: set); appendCanonicalByte(124, into: set)
        appendCanonicalUnsigned(UInt64(fact.st_ino), into: set); appendCanonicalByte(124, into: set)
        appendCanonicalUnsigned(UInt64(fact.st_mode), into: set); appendCanonicalByte(124, into: set)
        appendCanonicalUnsigned(UInt64(fact.st_nlink), into: set); appendCanonicalByte(124, into: set)
        appendCanonicalSigned(Int64(fact.st_size), into: set); appendCanonicalByte(124, into: set)
        appendCanonicalSigned(Int64(fact.st_mtimespec.tv_sec), into: set); appendCanonicalByte(124, into: set)
        appendCanonicalSigned(Int64(fact.st_mtimespec.tv_nsec), into: set); appendCanonicalByte(124, into: set)
        appendCanonicalSigned(Int64(fact.st_ctimespec.tv_sec), into: set); appendCanonicalByte(124, into: set)
        appendCanonicalSigned(Int64(fact.st_ctimespec.tv_nsec), into: set); appendCanonicalByte(124, into: set)
        if let members = row.members {
            for index in members.indices {
                if index != members.startIndex { appendCanonicalByte(44, into: set) }
