        try extra(metadata.facts.capacity, 128, MemoryLayout<[UInt64]>.stride)
        for fact in metadata.facts { try extra(fact.capacity, 22, MemoryLayout<UInt64>.stride) }
        try extra(metadata.digests.capacity, 128, MemoryLayout<Data>.stride)
        try extra(metadata.identifiers.capacity, 32, MemoryLayout<Data>.stride)
        try extra(metadata.words.capacity, 128, MemoryLayout<UInt64>.stride)
