    private func compareCoreChunk(offset: UInt64, count: Int, hasher: inout SHA256) throws {
        guard storage.coreReadActive, storage.coreReadChunk == nil else { throw EraseIntentStoreError.invalidAuthority }
        let bytes = try storage.resource.readExactly(offset: offset, count: count)
