        guard bytes.count == count else { throw EraseIntentStoreError.invalidAuthority }
        try requireMemoryAssociation(); try storage.resource.requirePinned()
        bytes.withUnsafeBytes { hasher.update(bufferPointer: $0) }
        try storage.resource.requirePinned(); try requireMemoryAssociation()
        storage.coreReadChunk = nil // only after this actual consumer; lexical alias ends on Void return
    }
    fileprivate func requireProgressCoreBytesCurrent() throws {
        do {
            guard storage.state == .preparedHeader, storage.progressConstructionEntered,
                  storage.progressPublisher != nil, !storage.coreReadActive, storage.coreReadChunk == nil else {
                throw EraseIntentStoreError.invalidAuthority
