            try requireMemoryAssociation(); try storage.resource.requirePinned()
            guard storage.resource.byteCount == storage.coreByteCount else { throw EraseIntentStoreError.invalidAuthority }
            var hasher = SHA256(), offset: UInt64 = 0
            while offset < storage.coreByteCount {
                let count = Int(min(UInt64(65_536), storage.coreByteCount - offset))
                try compareCoreChunk(offset: offset, count: count, hasher: &hasher)
                offset = try ColdEraseControlBinaryV1.adding(offset, UInt64(count))
            }
