            guard try ColdEraseScratchCapsuleContinuationWriterV1.sha256String(hasher) == storage.coreSHA256,
                  storage.coreReadChunk == nil else { throw EraseIntentStoreError.invalidAuthority }
            try requireMemoryAssociation()
            storage.coreReadActive = false
        } catch { poison(); throw error }
    }
    private func poison() {
        storage.state = .uncertain; storage.writer.poison()
        // No retained receipt/preparation/source/raw alias is discarded.
    }
}

/// The actual emitted 64-byte V3 header is copied into one registered buffer
/// BEFORE a second temp create can alter the parent. This class performs no
/// IO and exposes no raw backing or later pointer. A genuine second publisher
/// still owes its separately entered create/current-parent/write/policy frame.
@MainActor fileprivate final class ColdEraseScratchProgressBirthPreparationV1 {
    private enum State { case empty, preparing, prepared, uncertain }
    private struct Storage {
        let receipt: ColdEraseScratchContinuationPublicationReceiptV1
        let source: ColdEraseScratchProgressBirthSourceV1
        var state = State.empty
        var headerSHA256: String?
        var copyEntered = false
        var copyReturned = false
        var progressWriter: ColdEraseScratchCapsuleContinuationWriterV1?
        var writerBorrowEntered = false
        var writerBorrowReturned = false
        var activeWriterBorrow: UnsafeRawBufferPointer?
    }
    private var storage: Storage
    // Direct stored Data retains the registered mutable backing while the
    // copy closure borrows it. No aggregate accessor/COW or owner reentry.
    private var headerBuffer: Data?
    fileprivate static var declaredBackingBytes: UInt64 {
        UInt64(4 * MemoryLayout<Storage>.stride + MemoryLayout<Data?>.stride
            + 6 * MemoryLayout<Data>.stride + 4 * MemoryLayout<String>.stride
            + 4 * MemoryLayout<UnsafeRawBufferPointer>.stride
            + 2 * MemoryLayout<UnsafeMutableRawBufferPointer>.stride
            + 2 * MemoryLayout<SHA256>.stride + 6 * 64)
        // One 64B output plus explicit source/reencode/COW lexical overlap;
        // runtime/Framework internals, allocator/headers/VM remain unmeasured.
    }
    fileprivate init(receipt: ColdEraseScratchContinuationPublicationReceiptV1,
        source: ColdEraseScratchProgressBirthSourceV1) {
        storage = .init(receipt: receipt, source: source)
    }
    fileprivate func prepareHeader() throws {
        do {
            guard storage.state == .empty, headerBuffer == nil,
                  storage.headerSHA256 == nil, !storage.copyEntered, !storage.copyReturned else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try storage.receipt.requireHeaderPreparationAssociation(self)
            try storage.receipt.requireCurrentBeforeProgressCreate()
            storage.state = .preparing
            headerBuffer = Data(count: 64) // profile reserved before THIS constructor
            try storage.source.withEncodedProgressHeader { bytes in
                guard storage.state == .preparing, bytes.count == 64,
                      headerBuffer?.count == 64, !storage.copyEntered,
                      !storage.copyReturned else { throw EraseIntentStoreError.invalidAuthority }
                try storage.source.requireActiveHeaderBorrow(bytes)
                storage.copyEntered = true // before the actual lexical pointer copy
                headerBuffer!.withUnsafeMutableBytes { destination in
                    destination.copyMemory(from: bytes) // synchronous Void, no callback/owner mutation
                }
                storage.copyReturned = true // actual copy returned, not a syscall/effect result
                try storage.source.requireActiveHeaderBorrow(bytes)
                try storage.receipt.requireHeaderPreparationAssociation(self)
            }
            guard storage.copyEntered, storage.copyReturned, let headerBuffer,
                  headerBuffer.count == 64 else { throw EraseIntentStoreError.invalidAuthority }
            try storage.source.requireEmittedHeaderMemoryAssociation(headerBuffer)
            storage.headerSHA256 = StoreMigrationCanonicalJSONV1.sha256(headerBuffer)
            try storage.receipt.requireCurrentBeforeProgressCreate()
            storage.state = .prepared
        } catch {
            storage.state = .uncertain
            // Retain exact output/source/receipt and its lexical copy state.
            // The receipt's maker catches and poisons the genuine writer.
            throw error
        }
    }
    fileprivate var receipt: ColdEraseScratchContinuationPublicationReceiptV1 { storage.receipt }
    fileprivate func requirePreparedHeaderMemoryAssociation(
        receipt: ColdEraseScratchContinuationPublicationReceiptV1) throws {
        guard storage.receipt === receipt, storage.state == .prepared,
              storage.copyEntered, storage.copyReturned,
              let headerBuffer, headerBuffer.count == 64,
              let hash = storage.headerSHA256,
              StoreMigrationCanonicalJSONV1.sha256(headerBuffer) == hash else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try receipt.requireHeaderPreparationAssociation(self)
        try storage.source.requireEmittedHeaderMemoryAssociation(headerBuffer)
        // No current first-parent/zero Scope rearm after the eventual create.
        // DATA equality does not produce that unissued second-parent frame.
    }
    fileprivate func bindProgressWriter(_ writer: ColdEraseScratchCapsuleContinuationWriterV1) throws {
        guard storage.progressWriter == nil, !storage.writerBorrowEntered,
              !storage.writerBorrowReturned, storage.activeWriterBorrow == nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        storage.progressWriter = writer // BEFORE association callback; never overwrite
        try writer.requireProgressInputMemoryAssociation(preparation: self)
    }
    fileprivate func requireActiveProgressWriterBorrow(_ bytes: UnsafeRawBufferPointer,
        writer: ColdEraseScratchCapsuleContinuationWriterV1) throws {
        guard storage.progressWriter === writer, storage.writerBorrowEntered, !storage.writerBorrowReturned,
              let actual = storage.activeWriterBorrow, actual.baseAddress == bytes.baseAddress,
              actual.count == bytes.count, bytes.count == 64 else { throw EraseIntentStoreError.invalidAuthority }
        try requirePreparedHeaderMemoryAssociation(receipt: storage.receipt)
        // Memory comparison only. Writer's independent boundary owns current
        // parent/core/prefix/resource proof; no old Source current reentry.
    }
    fileprivate func withPreparedProgressWriterBytes(writer: ColdEraseScratchCapsuleContinuationWriterV1,
        _ body: (UnsafeRawBufferPointer) throws -> Void) throws {
        do {
            guard storage.progressWriter === writer, !storage.writerBorrowEntered,
                  !storage.writerBorrowReturned, storage.activeWriterBorrow == nil,
                  let headerBuffer, headerBuffer.count == 64 else { throw EraseIntentStoreError.invalidAuthority }
            storage.writerBorrowEntered = true // once-entry BEFORE any delegated proof
            try writer.requireProgressInputMemoryAssociation(preparation: self)
            try headerBuffer.withUnsafeBytes { bytes in
                storage.activeWriterBorrow = bytes // BEFORE the genuine synchronous Void writer
                try body(bytes)
                try requireActiveProgressWriterBorrow(bytes, writer: writer)
                storage.activeWriterBorrow = nil // only after actual callback return/proof
            }
            try writer.requireProgressInputMemoryAssociation(preparation: self)
            storage.writerBorrowReturned = true
        } catch { storage.state = .uncertain; writer.poison(); throw error }
    }
    fileprivate func requireReturnedProgressWriterBorrow(writer: ColdEraseScratchCapsuleContinuationWriterV1) throws -> String {
        guard storage.progressWriter === writer, storage.writerBorrowEntered,
              storage.writerBorrowReturned, storage.activeWriterBorrow == nil,
              let hash = storage.headerSHA256 else { throw EraseIntentStoreError.invalidAuthority }
        try requirePreparedHeaderMemoryAssociation(receipt: storage.receipt)
        return hash
    }
    fileprivate func requireCanonicalProgressHeaderBytes(_ bytes: Data,
        writer: ColdEraseScratchCapsuleContinuationWriterV1) throws {
        guard bytes.count == 64, let headerBuffer, bytes == headerBuffer,
              StoreMigrationCanonicalJSONV1.sha256(bytes) == (try requireReturnedProgressWriterBorrow(writer: writer)) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try storage.source.requireEmittedHeaderMemoryAssociation(bytes)
        // The genuine Source already decoded the exact V3 header against the
        // same core32. Equality here never mints a new header or restart owner.
    }

}

/// Real first-current-process role2 settlement, issued only after this
/// writer's entered/result0 sync/close/rename/parent-sync/canonical policy,
/// opened replacement resource, actual pin-close and full64/SHA/EOF readback.
/// It neither installs catalog/progress nor admits Seed, Attempt or REQUEST.
@MainActor fileprivate final class ColdEraseScratchProgressPublicationReceiptV1 {
    private struct Storage {
        let writer: ColdEraseScratchCapsuleContinuationWriterV1
        let resource: ColdEraseRetainedControlFileV1
        let preparation: ColdEraseScratchProgressBirthPreparationV1
        let operationID: UUID
        let canonicalFile: EraseColdControlLeafFactV1
        let sha256: String
        let context: ColdEraseScratchCapsulePublisherV1.Context
    }
    private let storage: Storage
    fileprivate static var declaredBackingBytes: UInt64 {
        UInt64(4 * MemoryLayout<Storage>.stride
            + 4 * MemoryLayout<ColdEraseScratchCapsulePublisherV1.Context>.stride
            + 4 * MemoryLayout<EraseColdControlLeafFactV1>.stride
            + 4 * MemoryLayout<[String]>.stride + 4 * 8 * MemoryLayout<String>.stride
            + 4 * MemoryLayout<String>.stride + 4 * 64)
    }
    fileprivate init(writer: ColdEraseScratchCapsuleContinuationWriterV1,
        resource: ColdEraseRetainedControlFileV1, preparation: ColdEraseScratchProgressBirthPreparationV1,
        operationID: UUID, canonicalFile: EraseColdControlLeafFactV1, sha256: String,
        context: ColdEraseScratchCapsulePublisherV1.Context) {
        storage = .init(writer: writer, resource: resource, preparation: preparation,
            operationID: operationID, canonicalFile: canonicalFile, sha256: sha256, context: context)
    }
    fileprivate func requireMemoryAssociation() throws {
        try storage.writer.requireProgressReceiptMemoryAssociation(self,
            resource: storage.resource, preparation: storage.preparation,
            operationID: storage.operationID, canonicalFile: storage.canonicalFile,
            sha256: storage.sha256, context: storage.context)
    }
    fileprivate func requireCurrentPublication() throws {
        try requireMemoryAssociation()
        try storage.writer.requireProgressReceiptCurrent(self, resource: storage.resource)
        try requireMemoryAssociation()
    }
}

@MainActor fileprivate final class ColdEraseScratchCapsulePublisherV1 {
    fileprivate struct Context {
        let support: Int32, erase: Int32
        let eraseURL: URL
        let firstSupport: EraseColdControlLeafFactV1
        let firstRoot: EraseColdControlLeafFactV1
        let firstNames: [String]
    }
    private enum State: Equatable { case registered, creating, zero, policyConsumed, uncertain }
    private enum Kind: Equatable { case create, supportHeld, supportNamed, rootHeld,
        rootNamed, leafHeld, leafNamed, absentCanonical, emptyRead }
    private final class Entry {
        struct Storage {
            let kind: Kind
