        let finalFullFact: String
    }
    private struct CanonicalRename {
        let parent: Int32
        let temporaryName: String
        let canonicalName: String
        let flags: UInt32
        let readDescriptor: Int32
        let beforeFile: EraseColdControlLeafFactV1
        let beforeRoot: EraseColdControlLeafFactV1
        let byteCount: UInt64
        let sha256: String
        let temporaryNameIndex: Int
        var result: Int32?
        var savedErrno: Int32?
        var heldFile: EraseColdControlLeafFactV1?
        var namedFile: EraseColdControlLeafFactV1?
        var afterRoot: EraseColdControlLeafFactV1?
        var absenceResult: Int32?
        var absenceErrno: Int32?
        var oldNameAbsenceChecked = false
        var projected = false
        var checked = false
    }
    private enum RenameStatKind { case heldFile, namedFile, absentTemporary }
    private struct RenameStatRequest {
        let kind: RenameStatKind
        let descriptor: Int32
        let name: String?
        var result: Int32?
        var savedErrno: Int32?
        var returned = stat()
    }
    private struct CanonicalParentSynchronization {
        let descriptor: Int32
        let beforeRoot: EraseColdControlLeafFactV1
        let canonicalFile: EraseColdControlLeafFactV1
        let readDescriptor: Int32
        let byteCount: UInt64
        let sha256: String
        var result: Int32?
        var savedErrno: Int32?
        var afterRoot: EraseColdControlLeafFactV1?
        var checked = false
    }
    private struct Storage {
        let ranges: ColdEraseScratchPayloadRangesV1
        let context: Context
        let operationID: UUID
        let kind: ColdEraseScratchCapsulePublicationKindV1
        var state = State.registered
        var descriptor: Int32 = -1
        var root: EraseColdControlLeafFactV1
        var temporary: EraseColdControlLeafFactV1?
        var active: Entry?
        var lastConsumed: Entry?
        var create: Entry?
        var scope: ColdEraseScratchCapsulePublicationPolicyScopeV1?
        var attempt: ColdEraseScratchCapsulePublicationPolicyAttemptV1?
        var node: ColdEraseScratchCapsulePublicationPolicyNodeV1?
        var policyConsumed = false
        var zeroPolicyBefore: EraseColdControlLeafFactV1?
        var zeroPolicyOrigin: ZeroPolicyOrigin?
        var nodeChargeBytes: UInt64 = 0
        var policyChargeBytes: UInt64 = 0
        var unexpectedNameBackingBytes: UInt64 = 0
        var continuationWriter: ColdEraseScratchCapsuleContinuationWriterV1?
        var writerChargeBytes: UInt64 = 0
        var canonicalRename: CanonicalRename?
        var activeRenameStat: RenameStatRequest?
        var consumedRenameStat: RenameStatRequest?
        var canonicalParentSynchronization: CanonicalParentSynchronization?
        var canonicalOrigin: ColdEraseScratchCapsuleCanonicalPublicationOriginV1?
        var canonicalNode: ColdEraseScratchCapsuleCanonicalPolicyNodeV1?
        var canonicalScope: ColdEraseScratchCapsuleCanonicalPolicyScopeV1?
        var canonicalPolicyChargeBytes: UInt64 = 0
        var unexpectedCanonicalNodeBackingBytes: UInt64 = 0
        var canonicalPolicyConsumed = false
        var canonicalInfrastructure: ColdEraseRetainedControlFileV1?
        let firstContinuationReceipt: ColdEraseScratchContinuationPublicationReceiptV1?
        let progressPreparation: ColdEraseScratchProgressBirthPreparationV1?
        var progressWriterEntered = false
        var currentCoreOrigin: ColdEraseScratchProgressCurrentCorePublicationOriginV1?
        var currentCoreNode: ColdEraseScratchProgressCurrentCorePolicyNodeV1?
        var currentCoreScope: ColdEraseScratchProgressCurrentCorePolicyScopeV1?
        var currentCoreBoundaryEntered = false
        var currentCoreBodyReturned = false
        var currentCorePolicyConsumed = false
        var currentCoreChargeBytes: UInt64 = 0
        var unexpectedCurrentCoreNodeBackingBytes: UInt64 = 0
    }
    private var storage: Storage
    let operationID: UUID
    let kind: ColdEraseScratchCapsulePublicationKindV1
    let eraseURL: URL
    let temporaryURL: URL
    private var projectedNames: [String] = []
    fileprivate init(ranges: ColdEraseScratchPayloadRangesV1, context: Context,
        operationID: UUID) {
        // Only the first live continuation producer exists here. Progress
        // construction needs its genuine completed continuation receipt.
        let publicationKind = ColdEraseScratchCapsulePublicationKindV1.continuation
        kind = publicationKind; self.operationID = operationID
        eraseURL = context.eraseURL
        temporaryURL = context.eraseURL.appendingPathComponent(publicationKind.temporaryName)
        storage = .init(ranges: ranges, context: context, operationID: operationID,
            kind: publicationKind, root: context.firstRoot,
            firstContinuationReceipt: nil, progressPreparation: nil)
    }
    fileprivate init(ranges: ColdEraseScratchPayloadRangesV1, context: Context, operationID: UUID,
        receipt: ColdEraseScratchContinuationPublicationReceiptV1,
        preparation: ColdEraseScratchProgressBirthPreparationV1) {
        let publicationKind = ColdEraseScratchCapsulePublicationKindV1.progress
        kind = publicationKind; self.operationID = operationID
        eraseURL = context.eraseURL
        temporaryURL = context.eraseURL.appendingPathComponent(publicationKind.temporaryName)
        storage = .init(ranges: ranges, context: context, operationID: operationID,
            kind: .progress, root: context.firstRoot,
            firstContinuationReceipt: receipt, progressPreparation: preparation)
    }
    fileprivate func requireProgressConstructionOperandAssociation(
        receipt: ColdEraseScratchContinuationPublicationReceiptV1,
        preparation: ColdEraseScratchProgressBirthPreparationV1) throws {
        guard storage.firstContinuationReceipt === receipt, storage.progressPreparation === preparation,
              kind == .progress else { throw EraseIntentStoreError.invalidAuthority }
    }
    fileprivate func requireProgressOriginMemoryAssociation() throws {
        guard kind == .progress, let receipt = storage.firstContinuationReceipt,
              let preparation = storage.progressPreparation else { throw EraseIntentStoreError.invalidAuthority }
        try receipt.requireProgressPublisherMemoryAssociation(self,
            preparation: preparation, context: storage.context)
    }
    fileprivate func requireConstructionLayout() throws {
        let context = storage.context
        guard context.support >= 0, context.erase >= 0,
              operationID != SettingsValidationV1.zeroUUID,
              context.firstNames.count == (kind == .continuation ? 4 : 5), projectedNames.isEmpty,
              !context.firstNames.contains(kind.canonicalName),
              !context.firstNames.contains(kind.temporaryName),
              eraseURL.isFileURL, eraseURL.standardizedFileURL == eraseURL,
              eraseURL.path.utf8.count <= 16_640, temporaryURL.path.utf8.count <= 16_640 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        if kind == .progress { try requireProgressOriginMemoryAssociation() }
        // The Range retains/charges this exact publisher BEFORE reserve.
        // One array, no concatenation or sorted output allocation. Every slot
        // append is inside the actual observed capacity, and the tiny ordered
        // name vector is sorted with one scalar String reference temporary.
        projectedNames.reserveCapacity(8)
        guard projectedNames.capacity == 8 else {
            storage.unexpectedNameBackingBytes = try ColdEraseControlBinaryV1.multiplying(
                UInt64(projectedNames.capacity), UInt64(MemoryLayout<String>.stride))
            throw EraseIntentStoreError.invalidAuthority
        }
        for name in context.firstNames {
            guard projectedNames.count < projectedNames.capacity, name.utf8.count <= 255 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            projectedNames.append(name)
        }
        guard projectedNames.count < projectedNames.capacity else { throw EraseIntentStoreError.invalidAuthority }
        projectedNames.append(kind.temporaryName)
        for i in 1..<projectedNames.count {
            let value = projectedNames[i]
            var position = i
            while position > 0 && value.utf8.lexicographicallyPrecedes(projectedNames[position - 1].utf8) {
                projectedNames[position] = projectedNames[position - 1]
                position -= 1
            }
            projectedNames[position] = value
        }
        guard projectedNames.count == (kind == .continuation ? 5 : 6), projectedNames.capacity == 8,
