    private func captureCanonicalRenameStat(_ kind: RenameStatKind) throws -> EraseColdControlLeafFactV1? {
        try frame()
        guard storage.activeRenameStat == nil, let rename = storage.canonicalRename,
              rename.result == 0, rename.savedErrno != nil,
              rename.parent == storage.context.erase, rename.parent >= 0,
              rename.readDescriptor >= 0 else { throw EraseIntentStoreError.invalidAuthority }
        let descriptor: Int32
        if kind == .heldFile {
            guard let writer = storage.continuationWriter else { throw EraseIntentStoreError.invalidAuthority }
            descriptor = try writer.canonicalPhysicalReadDescriptor(historicalReadDescriptor: rename.readDescriptor)
        } else { descriptor = rename.parent }
        let name: String? = kind == .heldFile ? nil :
            (kind == .namedFile ? rename.canonicalName : rename.temporaryName)
        storage.activeRenameStat = .init(kind: kind, descriptor: descriptor, name: name)
        var value = stat()
        let result: Int32
        if kind == .heldFile { result = Darwin.fstat(descriptor, &value) }
        else { result = Darwin.fstatat(descriptor, name!, &value, AT_SYMLINK_NOFOLLOW) }
        let saved = errno
        storage.activeRenameStat!.result = result
        storage.activeRenameStat!.savedErrno = saved
        storage.activeRenameStat!.returned = value // actual result/stat BEFORE postproof
        if kind == .absentTemporary {
            guard result == -1, saved == ENOENT else { throw EraseIntentStoreError.invalidAuthority }
        } else {
            guard result == 0 else { throw EraseIntentStoreError.invalidAuthority }
        }
        try frame()
        guard let request = storage.activeRenameStat, request.kind == kind,
              request.descriptor == descriptor, request.name == name,
              request.result == result, request.savedErrno == saved else {
            throw EraseIntentStoreError.invalidAuthority
        }
        storage.consumedRenameStat = request; storage.activeRenameStat = nil
        if kind == .absentTemporary { return nil }
        return EraseColdControlLeafFactV1(request.returned)
    }
    fileprivate func requireWriterCanonicalReadPinMetadata(_ writer: ColdEraseScratchCapsuleContinuationWriterV1) throws {
        try frame(); try requireCanonicalRenameMemoryAssociation(writer)
