        let held = try captureCanonicalRenameStat(.heldFile)
        let named = try captureCanonicalRenameStat(.namedFile)
        guard held == rename.heldFile, named == held else { throw EraseIntentStoreError.invalidAuthority }
        _ = try captureCanonicalRenameStat(.absentTemporary)
        guard try root() == storage.root else { throw EraseIntentStoreError.invalidAuthority }
        try requireCanonicalRenameMemoryAssociation(writer); try frame()
        // No Writer boundary or whole observer callback: this is the direct
        // physical inside check used by the complete four-sibling observer.
    }
    private func renameSyncedContinuation(_ writer: ColdEraseScratchCapsuleContinuationWriterV1) throws {
        do {
            try frame()
            guard storage.state == .policyConsumed, storage.continuationWriter === writer,
                  storage.canonicalRename == nil, storage.activeRenameStat == nil,
                  storage.active == nil, (kind == .continuation || kind == .progress), storage.descriptor == -1,
                  projectedNames.count == (kind == .continuation ? 5 : 6), projectedNames.capacity == 8,
                  let index = projectedNames.firstIndex(of: kind.temporaryName),
                  !projectedNames.contains(kind.canonicalName) else {
                throw EraseIntentStoreError.invalidAuthority
            }
