            try requireWriterWholePrefix(writer); try requireWriterPhysicalBinding(writer)
            guard storage.temporary == context.before, try root() == storage.root else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let parent = storage.context.erase
            storage.canonicalRename = .init(parent: parent, temporaryName: kind.temporaryName,
                canonicalName: kind.canonicalName, flags: UInt32(RENAME_EXCL),
                readDescriptor: context.readDescriptor, beforeFile: context.before,
                beforeRoot: storage.root, byteCount: context.byteCount,
                sha256: context.sha256, temporaryNameIndex: index) // BEFORE actual once-rename
            let result = Darwin.renameatx_np(parent, kind.temporaryName,
                parent, kind.canonicalName, UInt32(RENAME_EXCL)), saved = errno
            storage.canonicalRename!.result = result
            storage.canonicalRename!.savedErrno = saved // first, including unknown/failure
            guard result == 0 else { throw EraseIntentStoreError.invalidAuthority }
            let held = try captureCanonicalRenameStat(.heldFile)
            storage.canonicalRename!.heldFile = held
            let named = try captureCanonicalRenameStat(.namedFile)
            storage.canonicalRename!.namedFile = named
            guard let held, held == named, Self.sameFirstNine(held, context.before),
                  held.mode & mode_t(S_IFMT) == mode_t(S_IFREG),
                  held.mode & 0o7777 == 0o600, held.links == 1 else {
                throw EraseIntentStoreError.invalidAuthority
            }
