            guard let absent = storage.consumedRenameStat, absent.kind == .absentTemporary,
                  absent.descriptor == parent, absent.name == kind.temporaryName,
                  absent.result == -1, absent.savedErrno == ENOENT else {
                throw EraseIntentStoreError.invalidAuthority
            }
            storage.canonicalRename!.absenceResult = absent.result
            storage.canonicalRename!.absenceErrno = absent.savedErrno
            storage.canonicalRename!.oldNameAbsenceChecked = true
