                storage.unexpectedCanonicalNodeBackingBytes = try ColdEraseControlBinaryV1.multiplying(
                    UInt64(node.ancestors.capacity - 2),
                    UInt64(MemoryLayout<ColdEraseScratchCapsuleCanonicalPolicyNodeV1.Ancestor>.stride))
            }
            try node.requireDeclaredLayout()
            let scope = ColdEraseScratchCapsuleCanonicalPolicyScopeV1(publisher: self, origin: origin, node: node)
            storage.canonicalScope = scope // before first PFP allocation/getter/pin
            try requireCanonicalScopeCurrentBinding(scope)
