            if kind == .progress {
                observation = try ProtectedFilePolicyV1.observeColdEraseScratchProgressCanonicalPolicyWithCheckedClose(scope: scope)
            } else {
                observation = try ProtectedFilePolicyV1.observeColdEraseScratchCapsuleCanonicalPolicyWithCheckedClose(scope: scope)
            }
