        guard fields.count == 11, fields.capacity <= 22 else { throw EraseIntentStoreError.invalidAuthority }
        storage.activeFactWords = []
        storage.activeFactWords!.reserveCapacity(11)
        guard storage.activeFactWords!.capacity <= 22 else { throw EraseIntentStoreError.invalidAuthority }
