        storage.activeRenderedNine = nil
    }
    private func bindTreeFacts(_ context: Context) throws -> UInt64 {
        storage.keyNames = ["support/FieldEvidenceRestore", "support/FieldEvidenceCommerce",
            "support/FieldEvidenceDiagnostics", "support/" + LocalSearchIndexStoreV1.directoryName,
            "support/" + PortableExchangeSessionStoreLayoutV2.directoryName,
            "support/" + LocalJobStoreSchemaV1.directoryName,
            "support/FieldEvidenceOperations", "caches/FieldEvidenceApp", "temporary/FieldEvidenceApp"]
