            case ("absent", .absent):
                guard tree.rootFact == nil, tree.digest == nil, tree.nodes == nil,
                      tree.deletionOrder == nil else { throw EraseIntentStoreError.invalidAuthority }
            case ("present", .present(let rootFact, let digest)):
                guard let nodes = tree.nodes, !nodes.isEmpty, nodes.count < 100_000,
                      nodes.first?.path == "", nodes.first?.kind == "directory",
