                    throw EraseIntentStoreError.invalidAuthority
                }
                try setFullFact(18 + ordinal, rootFact)
                try matchNine(storage.facts[18 + ordinal], original: original)
                total = try ColdEraseControlBinaryV1.adding(total, UInt64(nodes.count))
            default: throw EraseIntentStoreError.invalidAuthority
            }
        }
        return total // original all-nine count only, never an execution census
    }
    private func buildMetadata(context: Context,
