                guard storage.state == .streaming, offset == storage.streamOffset,
                      storage.activeSegment == nil, storage.activeSegmentOffset == nil,
                      !bytes.isEmpty else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                try boundary()
                storage.streamDigest!.update(bufferPointer: bytes)
                storage.activeSegment = bytes
                storage.activeSegmentOffset = offset // BEFORE the concrete synchronous consumer
                try body(offset, bytes)
                try boundary()
                storage.activeSegment = nil
                storage.activeSegmentOffset = nil // only after consumer and real current frame
                storage.streamOffset = try ColdEraseControlBinaryV1.adding(offset, UInt64(bytes.count))
            }
