            try metadata.withUnsafeBytes { try emit(128, $0) }
            let actual = try frame().captureCoreBirthCatalog(self, emit)
            guard actual.physicalCount == expected.physicalCount,
                  actual.selectedCount == expected.selectedCount,
                  actual.catalogByteCount == expected.catalogByteCount,
                  actual.catalogSHA256 == expected.catalogSHA256,
                  actual.census == expected.census else { throw EraseIntentStoreError.invalidAuthority }
