                    guard try context.records.record(roles[ordinal]) == nil else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                } else {
                    try context.records.withCanonicalBytes(role: roles[ordinal], operation: context.operation,
                        store: context.store, ranges: try frame(), scope: context.scope) { bytes in
                        guard UInt64(bytes.count) == expectedCount else {
                            throw EraseIntentStoreError.invalidAuthority
                        }
