    fileprivate func requireCutValues(observer: ColdEraseScratchControlObserverV1,
        eraseRoot: EraseColdControlLeafFactV1, names: [String]) throws {
        try requireMemoryAssociation()
        guard storage.phase == .installed, storage.currentProofSequence > 0,
              !storage.currentEntered, !storage.currentBodyReturned,
              storage.scope == nil, storage.node == nil, storage.origin == nil,
              let progress = storage.progress, eraseRoot == progress.context.firstRoot,
