// BIRTH_CURRENT_OPERATIONS_CHILD_DATA_V1_BEGIN
/// Genuine retained Source-after direct-child comparison DATA. A branch
/// digest/full11 does not reveal descendant current policy or ownership.
@MainActor struct ColdEraseScratchBirthCurrentOperationsChildV1 {
    let name: String
    let kind: String
    let fullFact: String
    let digest: String
    fileprivate init(name: String,
        child: EraseSchema2ColdAuxiliaryFirstObserverV1.OperationsChild) throws {
        guard !name.isEmpty, name != ".", name != "..", !name.contains("/"),
              !name.utf8.contains(0), name.utf8.count <= 255 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        self.name = name
        switch child {
        case .directory(let rootFact, let digest):
            kind = "directory"; fullFact = rootFact; self.digest = digest
        case .regular(let fact, let digest):
            kind = "file"; fullFact = fact; self.digest = digest
        }
        guard fullFact.utf8.count <= 241,
              StoreMigrationCanonicalJSONV1.isLowercaseSHA256(digest) else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }
}
