        var borrowedCatalogPath: String?
        var borrowedCatalogIndex: ColdEraseCatalogSourceIndexV1?
        var borrowedRosterNode: EraseSchema2ColdAuxiliaryPhysicalRosterV1.Node?
        var borrowedPolicy: TemporalPolicyObservationV1?
        var borrowedCanonicalSHA256: String?
