        do {
            try requireNodeBorrowingIdle(capture: capture)
            guard let scanner = storage.ranges.firstPhysicalCatalogScannerForBirthBorrower(self),
                  let context = storage.scannerContext else { throw EraseIntentStoreError.invalidAuthority }
            return try scanner.issuedBirthOriginalOperationsCount(ranges: storage.ranges, context: context)
        } catch { poison(); throw error }
    }

    /// Numeric comparison association only. It is derived from the genuine
    /// completed scanner's original-position index and the checked Writer row.
    func originalOperationsOrdinal(physicalOrdinal: UInt64,
        capture: ColdEraseScratchBirthImageCaptureV1) throws -> UInt64 {
        do {
            try enterNodeBorrowing(.ordinalAssociation, capture: capture)
            let result = try performOrdinalAssociation(physicalOrdinal: physicalOrdinal)
            storage.nodeBorrowReturned = true // actual helper returned before any postproof
            try storage.ranges.requireBirthNodeBorrowingBoundary(self)
            guard storage.borrowedOriginalOperationsOrdinal == result else {
                throw EraseIntentStoreError.invalidAuthority
            }
            clearReturnedNodeBorrowing()
            return result // no path/range/policy or current-node authority
        } catch { poison(); throw error }
    }

    /// Selected-tree first full11/policy/SHA DATA only. The selected Range is
    /// deliberately nil, including authentic selected semantic source rows.
    func withAuthenticatedFirstNode(physicalOrdinal: UInt64,
        capture: ColdEraseScratchBirthImageCaptureV1,
        _ body: (ColdEraseScratchFirstNodeV1) throws -> Void) throws {
        do {
            try enterNodeBorrowing(.catalogNode, capture: capture)
            try performFirstNodeBorrow(physicalOrdinal: physicalOrdinal, body)
            storage.nodeBorrowReturned = true // lexical DTO/policy/path locals returned
            try storage.ranges.requireBirthNodeBorrowingBoundary(self)
            guard storage.borrowedFirstNode?.physicalOrdinal == physicalOrdinal,
                  storage.borrowedFirstNode?.selectedRange == nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
            clearReturnedNodeBorrowing()
        } catch { poison(); throw error }
    }

    /// Entire ORIGINAL Operations roster domain, including root ordinal zero.
    /// UID/GID/policy are absent here; current two-pass capture is separate.
    func withAuthenticatedOriginalOperationsNode(originalOperationsOrdinal: UInt64,
        capture: ColdEraseScratchBirthImageCaptureV1,
        _ body: (ColdEraseScratchBirthOriginalOperationsNodeV1) throws -> Void) throws {
        do {
            try enterNodeBorrowing(.originalNode, capture: capture)
            try performOriginalNodeBorrow(originalOperationsOrdinal: originalOperationsOrdinal, body)
            storage.nodeBorrowReturned = true // actual private Void helper return
