            guard storage.borrowedOriginalNode?.originalOperationsOrdinal == originalOperationsOrdinal else {
                throw EraseIntentStoreError.invalidAuthority
            }
            clearReturnedNodeBorrowing()
        } catch { poison(); throw error }
    }

    func withAuthenticatedCurrentOperationsChild(name: String,
        capture: ColdEraseScratchBirthImageCaptureV1,
        _ body: (ColdEraseScratchBirthCurrentOperationsChildV1) throws -> Void) throws {
        do {
            try enterNodeBorrowing(.currentChild, capture: capture)
            try performCurrentChildBorrow(name: name, body)
            storage.nodeBorrowReturned = true // private helper and lexical child aliases returned
            try storage.ranges.requireBirthNodeBorrowingBoundary(self)
            guard storage.borrowedCurrentChild?.name.utf8.elementsEqual(name.utf8) == true else {
                throw EraseIntentStoreError.invalidAuthority
            }
            clearReturnedNodeBorrowing()
        } catch { poison(); throw error }
    }

    /// Authentic FIRST direct-child full11/digest DATA, from the retained
    /// original Snapshot. This shares the same one lexical comparison window;
    /// it never supplies descendant UID/GID/policy or current absence authority.
    func withAuthenticatedFirstOperationsChild(name: String,
        capture: ColdEraseScratchBirthImageCaptureV1,
        _ body: (ColdEraseScratchBirthCurrentOperationsChildV1) throws -> Void) throws {
        do {
            try enterNodeBorrowing(.firstChild, capture: capture)
            try performFirstChildBorrow(name: name, body)
            storage.nodeBorrowReturned = true // private helper and actual lexical aliases returned
            try storage.ranges.requireBirthNodeBorrowingBoundary(self)
            guard storage.borrowedCurrentChild?.name.utf8.elementsEqual(name.utf8) == true else {
                throw EraseIntentStoreError.invalidAuthority
            }
            clearReturnedNodeBorrowing() // fixed/shared backing remains charged
        } catch { poison(); throw error }
    }

    private func requireNodeBorrowingIdle(capture: ColdEraseScratchBirthImageCaptureV1) throws {
        guard storage.state == .rootCompared, storage.comparisonReturned,
              storage.membershipRecorded, storage.capture === capture,
              storage.nodeBorrowKind == nil, !storage.nodeBorrowReturned,
              storage.borrowedPhysicalOrdinal == nil,
              storage.borrowedOriginalOperationsOrdinal == nil,
              storage.borrowedCatalogRaw == nil, storage.borrowedCatalogPath == nil,
              storage.borrowedCatalogIndex == nil, storage.borrowedRosterNode == nil,
              storage.borrowedPolicy == nil, storage.borrowedCanonicalSHA256 == nil,
              storage.borrowedSourceChild == nil,
              storage.borrowedFirstNode == nil, storage.borrowedOriginalNode == nil,
              storage.borrowedCurrentChild == nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try requireCaptureFrame(capture: capture)
    }

    private func enterNodeBorrowing(_ kind: NodeBorrowKind,
        capture: ColdEraseScratchBirthImageCaptureV1) throws {
        // Nil/once-entry checks precede ALL delegated current/full-policy work.
        guard storage.state == .rootCompared, storage.comparisonReturned,
              storage.membershipRecorded, storage.capture === capture,
              storage.nodeBorrowKind == nil, !storage.nodeBorrowReturned,
              storage.borrowedPhysicalOrdinal == nil,
              storage.borrowedOriginalOperationsOrdinal == nil,
              storage.borrowedCatalogRaw == nil, storage.borrowedCatalogPath == nil,
              storage.borrowedCatalogIndex == nil, storage.borrowedRosterNode == nil,
              storage.borrowedPolicy == nil, storage.borrowedCanonicalSHA256 == nil,
              storage.borrowedSourceChild == nil,
              storage.borrowedFirstNode == nil, storage.borrowedOriginalNode == nil,
              storage.borrowedCurrentChild == nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        storage.nodeBorrowKind = kind // prepaid fixed window before callback/allocation/IO
        try requireCaptureFrame(capture: capture)
        try storage.ranges.requireBirthNodeBorrowingBoundary(self)
    }

    private func performOrdinalAssociation(physicalOrdinal: UInt64) throws -> UInt64 {
        guard storage.nodeBorrowKind == .ordinalAssociation, !storage.nodeBorrowReturned,
              let context = storage.scannerContext,
              let scanner = storage.ranges.firstPhysicalCatalogScannerForBirthBorrower(self) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        storage.borrowedPhysicalOrdinal = physicalOrdinal
        let row = try storage.ranges.birthCatalogRowForBorrower(self, physicalOrdinal: physicalOrdinal)
        storage.borrowedCatalogIndex = row // actual returned scalar row before mapping/postproof
        let result = try scanner.issuedBirthOriginalOperationsOrdinal(row: row,
            ranges: storage.ranges, context: context)
        storage.borrowedOriginalOperationsOrdinal = result // returned DATA before next proof
        return result
    }

    private func performFirstNodeBorrow(physicalOrdinal: UInt64,
        _ body: (ColdEraseScratchFirstNodeV1) throws -> Void) throws {
        guard storage.nodeBorrowKind == .catalogNode, !storage.nodeBorrowReturned,
              let context = storage.scannerContext,
              let scanner = storage.ranges.firstPhysicalCatalogScannerForBirthBorrower(self) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        storage.borrowedPhysicalOrdinal = physicalOrdinal
        let row = try storage.ranges.birthCatalogRowForBorrower(self, physicalOrdinal: physicalOrdinal)
        storage.borrowedCatalogIndex = row // retain actual returned row before delegated comparison/read
        storage.borrowedOriginalOperationsOrdinal = try scanner.issuedBirthOriginalOperationsOrdinal(
            row: row, ranges: storage.ranges, context: context)
        // The actual retained File owns each entered pread result; its returned
        // raw Data is retained HERE before decoding or any fallible postproof.
        storage.borrowedCatalogRaw = try storage.ranges.readBirthCatalogPathForBorrower(self, row: row)
        guard let raw = storage.borrowedCatalogRaw,
              let path = String(data: raw, encoding: .utf8) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        storage.borrowedCatalogPath = path // retained before validation/postproof/callback
        guard path.utf8.elementsEqual(raw), UInt64(path.utf8.count) == row.pathByteCount else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try ColdEraseScratchBirthOriginalOperationsNodeV1.requireRelativePath(path, emptyRootAllowed: false)
        try scanner.requireIssuedBirthOriginalPath(row: row, path: path,
            ranges: storage.ranges, context: context)
        let policy = try ColdEraseControlBinaryV1.policy(row.policyCode, fact: row.fact.words)
        storage.borrowedPolicy = policy // DATA retained before DTO/render fallible work
        storage.borrowedCanonicalSHA256 = row.isDirectory ? nil
            : ColdEraseScratchFirstCatalogScannerV1.issuedBirthDigestSHA256(row.digest)
        storage.borrowedFirstNode = try ColdEraseScratchFirstNodeV1(birthOwner: storage.ranges,
            index: row, path: path, policy: policy,
            canonicalContentSHA256: storage.borrowedCanonicalSHA256)
        guard storage.borrowedFirstNode?.selectedRange == nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try storage.ranges.requireBirthRootReservationFrame(self)
        try body(storage.borrowedFirstNode!) // closed synchronous Void-only lexical consumer
        try storage.ranges.requireBirthRootReservationFrame(self)
    }

    private func performOriginalNodeBorrow(originalOperationsOrdinal: UInt64,
        _ body: (ColdEraseScratchBirthOriginalOperationsNodeV1) throws -> Void) throws {
        guard storage.nodeBorrowKind == .originalNode, !storage.nodeBorrowReturned,
              let context = storage.scannerContext,
              let scanner = storage.ranges.firstPhysicalCatalogScannerForBirthBorrower(self) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        storage.borrowedOriginalOperationsOrdinal = originalOperationsOrdinal
        let original = try scanner.issuedBirthOriginalOperationsNode(originalOperationsOrdinal:
            originalOperationsOrdinal, ranges: storage.ranges, context: context)
        storage.borrowedRosterNode = original // exact returned immutable aliases before parser/postproof
        storage.borrowedOriginalNode = try ColdEraseScratchBirthOriginalOperationsNodeV1(
            originalOperationsOrdinal: originalOperationsOrdinal, first: original)
        try storage.ranges.requireBirthRootReservationFrame(self)
        try body(storage.borrowedOriginalNode!) // no members/raw graph/range escapes
        try storage.ranges.requireBirthRootReservationFrame(self)
    }


    private func performCurrentChildBorrow(name: String,
        _ body: (ColdEraseScratchBirthCurrentOperationsChildV1) throws -> Void) throws {
        guard storage.nodeBorrowKind == .currentChild, !storage.nodeBorrowReturned,
              let source = storage.sourceContext, let root = storage.root,
              !name.isEmpty, name.utf8.count <= 255,
              !name.utf8.contains(0), !name.contains("/"), name != ".", name != "..",
              let child = source.notificationAfter.operationsChildren[name] else {
            throw EraseIntentStoreError.invalidAuthority
        }
        storage.borrowedSourceChild = child // actual Source-after aliases before delegated proof/DTO
        // Swift Dictionary String equality is not itself exact UTF8 proof.
        // Root names are the already charged incumbent String-sorted keys.
        var low = 0, high = root.names.count
        while low < high {
            let middle = low + (high - low) / 2
            if root.names[middle] < name { low = middle + 1 } else { high = middle }
        }
        guard low < root.names.count, root.names[low].utf8.elementsEqual(name.utf8) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        storage.borrowedCurrentChild = try ColdEraseScratchBirthCurrentOperationsChildV1(
            name: root.names[low], child: child)
        try storage.ranges.requireBirthRootReservationFrame(self)
        try body(storage.borrowedCurrentChild!)
        try storage.ranges.requireBirthRootReservationFrame(self)
    }

    private func performFirstChildBorrow(name: String,
        _ body: (ColdEraseScratchBirthCurrentOperationsChildV1) throws -> Void) throws {
        guard storage.nodeBorrowKind == .firstChild, !storage.nodeBorrowReturned,
              let source = storage.sourceContext,
              source.first.operationsChildren.count < 100_000,
              !name.isEmpty, name.utf8.count <= 255,
              !name.utf8.contains(0), !name.contains("/"), name != ".", name != ".." else {
            throw EraseIntentStoreError.invalidAuthority
        }
        // No sorted key array or Dictionary String-equivalence lookup is
        // allocated/adopted. The real iterator and element cells are prepaid.
        for entry in source.first.operationsChildren {
            guard entry.key.utf8.elementsEqual(name.utf8) else { continue }
            storage.borrowedSourceChild = entry.value // exact authentic alias before DTO/postproof
            storage.borrowedCurrentChild = try ColdEraseScratchBirthCurrentOperationsChildV1(
                name: entry.key, child: entry.value)
            try storage.ranges.requireBirthRootReservationFrame(self)
            try body(storage.borrowedCurrentChild!) // synchronous Void; no raw/descendant/Range alias
            try storage.ranges.requireBirthRootReservationFrame(self)
            return
        }
        throw EraseIntentStoreError.invalidAuthority // missing first source never becomes absence
    }

    private func clearReturnedNodeBorrowing() {
        // Called only AFTER private helper/lexical body returned and fresh
        // whole boundary succeeded. Fixed profile/shared owners stay charged.
        storage.borrowedFirstNode = nil; storage.borrowedOriginalNode = nil
        storage.borrowedCurrentChild = nil
        storage.borrowedCatalogPath = nil; storage.borrowedCatalogRaw = nil
        storage.borrowedCatalogIndex = nil; storage.borrowedRosterNode = nil
        storage.borrowedPolicy = nil; storage.borrowedCanonicalSHA256 = nil
        storage.borrowedSourceChild = nil
        storage.borrowedPhysicalOrdinal = nil; storage.borrowedOriginalOperationsOrdinal = nil
        storage.nodeBorrowReturned = false; storage.nodeBorrowKind = nil
    }

    /// Sole ONE-window constructor admission. Selected catalog rows remain
    /// comparison DATA; current stat/EOF/policy are produced by the genuine
    /// entered Target resource. No whole Image/Seed/Attempt is issued here.
    func reserveColdScratchBirthCurrentReadWindow(rootCapture: ColdEraseScratchBirthImageCaptureV1,
        originalOperationsOrdinal: UInt64, selectedPhysicalOrdinal: UInt64) throws
        -> ColdEraseScratchBirthCurrentReadReservationV1 {
        do {
            guard storage.state == .rootCompared, storage.capture === rootCapture,
                  storage.comparisonEntered, storage.comparisonReturned,
                  storage.membershipRecorded, storage.nodeBorrowKind == nil,
                  !storage.currentReadReservationEntered, storage.currentReadReservation == nil,
                  storage.currentReadReservationChargeBytes == 0,
                  originalOperationsOrdinal > 0 else { throw EraseIntentStoreError.invalidAuthority }
            storage.currentReadReservationEntered = true // BEFORE profiles/delegated proofs/ctor
            storage.currentReadReservationChargeBytes = ColdEraseScratchBirthCurrentReadReservationV1.declaredBackingBytes
            try storage.ranges.requireBirthCurrentReadInitialBacking(self)
            let owner = ColdEraseScratchBirthCurrentReadReservationV1(rootReservation: self,
                rootCapture: rootCapture, operation: storage.operation, scope: storage.scope,
                originalOperationsOrdinal: originalOperationsOrdinal,
                selectedPhysicalOrdinal: selectedPhysicalOrdinal)
            storage.currentReadReservation = owner // actual provisional owner BEFORE any fallible preparation
            owner.storage.fixedChargeBytes = storage.currentReadReservationChargeBytes
            try owner.prepare()
            return owner
        } catch {
            storage.currentReadReservation?.poison(error)
            poison(); throw error
        }
    }

    /// Distinct selected two-pass constructor owner. Authentic catalogue rows
    /// only describe the exact storage domain; fresh entered Target resources
    /// supply current observations. No whole Image/Seed/Attempt is issued.
    func reserveColdScratchBirthSelectedTraversal(rootCapture: ColdEraseScratchBirthImageCaptureV1) throws
        -> ColdEraseScratchBirthCurrentTraversalReservationV1 {
        do {
            guard storage.state == .rootCompared, storage.capture === rootCapture,
                  storage.comparisonEntered, storage.comparisonReturned,
                  storage.membershipRecorded, storage.nodeBorrowKind == nil,
                  !storage.traversalReservationEntered, storage.traversalReservation == nil,
                  storage.traversalReservationChargeBytes == 0,
                  storage.currentReadReservation == nil || storage.currentReadReservation?.storage.state == .checked else {
                throw EraseIntentStoreError.invalidAuthority
            }
            storage.traversalReservationEntered = true // BEFORE profiles/delegated proofs/constructor
            storage.traversalReservationChargeBytes = ColdEraseScratchBirthCurrentTraversalReservationV1.declaredBackingBytes
            try storage.ranges.requireBirthTraversalInitialBacking(self)
            let actual = ColdEraseScratchBirthCurrentTraversalReservationV1(rootReservation: self,
                rootCapture: rootCapture, operation: storage.operation, scope: storage.scope)
            storage.traversalReservation = actual // actual provisional owner BEFORE fallible preparation
            actual.storage.fixedChargeBytes = storage.traversalReservationChargeBytes
            try actual.prepare()
            return actual
        } catch {
            storage.traversalReservation?.poison(error)
            poison(); throw error
        }
    }

    fileprivate func poison() {
        storage.state = .uncertain; storage.ranges.poison()
        // No uncertain Capture/loan/names/raw charge is cleared or retried.
    }
}
// BIRTH_ROOT_RESERVATION_SOURCE_V1_END

// BIRTH_CURRENT_READ_RESERVATION_V1_BEGIN
/// One privately issued registered readonly window for one direct, selected,
/// stable ORIGINAL node. This is not a descendant stack/growth allowance,
/// current whole Image, Seed, Attempt, functional policy or task authority.
@MainActor final class ColdEraseScratchBirthCurrentReadReservationV1 {
    fileprivate enum State: Equatable { case issued, preparing, reserved, windowBound, nodeBound, checked, uncertain }
    fileprivate enum BoundaryKind: Equatable { case preconstruction, returnedWindow }
    fileprivate struct Storage {
        let rootReservation: ColdEraseScratchBirthImageReservationV1
        let rootCapture: ColdEraseScratchBirthImageCaptureV1
        let operation: EraseColdPreparationOperationV1
        let scope: ColdEraseScratchCleanupHeldGScopeV1
        let originalOperationsOrdinal: UInt64
        let selectedPhysicalOrdinal: UInt64
        var state: State = .issued
        var root: ColdEraseScratchBirthOperationsRootV1?
        var relativePathUTF8Count: UInt64 = 0
        var rootPrefixUTF8Count: UInt64 = 0
        var absoluteURLUTF8Count: UInt64 = 0
        var relativePath: String?
        var rootPrefix: String?
        var returnedRootPath: String?
        var isDirectory = false
        var originalByteCount: UInt64 = 0
        var readByteCount = 0
        var originalMeasured = false
        var selectedAssociated = false
        var targetProfileBytes: UInt64 = 0
        var policyObservationProfileBytes: UInt64 = 0
        var policyObservationCeilingBytes: UInt64 = 0
        var actualPolicyURLUTF8Count: UInt64 = 0
        var policyObservationActualBytes: UInt64 = 0
        var policyObservationChargedExcessBytes: UInt64 = 0
        var fixedChargeBytes: UInt64 = 0
        var liveRawChargeBytes: UInt64 = 0
        var windowEntered = false
        var window: ColdEraseScratchBirthCurrentReadWindowV1?
        var nodeEntered = false
        var node: ColdEraseScratchBirthCurrentReadNodeV1?
        var readBackingEntered = false
        var readBackingRecorded = false
        var readBackingReleased = false
        var policyScopeEntered = false
        var policyScope: ColdEraseScratchBirthCurrentPolicyScopeV1?
        var observationEntered = false
        var observation: ColdEraseScratchBirthCurrentPolicyObservationV1?
        var nodeConsumed = false
        var windowReturned = false
        var activeBoundary: BoundaryKind?
        var preconstructionBoundaryEntered = false
        var preconstructionBoundaryChecked = false
        var windowBoundaryEntered = false
        var windowBoundaryChecked = false
        var returnedBoundaryCut: ColdEraseScratchCapsuleControlCutV1?
        var retainedFailure: Error?
    }
    fileprivate var storage: Storage
    fileprivate init(rootReservation: ColdEraseScratchBirthImageReservationV1,
        rootCapture: ColdEraseScratchBirthImageCaptureV1,
        operation: EraseColdPreparationOperationV1, scope: ColdEraseScratchCleanupHeldGScopeV1,
        originalOperationsOrdinal: UInt64, selectedPhysicalOrdinal: UInt64) {
        storage = Storage(rootReservation: rootReservation, rootCapture: rootCapture,
            operation: operation, scope: scope,
            originalOperationsOrdinal: originalOperationsOrdinal,
            selectedPhysicalOrdinal: selectedPhysicalOrdinal)
    }
    fileprivate static var declaredBackingBytes: UInt64 {
        UInt64(MemoryLayout<Storage>.stride
            + 3 * MemoryLayout<ColdEraseScratchBirthCurrentReadReservationV1>.stride
            + 3 * MemoryLayout<ColdEraseScratchBirthOperationsRootV1>.stride
            + 3 * MemoryLayout<ColdEraseScratchCapsuleControlCutV1>.stride
            + 2 * MemoryLayout<ColdEraseScratchBirthOriginalOperationsNodeV1>.stride
            + 2 * MemoryLayout<ColdEraseScratchFirstNodeV1>.stride
            + 2 * MemoryLayout<ColdEraseScratchBirthCurrentReadWindowV1>.stride
            + 2 * MemoryLayout<ColdEraseScratchBirthCurrentReadNodeV1>.stride
            + 2 * MemoryLayout<ColdEraseScratchBirthCurrentPolicyScopeV1>.stride
            + 2 * MemoryLayout<ColdEraseScratchBirthCurrentPolicyObservationV1>.stride
            + 2 * MemoryLayout<URL>.stride + 2 * MemoryLayout<UUID>.stride
            + 4 * MemoryLayout<UnsafePointer<CChar>?>.stride
            + 4 * MemoryLayout<UnsafeRawBufferPointer>.stride
            + 8 * MemoryLayout<String>.stride + 8 * MemoryLayout<String.UTF8View>.stride
            + 2 * MemoryLayout<String.UTF8View.SubSequence>.stride
            + 6 * MemoryLayout<Int>.stride + 12 * MemoryLayout<UInt64>.stride)
        // Actual stored/lexical value cells ONLY. The authentic relative path
        // and root prefix UTF8 overlap, exact Target Window/Node/PFP profile
        // and raw pointer capacity are added before their constructors.
        // Foundation URL/String/decoder/allocator/class/header/VM unmeasured.
    }
    private func rootFrame() throws {
        guard storage.state != .uncertain, storage.retainedFailure == nil,
              storage.rootReservation.storage.currentReadReservation === self,
              storage.rootReservation.storage.currentReadReservationEntered,
              storage.rootReservation.storage.currentReadReservationChargeBytes > 0,
              storage.rootReservation.storage.capture === storage.rootCapture,
              storage.rootReservation.storage.operation === storage.operation,
              storage.rootReservation.storage.scope === storage.scope else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try storage.rootReservation.requireCaptureFrame(capture: storage.rootCapture)
    }
    private func updateCharge() throws {
        guard storage.rootReservation.storage.currentReadReservation === self,
              storage.rootReservation.storage.currentReadReservationEntered else {
            throw EraseIntentStoreError.invalidAuthority
        }
        storage.rootReservation.storage.currentReadReservationChargeBytes =
            try ColdEraseControlBinaryV1.adding(storage.fixedChargeBytes, storage.liveRawChargeBytes)
    }
    private func addFixedCharge(_ bytes: UInt64) throws {
        storage.fixedChargeBytes = try ColdEraseControlBinaryV1.adding(storage.fixedChargeBytes, bytes)
        try updateCharge() // actual cost retained BEFORE every fallible capacity proof
        try storage.rootReservation.storage.ranges.requireBirthCurrentReadBacking(self)
    }
    /// Called once by the same Root issuer after it has retained this owner.
    /// No borrowed original/selected DTO/String/policy is retained here. Only
    /// authenticated scalar counts precede exact precharge and owned copies.
    fileprivate func prepare() throws {
        do {
            guard storage.state == .issued, storage.root == nil,
                  storage.relativePath == nil, storage.rootPrefix == nil,
                  !storage.originalMeasured, !storage.selectedAssociated,
                  storage.window == nil, storage.node == nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
            storage.state = .preparing // permanent latch BEFORE delegated frame/borrow/profile
            try rootFrame()
            let root = try storage.rootReservation.requireOperationsRoot(capture: storage.rootCapture)
            storage.root = root // SAME returned value/loan/Source aliases BEFORE fallible proof
            guard root.operationID == storage.scope.operationID,
                  root.operationID == storage.operation.retainedColdOperationIDForComparison,
                  root.operationsURL.isFileURL,
                  storage.originalOperationsOrdinal > 0 else { throw EraseIntentStoreError.invalidAuthority }
            try storage.rootReservation.withAuthenticatedOriginalOperationsNode(
                originalOperationsOrdinal: storage.originalOperationsOrdinal,
                capture: storage.rootCapture) { first in
                guard first.originalOperationsOrdinal == self.storage.originalOperationsOrdinal,
                      !first.path.isEmpty, !first.path.contains("/"),
                      first.path.utf8.count <= 255,
                      first.kind == "directory" || first.kind == "file" else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                self.storage.relativePathUTF8Count = UInt64(first.path.utf8.count)
                self.storage.isDirectory = first.kind == "directory"
                self.storage.originalByteCount = first.byteCount
                self.storage.originalMeasured = true
            }
            let global = try storage.rootReservation.originalOperationsOrdinal(
                physicalOrdinal: storage.selectedPhysicalOrdinal, capture: storage.rootCapture)
            guard storage.originalMeasured, global == storage.originalOperationsOrdinal else {
                throw EraseIntentStoreError.invalidAuthority
            }
            storage.selectedAssociated = true // genuine scalar join, never policy/IO authority
            // The Foundation URL already has its authentic retained Source
            // origin. Only a scalar length escapes this lexical C-string view.
            // Its internal transcoding allocation is explicitly unmeasured.
            let prefixCount = try root.operationsURL.withUnsafeFileSystemRepresentation { pointer -> UInt64 in
                guard let pointer else { throw EraseIntentStoreError.invalidAuthority }
                let rawCount = Darwin.strlen(pointer)
                guard rawCount > 1 else { throw EraseIntentStoreError.invalidAuthority }
                let normalized = pointer[rawCount - 1] == CChar(47) ? rawCount - 1 : rawCount
                guard normalized > 0 else { throw EraseIntentStoreError.invalidAuthority }
                return UInt64(normalized)
            }
            storage.rootPrefixUTF8Count = prefixCount
            storage.absoluteURLUTF8Count = try ColdEraseControlBinaryV1.adding(
                prefixCount, 1, storage.relativePathUTF8Count)
            // Native owns one copied prefix/path. The verification getters
            // and old/new lexical values have two exact logical UTF8 windows.
            try addFixedCharge(try ColdEraseControlBinaryV1.adding(
                ColdEraseControlBinaryV1.multiplying(prefixCount, 2), 1,
