    fileprivate func capsuleObserverProjection(_ observer: ColdEraseScratchControlObserverV1) throws
        -> (EraseColdControlLeafFactV1, [String]) {
        guard controlObserver === observer else { throw EraseIntentStoreError.invalidAuthority }
        try requireFrame()
        if let current = requestSemanticOwner, state == .catalog || state == .bound {
            return try current.fixedProjection()
        }
        if let installation = publishedResourceInstallation {
            try requirePublishedResourceInstallationFrame(installation)
            return try installation.observerProjection()
        }
        if let progressPublisher {
            try requireCapsulePublisherFrame(progressPublisher)
            return try progressPublisher.observerProjection()
        }
        if let capsulePublisher {
            try requireCapsulePublisherFrame(capsulePublisher)
            return try capsulePublisher.observerProjection()
        }
        return (firstControls.eraseRoot, firstControls.names)
    }

    fileprivate func requireCapsuleObserverOwnedLeaf(_ observer: ColdEraseScratchControlObserverV1) throws {
        guard controlObserver === observer else { throw EraseIntentStoreError.invalidAuthority }
        try requireFrame()
        if let installation = publishedResourceInstallation {
            try requirePublishedResourceInstallationFrame(installation)
            try installation.requireCurrentResources()
            return
