        if let progressPublisher {
            try progressPublisher.requireObserverOwnedLeaf()
            try progressPublisher.requireProgressCoreCurrent()
            try progressPublisher.requireObserverOwnedLeaf()
        } else if let capsulePublisher { try capsulePublisher.requireObserverOwnedLeaf() }
    }

