              state != .closed, state != .fenced else { throw EraseIntentStoreError.invalidAuthority }
        if state == .postContent {
            guard oldScratchAccessFenced, postContentScope != nil,
                  postContentTransfer != nil else { throw EraseIntentStoreError.invalidAuthority }
            // Actual Main retained Namespace/Diagnostics lineage, no Store,
            // Range, revoked G or descriptor callback in this DATA producer.
            return try operation.requireColdCapsuleCapacitySupportProjection(ranges: self, store: store)
        }
        return firstProjection.supportFact // exact before any own Support mutation
    }

    /// The genuine completed same-process publishers own both actual Files.
    /// This once-only installer adds no source index/Seed/Attempt/task grant.
    fileprivate func installPublishedColdControlResources() throws {
        do {
            guard !publishedResourceInstallationEntered, publishedResourceInstallation == nil,
                  publishedResourceInstallationChargeBytes == 0, state == .registered,
                  attempt == nil, permit == nil, pending == nil, planning == nil,
                  pendingPrimitiveIntent == nil, pendingPrimitiveOutcome == nil,
                  resources.isEmpty, catalogResource == nil, progressResource == nil,
                  !oldScratchAccessFenced, postContentScope == nil, postContentTransfer == nil,
                  let first = capsulePublisher, let second = progressPublisher else {
                throw EraseIntentStoreError.invalidAuthority
            }
            publishedResourceInstallationEntered = true // BEFORE every delegated proof/profile/allocation
            let bytes = try ColdEraseControlBinaryV1.adding(
                ColdEraseScratchPublishedResourceInstallationV1.declaredBackingBytes,
                UInt64(MemoryLayout<Bool>.stride
                    + MemoryLayout<ColdEraseScratchPublishedResourceInstallationV1?>.stride
                    + 2 * MemoryLayout<UInt64>.stride + 2 * MemoryLayout<ColdEraseRetainedControlFileV1>.stride))
            publishedResourceInstallationChargeBytes = bytes // BEFORE capacity/constructor/reference array
            try requireFrame(); try requireBackingCapacity(additionalBytes: 0)
            let owner = ColdEraseScratchPublishedResourceInstallationV1(ranges: self,
                firstPublisher: first, secondPublisher: second)
            publishedResourceInstallation = owner // same actual owner BEFORE any proof/current IO
            try owner.prepare()
            guard let core = owner.storage.core, let progress = owner.storage.progress,
                  publishedCanonicalInfrastructure === core.resource,
                  publishedProgressInfrastructure === progress.resource else { throw EraseIntentStoreError.invalidAuthority }
            owner.storage.phase = .installing
            resources.reserveCapacity(2) // fixed reference backing was reserved above
            if resources.capacity > 2 {
                publishedResourceInstallationResourceExcessBytes = try ColdEraseControlBinaryV1.multiplying(
                    UInt64(resources.capacity - 2), UInt64(MemoryLayout<ColdEraseRetainedControlFileV1>.stride))
            }
            guard resources.capacity <= 2 else { throw EraseIntentStoreError.invalidAuthority }
            resources.append(core.resource); resources.append(progress.resource)
            catalogResource = core.resource; progressResource = progress.resource
            // All actual aliases are retained BEFORE throwing installed proofs.
            owner.storage.phase = .installed
            try requirePublishedResourceInstallationFrame(owner)
            try core.resource.requirePinned(); try progress.resource.requirePinned()
            guard let controlObserver else { throw EraseIntentStoreError.invalidAuthority }
            let cut = try controlObserver.capture()
            guard cut.coreByteCount == core.byteCount, cut.coreSHA256 == core.sha256,
                  cut.progressByteCount == 64, cut.progressSHA256 == progress.sha256 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try requirePublishedResourceInstallationFrame(owner)
            // Keep registered. A real authenticated scalar-index installer and
            // replay Seed producer must separately precede catalog/Attempt.
        } catch { poison(); throw error }
    }

    fileprivate func requirePublishedResourceInstallationFrame(_ owner: ColdEraseScratchPublishedResourceInstallationV1) throws {
        guard publishedResourceInstallation === owner, publishedResourceInstallationEntered,
              publishedResourceInstallationChargeBytes > 0, state == .registered,
              owner.storage.ranges === self, owner.storage.phase != .uncertain,
              attempt == nil, permit == nil, pending == nil, planning == nil,
              pendingPrimitiveIntent == nil, pendingPrimitiveOutcome == nil,
              !oldScratchAccessFenced, postContentScope == nil, postContentTransfer == nil,
              capsulePublisher === owner.storage.firstPublisher,
              progressPublisher === owner.storage.secondPublisher else { throw EraseIntentStoreError.invalidAuthority }
        if owner.storage.phase == .installed {
            guard let core = owner.storage.core, let progress = owner.storage.progress,
                  resources.count == 2, resources.capacity <= 2,
                  resources[0] === core.resource, resources[1] === progress.resource,
                  catalogResource === core.resource, progressResource === progress.resource else {
                throw EraseIntentStoreError.invalidAuthority
            }
        } else {
            guard owner.storage.phase == .preparing || owner.storage.phase == .prepared,
                  resources.isEmpty, catalogResource == nil, progressResource == nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        try requireFrame() // real registered OP/GEX/loan; never metadata authority
    }
    fileprivate func requirePublishedResourceInstallationCapacity(_ owner: ColdEraseScratchPublishedResourceInstallationV1) throws {
        try requirePublishedResourceInstallationFrame(owner)
