    /// Install only authentic immutable birth comparison indexes. The real
    /// protected current Files/whole prefix bracket all retained aliases and
    /// scalar copying. Registered remains registered: no Seed/Attempt grant.
    fileprivate func installPublishedBirthCatalogIndex() throws {
        do {
            guard state == .registered, attempt == nil, permit == nil,
                  pending == nil, planning == nil, pendingPrimitiveIntent == nil,
                  pendingPrimitiveOutcome == nil, sourceIndex.isEmpty,
                  sourceIndexChargeBytes == 0, selectedSourceCount == 0,
                  retainedPhysicalRoster == nil, retainedFirstSnapshot == nil,
                  retainedNotificationAfter == nil, retainedSeed == nil,
                  currentStateSHA256 == nil, lastCompleteFrameSHA256 == nil,
                  let installation = publishedResourceInstallation,
                  installation.storage.phase == .installed,
                  let core = catalogResource, let progress = progressResource,
                  let observer = controlObserver else { throw EraseIntentStoreError.invalidAuthority }
            // A nonzero existing charge is the permanent once-entry latch.
            // Actual returned Context/row/value aliases are reserved before
            // any delegated frame, capacity or getter can throw/reenter.
            sourceIndexChargeBytes = UInt64(MemoryLayout<UInt64>.stride)
            let fixed = try ColdEraseControlBinaryV1.adding(
                ColdEraseScratchCapsuleContinuationWriterV1.issuedBirthCatalogIndexBackingBytes,
                UInt64(MemoryLayout<[ColdEraseCatalogSourceIndexV1]>.stride
                + 8 * MemoryLayout<ColdEraseCatalogSourceIndexV1>.stride
                + 8 * MemoryLayout<ColdEraseScratchCoreBirthSourceV1.Context>.stride
                + 4 * MemoryLayout<EraseSchema2ColdAuxiliaryPhysicalRosterV1>.stride
                + 8 * MemoryLayout<EraseSchema2ColdAuxiliaryFirstObserverV1.Snapshot>.stride
                + 4 * MemoryLayout<ColdEraseScratchCapsuleControlCutV1>.stride
                + 8 * MemoryLayout<Int>.stride + 8 * MemoryLayout<UInt64>.stride
                + 4 * MemoryLayout<ColdEraseScratchCapsuleContinuationWriterV1>.stride))
            sourceIndexChargeBytes = fixed
            try requirePublishedResourceInstallationFrame(installation)
            try requireBackingCapacity(additionalBytes: 0)
            let before = try observer.capture() // real current policies + both full byte streams
            try requirePublishedResourceInstallationFrame(installation)
            let writer = try installation.storage.firstPublisher.issuedBirthCatalogIndexWriter(resource: core)
            let count = try writer.issuedBirthCatalogIndexCount(resource: core)
            guard count >= 0, count <= 100_000,
                  before.coreByteCount == core.byteCount, before.progressByteCount == 64,
                  before.coreSHA256 == installation.storage.core?.sha256,
                  before.progressSHA256 == installation.storage.progress?.sha256 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let rowStride = UInt64(MemoryLayout<ColdEraseCatalogSourceIndexV1>.stride)
            // The original Writer's exact scalar backing stays charged and
            // retained; this separately reserves Array capacity/resize overlap.
            let cells = try ColdEraseControlBinaryV1.multiplying(UInt64(count), 2)
            sourceIndexChargeBytes = try ColdEraseControlBinaryV1.adding(fixed,
                ColdEraseControlBinaryV1.multiplying(cells, rowStride))
            try requireBackingCapacity(additionalBytes: 0)
            sourceIndex.reserveCapacity(count)
            if UInt64(sourceIndex.capacity) > cells {
                // Retain actual returned overcapacity plus logical overlap
                // before refusal. It can never be discharged as an empty index.
                sourceIndexChargeBytes = try ColdEraseControlBinaryV1.adding(fixed,
                    ColdEraseControlBinaryV1.multiplying(
                        ColdEraseControlBinaryV1.multiplying(UInt64(sourceIndex.capacity), 2), rowStride))
                throw EraseIntentStoreError.invalidAuthority
            }
            guard sourceIndex.capacity >= count, UInt64(sourceIndex.capacity) <= cells else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let actual = try writer.issuedBirthCatalogIndexContext(resource: core, ranges: self)
            // Exact returned first-origin aliases are retained immediately.
            // No current survivor supplies a replacement first Snapshot.
            retainedPhysicalRoster = actual.physical
            retainedFirstSnapshot = actual.first
            retainedNotificationAfter = actual.notificationAfter
            guard actual.operation === operation, actual.store === store,
                  actual.scope === heldScope, actual.projection === firstProjection,
                  actual.records === notificationCanonicalRecords,
                  actual.physical.canonicalBytes == firstControls.auxiliaryBytes,
                  notificationCanonicalRecordsChargeBytes > 0 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let expectedSelected = try writer.issuedBirthCatalogSelectedCount(resource: core)
            var selected: UInt64 = 0
            for ordinal in 0..<count {
                let row = try writer.issuedBirthCatalogIndexRow(resource: core, ordinal: ordinal)
                guard row.physicalOrdinal == UInt64(ordinal),
                      row.selectedOrdinalBefore == selected,
                      row.pathByteCount > 0, row.pathByteCount <= 16_640 else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                if row.isSelected {
                    guard row.sourceOrdinal == selected, row.role != .physicalOnly else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    selected = try ColdEraseControlBinaryV1.adding(selected, 1)
                    guard selected <= expectedSelected else { throw EraseIntentStoreError.invalidAuthority }
                } else {
                    guard row.role == .physicalOnly, row.sourceOrdinal == UInt64.max,
                          row.semanticVersion == 0, row.rawByteCount == 0 else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                }
                sourceIndex.append(row) // actual returned scalar retained before subsequent proof
                guard sourceIndex.capacity >= count, UInt64(sourceIndex.capacity) <= cells else {
                    sourceIndexChargeBytes = try ColdEraseControlBinaryV1.adding(fixed,
                        ColdEraseControlBinaryV1.multiplying(
                            ColdEraseControlBinaryV1.multiplying(UInt64(sourceIndex.capacity), 2), rowStride))
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            selectedSourceCount = selected
            guard selected == expectedSelected, sourceIndex.count == count,
                  sourceIndex.capacity >= count, UInt64(sourceIndex.capacity) <= cells,
                  try writer.issuedBirthCatalogIndexCount(resource: core) == count else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let after = try observer.capture() // all aliases are retained on failed current proof
            try requirePublishedResourceInstallationFrame(installation)
            guard after === before, after.coreByteCount == core.byteCount,
                  after.coreSHA256 == installation.storage.core?.sha256,
                  after.progressByteCount == 64,
                  after.progressSHA256 == installation.storage.progress?.sha256,
                  retainedSeed == nil, currentStateSHA256 == nil,
                  lastCompleteFrameSHA256 == nil, state == .registered else {
                throw EraseIntentStoreError.invalidAuthority
            }
            // Seed requires its own real complete protected current image and
            // ingress prerequisite/settlement. This index never creates it.
        } catch { poison(); throw error }
    }


    /// Registered pre-Attempt readonly root issuer. No returned scalar, Cut or
    /// root comparison can install a complete image, Seed or task capability.
    func reserveColdScratchBirthImageCapture(operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws -> ColdEraseScratchBirthImageReservationV1 {
        do {
            guard self.operation === operation, heldScope === scope,
                  !birthRootReservationEntered, birthRootReservation == nil,
                  birthRootReservationChargeBytes == 0, state == .registered,
                  attempt == nil, permit == nil, pending == nil, planning == nil,
                  pendingPrimitiveIntent == nil, pendingPrimitiveOutcome == nil,
                  retainedSeed == nil, currentStateSHA256 == nil, lastCompleteFrameSHA256 == nil,
                  sourceIndexChargeBytes > 0, retainedPhysicalRoster != nil,
                  retainedFirstSnapshot != nil, retainedNotificationAfter != nil,
                  let installation = publishedResourceInstallation,
                  installation.storage.phase == .installed,
                  let core = catalogResource, progressResource != nil,
                  let scanner = firstPhysicalCatalogScanner, let observer = controlObserver else {
                throw EraseIntentStoreError.invalidAuthority
            }
            birthRootReservationEntered = true // BEFORE profile/current/capacity callbacks
            birthRootReservationChargeBytes = UInt64(MemoryLayout<Bool>.stride
                + MemoryLayout<ColdEraseScratchBirthImageReservationV1?>.stride + MemoryLayout<UInt64>.stride)
            let fixed = try ColdEraseControlBinaryV1.adding(birthRootReservationChargeBytes,
                ColdEraseScratchBirthImageReservationV1.declaredBackingBytes,
                ColdEraseScratchBirthImageCaptureV1.requiredBackingBytes())
            birthRootReservationChargeBytes = fixed // all actual fixed owners BEFORE ctor
            try requirePublishedResourceInstallationFrame(installation)
            try requireBackingCapacity(additionalBytes: 0)
            let owner = ColdEraseScratchBirthImageReservationV1(ranges: self,
                operation: operation, scope: scope)
            birthRootReservation = owner // exact provisional owner BEFORE every fallible producer
            owner.storage.state = .preparing
            try requireBirthRootReservationFrame(owner)
            let cut = try observer.capture() // genuine fresh current policy/full bytes/whole controls
            owner.storage.cut = cut // actual returned immutable comparison owner BEFORE postproof
            let writer = try installation.storage.firstPublisher.issuedBirthCatalogIndexWriter(resource: core)
            let source = try writer.issuedBirthCatalogIndexContext(resource: core, ranges: self)
            owner.storage.sourceContext = source // retain all returned origin aliases immediately
            let original = try scanner.issuedBirthOperationsRootContext(ranges: self)
            owner.storage.scannerContext = original
            let loan = try operation.requireColdScratchCapsuleBorrowedParents(ranges: self,
                store: store, scope: scope)
            owner.storage.loan = loan
            guard source.operation === operation, source.store === store, source.scope === scope,
                  source.projection === firstProjection, source.records === notificationCanonicalRecords,
                  notificationCanonicalRecordsChargeBytes > 0,
                  source.physical.canonicalBytes == firstControls.auxiliaryBytes,
                  retainedPhysicalRoster?.canonicalBytes == source.physical.canonicalBytes,
                  retainedFirstSnapshot == source.first, retainedNotificationAfter == source.notificationAfter,
                  original.roster.canonicalBytes == source.physical.canonicalBytes,
                  original.first == source.first, original.after == source.notificationAfter,
                  original.loan === loan, original.operationID == scope.operationID,
                  original.operationID == operation.retainedColdOperationIDForComparison,
                  let full = source.notificationAfter.operations.rootFact, full.utf8.count <= 241,
                  cut.coreSHA256 == installation.storage.core?.sha256,
                  cut.progressSHA256 == installation.storage.progress?.sha256 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try loan.requireBound(operation: operation, scope: scope)
            let count = source.notificationAfter.operationsChildren.count
            let plus = count.addingReportingOverflow(7)
            guard !plus.overflow else { throw EraseIntentStoreError.invalidAuthority }
            let membership = (plus.partialValue / 8).multipliedReportingOverflow(by: 2)
            guard !membership.overflow, membership.partialValue >= 0 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            var utf8: UInt64 = 0
            for (name, _) in source.notificationAfter.operationsChildren {
                guard !name.isEmpty, name != ".", name != "..", !name.contains("/"),
                      !name.utf8.contains(0), name.utf8.count <= 255 else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                utf8 = try ColdEraseControlBinaryV1.adding(utf8, UInt64(name.utf8.count))
            }
            let ceiling = try ColdEraseControlBinaryV1.multiplying(UInt64(count), 2)
            owner.storage.nameCount = count; owner.storage.namesUTF8Bytes = utf8
            owner.storage.namesCapacityCeiling = ceiling
            owner.storage.membershipBytes = membership.partialValue
            // One retained Array + in-place sort/value-copy logical overlap,
            // name UTF8 COW overlap and TWO exact initialized bitmaps. No Set,
            // duplicate whole graph, arbitrary scalar grant or count guess.
            birthRootReservationChargeBytes = try ColdEraseControlBinaryV1.adding(fixed,
                ColdEraseControlBinaryV1.multiplying(
                    ColdEraseControlBinaryV1.multiplying(ceiling, 2), UInt64(MemoryLayout<String>.stride)),
                ColdEraseControlBinaryV1.multiplying(utf8, 2), UInt64(membership.partialValue))
            try requireBackingCapacity(additionalBytes: 0)
            owner.storage.names.reserveCapacity(count)
            if UInt64(owner.storage.names.capacity) > ceiling {
                birthRootReservationChargeBytes = try ColdEraseControlBinaryV1.adding(
                    fixed,
                    ColdEraseControlBinaryV1.multiplying(
                        ColdEraseControlBinaryV1.multiplying(UInt64(owner.storage.names.capacity), 2),
                        UInt64(MemoryLayout<String>.stride)),
                    ColdEraseControlBinaryV1.multiplying(utf8, 2), UInt64(membership.partialValue))
                throw EraseIntentStoreError.invalidAuthority // retain actual capacity excess
            }
            guard owner.storage.names.capacity >= count else { throw EraseIntentStoreError.invalidAuthority }
            for (name, _) in source.notificationAfter.operationsChildren {
                owner.storage.names.append(name) // SAME immutable source String backing
                if UInt64(owner.storage.names.capacity) > ceiling {
                    birthRootReservationChargeBytes = try ColdEraseControlBinaryV1.adding(
                        fixed,
                        ColdEraseControlBinaryV1.multiplying(
                            ColdEraseControlBinaryV1.multiplying(UInt64(owner.storage.names.capacity), 2),
                            UInt64(MemoryLayout<String>.stride)),
                        ColdEraseControlBinaryV1.multiplying(utf8, 2), UInt64(membership.partialValue))
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            owner.storage.names.sort() // incumbent String ordering; no second sorted result array
            if UInt64(owner.storage.names.capacity) > ceiling {
                birthRootReservationChargeBytes = try ColdEraseControlBinaryV1.adding(fixed,
                    ColdEraseControlBinaryV1.multiplying(
                        ColdEraseControlBinaryV1.multiplying(UInt64(owner.storage.names.capacity), 2),
                        UInt64(MemoryLayout<String>.stride)),
                    ColdEraseControlBinaryV1.multiplying(utf8, 2), UInt64(membership.partialValue))
                throw EraseIntentStoreError.invalidAuthority
            }
            guard owner.storage.names.count == count,
                  UInt64(owner.storage.names.capacity) <= ceiling else {
                throw EraseIntentStoreError.invalidAuthority
            }
            for position in owner.storage.names.indices {
                let name = owner.storage.names[position]
                guard source.notificationAfter.operationsChildren[name] != nil,
                      position == owner.storage.names.startIndex || owner.storage.names[position - 1] < name else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            owner.storage.root = .init(loan: loan, operationsURL: original.operationsURL,
                fullFact: full, names: owner.storage.names, operationID: original.operationID)
            owner.storage.state = .reserved
            let after = try observer.capture()
            guard after === cut, state == .registered, retainedSeed == nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try owner.requireReservedCaptureFrame(operation: operation, scope: scope)
            return owner // readonly root owner only; no complete image/Seed/Attempt
        } catch { birthRootReservation?.poison(); poison(); throw error }
    }

    /// Per-entered-read current association. Direct installed File held/named
