        _ body: (ColdEraseSchema2NamespaceAuthenticatedAuxiliaryDigestV1) throws -> Void) throws {
        do {
            guard !namespaceAuxiliaryBorrowActive else { throw EraseIntentStoreError.invalidAuthority }
            namespaceAuxiliaryBorrowActive = true // before any delegated memory/capacity borrower
            try reservation.requireCompletedNamespaceCaptureMemory(capture)
            try preparation.requireCaptureAssociation(capture: capture)
            if namespaceAuxiliaryDigest == nil {
                guard !namespaceAuxiliaryDigestEntered,
                      namespaceCaptureReservation === reservation,
                      let roster = retainedPhysicalRoster,
                      roster.canonicalBytes == firstControls.auxiliaryBytes,
                      let identity = birthIdentityInitialization,
                      identity === requestSemanticIdentity, identity.storage.phase == .installed,
                      identity.storage.retainedFailure == nil else { throw EraseIntentStoreError.invalidAuthority }
                namespaceAuxiliaryDigestEntered = true // before real capacity, hash or constructor
                try reservation.reserveNamespaceConsumerBacking(capture: capture,
                    bytes: ColdEraseSchema2NamespaceAuthenticatedAuxiliaryDigestV1.declaredBackingBytes)
                let digest = Data(SHA256.hash(data: firstControls.auxiliaryBytes))
                let actual = ColdEraseSchema2NamespaceAuthenticatedAuxiliaryDigestV1(ranges: self,
                    reservation: reservation, capture: capture, preparation: preparation,
                    roster: roster, identity: identity, bytes: firstControls.auxiliaryBytes, digest: digest)
                namespaceAuxiliaryDigest = actual // SAME source identity before throwing consumer/postproof
            }
            guard let actual = namespaceAuxiliaryDigest else { throw EraseIntentStoreError.invalidAuthority }
            try actual.requireAssociation(preparation: preparation)
            try body(actual) // synchronous immutable DATA only; caller retains SAME object before its postproof
            try actual.requireAssociation(preparation: preparation)
            namespaceAuxiliaryBorrowActive = false
        } catch { reservation.poison(); poison(); throw error }
    }
