    func poison() {
        guard state != .closed else { return }
        let transferred = oldScratchAccessFenced
        state = .uncertain
        planning?.revoked = true
        if transferred { postContentScope?.poisonOnUncertainEffect() }
        else { heldScope.poisonOnUncertainCleanup() }
        operation.poisonColdScratchOwner()
    }

    private func requireFrame() throws {
        guard state != .uncertain, state != .closed, state != .fenced,
              uncertainPolicyDescriptors.isEmpty else {
            throw EraseIntentStoreError.invalidAuthority
        }
        if initialProducerV4.charge > 0 {
            guard initialProducerV4.failure == nil else { throw EraseIntentStoreError.invalidAuthority }
            try operation.requireColdScratchInitialBirthRangeMemoryV4(ranges: self,
                store: store, scope: heldScope, projection: firstProjection,
                retainedCharge: initialProducerV4.charge)
        }
        if state == .postContent {
            guard let postContentScope, let postContentTransfer else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try postContentTransfer.requireActivated(to: postContentScope)
            try postContentScope.requireCapsuleResources(ranges: self,
                store: store, operation: operation)
            return // permanently no old G/parent-loan access
        }
        if state == .transferring {
            guard let postContentScope, let postContentTransfer, let transferLoan else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try postContentTransfer.requireCommitAssociation(ranges: self,
                store: store, operation: operation, from: heldScope, to: postContentScope)
            try transferLoan.requireCheckedColdScratchLoanRevoked(
                operation: operation, scope: heldScope)
            try operation.requireColdPostContentTransferFrame(postContentScope,
                ranges: self, store: store, scope: heldScope)
            try heldScope.requireNonrecursiveCurrentFrame()
            return // checked loan revoke forbids any loan FD access
        }
        try operation.requireColdScratchCapsuleCurrentFrame(ranges: self,
            store: store, scope: heldScope)
        let loan = try operation.requireColdScratchCapsuleBorrowedParents(
            ranges: self, store: store, scope: heldScope)
        try loan.requireBound(operation: operation, scope: heldScope)
        try heldScope.requireNonrecursiveCurrentFrame()
    }

    fileprivate func requireStoreMemoryAssociation(store: EraseIntentStore,
        operation: EraseColdPreparationOperationV1) throws {
        guard self.store === store, self.operation === operation,
              state != .closed, state != .fenced, state != .uncertain,
              uncertainPolicyDescriptors.isEmpty else { throw EraseIntentStoreError.invalidAuthority }
        if state == .transferring || state == .postContent {
            try requireFrame()
            try operation.requireSchema2ColdIntentStore(store)
            return
        }
        try heldScope.requireOrigin(operation: operation, store: store)
        try operation.requireColdScratchRangeOwner(self, scope: heldScope, store: store)
    }

