                return .currentRoot(request)
            }
            if let absence = ingressConsumers.absence {
                try absence.requireBound(ranges: self, store: store, operation: operation, scope: scope)
                return .noCurrentRoot(absence)
            }
            guard !ingressConsumers.entered, ingressConsumers.failure == nil,
                  state == .registered, retainedSeed == nil, currentStateSHA256 == nil,
                  attempt == nil, permit == nil, pending == nil, planning == nil,
                  lastCompleteProgressOffset == 64, lastCompleteFrameSHA256 == nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
            ingressConsumers.entered = true // no retry after any fallible call
            ingressConsumers.fixedCharge = UInt64(MemoryLayout<IngressConsumersStorage>.stride)
            try requireBackingCapacity(additionalBytes: 0)
            let observer: ColdEraseScratchPreSeedWholeCurrentObserverV1
            if let retained = preSeedWholeObserver { observer = retained }
            else { observer = try capturePreSeedWholeCurrent(operation: operation, scope: scope) }
            ingressConsumers.observer = observer // actual returned owner BEFORE postproof
            try requirePreSeedWholeCurrentFrame(observer)
            try observer.requireAssociation(ranges: self, store: store, operation: operation, scope: scope)
            guard let urls = observer.storage.parentURLs,
                  let loan = preSeedWholeLoan, let core = catalogResource,
                  let installation = publishedResourceInstallation,
                  installation.storage.phase == .installed else { throw EraseIntentStoreError.invalidAuthority }
            ingressConsumers.pathCount = try ColdEraseScratchIngressDeclaredBackingV1.pathCount(urls.support)
            ingressConsumers.fixedCharge = try ColdEraseControlBinaryV1.adding(
                ingressConsumers.fixedCharge,
                ColdEraseScratchIngressDeclaredBackingV1.required(pathCount: ingressConsumers.pathCount))
            try requireBackingCapacity(additionalBytes: 0) // genuine live frame BEFORE all new constructors
            let writer = try installation.storage.firstPublisher.issuedBirthCatalogIndexWriter(resource: core)
            ingressConsumers.writer = writer // returned alias before memory/context getter
            let metadata = try writer.issuedBirthIngressMetadata(resource: core, ranges: self)
            ingressConsumers.metadata = metadata // actual immutable emitted/readback aliases retained
            let context = try writer.issuedBirthCatalogIndexContext(resource: core, ranges: self)
            guard context.operation === operation, context.store === store, context.scope === scope,
                  context.physical.canonicalBytes == observer.storage.context.physical.canonicalBytes,
                  context.first == observer.storage.context.first,
                  context.notificationAfter == observer.storage.context.notificationAfter else {
                throw EraseIntentStoreError.invalidAuthority
            }
            if metadata.flags[metadata.flags.startIndex + 80] == 0 {
                try ColdEraseScratchIngressDeclaredBackingV1.requireAbsentMetadata(metadata)
                guard context.first.ingressControlNodes == nil,
                      context.first.operationsChildren["ProtectedIngressReceiptsV1"] == nil,
                      context.notificationAfter.ingressControlNodes == nil,
                      context.notificationAfter.operationsChildren["ProtectedIngressReceiptsV1"] == nil else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                try observer.requireIngressAbsent(ranges: self, store: store, operation: operation, scope: scope)
                let actual = ColdEraseScratchIngressRootAbsenceProjectionV1(ranges: self, store: store,
                    operation: operation, scope: scope, observer: observer, core: core, writer: writer,
                    metadata: metadata)
                ingressConsumers.absence = actual // before positive association/Receipt consumer
                try actual.requireBound(ranges: self, store: store, operation: operation, scope: scope)
                try requirePreSeedWholeCurrentFrame(observer)
                ingressConsumers.prerequisiteReturned = true
                return .noCurrentRoot(actual)
            }
            let raw = try observer.requirePrePolicyIngressRoot(ranges: self, store: store,
                operation: operation, scope: scope)
            ingressConsumers.rawRoot = raw // returned authentic owner before immutable/current join
            let first = try ColdEraseScratchIngressDeclaredBackingV1.presentFirst(metadata,
                root: raw, context: context)
            let actual = ColdEraseScratchIngressPolicyRequestV1(ranges: self, store: store,
                operation: operation, scope: scope, loan: loan, observer: observer, root: raw,
                core: core, writer: writer, metadata: metadata, applicationSupportURL: urls.support,
                pathCount: ingressConsumers.pathCount, first: first)
            ingressConsumers.request = actual // BEFORE every fallible returned-owner proof
            try actual.requireBound(ranges: self, store: store, operation: operation, scope: scope)
            try requirePreSeedWholeCurrentFrame(observer)
            ingressConsumers.prerequisiteReturned = true
            return .currentRoot(actual)
        } catch { poisonIngressConsumers(error); throw error }
    }

    /// Initial real postpair consumes the SAME active completed two-setter
    /// Scope/Attempt. It is distinct from the later revoked-scope readonly pair.
    func recordIngressRootPolicySettlement(request: ColdEraseScratchIngressPolicyRequestV1,
        attempt: ColdEraseScratchIngressPolicyAttemptV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws -> ColdEraseScratchIngressRootPolicyProjectionV1 {
        do {
            guard heldScope === scope, ingressConsumers.request === request,
                  ingressConsumers.prerequisiteReturned, !ingressConsumers.settlementEntered,
                  ingressConsumers.projection == nil, ingressConsumers.absence == nil,
                  let observer = ingressConsumers.observer else { throw EraseIntentStoreError.invalidAuthority }
            ingressConsumers.settlementEntered = true // actual owner latches before current proof
            ingressConsumers.attempt = attempt // actual result BEFORE independent settlement checks
            let effectScope = try operation.requireColdScratchIngressPolicyAttempt(attempt,
                request: request, ranges: self, store: store, scope: scope)
            ingressConsumers.effectScope = effectScope
            try request.requireEffectScope(effectScope, operation: operation, scope: scope)
            try attempt.requireCheckedSettlement()
            try requirePreSeedWholeCurrentFrame(observer)
            try observer.observeAfterIngressPolicy(attempt: attempt, effectScope: effectScope)
            let digest = try observer.requirePostPolicyIngressDigest(attempt: attempt, effectScope: effectScope)
            guard let final = attempt.finalFullFact, digest.utf8.count == 64,
                  digest.utf8.allSatisfy({ (48...57).contains($0) || (97...102).contains($0) }) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let actual = ColdEraseScratchIngressRootPolicyProjectionV1(request: request,
                attempt: attempt, effectScope: effectScope, final: final, digest: digest)
            ingressConsumers.projection = actual // before returned proof/actual Receipt ctor
            try actual.requireAssociation(request: request, attempt: attempt, ranges: self,
                store: store, operation: operation, scope: scope)
            try requirePreSeedWholeCurrentFrame(observer)
            ingressConsumers.settlementReturned = true
            return actual
        } catch { poisonIngressConsumers(error); throw error }
    }

    /// First call is an explicit one-way execution after permanent revocation;
    /// subsequent calls consume only the same actual checked readonly result.
    func requireIngressRootPolicyProjection(request: ColdEraseScratchIngressPolicyRequestV1,
        attempt: ColdEraseScratchIngressPolicyAttemptV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        do {
            guard heldScope === scope, ingressConsumers.request === request,
                  ingressConsumers.attempt === attempt, ingressConsumers.settlementReturned,
                  let projection = ingressConsumers.projection,
                  let effectScope = ingressConsumers.effectScope,
                  let observer = ingressConsumers.observer else { throw EraseIntentStoreError.invalidAuthority }
            try projection.requireAssociation(request: request, attempt: attempt, ranges: self,
                store: store, operation: operation, scope: scope)
            try effectScope.requireConsumedPolicyAttempt(attempt) // PURE permanent revoked proof
            if !projection.storage.successorEntered {
                projection.storage.successorEntered = true // no second entry/retry
                try requirePreSeedWholeCurrentFrame(observer)
                let window = try observer.captureSettledCurrent(attempt: attempt, effectScope: effectScope)
                projection.storage.settledWindow = window // before returned-resource postproof
                try window.requireAssociation(observer: observer, attempt: attempt, effectScope: effectScope,
                    ranges: self, store: store, operation: operation, scope: scope)
                guard try window.requireIngressDigest() == projection.projectedTreeDigest else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                try requirePreSeedWholeCurrentFrame(observer)
                projection.storage.successorReturned = true
            }
            try requireCompletedPreSeedIngressAssociation(observer: observer, operation: operation, scope: scope)
        } catch { poisonIngressConsumers(error); throw error }
    }

    /// Pure idempotent return to Birth. No execution, current read, maker,
    /// reused effect scope or Seed is entered by either method below.
    func requireSettledPreSeedIngressObserver(operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws -> ColdEraseScratchPreSeedWholeCurrentObserverV1 {
        guard let observer = ingressConsumers.observer else { throw EraseIntentStoreError.invalidAuthority }
        try requireCompletedPreSeedIngressAssociation(observer: observer, operation: operation, scope: scope)
        return observer
    }
    func requireCompletedPreSeedIngressAssociation(observer: ColdEraseScratchPreSeedWholeCurrentObserverV1,
        operation: EraseColdPreparationOperationV1, scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        try requireIngressConsumersMemory(operation: operation, scope: scope)
        guard ingressConsumers.observer === observer, ingressConsumers.prerequisiteReturned else {
            throw EraseIntentStoreError.invalidAuthority
        }
        if let absence = ingressConsumers.absence {
            guard ingressConsumers.request == nil, ingressConsumers.attempt == nil,
                  ingressConsumers.projection == nil, !ingressConsumers.settlementEntered else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try absence.requireBound(ranges: self, store: store, operation: operation, scope: scope)
        } else {
            guard let request = ingressConsumers.request, let attempt = ingressConsumers.attempt,
                  let effectScope = ingressConsumers.effectScope, let projection = ingressConsumers.projection,
                  ingressConsumers.settlementReturned, projection.storage.successorEntered,
                  projection.storage.successorReturned, let window = projection.storage.settledWindow else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try effectScope.requireConsumedPolicyAttempt(attempt)
            try projection.requireAssociation(request: request, attempt: attempt, ranges: self,
                store: store, operation: operation, scope: scope)
            try window.requireAssociation(observer: observer, attempt: attempt, effectScope: effectScope,
                ranges: self, store: store, operation: operation, scope: scope)
            guard try window.requireIngressDigest() == projection.projectedTreeDigest else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        try observer.requireAssociation(ranges: self, store: store, operation: operation, scope: scope)
    }
    fileprivate func requireIngressConsumersMemory(operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        guard self.operation === operation, heldScope === scope,
              ingressConsumers.entered, ingressConsumers.failure == nil,
              ingressConsumers.fixedCharge > 0, ingressConsumers.excessCharge == 0,
              state == .registered || state == .catalog || state == .bound,
              !oldScratchAccessFenced, postContentScope == nil, postContentTransfer == nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        // This is identity/retained-result proof only, not current authority.
    }
    fileprivate func requireIngressRequestAssociation(_ request: ColdEraseScratchIngressPolicyRequestV1) throws {
        try requireIngressConsumersMemory(operation: request.storage.operation, scope: request.storage.scope)
        guard ingressConsumers.request === request, ingressConsumers.observer === request.storage.observer,
              ingressConsumers.rawRoot === request.storage.root, catalogResource === request.storage.core,
              ingressConsumers.writer === request.storage.writer,
              request.storage.loan === preSeedWholeLoan else { throw EraseIntentStoreError.invalidAuthority }
    }
    fileprivate func requireIngressAbsenceAssociation(_ absence: ColdEraseScratchIngressRootAbsenceProjectionV1) throws {
        try requireIngressConsumersMemory(operation: absence.storage.operation, scope: absence.storage.scope)
        guard ingressConsumers.absence === absence, ingressConsumers.observer === absence.storage.observer,
              ingressConsumers.writer === absence.storage.writer, catalogResource === absence.storage.core,
              ingressConsumers.request == nil else { throw EraseIntentStoreError.invalidAuthority }
    }
    fileprivate func requireIngressProjectionAssociation(_ projection: ColdEraseScratchIngressRootPolicyProjectionV1) throws {
        let request = projection.storage.request
        try requireIngressRequestAssociation(request)
        guard ingressConsumers.projection === projection, ingressConsumers.attempt === projection.storage.attempt,
              ingressConsumers.effectScope === projection.storage.effectScope else {
