    fileprivate func requireIngressPrepaidAssociation(request: ColdEraseScratchIngressPolicyRequestV1) throws {
        try requireIngressRequestAssociation(request)
        guard ingressConsumers.prerequisiteReturned,
              ingressConsumers.pathCount == request.storage.normalizedApplicationSupportPathUTF8Count,
              ingressConsumers.fixedCharge == (try ColdEraseControlBinaryV1.adding(
                UInt64(MemoryLayout<IngressConsumersStorage>.stride),
                ColdEraseScratchIngressDeclaredBackingV1.required(pathCount: ingressConsumers.pathCount))),
              ingressConsumers.excessCharge == 0 else { throw EraseIntentStoreError.invalidAuthority }
        // Already prepaid under the actual live Range capacity/frame before
        // construction. This callback cannot perform another capacity IO scan.
    }
    /// Monotone failure DATA only; no frame, policy, observer, or allocation
    /// authority is consulted. Unknown/excess owners remain strongly retained.
    fileprivate func recordIngressFailureBacking(request: ColdEraseScratchIngressPolicyRequestV1,
        unknown: Bool) {
        guard ingressConsumers.request === request, !unknown,
              request.storage.mainArrayHighWater != UInt64.max,
              request.storage.attemptHighWater != UInt64.max else {
            ingressConsumers.excessCharge = UInt64.max
            return
        }
        do {
            let arrayLimit = try ColdEraseScratchIngressDeclaredBackingV1.mainArrayBytes()
            let attemptLimit = try ColdEraseScratchIngressPolicyAttemptV1.requiredBackingBytes(
                normalizedApplicationSupportPathUTF8Count: request.storage.normalizedApplicationSupportPathUTF8Count)
            let arrays = request.storage.mainArrayHighWater > arrayLimit ? request.storage.mainArrayHighWater - arrayLimit : 0
            let attempt = request.storage.attemptHighWater > attemptLimit ? request.storage.attemptHighWater - attemptLimit : 0
            let sum = arrays.addingReportingOverflow(attempt)
            ingressConsumers.excessCharge = sum.overflow ? UInt64.max : max(ingressConsumers.excessCharge, sum.partialValue)
        } catch { ingressConsumers.excessCharge = UInt64.max }
    }
    fileprivate func recordIngressReachedBacking(request: ColdEraseScratchIngressPolicyRequestV1) throws {
        guard ingressConsumers.request === request else { throw EraseIntentStoreError.invalidAuthority }
        let arrayLimit = try ColdEraseScratchIngressDeclaredBackingV1.mainArrayBytes()
        let attemptLimit = try ColdEraseScratchIngressPolicyAttemptV1.requiredBackingBytes(
            normalizedApplicationSupportPathUTF8Count: request.storage.normalizedApplicationSupportPathUTF8Count)
        let arrays = request.storage.mainArrayHighWater > arrayLimit ? request.storage.mainArrayHighWater - arrayLimit : 0
        let attempt = request.storage.attemptHighWater > attemptLimit ? request.storage.attemptHighWater - attemptLimit : 0
        let sum = arrays.addingReportingOverflow(attempt)
        ingressConsumers.excessCharge = sum.overflow ? UInt64.max : max(ingressConsumers.excessCharge, sum.partialValue)
        // Reached unknown/overflow is retained as an explicit sentinel, never
        // an estimate or a permission to allocate more. All owners remain live.
        guard !sum.overflow, ingressConsumers.excessCharge == 0 else { throw EraseIntentStoreError.invalidAuthority }
    }
    private func poisonIngressConsumers(_ error: Error) {
        if ingressConsumers.failure == nil { ingressConsumers.failure = error }
        ingressConsumers.request?.poison(error)
        ingressConsumers.effectScope?.poisonOnUncertainEffect()
        ingressConsumers.projection?.storage.failure = error
        poison()
    }
    // PRESEED_INGRESS_RANGE_CONSUMERS_V2_END

    private func retainedBackingBytes() throws -> UInt64 {
        var bytes = try ColdEraseControlBinaryV1.adding(initialProducerV4.charge, sourceIndexChargeBytes,
            indexChargeBytes, activeCatalogPathBytes, activeFirstPhysicalNodeChargeBytes,
            retainedFirstScratchRootNodeChargeBytes, activeFirstScratchRootLookupChargeBytes,
            activeBufferCount, secondBufferCount, activeParentLookupPathBytes,
            observedLinkChargeBytes, postContentTransferChargeBytes, transferredControlChargeBytes,
            readerJournalChargeV4, readerPublicationSourceChargeV4,
            namespaceCaptureReservationChargeBytes, capsulePublisherChargeBytes,
            publishedCanonicalInfrastructureChargeBytes, progressPublisherChargeBytes,
            publishedProgressInfrastructureChargeBytes,
            namespaceOriginalNodeWindowChargeBytes, notificationCanonicalRecordsChargeBytes,
            notificationObservationChargeBytes, notificationReadReservationChargeBytes,
            notificationReadReservation?.retainedBackingBytes ?? 0, coreBirthSourceChargeBytes,
            publishedResourceInstallationChargeBytes,
            publishedResourceInstallationResourceExcessBytes, birthRootReservationChargeBytes,
            ingressConsumers.fixedCharge, ingressConsumers.excessCharge,
            preSeedWholeObserverChargeBytes, preSeedWholeObserver?.storage.charge ?? 0,
            preSeedWholeObserver?.storage.rawBytes ?? 0,
            birthRootReservation?.storage.currentReadReservationChargeBytes ?? 0,
            birthRootReservation?.storage.traversalReservationChargeBytes ?? 0,
            publishedResourceInstallation?.excessBackingBytes ?? 0)
        // NAMESPACE_READER_CURRENT_CAPTURE_CHARGE_V4_BEGIN
        bytes = try ColdEraseControlBinaryV1.adding(bytes, namespaceReaderCaptureChargeV4)
        // NAMESPACE_READER_CURRENT_CAPTURE_CHARGE_V4_END
        // SCRATCH_FIRST_D0_BIRTH_IDENTITY_CHARGE_V2_BEGIN
        bytes = try ColdEraseControlBinaryV1.adding(bytes, birthIdentityChargeBytes,
            birthIdentityInitialization?.storage.directoryBackingBytes ?? 0)
        // SCRATCH_FIRST_D0_BIRTH_IDENTITY_CHARGE_V2_END
        if let capsulePublisher {
            bytes = try ColdEraseControlBinaryV1.adding(bytes, capsulePublisher.retainedBackingBytes)
        }
        if let progressPublisher {
            bytes = try ColdEraseControlBinaryV1.adding(bytes, progressPublisher.retainedBackingBytes)
        }
        if let namespaceCaptureReservation {
            bytes = try ColdEraseControlBinaryV1.adding(bytes,
                namespaceCaptureReservation.retainedMetadataBytes)
        }
        for resource in resources {
            bytes = try ColdEraseControlBinaryV1.adding(bytes, resource.retainedBufferBytes)
        }
        if let publishedCanonicalInfrastructure,
           !resources.contains(where: { $0 === publishedCanonicalInfrastructure }) {
            bytes = try ColdEraseControlBinaryV1.adding(bytes, publishedCanonicalInfrastructure.retainedBufferBytes)
        }
        if let publishedProgressInfrastructure,
           !resources.contains(where: { $0 === publishedProgressInfrastructure }) {
            bytes = try ColdEraseControlBinaryV1.adding(bytes, publishedProgressInfrastructure.retainedBufferBytes)
        }
        if let firstPhysicalCatalogScanner {
            bytes = try ColdEraseControlBinaryV1.adding(bytes, firstPhysicalCatalogScanner.retainedBackingBytes)
        }
        if let controlObserver {
            bytes = try ColdEraseControlBinaryV1.adding(bytes, controlObserver.retainedBufferBytes)
        }
        // SCRATCH_MUTABLE_PROGRESS_RANGE_CHARGE_V1_BEGIN
        bytes = try ColdEraseControlBinaryV1.adding(bytes, mutableProgressIOChargeBytes)
        bytes = try ColdEraseControlBinaryV1.adding(bytes, requestSemanticFixedCharge,
            requestSemanticRecipeCharge, requestSemanticOwner?.storage.bufferCharge ?? 0)
        // SCRATCH_MUTABLE_PROGRESS_RANGE_CHARGE_V1_END
        // Genuine fixed registration exists with Range; reached ownership,
        // both old/new readonly buffers and uncertain excess stay charged.
        bytes = try ColdEraseControlBinaryV1.adding(bytes,
            Self.durableObservationStoredBackingBytes,
            durableObservation.fixedCharge, durableObservation.bufferCharge,
            durableObservation.excessCharge,
            durableObservation.owner?.storage.excessCharge ?? 0,
            durableObservation.owner?.storage.oldReader.retainedBufferBytes ?? 0,
            durableObservation.owner?.storage.currentReader?.retainedBufferBytes ?? 0)
        bytes = try ColdEraseControlBinaryV1.adding(bytes, firstHistoryCharge)
        // POST_NAMESPACE_CURRENT_PERMANENT_CHARGES_V4_BEGIN
        bytes = try ColdEraseControlBinaryV1.adding(bytes,
            postNamespaceCurrentControlsV4.charge, postNamespaceCurrentControlsV4.consumerCharge)
        // POST_NAMESPACE_CURRENT_PERMANENT_CHARGES_V4_END
        return bytes
    }

    // This is the nonrecursive outside frame for the Store's actual observer.
    // Its held/named control checks never call their own capture recursively.
    fileprivate func requireCapsuleObservationFrame(
        _ observer: ColdEraseScratchControlObserverV1) throws {
        guard controlObserver === observer else { throw EraseIntentStoreError.invalidAuthority }
        try requireFrame()
    }

    fileprivate func requireScratchControlScopeAssociation(
        _ scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        guard heldScope === scope, state != .transferring, state != .postContent else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try requireFrame()
    }

    fileprivate func requireCapsuleObservationCapacity(
        _ observer: ColdEraseScratchControlObserverV1, bytes: UInt64) throws {
        try requireCapsuleObservationFrame(observer)
        guard bytes <= UInt64(ColdEraseControlBinaryV1.readChunkBytes) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try requireBackingCapacity(additionalBytes: bytes)
    }

    fileprivate func installControlObserver(store: EraseIntentStore,
        operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        support: Int32, erase: Int32, eraseURL: URL,
        directoryName: String, intentName: String,
        preparationName: String, auxiliaryName: String) throws {
        try requireStoreMemoryAssociation(store: store, operation: operation)
        guard heldScope === scope, controlObserver == nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let observer = ColdEraseScratchControlObserverV1(owner: self,
            store: store, operation: operation, scope: scope,
            support: support, erase: erase, eraseURL: eraseURL,
            directoryName: directoryName, intentName: intentName,
            preparationName: preparationName, auxiliaryName: auxiliaryName,
            first: firstControls, firstSupport: firstProjection.supportFact)
        controlObserver = observer // retain before its FIRST stat/open/read
        do { _ = try observer.capture() }
        catch { poison(); throw error }
    }

    fileprivate func currentControlCut(store: EraseIntentStore,
        operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws
        -> ColdEraseScratchCapsuleControlCutV1 {
        try requireStoreMemoryAssociation(store: store, operation: operation)
        guard heldScope === scope, let controlObserver else {
            throw EraseIntentStoreError.invalidAuthority
        }
        guard state != .transferring, state != .postContent else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return try controlObserver.capture()
    }

    private func requireBackingCapacity(additionalBytes: UInt64) throws {
        try requireFrame()
        if state == .transferring || state == .postContent {
            guard let transferredControlOwner else { throw EraseIntentStoreError.invalidAuthority }
            try transferredControlOwner.requireCapacity(additionalBytes: additionalBytes,
                retainedBytes: retainedBackingBytes())
            try requireFrame()
            return
        }
        try operation.requireColdScratchCapsuleCapacity(ranges: self, store: store,
            scope: heldScope, additionalBytes: additionalBytes,
            retainedBytes: retainedBackingBytes())
        try requireFrame()
    }

    func bindAttempt(_ attempt: OriginalEraseScratchCleanupAttemptV1,
        permit: ColdEraseScratchCleanupEffectPermitV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        do {
            try requireFrame()
            guard (state == .catalog || state == .bound), postContentTransfer == nil,
                  heldScope === scope,
                  self.attempt == nil || self.attempt === attempt,
                  self.permit == nil || self.permit === permit,
                  permit.ranges === self,
                  permit.admission.heldScope === scope else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try attempt.requireColdOrigin(permit: permit, ranges: self)
            self.attempt = attempt
            self.permit = permit
            state = .bound
            try requireFrame()
        } catch { poison(); throw error }
    }

    func requireBound(scope: ColdEraseScratchCleanupHeldGScopeV1,
        attempt: OriginalEraseScratchCleanupAttemptV1) throws {
        try requireFrame()
        guard state == .bound, heldScope === scope, self.attempt === attempt,
              let permit, permit.ranges === self,
              permit.admission.heldScope === scope else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try attempt.requireColdOrigin(permit: permit, ranges: self)
        try scope.requireNonrecursiveCurrentFrame()
    }

    // BEGIN AUTHENTIC CURRENT PENDING GENERATED RECIPE CONSUMER V1
    /// Returns only the SAME recipe owned by the actual published REQUEST.
    /// This method neither creates a range nor interprets a historical index.
    func generatedRange(task: ColdEraseScratchPendingTaskV1) throws
        -> ColdEraseScratchPayloadRangeV1? {
        do {
            guard state == .bound, pending === task,
                  task.ownerIdentity == ObjectIdentifier(self),
                  task.sequence > 0, task.sequence <= ColdEraseControlBinaryV1.maximumTaskCount,
                  let actualAttempt = attempt else { throw EraseIntentStoreError.invalidAuthority }
            try requireBound(scope: heldScope, attempt: actualAttempt)
            // Peer-owned checker proves the actual parser REQUEST/trailer,
            // consumed checked-write receipt, released windows and fresh
            // read-only whole-progress SHA/EOF/policy before returning DATA.
            let actual = try requireActualPublishedRequestRecipe(task: task)
            let tag: UInt64
            switch task.kind {
            case .pendingRepair: tag = 1
            case .hygieneReceipt: tag = 2
            case .hygieneFinalization: tag = 3
            case .terminalPublication: tag = 4
            case .abortedPublication: tag = 5
            case .oldEraseCompletion: tag = 6
            case .globalErasePreparation: tag = 7
            case .globalEraseCompletion: tag = 8
            case .scratchControlMarker: tag = 9
            case .leaseDirectoryRename, .firstLeafRemoval, .generatedLeafRemoval,
                 .firstDirectoryRemoval, .scratchRootRemoval, .ingressRootRemoval:
                guard actual == nil, task.recipe == nil, task.finalPath == nil else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                try requireBound(scope: heldScope, attempt: actualAttempt)
                return nil // authenticated structural REQUEST, never missing history
            }
            guard let actual else { throw EraseIntentStoreError.invalidAuthority }
            let (rangeID, rangeIDOverflow) = task.sequence.addingReportingOverflow(1)
            let (recipeOffset, recipeOffsetOverflow) = task.requestOffset.addingReportingOverflow(992)
            let (requestBytes, requestBytesOverflow) = actual.byteCount.addingReportingOverflow(1_024)
            guard !rangeIDOverflow, !recipeOffsetOverflow, !requestBytesOverflow,
                  task.recipe == actual, !actual.isDirectory,
                  actual.ownerIdentity == ObjectIdentifier(self), actual.storage == .progress,
                  actual.physicalOrdinal == nil, actual.progressSequence == task.sequence,
                  actual.rangeID == rangeID,
                  actual.sourceOrdinal == task.sequence, actual.roleOrdinal == tag,
                  actual.byteCount > 0,
                  actual.byteCount <= (tag == 9 ? ColdEraseControlBinaryV1.maximumRecipeBytes : 262_144),
                  actual.offset == recipeOffset,
                  task.requestByteCount == requestBytes,
                  task.finalPath == actual.originalPath else { throw EraseIntentStoreError.invalidAuthority }
            // firstFullFact keeps its genuine progress-file storage-origin
            // meaning from the peer's retained write receipt. No content-leaf
            // identity, policy acceptance or historical view is inferred.
            try requireBound(scope: heldScope, attempt: actualAttempt)
            return actual
        } catch { poison(); throw error }
    }
    // END AUTHENTIC CURRENT PENDING GENERATED RECIPE CONSUMER V1

    func firstSource(ordinal: UInt64,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        attempt: OriginalEraseScratchCleanupAttemptV1
    ) throws -> ColdEraseScratchPayloadRangeV1 {
        try requireBound(scope: scope, attempt: attempt)
        guard ordinal < selectedSourceCount, let index = selectedIndex(ordinal: ordinal) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return try sourceRange(index)
    }

    /// Immutable metadata lookup only. It never caches a filesystem or
    /// authorization result. The repeated genuine frame/byte checks remain.
    private func selectedIndex(ordinal: UInt64) -> ColdEraseCatalogSourceIndexV1? {
        var low = 0, high = sourceIndex.count
        while low < high {
            let middle = low + (high - low) / 2
            if sourceIndex[middle].selectedOrdinalBefore < ordinal { low = middle + 1 }
            else { high = middle }
        }
        while low < sourceIndex.count, sourceIndex[low].selectedOrdinalBefore == ordinal {
            if sourceIndex[low].isSelected {
                return sourceIndex[low].sourceOrdinal == ordinal ? sourceIndex[low] : nil
            }
            low += 1
        }
        return nil
    }

    func firstPhysicalOrdinal(path: String,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        attempt: OriginalEraseScratchCleanupAttemptV1) throws -> UInt64 {
        do {
            try requireBound(scope: scope, attempt: attempt)
            guard activeFirstPhysicalNode == nil,
                  !path.isEmpty, path.utf8.count <= 16_640 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            // The scanner/parser proves authentic canonical UTF-8 order
            // before installing this primitive index. Lookup is DATA only;
            // each comparison still reads the exact pinned catalog bytes.
            var low = 0, high = sourceIndex.count
            while low < high {
                let middle = low + (high - low) / 2
                let index = sourceIndex[middle]
                let actual = try retainedCatalogPath(index)
                let matches = actual == path
                let precedes = actual.utf8.lexicographicallyPrecedes(path.utf8)
                try requireBound(scope: scope, attempt: attempt)
                activeCatalogPath = nil; activeCatalogPathRawBytes = nil; activeCatalogPathBytes = 0
                if matches { return index.physicalOrdinal }
                if precedes { low = middle + 1 } else { high = middle }
            }
            throw EraseIntentStoreError.invalidAuthority
        } catch { poison(); throw error }
    }

    func firstPhysicalParentOrdinal(ordinal: UInt64,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        attempt: OriginalEraseScratchCleanupAttemptV1) throws -> UInt64? {
        do {
            try requireBound(scope: scope, attempt: attempt)
            guard activeFirstPhysicalNode == nil, activeParentLookupPath == nil,
                  activeParentLookupPathBytes == 0,
                  let position = Int(exactly: ordinal), position < sourceIndex.count,
                  sourceIndex[position].physicalOrdinal == ordinal else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let index = sourceIndex[position]
            let path = try retainedCatalogPath(index)
            if path == "ScratchDataV1" || path == "ProtectedIngressReceiptsV1" {
                guard index.isDirectory else { throw EraseIntentStoreError.invalidAuthority }
                try requireBound(scope: scope, attempt: attempt)
                activeCatalogPath = nil; activeCatalogPathRawBytes = nil; activeCatalogPathBytes = 0
                return nil // exactly these two first roots have Operations parent
            }
            guard let slash = path.lastIndex(of: "/") else { throw EraseIntentStoreError.invalidAuthority }
            try requireBackingCapacity(additionalBytes: index.pathByteCount)
            activeParentLookupPathBytes = index.pathByteCount // before derived String allocation
            activeParentLookupPath = String(path[..<slash])
            activeCatalogPath = nil; activeCatalogPathRawBytes = nil; activeCatalogPathBytes = 0
            let parent = try firstPhysicalOrdinal(path: activeParentLookupPath!, scope: scope, attempt: attempt)
            guard let parentPosition = Int(exactly: parent), parentPosition < sourceIndex.count,
                  sourceIndex[parentPosition].isDirectory else { throw EraseIntentStoreError.invalidAuthority }
            try requireBound(scope: scope, attempt: attempt)
            activeParentLookupPath = nil; activeParentLookupPathBytes = 0
            return parent
        } catch { poison(); throw error }
    }

    func requireRecipePlan(plan: ColdEraseScratchTaskRecipePlanV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        attempt: OriginalEraseScratchCleanupAttemptV1) throws {
        try requireBound(scope: scope, attempt: attempt)
        guard planning === plan, !plan.revoked, pending == nil,
              plan.ownerIdentity == ObjectIdentifier(self),
              plan.attemptIdentity == ObjectIdentifier(attempt),
              plan.scopeIdentity == ObjectIdentifier(scope),
              let planningImage else { throw EraseIntentStoreError.invalidAuthority }
        let current = try attempt.requireColdTaskCurrentPrefix(kind: plan.kind, source: plan.source)
        guard current == planningImage else { throw EraseIntentStoreError.invalidAuthority }
        if let source = plan.source { _ = try resource(for: source) }
        try requireBound(scope: scope, attempt: attempt)
    }

    /// One fixed pre-Attempt comparison loan for the cold Store constructor.
    /// It retains the genuine first catalog node and its charge through the
    /// actual Initial/Store consumer; current root absence never replaces it.
    func requireFirstScratchRootForColdStore(
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws -> ColdEraseScratchFirstNodeV1? {
        do {
            try requireFrame()
            guard heldScope === scope, state == .catalog, attempt == nil, permit == nil,
                  activeFirstPhysicalNode == nil, activeCatalogPath == nil,
                  activeCatalogPathRawBytes == nil, activeCatalogPathBytes == 0,
                  activeFirstScratchRootLookupChargeBytes == 0,
                  activeFirstScratchRootFirstNine == nil,
                  let catalogResource, let progressResource, let controlObserver,
                  resources.contains(where: { $0 === catalogResource }),
                  resources.contains(where: { $0 === progressResource }) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try catalogResource.requirePinned(); try progressResource.requirePinned()
            let cut = try controlObserver.capture()
            guard cut.coreSHA256 != nil, cut.progressSHA256 != nil,
                  cut.coreByteCount == catalogResource.byteCount,
                  cut.progressByteCount == progressResource.byteCount else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let lookupCharge = try ColdEraseControlBinaryV1.adding(
                UInt64(MemoryLayout<ColdEraseCatalogSourceIndexV1>.stride),
                UInt64(MemoryLayout<EraseSchema2ColdAuxiliaryPhysicalRosterV1.Node>.stride),
                2 * 11 * 21, UInt64(MemoryLayout<UInt64>.stride * 11))
            try requireBackingCapacity(additionalBytes: lookupCharge)
            activeFirstScratchRootLookupChargeBytes = lookupCharge
            let physical = try operation.requireColdScratchPhysicalRoster(store: store, scope: scope)
            var originalRoot: EraseSchema2ColdAuxiliaryPhysicalRosterV1.Node?
            var expectedPhysicalCount: UInt64 = 0
            var foundOperations = false
            for tree in physical.record.trees where tree.key == "support/FieldEvidenceOperations" {
                guard !foundOperations else { throw EraseIntentStoreError.invalidAuthority }
                foundOperations = true
                for node in tree.nodes ?? [] {
                    if node.path == "ScratchDataV1" {
                        guard originalRoot == nil, node.kind == "directory" else {
                            throw EraseIntentStoreError.invalidAuthority
                        }
                        originalRoot = node
                    }
                    if node.path == "ScratchDataV1" || node.path.hasPrefix("ScratchDataV1/")
                        || node.path == "ProtectedIngressReceiptsV1"
                        || node.path.hasPrefix("ProtectedIngressReceiptsV1/") {
                        expectedPhysicalCount = try ColdEraseControlBinaryV1.adding(expectedPhysicalCount, 1)
                    }
                }
            }
            guard foundOperations, expectedPhysicalCount == UInt64(sourceIndex.count) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            var selected: ColdEraseCatalogSourceIndexV1?
            for index in sourceIndex {
                let path = try retainedCatalogPath(index)
                if path == "ScratchDataV1" {
                    guard selected == nil, index.isDirectory, index.role == .physicalOnly,
                          index.sourceOrdinal == UInt64.max, index.rawByteCount == 0,
                          index.policyCode != 0, let originalRoot else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    let firstNine = "\(Int64(bitPattern: index.fact.device))|\(index.fact.inode)|\(index.fact.mode)|\(index.fact.links)|\(Int64(bitPattern: index.fact.size))|\(Int64(bitPattern: index.fact.modifiedSeconds))|\(Int64(bitPattern: index.fact.modifiedNanoseconds))|\(Int64(bitPattern: index.fact.changedSeconds))|\(Int64(bitPattern: index.fact.changedNanoseconds))"
                    activeFirstScratchRootFirstNine = firstNine
                    guard firstNine == originalRoot.fact else { throw EraseIntentStoreError.invalidAuthority }
                    selected = index
                }
                try requireFrame()
                activeCatalogPath = nil; activeCatalogPathRawBytes = nil; activeCatalogPathBytes = 0
            }
            guard (originalRoot == nil) == (selected == nil) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            if firstScratchRootLookupCompleted {
                guard (retainedFirstScratchRootNode == nil) == (selected == nil),
                      retainedFirstScratchRootNode?.ownerIdentity == nil
                        || retainedFirstScratchRootNode?.ownerIdentity == ObjectIdentifier(self),
                      retainedFirstScratchRootNode?.fullFact == selected?.fact.rendered else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            } else if let selected {
                // Full11 decimal rendering, its temporary scalar words and
                // one fixed path overlap with the actual returned DATA loan.
                let charge = try ColdEraseControlBinaryV1.adding(
                    UInt64(MemoryLayout<ColdEraseScratchFirstNodeV1>.stride),
                    UInt64("ScratchDataV1".utf8.count), 11 * 21,
                    UInt64(MemoryLayout<UInt64>.stride * 11))
                try requireBackingCapacity(additionalBytes: charge)
                retainedFirstScratchRootNodeChargeBytes = charge // before allocation
                let policy = try ColdEraseControlBinaryV1.policy(selected.policyCode, fact: selected.fact.words)
                retainedFirstScratchRootNode = try ColdEraseScratchFirstNodeV1(owner: self,
                    index: selected, path: "ScratchDataV1", policy: policy, selectedRange: nil)
            }
            try catalogResource.requirePinned(); try progressResource.requirePinned()
            let after = try controlObserver.capture()
            guard after.eraseRoot == cut.eraseRoot, after.names == cut.names,
                  after.coreSHA256 == cut.coreSHA256, after.coreByteCount == cut.coreByteCount,
                  after.progressSHA256 == cut.progressSHA256,
                  after.progressByteCount == cut.progressByteCount else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try requireFrame()
            firstScratchRootLookupCompleted = true
            activeFirstScratchRootFirstNine = nil; activeFirstScratchRootLookupChargeBytes = 0
            return retainedFirstScratchRootNode
        } catch { poison(); throw error }
    }

    /// Installed-Attempt consumer of the earlier authentic immutable loan.
    /// This does not discover a current survivor or mint a new first root.
    func requireRetainedFirstScratchRootForColdStore(node: ColdEraseScratchFirstNodeV1?,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        attempt: OriginalEraseScratchCleanupAttemptV1) throws {
        do {
            try requireBound(scope: scope, attempt: attempt)
            guard firstScratchRootLookupCompleted,
                  activeFirstScratchRootLookupChargeBytes == 0,
                  activeFirstScratchRootFirstNine == nil,
                  let catalogResource, let progressResource, let controlObserver else {
                throw EraseIntentStoreError.invalidAuthority
            }
            switch (node, retainedFirstScratchRootNode) {
            case (nil, nil):
                guard retainedFirstScratchRootNodeChargeBytes == 0 else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            case (.some(let node), .some(let retained)):
                guard retainedFirstScratchRootNodeChargeBytes > 0,
                      node.ownerIdentity == ObjectIdentifier(self),
                      retained.ownerIdentity == ObjectIdentifier(self),
                      node.physicalOrdinal == retained.physicalOrdinal,
                      node.path == "ScratchDataV1", node.path == retained.path,
                      node.fullFact == retained.fullFact, node.contentSHA256 == nil,
                      retained.contentSHA256 == nil, node.policy == retained.policy,
                      node.selectedRange == nil, retained.selectedRange == nil,
                      node.isDirectory, retained.isDirectory,
                      let ordinal = Int(exactly: retained.physicalOrdinal),
                      ordinal < sourceIndex.count else { throw EraseIntentStoreError.invalidAuthority }
                let index = sourceIndex[ordinal]
                guard index.physicalOrdinal == retained.physicalOrdinal,
                      index.isDirectory, index.role == .physicalOnly,
                      index.sourceOrdinal == UInt64.max, index.rawByteCount == 0,
                      index.fact.rendered == retained.fullFact,
                      try ColdEraseControlBinaryV1.policyCode(retained.policy) == index.policyCode else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            default: throw EraseIntentStoreError.invalidAuthority
            }
            try catalogResource.requirePinned(); try progressResource.requirePinned()
            let cut = try controlObserver.capture()
            guard cut.coreSHA256 != nil, cut.progressSHA256 != nil,
                  cut.coreByteCount == catalogResource.byteCount,
                  cut.progressByteCount == progressResource.byteCount else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try requireBound(scope: scope, attempt: attempt)
        } catch { poison(); throw error }
    }

    func firstSource(path: String,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        attempt: OriginalEraseScratchCleanupAttemptV1
    ) throws -> ColdEraseScratchPayloadRangeV1 {
        try requireBound(scope: scope, attempt: attempt)
        for index in sourceIndex where index.isSelected {
            let source = try sourceRange(index)
            if source.originalPath == path { return source }
        }
        throw EraseIntentStoreError.invalidAuthority
    }

    func canonicalSource(path: String, fullFact: String)
        throws -> ColdEraseScratchPayloadRangeV1 {
        try requireFrame()
        for index in sourceIndex where index.isSelected {
            let source = try sourceRange(index)
            if source.originalPath == path {
                guard source.firstFullFact == fullFact else { throw EraseIntentStoreError.invalidAuthority }
                return source
            }
        }
        throw EraseIntentStoreError.invalidAuthority
    }

    private func sourceRange(_ index: ColdEraseCatalogSourceIndexV1)
        throws -> ColdEraseScratchPayloadRangeV1 {
        do {
            try requireFrame()
            guard index.isSelected, index.sourceOrdinal < selectedSourceCount,
                  activeFirstPhysicalNode == nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let path = try retainedCatalogPath(index)
            try requireFrame()
            let expected = try ColdEraseControlBinaryV1.catalogRole(path: path)
            guard expected.role == index.role, expected.version == index.semanticVersion,
                  index.rawByteCount <= (try ColdEraseControlBinaryV1.catalogReaderLimit(path: path)) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let range = ColdEraseScratchPayloadRangeV1(owner: self,
                rangeID: index.sourceOrdinal, sourceOrdinal: index.sourceOrdinal,
                roleOrdinal: index.role.rawValue, byteCount: index.rawByteCount,
                sha256: try index.digest.hex(), originalPath: path,
                firstFullFact: index.fact.rendered, isDirectory: index.role == .leaseDirectory,
                offset: index.rawOffset, storage: .catalog,
                physicalOrdinal: index.physicalOrdinal)
            try requireFrame()
            activeCatalogPath = nil; activeCatalogPathRawBytes = nil; activeCatalogPathBytes = 0
            return range
        } catch { poison(); throw error }
    }

    private func retainedCatalogPath(_ index: ColdEraseCatalogSourceIndexV1) throws -> String {
        try requireFrame()
        guard activeCatalogPathBytes == 0, activeCatalogPath == nil, activeCatalogPathRawBytes == nil,
              index.pathByteCount > 0, index.pathByteCount <= 16_640,
              let count = Int(exactly: index.pathByteCount),
              let catalogResource, resources.contains(where: { $0 === catalogResource }) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        // The raw UTF-8 window and decoded path coexist during exact decode.
        let charge = try ColdEraseControlBinaryV1.multiplying(index.pathByteCount, 2)
        try requireBackingCapacity(additionalBytes: charge)
        activeCatalogPathBytes = charge
        activeCatalogPathRawBytes = try catalogResource.readExactly(offset: index.pathOffset, count: count)
        guard let path = String(data: activeCatalogPathRawBytes!, encoding: .utf8),
              path.utf8.elementsEqual(activeCatalogPathRawBytes!),
              !path.hasPrefix("/"), !path.hasSuffix("/"),
              !path.split(separator: "/", omittingEmptySubsequences: false)
                .contains(where: { $0.isEmpty || $0 == "." || $0 == ".." || $0.utf8.count > 255 }),
              path.split(separator: "/", omittingEmptySubsequences: false).count <= 65,
              path == "ScratchDataV1" || path.hasPrefix("ScratchDataV1/")
                || path == "ProtectedIngressReceiptsV1" || path.hasPrefix("ProtectedIngressReceiptsV1/") else {
            throw EraseIntentStoreError.invalidAuthority
        }
        activeCatalogPath = path // retained on every later refusal
        try requireFrame()
        return path
    }

    func withFirstPhysicalNode<T>(ordinal: UInt64,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        attempt: OriginalEraseScratchCleanupAttemptV1,
        _ body: (ColdEraseScratchFirstNodeV1) throws -> T) throws -> T {
        do {
            try requireBound(scope: scope, attempt: attempt)
            guard activeFirstPhysicalNode == nil, activeFirstPhysicalNodeChargeBytes == 0,
                  let offset = Int(exactly: ordinal), offset < sourceIndex.count,
                  sourceIndex[offset].physicalOrdinal == ordinal else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let index = sourceIndex[offset]
            // Reserve the one returned DTO plus full-fact/SHA and selected
            // Range metadata before any DTO/String allocation. Path charge
            // is separate and precedes the bounded actual catalog read.
            let charge = try ColdEraseControlBinaryV1.adding(
                UInt64(MemoryLayout<ColdEraseScratchFirstNodeV1>.stride),
                UInt64(MemoryLayout<ColdEraseScratchPayloadRangeV1>.stride), 512, 64)
            try requireBackingCapacity(additionalBytes: charge)
            activeFirstPhysicalNodeChargeBytes = charge
            let path = try retainedCatalogPath(index)
            let policy = try ColdEraseControlBinaryV1.policy(index.policyCode, fact: index.fact.words)
            let selected: ColdEraseScratchPayloadRangeV1?
            if index.isSelected {
                let role = try ColdEraseControlBinaryV1.catalogRole(path: path)
                guard role.role == index.role, role.version == index.semanticVersion,
                      index.rawByteCount <= (try ColdEraseControlBinaryV1.catalogReaderLimit(path: path)) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                selected = ColdEraseScratchPayloadRangeV1(owner: self,
                    rangeID: index.sourceOrdinal, sourceOrdinal: index.sourceOrdinal,
                    roleOrdinal: index.role.rawValue, byteCount: index.rawByteCount,
                    sha256: try index.digest.hex(), originalPath: path,
                    firstFullFact: index.fact.rendered, isDirectory: index.isDirectory,
                    offset: index.rawOffset, storage: .catalog,
                    physicalOrdinal: index.physicalOrdinal)
            } else {
                guard index.role == .physicalOnly, index.semanticVersion == 0,
                      index.sourceOrdinal == UInt64.max, index.rawByteCount == 0 else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                selected = nil
            }
            activeFirstPhysicalNode = try ColdEraseScratchFirstNodeV1(owner: self,
                index: index, path: path, policy: policy, selectedRange: selected)
            try requireBound(scope: scope, attempt: attempt)
            let value = try body(activeFirstPhysicalNode!)
            try requireBound(scope: scope, attempt: attempt)
            // The closed structural callbacks return Void and retain no DTO,
            // path, range or policy alias. Any throw retains this exact node
            // and both charges and permanently poisons the enclosing owner.
            activeFirstPhysicalNode = nil
            activeFirstPhysicalNodeChargeBytes = 0
            activeCatalogPath = nil; activeCatalogPathRawBytes = nil; activeCatalogPathBytes = 0
            return value
        } catch { poison(); throw error }
    }

