    func streamingSHA256(range: ColdEraseScratchPayloadRangeV1,
        prefixCount: UInt64?) throws -> String {
        do {
            try requireFrame()
            let count = prefixCount ?? range.byteCount
            guard count <= range.byteCount else { throw EraseIntentStoreError.invalidAuthority }
            let resource = try resource(for: range)
            var hasher = SHA256()
            var offset: UInt64 = 0
            while offset < count {
                try requireFrame()
                let wanted = Int(min(UInt64(ColdEraseControlBinaryV1.readChunkBytes), count - offset))
                hasher.update(data: try resource.readExactly(
                    offset: ColdEraseControlBinaryV1.adding(range.offset, offset), count: wanted))
                offset = try ColdEraseControlBinaryV1.adding(offset, UInt64(wanted))
            }
            try resource.requirePinned()
            try requireFrame()
            return hasher.finalize().map { String(format: "%02x", $0) }.joined()
        } catch { poison(); throw error }
    }

    private func indexCharge(capacity: UInt64, stride: UInt64,
        utf8: UInt64, auxiliary: UInt64) throws -> UInt64 {
        try ColdEraseControlBinaryV1.adding(
            ColdEraseControlBinaryV1.multiplying(capacity, stride), utf8, auxiliary)
    }

    func reserveMechanicsIndex(kind: ColdEraseScratchMechanicsIndexKindV1,
        minimumCapacity: UInt64, elementStride: UInt64,
        retainedUTF8Bytes: UInt64, retainedAuxiliaryStorageBytes: UInt64 = 0,
        attempt: OriginalEraseScratchCleanupAttemptV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1)
        throws -> ColdEraseScratchMechanicsIndexLeaseV1 {
        do {
            try requireBound(scope: scope, attempt: attempt)
            guard elementStride > 0 else { throw EraseIntentStoreError.invalidAuthority }
            let charge = try indexCharge(capacity: minimumCapacity, stride: elementStride,
                utf8: retainedUTF8Bytes, auxiliary: retainedAuxiliaryStorageBytes)
            try requireBackingCapacity(additionalBytes: charge)
            let next = try ColdEraseControlBinaryV1.adding(indexChargeBytes, charge)
            let lease = ColdEraseScratchMechanicsIndexLeaseV1(owner: self, kind: kind,
                minimumCapacity: minimumCapacity, elementStride: elementStride,
                retainedUTF8Bytes: retainedUTF8Bytes, attempt: attempt, scope: scope)
            lease.retainedAuxiliaryStorageBytes = retainedAuxiliaryStorageBytes
            // Retain/charge BEFORE the backing reserve/insert. Old and new
            // leases coexist during a resize; an uncertain lease is permanent.
            retainedIndexLeases.append(lease)
            indexChargeBytes = next
            try requireBound(scope: scope, attempt: attempt)
            return lease
        } catch { poison(); throw error }
    }

    func recordMechanicsIndex(lease: ColdEraseScratchMechanicsIndexLeaseV1,
        actualCapacity: UInt64, retainedUTF8Bytes: UInt64,
        retainedAuxiliaryStorageBytes: UInt64 = 0,
        attempt: OriginalEraseScratchCleanupAttemptV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        do {
            try requireBound(scope: scope, attempt: attempt)
            guard retainedIndexLeases.contains(where: { $0 === lease }), !lease.released,
                  lease.ownerIdentity == ObjectIdentifier(self),
                  lease.attemptIdentity == ObjectIdentifier(attempt),
                  lease.scopeIdentity == ObjectIdentifier(scope),
                  actualCapacity >= lease.minimumCapacity else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let old = try indexCharge(capacity: lease.actualCapacity ?? lease.minimumCapacity,
                stride: lease.elementStride, utf8: lease.retainedUTF8Bytes,
                auxiliary: lease.retainedAuxiliaryStorageBytes)
            let new = try indexCharge(capacity: actualCapacity, stride: lease.elementStride,
                utf8: retainedUTF8Bytes, auxiliary: retainedAuxiliaryStorageBytes)
            guard new >= old else { throw EraseIntentStoreError.invalidAuthority }
            try requireBackingCapacity(additionalBytes: new - old)
            indexChargeBytes = try ColdEraseControlBinaryV1.adding(indexChargeBytes, new - old)
            lease.actualCapacity = actualCapacity
            lease.retainedUTF8Bytes = retainedUTF8Bytes
            lease.retainedAuxiliaryStorageBytes = retainedAuxiliaryStorageBytes
            try requireBound(scope: scope, attempt: attempt)
        } catch { poison(); throw error }
    }

    func releaseMechanicsIndex(lease: ColdEraseScratchMechanicsIndexLeaseV1,
        attempt: OriginalEraseScratchCleanupAttemptV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        do {
            try requireBound(scope: scope, attempt: attempt)
            guard retainedIndexLeases.contains(where: { $0 === lease }), !lease.released,
                  lease.ownerIdentity == ObjectIdentifier(self),
                  lease.attemptIdentity == ObjectIdentifier(attempt),
                  lease.scopeIdentity == ObjectIdentifier(scope) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            // This actual private engine call proves its concrete backing and
            // aliases are gone after checked outcome/readback consumption and
            // natural scope revoke. A caller Boolean cannot discharge it.
            try attempt.requireColdMechanicsIndexRelease(lease: lease)
            let charge = try indexCharge(capacity: lease.actualCapacity ?? lease.minimumCapacity,
                stride: lease.elementStride, utf8: lease.retainedUTF8Bytes,
                auxiliary: lease.retainedAuxiliaryStorageBytes)
            guard charge <= indexChargeBytes else { throw EraseIntentStoreError.invalidAuthority }
            try requireBound(scope: scope, attempt: attempt)
            lease.released = true
            indexChargeBytes -= charge
            // No future consumer may retain this backing after the actual
            // release checker. Keep uncertain leases, but compact checked
            // discharged records so live policy windows do not accumulate.
            retainedIndexLeases.removeAll(where: { $0 === lease })
        } catch { poison(); throw error }
    }

    func requireScratchTasksSettled(attempt: OriginalEraseScratchCleanupAttemptV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        try requireBound(scope: scope, attempt: attempt)
        guard planning == nil, pending == nil,
              activeBufferRange == nil, secondBufferRange == nil,
              activeBufferAttempt == nil, activeRawBuffer == nil,
              secondRawBuffer == nil, activeFirstPhysicalNode == nil,
              activeFirstPhysicalNodeChargeBytes == 0,
              activeCatalogPath == nil, activeCatalogPathRawBytes == nil,
              activeCatalogPathBytes == 0, activeParentLookupPath == nil,
              activeParentLookupPathBytes == 0, planningImage == nil,
              pendingPrimitiveIntent == nil, pendingPrimitiveOutcome == nil,
              observedLinks.isEmpty, observedLinkChargeBytes == 0,
              activeFirstScratchRootLookupChargeBytes == 0,
              activeFirstScratchRootFirstNine == nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try attempt.requireCheckedSettlement()
        try requireBound(scope: scope, attempt: attempt)
    }

    /// Prepare while the actual borrowed parent interval is still live.
    /// Nothing is reconstructed from the receipt's scalar fields, and the
    /// unfinished maker's nil core/progress cut cannot issue this receipt.
    func preparePostContentTransfer(postScope: ColdEraseSchema2PostContentScopeV1,
        receipt: ColdEraseScratchCleanupReceiptV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws
        -> ColdEraseSchema2PostContentTransferReceiptV1 {
        do {
            try requireScratchTasksSettled(attempt: receipt.attempt, scope: scope)
            guard postContentScope == nil, postContentTransfer == nil,
                  transferLoan == nil, postContentTransferChargeBytes == 0,
                  let permit, let catalogResource, let progressResource,
                  let controlObserver, indexChargeBytes == 0,
                  retainedIndexLeases.isEmpty, resources.count == 2,
                  resources.contains(where: { $0 === catalogResource }),
                  resources.contains(where: { $0 === progressResource }),
                  catalogResource !== progressResource,
                  receipt.finalImage.scratch == nil, receipt.finalImage.ingress == nil,
                  let currentStateSHA256 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            _ = try ColdEraseControlBinaryV1.rawSHA256(currentStateSHA256)
            try receipt.requireBound(permit: permit, attempt: receipt.attempt,
                finalImage: receipt.finalImage)
            try permit.requireCheckedBorrowedSettlement()
            try postScope.requireTransferPreparation(ranges: self, store: store,
                operation: operation, from: scope)
            let loan = try operation.requireColdScratchCapsuleBorrowedParents(
                ranges: self, store: store, scope: scope)
            try loan.requireBound(operation: operation, scope: scope)
            try catalogResource.requirePinned(); try progressResource.requirePinned()
            let transferredOwner = try prepareTransferredControlOwner(to: postScope)
            let cut = try transferredOwner.capture()
            try cut.requireTransferredIssuer(transferredOwner)
            guard let coreSHA = cut.coreSHA256, let coreCount = cut.coreByteCount,
                  let progressSHA = cut.progressSHA256, let progressCount = cut.progressByteCount,
                  coreCount == catalogResource.byteCount,
                  progressCount == progressResource.byteCount,
                  progressCount == lastCompleteProgressOffset,
                  progressCount == 64 || lastCompleteFrameSHA256 != nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
            _ = try ColdEraseControlBinaryV1.rawSHA256(coreSHA)
            _ = try ColdEraseControlBinaryV1.rawSHA256(progressSHA)
            let charge = ColdEraseSchema2PostContentTransferReceiptV1.backingBytes
            try requireBackingCapacity(additionalBytes: charge)
            postContentTransferChargeBytes = charge // before the concrete owner allocation
            let transfer = ColdEraseSchema2PostContentTransferReceiptV1(.init(
                ranges: self, store: store, operation: operation, from: scope,
                to: postScope, loan: loan, contentReceipt: receipt,
                catalog: catalogResource, progress: progressResource, cut: cut))
            transferLoan = loan; postContentScope = postScope
            postContentTransfer = transfer // before any post-allocation throwing reproof
            try transfer.requirePrepared(ranges: self, store: store,
                operation: operation, from: scope, to: postScope)
            return transfer
        } catch { poison(); throw error }
    }

    // Main's actual body returned while the SAME loan/G are still held.
    // Keep the real returned Scope before every throwing return proof.
    fileprivate func completeInitialColdScratchMainReturnV4(
        _ successor: ColdEraseSchema2PostContentScopeV1) throws {
        guard initialProducerV4.phase == .bodyEntered,
              initialProducerV4.failure == nil, initialProducerV4.returnedScope == nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        initialProducerV4.returnedScope = successor
        guard state == .bound, postContentScope === successor,
              let transfer = postContentTransfer else { throw EraseIntentStoreError.invalidAuthority }
        try transfer.requirePrepared(ranges: self, store: store,
            operation: operation, from: heldScope, to: successor)
        initialProducerV4.phase = .returned
    }

    fileprivate func requirePreparedPostContentTransfer(
        _ transfer: ColdEraseSchema2PostContentTransferReceiptV1,
        store: EraseIntentStore, operation: EraseColdPreparationOperationV1,
        from scope: ColdEraseScratchCleanupHeldGScopeV1,
        to postScope: ColdEraseSchema2PostContentScopeV1) throws {
        guard state == .bound, self.store === store, self.operation === operation,
              heldScope === scope, postContentScope === postScope,
              postContentTransfer === transfer, transferLoan === transfer.backing.loan,
              catalogResource === transfer.backing.catalog,
              progressResource === transfer.backing.progress,
              postContentTransferChargeBytes == ColdEraseSchema2PostContentTransferReceiptV1.backingBytes else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try transfer.requireCommitAssociation(ranges: self, store: store,
            operation: operation, from: scope, to: postScope)
        try requireScratchTasksSettled(attempt: transfer.backing.contentReceipt.attempt,
            scope: scope)
        try transfer.backing.loan.requireBound(operation: operation, scope: scope)
        try requireTransferControlCut(transfer)
    }

    private func requireTransferControlCut(_ transfer: ColdEraseSchema2PostContentTransferReceiptV1) throws {
        guard postContentTransfer === transfer, let controlObserver,
              resources.count == 2, catalogResource === transfer.backing.catalog,
              progressResource === transfer.backing.progress,
              resources.contains(where: { $0 === transfer.backing.catalog }),
              resources.contains(where: { $0 === transfer.backing.progress }),
              planning == nil, pending == nil, pendingPrimitiveIntent == nil,
              pendingPrimitiveOutcome == nil, activeRawBuffer == nil, secondRawBuffer == nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try transfer.backing.catalog.requirePinned(); try transfer.backing.progress.requirePinned()
        let current = try captureTransferredCurrentControlCut(), expected = transfer.backing.cut
        guard expected.coreSHA256 != nil, expected.progressSHA256 != nil,
              current.eraseRoot == expected.eraseRoot, current.names == expected.names,
              current.coreSHA256 == expected.coreSHA256,
              current.coreByteCount == expected.coreByteCount,
              current.progressSHA256 == expected.progressSHA256,
              current.progressByteCount == expected.progressByteCount,
              current.progressByteCount == lastCompleteProgressOffset else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try transfer.backing.catalog.requirePinned(); try transfer.backing.progress.requirePinned()
    }

    /// Called after the real loan has positively revoked, while original G
    /// is still held. The prepared objects retain the same infrastructure;
    /// the revoked Coordinator loan is never used for IO or capacity.
    func commitPostContentTransfer(postScope: ColdEraseSchema2PostContentScopeV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        do {
            guard state == .bound, heldScope === scope, postContentScope === postScope,
                  let transfer = postContentTransfer, let transferLoan else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try transfer.requireCommitAssociation(ranges: self, store: store,
                operation: operation, from: scope, to: postScope)
            try operation.requireColdPostContentTransferFrame(postScope,
                ranges: self, store: store, scope: scope)
            try transferLoan.requireCheckedColdScratchLoanRevoked(operation: operation, scope: scope)
            try scope.requireNonrecursiveCurrentFrame()
            oldScratchAccessFenced = true
            state = .transferring // old Scratch methods permanently refuse before reproof IO
            try requireTransferControlCut(transfer)
            try transfer.recordTransferred(ranges: self, store: store,
                operation: operation, from: scope, to: postScope)
            state = .postContent // no IO until true postScope activation succeeds
            try transfer.requireTransferred(to: postScope)
        } catch { poison(); throw error }
    }

    fileprivate func requireTransferredPostContentAssociation(
        _ transfer: ColdEraseSchema2PostContentTransferReceiptV1,
        to postScope: ColdEraseSchema2PostContentScopeV1) throws {
        guard state == .postContent, postContentScope === postScope,
              oldScratchAccessFenced,
              postContentTransfer === transfer, transferLoan === transfer.backing.loan,
              transfer.backing.ranges === self, transfer.backing.store === store,
              transfer.backing.operation === operation, transfer.backing.from === heldScope,
              catalogResource === transfer.backing.catalog,
              progressResource === transfer.backing.progress, resources.count == 2,
              resources.contains(where: { $0 === transfer.backing.catalog }),
              resources.contains(where: { $0 === transfer.backing.progress }),
              transfer.backing.catalog.state == .open, transfer.backing.progress.state == .open,
              postContentTransferChargeBytes == ColdEraseSchema2PostContentTransferReceiptV1.backingBytes,
              planning == nil, pending == nil, pendingPrimitiveIntent == nil,
              pendingPrimitiveOutcome == nil, uncertainPolicyDescriptors.isEmpty else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    func releaseMechanicsIndexes(attempt: OriginalEraseScratchCleanupAttemptV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        try requireScratchTasksSettled(attempt: attempt, scope: scope)
        while let lease = retainedIndexLeases.first {
            try releaseMechanicsIndex(lease: lease, attempt: attempt, scope: scope)
        }
        guard indexChargeBytes == 0 else { throw EraseIntentStoreError.invalidAuthority }
        try requireBound(scope: scope, attempt: attempt)
    }

    private func resource(for range: ColdEraseScratchPayloadRangeV1)
        throws -> ColdEraseRetainedControlFileV1 {
        guard range.ownerIdentity == ObjectIdentifier(self), !range.isDirectory else {
            throw EraseIntentStoreError.invalidAuthority
        }
        if range.storage == .progress, let historical = try firstHistoryResource(for: range) {
            return historical // exact registered raw REQUEST/OBS/resource owner, not settled.contains
        }
        let resource = range.storage == .catalog ? catalogResource : progressResource
        guard let resource, resources.contains(where: { $0 === resource }),
              range.offset <= resource.byteCount,
              range.byteCount <= resource.byteCount - range.offset else {
            throw EraseIntentStoreError.invalidAuthority
        }
        if range.storage == .catalog {
            guard let ordinal = range.physicalOrdinal, let physical = Int(exactly: ordinal),
                  physical < sourceIndex.count else { throw EraseIntentStoreError.invalidAuthority }
            let index = sourceIndex[physical]
            guard index.physicalOrdinal == ordinal, index.isSelected,
                  index.sourceOrdinal == range.sourceOrdinal,
                  range.rangeID == index.sourceOrdinal, range.roleOrdinal == index.role.rawValue,
                  range.offset == index.rawOffset, range.byteCount == index.rawByteCount,
                  range.firstFullFact == index.fact.rendered,
                  range.sha256 == (try index.digest.hex()),
                  UInt64(range.originalPath.utf8.count) == index.pathByteCount,
                  index.pathByteCount <= 16_640,
                  let count = Int(exactly: index.pathByteCount) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let actualPath = try resource.readExactly(offset: index.pathOffset, count: count)
            guard range.originalPath.utf8.elementsEqual(actualPath),
                  range.byteCount <= (try ColdEraseControlBinaryV1.catalogReaderLimit(path: range.originalPath)) else {
                throw EraseIntentStoreError.invalidAuthority
            }
        } else {
            // A progress selector is usable only while its exact authenticated
            // REQUEST belongs to this same privately retained Pending/Settled.
            guard let sequence = range.progressSequence,
                  ((pending?.recipe == range && pending?.sequence == sequence)
                    || settled.contains(where: { $0.recipe == range && $0.sequence == sequence })) else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        return resource
    }

    /// The generic callback is private engine DATA delivery only. Its closed
    /// call graph must return decoded semantic values, never a Data alias.
    func withCanonicalBytes<T>(range: ColdEraseScratchPayloadRangeV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        attempt: OriginalEraseScratchCleanupAttemptV1,
        _ body: (Data) throws -> T) throws -> T {
        do {
            try requireBound(scope: scope, attempt: attempt)
            guard activeBufferRange == nil, secondBufferRange == nil,
                  activeRawBuffer == nil, secondRawBuffer == nil,
                  range.byteCount <= ColdEraseControlBinaryV1.maximumRangeWindowBytes,
                  let count = Int(exactly: range.byteCount) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let resource = try resource(for: range)
            try requireBackingCapacity(additionalBytes: range.byteCount)
            activeBufferRange = range
            activeBufferCount = range.byteCount
            activeBufferAttempt = ObjectIdentifier(attempt)
            activeRawBuffer = Data(count: count) // actual owner before the first read
            var offset: UInt64 = 0
            while offset < range.byteCount {
                try requireBound(scope: scope, attempt: attempt)
                let wanted = Int(min(UInt64(ColdEraseControlBinaryV1.readChunkBytes),
                    range.byteCount - offset))
                let chunk = try resource.readExactly(
                    offset: ColdEraseControlBinaryV1.adding(range.offset, offset),
                    count: wanted)
                activeRawBuffer!.replaceSubrange(Int(offset)..<(Int(offset) + wanted), with: chunk)
                offset = try ColdEraseControlBinaryV1.adding(offset, UInt64(wanted))
            }
            guard StoreMigrationCanonicalJSONV1.sha256(activeRawBuffer!) == range.sha256 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let value = try body(activeRawBuffer!)
            try requireExactBytes(range: range, bytes: activeRawBuffer!, scope: scope, attempt: attempt)
            try requireBound(scope: scope, attempt: attempt)
            // Only a successful closed semantic callback/full exact reproof
            // releases the actual buffer. Failure keeps buffer and charge.
            activeRawBuffer = nil
            activeBufferRange = nil; activeBufferCount = 0; activeBufferAttempt = nil
            return value
        } catch { poison(); throw error }
    }

    func requireExactBytes(range: ColdEraseScratchPayloadRangeV1, bytes: Data,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        attempt: OriginalEraseScratchCleanupAttemptV1) throws {
        try requireBound(scope: scope, attempt: attempt)
        guard UInt64(bytes.count) == range.byteCount,
              activeBufferAttempt == ObjectIdentifier(attempt),
              ((activeBufferRange == range && activeBufferCount == range.byteCount)
                || (secondBufferRange == range && secondBufferCount == range.byteCount)) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let resource = try resource(for: range)
        var offset: UInt64 = 0
        while offset < range.byteCount {
            let count = Int(min(UInt64(ColdEraseControlBinaryV1.readChunkBytes),
                range.byteCount - offset))
            let chunk = try resource.readExactly(
                offset: ColdEraseControlBinaryV1.adding(range.offset, offset), count: count)
            let start = bytes.startIndex + Int(offset)
            guard bytes[start..<(start + count)].elementsEqual(chunk) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try requireBound(scope: scope, attempt: attempt)
            offset = try ColdEraseControlBinaryV1.adding(offset, UInt64(count))
        }
        try resource.requirePinned()
        try requireBound(scope: scope, attempt: attempt)
    }

    /// Two simultaneously charged raw values are needed only for the incumbent
    /// finalized-hygiene relation. Neither value nor an alias may escape this
    /// private synchronous semantic callback. All other loaders remain single.
    func withCanonicalPairBytes<T>(first: ColdEraseScratchPayloadRangeV1,
        second: ColdEraseScratchPayloadRangeV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        attempt: OriginalEraseScratchCleanupAttemptV1,
        _ body: (Data, Data) throws -> T) throws -> T {
        do {
            try requireBound(scope: scope, attempt: attempt)
            guard first != second, activeBufferRange == nil, secondBufferRange == nil,
                  activeRawBuffer == nil, secondRawBuffer == nil,
                  first.byteCount <= 262_144, second.byteCount <= 262_144,
                  let firstCount = Int(exactly: first.byteCount),
                  let secondCount = Int(exactly: second.byteCount) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let pairBytes = try ColdEraseControlBinaryV1.adding(first.byteCount, second.byteCount)
            let firstResource = try resource(for: first)
            let secondResource = try resource(for: second)
            try requireBackingCapacity(additionalBytes: pairBytes)
            // Both charges precede either allocation or read. On uncertainty
            // the enclosing owner is poisoned; it cannot enter another loader.
            activeBufferRange = first; activeBufferCount = first.byteCount
            secondBufferRange = second; secondBufferCount = second.byteCount
            activeBufferAttempt = ObjectIdentifier(attempt)
            activeRawBuffer = Data(count: firstCount)
            secondRawBuffer = Data(count: secondCount)
            func load(_ range: ColdEraseScratchPayloadRangeV1,
                _ resource: ColdEraseRetainedControlFileV1, firstBuffer: Bool) throws {
                var offset: UInt64 = 0
                while offset < range.byteCount {
                    try requireBound(scope: scope, attempt: attempt)
                    let wanted = Int(min(UInt64(ColdEraseControlBinaryV1.readChunkBytes),
                        range.byteCount - offset))
                    let chunk = try resource.readExactly(
                        offset: ColdEraseControlBinaryV1.adding(range.offset, offset),
                        count: wanted)
                    if firstBuffer {
                        activeRawBuffer!.replaceSubrange(Int(offset)..<(Int(offset) + wanted), with: chunk)
                    } else {
                        secondRawBuffer!.replaceSubrange(Int(offset)..<(Int(offset) + wanted), with: chunk)
                    }
                    offset = try ColdEraseControlBinaryV1.adding(offset, UInt64(wanted))
                }
                guard StoreMigrationCanonicalJSONV1.sha256(firstBuffer ? activeRawBuffer! : secondRawBuffer!) == range.sha256 else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            try load(first, firstResource, firstBuffer: true)
            try load(second, secondResource, firstBuffer: false)
            try requireExactBytes(range: first, bytes: activeRawBuffer!, scope: scope, attempt: attempt)
            try requireExactBytes(range: second, bytes: secondRawBuffer!, scope: scope, attempt: attempt)
            let value = try body(activeRawBuffer!, secondRawBuffer!)
            try requireExactBytes(range: first, bytes: activeRawBuffer!, scope: scope, attempt: attempt)
            try requireExactBytes(range: second, bytes: secondRawBuffer!, scope: scope, attempt: attempt)
            try requireBound(scope: scope, attempt: attempt)
            activeRawBuffer = nil; secondRawBuffer = nil
            activeBufferRange = nil; activeBufferCount = 0
            secondBufferRange = nil; secondBufferCount = 0
            activeBufferAttempt = nil
            return value
        } catch { poison(); throw error }
    }

    func requireObservedRequestLink(handle: ColdEraseScratchObservedRequestLinkV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        attempt: OriginalEraseScratchCleanupAttemptV1) throws {
        try requireBound(scope: scope, attempt: attempt)
        guard observedLinks.contains(where: { $0 === handle }),
              handle.ownerIdentity == ObjectIdentifier(self),
              handle.range.ownerIdentity == ObjectIdentifier(self),
              handle.pending === pending, handle.requestSequence == pending?.sequence,
              handle.requestSHA256 == pending?.requestSHA256,
              handle.cut.stage == .linked,
              pending?.recipe == handle.range else {
            throw EraseIntentStoreError.invalidAuthority
        }
        switch handle.origin {
        case .freshObserved:
            guard handle.pending.cut.stage == .linked else { throw EraseIntentStoreError.invalidAuthority }
        case .currentProcess(let outcome, let priorCut):
            if handle.readbackConsumed {
                guard handle.pending.cut.stage == .linked else { throw EraseIntentStoreError.invalidAuthority }
            } else {
                guard handle.pending.cut == priorCut,
                      pendingPrimitiveIntent === outcome.intent,
                      pendingPrimitiveOutcome === outcome, outcome.result == 0 else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                try attempt.requireColdPendingPrimitive(task: handle.pending,
                    intent: outcome.intent, outcome: outcome)
            }
        }
        _ = try resource(for: handle.range)
        try requireBound(scope: scope, attempt: attempt)
    }

    func observedRequestLink(task: ColdEraseScratchPendingTaskV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        attempt: OriginalEraseScratchCleanupAttemptV1) throws -> ColdEraseScratchObservedRequestLinkV1 {
        try requireBound(scope: scope, attempt: attempt)
        guard pending === task, let handle = observedLinks.first(where: { $0.pending === task }),
              observedLinks.filter({ $0.pending === task }).count == 1 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try requireObservedRequestLink(handle: handle, scope: scope, attempt: attempt)
        return handle
    }

    private func requirePendingControlPrefix(_ task: ColdEraseScratchPendingTaskV1) throws {
        try requireFrame()
        guard pending === task, task.ownerIdentity == ObjectIdentifier(self),
              task.sequence > 0, task.sequence <= ColdEraseControlBinaryV1.maximumTaskCount,
              task.requestOffset >= 64, task.requestByteCount >= 160,
              let currentStateSHA256, currentStateSHA256 == task.stateSHA256,
              let progressResource, let controlObserver else { throw EraseIntentStoreError.invalidAuthority }
        let end = try ColdEraseControlBinaryV1.adding(task.requestOffset, task.requestByteCount)
        guard end == lastCompleteProgressOffset, end <= progressResource.byteCount,
              lastCompleteFrameSHA256 == task.requestSHA256 else { throw EraseIntentStoreError.invalidAuthority }
        try progressResource.requirePinned()
        let controls = try controlObserver.capture()
        guard controls.coreSHA256 != nil, controls.progressSHA256 != nil,
              controls.progressByteCount == progressResource.byteCount else {
            throw EraseIntentStoreError.invalidAuthority
        }
        if let recipe = task.recipe { _ = try resource(for: recipe) }
        try requireFrame()
    }

    /// These hooks prove the genuine private Attempt objects AND the exact
    /// installed complete REQUEST. An actual returned outcome is retained;
    /// it cannot advance a cut before the once-consumed full readback arrives.
    func requirePendingPrimitive(task: ColdEraseScratchPendingTaskV1,
        intent: OriginalEraseScratchCleanupPrimitiveIntentV1,
        outcome: OriginalEraseScratchCleanupPrimitiveOutcomeV1?) throws {
        do {
            guard let attempt else { throw EraseIntentStoreError.invalidAuthority }
            try requireBound(scope: heldScope, attempt: attempt)
            try requirePendingControlPrefix(task)
            try attempt.requireColdPendingPrimitive(task: task, intent: intent, outcome: outcome)
            if let outcome {
                guard pendingPrimitiveIntent === intent, pendingPrimitiveOutcome == nil,
                      outcome.intent === intent else { throw EraseIntentStoreError.invalidAuthority }
                pendingPrimitiveOutcome = outcome // retain actual result before validation
                switch intent.kind {
                case .createTemporary:
                    guard outcome.result >= 0 else { throw EraseIntentStoreError.invalidAuthority }
                case .writeTemporary(_, _, let requested):
                    guard outcome.result > 0, outcome.result <= Int64(requested) else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                default:
                    guard outcome.result == 0 else { throw EraseIntentStoreError.invalidAuthority }
                }
                if case .linkPublication(let temporary, let final) = intent.kind {
                    guard let recipe = task.recipe, observedLinks.isEmpty,
                          case .temporary(let count, let accepted) = task.cut.stage,
                          count == recipe.byteCount, accepted else { throw EraseIntentStoreError.invalidAuthority }
                    let charge = try ColdEraseControlBinaryV1.adding(
                        UInt64(MemoryLayout<ColdEraseScratchGeneratedLineageV1>.stride),
                        UInt64(temporary.utf8.count), UInt64(final.utf8.count), 128)
                    try requireBackingCapacity(additionalBytes: charge)
                    observedLinkChargeBytes = charge
                    let handle = ColdEraseScratchObservedRequestLinkV1(owner: self, pending: task,
                        range: recipe, temporaryPath: temporary, finalPath: final,
                        origin: .currentProcess(outcome: outcome, priorCut: task.cut))
                    observedLinks.append(handle)
                }
            } else {
                guard pendingPrimitiveIntent == nil, pendingPrimitiveOutcome == nil else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                pendingPrimitiveIntent = intent // retained BEFORE the actual primitive
                try requireClosedPendingPrimitive(task: task, intent: intent, attempt: attempt)
            }
            try requirePendingControlPrefix(task)
            try attempt.requireColdPendingPrimitive(task: task, intent: intent, outcome: outcome)
        } catch { poison(); throw error }
    }

    private func requireClosedPendingPrimitive(task: ColdEraseScratchPendingTaskV1,
        intent: OriginalEraseScratchCleanupPrimitiveIntentV1,
        attempt: OriginalEraseScratchCleanupAttemptV1) throws {
        if let recipe = task.recipe, let logicalFinal = task.finalPath {
            let temporary = "ProtectedIngressReceiptsV1/.partial-" + task.publicationTempID.uuidString.lowercased()
            let publicationFinal: String
            if case .hygieneFinalization = task.kind { publicationFinal = logicalFinal + ".finalizing" }
            else { publicationFinal = logicalFinal }
            guard recipe.originalPath == logicalFinal, !recipe.isDirectory,
                  recipe.progressSequence == task.sequence,
                  logicalFinal.hasPrefix("ProtectedIngressReceiptsV1/") else {
                throw EraseIntentStoreError.invalidAuthority
            }
            switch intent.kind {
            case .createTemporary(let path, let final, let bytes, let sha, let mode, let exclusive):
                guard task.cut.stage == .preimage, path == temporary, final == publicationFinal,
                      mode == 0o600, exclusive == task.choice.exclusiveFinalRename,
                      UInt64(bytes.count) == recipe.byteCount, sha == recipe.sha256 else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                try requireExactBytes(range: recipe, bytes: bytes, scope: heldScope, attempt: attempt)
            case .writeTemporary(let path, let offset, let count):
                guard path == temporary, offset >= 0, count > 0,
                      case .temporary(let prefix, let accepted) = task.cut.stage,
                      !accepted, UInt64(offset) == prefix, prefix <= recipe.byteCount,
                      UInt64(count) <= recipe.byteCount - prefix else { throw EraseIntentStoreError.invalidAuthority }
            case .requestPolicy(let path, _):
                guard path == temporary,
                      case .temporary(let count, let accepted) = task.cut.stage,
                      count == recipe.byteCount, !accepted else { throw EraseIntentStoreError.invalidAuthority }
            case .linkPublication(let path, let final):
                guard !task.choice.exclusiveFinalRename, path == temporary, final == publicationFinal,
                      case .temporary(let count, let accepted) = task.cut.stage,
                      count == recipe.byteCount, accepted else { throw EraseIntentStoreError.invalidAuthority }
            case .renamePublication(let source, let final, let exclusive):
                if case .hygieneFinalization = task.kind,
                   source == publicationFinal, final == logicalFinal, !exclusive {
                    guard task.cut.stage == .renamed || task.cut.stage == .postimage else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                } else {
                    guard task.choice.exclusiveFinalRename, exclusive,
                          source == temporary, final == publicationFinal,
                          case .temporary(let count, let accepted) = task.cut.stage,
                          count == recipe.byteCount, accepted else { throw EraseIntentStoreError.invalidAuthority }
                }
            case .removeLeaf(let path):
                guard path == temporary, task.cut.stage == .linked else { throw EraseIntentStoreError.invalidAuthority }
            case .synchronize(let path), .lockOwnedDirectory(let path):
                guard path == "ProtectedIngressReceiptsV1" || path == temporary
                    || path == publicationFinal || path == logicalFinal else { throw EraseIntentStoreError.invalidAuthority }
            case .closeOwnedResource(let path, _):
                guard path == "ProtectedIngressReceiptsV1" || path == temporary
                    || path == publicationFinal || path == logicalFinal else { throw EraseIntentStoreError.invalidAuthority }
            default: throw EraseIntentStoreError.invalidAuthority
            }
            return
        }
        guard task.recipe == nil, task.finalPath == nil else { throw EraseIntentStoreError.invalidAuthority }
        func validateTarget(_ target: String, parent: String,
            isDirectory: Bool, renamed: String? = nil) throws {
            switch intent.kind {
            case .renameLeaseDirectory(let original, let tombstone):
                guard isDirectory, task.cut.stage == .preimage,
                      original == target, tombstone == renamed else { throw EraseIntentStoreError.invalidAuthority }
            case .removeLeaf(let path):
                guard !isDirectory, path == target, task.cut.stage == .preimage else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            case .removeDirectory(let path):
                guard isDirectory, renamed == nil, path == target, task.cut.stage == .preimage else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            case .synchronize(let path), .lockOwnedDirectory(let path), .closeOwnedResource(let path, _):
                guard path == target || path == parent || path == renamed else { throw EraseIntentStoreError.invalidAuthority }
            default: throw EraseIntentStoreError.invalidAuthority
            }
        }
        switch task.kind {
        case .leaseDirectoryRename(let ordinal):
            try withFirstPhysicalNode(ordinal: ordinal, scope: heldScope, attempt: attempt) { first in
                let parts = first.path.split(separator: "/", omittingEmptySubsequences: false)
                guard first.isDirectory, parts.count == 2, parts[0] == "ScratchDataV1",
                      OwnedStorageLedgerV1.isConfidentColdScratchLeaseDirectoryName(String(parts[1])) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                try validateTarget(first.path, parent: "ScratchDataV1", isDirectory: true,
                    renamed: "ScratchDataV1/.deleting-" + String(parts[1]))
            }
        case .firstLeafRemoval(let ordinal), .firstDirectoryRemoval(let ordinal):
            try withFirstPhysicalNode(ordinal: ordinal, scope: heldScope, attempt: attempt) { first in
                let isDirectory: Bool
                if case .firstDirectoryRemoval = task.kind { isDirectory = true } else { isDirectory = false }
                guard first.isDirectory == isDirectory else { throw EraseIntentStoreError.invalidAuthority }
                guard let path = task.structuralTargetPath else { throw EraseIntentStoreError.invalidAuthority }
                let parts = first.path.split(separator: "/", omittingEmptySubsequences: false)
                if path != first.path {
                    guard parts.count >= 2, parts[0] == "ScratchDataV1",
                          OwnedStorageLedgerV1.isConfidentColdScratchLeaseDirectoryName(String(parts[1])),
                          !parts[1].hasPrefix(".deleting-"),
                          path == "ScratchDataV1/.deleting-" + parts.dropFirst().joined(separator: "/") else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                }
                let parent = path.split(separator: "/").dropLast().joined(separator: "/")
                try validateTarget(path, parent: parent, isDirectory: isDirectory)
            }
        case .generatedLeafRemoval(let sequence):
            guard let source = task.source, source.progressSequence == sequence else { throw EraseIntentStoreError.invalidAuthority }
            try validateTarget(source.originalPath, parent: "ProtectedIngressReceiptsV1", isDirectory: false)
        case .scratchRootRemoval:
            try validateTarget("ScratchDataV1", parent: "", isDirectory: true)
        case .ingressRootRemoval:
            try validateTarget("ProtectedIngressReceiptsV1", parent: "", isDirectory: true)
        default: throw EraseIntentStoreError.invalidAuthority
        }
    }

    func requirePendingPrimitiveReadback(task: ColdEraseScratchPendingTaskV1,
        intent: OriginalEraseScratchCleanupPrimitiveIntentV1,
        outcome: OriginalEraseScratchCleanupPrimitiveOutcomeV1,
        after: OriginalEraseScratchCleanupImageV1,
        attempt: OriginalEraseScratchCleanupAttemptV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        do {
            try requireBound(scope: scope, attempt: attempt)
            try requirePendingControlPrefix(task)
            guard pendingPrimitiveIntent === intent, pendingPrimitiveOutcome === outcome,
                  outcome.intent === intent else { throw EraseIntentStoreError.invalidAuthority }
            try attempt.requireColdPendingPrimitiveReadback(task: task,
                intent: intent, outcome: outcome, after: after)
            func node(_ path: String) throws -> OriginalEraseScratchCleanupImageV1.Node? {
                let root: OriginalEraseScratchCleanupImageV1.Root?
                let name: String
                if path == "ScratchDataV1" || path.hasPrefix("ScratchDataV1/") {
                    root = after.scratch; name = "ScratchDataV1"
                } else if path == "ProtectedIngressReceiptsV1" || path.hasPrefix("ProtectedIngressReceiptsV1/") {
                    root = after.ingress; name = "ProtectedIngressReceiptsV1"
                } else { throw EraseIntentStoreError.invalidAuthority }
                let relative = path == name ? "" : String(path.dropFirst(name.count + 1))
                var selected: OriginalEraseScratchCleanupImageV1.Node?
                for candidate in root?.nodes ?? [] where candidate.path == relative {
                    guard selected == nil else { throw EraseIntentStoreError.invalidAuthority }
                    selected = candidate
                }
                return selected
            }
            func requireRecipeNode(_ path: String, range: ColdEraseScratchPayloadRangeV1,
                count: UInt64, links: UInt64, accepted: Bool) throws
                -> OriginalEraseScratchCleanupImageV1.Node {
                guard count <= range.byteCount, let value = try node(path) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                let fields = value.fullFact.split(separator: "|", omittingEmptySubsequences: false)
                guard fields.count == 11, let mode = UInt64(fields[2]), mode & UInt64(S_IFMT) == UInt64(S_IFREG),
                      UInt64(fields[5]) == links, UInt64(fields[6]) == count,
                      value.contentSHA256 == (try streamingSHA256(range: range, prefixCount: count)),
                      !accepted || value.policy != nil else { throw EraseIntentStoreError.invalidAuthority }
                return value
            }
            var next = task.cut
            switch intent.kind {
            case .createTemporary(let path, _, _, _, _, _):
                guard outcome.result >= 0, let range = task.recipe else { throw EraseIntentStoreError.invalidAuthority }
                _ = try requireRecipeNode(path, range: range, count: 0, links: 1, accepted: false)
                next = .init(stage: .temporary(prefixCount: 0, policyAccepted: false))
            case .writeTemporary(let path, let offset, _):
                guard outcome.result > 0, offset >= 0, let range = task.recipe,
                      case .temporary(let beforeCount, let accepted) = task.cut.stage,
                      !accepted, beforeCount == UInt64(offset) else { throw EraseIntentStoreError.invalidAuthority }
                let count = try ColdEraseControlBinaryV1.adding(beforeCount, UInt64(outcome.result))
                _ = try requireRecipeNode(path, range: range, count: count, links: 1, accepted: false)
                next = .init(stage: .temporary(prefixCount: count, policyAccepted: false))
            case .requestPolicy(let path, _):
                guard outcome.result == 0, let range = task.recipe,
                      case .temporary(let count, let accepted) = task.cut.stage,
                      count == range.byteCount, !accepted else { throw EraseIntentStoreError.invalidAuthority }
                _ = try requireRecipeNode(path, range: range, count: count, links: 1, accepted: true)
                next = .init(stage: .temporary(prefixCount: count, policyAccepted: true))
            case .linkPublication(let temporary, let final):
                guard outcome.result == 0, let range = task.recipe,
                      let handle = observedLinks.first(where: { $0.pending === task }),
                      case .currentProcess(let actual, _) = handle.origin,
                      actual === outcome, !handle.readbackConsumed else { throw EraseIntentStoreError.invalidAuthority }
                let a = try requireRecipeNode(temporary, range: range, count: range.byteCount, links: 2, accepted: true)
                let b = try requireRecipeNode(final, range: range, count: range.byteCount, links: 2, accepted: true)
                guard a.fullFact == b.fullFact, a.policy == b.policy else { throw EraseIntentStoreError.invalidAuthority }
                next = .init(stage: .linked)
            case .renamePublication(let source, let final, let exclusive):
                guard outcome.result == 0, let range = task.recipe,
                      try node(source) == nil else { throw EraseIntentStoreError.invalidAuthority }
                _ = try requireRecipeNode(final, range: range, count: range.byteCount, links: 1, accepted: true)
                if !exclusive, case .hygieneFinalization = task.kind {
                    guard source == range.originalPath + ".finalizing", final == range.originalPath else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    next = .init(stage: .postimage)
                } else { next = .init(stage: .renamed) }
            case .renameLeaseDirectory(let original, let destination):
                guard outcome.result == 0, try node(original) == nil,
                      let renamed = try node(destination),
                      let before = intent.before.scratch?.nodes.first(where: {
                          $0.path == String(original.dropFirst("ScratchDataV1/".count))
                      }) else { throw EraseIntentStoreError.invalidAuthority }
                let first = before.fullFact.split(separator: "|", omittingEmptySubsequences: false)
                let current = renamed.fullFact.split(separator: "|", omittingEmptySubsequences: false)
                guard first.count == 11, current.count == 11, Array(first.prefix(7)) == Array(current.prefix(7)) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                next = .init(stage: .postimage)
            case .removeLeaf(let path), .removeDirectory(let path):
                guard outcome.result == 0, try node(path) == nil else { throw EraseIntentStoreError.invalidAuthority }
                if let range = task.recipe {
                    guard task.cut.stage == .linked, let final = task.finalPath else { throw EraseIntentStoreError.invalidAuthority }
                    let physicalFinal: String
                    if case .hygieneFinalization = task.kind { physicalFinal = final + ".finalizing" }
                    else { physicalFinal = final }
                    _ = try requireRecipeNode(physicalFinal, range: range, count: range.byteCount, links: 1, accepted: true)
                    if case .hygieneFinalization = task.kind {
                        next = .init(stage: .renamed)
                    } else { next = .init(stage: .postimage) }
                } else {
                    next = .init(stage: .postimage)
                }
            case .synchronize, .lockOwnedDirectory, .closeOwnedResource:
                guard outcome.result == 0, after == intent.before else { throw EraseIntentStoreError.invalidAuthority }
            }
            // The real completed readback, not the raw syscall outcome, is
            // the sole source of cut advancement and mixed-link adoption.
            try task.advance(owner: self, cut: next)
            if case .linkPublication = intent.kind {
                guard let handle = observedLinks.first(where: { $0.pending === task }) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                handle.readbackConsumed = true
            }
            try requirePendingControlPrefix(task)
            try attempt.requireColdPendingPrimitiveReadback(task: task,
                intent: intent, outcome: outcome, after: after)
            // Clear only after both exact current-prefix and actual consumed
            // object checks have succeeded. Any throw above retains the pair.
            pendingPrimitiveOutcome = nil; pendingPrimitiveIntent = nil
        } catch { poison(); throw error }
    }

    fileprivate func retainUncertainPolicyDescriptor(_ descriptor: Int32) {
        uncertainPolicyDescriptors.append(descriptor)
        poison()
    }

    fileprivate func requireControlResourceFrame(_ resource: ColdEraseRetainedControlFileV1) throws {
        try requireFrame()
        if state == .transferring || state == .postContent {
            guard let transferredControlOwner else { throw EraseIntentStoreError.invalidAuthority }
            try transferredControlOwner.requireResourceMemory(resource)
            return
        }
        if let current = requestSemanticOwner, state == .catalog || state == .bound {
            try current.requireResourceMemory(resource)
            return
        }
        if let installation = publishedResourceInstallation,
           installation.storage.core?.resource === resource || installation.storage.progress?.resource === resource {
            try requirePublishedResourceInstallationFrame(installation)
            try installation.requireResourceAssociation(resource)
            return // genuine installed owner; no construction Publisher/old Scope rearm
        }
        if publishedProgressInfrastructure === resource {
            guard publishedProgressInfrastructureChargeBytes > 0,
                  let progressPublisher else { throw EraseIntentStoreError.invalidAuthority }
            try requireCapsulePublisherFrame(progressPublisher)
            try progressPublisher.requireCanonicalInfrastructureMemoryAssociation(resource)
            return
        }
        if publishedCanonicalInfrastructure === resource {
            guard publishedCanonicalInfrastructureChargeBytes > 0,
                  let capsulePublisher else { throw EraseIntentStoreError.invalidAuthority }
            try requireCapsulePublisherFrame(capsulePublisher)
            try capsulePublisher.requireCanonicalInfrastructureMemoryAssociation(resource)
            return // genuine privately registered current publication resource
        }
        guard resources.contains(where: { $0 === resource }) else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    fileprivate func requireControlReadCapacity(_ resource: ColdEraseRetainedControlFileV1,
        count: Int) throws {
        try requireControlResourceFrame(resource)
        guard count >= 0, count <= ColdEraseControlBinaryV1.readChunkBytes else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try requireBackingCapacity(additionalBytes: UInt64(count))
        try requireControlResourceFrame(resource)
    }

    fileprivate func requireClosedControlResourceFrame(_ resource: ColdEraseRetainedControlFileV1) throws {
        try requireFrame()
        guard resources.contains(where: { $0 === resource }), resource.state == .closed else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }
}

/// One retained file description for specialized cold controls. The owner
/// registers this object before open. Close detaches/fences the FD before the
/// syscall, and an ambiguous result stays retained with no numeric-FD retry.
@MainActor fileprivate final class ColdEraseRetainedControlFileV1 {
    enum State: Equatable { case unopened, open, closing, closed, uncertain }
    private enum SyscallKind: Equatable { case open, parentStat, heldStat, namedStat, read, close }
    private final class Syscall {
        private struct Storage {
            let sequence: UInt64
            let kind: SyscallKind
            let offset: UInt64
            let requestedCount: Int
            let enteredDescriptor: Int32?
            var result: Int64? = nil
            var savedErrno: Int32? = nil
        }
        private var storage: Storage
        var sequence: UInt64 { storage.sequence }
        var kind: SyscallKind { storage.kind }
        var offset: UInt64 { storage.offset }
        var requestedCount: Int { storage.requestedCount }
        var enteredDescriptor: Int32? { storage.enteredDescriptor }
        private(set) var result: Int64? {
            get { storage.result }
            set { storage.result = newValue }
        }
        private(set) var savedErrno: Int32? {
            get { storage.savedErrno }
            set { storage.savedErrno = newValue }
        }
        static var declaredBackingBytes: UInt64 {
            UInt64(MemoryLayout<Storage>.stride)
        }
        init(sequence: UInt64, kind: SyscallKind, offset: UInt64, requestedCount: Int,
            descriptor: Int32?) {
            storage = .init(sequence: sequence, kind: kind, offset: offset,
                requestedCount: requestedCount, enteredDescriptor: descriptor)
        }
        func record(result: Int64, savedErrno: Int32) throws {
            guard self.result == nil, self.savedErrno == nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
            self.result = result; self.savedErrno = savedErrno
        }
    }
    private struct Storage {
        let name: String
        let parent: Int32
        let url: URL
        let maximumBytes: UInt64
        var state: State = .unopened
        var descriptor: Int32 = -1
        var fullFact: EraseColdControlLeafFactV1? = nil
        weak var owner: ColdEraseScratchPayloadRangesV1?
        // One actual entered request and its immediate outcome remain retained
        // through checked consumption. Failure keeps that exact request forever.
        var pendingSyscall: Syscall? = nil
        var lastConsumedSyscall: Syscall? = nil
        var syscallSequence: UInt64 = 0
        var checkedClose: Syscall? = nil
        var readBufferChargeBytes: UInt64 = 0
    }
    private var storage: Storage
    var name: String { storage.name }
    var parent: Int32 { storage.parent }
    var url: URL { storage.url }
    var maximumBytes: UInt64 { storage.maximumBytes }
    private(set) var state: State {
        get { storage.state }
        set { storage.state = newValue }
    }
    private var descriptor: Int32 {
        get { storage.descriptor }
        set { storage.descriptor = newValue }
    }
    private var fullFact: EraseColdControlLeafFactV1? {
        get { storage.fullFact }
        set { storage.fullFact = newValue }
    }
    private var owner: ColdEraseScratchPayloadRangesV1? {
        get { storage.owner }
        set { storage.owner = newValue }
    }
    private var pendingSyscall: Syscall? {
        get { storage.pendingSyscall }
        set { storage.pendingSyscall = newValue }
    }
    private var lastConsumedSyscall: Syscall? {
        get { storage.lastConsumedSyscall }
        set { storage.lastConsumedSyscall = newValue }
    }
    private var syscallSequence: UInt64 {
        get { storage.syscallSequence }
        set { storage.syscallSequence = newValue }
    }
    private var checkedClose: Syscall? {
        get { storage.checkedClose }
        set { storage.checkedClose = newValue }
    }
    // Deliberately remains the original stored class field. Its actual in-place
    // mutable borrow calls methods that mutate Storage; no accessor/COW copy,
    // aggregate Storage inout yield or unregistered nil-staging is introduced.
    private var retainedReadBuffer: Data?
    private var readBufferChargeBytes: UInt64 {
        get { storage.readBufferChargeBytes }
        set { storage.readBufferChargeBytes = newValue }
    }

    /// Actual value-field footprint only; dynamic paths/raw buffers and live
    /// syscall/object counts require the caller's separate genuine reservation.
    fileprivate static var declaredBackingBytes: UInt64 {
        UInt64(MemoryLayout<Storage>.stride + MemoryLayout<Data?>.stride)
    }
    fileprivate static var declaredSyscallBackingBytes: UInt64 {
        Syscall.declaredBackingBytes
    }
    var retainedBufferBytes: UInt64 { readBufferChargeBytes }

    init(owner: ColdEraseScratchPayloadRangesV1, parent: Int32,
        name: String, url: URL, maximumBytes: UInt64) {
        storage = .init(name: name, parent: parent, url: url,
            maximumBytes: maximumBytes, owner: owner)
    }

    private func enter(_ kind: SyscallKind, offset: UInt64 = 0,
        count: Int = 0) throws -> Syscall {
        guard pendingSyscall == nil, let owner, state != .uncertain,
              state != .closed, count >= 0 else { throw EraseIntentStoreError.invalidAuthority }
        try owner.requireControlResourceFrame(self)
        let next = try ColdEraseControlBinaryV1.adding(syscallSequence, 1)
        let request = Syscall(sequence: next, kind: kind, offset: offset,
            requestedCount: count, descriptor: kind == .close ? descriptor : nil)
        pendingSyscall = request // register BEFORE syscall entry
        return request
    }

    private func consume(_ request: Syscall, expected result: Int64) throws {
        guard pendingSyscall === request, request.result == result,
              request.savedErrno != nil, let owner else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try owner.requireControlResourceFrame(self)
        syscallSequence = request.sequence
        lastConsumedSyscall = request
        pendingSyscall = nil
    }

    private func heldStat() throws -> stat {
        let request = try enter(.heldStat)
        var value = stat()
        let result = Darwin.fstat(descriptor, &value)
        let savedErrno = errno
        try request.record(result: Int64(result), savedErrno: savedErrno)
        guard result == 0 else { throw EraseIntentStoreError.invalidAuthority }
        try consume(request, expected: 0)
        return value
    }

    private func parentStat() throws -> stat {
        let request = try enter(.parentStat)
        var value = stat()
        let result = Darwin.fstat(parent, &value)
        let savedErrno = errno
        try request.record(result: Int64(result), savedErrno: savedErrno)
        guard result == 0, value.st_mode & S_IFMT == S_IFDIR else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try consume(request, expected: 0)
        return value
    }

    private func requireFileOwnership(_ held: stat, parent: stat) throws {
        let group = parent.st_mode & mode_t(S_ISGID) != 0 ? parent.st_gid : getegid()
        guard held.st_mode & S_IFMT == S_IFREG, held.st_nlink == 1,
              held.st_dev == parent.st_dev, held.st_uid == geteuid(),
              held.st_gid == group, held.st_mode & 0o7777 == 0o600,
              held.st_size >= 0, UInt64(held.st_size) <= maximumBytes else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    private func namedStat() throws -> stat {
        let request = try enter(.namedStat)
        var value = stat()
        let result = Darwin.fstatat(parent, name, &value, AT_SYMLINK_NOFOLLOW)
        let savedErrno = errno
        try request.record(result: Int64(result), savedErrno: savedErrno)
        guard result == 0 else { throw EraseIntentStoreError.invalidAuthority }
        try consume(request, expected: 0)
        return value
    }

    func openExisting() throws {
        guard state == .unopened, let owner else {
            throw EraseIntentStoreError.invalidAuthority
        }
        do {
            let request = try enter(.open)
            let result = Darwin.openat(parent, name,
                O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
            let savedErrno = errno
            // Successful open is retained before any throwing guard/callback.
            if result >= 0 { descriptor = result; state = .open }
            try request.record(result: Int64(result), savedErrno: savedErrno)
            guard result >= 0 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try consume(request, expected: Int64(result))
            let parent = try parentStat()
            let held = try heldStat(), named = try namedStat()
            try requireFileOwnership(held, parent: parent)
            guard
                  EraseColdControlLeafFactV1(held) == EraseColdControlLeafFactV1(named) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            fullFact = EraseColdControlLeafFactV1(held)
            try requirePinned()
            let policy = try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(
                .journal, at: url, retainUncertainDescriptor: {
                    owner.retainUncertainPolicyDescriptor($0)
                })
            guard policy.state == .strictComplete else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try requirePinned()
        } catch {
            state = .uncertain
            owner.poison()
            throw error
        }
    }

    /// Distinct live-capsule read-only open. This consumes the real native
    /// canonical policy/rename/sync origin rather than ordinary strict-only
    /// openExisting, a caller disposition or a fabricated published receipt.
    fileprivate func openPublishedCanonical(publisher: ColdEraseScratchCapsulePublisherV1) throws {
        guard state == .unopened, let owner else { throw EraseIntentStoreError.invalidAuthority }
        do {
            try publisher.requireCanonicalInfrastructureOpenPrerequisite(self)
            try owner.requireControlResourceFrame(self)
            let request = try enter(.open)
            let result = Darwin.openat(parent, name, O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
            let saved = errno
            if result >= 0 { descriptor = result; state = .open }
            try request.record(result: Int64(result), savedErrno: saved) // actual FD/result BEFORE postproof
            guard result >= 0 else { throw EraseIntentStoreError.invalidAuthority }
            try consume(request, expected: Int64(result))
            let parent = try parentStat()
            let held = try heldStat(), named = try namedStat()
            try requireFileOwnership(held, parent: parent)
            guard EraseColdControlLeafFactV1(held) == EraseColdControlLeafFactV1(named) else {
                throw EraseIntentStoreError.invalidAuthority
            }
