            return withUnsafeBytes(of: &tuple) { bytes in
                var high: UInt64 = 0, low: UInt64 = 0
                for i in 0..<8 { high = (high << 8) | UInt64(bytes[i]) }
                for i in 8..<16 { low = (low << 8) | UInt64(bytes[i]) }
                return Identifier(high: high, low: low)
