                prefix = "ingress-"; family = 1
                if name.hasSuffix(".pending.json.replacement") { suffix = ".pending.json.replacement" }
                else if name.hasSuffix(".prepare.json") { suffix = ".prepare.json" }
                else if name.hasSuffix(".claim.json") { suffix = ".claim.json" }
                else if name.hasSuffix(".published.json") { suffix = ".published.json" }
                else if name.hasSuffix(".pending.json") { suffix = ".pending.json" }
