    private func retainChain(to parentComponents: [Substring], nodes: [Roster.Node]) throws {
        guard parentComponents.count <= 64, parentComponents.capacity <= 65, let context else { throw EraseIntentStoreError.invalidAuthority }
        var common = 0
        while common < chain.count && common < parentComponents.count {
            let expected = parentComponents[0...common].joined(separator: "/")
            guard expected.utf8.count <= 16_640 else { throw EraseIntentStoreError.invalidAuthority }
            if chain[common].path != expected { break }
            common += 1
        }
        while chain.count > common {
            let owner = chain[chain.count - 1]
            try owner.closeChecked()
            try owner.requireClosedNamed() // its real parent remains live
            lastClosedAncestor = owner
            chain.removeLast() // positive typed consumer, no accumulating history
            lastClosedAncestor = nil
        }
        var depth = common
        while depth < parentComponents.count {
            let path = parentComponents[0...depth].joined(separator: "/")
            let original = nodes[try position(path: path, in: nodes)]
            guard original.kind == "directory", Self.selected(path) else { throw EraseIntentStoreError.invalidAuthority }
            let parent = chain.last?.descriptor ?? context.loan.operations
            let expected = try capturedDirectoryFact(path: path, nodes: nodes)
            let owner = NodeResource(scanner: self, original: original,
                physicalOrdinal: UInt64.max, parent: parent,
                url: context.operationsURL.appendingPathComponent(path, isDirectory: true),
                expectedFullFact: expected, ancestor: true)
            chain.append(owner) // retained before its FIRST open/stat/cursor
            guard chain.count <= 65, chain.capacity <= 65 else {
                slotCharge = try ColdEraseControlBinaryV1.adding(slotCharge,
                    UInt64(chain.capacity) * UInt64(MemoryLayout<NodeResource?>.stride))
                poison(); throw EraseIntentStoreError.invalidAuthority
            }
            try owner.openChecked()
            try owner.requirePinned()
            depth += 1
        }
        try requireAncestors()
    }
    private func rowReservation(path: String) throws -> UInt64 {
        // Closed row path, <=65 live chain aliases/DTOs, stat/word/header/name/bitset
        // temporaries and fixed object/reference storage. Allocator/VM overhead unmeasured.
        let pathBytes = UInt64(path.utf8.count)
        guard pathBytes > 0, pathBytes <= 16_640 else { throw EraseIntentStoreError.invalidAuthority }
        return try ColdEraseControlBinaryV1.adding(
            ColdEraseControlBinaryV1.multiplying(66, 16_640 * 8 + 512 * 8),
            UInt64(MemoryLayout<ColdEraseScratchFirstCatalogPolicyNodeV1.Ancestor>.stride) * 65,
            UInt64(MemoryLayout<ColdEraseScratchFirstCatalogPolicyNodeV1>.stride),
            12_504, 65_536, 4_096, pathBytes * 8)
    }
    private func reserveIndex(_ count: Int) throws {
        guard index.isEmpty, rosterPositions.isEmpty, indexCharge == 0, count >= 0, count <= 100_000 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let ceiling = try ColdEraseControlBinaryV1.adding(
            ColdEraseControlBinaryV1.multiplying(100_000, UInt64(MemoryLayout<Index>.stride)),
            ColdEraseControlBinaryV1.multiplying(100_000, UInt64(MemoryLayout<Int>.stride)))
        try capacity(ceiling); indexCharge = ceiling
        index.reserveCapacity(count); rosterPositions.reserveCapacity(count)
        let observed = try ColdEraseControlBinaryV1.adding(
            ColdEraseControlBinaryV1.multiplying(UInt64(index.capacity), UInt64(MemoryLayout<Index>.stride)),
            ColdEraseControlBinaryV1.multiplying(UInt64(rosterPositions.capacity), UInt64(MemoryLayout<Int>.stride)))
        if observed > indexCharge {
            // Retain actual unexpected backing on uncertainty; never report a pre-known VM bound.
            indexCharge = observed; poison(); throw EraseIntentStoreError.invalidAuthority
        }
        guard index.capacity >= count, index.capacity <= 100_000,
              rosterPositions.capacity >= count, rosterPositions.capacity <= 100_000 else {
            poison(); throw EraseIntentStoreError.invalidAuthority
        }
    }
    fileprivate func requireNodeDataConstruction(_ resource: NodeResource) throws {
        try requireMembership(resource); try requireAncestors()
