    fileprivate func makePolicyNode(resource: NodeResource) throws -> ColdEraseScratchFirstCatalogPolicyNodeV1 {
        try requireNodeDataConstruction(resource)
        guard let context else { throw EraseIntentStoreError.invalidAuthority }
        guard activeAncestorDTOs == nil else { throw EraseIntentStoreError.invalidAuthority }
        activeAncestorDTOs = []
        activeAncestorDTOs!.reserveCapacity(chain.count + 1)
        guard activeAncestorDTOs!.capacity <= 65, chain.count + 1 <= 65 else {
            rowCharge = try ColdEraseControlBinaryV1.adding(rowCharge,
                UInt64(activeAncestorDTOs!.capacity) * UInt64(MemoryLayout<ColdEraseScratchFirstCatalogPolicyNodeV1.Ancestor>.stride))
            poison(); throw EraseIntentStoreError.invalidAuthority
        }
        activeAncestorDTOs!.append(try .init(url: context.operationsURL, fact: requireRoot()))
        for owner in chain {
            guard let full = owner.capturedFact else { throw EraseIntentStoreError.invalidAuthority }
            try owner.requirePinned()
            activeAncestorDTOs!.append(try .init(url: owner.url, fact: full))
        }
        let parentURL = chain.last?.url ?? context.operationsURL
        let parentFact = try resource.requireMetadata().parentFact
        return try .init(scanner: self, resource: resource, parentURL: parentURL,
            parentFullFact: parentFact.rendered, ancestors: activeAncestorDTOs!)
    }
    fileprivate func requirePolicyObservation(scope: Scope, resource: NodeResource) throws {
        try requireMembership(resource)
        guard activeNode === resource, activeScope === scope else {
            throw EraseIntentStoreError.invalidAuthority
        }
        if rowRecorded { try requireCheckedNodeResource(resource, scope: scope) }
        else { try requireAncestors(); _ = try resource.requireMetadata() }
    }

    fileprivate func requirePolicyObservationCapacity(
        observation: ColdEraseScratchFirstCatalogPolicyObservationV1, scope: Scope,
        resource: NodeResource, additionalBytes: UInt64) throws {
        try requirePolicyObservation(scope: scope, resource: resource)
        guard !rowRecorded, policyCharge > 0 else { throw EraseIntentStoreError.invalidAuthority }
        try scope.requireObservationAttempt(observation)
        if let retained = policyObservationOwner {
            guard retained === observation else { throw EraseIntentStoreError.invalidAuthority }
        } else {
            policyObservationOwner = observation // actual Scope-retained object before nested allocation
        }
        let observed = observation.actualBackingBytes
        guard observed <= policyCharge, additionalBytes <= policyCharge else {
            // additionalBytes is a TOTAL owner backing observation/request, not an additive charge.
            // Keep every actual object and its observed overcapacity; do not turn it into permission.
            policyCharge = max(policyCharge, observed)
            poison(); throw EraseIntentStoreError.invalidAuthority
        }
        try capacity(0) // fresh whole capacity with this same reservation already retained
        try requirePolicyObservation(scope: scope, resource: resource)
    }
    fileprivate func requireCheckedNodeResource(_ resource: NodeResource, scope: Scope) throws {
        // Nonrecursive: Scope.requireCurrentBinding must never be called here.
        try requireMembership(resource)
        guard activeNode === resource, activeScope === scope, rowRecorded,
              activeOrdinal == resource.physicalOrdinal else {
            throw EraseIntentStoreError.invalidAuthority
