                  old.selectedOrdinalBefore == row.selectedOrdinalBefore,
                  old.pathOffset == row.pathOffset, old.pathByteCount == row.pathByteCount,
                  old.rawOffset == row.rawOffset, old.rawByteCount == row.rawByteCount,
                  old.role == row.role, old.semanticVersion == row.semanticVersion,
                  old.policyCode == row.policyCode, Self.same(old.fact, row.fact),
                  Self.same(old.digest, row.digest) else { throw EraseIntentStoreError.invalidAuthority }
