    private func metadataHeader(_ row: Index) throws -> Data {
        var digest = Data(capacity: 32)
        for word in [row.digest.first, row.digest.second, row.digest.third, row.digest.fourth] {
            var value = word.littleEndian
            withUnsafeBytes(of: &value) { digest.append(contentsOf: $0) }
        }
        return try ColdEraseControlBinaryV1.catalogSourceHeader(.init(
            pathByteCount: row.pathByteCount, rawByteCount: row.rawByteCount,
            sourceRole: row.role.rawValue, semanticVersion: row.semanticVersion,
            fullFact: row.fact.words, sha256: digest, policyCode: row.policyCode))
    }
