                  policyCharge == 0, policyObservationOwner == nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
            if second {
                guard ordinal < UInt64(rosterPositions.count), rosterPositions[Int(ordinal)] == nodePosition else {
                    throw EraseIntentStoreError.invalidAuthority
