            }
            if encodedSink != nil {
                guard phase == .emitting, emittedCensus != nil else { throw EraseIntentStoreError.invalidAuthority }
                try emittedCensus!.recordValidatedRow(path: original.path, row: row)
            }
            rowCharge = 0; policyCharge = 0 // helper exited: row aliases and actual released owner are gone
            offset = try ColdEraseControlBinaryV1.adding(row.rawOffset, row.rawByteCount)
            guard offset <= ColdEraseControlBinaryV1.maximumCatalogBytes else {
                throw EraseIntentStoreError.invalidAuthority
            }
            if row.isSelected { selected += 1 }
            ordinal += 1
