                  cursor == original.encodedByteCount,
                  selectedRawBytes == nil, selectedRawCharge == 0,
                  selectedCanonicalComparisonCharge == 0,
                  encodedHeader == nil, encodedPath == nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try ranges?.requireFirstCatalogScannerContext(self, context: context)
            try requireFrame()
            guard let census = emittedCensus else { throw EraseIntentStoreError.invalidAuthority }
            _ = try census.checkedCeilings(physicalCount: checked.physicalCount)
            let hash = try ColdEraseControlBinaryV1.hexSHA256(Data(digest.finalize()))
            phase = .complete; emittedCensus = nil; encodedWalkCharge = 0
            return EncodedCapture(physicalCount: checked.physicalCount,
                selectedCount: checked.selectedCount, catalogByteCount: byteCount,
                catalogSHA256: hash, census: census)
        } catch { poison(); throw error }
    }


