    /// Canonical lowercase64 SHA comparison text from the actual four words.
    /// Fixed scalar pair/tuple cells replace map/format/join/Array/Data scratch.
    fileprivate static func issuedBirthDigestSHA256(_ value: Digest) -> String {
        func ascii(_ nibble: UInt64) -> UInt64 {
            nibble < 10 ? 48 + nibble : 87 + nibble
        }
        func pair(_ word: UInt64) -> (UInt64, UInt64) {
            var low: UInt64 = 0, high: UInt64 = 0
            for position in 0..<8 {
                let byte = (word >> UInt64(position * 8)) & 255
                let characters = ascii(byte >> 4) | (ascii(byte & 15) << 8)
                if position < 4 { low |= characters << UInt64(position * 16) }
                else { high |= characters << UInt64((position - 4) * 16) }
            }
            return (low.littleEndian, high.littleEndian)
        }
        let first = pair(value.first), second = pair(value.second)
        let third = pair(value.third), fourth = pair(value.fourth)
        var encoded = (first.0, first.1, second.0, second.1,
            third.0, third.1, fourth.0, fourth.1)
        return withUnsafeBytes(of: &encoded) { bytes in
            String(decoding: bytes, as: UTF8.self) // lexical64 initialized ASCII bytes only
        }
    }

    /// Scalar catalog Fact projection in the canonical ORIGINAL nine-field
    /// order. The incumbent stat helper remains untouched; no stat is minted.
    private static func issuedBirthNine(_ value: Fact) -> String {
        "\(Int64(bitPattern: value.device))|\(value.inode)|\(value.mode)|\(value.links)|\(Int64(bitPattern: value.size))|\(Int64(bitPattern: value.modifiedSeconds))|\(Int64(bitPattern: value.modifiedNanoseconds))|\(Int64(bitPattern: value.changedSeconds))|\(Int64(bitPattern: value.changedNanoseconds))"
    }

    fileprivate static func sameIssuedBirthFact(_ a: Fact, _ b: Fact) -> Bool { same(a, b) }
    fileprivate static func sameIssuedBirthDigest(_ a: Digest, _ b: Digest) -> Bool { same(a, b) }

    fileprivate func issuedBirthOriginalOperationsOrdinal(row: Index,
        ranges: ColdEraseScratchPayloadRangesV1, context: Context) throws -> UInt64 {
        let all = try requireIssuedBirthOriginalContext(ranges: ranges, context: context)
        guard let ordinal = Int(exactly: row.physicalOrdinal), ordinal >= 0, ordinal < index.count,
              rosterPositions.count == index.count else { throw EraseIntentStoreError.invalidAuthority }
        let expected = index[ordinal], position = rosterPositions[ordinal]
        guard position >= 0, position < all.count,
              Self.selected(all[position].path),
              (all[position].kind == "directory") == row.isDirectory,
              expected.physicalOrdinal == row.physicalOrdinal,
              expected.sourceOrdinal == row.sourceOrdinal,
              expected.selectedOrdinalBefore == row.selectedOrdinalBefore,
              expected.pathOffset == row.pathOffset, expected.pathByteCount == row.pathByteCount,
              expected.rawOffset == row.rawOffset, expected.rawByteCount == row.rawByteCount,
              expected.role == row.role, expected.semanticVersion == row.semanticVersion,
              expected.policyCode == row.policyCode,
              Self.same(expected.fact, row.fact), Self.same(expected.digest, row.digest),
              UInt64(all[position].path.utf8.count) == row.pathByteCount,
              Self.issuedBirthNine(row.fact).utf8.elementsEqual(all[position].fact.utf8) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        if row.isDirectory {
            guard all[position].sha256 == nil, all[position].members != nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
        } else {
            guard all[position].members == nil, let originalSHA = all[position].sha256,
                  StoreMigrationCanonicalJSONV1.isLowercaseSHA256(originalSHA),
                  Self.issuedBirthDigestSHA256(row.digest) == originalSHA else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        return UInt64(position) // actual global Ops roster position, never SourceOrdinal
    }

    fileprivate func requireIssuedBirthOriginalPath(row: Index, path: String,
        ranges: ColdEraseScratchPayloadRangesV1, context: Context) throws {
        let position = try issuedBirthOriginalOperationsOrdinal(row: row, ranges: ranges, context: context)
        let original = try issuedBirthOriginalOperationsNode(originalOperationsOrdinal: position,
            ranges: ranges, context: context)
        guard original.path.utf8.elementsEqual(path.utf8), Self.selected(path) else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

