            var byte: UInt8 = 0
            let eof = try enter(.read, offset: capturedFact.size, count: 1)
            let result = Darwin.pread(descriptor, &byte, 1, end), saved = errno
            try eof.record(Int64(result), errno: saved)
            guard result == 0 else { throw EraseIntentStoreError.invalidAuthority }
            try consume(eof, result: 0); try requirePinned()
            let bytes = Data(hasher.finalize())
            let digest = try Digest(bytes)
            guard try digest.hex() == original.sha256 else { throw EraseIntentStoreError.invalidAuthority }
            capturedDigest = digest; digestChecked = true
            scanner.activeRead = nil; scanner.readCharge = 0
        }
        private func scanNames() throws {
