            let callBudget = expected.count.addingReportingOverflow(3) // two dots plus genuine EOF
            guard !callBudget.overflow else { throw EraseIntentStoreError.invalidAuthority }
            let maximumCursorCalls = callBudget.partialValue
            let words = (expected.count + 63) / 64
            seen = [UInt64](repeating: 0, count: words) // backed by charged closed row window
