                    Data($0.prefix(Int(entry!.pointee.d_namlen)))
                }
                guard !nameBytes.contains(0), let actualName = String(data: nameBytes, encoding: .utf8) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                if actualName == "." || actualName == ".." { continue }
                guard !actualName.contains("/") else { throw EraseIntentStoreError.invalidAuthority }
                var lo = 0, hi = expected.count
                while lo < hi {
