            guard !cursorCloseAttempted, let actualCursor = cursor else {
                throw EraseIntentStoreError.invalidAuthority
            }
            _ = try retainEnteredClose(.directory(actualCursor), request: closed)
            cursorCloseAttempted = true; cursor = nil // fence BEFORE sole actual close; exact owner retained
            let result = Darwin.closedir(actualCursor), saved = errno
            try closed.record(Int64(result), errno: saved)
            guard result == 0 else { throw EraseIntentStoreError.invalidAuthority }
            try consume(closed, result: 0); checkedCursorClose = closed
            try requirePinned(); seen = []; namesChecked = true
