            let bytes = try ColdEraseControlBinaryV1.adding(
                ColdEraseControlBinaryV1.multiplying(expected.rawByteCount, 2),
                UInt64(2 * MemoryLayout<Data>.stride + 128))
            // Separate typed nested arrays/Strings/validation map+sort+Set
            // declaration supplied by the actual private codec owner. This is
            // not covered by the raw two-window allowance or a fixed header.
            let comparisonBytes = try OwnedStorageLedgerV1.requiredColdCatalogCanonicalComparisonBackingBytes(
                path: path, sourceRole: expected.role.rawValue,
                semanticVersion: expected.semanticVersion, byteCount: expected.rawByteCount)
            guard comparisonBytes > 0 else { throw EraseIntentStoreError.invalidAuthority }
            try scanner.capacity(ColdEraseControlBinaryV1.adding(bytes, comparisonBytes))
            scanner.selectedRawCharge = bytes
            scanner.selectedCanonicalComparisonCharge = comparisonBytes
            scanner.selectedRawBytes = Data(count: count) // retained BEFORE actual raw read
            var offset = 0
            while offset < count {
                try scanner.requirePolicyObservation(scope: scope, resource: self)
                try requirePinned()
                let wanted = min(ColdEraseControlBinaryV1.readChunkBytes, count - offset)
                guard let position = off_t(exactly: offset) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                let request = try enter(.read, offset: UInt64(offset), count: wanted)
                let result = scanner.selectedRawBytes!.withUnsafeMutableBytes { buffer in
                    Darwin.pread(descriptor, buffer.baseAddress!.advanced(by: offset), wanted, position)
                }
                let saved = errno
                try request.record(Int64(result), errno: saved)
                guard result > 0, result <= wanted else { throw EraseIntentStoreError.invalidAuthority }
                try consume(request, result: Int64(result)); try requirePinned()
                offset += result // every successful read advances, <=byteCount actual calls
            }
            var byte: UInt8 = 0
            guard let end = off_t(exactly: expected.rawByteCount) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let eof = try enter(.read, offset: expected.rawByteCount, count: 1)
            let result = Darwin.pread(descriptor, &byte, 1, end), saved = errno
            try eof.record(Int64(result), errno: saved)
            guard result == 0 else { throw EraseIntentStoreError.invalidAuthority }
            try consume(eof, result: 0); try requirePinned()
            guard StoreMigrationCanonicalJSONV1.sha256(scanner.selectedRawBytes!) == (try hash.hex()) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            // Actual Ledger-private closed codec/validate/sole-reencode adapter.
            // It returns no role/clock/IO/permission and must retain no aliases.
            try OwnedStorageLedgerV1.validateColdCatalogCanonicalSource(path: path,
                sourceRole: expected.role.rawValue, semanticVersion: expected.semanticVersion,
                bytes: scanner.selectedRawBytes!)
            try scanner.requirePolicyObservation(scope: scope, resource: self)
            try scanner.selectedRawBytes!.withUnsafeBytes(body)
            try requirePinned(); try streamDigest() // fresh whole source SHA+EOF AFTER consumer
            try scanner.requirePolicyObservation(scope: scope, resource: self)
            guard let currentHash = capturedDigest,
                  ColdEraseScratchFirstCatalogScannerV1.same(currentHash, expected.digest) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            // Keep raw/reencode charge and source window through actual close
            // plus captured-row consumption; no discharge here or on refusal.
        }
        fileprivate func captureBytesOrNames() throws {
            guard !isAncestor else { throw EraseIntentStoreError.invalidAuthority }
            do { if directory { try scanNames() } else { try streamDigest() } }
            catch { state = .uncertain; scanner?.poison(); throw error }
        }
        fileprivate func requireMetadata() throws -> Metadata {
            // LIVE only: never fstat a discharged descriptor.
            try requirePinned()
            guard let capturedFact, let capturedParent,
                  directory ? namesChecked : digestChecked,
                  let capturedDigest else { throw EraseIntentStoreError.invalidAuthority }
            return Metadata(fact: capturedFact, parentFact: capturedParent,
                byteCount: directory ? 0 : capturedFact.size, digest: directory ? nil : capturedDigest)
        }
        private func retainEnteredClose(_ resource: EnteredCloseOwner.Resource,
            request: Request) throws -> EnteredCloseOwner {
            guard pending === request, let scanner else { throw EraseIntentStoreError.invalidAuthority }
            let charge = UInt64(MemoryLayout<EnteredCloseOwner.Resource>.stride
                + 2 * MemoryLayout<EnteredCloseOwner?>.stride)
            try scanner.capacity(charge)
            enteredCloseBacking = try ColdEraseControlBinaryV1.adding(enteredCloseBacking, charge)
            let actual = EnteredCloseOwner(resource) // charged BEFORE allocation; immutable exact identity
            switch resource {
            case .descriptor(let fd):
                guard request.kind == .close, fd == descriptor, fd >= 0,
                      enteredDescriptorCloseOwner == nil, !descriptorCloseAttempted else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                enteredDescriptorCloseOwner = actual // retain BEFORE fence/call
            case .directory(let pointer):
                guard request.kind == .cursorClose, pointer == cursor,
                      enteredCursorCloseOwner == nil, !cursorCloseAttempted else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                enteredCursorCloseOwner = actual // retain BEFORE fence/call
            }
            try request.retainEnteredClose(actual)
            return actual
        }
        fileprivate func closeChecked() throws {
            do {
                try requirePinned()
                guard state == .open, !descriptorCloseAttempted, descriptor >= 0,
                      cursor == nil, cursorDescriptor == -1 else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                let request = try enter(.close)
                let fd = descriptor
                _ = try retainEnteredClose(.descriptor(fd), request: request)
                descriptorCloseAttempted = true; state = .closing
                descriptor = -1 // irreversible fence before actual close; exact owner retained
                let result = Darwin.close(fd), saved = errno
                try request.record(Int64(result), errno: saved)
                guard result == 0 else { throw EraseIntentStoreError.invalidAuthority }
                try consume(request, result: 0); checkedClose = request; state = .closed
            } catch { state = .uncertain; scanner?.poison(); throw error }
        }
        fileprivate func requireClosedNamed() throws {
            guard state == .closed, descriptor == -1, descriptorCloseAttempted,
                  cursor == nil, cursorDescriptor == -1, pending == nil, seen.isEmpty,
                  let checkedClose, checkedClose.kind == .close, checkedClose.result == 0,
                  checkedClose.savedErrno != nil, let enteredDescriptorCloseOwner,
                  checkedClose.enteredCloseOwner === enteredDescriptorCloseOwner,
                  let capturedFact, let capturedParent else {
                throw EraseIntentStoreError.invalidAuthority
            }
            if !isAncestor && directory {
                guard namesChecked, cursorCloseAttempted,
                      checkedCursorClose?.kind == .cursorClose,
                      checkedCursorClose?.result == 0, checkedCursorClose?.savedErrno != nil,
                      let enteredCursorCloseOwner,
                      checkedCursorClose?.enteredCloseOwner === enteredCursorCloseOwner else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            // Distinct post-close request against the STILL-HELD genuine single-component parent.
            let parentValue = try statParent(afterClose: true), named = try statNamed(afterClose: true)
            try requireOwnership(named, parentValue: parentValue)
            guard ColdEraseScratchFirstCatalogScannerV1.same(capturedFact,
                      try ColdEraseScratchFirstCatalogScannerV1.fact(named)),
                  ColdEraseScratchFirstCatalogScannerV1.same(capturedParent,
                      try ColdEraseScratchFirstCatalogScannerV1.fact(parentValue)) else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        fileprivate func closedMetadata() throws -> Metadata {
            try requireClosedNamed()
            guard !isAncestor, let capturedFact, let capturedParent, let capturedDigest else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return Metadata(fact: capturedFact, parentFact: capturedParent,
                byteCount: directory ? 0 : capturedFact.size, digest: directory ? nil : capturedDigest)
        }
    }
}


/// Bounded comparison DATA built from the scanner's identical active resource.
/// No node, full fact, URL or policy value authorizes a content effect.
@MainActor struct ColdEraseScratchFirstCatalogPolicyNodeV1 {
    struct Ancestor {
        let url: URL
        let fullFact: String
        let recordedFullMode: UInt32?

        fileprivate init(url: URL, fact: ColdEraseCatalogSourceIndexV1.Fact) throws {
            guard url.isFileURL, url == url.standardizedFileURL,
                  fact.mode & UInt64(S_IFMT) == UInt64(S_IFDIR),
                  fact.links >= 2, let mode = UInt32(exactly: fact.mode) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            self.url = url; fullFact = fact.rendered; recordedFullMode = mode
        }
    }

    let kind: OwnedFileKindV1
    let url: URL
    let fullFact: String
    let parentURL: URL
    let parentFullFact: String
    let ancestors: [Ancestor]
    let recordedFullMode: UInt32?
    let byteCount: Int64?
    let sha256: String?

    fileprivate init(scanner: ColdEraseScratchFirstCatalogScannerV1,
        resource: ColdEraseScratchFirstCatalogScannerV1.NodeResource,
        parentURL: URL, parentFullFact: String, ancestors: [Ancestor]) throws {
        try scanner.requireNodeDataConstruction(resource)
        let metadata = try resource.requireMetadata()
        guard resource.url.isFileURL, resource.url == resource.url.standardizedFileURL,
              parentURL.isFileURL, parentURL == parentURL.standardizedFileURL,
              !ancestors.isEmpty, ancestors.count <= 65,
              ancestors.last?.url == parentURL,
              ancestors.last?.fullFact == parentFullFact,
              metadata.parentFact.rendered == parentFullFact,
              let mode = UInt32(exactly: metadata.fact.mode) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        kind = resource.kind; url = resource.url; fullFact = metadata.fact.rendered
        self.parentURL = parentURL; self.parentFullFact = parentFullFact
        self.ancestors = ancestors; recordedFullMode = mode
        if kind == .stagingDirectory {
            guard metadata.fact.mode & UInt64(S_IFMT) == UInt64(S_IFDIR),
                  metadata.fact.links >= 2, metadata.digest == nil,
                  metadata.fact.mode & 0o7777 == 0o700
                    || metadata.fact.mode & 0o7777 == 0o2700 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            byteCount = nil; sha256 = nil
        } else if kind == .temporaryFile {
            guard metadata.fact.mode & UInt64(S_IFMT) == UInt64(S_IFREG),
                  metadata.fact.mode & 0o7777 == 0o600, metadata.fact.links == 1,
                  metadata.fact.size == metadata.byteCount,
                  let count = Int64(exactly: metadata.byteCount),
                  let digest = metadata.digest else {
                throw EraseIntentStoreError.invalidAuthority
            }
            byteCount = count; sha256 = try digest.hex()
        } else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try scanner.requireNodeDataConstruction(resource)
    }
}

/// Genuine pre-Attempt read-only origin. The scanner retains this Scope before
/// PFP entry. No Original/Diagnostics scope or fixed-root setter is aliased.
@MainActor final class ColdEraseScratchFirstCatalogObservationScopeV1 {
    private enum State { case observing, completed, consumed, revoked, uncertain }
    private var state: State = .observing
    private let scanner: ColdEraseScratchFirstCatalogScannerV1
    private let resource: ColdEraseScratchFirstCatalogScannerV1.NodeResource
    private var observation: ColdEraseScratchFirstCatalogPolicyObservationV1?
    let operationID: UUID
    let node: ColdEraseScratchFirstCatalogPolicyNodeV1

    fileprivate init(scanner: ColdEraseScratchFirstCatalogScannerV1,
        resource: ColdEraseScratchFirstCatalogScannerV1.NodeResource) throws {
        try scanner.requireNodeDataConstruction(resource)
        self.scanner = scanner; self.resource = resource
        operationID = scanner.operationID
        node = try scanner.makePolicyNode(resource: resource)
        try scanner.requireNodeDataConstruction(resource)
        // Scanner installs this exact returned object before PFP's first IO;
        // currentBinding cannot run recursively during that construction.
    }

    func requireCurrentBinding() throws {
        guard state == .observing || state == .completed || state == .consumed else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try scanner.requirePolicyObservation(scope: self, resource: resource)
        guard operationID == scanner.operationID else { throw EraseIntentStoreError.invalidAuthority }
    }

    func requireNode(_ kind: OwnedFileKindV1, at url: URL,
        fullFact: String) throws -> ColdEraseScratchFirstCatalogPolicyNodeV1 {
        try requireCurrentBinding()
        guard kind == node.kind, url == node.url, fullFact == node.fullFact else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return node
    }

    func retainObservationAttempt(_ observation: ColdEraseScratchFirstCatalogPolicyObservationV1) throws {
        try requireCurrentBinding()
        guard state == .observing, self.observation == nil,
              observation.scopeIdentity == ObjectIdentifier(self),
              observation.operationID == operationID,
              observation.kind == node.kind, observation.url == node.url,
              observation.beforeFullFact == node.fullFact else {
            throw EraseIntentStoreError.invalidAuthority
        }
        self.observation = observation // BEFORE its first getter/pin/open
    }

    func requireObservationAttempt(_ observation: ColdEraseScratchFirstCatalogPolicyObservationV1) throws {
        try requireCurrentBinding()
        guard self.observation === observation,
              observation.scopeIdentity == ObjectIdentifier(self),
              observation.operationID == operationID,
              observation.kind == node.kind, observation.url == node.url,
              observation.beforeFullFact == node.fullFact else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    func requireObservationCapacity(_ observation: ColdEraseScratchFirstCatalogPolicyObservationV1,
        additionalBytes: UInt64) throws {
        try requireObservationAttempt(observation)
        guard state == .observing else { throw EraseIntentStoreError.invalidAuthority }
        try scanner.requirePolicyObservationCapacity(observation: observation,
            scope: self, resource: resource, additionalBytes: additionalBytes)
        try requireObservationAttempt(observation)
    }

    func completeObservationAttempt(_ observation: ColdEraseScratchFirstCatalogPolicyObservationV1) throws {
        try requireObservationAttempt(observation)
        guard state == .observing else { throw EraseIntentStoreError.invalidAuthority }
        try observation.requireCheckedSettlement()
        guard let value = observation.value,
              try ColdEraseControlBinaryV1.policyCode(value) != 0 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        state = .completed
        try requireObservationAttempt(observation)
    }

    /// Only the actual scanner calls this after its independent scalar row
    /// consumer and every row-owned positive checked close/current reproof.
    fileprivate func consumeCapturedRow(scanner: ColdEraseScratchFirstCatalogScannerV1,
        resource: ColdEraseScratchFirstCatalogScannerV1.NodeResource) throws {
        try requireCurrentBinding()
        guard self.scanner === scanner, self.resource === resource,
              state == .completed, let observation, observation.value != nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try observation.requireCheckedSettlement()
        try scanner.requireCheckedNodeResource(resource, scope: self)
        state = .consumed
        try requireConsumedObservationAttempt(observation)
    }

    func requireConsumedObservationAttempt(_ observation: ColdEraseScratchFirstCatalogPolicyObservationV1) throws {
        try requireObservationAttempt(observation)
        guard state == .consumed, observation.value != nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try observation.requireCheckedSettlement()
        try scanner.requireCheckedNodeResource(resource, scope: self)
    }

    fileprivate func releaseCapturedRow(scanner: ColdEraseScratchFirstCatalogScannerV1,
        resource: ColdEraseScratchFirstCatalogScannerV1.NodeResource) throws {
        guard self.scanner === scanner, self.resource === resource,
              state == .consumed, let observation else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try requireConsumedObservationAttempt(observation)
        try observation.releaseConsumedScope(self)
        try scanner.requireCheckedNodeResource(resource, scope: self)
        self.observation = nil; state = .revoked
    }

    fileprivate func requireReleasedCapturedRow(scanner: ColdEraseScratchFirstCatalogScannerV1,
        resource: ColdEraseScratchFirstCatalogScannerV1.NodeResource) throws {
        guard self.scanner === scanner, self.resource === resource,
              state == .revoked, observation == nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try scanner.requireCheckedNodeResource(resource, scope: self)
    }

    func retainUncertainDescriptor(_ descriptor: Int32) {
        scanner.retainUncertainPolicyDescriptor(descriptor, resource: resource)
        state = .uncertain
    }

    func poisonOnUncertainObservation() {
        state = .uncertain
        scanner.poisonOnUncertainObservation(resource: resource)
    }
}

/// A cut is issued only by the retained checked Store observer. Its values
/// are comparison DATA; use requires a new check by that same actual owner.
@MainActor final class ColdEraseScratchCapsuleControlCutV1 {
    let eraseRoot: EraseColdControlLeafFactV1
    let names: [String]
    let coreSHA256: String?
    let coreByteCount: UInt64?
    let progressSHA256: String?
    let progressByteCount: UInt64?
