    private var transferredOwner: ColdEraseSchema2TransferredControlOwnerV1?
    private var transferredEpoch: ColdEraseSchema2TransferredControlOwnerV1.Epoch?
    fileprivate init(transferredOwner: ColdEraseSchema2TransferredControlOwnerV1,
        epoch: ColdEraseSchema2TransferredControlOwnerV1.Epoch,
        observer: ColdEraseScratchControlObserverV1,
        eraseRoot: EraseColdControlLeafFactV1, names: [String],
        coreSHA256: String, coreByteCount: UInt64, progressSHA256: String, progressByteCount: UInt64) {
        self.observer = observer; self.transferredOwner = transferredOwner; transferredEpoch = epoch
        self.eraseRoot = eraseRoot; self.names = names
        self.coreSHA256 = coreSHA256; self.coreByteCount = coreByteCount
        self.progressSHA256 = progressSHA256; self.progressByteCount = progressByteCount
    }
    fileprivate func requireTransferredIssuer(_ owner: ColdEraseSchema2TransferredControlOwnerV1) throws {
        guard transferredOwner === owner, let transferredEpoch else { throw EraseIntentStoreError.invalidAuthority }
        try owner.requireIssuedEpochMemory(transferredEpoch, cut: self)
    }
    // POSTCONTENT_TRANSFERRED_CONTROL_CUT_V1_END

    private let observer: ColdEraseScratchControlObserverV1
    fileprivate init(observer: ColdEraseScratchControlObserverV1,
        eraseRoot: EraseColdControlLeafFactV1, names: [String]) {
        self.observer = observer; self.eraseRoot = eraseRoot; self.names = names
        coreSHA256 = nil; coreByteCount = nil
        progressSHA256 = nil; progressByteCount = nil
    }
    fileprivate static var declaredPublishedStoredBackingBytes: UInt64 {
        UInt64(MemoryLayout<EraseColdControlLeafFactV1>.stride + MemoryLayout<[String]>.stride
            + 2 * MemoryLayout<String?>.stride + 2 * MemoryLayout<UInt64?>.stride
            + MemoryLayout<ColdEraseScratchControlObserverV1>.stride
            + MemoryLayout<ColdEraseSchema2TransferredControlOwnerV1?>.stride
            + MemoryLayout<ColdEraseSchema2TransferredControlOwnerV1.Epoch?>.stride)
        // Exact actual separately stored value/reference fields. Name/hash
        // payload and returned value aliases are in the owning profile.
    }
    fileprivate init(observer: ColdEraseScratchControlObserverV1,
        eraseRoot: EraseColdControlLeafFactV1, names: [String],
        core: ColdEraseScratchPublishedResourceOperandV1,
        progress: ColdEraseScratchPublishedResourceOperandV1) {
        self.observer = observer; self.eraseRoot = eraseRoot; self.names = names
        coreSHA256 = core.sha256; coreByteCount = core.byteCount
        progressSHA256 = progress.sha256; progressByteCount = progress.byteCount
    }
    fileprivate init(observer: ColdEraseScratchControlObserverV1,
        currentRequestOwner: ColdEraseScratchRequestSemanticOwnerV2,
        eraseRoot: EraseColdControlLeafFactV1, names: [String],
        coreSHA256: String, coreByteCount: UInt64,
        progressSHA256: String, progressByteCount: UInt64) {
        self.observer = observer; self.eraseRoot = eraseRoot; self.names = names
        self.coreSHA256 = coreSHA256; self.coreByteCount = coreByteCount
        self.progressSHA256 = progressSHA256; self.progressByteCount = progressByteCount
    }
    func requireBound(store: EraseIntentStore,
        operation: EraseColdPreparationOperationV1,
        ranges: ColdEraseScratchPayloadRangesV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        try observer.requireAssociation(store: store, operation: operation,
            ranges: ranges, scope: scope)
        let current = try observer.capture()
        guard current.eraseRoot == eraseRoot, current.names == names,
              current.coreSHA256 == coreSHA256, current.coreByteCount == coreByteCount,
              current.progressSHA256 == progressSHA256,
              current.progressByteCount == progressByteCount else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }
}

/// One bounded actual observer, retained before its first IO. It initially
/// admits only the four genuine incumbent controls. Adding a capsule name
/// requires a separate consumed writer transition; an observed new child can
/// never expand this vocabulary or replace the retained first control facts.
@MainActor fileprivate final class ColdEraseScratchControlObserverV1 {
    private enum Kind { case heldSupport, namedSupport, capacity,
        heldRoot, namedRoot, heldLeaf, namedLeaf, openLeaf,
        readLeaf, closeLeaf, openEnumeration, adoptEnumeration, readName, closeEnumeration }
    private final class Entry {
        let kind: Kind
        let enteredDescriptor: Int32?
        let enteredDirectory: UnsafeMutablePointer<DIR>?
        private(set) var result: Int64?
        private(set) var savedErrno: Int32?
        init(_ kind: Kind, descriptor: Int32? = nil,
            directory: UnsafeMutablePointer<DIR>? = nil) {
            self.kind = kind; enteredDescriptor = descriptor
            enteredDirectory = directory
        }
        func record(_ result: Int64, _ savedErrno: Int32) throws {
            guard self.result == nil, self.savedErrno == nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
            self.result = result; self.savedErrno = savedErrno
        }
    }
    private weak var owner: ColdEraseScratchPayloadRangesV1?
    private let store: EraseIntentStore
    private let operation: EraseColdPreparationOperationV1
    private let scope: ColdEraseScratchCleanupHeldGScopeV1
    private let support: Int32, erase: Int32
    private let eraseURL: URL
    private let directoryName: String, intentName: String
    private let preparationName: String, auxiliaryName: String
    private let first: EraseIntentStore.Schema2ColdPostGenerationControlCutV1
    private let firstSupport: EraseColdControlLeafFactV1
    private var active: Entry?
    private var lastConsumed: Entry?
    private var leafFD: Int32 = -1
    private var enumerationFD: Int32 = -1
    private var directory: UnsafeMutablePointer<DIR>?
    private var retainedBuffer: Data?
    private var bufferCharge: UInt64 = 0
    private var uncertainPolicyDescriptors: [Int32] = []
    private var uncertain = false
    private var capturing = false
    var retainedBufferBytes: UInt64 { bufferCharge }

    // Two actual Entry owners can overlap: last consumed plus current.
    // This covers their stored cells, not opaque runtime/allocator tables.
    fileprivate static func declaredInitialStoredCellBackingBytesV4() throws -> UInt64 {
        func cells<T>(_ type: T.Type, _ count: UInt64) throws -> UInt64 {
            let one = try ColdEraseControlBinaryV1.adding(UInt64(MemoryLayout<T>.stride),
                UInt64(MemoryLayout<T>.alignment - 1))
            return try ColdEraseControlBinaryV1.multiplying(count, one)
        }
        var bytes: UInt64 = 0
        bytes = try ColdEraseControlBinaryV1.adding(bytes, cells(Optional<ColdEraseScratchPayloadRangesV1>.self, 1))
        bytes = try ColdEraseControlBinaryV1.adding(bytes, cells(EraseIntentStore.self, 1))
        bytes = try ColdEraseControlBinaryV1.adding(bytes, cells(EraseColdPreparationOperationV1.self, 1))
        bytes = try ColdEraseControlBinaryV1.adding(bytes, cells(ColdEraseScratchCleanupHeldGScopeV1.self, 1))
        bytes = try ColdEraseControlBinaryV1.adding(bytes, cells(Int32.self, 4))
        bytes = try ColdEraseControlBinaryV1.adding(bytes, cells(URL.self, 1))
        bytes = try ColdEraseControlBinaryV1.adding(bytes, cells(String.self, 4))
        bytes = try ColdEraseControlBinaryV1.adding(bytes, cells(EraseIntentStore.Schema2ColdPostGenerationControlCutV1.self, 1))
        bytes = try ColdEraseControlBinaryV1.adding(bytes, cells(EraseColdControlLeafFactV1.self, 1))
        bytes = try ColdEraseControlBinaryV1.adding(bytes, cells(Optional<Entry>.self, 2))
        bytes = try ColdEraseControlBinaryV1.adding(bytes, cells(Optional<UnsafeMutablePointer<DIR>>.self, 1))
        bytes = try ColdEraseControlBinaryV1.adding(bytes, cells(Optional<Data>.self, 1))
        bytes = try ColdEraseControlBinaryV1.adding(bytes, cells(UInt64.self, 1))
        bytes = try ColdEraseControlBinaryV1.adding(bytes, cells([Int32].self, 1))
        bytes = try ColdEraseControlBinaryV1.adding(bytes, cells(Bool.self, 2))
        bytes = try ColdEraseControlBinaryV1.adding(bytes, cells(Kind.self, 2))
        bytes = try ColdEraseControlBinaryV1.adding(bytes, cells(Optional<Int32>.self, 4))
        bytes = try ColdEraseControlBinaryV1.adding(bytes, cells(Optional<UnsafeMutablePointer<DIR>>.self, 2))
        bytes = try ColdEraseControlBinaryV1.adding(bytes, cells(Optional<Int64>.self, 2))
        return bytes
    }

    init(owner: ColdEraseScratchPayloadRangesV1, store: EraseIntentStore,
        operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        support: Int32, erase: Int32, eraseURL: URL,
        directoryName: String, intentName: String,
        preparationName: String, auxiliaryName: String,
        first: EraseIntentStore.Schema2ColdPostGenerationControlCutV1,
        firstSupport: EraseColdControlLeafFactV1) {
        self.owner = owner; self.store = store; self.operation = operation
        self.scope = scope; self.support = support; self.erase = erase
        self.eraseURL = eraseURL; self.first = first; self.firstSupport = firstSupport
        self.directoryName = directoryName; self.intentName = intentName
        self.preparationName = preparationName; self.auxiliaryName = auxiliaryName
    }
    func requireAssociation(store: EraseIntentStore,
        operation: EraseColdPreparationOperationV1,
        ranges: ColdEraseScratchPayloadRangesV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        guard self.store === store, self.operation === operation,
              owner === ranges, self.scope === scope, !uncertain else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try ranges.requireCapsuleObservationFrame(self)
        try ranges.requireScratchControlScopeAssociation(scope)
    }
    private func frame() throws {
        guard !uncertain, uncertainPolicyDescriptors.isEmpty, let owner else {
