    private func names() throws -> [String] {
        guard enumerationFD == -1, directory == nil else { throw EraseIntentStoreError.invalidAuthority }
        guard let owner else { throw EraseIntentStoreError.invalidAuthority }
        let expected = try owner.capsuleObserverProjection(self).1
        guard expected.count >= 4, expected.count <= 6 else { throw EraseIntentStoreError.invalidAuthority }
        _ = try root()
