            guard requestCount < expected.count + 3 else { throw EraseIntentStoreError.invalidAuthority }
            requestCount += 1 // includes both dot entries and the actual EOF call
            let request = try enter(.readName)
            errno = 0
            let entry = readdir(stream), saved = errno
            try request.record(entry == nil ? 0 : 1, saved)
            guard entry != nil || saved == 0 else { throw EraseIntentStoreError.invalidAuthority }
            try consume(request, result: entry == nil ? 0 : 1)
            guard let entry else { break }
            entryCount += 1
