                  entry.pointee.d_namlen > 0, entry.pointee.d_namlen <= 255 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            _ = try root()
            let name = withUnsafePointer(to: &entry.pointee.d_name) {
                $0.withMemoryRebound(to: CChar.self, capacity: 256) { String(validatingUTF8: $0) }
            }
            guard let name, name.utf8.count == Int(entry.pointee.d_namlen) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            if name == "." || name == ".." { continue }
            guard expected.contains(name), !names.contains(name), names.count < expected.count else {
                throw EraseIntentStoreError.invalidAuthority
