            guard let owner else { throw EraseIntentStoreError.invalidAuthority }
            try owner.requireCapsuleObserverOwnedLeaf(self)
            let before = try root(), beforeNames = try names()
            try read(intentName, expected: first.intentFact, bytes: first.intentBytes)
            try read(preparationName, expected: first.preparationFact, bytes: first.preparationBytes)
            try read(auxiliaryName, expected: first.auxiliaryProjectedFact, bytes: first.auxiliaryBytes)
            try read(EraseSchema2ColdDeletionRosterV1.canonicalName, expected: first.deletionFact, bytes: first.deletionBytes)
            guard try root() == before, try names() == beforeNames,
