@MainActor extension EraseIntentStore {
    // INITIAL_V4_ENCLOSING_AUTHENTIC_CALLER_V1_BEGIN
    /// Actual Main owns the entry/projection/loan/charge before first IO and
    /// retains the real returned Range before registration/named-source proof.
    /// Native keeps the constructor and genuine private Source producer here.
    func withSchema2ColdScratchPayloadRanges(
        operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        _ body: (ColdEraseScratchPayloadRangesV1) throws -> ColdEraseSchema2PostContentScopeV1
    ) throws -> ColdEraseSchema2PostContentScopeV1 {
        let ranges: ColdEraseScratchPayloadRangesV1
        do {
            ranges = try operation.prepareColdScratchInitialBirthRangesV4(store: self, scope: scope,
                declaredRangeBacking: {
                    try ColdEraseControlBinaryV1.adding(
                        ColdEraseScratchPayloadRangesV1.declaredInitialStoredCellBackingBytesV4(),
                        ColdEraseScratchControlObserverV1.declaredInitialStoredCellBackingBytesV4())
                }, make: { projection, charge in
                    ColdEraseScratchPayloadRangesV1(initialV4Operation: operation,
                        store: self, scope: scope, issuedProjection: projection,
                        retainedInitialCharge: charge)
                })
        } catch {
            scope.poisonOnUncertainCleanup(); operation.poisonColdScratchOwner()
            throw error // actual Main retains failed entry/Range before this propagation
        }
        do {
            try ranges.beginInitialColdScratchProducerV4()
            try installSchema2ColdCapsuleObserver(operation: operation, scope: scope, ranges: ranges)
            let source = try ranges.prepareColdContinuationCoreBirthSourceV4()
            let publisher = try ranges.beginColdContinuationZeroTemporary()
            try publisher.writeContinuationSource(source) // SAME real chain installs both resources/catalog
            _ = try ranges.capturePreSeedWholeCurrent(operation: operation, scope: scope)
            try ranges.enterInitialColdScratchMainBodyV4()
            let successor = try body(ranges) // actual Main policy/identity/admission/Attempt/transfer once
            try ranges.completeInitialColdScratchMainReturnV4(successor)
            return successor // Main alone revokes SAME loan, commits and checked-releases G
        } catch {
            ranges.retainInitialColdScratchProducerFailureV4(error)
            scope.poisonOnUncertainCleanup(); operation.poisonColdScratchOwner()
            throw error
        }
    }
