// NAMESPACE_AUTHENTIC_FROZEN_CORE_ORIGIN_V1_BEGIN
/// Authentic immutable published core and retired prefix DATA. This cannot
/// issue a Reader recipe, current selected frame, setter, REQUEST or effect.
@MainActor fileprivate final class ColdEraseSchema2NamespaceFrozenCoreOriginV1 {
    fileprivate struct Storage {
        let ranges: ColdEraseScratchPayloadRangesV1
        let reservation: ColdEraseSchema2NamespaceCaptureReservationV1
        let capture: ColdEraseSchema2NamespaceCaptureOwnerV1
        let controlOwner: ColdEraseSchema2TransferredControlOwnerV1
        let identity: ColdEraseScratchBirthIdentityInitializationV1
        let cut: ColdEraseScratchCapsuleControlCutV1
        let headerBytes: Data
        let metadataBytes: Data
        var header: ColdEraseControlBinaryV1.Header?
        var metadata: ColdEraseControlBinaryV1.Metadata?
        var coreSHA256: Data?
        var progressSHA256: String?
        var stateSHA256: Data?
        var frameSHA256: Data?
        var completeProgressOffset: UInt64 = 0
        var completeRequestCount: UInt64 = 0
        var prepared = false
        var failure: Error?
    }
    fileprivate var storage: Storage
    fileprivate static var declaredBackingBytes: UInt64 {
        UInt64(MemoryLayout<Storage>.stride + MemoryLayout<ColdEraseControlBinaryV1.Header>.stride
            + MemoryLayout<ColdEraseControlBinaryV1.Metadata>.stride
            + 64 * MemoryLayout<[UInt64]>.stride + 64 * MemoryLayout<Data>.stride
            + 16 * MemoryLayout<Data>.stride + 6 * MemoryLayout<UInt64>.stride)
            + 4 * 16_384 + 4 * 128 + 64 * 11 * 8 + 64 * 32 + 16 * 16 + 64 * 8 + 128 + 8 * 32 + 4 * 64
    }
    fileprivate init(ranges: ColdEraseScratchPayloadRangesV1,
        reservation: ColdEraseSchema2NamespaceCaptureReservationV1,
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        controlOwner: ColdEraseSchema2TransferredControlOwnerV1,
        identity: ColdEraseScratchBirthIdentityInitializationV1,
        cut: ColdEraseScratchCapsuleControlCutV1, headerBytes: Data, metadataBytes: Data) {
        storage = .init(ranges: ranges, reservation: reservation, capture: capture,
            controlOwner: controlOwner, identity: identity, cut: cut,
            headerBytes: headerBytes, metadataBytes: metadataBytes)
    }
    fileprivate func requireMemoryAssociation() throws {
        guard storage.failure == nil,
              storage.identity === storage.controlOwner.storage.source.storage.identity,
              storage.identity.storage.phase == .installed,
              storage.identity.storage.retainedFailure == nil,
              storage.identity.storage.coreHeader == storage.headerBytes,
              storage.identity.storage.metadata == storage.metadataBytes,
              storage.headerBytes.count == 128, storage.metadataBytes.count == 16_384 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try storage.reservation.requireCompletedNamespaceCaptureMemory(storage.capture)
        try storage.ranges.requireNamespaceFrozenCoreOriginMemory(self)
        try storage.controlOwner.requireNamespaceFrozenCoreOriginSource(self)
        try storage.cut.requireTransferredIssuer(storage.controlOwner)
        // Closed issued Source/row/resource facts; no original loan/current IO.
    }
    fileprivate func prepare() throws {
        do {
            try requireMemoryAssociation()
            guard !storage.prepared, storage.header == nil, storage.metadata == nil,
                  let origin = storage.controlOwner.storage.origin,
                  let actualCoreSHA = storage.cut.coreSHA256,
                  let actualProgressSHA = storage.cut.progressSHA256,
                  let actualCoreCount = storage.cut.coreByteCount,
                  let actualProgressCount = storage.cut.progressByteCount,
                  actualCoreSHA == origin.core.sha256, actualCoreCount == origin.core.byteCount,
                  actualProgressSHA == origin.progressSHA256,
                  actualProgressCount == origin.progressByteCount else {
                throw EraseIntentStoreError.invalidAuthority
            }
            storage.header = try ColdErasePostContentBinaryV3.decodeHeader(storage.headerBytes)
            storage.metadata = try ColdEraseControlBinaryV1.decodeMetadata(storage.metadataBytes, kind: .continuation)
            guard storage.header?.kind == .continuation,
                  storage.header?.encodedByteCount == actualCoreCount,
                  let metadata = storage.metadata, metadata.digests.count == 64,
                  metadata.identifiers.count == 16, metadata.words.count == 64,
                  metadata.facts.count == 64, metadata.flags.count == 128,
                  metadata.digests[2] == (try ColdEraseControlBinaryV1.rawSHA256(
                    StoreMigrationCanonicalJSONV1.sha256(storage.controlOwner.storage.first.auxiliaryBytes))) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            storage.coreSHA256 = try ColdEraseControlBinaryV1.rawSHA256(actualCoreSHA)
            storage.progressSHA256 = actualProgressSHA
            storage.stateSHA256 = origin.stateDigest.codecData()
            storage.frameSHA256 = origin.frameDigest?.codecData()
            storage.completeProgressOffset = actualProgressCount
            if let history = origin.history {
                try history.requireRetiredControlOriginMemory(ranges: storage.ranges)
                guard let completion = history.storage.observation.storage.completion,
                      completion.pending == nil, completion.tail == nil,
                      completion.completePrefixByteCount == actualProgressCount,
                      completion.completeRequestCount == UInt64(completion.settledCount),
                      completion.completeRequestCount == 1 else { throw EraseIntentStoreError.invalidAuthority }
