                try storage.ranges.requireUnchanged64TransferredOrigin(storage.controlOwner)
                guard actualProgressCount == 64, origin.frameDigest == nil else { throw EraseIntentStoreError.invalidAuthority }
                storage.completeRequestCount = 0
            }
            try requireMemoryAssociation(); storage.prepared = true
        } catch {
            if storage.failure == nil { storage.failure = error }
            storage.ranges.poison(); throw error
        }
    }
}
