        }
        var stride: UInt64 {
            switch self {
            case .scans: return UInt64(MemoryLayout<Scan>.stride)
            case .rows: return UInt64(MemoryLayout<Row>.stride)
            case .trees: return UInt64(MemoryLayout<TreeResult>.stride)
            case .resources: return UInt64(MemoryLayout<ReadResource>.stride)
            case .names, .tokens: return UInt64(MemoryLayout<String>.stride)
            case .tokenSets: return UInt64(MemoryLayout<TokenSet>.stride)
