        if count <= capacity { return capacity }
        let double = capacity.multipliedReportingOverflow(by: 2)
        guard !double.overflow else { throw EraseIntentStoreError.invalidAuthority }
        let next = min(role.limit, max(count, max(1, double.partialValue)))
        try reserve(try ColdEraseControlBinaryV1.multiplying(ColdEraseControlBinaryV1.multiplying(UInt64(next), role.stride), 2))
        return next // old backing and all resize overlap remain conservatively charged
    }
    fileprivate func recordArray(_ role: ArrayRole, requested: Int, actual: Int, count: Int) throws {
        guard actual >= count else { throw EraseIntentStoreError.invalidAuthority }
        let ceiling = requested.multipliedReportingOverflow(by: 2)
        guard !ceiling.overflow else { throw EraseIntentStoreError.invalidAuthority }
        if actual > ceiling.partialValue {
            storage.charge = try ColdEraseControlBinaryV1.adding(storage.charge,
                ColdEraseControlBinaryV1.multiplying(UInt64(actual - ceiling.partialValue), role.stride))
            throw EraseIntentStoreError.invalidAuthority
