            case .directory(let expectedFact, let expectedSHA):
                guard Self.full(root.fact) == expectedFact, branchDigest == expectedSHA else { throw EraseIntentStoreError.invalidAuthority }
            case .regular(let expectedFact, let expectedSHA):
                guard Self.full(root.fact) == expectedFact, root.sha256 == expectedSHA,
                      branchEnd - branchStart == 1 else { throw EraseIntentStoreError.invalidAuthority }
            }
