        }
        guard branchStart == end else { throw EraseIntentStoreError.invalidAuthority }
        if !afterSetter {
            guard fact == storage.context.notificationAfter.operations.rootFact,
                  case .present(_, let expected) = storage.context.notificationAfter.operations,
                  digest == expected else { throw EraseIntentStoreError.invalidAuthority }
        }
    }
