    /// SHA256.Digest supplies its fixed 32 bytes as a Sequence, rather
    /// than Collection. This performs the same lowercase per-byte encoding
    /// with one 64-byte logical String output and no Array/Data clone.
    fileprivate static func hex(_ bytes: SHA256.Digest) -> String {
        return String(unsafeUninitializedCapacity: 64) { output in
            var at = 0
            for byte in bytes {
                let hi = byte >> 4, lo = byte & 15
                output[at] = hi < 10 ? hi + 48 : hi + 87
                output[at + 1] = lo < 10 ? lo + 48 : lo + 87; at += 2
            }
            return at
        }
    }
    fileprivate static func hex<C: Collection>(_ bytes: C) -> String where C.Element == UInt8 {
        let count = bytes.count * 2
        return String(unsafeUninitializedCapacity: count) { output in
            var at = 0
            for byte in bytes {
                let hi = byte >> 4, lo = byte & 15
                output[at] = hi < 10 ? hi + 48 : hi + 87
                output[at + 1] = lo < 10 ? lo + 48 : lo + 87; at += 2
            }
            return count
        }
    }
