        } catch { poison(error); throw error }
    }
    /// Positive private whole-current materialization/consumer boundary.
    /// Shared node/path/fullFact/policy/SHA buffers stay strongly charged in
    /// this owner. This proves an actual returned product, never new IO or a
    /// Seed/state transition. A downstream issuer must retain this same owner.
    func requireMaterializedCurrentImage(ranges: ColdEraseScratchPayloadRangesV1,
        store: EraseIntentStore, operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws -> OriginalEraseScratchCleanupImageV1 {
        try requireAssociation(ranges: ranges, store: store, operation: operation, scope: scope)
        guard storage.materializationBorrowEntered, storage.materializationBorrowReturned,
              storage.materializationAfterPairChecked, let actual = storage.image,
              storage.activeScan == nil, storage.activeResource == nil else { throw EraseIntentStoreError.invalidAuthority }
        return actual // authentic charged value aliases; owning observer must remain retained
    }
    private func consumeImageBody(_ body: (OriginalEraseScratchCleanupImageV1) throws -> Void) throws {
        guard let image = storage.image, storage.materializationBorrowEntered,
              !storage.materializationBorrowReturned else { throw EraseIntentStoreError.invalidAuthority }
        try body(image) // all shared backing remains charged and strongly owned
    }
    private func materializeRoot(name: String, scan: Int) throws -> OriginalEraseScratchCleanupImageV1.Root? {
        guard storage.materializingRoot == nil else { throw EraseIntentStoreError.invalidAuthority }
        guard let start = storage.scans[scan].rows.firstIndex(where: {
            storage.context.physical.record.trees[$0.tree].key == "support/FieldEvidenceOperations" && $0.path == name
        }) else { return nil } // absence comes from the exact positive whole pair, not nil-as-authority
        let tree = storage.scans[scan].rows[start].tree
        var end = start + 1
        try stringBytes(UInt64(name.utf8.count + 1))
        let prefix = name + "/"
        while end < storage.scans[scan].rows.count && storage.scans[scan].rows[end].tree == tree && storage.scans[scan].rows[end].path.hasPrefix(prefix) { end += 1 }
        guard end - start <= 100_000 else { throw EraseIntentStoreError.invalidAuthority }
        storage.materializingRoot = name
        storage.materializedNodes = [] // previous Root owns its actual array; old charge remains
        let capacity = try prepareArray(.imageNodes, capacity: 0, count: end - start)
        storage.materializedNodes.reserveCapacity(capacity)
        try recordArray(.imageNodes, requested: capacity, actual: storage.materializedNodes.capacity, count: end - start)
        for position in start..<end {
            let row = storage.scans[scan].rows[position]
            try stringBytes(UInt64(row.path.utf8.count + 241), copies: 2)
            let path = position == start ? "" : String(row.path.dropFirst(prefix.count))
            let policy = try row.policy.temporal(row.fact)
            storage.materializedNodes.append(.init(path: path, fullFact: Self.full(row.fact), contentSHA256: row.sha256, policy: policy))
        }
        // DFS rows are converted to the incumbent canonical UTF8 path order.
        storage.materializedNodes.sort { $0.path.utf8.lexicographicallyPrecedes($1.path.utf8) }
        let digest = try digestRows(scan: scan, start: start, end: end, relativeRoot: name)
        try stringBytes(241)
        let actual = OriginalEraseScratchCleanupImageV1.Root(fullFact: Self.full(storage.scans[scan].rows[start].fact),
            digest: digest, nodes: storage.materializedNodes)
        let rootCapacity = try prepareArray(.imageRoots, capacity: storage.materializedRoots.capacity, count: storage.materializedRoots.count + 1)
        storage.materializedRoots.reserveCapacity(rootCapacity)
        try recordArray(.imageRoots, requested: rootCapacity, actual: storage.materializedRoots.capacity, count: storage.materializedRoots.count + 1)
        storage.materializedRoots.append(actual); storage.materializingRoot = nil
        return actual
    }

}
