// New readonly whole-observer association. The incumbent completed/scanner
// methods above remain byte-exact. The authentic immutable whole-context
// equality is checked once at real binding; each current row still compares
// every genuine initialized catalog/index/global/path/full9/SHA scalar.
// Live current filesystem and capacity authority is never cached here.
extension ColdEraseScratchFirstCatalogScannerV1 {
    fileprivate func bindPreSeedWholeOriginalContext(observer: ColdEraseScratchPreSeedWholeCurrentObserverV1,
        ranges: ColdEraseScratchPayloadRangesV1, context: Context) throws {
        guard preSeedWholeObserver == nil else { throw EraseIntentStoreError.invalidAuthority }
        preSeedWholeObserver = observer // before fallible original/current association
        _ = try requireIssuedBirthOriginalContext(ranges: ranges, context: context)
        try observer.requireMemoryAssociation(ranges: ranges)
        guard observer.storage.loan === context.loan,
              observer.storage.context.physical.canonicalBytes == context.roster.canonicalBytes,
              observer.storage.context.first == context.first,
              observer.storage.context.notificationAfter == context.after else { throw EraseIntentStoreError.invalidAuthority }
    }
    private func requireBoundPreSeedWholeOriginalNodes(observer: ColdEraseScratchPreSeedWholeCurrentObserverV1,
        ranges: ColdEraseScratchPayloadRangesV1) throws -> [Roster.Node] {
        guard preSeedWholeObserver === observer else { throw EraseIntentStoreError.invalidAuthority }
        let actual = try issuedBirthOperationsRootContext(ranges: ranges)
        try observer.requireMemoryAssociation(ranges: ranges)
        guard observer.storage.loan === actual.loan,
              observer.storage.scope.operationID == actual.operationID,
              actual.roster.record.trees.count == 9,
              actual.treePosition >= 0, actual.treePosition < actual.roster.record.trees.count else { throw EraseIntentStoreError.invalidAuthority }
        let tree = actual.roster.record.trees[actual.treePosition]
        guard tree.key == "support/FieldEvidenceOperations", tree.state == "present",
              let all = tree.nodes, !all.isEmpty, all.count < 100_000,
              all[0].path.isEmpty, all[0].kind == "directory" else { throw EraseIntentStoreError.invalidAuthority }
        return all // original immutable aliases stay on both genuine owners
    }
    fileprivate func issuedPreSeedOriginalOperationsOrdinal(row: Index, observer: ColdEraseScratchPreSeedWholeCurrentObserverV1,
        ranges: ColdEraseScratchPayloadRangesV1, context: Context) throws -> UInt64 {
        let all = try requireBoundPreSeedWholeOriginalNodes(observer: observer, ranges: ranges)
        guard let ordinal = Int(exactly: row.physicalOrdinal), ordinal >= 0, ordinal < index.count,
              rosterPositions.count == index.count else { throw EraseIntentStoreError.invalidAuthority }
        let expected = index[ordinal], position = rosterPositions[ordinal]
        guard position >= 0, position < all.count,
              Self.selected(all[position].path),
              (all[position].kind == "directory") == row.isDirectory,
              expected.physicalOrdinal == row.physicalOrdinal,
              expected.sourceOrdinal == row.sourceOrdinal,
              expected.selectedOrdinalBefore == row.selectedOrdinalBefore,
              expected.pathOffset == row.pathOffset, expected.pathByteCount == row.pathByteCount,
              expected.rawOffset == row.rawOffset, expected.rawByteCount == row.rawByteCount,
              expected.role == row.role, expected.semanticVersion == row.semanticVersion,
              expected.policyCode == row.policyCode,
              Self.same(expected.fact, row.fact), Self.same(expected.digest, row.digest),
              UInt64(all[position].path.utf8.count) == row.pathByteCount,
              Self.issuedBirthNine(row.fact).utf8.elementsEqual(all[position].fact.utf8) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        if row.isDirectory {
            guard all[position].sha256 == nil, all[position].members != nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
        } else {
            guard all[position].members == nil, let originalSHA = all[position].sha256,
                  StoreMigrationCanonicalJSONV1.isLowercaseSHA256(originalSHA),
                  Self.issuedBirthDigestSHA256(row.digest) == originalSHA else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        return UInt64(position) // actual global Ops roster position, never SourceOrdinal
    }

    fileprivate func issuedPreSeedOriginalOperationsNode(originalOperationsOrdinal: UInt64,
        observer: ColdEraseScratchPreSeedWholeCurrentObserverV1,
        ranges: ColdEraseScratchPayloadRangesV1) throws -> Roster.Node {
        let all = try requireBoundPreSeedWholeOriginalNodes(observer: observer, ranges: ranges)
        guard let ordinal = Int(exactly: originalOperationsOrdinal), ordinal >= 0, ordinal < all.count else { throw EraseIntentStoreError.invalidAuthority }
        return all[ordinal] // lexical comparison only; caller stores no returned path/DTO
    }
}


