/// This representation owns actual retained objects, not a decoded request
/// flag or a current stat relabelled as immutable core-birth provenance.
@MainActor final class ColdEraseScratchIngressPolicyRequestV1 {
    fileprivate struct Storage {
        let ranges: ColdEraseScratchPayloadRangesV1
        let store: EraseIntentStore
        let operation: EraseColdPreparationOperationV1
        let scope: ColdEraseScratchCleanupHeldGScopeV1
        let loan: ColdEraseScratchBorrowedParentsV1
        let observer: ColdEraseScratchPreSeedWholeCurrentObserverV1
        let root: ColdEraseScratchPreSeedIngressRootV1
        let core: ColdEraseRetainedControlFileV1
        let writer: ColdEraseScratchCapsuleContinuationWriterV1
        let metadata: ColdEraseControlBinaryV1.Metadata
        let applicationSupportURL: URL
        let normalizedApplicationSupportPathUTF8Count: UInt64
        let firstRootFullFact: String
        let currentRootFullFact: String
        let currentOperationsFullFact: String
        var constructionEntered = false
        var effectScope: ColdEraseScratchIngressPolicyEffectScopeV1?
        var unexpectedEffectScope: ColdEraseScratchIngressPolicyEffectScopeV1?
        var failure: Error?
        var mainArrayHighWater: UInt64 = 0
        var attemptHighWater: UInt64 = 0
    }
    fileprivate var storage: Storage
    var firstRootFullFact: String { storage.firstRootFullFact }
    var currentRootFullFact: String { storage.currentRootFullFact }
    var currentOperationsFullFact: String { storage.currentOperationsFullFact }
    fileprivate init(ranges: ColdEraseScratchPayloadRangesV1, store: EraseIntentStore,
        operation: EraseColdPreparationOperationV1, scope: ColdEraseScratchCleanupHeldGScopeV1,
        loan: ColdEraseScratchBorrowedParentsV1, observer: ColdEraseScratchPreSeedWholeCurrentObserverV1,
        root: ColdEraseScratchPreSeedIngressRootV1, core: ColdEraseRetainedControlFileV1,
        writer: ColdEraseScratchCapsuleContinuationWriterV1, metadata: ColdEraseControlBinaryV1.Metadata,
        applicationSupportURL: URL, pathCount: UInt64, first: String) {
        storage = .init(ranges: ranges, store: store, operation: operation, scope: scope,
            loan: loan, observer: observer, root: root, core: core, writer: writer,
            metadata: metadata, applicationSupportURL: applicationSupportURL,
            normalizedApplicationSupportPathUTF8Count: pathCount, firstRootFullFact: first,
            currentRootFullFact: root.fullFact, currentOperationsFullFact: root.operationsFullFact)
    }
    func requireBound(ranges: ColdEraseScratchPayloadRangesV1, store: EraseIntentStore,
        operation: EraseColdPreparationOperationV1, scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        guard storage.ranges === ranges, storage.store === store,
              storage.operation === operation, storage.scope === scope,
              storage.failure == nil else { throw EraseIntentStoreError.invalidAuthority }
        try ranges.requireIngressRequestAssociation(self)
        try storage.root.requireAssociation(observer: storage.observer, ranges: ranges,
            store: store, operation: operation, scope: scope)
        // Pure emitted/readback lineage. Fresh physical proof belongs to the
        // observer entry, never these callbacks during a setter readback.
        let actual = try storage.writer.issuedBirthIngressMetadata(resource: storage.core, ranges: ranges)
        try ColdEraseScratchIngressDeclaredBackingV1.requireSameRequest(actual, storage.metadata)
        guard storage.root.operationID == scope.operationID,
              currentRootFullFact == storage.root.fullFact,
              currentOperationsFullFact == storage.root.operationsFullFact else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }
    func requireEffectScopeConstructionCapacity(operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        guard !storage.constructionEntered, storage.effectScope == nil else {
            poison(EraseIntentStoreError.invalidAuthority); throw EraseIntentStoreError.invalidAuthority
        }
        storage.constructionEntered = true // permanent BEFORE any delegated proof
        do {
            let count = try operation.requireColdScratchIngressPreconstructorAssociation(
                request: self, ranges: storage.ranges, store: storage.store, scope: scope,
                loan: storage.loan, applicationSupportURL: storage.applicationSupportURL)
            guard count == storage.normalizedApplicationSupportPathUTF8Count else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try requireBound(ranges: storage.ranges, store: storage.store, operation: operation, scope: scope)
            try storage.ranges.requireIngressPrepaidAssociation(request: self)
        } catch { poison(error); throw error }
    }
    func retainEffectScope(_ actual: ColdEraseScratchIngressPolicyEffectScopeV1,
        operation: EraseColdPreparationOperationV1, scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        guard storage.constructionEntered, storage.effectScope == nil else {
            if storage.unexpectedEffectScope == nil { storage.unexpectedEffectScope = actual }
            poison(EraseIntentStoreError.invalidAuthority); throw EraseIntentStoreError.invalidAuthority
        }
        storage.effectScope = actual // actual return BEFORE fallible identity/capacity proof
        do { try requireEffectScope(actual, operation: operation, scope: scope) }
        catch { poison(error); throw error }
    }
    func requireEffectScope(_ actual: ColdEraseScratchIngressPolicyEffectScopeV1,
        operation: EraseColdPreparationOperationV1, scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        do {
            guard storage.constructionEntered, storage.effectScope === actual,
                  storage.operation === operation, storage.scope === scope,
                  storage.failure == nil else { throw EraseIntentStoreError.invalidAuthority }
            try actual.requireReservationAssociation(request: self, ranges: storage.ranges,
                store: storage.store, operation: operation, scope: scope)
            let operands = try actual.requireIngressReservationOperands(request: self,
                ranges: storage.ranges, store: storage.store, operation: operation, scope: scope)
            // Capture actual reached backing BEFORE any profile refusal. The
            // actual Scope/Attempt stay retained on every failure/overflow.
            storage.mainArrayHighWater = max(storage.mainArrayHighWater, operands.arrayBytes)
            if let attempt = operands.attempt {
                storage.attemptHighWater = max(storage.attemptHighWater, attempt.actualBackingBytes)
            }
            try storage.ranges.recordIngressReachedBacking(request: self)
            try requireBound(ranges: storage.ranges, store: storage.store, operation: operation, scope: scope)
            guard actual.operationID == scope.operationID,
                  actual.normalizedApplicationSupportPathUTF8Count == storage.normalizedApplicationSupportPathUTF8Count,
                  actual.node.kind == .stagingDirectory, actual.node.fullFact == currentRootFullFact,
                  actual.node.parentFullFact == currentOperationsFullFact,
                  actual.actualBackingBytes == (try ColdEraseScratchIngressPolicyEffectScopeV1.requiredBackingBytes(
                    normalizedApplicationSupportPathUTF8Count: storage.normalizedApplicationSupportPathUTF8Count)) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try storage.ranges.requireIngressPrepaidAssociation(request: self)
        } catch { poison(error); throw error }
    }
    /// Pure failure cost capture from SAME retained actual Scope/Attempt.
    /// It is callable after poison solely to preserve reached/unknown charge;
    /// it never validates current state, authorizes IO, or clears any owner.
    func recordEffectScopeFailureBacking(_ actual: ColdEraseScratchIngressPolicyEffectScopeV1) {
        guard storage.effectScope === actual else {
            if storage.unexpectedEffectScope == nil { storage.unexpectedEffectScope = actual }
            storage.ranges.recordIngressFailureBacking(request: self, unknown: true)
            return
        }
        do {
            let operands = try actual.requireIngressFailureBackingOperands(request: self,
                ranges: storage.ranges, store: storage.store, operation: storage.operation,
                scope: storage.scope, loan: storage.loan)
            storage.mainArrayHighWater = max(storage.mainArrayHighWater, operands.arrayBytes)
            if let attempt = operands.attempt {
                storage.attemptHighWater = max(storage.attemptHighWater, attempt.actualBackingBytes)
            }
            storage.ranges.recordIngressFailureBacking(request: self,
                unknown: storage.unexpectedEffectScope != nil)
        } catch { storage.ranges.recordIngressFailureBacking(request: self, unknown: true) }
    }
    fileprivate func poison(_ error: Error) {
        if let actual = storage.effectScope { recordEffectScopeFailureBacking(actual) }
        else if storage.unexpectedEffectScope != nil {
            storage.ranges.recordIngressFailureBacking(request: self, unknown: true)
        }
        if storage.failure == nil { storage.failure = error }
        storage.ranges.poison(); storage.operation.poisonColdScratchOwner()
        storage.scope.poisonOnUncertainCleanup()
    }
}

