        var facts: [ColdEraseScratchTaskProgressFactV1]?
        var observation: ColdEraseScratchProgressPayloadCodecV1.Observation?
        var payload: Data?
        var io: IO?
        var receipt: IO.Receipt?
        var parserInput: ColdEraseScratchProgressParserInputV1?
        var parser: ColdEraseScratchProgressParserV1?
        var completion: ColdEraseScratchProgressParserCompletionV1?
        var scratch: UnsafeMutableRawPointer?
        var settledRows: UnsafeMutablePointer<ColdEraseScratchSettledIndexRowV1>?
        var generatedRows: UnsafeMutablePointer<ColdEraseScratchGeneratedIndexRowV1>?
