            ColdEraseControlBinaryV1.multiplying(UInt64(max(c.settledCapacity, 1)),
                UInt64(MemoryLayout<ColdEraseScratchSettledIndexRowV1>.stride)),
            ColdEraseControlBinaryV1.multiplying(UInt64(max(c.generatedCapacity, 1)),
                UInt64(MemoryLayout<ColdEraseScratchGeneratedIndexRowV1>.stride)))
        let path = UInt64(c.originalProgress.original.canonicalURL.path.utf8.count)
