            UInt64(MemoryLayout<Storage>.stride),
            ColdEraseScratchPayloadRangesV1.durableObservationStoredBackingBytes,
            ColdEraseScratchSettledTaskV1.declaredStoredFieldBackingBytes,
            3 * 64, IO.storedAndWindowMinimumBytes,
            ColdEraseScratchProgressParserV1.declaredStoredBackingBytes(),
            ColdEraseRetainedControlFileV1.declaredBackingBytes,
            4 * ColdEraseRetainedControlFileV1.declaredSyscallBackingBytes,
            UInt64(4 * MemoryLayout<RequestOwner.StatEntry.Storage>.stride),
            UInt64(8 * MemoryLayout<stat>.stride),
            UInt64(4 * MemoryLayout<ColdEraseScratchTaskProgressFactV1>.stride),
            UInt64(MemoryLayout<ColdEraseScratchTaskPhysicalPayloadV1>.stride),
            UInt64(MemoryLayout<ColdEraseScratchProgressPayloadCodecV1.Observation>.stride),
            UInt64(MemoryLayout<ColdEraseScratchProgressParserInputV1>.stride),
            UInt64(MemoryLayout<ColdEraseScratchProgressParserCompletionV1>.stride),
            UInt64(4 * MemoryLayout<Data>.stride), UInt64(4 * MemoryLayout<String>.stride),
            UInt64(8 * MemoryLayout<SHA256>.stride), UInt64(8 * MemoryLayout<SHA256.Digest>.stride),
            UInt64(MemoryLayout<ColdEraseScratchSettledTaskV1>.stride),
            UInt64(MemoryLayout<[ColdEraseScratchSettledTaskV1]>.stride),
            UInt64(MemoryLayout<ColdEraseScratchSettledTaskV1?>.stride),
