            let wanted = Int(min(UInt64(65_536), count - consumed))
            storage.chunk = try storage.reader.readExactly(offset: ColdEraseControlBinaryV1.adding(offset, consumed), count: wanted)
            guard let actual = storage.chunk, actual.count == wanted else { throw EraseIntentStoreError.invalidAuthority }
            let selected = Int(consumed)..<(Int(consumed) + wanted)
            switch slot {
            case .request: storage.requestFixed!.replaceSubrange(selected, with: actual)
            case .recipe: storage.recipe!.replaceSubrange(selected, with: actual)
            case .trailer: storage.requestTrailer!.replaceSubrange(selected, with: actual)
            case .observation: storage.observationFrame!.replaceSubrange(selected, with: actual)
