                  actual.device == value.device, actual.inode == value.inode, actual.mode == value.mode,
                  actual.linkCount == value.linkCount, actual.backupExcluded == value.backupExcluded,
                  actual.isDirectory == value.isDirectory, actual.urlProtection == value.urlProtection,
                  actual.fileManagerProtection == value.fileManagerProtection,
