extension ColdEraseScratchPayloadRangesV1 {
    func beginPostNamespaceCurrentControlOwnerV4(owner: ColdEraseSchema2TerminalOwnerV1,
        operation: EraseColdPreparationOperationV1, store: EraseIntentStore,
        request: ColdEraseSchema2NamespaceRemovalRequestV1,
        receipt: ColdEraseSchema2NamespaceRemovalReceiptV1)
        throws -> ColdEraseSchema2PostNamespaceCurrentControlOwnerV4 {
        // Foreign operands cannot enter or poison the incumbent reservation.
        guard self.operation === operation, self.store === store,
              request.storage.ranges === self, request.storage.operation === operation,
              request.storage.owner === owner else { throw EraseIntentStoreError.invalidAuthority }
        try owner.requirePostNamespaceCurrentControlMemoryV4(request: request, receipt: receipt,
            ranges: self, store: store, operation: operation)
        if let actual = postNamespaceCurrentControlsV4.owner {
            guard postNamespaceCurrentControlsV4.issued else { throw EraseIntentStoreError.invalidAuthority }
            try actual.requireMemoryAssociation(main: owner, operation: operation, ranges: self, store: store)
            // Retrieval returns only the SAME retained current owner; no new
            // constructor or Source borrow is entered. The caller must use its
            // fresh withCurrentContinuation before planning the next operation.
            return actual
        }
        do {
            guard state == .postContent, oldScratchAccessFenced,
                  !postNamespaceCurrentControlsV4.entered,
                  !postNamespaceCurrentControlsV4.issued,
                  postNamespaceCurrentControlsV4.charge == 0,
                  postNamespaceCurrentControlsV4.consumerCharge == 0,
                  let current = readerCurrentOwnerV4,
                  current.namespaceRequest === request,
                  current.ranges === self, let transferred = transferredControlOwner,
                  request.storage.controlOwner === transferred,
                  request.storage.currentOwner === current,
                  let context = transferred.storage.context else {
                throw EraseIntentStoreError.invalidAuthority
            }
            postNamespaceCurrentControlsV4.entered = true // before frame/profile/capacity/Source/constructor
            try owner.requirePostNamespaceCurrentControlFrameV4(request: request, receipt: receipt,
                ranges: self, store: store, operation: operation)
            try request.requireCompletedCurrentNamespaceReceipt(receipt, owner: current)
            let namesBytes = try transferred.storage.first.names.reduce(UInt64(0)) {
                try ColdEraseControlBinaryV1.adding($0, UInt64($1.utf8.count))
            }
            let allNamesBytes = try ColdEraseControlBinaryV1.adding(namesBytes,
                UInt64(ColdEraseScratchCapsulePublicationKindV1.continuation.canonicalName.utf8.count),
                UInt64(ColdEraseScratchCapsulePublicationKindV1.progress.canonicalName.utf8.count))
            let bytes = try ColdEraseSchema2PostNamespaceCurrentControlOwnerV4.declaredBackingBytes(
                pathUTF8Count: UInt64(context.eraseURL.path.utf8.count), namesUTF8Count: allNamesBytes)
            postNamespaceCurrentControlsV4.charge = bytes // actual prospective profile BEFORE capacity/constructor
            try requireBackingCapacity(additionalBytes: 0)
            try current.withCompletedNamespaceControlPublicationSource(request: request, receipt: receipt) { source in
                guard source.ranges === self, source.operation === operation,
                      source.request === request, source.receipt === receipt,
                      source.currentOwner === current,
                      postNamespaceCurrentControlsV4.owner == nil else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                let actual = ColdEraseSchema2PostNamespaceCurrentControlOwnerV4(source: source,
                    main: owner, operation: operation)
                postNamespaceCurrentControlsV4.owner = actual // SAME Source/resources before every fallible proof
                try actual.validatePreparedSource()
            }
            guard let actual = postNamespaceCurrentControlsV4.owner else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try actual.withCurrentContinuation(owner: owner, operation: operation, ranges: self, store: store) { _ in }
            postNamespaceCurrentControlsV4.issued = true // only after genuine fresh physical callback/postproof
            return actual // actual current physical/Namespace/target/EX proof returned positively
        } catch {
            postNamespaceCurrentControlsV4.owner?.poison(error)
            owner.poisonOnUncertainEffect(); poison(); throw error
        }
    }
    fileprivate func requirePostNamespaceCurrentControlMemoryV4(
        _ owner: ColdEraseSchema2PostNamespaceCurrentControlOwnerV4) throws {
        guard state == .postContent, oldScratchAccessFenced,
              postNamespaceCurrentControlsV4.entered,
              postNamespaceCurrentControlsV4.owner === owner,
              postNamespaceCurrentControlsV4.charge > 0,
              owner.source.ranges === self, owner.source.operation === operation,
              owner.source.transferredOwner === transferredControlOwner,
              owner.source.currentOwner === readerCurrentOwnerV4,
              owner.source.request.storage.ranges === self,
              owner.source.request.storage.currentOwner === readerCurrentOwnerV4,
              owner.source.transferredOwner.storage.store === store,
              uncertainPolicyDescriptors.isEmpty else { throw EraseIntentStoreError.invalidAuthority }
        // No owner, scanner, current IO or capacity callback here.
    }
    fileprivate func reservePostNamespaceCurrentConsumerBackingV4(
        _ owner: ColdEraseSchema2PostNamespaceCurrentControlOwnerV4,
        additionalBytes: UInt64) throws {
        try requirePostNamespaceCurrentControlMemoryV4(owner)
        guard additionalBytes > 0 else { throw EraseIntentStoreError.invalidAuthority }
        let prospective = try ColdEraseControlBinaryV1.adding(
            postNamespaceCurrentControlsV4.consumerCharge, additionalBytes)
        postNamespaceCurrentControlsV4.consumerCharge = prospective // retained before statfs/frame can fail
        try requireBackingCapacity(additionalBytes: 0)
        try requirePostNamespaceCurrentControlMemoryV4(owner)
        // Retirement/decharge belongs to genuine later Plan/Request backing
        // consumers and the final control close. No early release API exists.
    }
}
