    fileprivate var activeDiagnosticsIOV4: ColdEraseSchema2DiagnosticsJournalIOV4? {
        diagnosticsCurrentV4.activeIO
    }
    fileprivate func requireDiagnosticsAdoptionMemoryV4(
        request: ColdEraseSchema2DiagnosticsRequestV1,
        control: ColdEraseSchema2PostNamespaceCurrentControlOwnerV4) throws {
        try requireImmutableTransferredOriginMemory(ranges: ranges, transferredOwner: transferredOwner)
        guard diagnosticsCurrentV4.adoptionEntered,
              diagnosticsCurrentV4.request === request, diagnosticsCurrentV4.control === control,
              diagnosticsCurrentV4.uncertainControl == nil,
              request.storage.currentControl === control, request.storage.journalOwner === self,
              request.storage.ranges === ranges, request.storage.controlOwner === transferredOwner,
              request.storage.owner === control.source.request.storage.owner,
              request.storage.operation === control.source.operation,
              request.storage.before === control.source.projection,
