    /// Completed cleanup has removed the entire journal root. Observing that
    /// postcondition must not initialize a new journal namespace.
    static func completedCleanupRootIsAbsent(applicationSupportURL: URL) throws -> Bool {
        let root = applicationSupportURL.standardizedFileURL
        guard root.isFileURL else { throw EraseIntentStoreError.invalidAuthority }
        let descriptor = Darwin.open(root.path, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard descriptor >= 0 else { throw EraseIntentStoreError.invalidAuthority }
        defer { _ = Darwin.close(descriptor) }
        let expected = try directoryIdentity(descriptor)

        func verifyRoot() throws {
            let reopened = Darwin.open(root.path, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
            guard reopened >= 0 else { throw EraseIntentStoreError.invalidAuthority }
            defer { _ = Darwin.close(reopened) }
            guard try directoryIdentity(descriptor) == expected,
                  try directoryIdentity(reopened) == expected else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }

        try verifyRoot()
        var info = stat()
        let result = Darwin.fstatat(descriptor, directoryName, &info, AT_SYMLINK_NOFOLLOW)
        let lookupError = errno
        guard result == 0 || lookupError == ENOENT else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try verifyRoot()
        // Every present entry, including an empty directory or dangling link,
        // denies completed-cleanup admission. Never follow, repair or remove it.
        return result != 0
    }

    init(
        applicationSupportURL: URL,
        fileManager: FileManager = .default,
        expectedApplicationSupportIdentity: StoreApplicationSupportIdentity? = nil,
        originalRecoveryCheckedIO: EraseAbortCheckedSnapshotIOV1? = nil,
        originalNoRepairExistingRoot: Bool = false
    ) throws {
        let canonicalIO = OriginalCanonicalCheckedIOV1()
        var canonicalConstructed = false
        defer {
            if !canonicalConstructed {
                do { try canonicalIO.finishOwnedOnce() } catch { canonicalIO.poison() }
                if (try? canonicalIO.requireSettled()) == nil {
                    Self.retainCanonicalIO(canonicalIO)
                }
            }
        }

        try FunctionalRelationshipEraseIntentStorePolicyV1.validate()
        try EvidenceAssuranceEraseIntentStorePolicyV1.validate()
        try InspectionReviewEraseIntentStorePolicyV1.validate()
        try WorkPacketEraseIntentStorePolicyV1.validate()
        try FieldDraftEraseIntentStorePolicyV1.validate()
        try PackageEvolutionEraseIntentStorePolicyV1.validate()
        try ClientCapabilityEraseIntentStorePolicyV1.validate()
        try PrivacyTransformEraseIntentStorePolicyV1.validate()
        try MeasurementIntegrityEraseIntentStorePolicyV1.validate()
        try FieldReferenceEraseIntentStorePolicyV1.validate()
        try AccessibleDocumentEraseIntentStorePolicyV1.validate()
        try SurveyDefinitionEraseIntentStorePolicyV1.validate()
        try ScheduleEraseIntentStorePolicyV1.validate()
        try PlanEraseIntentStorePolicyV1.validate()
        try PlacementPoseEraseIntentStorePolicyV1.validate()
        try SurveySessionEraseIntentEnrollmentV1.validate()
        try C53AssetServiceReliabilityEraseIntentStorePolicyV1.validate()
        let root = applicationSupportURL.standardizedFileURL
        guard root.isFileURL else { throw EraseIntentStoreError.invalidAuthority }
        if expectedApplicationSupportIdentity == nil && originalRecoveryCheckedIO == nil {
            try fileManager.createDirectory(
                at: root,
                withIntermediateDirectories: true
            )
        }
        let appDescriptor = try canonicalIO.openPath(root.path, flags: O_RDONLY | O_DIRECTORY)
        guard appDescriptor >= 0 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let appIdentity = try Self.directoryIdentity(appDescriptor)
        if let expectedApplicationSupportIdentity {
            guard appIdentity.device == expectedApplicationSupportIdentity.device,
                  appIdentity.inode == expectedApplicationSupportIdentity.inode else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }

        var eraseDescriptor: Int32
        do { eraseDescriptor = try canonicalIO.openAt(appDescriptor, name: Self.directoryName, flags: O_RDONLY | O_DIRECTORY) }
        catch EraseIntentStoreError.intentMismatch { eraseDescriptor = -1 }
        if eraseDescriptor < 0,
           !originalNoRepairExistingRoot, originalRecoveryCheckedIO == nil {
            guard Darwin.mkdirat(
                appDescriptor,
                Self.directoryName,
                mode_t(0o700)
            ) == 0 || errno == EEXIST else {
                throw EraseIntentStoreError.invalidAuthority
            }
            eraseDescriptor = try canonicalIO.openAt(appDescriptor, name: Self.directoryName, flags: O_RDONLY | O_DIRECTORY)
        }
        guard eraseDescriptor >= 0 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let eraseIdentity = try Self.directoryIdentity(eraseDescriptor)
        var canonicalPolicyEffectStarted = false
        do {
            if let originalRecoveryCheckedIO {
                // The retained original owner already checked this exact
                // directory policy and full leaf witness under Support EX.
                // A second policy request here would be a pre-effect write.
                guard try Self.directoryIdentity(appDescriptor) == appIdentity,
                      try Self.directoryIdentity(eraseDescriptor) == eraseIdentity else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                _ = try originalRecoveryCheckedIO.names(in: eraseDescriptor)
            } else {
            if originalNoRepairExistingRoot {
                let observed = try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(
                    .stagingDirectory, at: root.appendingPathComponent(Self.directoryName, isDirectory: true),
                    retainUncertainDescriptor: { canonicalIO.retainUncertainDescriptor($0) })
                guard observed.state == .strictComplete,
                      observed.device == UInt64(eraseIdentity.device),
                      observed.inode == UInt64(eraseIdentity.inode),
                      try Self.directoryIdentity(appDescriptor) == appIdentity,
                      try Self.directoryIdentity(eraseDescriptor) == eraseIdentity else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            } else {
                var supportPolicyRoot = stat(), erasePolicyRoot = stat()
                guard Darwin.fstat(appDescriptor, &supportPolicyRoot) == 0,
                      Darwin.fstat(eraseDescriptor, &erasePolicyRoot) == 0 else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                let constructionAuthority: () throws -> Void = {
                    guard try Self.directoryIdentity(appDescriptor) == appIdentity,
                          try Self.directoryIdentity(eraseDescriptor) == eraseIdentity else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    var namedSupport = stat(), named = stat()
                    var heldSupport = stat(), heldErase = stat()
                    guard Darwin.fstat(appDescriptor, &heldSupport) == 0,
                          Darwin.fstat(eraseDescriptor, &heldErase) == 0,
                          heldSupport.st_nlink == supportPolicyRoot.st_nlink,
                          heldErase.st_nlink == erasePolicyRoot.st_nlink,
                          Darwin.lstat(root.path, &namedSupport) == 0,
                          namedSupport.st_mode & S_IFMT == S_IFDIR,
                          namedSupport.st_dev == appIdentity.device,
                          namedSupport.st_ino == appIdentity.inode,
                          namedSupport.st_nlink == supportPolicyRoot.st_nlink,
                          Darwin.fstatat(appDescriptor, Self.directoryName, &named, AT_SYMLINK_NOFOLLOW) == 0,
                          named.st_dev == eraseIdentity.device, named.st_ino == eraseIdentity.inode,
                          named.st_nlink == erasePolicyRoot.st_nlink else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                }
                try ProtectedFilePolicyV1.applyAndVerifyEraseColdPrivateWithCheckedClose(
                    .stagingDirectory, at: root.appendingPathComponent(Self.directoryName, isDirectory: true),
                    retainUncertainDescriptor: { canonicalIO.retainUncertainDescriptor($0) },
                    authorityCheck: constructionAuthority,
                    beforeFirstEffect: {
                        try constructionAuthority()
                        canonicalPolicyEffectStarted = true
                    })
            }
            }
        } catch {
            if canonicalPolicyEffectStarted { canonicalIO.poison() }
            throw EraseIntentStoreError.invalidAuthority
        }

        try canonicalIO.transferParentsToStore([appDescriptor, eraseDescriptor])
        canonicalConstructed = true
        self.applicationSupportURL = root
        self.applicationSupportDescriptor = appDescriptor
        self.applicationSupportIdentity = appIdentity
        self.eraseDescriptor = eraseDescriptor
        self.eraseIdentity = eraseIdentity
        self.borrowsColdObservation = false
        self.originalRecoveryCheckedIO = originalRecoveryCheckedIO
        self.originalCanonicalSourceIO = canonicalIO
        self.coldExpectedIntentBytes = nil
        self.coldExpectedPreparationBytes = nil
        self.coldExpectedIntentFact = nil
        self.coldExpectedPreparationFact = nil
    }

    @MainActor
    init(coldObservation: EraseColdExistingControlObservationV1,
        snapshot: EraseColdExistingControlObservationV1.Snapshot,
        operation: EraseColdPreparationOperationV1) throws {
        let held = try coldObservation.beginSchema2StoreBorrow(snapshot,
            operation: operation)
        self.applicationSupportURL = held.supportURL
        self.applicationSupportDescriptor = held.supportFD
        self.applicationSupportIdentity = Identity(
            device: held.supportDevice, inode: held.supportInode)
        self.eraseDescriptor = held.eraseFD
        self.eraseIdentity = Identity(
            device: held.eraseDevice, inode: held.eraseInode)
        self.borrowsColdObservation = true
        self.originalRecoveryCheckedIO = nil
        self.originalCanonicalSourceIO = OriginalCanonicalCheckedIOV1()
        self.coldExpectedIntentBytes = held.intentBytes
        self.coldExpectedPreparationBytes = held.preparationBytes
        self.coldCapturedOpaqueNextBytes = held.opaqueIntentNextBytes
        self.coldCapturedOpaqueRosterPresent = held.opaqueRosterPresent
        self.coldCapturedOpaqueRosterNextPresent = held.opaqueRosterNextPresent
        self.coldCapturedOpaqueAuxiliaryRosterBytes =
            held.opaqueAuxiliaryRosterBytes
        self.coldCapturedOpaqueAuxiliaryRosterFact =
            held.opaqueAuxiliaryRosterFact
        self.coldCapturedOpaqueAuxiliaryRosterPolicy =
            held.opaqueAuxiliaryRosterPolicy
        self.coldCapturedOpaqueAuxiliaryRosterNextPresent =
            held.opaqueAuxiliaryRosterNextPresent
        self.coldCapturedOpaqueOriginalRetired =
            held.opaqueOriginalRetired
        self.coldExpectedIntentFact = held.intentFact
        self.coldExpectedPreparationFact = held.preparationFact
        self.coldCapturedOpaqueNextFact = held.opaqueIntentNextFact
    }

    @MainActor
    func schema2ColdSupportIdentity(
        operation: EraseColdPreparationOperationV1
    ) throws -> (device: dev_t, inode: ino_t) {
        try operation.requireSchema2ColdIntentStore(self)
        guard borrowsColdObservation else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try verifyAuthority()
        return (applicationSupportIdentity.device,
            applicationSupportIdentity.inode)
    }

    /// Opaque first P controls only. The cold Manifest and Registry must
    /// separately authenticate the recorded Data inode and source lineage
    /// under the same operation's EX/G before any replay effect.
    @MainActor
    func requireSchema2ColdObservedOriginalRetiredControls(
        intent: EraseIntentV1,
        preparation: ErasePreparationV2,
        operation: EraseColdPreparationOperationV1
    ) throws -> (records: [String: EraseColdExistingControlObservationV1
                    .OpaqueOriginalRetiredLeafV1],
                 eraseRoot: EraseColdControlLeafFactV1,
                 names: [String]) {
        try operation.requireSchema2ColdIntentStore(self)
        guard borrowsColdObservation,
              intent.schemaVersion == 2,
              intent.phase == .emptyGenerationPrepared,
              preparation.matches(intent),
              !coldCapturedOpaqueOriginalRetired.isEmpty,
              coldCapturedOpaqueOriginalRetired[
                Self.originalRetiredStageIdentityName] == nil ||
                coldCapturedOpaqueOriginalRetired[
                    Self.originalRetiredCommitmentName] != nil,
              !coldEffectUncertain,
              try load() == intent,
              try loadPreparation() == preparation else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try verifyAuthority()
        let firstRoot = try coldRootFact()
        let names = try coldNamesChecked()
        guard names == schema2ColdRosterNames() else {
            throw EraseIntentStoreError.invalidAuthority
        }
        for name in [Self.originalRetiredCommitmentName,
                     Self.originalRetiredCommitmentNextName,
                     Self.originalRetiredStageIdentityName,
                     Self.originalRetiredStageIdentityNextName] {
            let first = coldCapturedOpaqueOriginalRetired[name]
            guard names.contains(name) == (first != nil) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            guard let first else { continue }
            var before = stat(), after = stat()
            guard Darwin.fstatat(eraseDescriptor, name, &before,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  EraseColdControlLeafFactV1(before) == first.fact,
                  try readColdOpaqueOriginalRetired(name,
                    expected: first),
                  Darwin.fstatat(eraseDescriptor, name, &after,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  EraseColdControlLeafFactV1(after) == first.fact,
                  try observeBorrowedColdPolicy(
                    name.hasSuffix(".next")
                        ? .journalTemporary : .journal,
                    at: applicationSupportURL.appendingPathComponent(
                        policyRelativePath(name))) == first.policy else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        try verifyAuthority()
        guard try coldRootFact() == firstRoot,
              try coldNamesChecked() == names else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return (coldCapturedOpaqueOriginalRetired, firstRoot, names)
    }

    /// Decode only the canonical first-held P records. A pending `.next`
    /// remains an opaque interruption cut; neither its bytes nor a matching
    /// deterministic name can establish the original writer's ownership.
    @MainActor
    func requireSchema2ColdSemanticOriginalRetiredControls(
        intent: EraseIntentV1,
        preparation: ErasePreparationV2,
        operation: EraseColdPreparationOperationV1
    ) throws -> (commitment: OriginalRecoveryRetiredCommitmentRecordV1,
                 stage: OriginalRecoveryRetiredStageIdentityRecordV1?,
                 first: [String: EraseColdExistingControlObservationV1
                    .OpaqueOriginalRetiredLeafV1],
                 root: EraseColdControlLeafFactV1,
                 names: [String]) {
        let cut = try requireSchema2ColdObservedOriginalRetiredControls(
            intent: intent, preparation: preparation,
            operation: operation)
        guard cut.records[Self.originalRetiredCommitmentNextName] == nil,
              cut.records[Self.originalRetiredStageIdentityNextName] == nil,
              let commitmentLeaf = cut.records[
                Self.originalRetiredCommitmentName],
              let firstIntent = coldExpectedIntentBytes,
              let firstPreparation = coldExpectedPreparationBytes,
              let firstIntentFact = coldExpectedIntentFact,
              let firstPreparationFact = coldExpectedPreparationFact,
              let auxiliaryBytes = coldCapturedOpaqueAuxiliaryRosterBytes,
              let auxiliaryFact = coldCapturedOpaqueAuxiliaryRosterFact,
              let auxiliaryPolicy = coldCapturedOpaqueAuxiliaryRosterPolicy,
              auxiliaryPolicy.state == .strictComplete,
              auxiliaryPolicy.backupExcluded == true,
              commitmentLeaf.policy?.state == .strictComplete,
              commitmentLeaf.policy?.backupExcluded == true,
              !coldCapturedOpaqueAuxiliaryRosterNextPresent else {
            throw EraseIntentStoreError.invalidAuthority
        }
        typealias Fact = OriginalRecoveryRetiredCommitmentRecordV1.Fact
        func full(_ value: EraseColdControlLeafFactV1) -> Fact {
            Fact(device: value.device, inode: value.inode,
                mode: value.mode, links: value.links,
                user: value.user, group: value.group,
                size: value.size,
                modifiedSeconds: value.modifiedSeconds,
                modifiedNanoseconds: value.modifiedNanoseconds,
                changedSeconds: value.changedSeconds,
                changedNanoseconds: value.changedNanoseconds)
        }
        let commitment = try OriginalRecoveryRetiredCommitmentRecordV1
            .decodeCanonical(commitmentLeaf.bytes)
        guard commitment.intentBytes == firstIntent,
              commitment.preparationBytes == firstPreparation,
              commitment.intentFact == full(firstIntentFact),
              commitment.preparationFact == full(firstPreparationFact),
              commitment.auxiliaryRosterBytes == auxiliaryBytes,
              commitment.auxiliaryRosterFact == full(auxiliaryFact),
              commitment.eraseID == intent.eraseID.uuidString.lowercased(),
              commitment.sourceGenerationID == intent.oldGenerationID
                .uuidString.lowercased(),
              commitment.targetGenerationID == intent.newGenerationID
                .uuidString.lowercased(),
              commitment.erase.device == Int64(cut.eraseRoot.device),
              commitment.erase.inode == UInt64(cut.eraseRoot.inode),
              commitment.erase.mode == UInt32(cut.eraseRoot.mode),
              commitment.erase.user == UInt32(cut.eraseRoot.user),
              commitment.erase.group == UInt32(cut.eraseRoot.group) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let stage: OriginalRecoveryRetiredStageIdentityRecordV1?
        if let stageLeaf = cut.records[Self.originalRetiredStageIdentityName] {
            guard stageLeaf.policy?.state == .strictComplete,
                  stageLeaf.policy?.backupExcluded == true else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let decoded = try OriginalRecoveryRetiredStageIdentityRecordV1
                .decodeCanonical(stageLeaf.bytes)
            guard decoded.eraseID == commitment.eraseID,
                  decoded.commitmentSHA256 ==
                    StoreMigrationCanonicalJSONV1.sha256(
                        commitmentLeaf.bytes),
                  decoded.commitmentFact == full(commitmentLeaf.fact),
                  decoded.firstDataFact == commitment.namespace.data,
                  decoded.firstDataChildren == [
                    .init(name: "current.json", kind: "regular",
                        fact: commitment.namespace.currentFact),
                    .init(name: "generations", kind: "directory",
                        fact: commitment.namespace.installedParent),
                    .init(name: "retired.json", kind: "regular",
                        fact: commitment.namespace.retiredFact)],
                  decoded.privateStageName == commitment.privateStageName,
                  decoded.canonicalTempName == commitment.canonicalTempName,
                  decoded.replacementSHA256 ==
                    commitment.replacementSHA256 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            stage = decoded
        } else {
            stage = nil
        }
        let after = try requireSchema2ColdObservedOriginalRetiredControls(
            intent: intent, preparation: preparation,
            operation: operation)
        guard after.records == cut.records,
              after.eraseRoot == cut.eraseRoot,
              after.names == cut.names else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return (commitment, stage, cut.records, cut.eraseRoot,
            cut.names)
    }

    /// Classify only the immutable initial capture, never current survivors.
    private func schema2ColdPointerOriginalRecordShape() throws
        -> EraseSchema2ColdPointerOriginalRecordShapeV1 {
        let names = coldCapturedOpaqueOriginalRetired.keys.sorted()
        if names.isEmpty { return .ordinaryNoRecords }
        guard names == [Self.originalRetiredCommitmentName,
            Self.originalRetiredStageIdentityName].sorted() else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return .recoveredCompleteRecords
    }

    /// Completed Original P records have a distinct first cut from E.
    /// Capture it under the same pre-reader owner; no late R baseline exists.
    @MainActor
    func requireSchema2ColdObservedPointerOriginalRetiredControls(
        intent: EraseIntentV1,
        preparation: ErasePreparationV2,
        operation: EraseColdPreparationOperationV1
    ) throws -> (shape: EraseSchema2ColdPointerOriginalRecordShapeV1,
                 records: [String: EraseColdExistingControlObservationV1
                    .OpaqueOriginalRetiredLeafV1],
                 eraseRoot: EraseColdControlLeafFactV1,
                 names: [String]) {
        try operation.requireSchema2ColdPointerOriginalRetiredCaptureOwner(
            intent: intent, preparation: preparation, store: self)
        let recordShape = try schema2ColdPointerOriginalRecordShape()
        guard borrowsColdObservation, !coldEffectUncertain,
              !coldCloseAttempted, !coldClosed,
              intent.phase == .pointerSwitched,
              preparation.matches(intent),
              coldProjectedOriginalRetiredFacts.isEmpty,
              coldVerifiedOriginalRetiredDispositions.isEmpty,
              let intentBytes = coldExpectedIntentBytes,
              let intentFact = coldExpectedIntentFact,
              let preparationBytes = coldExpectedPreparationBytes,
              let preparationFact = coldExpectedPreparationFact else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let controls = try requireSchema2ColdCanonicalControls(
            intent: intent, preparation: preparation,
            operation: operation)
        guard controls.intentBytes == intentBytes,
              controls.preparationBytes == preparationBytes,
              controls.names == schema2ColdRosterNames(),
              !controls.names.contains(Self.nextName),
              !coldCapturedOpaqueAuxiliaryRosterNextPresent,
              coldCapturedOpaqueAuxiliaryRosterBytes != nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        for name in coldCapturedOpaqueOriginalRetired.keys.sorted() {
            guard let first = coldCapturedOpaqueOriginalRetired[name],
                  try readColdOpaqueOriginalRetired(name, expected: first) else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        let after = try requireSchema2ColdCanonicalControls(
            intent: intent, preparation: preparation,
            operation: operation)
        guard after.intentBytes == controls.intentBytes,
              after.preparationBytes == controls.preparationBytes,
              after.eraseRoot == controls.eraseRoot,
              after.names == controls.names else {
            throw EraseIntentStoreError.invalidAuthority
        }
        if let retained = coldPointerOriginalControlCut {
            guard retained.recordShape == recordShape,
                  retained.intent == intent,
                  retained.preparation == preparation,
                  retained.intentBytes == intentBytes,
                  retained.intentFact == intentFact,
                  retained.preparationBytes == preparationBytes,
                  retained.preparationFact == preparationFact,
                  retained.eraseRoot == controls.eraseRoot,
                  retained.names == controls.names else {
                throw EraseIntentStoreError.invalidAuthority
            }
        } else {
            coldPointerOriginalControlCut = .init(recordShape: recordShape,
                intent: intent,
                preparation: preparation, intentBytes: intentBytes,
                intentFact: intentFact, preparationBytes: preparationBytes,
                preparationFact: preparationFact,
                eraseRoot: controls.eraseRoot, names: controls.names)
        }
        return (recordShape, coldCapturedOpaqueOriginalRetired,
            controls.eraseRoot, controls.names)
    }

    @MainActor
    func requireSchema2ColdSemanticPointerOriginalRetiredControls(
        intent: EraseIntentV1,
        preparation: ErasePreparationV2,
        operation: EraseColdPreparationOperationV1
    ) throws -> (commitment: OriginalRecoveryRetiredCommitmentRecordV1,
                 stage: OriginalRecoveryRetiredStageIdentityRecordV1?,
                 first: [String: EraseColdExistingControlObservationV1
                    .OpaqueOriginalRetiredLeafV1],
                 root: EraseColdControlLeafFactV1,
                 names: [String]) {
        let cut = try requireSchema2ColdObservedPointerOriginalRetiredControls(
            intent: intent, preparation: preparation, operation: operation)
        guard cut.shape == .recoveredCompleteRecords else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let semantic = try decodeSchema2ColdPointerOriginalRetiredControls(
            firstIntent: intent, preparation: preparation,
            root: cut.eraseRoot, names: cut.names)
        let after = try requireSchema2ColdObservedPointerOriginalRetiredControls(
            intent: intent, preparation: preparation, operation: operation)
        guard after.shape == cut.shape, after.records == cut.records,
              after.eraseRoot == cut.eraseRoot, after.names == cut.names else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return semantic
    }

    /// Decode the recorded E commitment against the actual retained P.
    /// Its E inode/times are historical DATA, not the replaced P/R leaf.
    private func decodeSchema2ColdPointerOriginalRetiredControls(
        firstIntent: EraseIntentV1, preparation: ErasePreparationV2,
        root: EraseColdControlLeafFactV1, names: [String]
    ) throws -> (commitment: OriginalRecoveryRetiredCommitmentRecordV1,
                 stage: OriginalRecoveryRetiredStageIdentityRecordV1?,
                 first: [String: EraseColdExistingControlObservationV1
                    .OpaqueOriginalRetiredLeafV1],
                 root: EraseColdControlLeafFactV1, names: [String]) {
        guard let retained = coldPointerOriginalControlCut,
              retained.recordShape == .recoveredCompleteRecords,
              retained.intent == firstIntent,
              firstIntent.phase == .pointerSwitched,
              retained.preparation == preparation,
              let commitmentLeaf = coldCapturedOpaqueOriginalRetired[
                Self.originalRetiredCommitmentName],
              let stageLeaf = coldCapturedOpaqueOriginalRetired[
                Self.originalRetiredStageIdentityName],
              coldCapturedOpaqueOriginalRetired.count == 2,
              let auxiliaryBytes = coldCapturedOpaqueAuxiliaryRosterBytes,
              let auxiliaryFact = coldCapturedOpaqueAuxiliaryRosterFact,
              let auxiliaryPolicy = coldCapturedOpaqueAuxiliaryRosterPolicy,
              !coldCapturedOpaqueAuxiliaryRosterNextPresent else {
            throw EraseIntentStoreError.invalidAuthority
        }
        for (bytes, fact, policy) in [
            (commitmentLeaf.bytes, commitmentLeaf.fact, commitmentLeaf.policy),
            (stageLeaf.bytes, stageLeaf.fact, stageLeaf.policy),
            (auxiliaryBytes, auxiliaryFact, Optional(auxiliaryPolicy))] {
            guard fact.mode & S_IFMT == S_IFREG,
                  fact.links == 1, fact.size == off_t(bytes.count),
                  fact.size > 0, fact.size <= off_t(Self.maximumJournalBytes),
                  fact.device == retained.eraseRoot.device,
                  fact.user == retained.eraseRoot.user,
                  fact.group == retained.eraseRoot.group,
                  policy?.device == UInt64(fact.device),
                  policy?.inode == UInt64(fact.inode),
                  policy?.linkCount == 1,
                  policy?.backupExcluded == true,
                  policy?.state == .strictComplete ||
                    policy?.state == .pendingSimulatorRequest else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        typealias Fact = OriginalRecoveryRetiredCommitmentRecordV1.Fact
        func full(_ value: EraseColdControlLeafFactV1) -> Fact {
            Fact(device: value.device, inode: value.inode,
                mode: value.mode, links: value.links,
                user: value.user, group: value.group, size: value.size,
                modifiedSeconds: value.modifiedSeconds,
                modifiedNanoseconds: value.modifiedNanoseconds,
                changedSeconds: value.changedSeconds,
                changedNanoseconds: value.changedNanoseconds)
        }
        let commitment = try OriginalRecoveryRetiredCommitmentRecordV1
            .decodeCanonical(commitmentLeaf.bytes)
        let recorded = try EraseIntentCodecV1.decode(commitment.intentBytes)
        guard try EraseIntentCodecV1.encode(recorded) == commitment.intentBytes,
              recorded.phase == .emptyGenerationPrepared,
              firstIntent == recorded.advancing(to: .pointerSwitched),
              retained.intentBytes == (try EraseIntentCodecV1.encode(firstIntent)),
              commitment.preparationBytes == retained.preparationBytes,
              commitment.preparationFact == full(retained.preparationFact),
              commitment.auxiliaryRosterBytes == auxiliaryBytes,
              commitment.auxiliaryRosterFact == full(auxiliaryFact),
              commitment.intentFact.mode & UInt32(S_IFMT) == UInt32(S_IFREG),
              commitment.intentFact.links == 1,
              commitment.intentFact.size == Int64(commitment.intentBytes.count),
              commitment.intentFact.device == Int64(retained.eraseRoot.device),
              commitment.intentFact.user == UInt32(retained.eraseRoot.user),
              commitment.intentFact.group == UInt32(retained.eraseRoot.group),
              commitment.eraseID == firstIntent.eraseID.uuidString.lowercased(),
              commitment.sourceGenerationID == firstIntent.oldGenerationID
                .uuidString.lowercased(),
              commitment.targetGenerationID == firstIntent.newGenerationID
                .uuidString.lowercased(),
              commitment.erase.device == Int64(retained.eraseRoot.device),
              commitment.erase.inode == UInt64(retained.eraseRoot.inode),
              commitment.erase.mode == UInt32(retained.eraseRoot.mode),
              commitment.erase.user == UInt32(retained.eraseRoot.user),
              commitment.erase.group == UInt32(retained.eraseRoot.group) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let stage = try OriginalRecoveryRetiredStageIdentityRecordV1
            .decodeCanonical(stageLeaf.bytes)
        guard stage.eraseID == commitment.eraseID,
              stage.commitmentSHA256 == StoreMigrationCanonicalJSONV1
                .sha256(commitmentLeaf.bytes),
              stage.commitmentFact == full(commitmentLeaf.fact),
              stage.firstDataFact == commitment.namespace.data,
              stage.firstDataChildren == [
                .init(name: "current.json", kind: "regular",
                    fact: commitment.namespace.currentFact),
                .init(name: "generations", kind: "directory",
                    fact: commitment.namespace.installedParent),
                .init(name: "retired.json", kind: "regular",
                    fact: commitment.namespace.retiredFact)],
              stage.privateStageName == commitment.privateStageName,
              stage.canonicalTempName == commitment.canonicalTempName,
              stage.replacementSHA256 == commitment.replacementSHA256 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return (commitment, stage, coldCapturedOpaqueOriginalRetired, root, names)
    }

    /// R can consume only its actual retained first P and checked own CAS.
    /// A separately born R or equal survivor namespace cannot enter here.
    @MainActor
    func requireSchema2ColdActivatedOriginalRetiredControls(
        intent: EraseIntentV1,
        preparation: ErasePreparationV2,
        operation: EraseColdPreparationOperationV1
    ) throws -> (commitment: OriginalRecoveryRetiredCommitmentRecordV1,
                 stage: OriginalRecoveryRetiredStageIdentityRecordV1?,
                 first: [String: EraseColdExistingControlObservationV1
                    .OpaqueOriginalRetiredLeafV1],
                 root: EraseColdControlLeafFactV1, names: [String]) {
        let cut = try requireSchema2ColdActivatedPointerOriginalControlCut(
            intent: intent, preparation: preparation, operation: operation)
        guard cut.shape == .recoveredCompleteRecords,
              let retained = coldPointerOriginalControlCut,
              retained.recordShape == cut.shape else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return try decodeSchema2ColdPointerOriginalRetiredControls(
            firstIntent: retained.intent, preparation: preparation,
            root: cut.eraseRoot, names: cut.names)
    }

    @MainActor
    func requireSchema2ColdActivatedPointerOriginalControlCut(
        intent: EraseIntentV1,
        preparation: ErasePreparationV2,
        operation: EraseColdPreparationOperationV1
    ) throws -> (shape: EraseSchema2ColdPointerOriginalRecordShapeV1,
                 records: [String: EraseColdExistingControlObservationV1
                    .OpaqueOriginalRetiredLeafV1],
                 eraseRoot: EraseColdControlLeafFactV1, names: [String]) {
        let firstIntent = try operation
            .requireSchema2ColdActivatedOriginalRetiredControlsOwner(
                intent: intent, preparation: preparation, store: self)
        guard borrowsColdObservation, !coldEffectUncertain,
              !coldCloseAttempted, !coldClosed,
              let retained = coldPointerOriginalControlCut,
              retained.recordShape == (try schema2ColdPointerOriginalRecordShape()),
              retained.intent == firstIntent,
              retained.preparation == preparation,
              intent == firstIntent.advancing(to: .sessionActivated),
              let phaseRoot = coldPointerPhasePublishedControlRoot else {
            throw EraseIntentStoreError.invalidAuthority
        }
        if retained.recordShape == .ordinaryNoRecords {
            guard coldCapturedOpaqueOriginalRetired.isEmpty,
                  coldProjectedOriginalRetiredFacts.isEmpty,
                  coldVerifiedOriginalRetiredDispositions.isEmpty else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        var expectedRoot = phaseRoot
        var expectedNames = retained.names
        if let receipt = coldRosterPublication {
            guard receipt.store === self, receipt.operation === operation,
                  !coldRosterInFlight,
                  receipt.intentBytes == coldExpectedIntentBytes,
                  receipt.preparationBytes == retained.preparationBytes,
                  let projected = receipt.postPublishedRoot,
                  let bytes = coldOwnRosterBytes,
                  let fact = coldOwnRosterFact,
                  receipt.publishedFact == fact,
                  let leaf = try readColdLeafIfPresent(Self.rosterName,
                    maximumBytes: bytes.count), leaf.data == bytes else {
                throw EraseIntentStoreError.invalidAuthority
            }
            var named = stat()
            guard Darwin.fstatat(eraseDescriptor, Self.rosterName,
                    &named, AT_SYMLINK_NOFOLLOW) == 0,
                  EraseColdControlLeafFactV1(named) == fact else {
                throw EraseIntentStoreError.invalidAuthority
            }
            expectedRoot = projected
            expectedNames = (retained.names + [Self.rosterName]).sorted()
        }
        let before = try requireSchema2ColdCanonicalControls(
            intent: intent, preparation: preparation, operation: operation)
        guard before.eraseRoot == expectedRoot,
              before.names == expectedNames,
              before.intentBytes == coldExpectedIntentBytes,
              before.preparationBytes == retained.preparationBytes else {
            throw EraseIntentStoreError.invalidAuthority
        }
        for name in coldCapturedOpaqueOriginalRetired.keys.sorted() {
            guard let first = coldCapturedOpaqueOriginalRetired[name] else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let fact = coldProjectedOriginalRetiredFacts[name] ?? first.fact
            let policy = try observeBorrowedColdPolicy(.journal,
                at: applicationSupportURL.appendingPathComponent(
                    policyRelativePath(name)))
            if let disposition = coldVerifiedOriginalRetiredDispositions[name] {
                guard coldProjectedOriginalRetiredFacts[name] != nil,
                      policy.device == UInt64(first.fact.device),
                      policy.inode == UInt64(first.fact.inode),
                      policy.linkCount == 1, policy.backupExcluded == true,
                      (disposition == .verifiedComplete
                        ? policy.state == .strictComplete
                        : (policy.state == .pendingSimulatorRequest ||
                            policy.state == .strictComplete)) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            } else {
                guard coldProjectedOriginalRetiredFacts[name] == nil,
                      policy == first.policy else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            let projected = EraseColdExistingControlObservationV1
                .OpaqueOriginalRetiredLeafV1(bytes: first.bytes,
                    fact: fact, policy: policy)
            guard try readColdOpaqueOriginalRetired(name, expected: projected) else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        let after = try requireSchema2ColdCanonicalControls(
            intent: intent, preparation: preparation, operation: operation)
        guard after.eraseRoot == before.eraseRoot,
              after.names == before.names,
              after.intentBytes == before.intentBytes,
              after.preparationBytes == before.preparationBytes else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return (retained.recordShape, coldCapturedOpaqueOriginalRetired,
            after.eraseRoot, after.names)
    }

    /// A real checked request, once per exact canonical record, is needed
    /// before replay. No-request and cached paths retain the exact full fact;
    /// only the helper's actual pending-request boundary permits own ctime.
    @MainActor
    func requireSchema2ColdVerifiedActivatedOriginalRetiredPolicies(
        intent: EraseIntentV1, preparation: ErasePreparationV2,
        operation: EraseColdPreparationOperationV1
    ) throws {
        guard !coldOriginalRetiredPolicyInFlight, !coldEffectUncertain else {
            throw EraseIntentStoreError.invalidAuthority
        }
        _ = try requireSchema2ColdActivatedOriginalRetiredControls(
            intent: intent, preparation: preparation, operation: operation)
        coldOriginalRetiredPolicyInFlight = true
        do {
            for name in [Self.originalRetiredCommitmentName,
                         Self.originalRetiredStageIdentityName] {
                guard let first = coldCapturedOpaqueOriginalRetired[name] else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                var expectedFact = coldProjectedOriginalRetiredFacts[name] ?? first.fact
                var requestCtimeTransitionEntered = false
                func witness() throws
                    -> (value: Schema2ColdOriginalAuxiliaryPolicyWitnessV1,
                        fact: EraseColdControlLeafFactV1) {
                    try operation.requireSchema2ColdRosterObservationOwner(store: self)
                    let controls = try self.requireSchema2ColdCanonicalControls(
                        intent: intent, preparation: preparation, operation: operation)
                    var named = stat()
                    guard controls.names.contains(name),
                          Darwin.fstatat(self.eraseDescriptor, name, &named,
                            AT_SYMLINK_NOFOLLOW) == 0,
                          named.st_dev == first.fact.device,
                          named.st_ino == first.fact.inode,
                          named.st_mode == first.fact.mode,
                          named.st_nlink == first.fact.links,
                          named.st_uid == first.fact.user,
                          named.st_gid == first.fact.group,
                          named.st_uid == Darwin.getuid(),
                          named.st_gid == Darwin.getgid(),
                          named.st_size == first.fact.size,
                          Int64(named.st_mtimespec.tv_sec) == first.fact.modifiedSeconds,
                          Int64(named.st_mtimespec.tv_nsec) == first.fact.modifiedNanoseconds else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    let fact = EraseColdControlLeafFactV1(named)
                    guard requestCtimeTransitionEntered || fact == expectedFact else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    let policy = try self.observeBorrowedColdPolicy(.journal,
                        at: self.applicationSupportURL.appendingPathComponent(
                            self.policyRelativePath(name)))
                    let read = EraseColdExistingControlObservationV1
                        .OpaqueOriginalRetiredLeafV1(bytes: first.bytes,
                            fact: fact, policy: policy)
                    var after = stat()
                    guard try self.readColdOpaqueOriginalRetired(name, expected: read),
                          Darwin.fstatat(self.eraseDescriptor, name, &after,
                            AT_SYMLINK_NOFOLLOW) == 0,
                          EraseColdControlLeafFactV1(after) == fact,
                          try self.coldRootFact() == controls.eraseRoot,
                          try self.coldNamesChecked() == controls.names else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    return (.init(intentBytes: controls.intentBytes,
                        preparationBytes: controls.preparationBytes,
                        recordBytes: first.bytes, device: named.st_dev,
                        inode: named.st_ino, mode: named.st_mode,
                        user: named.st_uid, group: named.st_gid,
                        links: named.st_nlink, size: named.st_size,
                        modifiedSeconds: Int64(named.st_mtimespec.tv_sec),
                        modifiedNanoseconds: Int64(named.st_mtimespec.tv_nsec),
                        eraseRoot: controls.eraseRoot, names: controls.names), fact)
                }
                let before = try witness()
                if coldVerifiedOriginalRetiredDispositions[name] == nil {
                    _ = try requireSchema2ColdActivatedOriginalRetiredControls(
                        intent: intent, preparation: preparation, operation: operation)
                    let disposition = try ProtectedFilePolicyV1
                        .verifyEraseColdTemporalPolicyWithCheckedRequest(.journal,
                            at: applicationSupportURL.appendingPathComponent(
                                policyRelativePath(name)),
                            retainUncertainDescriptor: { value in
                                self.coldUncertainFDs.append(value)
                            }, willRequestCompleteProtection: {
                                let actual = try witness()
                                guard !requestCtimeTransitionEntered,
                                      actual.value == before.value,
                                      actual.fact == expectedFact else {
                                    throw EraseIntentStoreError.invalidAuthority
                                }
                                requestCtimeTransitionEntered = true
                            }, unchangedWitness: { try witness().value })
                    let after = try witness()
                    guard coldUncertainFDs.isEmpty,
                          after.value == before.value,
                          requestCtimeTransitionEntered || after.fact == expectedFact else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    // Freeze the exact actual returned endpoint immediately;
                    // later witness calls cannot project a second transition.
                    expectedFact = after.fact
                    requestCtimeTransitionEntered = false
                    let settled = try witness()
                    guard settled.value == before.value,
                          settled.fact == expectedFact else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    coldProjectedOriginalRetiredFacts[name] = expectedFact
                    coldVerifiedOriginalRetiredDispositions[name] = disposition
                }
                _ = try requireSchema2ColdActivatedOriginalRetiredControls(
                    intent: intent, preparation: preparation, operation: operation)
                let settled = try witness()
                guard settled.value == before.value,
                      settled.fact == expectedFact else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            coldOriginalRetiredPolicyInFlight = false
        } catch {
            coldEffectUncertain = true
            throw error
        }
    }
    /// Re-read the first opaque record or zero/prefix temporary without a
    /// policy setter. Failed or ambiguous close leaves this Store terminal.
    private func readColdOpaqueOriginalRetired(_ name: String,
        expected: EraseColdExistingControlObservationV1
            .OpaqueOriginalRetiredLeafV1) throws -> Bool {
        guard coldActiveFD == nil, coldUncertainFDs.isEmpty,
              !coldEffectUncertain else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let descriptor = Darwin.openat(eraseDescriptor, name,
            O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
        guard descriptor >= 0 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        coldActiveFD = descriptor
        do {
            var before = stat(), after = stat(), named = stat()
            guard Darwin.fstat(descriptor, &before) == 0,
                  EraseColdControlLeafFactV1(before) == expected.fact,
                  before.st_mode & S_IFMT == S_IFREG,
                  before.st_nlink == 1,
                  before.st_size >= 0,
                  before.st_size <= off_t(Self.maximumJournalBytes),
                  Darwin.lseek(descriptor, 0, SEEK_SET) == 0 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            var bytes = Data(count: Int(before.st_size))
            try bytes.withUnsafeMutableBytes { raw in
                var offset = 0
                while offset < raw.count {
                    let count = Darwin.read(descriptor,
                        raw.baseAddress!.advanced(by: offset),
                        raw.count - offset)
                    if count < 0 && errno == EINTR { continue }
                    guard count > 0 else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    offset += count
                }
            }
            let kind: OwnedFileKindV1 = name.hasSuffix(".next")
                ? .journalTemporary : .journal
            let policy = try observeBorrowedColdPolicy(kind,
                at: applicationSupportURL.appendingPathComponent(
                    policyRelativePath(name)))
            guard bytes == expected.bytes,
                  policy == expected.policy,
                  Darwin.fstat(descriptor, &after) == 0,
                  Darwin.fstatat(eraseDescriptor, name, &named,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  EraseColdControlLeafFactV1(after) == expected.fact,
                  EraseColdControlLeafFactV1(named) == expected.fact,
                  Darwin.close(descriptor) == 0 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            coldActiveFD = nil
            return true
        } catch {
            coldEffectUncertain = true
            throw error
        }
    }

    /// Publish a missing first-P auxiliary record under the genuine retained
    /// cold operation. It returns a cold receipt, never an Original receipt.
    @MainActor
    func publishSchema2ColdPreparedAuxiliaryRoster(
        seal: EraseSchema2ColdAuxiliaryRosterPublicationSealV1,
        operation: EraseColdPreparationOperationV1
    ) throws -> Schema2ColdPreparedAuxiliaryPublicationV1 {
        guard borrowsColdObservation, !coldEffectUncertain,
              !coldPreparedAuxiliaryPublicationStarted,
              coldPreparedAuxiliaryPublication == nil,
              coldCapturedOpaqueAuxiliaryRosterBytes == nil,
              coldCapturedOpaqueAuxiliaryRosterFact == nil,
              coldCapturedOpaqueAuxiliaryRosterPolicy == nil,
              !coldCapturedOpaqueAuxiliaryRosterNextPresent,
              seal.firstIntentForComparison.phase == .emptyGenerationPrepared,
              !seal.canonicalBytes.isEmpty,
              seal.canonicalBytes.count <= Self.maximumJournalBytes,
              seal.canonicalSHA256 == StoreMigrationCanonicalJSONV1.sha256(seal.canonicalBytes) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try operation.requireSchema2ColdPreparedAuxiliaryPublicationSeal(seal, store: self)
        let before = try requireSchema2ColdCanonicalControls(intent: seal.firstIntentForComparison,
            preparation: seal.preparationForComparison, operation: operation)
        guard before.names == [Self.intentName, Self.preparationName].sorted(),
              try readColdLeafIfPresent(Self.auxiliaryRosterName) == nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        coldPreparedAuxiliaryPublicationStarted = true
        coldOwnPreparedAuxiliaryBytes = seal.canonicalBytes
        do {
            try operation.withSchema2ColdPreparedAuxiliaryMutation(seal: seal, store: self) {
                let unchanged = try self.requireSchema2ColdCanonicalControls(intent: seal.firstIntentForComparison,
                    preparation: seal.preparationForComparison, operation: operation)
                guard unchanged.eraseRoot == before.eraseRoot,
                      unchanged.names == before.names,
                      unchanged.intentBytes == before.intentBytes,
                      unchanged.preparationBytes == before.preparationBytes else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                let temporary = try self.createColdLeaf(Self.auxiliaryRosterNextName,
                    data: seal.canonicalBytes)
                guard let next = try self.readColdLeafIfPresent(Self.auxiliaryRosterNextName),
                      next.identity == temporary, next.data == seal.canonicalBytes,
                      try self.readColdLeafIfPresent(Self.auxiliaryRosterName) == nil,
                      try self.coldNamesChecked() ==
                        (before.names + [Self.auxiliaryRosterNextName]).sorted() else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                guard Darwin.renameatx_np(self.eraseDescriptor, Self.auxiliaryRosterNextName,
                    self.eraseDescriptor, Self.auxiliaryRosterName, UInt32(RENAME_EXCL)) == 0,
                      Darwin.fsync(self.eraseDescriptor) == 0 else {
                    throw EraseIntentStoreError.writeFailed
                }
                self.coldOwnPublishingName = Self.auxiliaryRosterName
                self.coldOwnPublishedIdentity = temporary
                self.coldPublishedVerified = false
                try self.verifyPublishedPolicy(.journal, name: Self.auxiliaryRosterName,
                    failure: .writeFailed, expectedIdentity: temporary)
                guard let published = try self.readColdLeafIfPresent(Self.auxiliaryRosterName),
                      published.identity == temporary, published.data == seal.canonicalBytes,
                      try self.readColdLeafIfPresent(Self.auxiliaryRosterNextName) == nil else {
                    throw EraseIntentStoreError.writeFailed
                }
                var named = stat()
                guard Darwin.fstatat(self.eraseDescriptor, Self.auxiliaryRosterName,
                    &named, AT_SYMLINK_NOFOLLOW) == 0,
                      named.st_dev == temporary.device, named.st_ino == temporary.inode,
                      named.st_mode & S_IFMT == S_IFREG, named.st_nlink == 1 else {
                    throw EraseIntentStoreError.writeFailed
                }
                let fact = EraseColdControlLeafFactV1(named)
                let policy = try self.observeBorrowedColdPolicy(.journal,
                    at: self.applicationSupportURL.appendingPathComponent(
                        self.policyRelativePath(Self.auxiliaryRosterName)))
                guard policy.device == UInt64(fact.device), policy.inode == UInt64(fact.inode),
                      policy.backupExcluded == true,
                      try self.coldNamesChecked() ==
                        (before.names + [Self.auxiliaryRosterName]).sorted() else {
                    throw EraseIntentStoreError.writeFailed
                }
                self.coldPreparedAuxiliaryPublication = Schema2ColdPreparedAuxiliaryPublicationV1(
                    store: self, operation: operation, seal: seal,
                    bytes: seal.canonicalBytes, fact: fact, policy: policy)
                self.coldOwnTemporaryName = nil
                self.coldOwnTemporaryIdentity = nil
                self.coldOwnTemporaryBytes = nil
                self.coldOwnPublishingName = nil
                self.coldOwnPublishedIdentity = nil
                self.coldPublishedVerified = false
                let after = try self.requireSchema2ColdCanonicalControls(intent: seal.firstIntentForComparison,
                    preparation: seal.preparationForComparison, operation: operation)
                guard after.intentBytes == before.intentBytes,
                      after.preparationBytes == before.preparationBytes,
                      after.names == (before.names + [Self.auxiliaryRosterName]).sorted(),
                      after.eraseRoot.device == before.eraseRoot.device,
                      after.eraseRoot.inode == before.eraseRoot.inode,
                      after.eraseRoot.mode == before.eraseRoot.mode,
                      after.eraseRoot.user == before.eraseRoot.user,
                      after.eraseRoot.group == before.eraseRoot.group,
                      after.eraseRoot.links == before.eraseRoot.links else {
                    throw EraseIntentStoreError.writeFailed
                }
            }
            guard let receipt = coldPreparedAuxiliaryPublication else {
                throw EraseIntentStoreError.writeFailed
            }
            try requireSchema2ColdPreparedAuxiliaryPublication(receipt,
                seal: seal, operation: operation)
            return receipt
        } catch {
            coldEffectUncertain = true
            throw error
        }
    }

    @MainActor
    func requireSchema2ColdPreparedAuxiliaryPublication(
        _ receipt: Schema2ColdPreparedAuxiliaryPublicationV1,
        seal: EraseSchema2ColdAuxiliaryRosterPublicationSealV1,
        operation: EraseColdPreparationOperationV1
    ) throws {
        try operation.requireSchema2ColdIntentStore(self)
        guard coldPreparedAuxiliaryPublication === receipt,
              receipt.store === self, receipt.operation === operation,
              receipt.seal === seal, receipt.bytes == seal.canonicalBytes,
              coldCapturedOpaqueAuxiliaryRosterBytes == nil,
              !coldEffectUncertain,
              let leaf = try readColdLeafIfPresent(Self.auxiliaryRosterName),
              leaf.data == receipt.bytes, leaf.identity.device == receipt.fact.device,
              leaf.identity.inode == receipt.fact.inode else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var named = stat(), missing = stat()
        guard Darwin.fstatat(eraseDescriptor, Self.auxiliaryRosterName,
                &named, AT_SYMLINK_NOFOLLOW) == 0,
              EraseColdControlLeafFactV1(named) == (coldProjectedAuxiliaryRosterFact ?? receipt.fact),
              Darwin.fstatat(eraseDescriptor, Self.auxiliaryRosterNextName,
                &missing, AT_SYMLINK_NOFOLLOW) != 0, errno == ENOENT else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try verifyAuthority()
    }

    @MainActor
    func requireSchema2ColdPreparedDurableAuxiliary(intent: EraseIntentV1,
        preparation: ErasePreparationV2,
        operation: EraseColdPreparationOperationV1) throws {
        try operation.requireSchema2ColdPreparedControls(intent: intent,
            preparation: preparation)
        guard !coldEffectUncertain, !coldCapturedOpaqueAuxiliaryRosterNextPresent,
              let bytes = coldAuxiliaryOriginBytes,
              let fact = coldAuxiliaryOriginFact,
              let policy = coldAuxiliaryOriginPolicy,
              let leaf = try readColdLeafIfPresent(Self.auxiliaryRosterName),
              leaf.data == bytes, leaf.identity.device == fact.device,
              leaf.identity.inode == fact.inode else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var named = stat(), absent = stat()
        guard Darwin.fstatat(eraseDescriptor, Self.auxiliaryRosterName,
                &named, AT_SYMLINK_NOFOLLOW) == 0,
              EraseColdControlLeafFactV1(named) == fact,
              try observeBorrowedColdPolicy(.journal,
                at: applicationSupportURL.appendingPathComponent(
                    policyRelativePath(Self.auxiliaryRosterName))) == policy,
              Darwin.fstatat(eraseDescriptor, Self.auxiliaryRosterNextName,
                &absent, AT_SYMLINK_NOFOLLOW) != 0, errno == ENOENT else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try verifyAuthority()
    }

    /// Read only the first-held original P record under the already retained
    /// cold EX/G. This never requests or promotes its observed policy; even a
    /// pending Simulator disposition remains opaque data for a later typed
    /// same-inode effect owner. No present survivor becomes a new baseline.
    @MainActor
    func requireSchema2ColdObservedPreparedAuxiliaryRosterCut(
        intent: EraseIntentV1,
        preparation: ErasePreparationV2,
        manifest: EraseSchema2ColdManifestOwnerV1,
        operation: EraseColdPreparationOperationV1
    ) throws -> (bytes: Data, fact: EraseColdControlLeafFactV1,
                 eraseRoot: EraseColdControlLeafFactV1,
                 names: [String]) {
        try operation.requireSchema2ColdPreparedAuxiliaryObservationOwner(
            store: self, manifest: manifest)
        guard borrowsColdObservation,
              intent.schemaVersion == 2,
              intent.phase == .emptyGenerationPrepared,
              preparation.matches(intent),
              !coldCapturedOpaqueAuxiliaryRosterNextPresent,
              let firstBytes = coldCapturedOpaqueAuxiliaryRosterBytes,
              let firstFact = coldCapturedOpaqueAuxiliaryRosterFact,
              let firstPolicy = coldCapturedOpaqueAuxiliaryRosterPolicy else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let controls = try requireSchema2ColdCanonicalControls(
            intent: intent, preparation: preparation,
            operation: operation)
        guard controls.names == schema2ColdRosterNames(),
              controls.names.contains(Self.auxiliaryRosterName),
              !controls.names.contains(Self.auxiliaryRosterNextName),
              let read = try readColdLeafIfPresent(
                Self.auxiliaryRosterName,
                maximumBytes: Self.maximumJournalBytes),
              read.data == firstBytes else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var named = stat()
        guard Darwin.fstatat(eraseDescriptor,
                  Self.auxiliaryRosterName, &named,
                  AT_SYMLINK_NOFOLLOW) == 0,
              EraseColdControlLeafFactV1(named) == firstFact,
              named.st_mode & S_IFMT == S_IFREG,
              named.st_nlink == 1,
              named.st_size == off_t(firstBytes.count),
              try observeBorrowedColdPolicy(.journal,
                at: applicationSupportURL.appendingPathComponent(
                    policyRelativePath(Self.auxiliaryRosterName)))
                == firstPolicy,
              try coldRootFact() == controls.eraseRoot,
              try coldNamesChecked() == controls.names else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return (firstBytes, firstFact, controls.eraseRoot,
            controls.names)
    }

    /// First-held original auxiliary record, still data only. Its P lineage
    /// is decoded against authentic R controls by the Manifest owner; this
    /// method never derives an inventory from current survivors.
    @MainActor
    func requireSchema2ColdObservedOriginalAuxiliaryRosterCut(
        intent: EraseIntentV1,
        preparation: ErasePreparationV2,
        operation: EraseColdPreparationOperationV1
    ) throws -> (bytes: Data, fact: EraseColdControlLeafFactV1,
                 eraseRoot: EraseColdControlLeafFactV1,
                 names: [String]) {
        try operation.requireSchema2ColdRosterObservationOwner(
            store: self)
        guard borrowsColdObservation,
              intent.schemaVersion == 2,
              intent.phase == .sessionActivated,
              preparation.matches(intent),
              !coldCapturedOpaqueAuxiliaryRosterNextPresent,
              let firstBytes = coldAuxiliaryOriginBytes,
              let firstFact = coldAuxiliaryOriginFact,
              let firstPolicy = coldAuxiliaryOriginPolicy else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let controls = try requireSchema2ColdCanonicalControls(
            intent: intent, preparation: preparation,
            operation: operation)
        guard controls.names.contains(Self.auxiliaryRosterName),
              !controls.names.contains(Self.auxiliaryRosterNextName),
              let read = try readColdLeafIfPresent(
                Self.auxiliaryRosterName,
                maximumBytes: Self.maximumJournalBytes),
              read.data == firstBytes else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var named = stat()
        guard Darwin.fstatat(eraseDescriptor,
                  Self.auxiliaryRosterName, &named,
                  AT_SYMLINK_NOFOLLOW) == 0,
              EraseColdControlLeafFactV1(named)
                == (coldProjectedAuxiliaryRosterFact ?? firstFact),
              named.st_mode & S_IFMT == S_IFREG,
              named.st_nlink == 1 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let policy = try observeBorrowedColdPolicy(.journal,
            at: applicationSupportURL.appendingPathComponent(
                policyRelativePath(Self.auxiliaryRosterName)))
        guard (coldVerifiedAuxiliaryDisposition == nil
                ? policy == firstPolicy
                : policy.device == UInt64(firstFact.device) &&
                    policy.inode == UInt64(firstFact.inode) &&
                    policy.linkCount == 1 &&
                    policy.backupExcluded == true &&
                    (coldVerifiedAuxiliaryDisposition
                        == .verifiedComplete
                        ? policy.state == .strictComplete
                        : (policy.state == .pendingSimulatorRequest ||
                            policy.state == .strictComplete))),
              try coldRootFact() == controls.eraseRoot,
              try coldNamesChecked() == controls.names else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return (firstBytes, firstFact, controls.eraseRoot,
            controls.names)
    }

    /// A decoded original-P roster may request complete protection once on
    /// the exact first canonical inode. The witness excludes only ctime,
    /// which the checked request itself can change. It never accepts raw
    /// pending Simulator policy as replay authority.
    @MainActor
    func requireSchema2ColdVerifiedObservedOriginalAuxiliaryRosterPolicy(
        roster: EraseSchema2ColdAuxiliaryPhysicalRosterV1,
        intent: EraseIntentV1,
        preparation: ErasePreparationV2,
        operation: EraseColdPreparationOperationV1
    ) throws -> EraseColdControlLeafFactV1 {
        guard !coldObservedAuxiliaryPolicyInFlight,
              !coldEffectUncertain,
              let firstBytes = coldAuxiliaryOriginBytes,
              let firstFact = coldAuxiliaryOriginFact,
              roster.canonicalBytes == firstBytes,
              roster.canonicalSHA256 ==
                StoreMigrationCanonicalJSONV1.sha256(firstBytes) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var expectedFullFact = coldProjectedAuxiliaryRosterFact ?? firstFact
        var requestCtimeTransitionEntered = false
        func witness() throws
            -> Schema2ColdOriginalAuxiliaryPolicyWitnessV1 {
            try operation.requireSchema2ColdRosterObservationOwner(
                store: self)
            let controls = try requireSchema2ColdCanonicalControls(
                intent: intent, preparation: preparation,
                operation: operation)
            guard controls.names.contains(Self.auxiliaryRosterName),
                  !controls.names.contains(Self.auxiliaryRosterNextName),
                  let leaf = try readColdLeafIfPresent(
                    Self.auxiliaryRosterName,
                    maximumBytes: Self.maximumJournalBytes),
                  leaf.data == firstBytes else {
                throw EraseIntentStoreError.invalidAuthority
            }
            var named = stat()
            guard Darwin.fstatat(eraseDescriptor,
                    Self.auxiliaryRosterName, &named,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  named.st_mode & S_IFMT == S_IFREG,
                  named.st_nlink == 1,
                  named.st_dev == firstFact.device,
                  named.st_ino == firstFact.inode,
                  named.st_mode == firstFact.mode,
                  named.st_uid == firstFact.user,
                  named.st_gid == firstFact.group,
                  named.st_uid == Darwin.getuid(),
                  named.st_gid == Darwin.getgid(),
                  named.st_size == firstFact.size,
                  Int64(named.st_mtimespec.tv_sec)
                    == firstFact.modifiedSeconds,
                  Int64(named.st_mtimespec.tv_nsec)
                    == firstFact.modifiedNanoseconds,
                  try coldRootFact() == controls.eraseRoot,
                  try coldNamesChecked() == controls.names else {
                throw EraseIntentStoreError.invalidAuthority
            }
            guard requestCtimeTransitionEntered ||
                    EraseColdControlLeafFactV1(named) == expectedFullFact else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return .init(intentBytes: controls.intentBytes,
                preparationBytes: controls.preparationBytes,
                recordBytes: leaf.data, device: named.st_dev,
                inode: named.st_ino, mode: named.st_mode,
                user: named.st_uid, group: named.st_gid,
                links: named.st_nlink, size: named.st_size,
                modifiedSeconds:
                    Int64(named.st_mtimespec.tv_sec),
                modifiedNanoseconds:
                    Int64(named.st_mtimespec.tv_nsec),
                eraseRoot: controls.eraseRoot,
                names: controls.names)
        }
        let before = try witness()
        if let disposition = coldVerifiedAuxiliaryDisposition {
            guard try witness() == before else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let policy = try observeBorrowedColdPolicy(.journal,
                at: applicationSupportURL.appendingPathComponent(
                    policyRelativePath(Self.auxiliaryRosterName)))
            guard policy.device == UInt64(firstFact.device),
                  policy.inode == UInt64(firstFact.inode),
                  policy.linkCount == 1,
                  policy.backupExcluded == true,
                  (disposition == .verifiedComplete
                    ? policy.state == .strictComplete
                    : (policy.state == .pendingSimulatorRequest ||
                        policy.state == .strictComplete)),
                  try witness() == before else {
                throw EraseIntentStoreError.invalidAuthority
            }
            guard let projected = coldProjectedAuxiliaryRosterFact else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return projected
        }
        // The first full physical fact, including ctime, is bound before the
        // request. Only this checked request may subsequently project ctime.
        _ = try requireSchema2ColdObservedOriginalAuxiliaryRosterCut(
            intent: intent, preparation: preparation,
            operation: operation)
        coldObservedAuxiliaryPolicyInFlight = true
        do {
            let disposition = try ProtectedFilePolicyV1
                .verifyEraseColdTemporalPolicyWithCheckedRequest(
                    .journal,
                    at: applicationSupportURL.appendingPathComponent(
                        policyRelativePath(Self.auxiliaryRosterName)),
                    retainUncertainDescriptor: { value in
                        self.coldUncertainFDs.append(value)
                    }, willRequestCompleteProtection: {
                        guard !requestCtimeTransitionEntered,
                              try witness() == before else {
                            throw EraseIntentStoreError.invalidAuthority
                        }
                        requestCtimeTransitionEntered = true
                    }, unchangedWitness: { try witness() })
            guard coldUncertainFDs.isEmpty,
                  try witness() == before else {
                throw EraseIntentStoreError.invalidAuthority
            }
            var named = stat()
            guard Darwin.fstatat(eraseDescriptor,
                    Self.auxiliaryRosterName, &named,
                    AT_SYMLINK_NOFOLLOW) == 0 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let returnedFullFact = EraseColdControlLeafFactV1(named)
            guard requestCtimeTransitionEntered ||
                    returnedFullFact == expectedFullFact else {
                throw EraseIntentStoreError.invalidAuthority
            }
            expectedFullFact = returnedFullFact
            requestCtimeTransitionEntered = false
            let policy = try observeBorrowedColdPolicy(.journal,
                at: applicationSupportURL.appendingPathComponent(
                    policyRelativePath(Self.auxiliaryRosterName)))
            guard policy.device == UInt64(firstFact.device),
                  policy.inode == UInt64(firstFact.inode),
                  policy.linkCount == 1,
                  policy.backupExcluded == true,
                  (disposition == .verifiedComplete
                    ? policy.state == .strictComplete
                    : (policy.state == .pendingSimulatorRequest ||
                        policy.state == .strictComplete)),
                  try witness() == before else {
                throw EraseIntentStoreError.invalidAuthority
            }
            coldProjectedAuxiliaryRosterFact =
                EraseColdControlLeafFactV1(named)
            coldVerifiedAuxiliaryDisposition = disposition
            coldObservedAuxiliaryPolicyInFlight = false
            return EraseColdControlLeafFactV1(named)
        } catch {
            coldEffectUncertain = true
            throw error
        }
    }

    /// The roster publisher consumes these exact held control bytes, not a
    /// fresh serialization used as a new baseline. This is observation only:
    /// it grants no right to add a roster child or to delete a generation.
    @MainActor
    func requireSchema2ColdCanonicalControls(
        intent expectedIntent: EraseIntentV1,
        preparation expectedPreparation: ErasePreparationV2,
        operation: EraseColdPreparationOperationV1
    ) throws -> (intentBytes: Data, preparationBytes: Data,
                 eraseRoot: EraseColdControlLeafFactV1,
                 names: [String]) {
        try operation.requireSchema2ColdIntentStore(self)
        guard borrowsColdObservation,
              expectedIntent.schemaVersion == 2,
              expectedPreparation.matches(expectedIntent) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try verifyAuthority()
        var before = stat(), named = stat()
        guard Darwin.fstat(eraseDescriptor, &before) == 0,
              Darwin.fstatat(applicationSupportDescriptor,
                  Self.directoryName, &named, AT_SYMLINK_NOFOLLOW) == 0,
              EraseColdControlLeafFactV1(before)
                == EraseColdControlLeafFactV1(named),
              let intentLeaf = try readIfPresent(Self.intentName),
              let preparationLeaf = try readIfPresent(Self.preparationName),
              try decode(intentLeaf.data) == expectedIntent,
              try decodePreparation(preparationLeaf.data)
                == expectedPreparation,
              try EraseIntentCodecV1.encode(expectedIntent)
                == intentLeaf.data,
              try ErasePreparationCodecV2.encode(expectedPreparation)
                == preparationLeaf.data else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let names = try coldNamesChecked()
        var after = stat(), namedAfter = stat()
        guard Darwin.fstat(eraseDescriptor, &after) == 0,
              Darwin.fstatat(applicationSupportDescriptor,
                  Self.directoryName, &namedAfter,
                  AT_SYMLINK_NOFOLLOW) == 0,
              EraseColdControlLeafFactV1(before)
                == EraseColdControlLeafFactV1(after),
              EraseColdControlLeafFactV1(after)
                == EraseColdControlLeafFactV1(namedAfter) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try verifyAuthority()
        return (intentLeaf.data, preparationLeaf.data,
            EraseColdControlLeafFactV1(after), names)
    }

    /// A post-generation continuation keeps the first control bytes and the
    /// checked policy projection. This value is comparison data, not an
    /// original publication receipt or permission to retire a control leaf.
    struct Schema2ColdPostGenerationControlCutV1: Equatable {
        let intentBytes: Data
        let intentFact: EraseColdControlLeafFactV1
        let preparationBytes: Data
        let preparationFact: EraseColdControlLeafFactV1
        let eraseRoot: EraseColdControlLeafFactV1
        let names: [String]
        let auxiliaryBytes: Data
        let auxiliaryFirstFact: EraseColdControlLeafFactV1
        let auxiliaryProjectedFact: EraseColdControlLeafFactV1
        let deletionBytes: Data
        let deletionFact: EraseColdControlLeafFactV1
    }

    @MainActor
    func requireSchema2ColdPostGenerationControlCut(
        intent: EraseIntentV1,
        preparation: ErasePreparationV2,
        roster: EraseSchema2ColdDeletionRosterV1,
        auxiliary: EraseSchema2ColdObservedOriginalAuxiliaryRosterV1,
        operation: EraseColdPreparationOperationV1
    ) throws -> Schema2ColdPostGenerationControlCutV1 {
        try operation.requireSchema2ColdPublishedRosterControlOwner(store: self)
        guard borrowsColdObservation, !coldCloseAttempted, !coldClosed,
              !coldEffectUncertain, !coldRosterInFlight,
              !coldObservedAuxiliaryPolicyInFlight,
              coldActiveFD == nil, coldEnumerationFD == nil,
              coldDirectoryStream == nil, coldUncertainFDs.isEmpty,
              !coldUncertainStreamClose,
              intent.phase == .sessionActivated,
              preparation.c05JobDrainV3 == nil,
              let intentFact = coldExpectedIntentFact,
              let preparationFact = coldExpectedPreparationFact,
              let firstBytes = coldAuxiliaryOriginBytes,
              let firstFact = coldAuxiliaryOriginFact,
              let projectedFact = coldProjectedAuxiliaryRosterFact,
              coldVerifiedAuxiliaryDisposition != nil,
              firstBytes == auxiliary.roster.canonicalBytes,
              firstFact == auxiliary.firstFileFact,
              projectedFact == auxiliary.projectedFileFact else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let controls = try requireSchema2ColdCanonicalControls(
            intent: intent, preparation: preparation, operation: operation)
        let expectedNames = [Self.intentName, Self.preparationName,
            Self.auxiliaryRosterName,
            EraseSchema2ColdDeletionRosterV1.canonicalName].sorted()
        guard controls.names == expectedNames,
              let auxiliaryLeaf = try readColdLeafIfPresent(
                Self.auxiliaryRosterName,
                maximumBytes: Self.maximumJournalBytes),
              auxiliaryLeaf.data == firstBytes else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var namedIntent = stat(), namedPreparation = stat(),
            namedAuxiliary = stat(), namedDeletion = stat()
        guard Darwin.fstatat(eraseDescriptor, Self.intentName,
                &namedIntent, AT_SYMLINK_NOFOLLOW) == 0,
              Darwin.fstatat(eraseDescriptor, Self.preparationName,
                &namedPreparation, AT_SYMLINK_NOFOLLOW) == 0,
              Darwin.fstatat(eraseDescriptor, Self.auxiliaryRosterName,
                &namedAuxiliary, AT_SYMLINK_NOFOLLOW) == 0,
              Darwin.fstatat(eraseDescriptor,
                EraseSchema2ColdDeletionRosterV1.canonicalName,
                &namedDeletion, AT_SYMLINK_NOFOLLOW) == 0,
              EraseColdControlLeafFactV1(namedIntent) == intentFact,
              EraseColdControlLeafFactV1(namedPreparation) == preparationFact,
              EraseColdControlLeafFactV1(namedAuxiliary) == projectedFact,
              EraseColdControlLeafFactV1(namedDeletion) == roster.recordFileFact,
              try coldRootFact() == controls.eraseRoot,
              try coldNamesChecked() == expectedNames else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try requireSchema2ColdPublishedRoster(intent: intent,
            preparation: preparation, canonicalBytes: roster.canonicalBytes,
            recordFact: roster.recordFileFact, operation: operation)
        try operation.requireSchema2ColdPublishedRosterControlOwner(store: self)
        return Schema2ColdPostGenerationControlCutV1(
            intentBytes: controls.intentBytes, intentFact: intentFact,
            preparationBytes: controls.preparationBytes,
            preparationFact: preparationFact, eraseRoot: controls.eraseRoot,
            names: expectedNames, auxiliaryBytes: firstBytes,
            auxiliaryFirstFact: firstFact,
            auxiliaryProjectedFact: projectedFact,
            deletionBytes: roster.canonicalBytes,
            deletionFact: roster.recordFileFact)
    }

    /// Bind only the physical R roster namespace observed before Support EX
    /// to this held Store after genuine EX/G. These bytes are opaque: the
    /// Manifest owner must decode and bind them to the canonical R controls
    /// and complete survivor cut before any deletion or temp replay.
    @MainActor
    func requireSchema2ColdObservedRosterCut(
        intent: EraseIntentV1,
        preparation: ErasePreparationV2,
        operation: EraseColdPreparationOperationV1,
        registryGAlreadyHeld: Bool = false
    ) throws -> Schema2ColdObservedRosterCutV1 {
        try operation.requireSchema2ColdRosterObservationOwner(
            store: self, registryGAlreadyHeld: registryGAlreadyHeld)
        guard borrowsColdObservation,
              intent.schemaVersion == 2,
              intent.phase == .sessionActivated,
              preparation.matches(intent),
              try load() == intent,
              try loadPreparation() == preparation,
              !coldRosterInFlight,
              coldRosterPublication == nil,
              coldOwnRosterFact == nil,
              coldActiveFD == nil,
              coldUncertainFDs.isEmpty,
              !coldEffectUncertain else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try verifyAuthority()
        let firstRoot = try coldRootFact()
        let names = try coldNamesChecked()
        guard names.contains(Self.rosterName)
                == coldCapturedOpaqueRosterPresent,
              names.contains(Self.rosterNextName)
                == (coldCapturedOpaqueRosterNextPresent &&
                    !coldObservedRosterTempSettled),
              names.allSatisfy({
                $0 == Self.intentName ||
                $0 == Self.preparationName ||
                ($0 == Self.nextName &&
                    coldCapturedOpaqueNextBytes != nil) ||
                ($0 == Self.auxiliaryRosterName &&
                    coldAuxiliaryOriginBytes != nil) ||
                ($0 == Self.originalRetiredCommitmentName &&
                    coldCapturedOpaqueOriginalRetired[$0] != nil) ||
                ($0 == Self.originalRetiredStageIdentityName &&
                    coldCapturedOpaqueOriginalRetired[$0] != nil) ||
                $0 == Self.rosterName ||
                $0 == Self.rosterNextName
              }) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let published = try observeSchema2ColdOpaqueRosterLeaf(
            Self.rosterName, expectedPresent:
                coldCapturedOpaqueRosterPresent)
        let temporary = try observeSchema2ColdOpaqueRosterLeaf(
            Self.rosterNextName, expectedPresent:
                coldCapturedOpaqueRosterNextPresent &&
                    !coldObservedRosterTempSettled)
        try verifyAuthority()
        guard try coldRootFact() == firstRoot,
              try coldNamesChecked() == names,
              try load() == intent,
              try loadPreparation() == preparation else {
            throw EraseIntentStoreError.invalidAuthority
        }
        // The final canonical leaf reads above are fallible observations.
        // Bind their result to the same held/named Erase root and closed name
        // set before retaining this cut as replay's sole physical baseline.
        try verifyAuthority()
        guard try coldRootFact() == firstRoot,
              try coldNamesChecked() == names else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let cut = Schema2ColdObservedRosterCutV1(
            published: published, temporary: temporary,
            eraseRoot: firstRoot, names: names)
        if let first = coldFirstObservedRosterCut {
            // A checked complete request may change only the policy
            // observation. The first opaque bytes, inode, full file fact,
            // Erase root, and names remain the sole physical baseline.
            guard first.published?.bytes == cut.published?.bytes,
                  first.published?.fact == cut.published?.fact,
                  (coldObservedRosterTempSettled
                    ? (first.temporary != nil &&
                        cut.temporary == nil &&
                        cut.eraseRoot ==
                            coldObservedRosterTempSettledRoot &&
                        cut.names == schema2ColdRosterNames())
                    : (first.temporary?.bytes == cut.temporary?.bytes &&
                        first.temporary?.fact == cut.temporary?.fact &&
                        first.eraseRoot == cut.eraseRoot &&
                        first.names == cut.names)) else {
                throw EraseIntentStoreError.invalidAuthority
            }
        } else {
            coldFirstObservedRosterCut = cut
        }
        return cut
    }

    /// A fresh R roster is data until its canonical record has been decoded
    /// against the held intent, preparation, and generations parent. Only
    /// then may this same operation request complete protection on the exact
    /// first observed inode. Pending policy alone is never replay authority.
    @MainActor
    func requireSchema2ColdVerifiedObservedRosterPolicy(
        roster: EraseSchema2ColdDeletionRosterV1,
        intent: EraseIntentV1,
        preparation: ErasePreparationV2,
        operation: EraseColdPreparationOperationV1,
        registryGAlreadyHeld: Bool = false
    ) throws {
        try operation.requireSchema2ColdRosterObservationOwner(
            store: self, registryGAlreadyHeld: registryGAlreadyHeld)
        guard borrowsColdObservation,
              intent.schemaVersion == 2,
              intent.phase == .sessionActivated,
              preparation.matches(intent),
              !coldObservedRosterPolicyRequestInFlight,
              !coldEffectUncertain,
              coldRosterPublication == nil,
              coldOwnRosterFact == nil,
              coldActiveFD == nil,
              coldUncertainFDs.isEmpty else {
            throw EraseIntentStoreError.invalidAuthority
        }
        func physicalWitness() throws -> Schema2ColdRosterPolicyWitnessV1 {
            try operation.requireSchema2ColdRosterObservationOwner(
                store: self, registryGAlreadyHeld: registryGAlreadyHeld)
            let controls = try requireSchema2ColdCanonicalControls(
                intent: intent, preparation: preparation,
                operation: operation)
            let cut = try requireSchema2ColdObservedRosterCut(
                intent: intent, preparation: preparation,
                operation: operation,
                registryGAlreadyHeld: registryGAlreadyHeld)
            guard let leaf = cut.published,
                  cut.temporary == nil,
                  cut.eraseRoot == controls.eraseRoot,
                  cut.names == controls.names,
                  cut.names == schema2ColdRosterNames([Self.rosterName]),
                  leaf.bytes == roster.canonicalBytes,
                  leaf.fact == roster.recordFileFact,
                  leaf.fact.mode & S_IFMT == S_IFREG,
                  leaf.fact.links == 1 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return Schema2ColdRosterPolicyWitnessV1(
                intentBytes: controls.intentBytes,
                preparationBytes: controls.preparationBytes,
                bytes: leaf.bytes, fact: leaf.fact,
                eraseRoot: cut.eraseRoot, names: cut.names)
        }
        let before = try physicalWitness()
        guard roster.canonicalSHA256 ==
                StoreMigrationCanonicalJSONV1.sha256(before.bytes) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        if let disposition = coldVerifiedObservedRosterDisposition {
            guard coldVerifiedObservedRosterSHA256 ==
                    roster.canonicalSHA256,
                  try physicalWitness() == before else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let policy = try observeBorrowedColdPolicy(.journal,
                at: applicationSupportURL.appendingPathComponent(
                    policyRelativePath(Self.rosterName)))
            guard policy.device == UInt64(before.fact.device),
                  policy.inode == UInt64(before.fact.inode),
                  policy.linkCount == 1,
                  (disposition == .verifiedComplete
                    ? policy.state == .strictComplete
                    : (policy.state == .pendingSimulatorRequest ||
                        policy.state == .strictComplete)),
                  try physicalWitness() == before else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return
        }
        // Registry's publisher has G and rechecks the exact prior tokens
        // inside that lock. It may only consume a previously checked policy
        // disposition; a new Foundation setter cannot run inside G.
        guard !registryGAlreadyHeld else {
            throw EraseIntentStoreError.invalidAuthority
        }
        coldObservedRosterPolicyRequestInFlight = true
        do {
            let disposition = try ProtectedFilePolicyV1
                .verifyEraseColdTemporalPolicyWithCheckedRequest(
                    .journal,
                    at: applicationSupportURL.appendingPathComponent(
                        policyRelativePath(Self.rosterName)),
                    retainUncertainDescriptor: { value in
                        self.coldUncertainFDs.append(value)
                    }, unchangedWitness: { try physicalWitness() })
            guard coldUncertainFDs.isEmpty,
                  try physicalWitness() == before else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let policy = try observeBorrowedColdPolicy(.journal,
                at: applicationSupportURL.appendingPathComponent(
                    policyRelativePath(Self.rosterName)))
            guard policy.device == UInt64(before.fact.device),
                  policy.inode == UInt64(before.fact.inode),
                  policy.linkCount == 1,
                  (disposition == .verifiedComplete
                    ? policy.state == .strictComplete
                    : (policy.state == .pendingSimulatorRequest ||
                        policy.state == .strictComplete)),
                  try physicalWitness() == before else {
                throw EraseIntentStoreError.invalidAuthority
            }
            coldVerifiedObservedRosterSHA256 = roster.canonicalSHA256
            coldVerifiedObservedRosterDisposition = disposition
            coldObservedRosterPolicyRequestInFlight = false
        } catch {
            coldEffectUncertain = true
            throw error
        }
    }

    @MainActor
    private func observeSchema2ColdOpaqueRosterLeaf(
        _ name: String, expectedPresent: Bool
    ) throws -> Schema2ColdObservedRosterLeafV1? {
        guard name == Self.rosterName || name == Self.rosterNextName,
              coldActiveFD == nil,
              coldUncertainFDs.isEmpty else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let descriptor = Darwin.openat(eraseDescriptor, name,
            O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
        if descriptor < 0 {
            guard errno == ENOENT, !expectedPresent else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return nil
        }
        coldActiveFD = descriptor
        do {
            var before = stat(), after = stat(), named = stat()
            guard expectedPresent,
                  Darwin.fstat(descriptor, &before) == 0,
                  before.st_mode & S_IFMT == S_IFREG,
                  before.st_nlink == 1,
                  before.st_size >= 0,
                  before.st_size <= off_t(Int.max),
                  Darwin.fstatat(eraseDescriptor, name, &named,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  EraseColdControlLeafFactV1(before)
                    == EraseColdControlLeafFactV1(named) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let fact = EraseColdControlLeafFactV1(before)
            let kind: OwnedFileKindV1 = name == Self.rosterName
                ? .journal : .journalTemporary
            let policyURL = applicationSupportURL.appendingPathComponent(
                policyRelativePath(name))
            let firstPolicy = try observeBorrowedColdPolicy(kind,
                at: policyURL)
            guard firstPolicy.device == UInt64(before.st_dev),
                  firstPolicy.inode == UInt64(before.st_ino),
                  firstPolicy.linkCount == 1,
                  (firstPolicy.state == .strictComplete ||
                    firstPolicy.state == .pendingSimulatorRequest) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            var bytes = Data()
            var buffer = [UInt8](repeating: 0, count: 16 * 1024)
            while true {
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.read(descriptor, $0.baseAddress, $0.count)
                }
                if count > 0 {
                    guard bytes.count <= Int(before.st_size) - count else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    bytes.append(contentsOf: buffer.prefix(count))
                } else if count == 0 { break }
                else if errno != EINTR {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            guard bytes.count == Int(before.st_size),
                  Darwin.fstat(descriptor, &after) == 0,
                  Darwin.fstatat(eraseDescriptor, name, &named,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  EraseColdControlLeafFactV1(after) == fact,
                  EraseColdControlLeafFactV1(named) == fact,
                  try observeBorrowedColdPolicy(kind,
                    at: policyURL) == firstPolicy else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try closeColdActiveChecked()
            return Schema2ColdObservedRosterLeafV1(
                bytes: bytes, fact: fact, policy: firstPolicy)
        } catch {
            let failure = error
            if coldActiveFD != nil { try closeColdActiveChecked() }
            throw failure
        }
    }

    /// Settle only the first opaque roster temporary after Manifest has
    /// derived the complete canonical record from still-held intact sources.
    /// The first temp bytes/fact remain immutable; a separate one-way root
    /// projection records this checked unlink and cannot authorize a
    /// different temporary or a partially deleted tree.
    @MainActor
    func settleSchema2ColdObservedRosterTemporary(
        seal: EraseSchema2ColdDeletionRosterPublicationSealV1,
        intent: EraseIntentV1,
        preparation: ErasePreparationV2,
        operation: EraseColdPreparationOperationV1
    ) throws {
        guard borrowsColdObservation,
              coldCapturedOpaqueRosterNextPresent,
              !coldCapturedOpaqueRosterPresent,
              !coldObservedRosterTempRemovalInFlight,
              !coldObservedRosterTempSettled,
              coldRosterPublication == nil,
              !coldRosterInFlight,
              !coldEffectUncertain,
              coldActiveFD == nil,
              coldUncertainFDs.isEmpty else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try operation.requireSchema2ColdRosterSourceFactsBeforeTempRemoval(
            seal: seal, store: self)
        func physicalWitness() throws -> Schema2ColdRosterPolicyWitnessV1 {
            try operation.requireSchema2ColdRosterSourceFactsBeforeTempRemoval(
                seal: seal, store: self)
            let controls = try requireSchema2ColdCanonicalControls(
                intent: intent, preparation: preparation,
                operation: operation)
            let cut = try requireSchema2ColdObservedRosterCut(
                intent: intent, preparation: preparation,
                operation: operation)
            guard cut.published == nil,
                  let temp = cut.temporary,
                  cut.eraseRoot == controls.eraseRoot,
                  cut.names == controls.names,
                  cut.names == schema2ColdRosterNames([Self.rosterNextName]),
                  temp.fact.mode & S_IFMT == S_IFREG,
                  temp.fact.links == 1,
                  temp.fact.size == off_t(temp.bytes.count),
                  seal.canonicalBytes.starts(with: temp.bytes) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return Schema2ColdRosterPolicyWitnessV1(
                intentBytes: controls.intentBytes,
                preparationBytes: controls.preparationBytes,
                bytes: temp.bytes, fact: temp.fact,
                eraseRoot: cut.eraseRoot, names: cut.names)
        }
        let first = try physicalWitness()
        coldObservedRosterTempRemovalInFlight = true
        do {
            let url = applicationSupportURL.appendingPathComponent(
                policyRelativePath(Self.rosterNextName))
            let disposition = try ProtectedFilePolicyV1
                .verifyEraseColdTemporalPolicyWithCheckedRequest(
                    .journalTemporary, at: url,
                    retainUncertainDescriptor: { value in
                        self.coldUncertainFDs.append(value)
                    }, unchangedWitness: { try physicalWitness() })
            guard coldUncertainFDs.isEmpty,
                  try physicalWitness() == first else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let policy = try observeBorrowedColdPolicy(
                .journalTemporary, at: url)
            guard policy.device == UInt64(first.fact.device),
                  policy.inode == UInt64(first.fact.inode),
                  policy.linkCount == 1,
                  (disposition == .verifiedComplete
                    ? policy.state == .strictComplete
                    : (policy.state == .pendingSimulatorRequest ||
                        policy.state == .strictComplete)),
                  try physicalWitness() == first else {
                throw EraseIntentStoreError.invalidAuthority
            }
            coldVerifiedObservedRosterTempDisposition = disposition
            let descriptor = Darwin.openat(eraseDescriptor,
                Self.rosterNextName,
                O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
            guard descriptor >= 0 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            coldActiveFD = descriptor
            var held = stat(), named = stat()
            var heldRoot = stat(), namedRoot = stat(), namedSupport = stat()
            try operation.requireSchema2ColdRosterSourceFactsBeforeTempRemoval(
                seal: seal, store: self)
            guard Darwin.fstat(descriptor, &held) == 0,
                  Darwin.fstatat(eraseDescriptor,
                    Self.rosterNextName, &named,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  EraseColdControlLeafFactV1(held) == first.fact,
                  EraseColdControlLeafFactV1(named) == first.fact,
                  Darwin.fstat(eraseDescriptor, &heldRoot) == 0,
                  Darwin.fstatat(applicationSupportDescriptor,
                    Self.directoryName, &namedRoot,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  EraseColdControlLeafFactV1(heldRoot)
                    == first.eraseRoot,
                  EraseColdControlLeafFactV1(namedRoot)
                    == first.eraseRoot,
                  Darwin.lstat(applicationSupportURL.path,
                    &namedSupport) == 0,
                  namedSupport.st_mode & S_IFMT == S_IFDIR,
                  namedSupport.st_dev
                    == applicationSupportIdentity.device,
                  namedSupport.st_ino
                    == applicationSupportIdentity.inode,
                  try coldNamesChecked() == first.names,
                  Darwin.unlinkat(eraseDescriptor,
                    Self.rosterNextName, 0) == 0,
                  Darwin.fsync(eraseDescriptor) == 0 else {
                throw EraseIntentStoreError.writeFailed
            }
            try closeColdActiveChecked()
            let afterRoot = try coldRootFact()
            let afterNames = try coldNamesChecked()
            var absent = stat()
            guard afterRoot.device == first.eraseRoot.device,
                  afterRoot.inode == first.eraseRoot.inode,
                  afterRoot.mode == first.eraseRoot.mode,
                  afterRoot.links == first.eraseRoot.links,
                  afterNames == schema2ColdRosterNames(),
                  Darwin.fstatat(eraseDescriptor,
                    Self.rosterNextName, &absent,
                    AT_SYMLINK_NOFOLLOW) != 0,
                  errno == ENOENT else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try operation.requireSchema2ColdRosterSourceFactsBeforeTempRemoval(
                seal: seal, store: self)
            coldObservedRosterTempSettledRoot = afterRoot
            coldObservedRosterTempSettled = true
            coldObservedRosterTempRemovalInFlight = false
            let controls = try requireSchema2ColdCanonicalControls(
                intent: intent, preparation: preparation,
                operation: operation)
            guard controls.eraseRoot == afterRoot,
                  controls.names == afterNames else {
                throw EraseIntentStoreError.invalidAuthority
            }
        } catch {
            let failure = error
            if coldActiveFD != nil {
                do { try closeColdActiveChecked() }
                catch {
                    coldEffectUncertain = true
                    throw error
                }
            }
            coldEffectUncertain = true
            throw failure
        }
    }

    /// The Manifest owner has already sealed a complete semantic roster and
    /// the Router proves the actual R session/EX/G. This first physical cut
    /// has exactly the two captured canonical leaves and no roster child.
    @MainActor
    func beginSchema2ColdRosterPublication(
        intent: EraseIntentV1, preparation: ErasePreparationV2,
        seal: EraseSchema2ColdDeletionRosterPublicationSealV1,
        operation: EraseColdPreparationOperationV1
    ) throws -> Schema2ColdRosterPublicationV1 {
        guard intent.schemaVersion == 2,
              intent.phase == .sessionActivated,
              !coldRosterInFlight,
              coldRosterPublication == nil,
              coldOwnRosterFact == nil,
              !seal.canonicalBytes.isEmpty,
              seal.canonicalSHA256 == StoreMigrationCanonicalJSONV1.sha256(
                seal.canonicalBytes) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try operation.requireSchema2ColdRosterAdmission(
            intent: intent, store: self)
        try operation.requireSchema2ColdRosterPublicationSeal(seal)
        let controls = try requireSchema2ColdCanonicalControls(
            intent: intent, preparation: preparation,
            operation: operation)
        if coldObservedRosterTempSettled {
            guard let projected = coldObservedRosterTempSettledRoot,
                  controls.eraseRoot == projected else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        guard controls.names == schema2ColdRosterNames() else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let receipt = Schema2ColdRosterPublicationV1(
            store: self, operation: operation,
            seal: seal,
            intentBytes: controls.intentBytes,
            preparationBytes: controls.preparationBytes,
            originalRoot: controls.eraseRoot)
        coldRosterPublication = receipt
        coldRosterInFlight = true
        return receipt
    }

    /// The borrowed Store is the sole descriptor owner for this prospective
    /// record. Its O_EXCL temporary is policy-checked, fully written and
    /// fsynced before a checked no-replace rename and parent fsync. No fixed
    /// journal-size ceiling is imposed on the complete node roster.
    @MainActor
    func publishSchema2ColdRosterBytes(
        receipt: Schema2ColdRosterPublicationV1,
        seal: EraseSchema2ColdDeletionRosterPublicationSealV1,
        operation: EraseColdPreparationOperationV1
    ) throws -> EraseColdControlLeafFactV1 {
        let canonicalBytes = seal.canonicalBytes
        guard coldRosterPublication === receipt,
              receipt.store === self,
              receipt.operation === operation,
              receipt.seal === seal,
              coldRosterInFlight,
              receipt.publishedFact == nil,
              !canonicalBytes.isEmpty,
              seal.canonicalSHA256 == StoreMigrationCanonicalJSONV1.sha256(
                canonicalBytes),
              coldOwnRosterBytes == nil,
              coldActiveFD == nil,
              coldUncertainFDs.isEmpty,
              !coldEffectUncertain else {
            throw EraseIntentStoreError.invalidAuthority
        }
        do {
            try operation.requireSchema2ColdRosterPublicationSeal(seal)
            try operation.requireSchema2ColdRosterEffectOwner(
                store: self)
            _ = try requireSchema2ColdRosterControls(
                receipt: receipt,
                expectedNames: schema2ColdRosterNames(),
                expectedRoot: receipt.originalRoot)
            coldOwnRosterBytes = canonicalBytes
            let temporary = try createColdLeaf(Self.rosterNextName,
                data: canonicalBytes, maximumBytes: canonicalBytes.count)
            receipt.postTemporaryRoot = try requireSchema2ColdRosterControls(
                receipt: receipt,
                expectedNames: schema2ColdRosterNames([Self.rosterNextName]),
                expectedRoot: nil)
            guard let checkedTemp = try readColdLeafIfPresent(
                    Self.rosterNextName,
                    maximumBytes: canonicalBytes.count),
                  checkedTemp.identity == temporary,
                  checkedTemp.data == canonicalBytes else {
                throw EraseIntentStoreError.writeFailed
            }
            guard let afterTemp = receipt.postTemporaryRoot else {
                throw EraseIntentStoreError.writeFailed
            }
            try operation.requireSchema2ColdRosterSourceFactsBeforeRename(
                seal: seal, store: self)
            guard try requireSchema2ColdRosterControls(
                    receipt: receipt,
                    expectedNames: schema2ColdRosterNames([Self.rosterNextName]),
                    expectedRoot: afterTemp) == afterTemp,
                  Darwin.renameatx_np(eraseDescriptor,
                    Self.rosterNextName, eraseDescriptor,
                    Self.rosterName, UInt32(RENAME_EXCL)) == 0,
                  Darwin.fsync(eraseDescriptor) == 0 else {
                throw EraseIntentStoreError.writeFailed
            }
            coldOwnPublishingName = Self.rosterName
            coldOwnPublishedIdentity = temporary
            receipt.postPublishedRoot = try requireSchema2ColdRosterControls(
                receipt: receipt,
                expectedNames: schema2ColdRosterNames([Self.rosterName]),
                expectedRoot: nil)
            guard let written = try readColdLeafIfPresent(
                    Self.rosterName,
                    maximumBytes: canonicalBytes.count),
                  written.identity == temporary,
                  written.data == canonicalBytes else {
                throw EraseIntentStoreError.writeFailed
            }
            var record = stat(), named = stat()
            guard Darwin.fstatat(eraseDescriptor,
                    Self.rosterName, &record,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  Darwin.fstatat(eraseDescriptor,
                    Self.rosterName, &named,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  EraseColdControlLeafFactV1(record)
                    == EraseColdControlLeafFactV1(named),
                  record.st_dev == temporary.device,
                  record.st_ino == temporary.inode,
                  record.st_mode & S_IFMT == S_IFREG,
                  record.st_nlink == 1 else {
                throw EraseIntentStoreError.writeFailed
            }
            let fact = EraseColdControlLeafFactV1(record)
            receipt.publishedFact = fact
            return fact
        } catch {
            coldEffectUncertain = true
            throw error
        }
    }

    /// Manifest may accept the record only after this same held Store sees
    /// its exact published inode/bytes, absent temp, unchanged canonical
    /// intent/preparation and a stable held/named Erase root. The projection
    /// grants no deletion right; the typed durable roster is separately due.
    @MainActor
    func finishSchema2ColdRosterPublication(
        receipt: Schema2ColdRosterPublicationV1,
        seal: EraseSchema2ColdDeletionRosterPublicationSealV1,
        recordFact: EraseColdControlLeafFactV1,
        operation: EraseColdPreparationOperationV1
    ) throws {
        let canonicalBytes = seal.canonicalBytes
        guard coldRosterPublication === receipt,
              receipt.store === self,
              receipt.operation === operation,
              receipt.seal === seal,
              coldRosterInFlight,
              seal.canonicalSHA256 == StoreMigrationCanonicalJSONV1.sha256(
                canonicalBytes),
              receipt.publishedFact == recordFact,
              coldOwnRosterBytes == canonicalBytes,
              !coldEffectUncertain else {
            throw EraseIntentStoreError.invalidAuthority
        }
        do {
            try operation.requireSchema2ColdRosterPublicationSeal(seal)
            guard let publishedRoot = receipt.postPublishedRoot,
                  try requireSchema2ColdRosterControls(
                receipt: receipt,
                expectedNames: schema2ColdRosterNames([Self.rosterName]),
                expectedRoot: publishedRoot) == publishedRoot else {
                throw EraseIntentStoreError.invalidAuthority
            }
            guard let written = try readColdLeafIfPresent(
                    Self.rosterName,
                    maximumBytes: canonicalBytes.count),
                  written.data == canonicalBytes else {
                throw EraseIntentStoreError.invalidAuthority
            }
            var record = stat()
            guard Darwin.fstatat(eraseDescriptor,
                    Self.rosterName, &record,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  EraseColdControlLeafFactV1(record) == recordFact else {
                throw EraseIntentStoreError.invalidAuthority
            }
            coldOwnRosterFact = recordFact
            coldOwnTemporaryName = nil
            coldOwnTemporaryIdentity = nil
            coldOwnTemporaryBytes = nil
            coldOwnPublishingName = nil
            coldOwnPublishedIdentity = nil
            coldPublishedVerified = false
            coldRosterInFlight = false
            try verifyAuthority()
        } catch {
            coldEffectUncertain = true
            throw error
        }
    }

    /// Reprove the exact roster published by this borrowed Store before a
    /// rostered deletion step. This is an observation, not another roster
    /// admission or an opportunity to adopt a named file as our own record.
    @MainActor
    func requireSchema2ColdPublishedRoster(
        intent: EraseIntentV1,
        preparation: ErasePreparationV2,
        canonicalBytes: Data,
        recordFact: EraseColdControlLeafFactV1,
        operation: EraseColdPreparationOperationV1
    ) throws {
        try operation.requireSchema2ColdPublishedRosterControlOwner(
            store: self)
        if coldRosterPublication == nil {
            // A fresh R operation may inherit only the exact canonical leaf
            // captured as opaque physical evidence before EX. Its first
            // checked post-EX/G bytes/fact remain the sole replay baseline.
            // The decoded record must also carry this operation's successful
            // complete-request disposition; raw pending is insufficient.
            let roster = try operation.requireSchema2ColdObservedReplayRoster(
                canonicalBytes: canonicalBytes, recordFact: recordFact,
                store: self)
            try requireSchema2ColdVerifiedObservedRosterPolicy(
                roster: roster, intent: intent,
                preparation: preparation, operation: operation)
            let observed = try requireSchema2ColdObservedRosterCut(
                intent: intent, preparation: preparation,
                operation: operation)
            guard let leaf = observed.published,
                  observed.temporary == nil,
                  leaf.bytes == canonicalBytes,
                  leaf.fact == recordFact,
                  observed.names == schema2ColdRosterNames([Self.rosterName]) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try verifyAuthority()
            return
        }
        guard borrowsColdObservation,
              !coldRosterInFlight,
              !coldEffectUncertain,
              coldRosterPublication?.store === self,
              coldRosterPublication?.operation === operation,
              coldRosterPublication?.intentBytes
                == (try EraseIntentCodecV1.encode(intent)),
              coldRosterPublication?.preparationBytes
                == (try ErasePreparationCodecV2.encode(preparation)),
              coldOwnRosterFact == recordFact,
              coldOwnRosterBytes == canonicalBytes,
              !canonicalBytes.isEmpty else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try verifyAuthority()
        let controls = try requireSchema2ColdCanonicalControls(
            intent: intent,
            preparation: preparation,
            operation: operation)
        guard controls.names == schema2ColdRosterNames([Self.rosterName]),
              try readColdLeafIfPresent(Self.rosterNextName,
                maximumBytes: canonicalBytes.count) == nil,
              let leaf = try readColdLeafIfPresent(Self.rosterName,
                maximumBytes: canonicalBytes.count),
              leaf.data == canonicalBytes,
              leaf.identity.device == recordFact.device,
              leaf.identity.inode == recordFact.inode else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var named = stat()
        guard Darwin.fstatat(eraseDescriptor, Self.rosterName,
                &named, AT_SYMLINK_NOFOLLOW) == 0,
              EraseColdControlLeafFactV1(named) == recordFact,
              named.st_mode & S_IFMT == S_IFREG,
              named.st_nlink == 1 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try verifyAuthority()
    }

    @MainActor
    private func requireSchema2ColdRosterControls(
        receipt: Schema2ColdRosterPublicationV1,
        expectedNames: [String],
        expectedRoot: EraseColdControlLeafFactV1?
    ) throws -> EraseColdControlLeafFactV1 {
        guard coldRosterPublication === receipt,
              coldRosterInFlight,
              !coldEffectUncertain,
              coldActiveFD == nil,
              coldUncertainFDs.isEmpty else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var heldBefore = stat(), namedBefore = stat(),
            heldAfter = stat(), namedAfter = stat()
        guard Darwin.fstat(eraseDescriptor, &heldBefore) == 0,
              Darwin.fstatat(applicationSupportDescriptor,
                Self.directoryName, &namedBefore,
                AT_SYMLINK_NOFOLLOW) == 0,
              EraseColdControlLeafFactV1(heldBefore)
                == EraseColdControlLeafFactV1(namedBefore),
              expectedRoot == nil ||
                EraseColdControlLeafFactV1(heldBefore)
                    == expectedRoot,
              try coldNamesChecked() == expectedNames,
              let intent = try readColdLeafIfPresent(Self.intentName),
              let preparation = try readColdLeafIfPresent(
                Self.preparationName),
              intent.data == receipt.intentBytes,
              preparation.data == receipt.preparationBytes,
              try coldNamesChecked() == expectedNames,
              Darwin.fstat(eraseDescriptor, &heldAfter) == 0,
              Darwin.fstatat(applicationSupportDescriptor,
                Self.directoryName, &namedAfter,
                AT_SYMLINK_NOFOLLOW) == 0,
              EraseColdControlLeafFactV1(heldBefore)
                == EraseColdControlLeafFactV1(heldAfter),
              EraseColdControlLeafFactV1(heldAfter)
                == EraseColdControlLeafFactV1(namedAfter) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return EraseColdControlLeafFactV1(heldAfter)
    }

    deinit {
        // The retained cold observation owns these lent descriptors and its
        // checked close is the only release. Closing here could hit a reused
        // descriptor after that owner has already closed it.
        guard !borrowsColdObservation, !originalRecoveryCloseAttempted else { return }
        originalRecoveryCloseAttempted = true // fence numeric parent slots BEFORE close
        for descriptor in [eraseDescriptor, applicationSupportDescriptor] {
            if Darwin.close(descriptor) != 0 {
                Self.uncertainOriginalRecoveryCloseLock.withLock {
                    Self.uncertainOriginalRecoveryDescriptors.append(descriptor)
                }
            }
        }
        if (try? originalCanonicalSourceIO.requireSettled()) == nil {
            Self.retainCanonicalIO(originalCanonicalSourceIO)
        }
        if let originalCanonicalReadIO { Self.retainCanonicalIO(originalCanonicalReadIO) }
    }

    /// The first-effect writer is constructed only under the original EX/G.
    /// Its two held descriptors and every transient are settled before the
    /// coordinator may transfer to target-writer installation.
    func closeCheckedForOriginalRecovery() throws {
        guard !borrowsColdObservation, let originalRecoveryCheckedIO,
              !originalRecoveryCloseAttempted else {
            throw EraseIntentStoreError.invalidAuthority
        }
        originalRecoveryCloseAttempted = true
        var failed = false
        if (try? originalRecoveryCheckedIO.requireSettled()) == nil
            || (try? originalCanonicalSourceIO.requireSettled()) == nil
            || !originalRecoveryUncertainPolicyDescriptors.isEmpty { failed = true }
        for descriptor in [eraseDescriptor, applicationSupportDescriptor] {
            if Darwin.close(descriptor) != 0 {
                Self.uncertainOriginalRecoveryCloseLock.withLock {
                    Self.uncertainOriginalRecoveryDescriptors.append(descriptor)
                }
                failed = true
            }
        }
        guard !failed else { throw EraseIntentStoreError.invalidAuthority }
    }

    /// The operation-retained observer alone closes the lent root descriptors.
    /// A failed close is terminal and never retried by numeric descriptor.
    @MainActor
    func sealBorrowedColdAndCloseObserverChecked(
        operation: EraseColdPreparationOperationV1
    ) throws {
        try operation.requireSchema2ColdIntentStore(self)
        guard borrowsColdObservation, !coldCloseAttempted,
              coldActiveFD == nil, coldEnumerationFD == nil,
              coldDirectoryStream == nil, coldUncertainFDs.isEmpty,
              !coldUncertainStreamClose, coldOwnTemporaryName == nil,
              coldOwnPublishingName == nil,
              coldOwnPublishedIdentity == nil,
              coldDisplacedBytes == nil, coldDisplacedFact == nil,
              !coldEffectUncertain else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try verifyAuthority()
        _ = try readColdLeafIfPresent(Self.intentName)
        _ = try readColdLeafIfPresent(Self.preparationName)
        guard try readColdLeafIfPresent(Self.nextName) == nil,
              try readColdLeafIfPresent(Self.preparationNextName) == nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try verifyAuthority()
        coldCloseAttempted = true
        try operation.closeColdControlObservationChecked()
        coldClosed = true
    }

    /// The fixed retirement edge must never run load's pending-file repairs
    /// while the transferred registry exclusion is held.
    struct RetirementObservation {
        fileprivate let storeIdentity: ObjectIdentifier
        fileprivate let device: dev_t
        fileprivate let inode: ino_t
        fileprivate let fact: RetirementLeafFact
        fileprivate let data: Data
        let intent: EraseIntentV1
    }

    fileprivate struct RetirementLeafFact: Equatable {
        let device: dev_t, inode: ino_t, mode: mode_t, links: nlink_t
        let size: off_t
        let modifiedSeconds: Int64, modifiedNanoseconds: Int64
        let changedSeconds: Int64, changedNanoseconds: Int64
        init(_ value: stat) {
            device = value.st_dev; inode = value.st_ino
            mode = value.st_mode; links = value.st_nlink
            size = value.st_size
            modifiedSeconds = Int64(value.st_mtimespec.tv_sec)
            modifiedNanoseconds = Int64(value.st_mtimespec.tv_nsec)
            changedSeconds = Int64(value.st_ctimespec.tv_sec)
            changedNanoseconds = Int64(value.st_ctimespec.tv_nsec)
        }
    }

    private struct RetirementBoundWitness: Equatable {
        let fact: RetirementLeafFact
        let data: Data
    }

    private enum RetirementPolicyMode {
        case strict
        case pureObservation
        case authenticated(RetirementBoundWitness)
    }

    func captureRetirementObservation(expected: EraseIntentV1) throws
        -> RetirementObservation {
        guard expected.phase == .sessionActivated || expected.phase == .cleanupComplete,
              EraseIntentCodecV1.valid(expected) else {
            throw EraseIntentStoreError.invalidIntent
        }
        let leaf = try readRetirementCanonical(policy: .pureObservation)
        guard try decode(leaf.data) == expected else {
            throw EraseIntentStoreError.intentMismatch
        }
        let authenticated = try readRetirementCanonical(
            policy: .authenticated(RetirementBoundWitness(fact: leaf.fact, data: leaf.data)))
        guard authenticated.fact == leaf.fact,
              authenticated.data == leaf.data else {
            throw EraseIntentStoreError.intentMismatch
        }
        return RetirementObservation(storeIdentity: ObjectIdentifier(self),
            device: leaf.identity.device, inode: leaf.identity.inode,
            fact: leaf.fact, data: leaf.data, intent: expected)
    }

    func requireRetirementObservation(_ observation: RetirementObservation) throws {
        guard observation.storeIdentity == ObjectIdentifier(self) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let leaf = try readRetirementCanonical(
            policy: .authenticated(RetirementBoundWitness(fact: observation.fact, data: observation.data)))
        guard leaf.identity.device == observation.device,
              leaf.identity.inode == observation.inode,
              leaf.fact == observation.fact,
              leaf.data == observation.data,
              try decode(leaf.data) == observation.intent else {
            throw EraseIntentStoreError.intentMismatch
        }
    }

#if DEBUG
    /// Original held-root, nonrepairing intent/preparation observation at the
    /// post-retirement fault. It reuses the genuine retirement observation and
    /// checked descriptor reads, then binds the complete exact Erase root.
    func postRetiredSnapshot(
        observation: RetirementObservation
    ) throws -> ErasePostRetiredIntentSnapshotV1 {
        try requireRetirementObservation(observation)
        try verifyAuthority()
        let names = try postRetiredIO.names(in: eraseDescriptor)
        guard names == [Self.intentName, Self.preparationName].sorted() else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let digest = try postRetiredIO.postRetiredTree(
            parent: applicationSupportDescriptor, name: Self.directoryName)
        try requireRetirementObservation(observation)
        guard try postRetiredIO.names(in: eraseDescriptor) == names,
              try postRetiredIO.postRetiredTree(
                  parent: applicationSupportDescriptor,
                  name: Self.directoryName) == digest else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return ErasePostRetiredIntentSnapshotV1(rootDigest: digest)
    }
#endif

    // An ambiguous close is retained as an unresolved actual descriptor;
    // its integer is never retried or relabeled closed.
    private var retirementUncertainReadDescriptors: [Int32] = []

    private func readRetirementCanonical(
        policy: RetirementPolicyMode = .strict
    ) throws -> (data: Data, identity: Identity, fact: RetirementLeafFact) {
        guard let value = try readRetirementLeaf(Self.intentName,
            kind: .journal, policy: policy) else {
            throw EraseIntentStoreError.intentMissing
        }
        return value
    }

#if DEBUG
    /// Admission to a test-host owner shutdown must observe the original
    /// canonical intent without `load()` repairing either pending leaf. The
    /// checked retirement reader retains an ambiguous descriptor close and
    /// throws; this method never promotes or removes a journal entry.
    func requireLiveOriginalColdShutdownIntent(
        sameOperationAs expected: EraseIntentV1
    ) throws {
        _ = try readLiveOriginalColdShutdownIntent(sameOperationAs: expected)
    }

    /// Returns the exact canonical value from the retained original Store.
    /// A checked policy request follows exact operation/phase authentication;
    /// no fresh owner is opened and no pending leaf is repaired.
    func readLiveOriginalColdShutdownIntent(
        sameOperationAs expected: EraseIntentV1,
        requiringPhase: EraseIntentPhaseV1? = nil
    ) throws -> EraseIntentV1 {
        guard EraseIntentCodecV1.valid(expected),
              expected.phase != .cleanupComplete else {
            throw EraseIntentStoreError.invalidIntent
        }
        func requireNoPendingPreparation() throws {
            try verifyAuthority()
            var pending = stat()
            let result = Darwin.fstatat(
                eraseDescriptor, Self.preparationNextName, &pending,
                AT_SYMLINK_NOFOLLOW
            )
            let lookupError = errno
            guard result != 0, lookupError == ENOENT else {
                throw EraseIntentStoreError.invalidPreparation
            }
            try verifyAuthority()
        }
        try requireNoPendingPreparation()
        // Read without effects first, then authenticate the exact original
        // operation and phase before requesting policy on that same leaf.
        let leaf = try readRetirementCanonical(policy: .pureObservation)
        let current = try decode(leaf.data)
        guard current.phase != .cleanupComplete,
              requiringPhase.map({ current.phase == $0 }) ?? true,
              sameOperation(current, expected) else {
            throw EraseIntentStoreError.intentMismatch
        }
        try requireNoPendingPreparation()
        let authenticated = try readRetirementCanonical(
            policy: .authenticated(RetirementBoundWitness(
                fact: leaf.fact, data: leaf.data)))
        guard authenticated.identity == leaf.identity,
              authenticated.fact == leaf.fact,
              authenticated.data == leaf.data,
              try decode(authenticated.data) == current else {
            throw EraseIntentStoreError.intentMismatch
        }
        try requireNoPendingPreparation()
        return current
    }
#endif

    private func readRetirementLeaf(_ name: String, kind: OwnedFileKindV1,
        policy mode: RetirementPolicyMode = .strict) throws
        -> (data: Data, identity: Identity, fact: RetirementLeafFact)? {
        guard name == Self.intentName || name == Self.preparationName else {
            throw EraseIntentStoreError.invalidAuthority
        }
        guard retirementUncertainReadDescriptors.isEmpty else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try AssetLocatorEraseIntentEnrollmentV1.validate()
        try verifyRetirementRootNoOpen()
        var pending = stat()
        guard Darwin.fstatat(eraseDescriptor, Self.nextName, &pending,
                             AT_SYMLINK_NOFOLLOW) != 0, errno == ENOENT else {
            throw EraseIntentStoreError.invalidIntent
        }
        let descriptor = Darwin.openat(eraseDescriptor, name,
                                       O_RDONLY | O_NOFOLLOW | O_NONBLOCK | O_CLOEXEC)
        if descriptor < 0, errno == ENOENT { return nil }
        guard descriptor >= 0 else { throw EraseIntentStoreError.invalidAuthority }
        var closeAttempted = false
        do {
        var before = stat()
        guard Darwin.fstat(descriptor, &before) == 0,
              (before.st_mode & S_IFMT) == S_IFREG, before.st_nlink == 1,
              before.st_size >= 0, before.st_size <= 1_048_576 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let identity = Identity(device: before.st_dev, inode: before.st_ino)
        let fact = RetirementLeafFact(before)
        if case .authenticated(let expected) = mode {
            guard fact == expected.fact else { throw EraseIntentStoreError.intentMismatch }
        }
        try verifyLeaf(name, descriptor: descriptor, expected: identity)
        let url = applicationSupportURL.appendingPathComponent(
            Self.directoryName).appendingPathComponent(name)
        let policy = try ProtectedFilePolicyV1
            .observeTemporalPolicyWithCheckedClose(kind, at: url,
                retainUncertainDescriptor: { value in
                    self.retirementUncertainReadDescriptors.append(value)
                })
        guard policy.device == UInt64(before.st_dev),
              policy.inode == UInt64(before.st_ino), policy.linkCount == 1,
              retirementUncertainReadDescriptors.isEmpty else {
            throw EraseIntentStoreError.invalidAuthority
        }
        switch mode {
        case .strict:
            guard policy.state == .strictComplete else {
                throw EraseIntentStoreError.retirementPolicyEffectUnavailable
            }
        case .pureObservation, .authenticated:
            guard policy.state == .strictComplete
                    || policy.state == .pendingSimulatorRequest else {
                throw EraseIntentStoreError.retirementPolicyEffectUnavailable
            }
        }
        var data = Data()
        var buffer = [UInt8](repeating: 0, count: 16 * 1024)
        while true {
            let count = buffer.withUnsafeMutableBytes {
                Darwin.read(descriptor, $0.baseAddress, $0.count)
            }
            if count > 0 {
                guard data.count <= 1_048_576 - count else { throw EraseIntentStoreError.invalidAuthority }
                data.append(contentsOf: buffer.prefix(count))
            }
            else if count == 0 { break }
            else if errno != EINTR { throw EraseIntentStoreError.invalidAuthority }
        }
        var after = stat()
        guard Darwin.fstat(descriptor, &after) == 0,
              fact == RetirementLeafFact(after),
              data.count == Int(after.st_size),
              after.st_nlink == 1,
              Darwin.fstatat(eraseDescriptor, Self.nextName, &pending,
                             AT_SYMLINK_NOFOLLOW) != 0, errno == ENOENT else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try verifyLeaf(name, descriptor: descriptor, expected: identity)
        try verifyRetirementRootNoOpen()
        if case .authenticated(let expected) = mode {
            guard fact == expected.fact, data == expected.data else {
                throw EraseIntentStoreError.intentMismatch
            }
            let beforeRequest = try retirementLeafWitness(
                descriptor: descriptor, name: name, expected: fact)
            guard beforeRequest.fact == fact,
                  beforeRequest.data == data else {
                throw EraseIntentStoreError.invalidAuthority
            }
            _ = try ProtectedFilePolicyV1
                .verifyEraseColdTemporalPolicyWithCheckedRequest(
                    kind, at: url, retainUncertainDescriptor: { value in
                        self.retirementUncertainReadDescriptors.append(value)
                    }, unchangedWitness: {
                        try self.retirementLeafWitness(
                            descriptor: descriptor, name: name,
                            expected: fact)
                    })
            guard retirementUncertainReadDescriptors.isEmpty,
                  try retirementLeafWitness(descriptor: descriptor,
                      name: name, expected: fact) == beforeRequest else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        closeAttempted = true
        guard Darwin.close(descriptor) == 0 else {
            retirementUncertainReadDescriptors.append(descriptor)
            throw EraseIntentStoreError.invalidAuthority
        }
        return (data, identity, fact)
        } catch {
            if !closeAttempted, Darwin.close(descriptor) != 0 {
                retirementUncertainReadDescriptors.append(descriptor)
            }
            throw error
        }
    }

    private func verifyRetirementRootNoOpen() throws {
        guard !originalAuxiliaryRetirementFailed else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try Self.requireDirectory(applicationSupportDescriptor,
            identity: applicationSupportIdentity)
        try Self.requireDirectory(eraseDescriptor, identity: eraseIdentity)
        var namedSupport = stat(), namedErase = stat()
        guard Darwin.lstat(applicationSupportURL.path, &namedSupport) == 0,
              namedSupport.st_mode & S_IFMT == S_IFDIR,
              namedSupport.st_dev == applicationSupportIdentity.device,
              namedSupport.st_ino == applicationSupportIdentity.inode,
              Darwin.fstatat(applicationSupportDescriptor,
                  Self.directoryName, &namedErase,
                  AT_SYMLINK_NOFOLLOW) == 0,
              namedErase.st_mode & S_IFMT == S_IFDIR,
              namedErase.st_dev == eraseIdentity.device,
              namedErase.st_ino == eraseIdentity.inode else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    /// Called only after an exact canonical model comparison. It retains the
    /// local leaf FD through the complete-request boundary and proves both
    /// that physical leaf and its canonical bytes without reparative loads.
    private func retirementLeafWitness(descriptor: Int32, name: String,
        expected: RetirementLeafFact) throws -> RetirementBoundWitness {
        guard retirementUncertainReadDescriptors.isEmpty,
              name == Self.intentName || name == Self.preparationName,
              expected.size >= 0, expected.size <= 1_048_576 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try verifyRetirementRootNoOpen()
        var held = stat(), named = stat(), pending = stat()
        guard Darwin.fstat(descriptor, &held) == 0,
              Darwin.fstatat(eraseDescriptor, name, &named,
                  AT_SYMLINK_NOFOLLOW) == 0,
              RetirementLeafFact(held) == expected,
              RetirementLeafFact(named) == expected,
              Darwin.fstatat(eraseDescriptor, Self.nextName, &pending,
                  AT_SYMLINK_NOFOLLOW) != 0, errno == ENOENT else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var bytes = Data(count: Int(expected.size))
        try bytes.withUnsafeMutableBytes { raw in
            var offset = 0
            while offset < raw.count {
                let count = Darwin.pread(descriptor,
                    raw.baseAddress!.advanced(by: offset),
                    raw.count - offset, off_t(offset))
                if count < 0 && errno == EINTR { continue }
                guard count > 0 else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                offset += count
            }
        }
        var afterHeld = stat(), afterNamed = stat()
        guard Darwin.fstat(descriptor, &afterHeld) == 0,
              Darwin.fstatat(eraseDescriptor, name, &afterNamed,
                  AT_SYMLINK_NOFOLLOW) == 0,
              RetirementLeafFact(afterHeld) == expected,
              RetirementLeafFact(afterNamed) == expected else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try verifyRetirementRootNoOpen()
        return RetirementBoundWitness(fact: expected, data: bytes)
    }

    /// The retirement capability belongs to one physical support root. This
    /// check opens no descriptors and grants no phase or deletion authority.
    @MainActor
    private func requireRetirementRoot(_ retirement: ErasedRegistryRetirementProofV1) throws {
        guard !originalAuxiliaryRetirementFailed else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let subject = retirement.binding.subject
        guard applicationSupportURL.standardizedFileURL == subject.applicationSupportURL.standardizedFileURL,
              Int64(applicationSupportIdentity.device) == subject.applicationSupportDevice,
              UInt64(applicationSupportIdentity.inode) == subject.applicationSupportInode else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try Self.requireDirectory(applicationSupportDescriptor, identity: applicationSupportIdentity)
        try Self.requireDirectory(eraseDescriptor, identity: eraseIdentity)
        var namedSupport = stat(), namedErase = stat()
        guard Darwin.lstat(applicationSupportURL.path, &namedSupport) == 0,
              namedSupport.st_mode & S_IFMT == S_IFDIR,
              namedSupport.st_dev == applicationSupportIdentity.device,
              namedSupport.st_ino == applicationSupportIdentity.inode,
              Darwin.fstatat(applicationSupportDescriptor, Self.directoryName,
                &namedErase, AT_SYMLINK_NOFOLLOW) == 0,
              namedErase.st_mode & S_IFMT == S_IFDIR,
              namedErase.st_dev == eraseIdentity.device,
              namedErase.st_ino == eraseIdentity.inode else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    /// Captures only the genuine original publication's immutable evidence.
    /// The old roster is deliberately not replayed after namespace retirement.
    @MainActor
    func captureOriginalAuxiliaryRetirementData(expected: EraseIntentV1,
        operation: EraseRouterOperationV1) throws -> OriginalAuxiliaryRetirementDataV1 {
        guard expected.schemaVersion == 2, expected.phase == .sessionActivated,
              originalCanonicalReadIO == nil, originalAuxiliaryRetirementIO == nil,
              !originalAuxiliaryRetirementFailed, !originalAuxiliaryRetirementRemoved else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let projection = try originalCanonicalLateProjection(operation: operation)
        let receipt = projection.roster
        let preparation = try decodePreparation(receipt.preparationBytes)
        let roster = try EraseSchema2ColdAuxiliaryPhysicalRosterV1.decodeCanonical(
            receipt.canonicalBytes, intent: expected, preparation: preparation)
        guard try decode(projection.leaves[0].bytes) == expected,
              try encode(expected) == projection.leaves[0].bytes,
              roster.canonicalBytes == receipt.seal.canonicalBytes,
              roster.record == receipt.seal.firstRoster.record,
              roster.record.supportDevice == Int64(applicationSupportIdentity.device),
              roster.record.supportInode == UInt64(applicationSupportIdentity.inode),
              projection.root.device == eraseIdentity.device,
              projection.root.inode == eraseIdentity.inode,
              let disposition = originalAuxiliaryTemporaryDisposition else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return OriginalAuxiliaryRetirementDataV1(storeIdentity: ObjectIdentifier(self),
            publicationIdentity: ObjectIdentifier(receipt),
            supportDevice: applicationSupportIdentity.device,
            supportInode: applicationSupportIdentity.inode,
            eraseDevice: eraseIdentity.device, eraseInode: eraseIdentity.inode,
            eraseMode: projection.root.mode, eraseUser: projection.root.user,
            eraseGroup: projection.root.group, intent: expected,
            canonicalBytes: receipt.canonicalBytes, fact: receipt.recordFact,
            disposition: disposition)
    }

    private struct OriginalAuxiliaryRetirementWitnessV1: Equatable {
        let fact: EraseColdControlLeafFactV1
        let bytes: Data
    }

    /// One fixed original leaf, under the current consumed retirement owner.
    /// A cold/legacy survivor is never promoted into original-publication DATA.
    @MainActor
    func removeOriginalAuxiliaryAfterRegistryRetirement(expected: EraseIntentV1,
        retirement: ErasedRegistryRetirementProofV1,
        data: OriginalAuxiliaryRetirementDataV1?) throws {
        func currentRetirement() throws {
            try requireRetirementRoot(retirement)
            try retirement.requireCompletionControlRemoval(expected: expected)
            guard retirementUncertainReadDescriptors.isEmpty else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        func absent(_ name: String) throws {
            try currentRetirement()
            var value = stat()
            let result = Darwin.fstatat(eraseDescriptor, name, &value, AT_SYMLINK_NOFOLLOW)
            let failure = errno
            try currentRetirement()
            guard result != 0, failure == ENOENT else {
#if DEBUG
                if result == 0 {
                    print("ORIGINAL_AUX_RETIREMENT_V1 refusal=expected-absence-present")
                } else {
                    print("ORIGINAL_AUX_RETIREMENT_V1 syscall=absence-fstatat errno=\(failure)")
                }
#endif
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        func completedIntent() throws -> RetirementBoundWitness {
            try currentRetirement()
            let value = try readRetirementCanonical(policy: .pureObservation)
            try currentRetirement()
            guard try encode(expected) == value.data,
                  try decode(value.data) == expected else {
                throw EraseIntentStoreError.intentMismatch
            }
            let witness = RetirementBoundWitness(fact: value.fact, data: value.data)
            let authenticated = try readRetirementCanonical(policy: .authenticated(witness))
            try currentRetirement()
            guard authenticated.identity == value.identity,
                  authenticated.fact == value.fact,
                  authenticated.data == value.data else {
                throw EraseIntentStoreError.intentMismatch
            }
            return witness
        }
        try currentRetirement()
        guard let data else {
            guard !originalAuxiliaryPublicationStarted,
                  originalAuxiliaryPublishedReceipt == nil,
                  originalAuxiliaryRetirementIO == nil,
                  !originalAuxiliaryRetirementFailed,
                  !originalAuxiliaryRetirementRemoved else {
                throw EraseIntentStoreError.invalidAuthority
            }
            _ = try completedIntent()
            try absent(Self.auxiliaryRosterName)
            try absent(Self.auxiliaryRosterNextName)
            try currentRetirement()
            return
        }
        guard originalAuxiliaryRetirementIO == nil,
              !originalAuxiliaryRetirementFailed, !originalAuxiliaryRetirementRemoved else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let io = OriginalCanonicalCheckedIOV1()
        originalAuxiliaryRetirementIO = io // actual owner retained BEFORE acquisition
        var stage = "data-binding"
        func bound() throws {
            try currentRetirement()
            try requireOriginalCanonicalMemoryLifetime()
            guard originalAuxiliaryRetirementIO === io,
                  !originalAuxiliaryRetirementFailed,
                  data.storeIdentity == ObjectIdentifier(self),
                  data.supportDevice == applicationSupportIdentity.device,
                  data.supportInode == applicationSupportIdentity.inode,
                  data.eraseDevice == eraseIdentity.device,
                  data.eraseInode == eraseIdentity.inode,
                  expected == data.intent.advancing(to: .cleanupComplete),
                  let receipt = originalAuxiliaryPublishedReceipt,
                  ObjectIdentifier(receipt) == data.publicationIdentity,
                  receipt.store === self, receipt.checkedSettled,
                  receipt.canonicalBytes == data.canonicalBytes,
                  receipt.recordFact == data.fact,
                  originalAuxiliaryTemporaryDisposition == data.disposition,
                  !data.canonicalBytes.isEmpty,
                  data.canonicalBytes.count <= Self.maximumJournalBytes,
                  data.fact.mode & S_IFMT == S_IFREG, data.fact.links == 1,
                  data.fact.size == off_t(data.canonicalBytes.count) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try io.requireNoUncertainty()
        }
        func syscall(_ name: String, _ body: () -> Int32) throws {
            try bound()
            let result = body(); let failure = errno
#if DEBUG
            if result != 0 {
                print("ORIGINAL_AUX_RETIREMENT_V1 syscall=\(name) errno=\(failure)")
            }
#endif
            try bound()
            guard result == 0 else { throw EraseIntentStoreError.invalidAuthority }
        }
        func rootFact(names: [String]) throws -> EraseColdControlLeafFactV1 {
            var held = stat(), named = stat()
            try syscall("root-fstat") { Darwin.fstat(eraseDescriptor, &held) }
            try syscall("root-fstatat") {
                Darwin.fstatat(applicationSupportDescriptor, Self.directoryName,
                    &named, AT_SYMLINK_NOFOLLOW)
            }
            let fact = EraseColdControlLeafFactV1(held)
            guard fact == EraseColdControlLeafFactV1(named),
                  fact.device == data.eraseDevice, fact.inode == data.eraseInode,
                  fact.mode == data.eraseMode, fact.user == data.eraseUser,
                  fact.group == data.eraseGroup,
                  EraseDirectoryEntryLinkModelV1.matches(
                    linkCount: Int64(fact.links), directEntryCount: names.count) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return fact
        }
        func namespace(_ names: [String]) throws {
            let before = try rootFact(names: names)
            _ = try io.names(parent: eraseDescriptor, expected: names, boundary: bound)
            guard try rootFact(names: names) == before else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        func namedLeaf() throws {
            var named = stat()
            try syscall("leaf-fstatat") {
                Darwin.fstatat(eraseDescriptor, Self.auxiliaryRosterName,
                    &named, AT_SYMLINK_NOFOLLOW)
            }
            guard EraseColdControlLeafFactV1(named) == data.fact else {
                throw EraseIntentStoreError.intentMismatch
            }
        }
        func heldLeaf(_ descriptor: Int32) throws {
            var held = stat()
            try syscall("leaf-fstat") { Darwin.fstat(descriptor, &held) }
            guard EraseColdControlLeafFactV1(held) == data.fact else {
                throw EraseIntentStoreError.intentMismatch
            }
            try namedLeaf()
        }
        func witness(_ descriptor: Int32) throws -> OriginalAuxiliaryRetirementWitnessV1 {
            try heldLeaf(descriptor)
            var offset = 0, calls = 0
            let (maximumCalls, overflow) = data.canonicalBytes.count.addingReportingOverflow(1)
            guard !overflow else { throw EraseIntentStoreError.invalidAuthority }
            var buffer = [UInt8](repeating: 0, count: 16 * 1024)
            while true {
                guard calls < maximumCalls else { throw EraseIntentStoreError.invalidAuthority }
                calls += 1
                let requested = offset == data.canonicalBytes.count ? 1
                    : min(buffer.count, data.canonicalBytes.count - offset)
                try bound(); try heldLeaf(descriptor)
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.pread(descriptor, $0.baseAddress, requested, off_t(offset))
                }
                let failure = errno
#if DEBUG
                if count < 0 { print("ORIGINAL_AUX_RETIREMENT_V1 syscall=leaf-pread errno=\(failure)") }
#endif
                try bound(); try heldLeaf(descriptor)
                guard count >= 0 else { throw EraseIntentStoreError.invalidAuthority }
                if count == 0 {
                    guard offset == data.canonicalBytes.count else {
                        throw EraseIntentStoreError.intentMismatch
                    }
                    break
                }
                guard count <= data.canonicalBytes.count - offset else {
                    throw EraseIntentStoreError.intentMismatch
                }
                let equal = data.canonicalBytes.withUnsafeBytes { expectedBytes in
                    buffer.withUnsafeBytes { actual in
                        memcmp(expectedBytes.baseAddress!.advanced(by: offset),
                            actual.baseAddress!, count) == 0
                    }
                }
                guard equal else { throw EraseIntentStoreError.intentMismatch }
                offset += count
            }
            try heldLeaf(descriptor)
            return OriginalAuxiliaryRetirementWitnessV1(fact: data.fact, bytes: data.canonicalBytes)
        }
        let beforeNames = [Self.intentName, Self.preparationName, Self.auxiliaryRosterName].sorted()
        let afterNames = [Self.intentName, Self.preparationName].sorted()
        do {
            try bound()
            stage = "completed-intent"
            let intentWitness = try completedIntent()
            try bound()
            stage = "namespace-before"
            try namespace(beforeNames)
            stage = "leaf-open"
            try bound()
            let descriptor = try io.openAt(eraseDescriptor, name: Self.auxiliaryRosterName,
                flags: O_RDONLY | O_NONBLOCK)
            try bound()
            stage = "leaf-fact-bytes"
            let first = try witness(descriptor)
            let url = applicationSupportURL.appendingPathComponent(Self.directoryName)
                .appendingPathComponent(Self.auxiliaryRosterName)
            stage = "leaf-policy"
            try bound()
            let policy = try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(.journal,
                at: url, retainUncertainDescriptor: { io.retainUncertainDescriptor($0) })
            try bound()
            guard policy.device == UInt64(data.fact.device),
                  policy.inode == UInt64(data.fact.inode), policy.linkCount == 1,
                  policy.backupExcluded == true,
                  policy.state == .strictComplete || (policy.state == .pendingSimulatorRequest
                    && data.disposition == .simulatorFileProtectionUnsupported),
                  try witness(descriptor) == first else {
                throw EraseIntentStoreError.retirementPolicyEffectUnavailable
            }
            _ = try ProtectedFilePolicyV1.verifyEraseColdTemporalPolicyWithCheckedRequest(.journal,
                at: url, retainUncertainDescriptor: { io.retainUncertainDescriptor($0) },
                unchangedWitness: { try witness(descriptor) })
            try bound()
            guard try witness(descriptor) == first else { throw EraseIntentStoreError.intentMismatch }
            stage = "leaf-close"
            try bound(); try io.closeOwnedOnce(descriptor); try bound()
            try io.requireSettled()
            stage = "completed-intent-before-unlink"
            guard try completedIntent() == intentWitness else {
                throw EraseIntentStoreError.intentMismatch
            }
            stage = "namespace-unlink"
            try io.withEffect(name: Self.auxiliaryRosterName,
                expectedBytes: data.canonicalBytes, replacementBytes: nil) {
                try namespace(beforeNames)
                try namedLeaf()
                try bound()
                io.markEffectEntry() // consumed effect BEFORE the actual unlink
                let result = Darwin.unlinkat(eraseDescriptor, Self.auxiliaryRosterName, 0)
                let failure = errno
#if DEBUG
                if result != 0 { print("ORIGINAL_AUX_RETIREMENT_V1 syscall=leaf-unlinkat errno=\(failure)") }
#endif
                try bound()
                guard result == 0 else { throw EraseIntentStoreError.cleanupFailed }
                stage = "namespace-sync"
                try syscall("root-fsync") { Darwin.fsync(eraseDescriptor) }
                stage = "namespace-after"
                try absent(Self.auxiliaryRosterName)
                try namespace(afterNames)
                try bound()
            }
            try io.requireSettled(); try bound()
            originalAuxiliaryRetirementRemoved = true
        } catch {
            let failure = error
#if DEBUG
            print("ORIGINAL_AUX_RETIREMENT_V1 refusal=\(stage)")
#endif
            originalAuxiliaryRetirementFailed = true
            do { try io.finishOwnedOnce() } catch { io.poison() }
            io.poison() // failed validation/effect cannot be retried through this owner
            Self.retainCanonicalIO(io)
            throw failure
        }
    }

    @MainActor
    func removePreparationAfterRegistryRetirement(expectedIntent: EraseIntentV1,
        retirement: ErasedRegistryRetirementProofV1) throws {
        try requireRetirementRoot(retirement)
        try retirement.requireCompletionControlRemoval(expected: expectedIntent)
        guard let value = try readRetirementLeaf(Self.preparationName,
            kind: .journal, policy: .pureObservation) else {
            try retirement.requireAlreadyAbsentPreparation(expected: expectedIntent)
            try requireRetirementRoot(retirement)
            try retirement.requireCompletionControlRemoval(expected: expectedIntent)
            return
        }
        let preparation = try decodePreparation(value.data)
        guard preparation.matches(expectedIntent), try encodePreparation(preparation) == value.data else {
            throw EraseIntentStoreError.preparationMismatch
        }
        guard let authenticated = try readRetirementLeaf(
            Self.preparationName, kind: .journal,
            policy: .authenticated(RetirementBoundWitness(fact: value.fact, data: value.data))),
            authenticated.fact == value.fact,
            authenticated.data == value.data else {
            throw EraseIntentStoreError.preparationMismatch
        }
        try removeRetirementExact(Self.preparationName, expected: value,
            expectedIntent: expectedIntent, retirement: retirement)
        try requireRetirementRoot(retirement)
        try retirement.requireCompletionControlRemoval(expected: expectedIntent)
    }

    @MainActor
    func removeAfterRegistryRetirement(expected: EraseIntentV1,
        retirement: ErasedRegistryRetirementProofV1) throws {
        try requireRetirementRoot(retirement)
        try retirement.requireCompletionControlRemoval(expected: expected)
        let value = try readRetirementCanonical(
            policy: .pureObservation)
        guard try encode(expected) == value.data, try decode(value.data) == expected else {
            throw EraseIntentStoreError.intentMismatch
        }
        let authenticated = try readRetirementCanonical(
            policy: .authenticated(RetirementBoundWitness(fact: value.fact, data: value.data)))
        guard authenticated.fact == value.fact,
              authenticated.data == value.data else {
            throw EraseIntentStoreError.intentMismatch
        }
        try removeRetirementExact(Self.intentName, expected: value,
            expectedIntent: expected, retirement: retirement)
        try requireRetirementRoot(retirement)
        try retirement.requireCompletionControlRemoval(expected: expected)
    }

    @MainActor
    private func removeRetirementExact(_ name: String,
        expected: (data: Data, identity: Identity,
                   fact: RetirementLeafFact), expectedIntent: EraseIntentV1,
        retirement: ErasedRegistryRetirementProofV1) throws {
        try requireRetirementRoot(retirement)
        try retirement.requireCompletionControlRemoval(expected: expectedIntent)
        guard let current = try readRetirementLeaf(name, kind: .journal,
                policy: .authenticated(RetirementBoundWitness(fact: expected.fact, data: expected.data))),
              current.identity == expected.identity,
              current.fact == expected.fact,
              current.data == expected.data else {
            throw EraseIntentStoreError.cleanupFailed
        }
        try requireRetirementRoot(retirement)
        try retirement.requireCompletionControlRemoval(expected: expectedIntent)
        guard Darwin.unlinkat(eraseDescriptor, name, 0) == 0,
              Darwin.fsync(eraseDescriptor) == 0,
              try readRetirementLeaf(name, kind: .journal) == nil else {
            throw EraseIntentStoreError.cleanupFailed
        }
        try requireRetirementRoot(retirement)
        try retirement.requireCompletionControlRemoval(expected: expectedIntent)
        try verifyRetirementRootNoOpen()
    }

    /// Observe only the exact four names used by original no-intent retry.
    /// Unlike load(), this opens no leaf, repairs no temp and cannot promote
    /// a newly arrived V3 preparation before the retained reader reproof.
    func requireOriginalNoIntentControlsNoRepair(
        preparationExpected: Bool
    ) throws {
        try AssetLocatorEraseIntentEnrollmentV1.validate()
        try verifyAuthority()
        for name in [Self.intentName, Self.nextName,
                     Self.preparationNextName] {
            var item = stat()
            guard Darwin.fstatat(eraseDescriptor, name, &item,
                    AT_SYMLINK_NOFOLLOW) != 0, errno == ENOENT else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        var preparation = stat()
        let found = Darwin.fstatat(eraseDescriptor,
            Self.preparationName, &preparation, AT_SYMLINK_NOFOLLOW) == 0
        guard found == preparationExpected else {
            throw EraseIntentStoreError.invalidAuthority
        }
        if found {
            guard preparation.st_mode & S_IFMT == S_IFREG,
                  preparation.st_nlink == 1 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try verifyExistingPolicy(.journal, name: Self.preparationName)
        } else {
            guard errno == ENOENT else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        try verifyAuthority()
    }

    private struct OriginalCanonicalExpectedLeafV1 {
        let name: String
        let bytes: Data
        let fact: EraseColdControlLeafFactV1
        let maximum: Int
    }
    @MainActor
    private struct OriginalCanonicalLateProjectionV1 {
        let operation: EraseRouterOperationV1
        let roster: OriginalAuxiliaryRosterPublicationReceiptV1
        let commitment: OriginalRecoveryRetiredCommitmentReceiptV1?
        let stage: OriginalRecoveryRetiredStageIdentityReceiptV1?
        let root: EraseColdControlLeafFactV1
        let leaves: [OriginalCanonicalExpectedLeafV1]
        var names: [String] { leaves.map(\.name).sorted() }
    }

    /// Memory only: no loader, publisher reproof, filesystem or Registry IO.
    @MainActor
    func originalScratchCanonicalControlExpectation(operation: EraseRouterOperationV1)
        throws -> (intent: EraseIntentV1, preparation: ErasePreparationV2) {
        guard originalCanonicalReadIO == nil else { throw EraseIntentStoreError.invalidAuthority }
        let projection = try originalCanonicalLateProjection(operation: operation)
        let intent = try decode(projection.leaves[0].bytes)
        let preparation = try decodePreparation(projection.leaves[1].bytes)
        guard preparation.matches(intent) else { throw EraseIntentStoreError.invalidAuthority }
        return (intent, preparation)
    }

    private func requireOriginalCanonicalMemoryLifetime() throws {
        guard !borrowsColdObservation, !originalRecoveryCloseAttempted,
              !coldCloseAttempted, !coldClosed, !originalCanonicalReadFailed,
              !originalAuxiliaryPublicationUncertain,
              !originalAuxiliaryPhaseInFlight, !originalAuxiliaryPhaseUncertain,
              !originalRetiredCommitmentUncertain, !originalRetiredStageIdentityUncertain,
              originalAuxiliaryActiveFD == nil, originalAuxiliaryUncertainFDs.isEmpty,
              originalAuxiliaryEnumerationFD == nil, originalAuxiliaryDirectoryStream == nil,
              !originalAuxiliaryUncertainStreamClose,
              originalRecoveryUncertainPolicyDescriptors.isEmpty,
              coldActiveFD == nil, coldUncertainFDs.isEmpty,
              !coldEffectUncertain, !coldRosterInFlight,
              coldEnumerationFD == nil, coldDirectoryStream == nil,
              !coldUncertainStreamClose else { throw EraseIntentStoreError.invalidAuthority }
        try originalCanonicalSourceIO.requireSettled() // actual tracked writer/read ownership
        try originalRecoveryCheckedIO?.requireSettled()
    }

    @MainActor
    private func originalCanonicalLateProjection(operation: EraseRouterOperationV1)
        throws -> OriginalCanonicalLateProjectionV1 {
        try requireOriginalCanonicalMemoryLifetime()
        guard originalAuxiliaryPublicationStarted,
              let roster = originalAuxiliaryPublishedReceipt,
              roster.store === self, roster.operation === operation, roster.checkedSettled,
              originalAuxiliaryTemporaryDisposition != nil,
              let root = originalAuxiliaryProjectedRoot,
              let intentBytes = originalAuxiliaryProjectedIntentBytes,
              let intentFact = originalAuxiliaryProjectedIntentFact,
              (!originalRetiredCommitmentStarted || originalRetiredCommitmentReceipt != nil),
              (!originalRetiredStageIdentityStarted || originalRetiredStageIdentityReceipt != nil) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var leaves = [
            OriginalCanonicalExpectedLeafV1(name: Self.intentName,
                bytes: intentBytes, fact: intentFact, maximum: Self.maximumJournalBytes),
            OriginalCanonicalExpectedLeafV1(name: Self.preparationName,
                bytes: roster.preparationBytes, fact: roster.preparationFact,
                maximum: Self.maximumJournalBytes),
            OriginalCanonicalExpectedLeafV1(name: Self.auxiliaryRosterName,
                bytes: roster.canonicalBytes, fact: roster.recordFact,
                maximum: Self.maximumJournalBytes)
        ]
        if let commitment = originalRetiredCommitmentReceipt {
            guard commitment.store === self, commitment.operation === operation,
                  commitment.checkedSettled else { throw EraseIntentStoreError.invalidAuthority }
            leaves.append(OriginalCanonicalExpectedLeafV1(
                name: Self.originalRetiredCommitmentName, bytes: commitment.canonicalBytes,
                fact: commitment.recordFact, maximum: Self.maximumJournalBytes * 3))
        }
        if let stage = originalRetiredStageIdentityReceipt {
            guard stage.store === self, stage.operation === operation, stage.checkedSettled,
                  stage.commitment === originalRetiredCommitmentReceipt else {
                throw EraseIntentStoreError.invalidAuthority
            }
            leaves.append(OriginalCanonicalExpectedLeafV1(
                name: Self.originalRetiredStageIdentityName, bytes: stage.canonicalBytes,
                fact: stage.recordFact, maximum: Self.maximumJournalBytes * 3))
        }
        for leaf in leaves {
            guard !leaf.bytes.isEmpty, leaf.bytes.count <= leaf.maximum,
                  leaf.fact.size == off_t(leaf.bytes.count),
                  leaf.fact.mode & S_IFMT == S_IFREG, leaf.fact.links == 1 else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        return OriginalCanonicalLateProjectionV1(operation: operation,
            roster: roster, commitment: originalRetiredCommitmentReceipt,
            stage: originalRetiredStageIdentityReceipt, root: root, leaves: leaves)
    }

    @MainActor
    func observeOriginalCanonicalControls(scope: EraseOriginalCanonicalControlReadScopeV1)
        throws -> EraseOriginalCanonicalControlReadbackV1 {
        try scope.requireHeld(store: self) // pure real owner/G association, BEFORE numeric IO
        guard originalCanonicalReadIO == nil else { throw EraseIntentStoreError.invalidAuthority }
        let projection = try originalCanonicalLateProjection(operation: scope.operation)
        guard try decode(projection.leaves[0].bytes) == scope.expectedIntent,
              try decodePreparation(projection.leaves[1].bytes) == scope.expectedPreparation,
              scope.expectedPreparation.matches(scope.expectedIntent) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let io = OriginalCanonicalCheckedIOV1()
        originalCanonicalReadIO = io // retain actual attempt BEFORE first acquisition
        let eraseRootURL = applicationSupportURL.appendingPathComponent(
            Self.directoryName, isDirectory: true)
        func bound() throws {
            try scope.requireHeld(store: self)
            try self.requireOriginalCanonicalMemoryLifetime()
            guard self.originalCanonicalReadIO === io,
                  self.originalAuxiliaryPublishedReceipt === projection.roster,
                  self.originalRetiredCommitmentReceipt === projection.commitment,
                  self.originalRetiredStageIdentityReceipt === projection.stage,
                  self.originalAuxiliaryProjectedRoot == projection.root,
                  self.originalAuxiliaryProjectedIntentFact == projection.leaves[0].fact else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try io.requireNoUncertainty()
        }
        func syscall(_ operation: () -> Int32) throws {
            try bound()
            let result = operation(); let failure = errno
            try bound()
            guard result == 0 else { _ = failure; throw EraseIntentStoreError.invalidAuthority }
        }
        func roots() throws -> EraseColdControlLeafFactV1 {
            var support = stat(), supportNamed = stat(), erase = stat(), eraseNamed = stat()
            try syscall { Darwin.fstat(self.applicationSupportDescriptor, &support) }
            try syscall { Darwin.lstat(self.applicationSupportURL.path, &supportNamed) }
            try syscall { Darwin.fstat(self.eraseDescriptor, &erase) }
            try syscall { Darwin.fstatat(self.applicationSupportDescriptor,
                Self.directoryName, &eraseNamed, AT_SYMLINK_NOFOLLOW) }
            let supportFact = EraseColdControlLeafFactV1(support)
            guard support.st_mode & S_IFMT == S_IFDIR,
                  support.st_dev == self.applicationSupportIdentity.device,
                  support.st_ino == self.applicationSupportIdentity.inode,
                  supportFact == EraseColdControlLeafFactV1(supportNamed),
                  erase.st_mode & S_IFMT == S_IFDIR,
                  erase.st_dev == self.eraseIdentity.device,
                  erase.st_ino == self.eraseIdentity.inode,
                  EraseColdControlLeafFactV1(erase) == projection.root,
                  EraseColdControlLeafFactV1(eraseNamed) == projection.root else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return supportFact
        }
        func leafFact(_ leaf: OriginalCanonicalExpectedLeafV1, descriptor: Int32) throws {
            var held = stat(), named = stat()
            try syscall { Darwin.fstat(descriptor, &held) }
            try syscall { Darwin.fstatat(self.eraseDescriptor, leaf.name,
                &named, AT_SYMLINK_NOFOLLOW) }
            guard EraseColdControlLeafFactV1(held) == leaf.fact,
                  EraseColdControlLeafFactV1(named) == leaf.fact else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        func policy(_ kind: OwnedFileKindV1, at url: URL,
                    fact: EraseColdControlLeafFactV1) throws -> TemporalPolicyObservationV1 {
            try bound()
            let observed = try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(
                kind, at: url,
                retainUncertainDescriptor: { io.retainUncertainDescriptor($0) })
            try bound()
            guard observed.device == UInt64(fact.device), observed.inode == UInt64(fact.inode),
                  observed.mode == UInt16(fact.mode), observed.linkCount == UInt64(fact.links) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return observed // raw pending remains DATA, no setter/disposition
        }
        do {
            let support = try roots()
            let names = try io.names(parent: eraseDescriptor, expected: projection.names, boundary: bound)
            guard try roots() == support else { throw EraseIntentStoreError.invalidAuthority }
            let rootPolicy = try policy(.stagingDirectory, at: eraseRootURL, fact: projection.root)
            var held: [(OriginalCanonicalExpectedLeafV1, Int32,
                EraseOriginalCanonicalControlReadbackV1.LeafV1)] = []
            var buffer = [UInt8](repeating: 0, count: 16 * 1024)
            for leaf in projection.leaves {
                try bound()
                let descriptor = try io.openAt(eraseDescriptor, name: leaf.name,
                    flags: O_RDONLY | O_NONBLOCK)
                try bound(); try leafFact(leaf, descriptor: descriptor)
                let beforePolicy = try policy(.journal, at: eraseRootURL.appendingPathComponent(leaf.name), fact: leaf.fact)
                try leafFact(leaf, descriptor: descriptor)
                var offset = 0
                var calls = 0
                let (maximumCalls, overflow) = leaf.bytes.count.addingReportingOverflow(1)
                guard !overflow else { throw EraseIntentStoreError.invalidAuthority }
                while true {
                    try bound(); try leafFact(leaf, descriptor: descriptor)
                    guard calls < maximumCalls else { throw EraseIntentStoreError.invalidAuthority }
                    calls += 1
                    let requested = offset == leaf.bytes.count ? 1 : min(buffer.count, leaf.bytes.count - offset)
                    let count = buffer.withUnsafeMutableBytes {
                        Darwin.read(descriptor, $0.baseAddress, requested)
                    }
                    let failure = errno // no callback can overwrite actual read errno
                    try bound(); try leafFact(leaf, descriptor: descriptor)
                    guard count >= 0 else { _ = failure; throw EraseIntentStoreError.invalidAuthority }
                    if count == 0 {
                        guard offset == leaf.bytes.count else { throw EraseIntentStoreError.invalidAuthority }
                        break
                    }
                    guard count <= leaf.bytes.count - offset else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    let equal = leaf.bytes.withUnsafeBytes { expected in
                        buffer.withUnsafeBytes { actual in
                            memcmp(expected.baseAddress!.advanced(by: offset), actual.baseAddress!, count) == 0
                        }
                    }
                    guard equal else { throw EraseIntentStoreError.invalidAuthority }
                    offset += count
                }
                try leafFact(leaf, descriptor: descriptor)
                let afterPolicy = try policy(.journal, at: eraseRootURL.appendingPathComponent(leaf.name), fact: leaf.fact)
                guard beforePolicy == afterPolicy else { throw EraseIntentStoreError.invalidAuthority }
                try leafFact(leaf, descriptor: descriptor)
                held.append((leaf, descriptor, .init(canonicalBytes: leaf.bytes,
                    fact: leaf.fact, policy: afterPolicy)))
            }
            guard try io.names(parent: eraseDescriptor, expected: projection.names, boundary: bound) == names,
                  try roots() == support,
                  try policy(.stagingDirectory, at: eraseRootURL, fact: projection.root) == rootPolicy else {
                throw EraseIntentStoreError.invalidAuthority
            }
            for (leaf, descriptor, _) in held {
                try leafFact(leaf, descriptor: descriptor)
                try bound(); try io.closeOwnedOnce(descriptor); try bound()
                var named = stat()
                try syscall { Darwin.fstatat(self.eraseDescriptor, leaf.name, &named, AT_SYMLINK_NOFOLLOW) }
                guard EraseColdControlLeafFactV1(named) == leaf.fact else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            guard try roots() == support else { throw EraseIntentStoreError.invalidAuthority }
            try io.requireSettled(); try bound()
            let result = EraseOriginalCanonicalControlReadbackV1(store: self,
                supportFact: support, eraseRootFact: projection.root,
                eraseRootPolicy: rootPolicy, names: names, intent: held[0].2,
                preparation: held[1].2,
                otherCanonicalControls: held.dropFirst(2).map { .init(name: $0.0.name, leaf: $0.2) })
            originalCanonicalReadIO = nil
            return result
        } catch {
            let failure = error
            originalCanonicalReadFailed = true
            do { try io.finishOwnedOnce() } catch { io.poison() }
            Self.retainCanonicalIO(io) // owns terminal uncertainty; no deinit retry
            originalCanonicalReadIO = io
            throw failure
        }
    }

    func load() throws -> EraseIntentV1? {
        try AssetLocatorEraseIntentEnrollmentV1.validate()
        try verifyAuthority()
        try verifyExistingPolicy(.journal, name: Self.intentName)
        if borrowsColdObservation {
            // A retained, physically exact interrupted next leaf is opaque
            // until the same operation acquires EX/G and proves a P/R cut.
            // Reading canonical P or R here does not admit that temporary as
            // an expected phase or authorize any effect.
            return try readIfPresent(Self.intentName).map { try decode($0.data) }
        }
        try verifyExistingPolicy(.journalTemporary, name: Self.nextName)
        let canonical = try readIfPresent(Self.intentName)
        let pending = try readIfPresent(Self.nextName)

        switch (canonical, pending) {
        case (nil, nil):
            return nil
        case (nil, let pending?):
            let value = try decode(pending.data)
            guard value.phase == .emptyGenerationPrepared else {
                throw EraseIntentStoreError.invalidIntent
            }
            return try withOriginalCanonicalSourceEffect(name: Self.intentName,
                expectedBytes: nil, replacementBytes: pending.data) {
                markOriginalCanonicalEffectEntry()
                guard Darwin.renameatx_np(
                        eraseDescriptor,
                        Self.nextName,
                        eraseDescriptor,
                        Self.intentName,
                        UInt32(RENAME_EXCL)
                      ) == 0,
                      Darwin.fsync(eraseDescriptor) == 0 else {
                    throw EraseIntentStoreError.invalidIntent
                }
                try verifyPublishedPolicy(
                    .journal,
                    name: Self.intentName,
                    failure: .invalidIntent,
                    expectedIdentity: pending.identity
                )
                guard let promoted = try readIfPresent(Self.intentName),
                      promoted.identity == pending.identity,
                      promoted.data == pending.data else {
                    throw EraseIntentStoreError.invalidIntent
                }
                try verifyAuthority()
                return value
            }
        case (let canonical?, nil):
            return try decode(canonical.data)
        case (let canonical?, let pending?):
            let current = try decode(canonical.data)
            let next = try decode(pending.data)
            guard sameOperation(current, next),
                  next.phase == nextPhase(after: current.phase)
                    || current.phase == nextPhase(after: next.phase) else {
                throw EraseIntentStoreError.invalidIntent
            }
            try removeExact(Self.nextName, expected: pending)
            return current
        }
    }

    func loadPreparation() throws -> ErasePreparationV2? {
        try verifyAuthority()
        try verifyExistingPolicy(.journal, name: Self.preparationName)
        try verifyExistingPolicy(
            .journalTemporary,
            name: Self.preparationNextName
        )
        if borrowsColdObservation {
            guard try readIfPresent(Self.preparationNextName) == nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return try readIfPresent(Self.preparationName).map {
                try decodePreparation($0.data)
            }
        }
        let canonical = try readIfPresent(Self.preparationName)
        let pending = try readIfPresent(Self.preparationNextName)

        switch (canonical, pending) {
        case (nil, nil):
            return nil
        case (nil, let pending?):
            let value = try decodePreparation(pending.data)
            return try withOriginalCanonicalSourceEffect(name: Self.preparationName,
                expectedBytes: nil, replacementBytes: pending.data) {
                markOriginalCanonicalEffectEntry()
                guard Darwin.renameatx_np(
                    eraseDescriptor,
                    Self.preparationNextName,
                    eraseDescriptor,
                    Self.preparationName,
                    UInt32(RENAME_EXCL)
                ) == 0,
                      Darwin.fsync(eraseDescriptor) == 0 else {
                    throw EraseIntentStoreError.invalidPreparation
                }
                try verifyPublishedPolicy(
                    .journal,
                    name: Self.preparationName,
                    failure: .invalidPreparation,
                    expectedIdentity: pending.identity
                )
                guard let promoted = try readIfPresent(Self.preparationName),
                      promoted.identity == pending.identity,
                      promoted.data == pending.data else {
                    throw EraseIntentStoreError.invalidPreparation
                }
                try verifyAuthority()
                return value
            }
        case (let canonical?, nil):
            return try decodePreparation(canonical.data)
        case (let canonical?, let pending?):
            let current = try decodePreparation(canonical.data)
            let next = try decodePreparation(pending.data)
            guard isPreparationTransition(current, next)
                    || isPreparationTransition(next, current) else {
                throw EraseIntentStoreError.invalidPreparation
            }
            try removeExact(Self.preparationNextName, expected: pending)
            return current
        }
    }

    func createPreparation(_ value: ErasePreparationV2) throws {
        let registry = try GenerationLeaseRegistryV1(applicationSupportURL: applicationSupportURL)
        try registry.withNoMigrationReservation { try createPreparationWithoutMigrationReservation(value) }
    }

    private func createPreparationWithoutMigrationReservation(_ value: ErasePreparationV2) throws {
        // Cold continuation consumes an already durable preparation. It never
        // creates a new original-Erase authority from a startup observation.
        guard !borrowsColdObservation else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try verifyAuthority()
        try verifyExistingPolicy(.journal, name: Self.preparationName)
        try verifyExistingPolicy(
            .journalTemporary,
            name: Self.preparationNextName
        )
        guard try readIfPresent(Self.preparationName) == nil,
              try readIfPresent(Self.preparationNextName) == nil else {
            throw EraseIntentStoreError.preparationAlreadyExists
        }
        let data = try encodePreparation(value)
        try withOriginalCanonicalSourceEffect(name: Self.preparationName,
            expectedBytes: nil, replacementBytes: data) {
            let temporaryIdentity = try createLeaf(
                Self.preparationNextName,
                data: data
            )
            var published = false
            do {
                markOriginalCanonicalEffectEntry()
                guard Darwin.renameatx_np(
                    eraseDescriptor,
                    Self.preparationNextName,
                    eraseDescriptor,
                    Self.preparationName,
                    UInt32(RENAME_EXCL)
                ) == 0 else {
                    throw EraseIntentStoreError.writeFailed
                }
                published = true
                guard Darwin.fsync(eraseDescriptor) == 0 else {
                    throw EraseIntentStoreError.writeFailed
                }
                try verifyPublishedPolicy(
                    .journal,
                    name: Self.preparationName,
                    failure: .writeFailed,
                    expectedIdentity: temporaryIdentity
                )
                guard let written = try readIfPresent(Self.preparationName),
                      written.identity == temporaryIdentity,
                      written.data == data else {
                    throw EraseIntentStoreError.writeFailed
                }
                try verifyAuthority()
            } catch {
                if published {
                    try? removeExact(
                        Self.preparationName,
                        expected: (data: data, identity: temporaryIdentity)
                    )
                }
                throw error
            }        }

    }

    func replacePreparation(
        expected: ErasePreparationV2,
        with replacement: ErasePreparationV2
    ) throws {
        let registry = try GenerationLeaseRegistryV1(applicationSupportURL: applicationSupportURL)
        try registry.withNoMigrationReservation {
            try replacePreparationWithoutMigrationReservation(expected: expected, with: replacement)
        }
    }

    private func replacePreparationWithoutMigrationReservation(
        expected: ErasePreparationV2, with replacement: ErasePreparationV2
    ) throws {
        try verifyAuthority()
        try verifyExistingPolicy(.journal, name: Self.preparationName)
        try verifyExistingPolicy(
            .journalTemporary,
            name: Self.preparationNextName
        )
        let expectedData = try encodePreparation(expected)
        let replacementData = try encodePreparation(replacement)
        guard isPreparationTransition(expected, replacement),
              let current = try readIfPresent(Self.preparationName),
              current.data == expectedData,
              try readIfPresent(Self.preparationNextName) == nil else {
            throw EraseIntentStoreError.preparationMismatch
        }
        if borrowsColdObservation {
            guard let coldExpectedPreparationFact,
                  coldExpectedPreparationBytes == expectedData else {
                throw EraseIntentStoreError.invalidAuthority
            }
            coldDisplacedBytes = expectedData
            coldDisplacedFact = coldExpectedPreparationFact
        }
        try withOriginalCanonicalSourceEffect(name: Self.preparationName,
            expectedBytes: expectedData, replacementBytes: replacementData) {
            let replacementIdentity = try createLeaf(
                Self.preparationNextName,
                data: replacementData
            )
            var swapped = false
            do {
                markOriginalCanonicalEffectEntry()
                guard Darwin.renameatx_np(
                    eraseDescriptor,
                    Self.preparationNextName,
                    eraseDescriptor,
                    Self.preparationName,
                    UInt32(RENAME_SWAP)
                ) == 0 else {
                    throw EraseIntentStoreError.writeFailed
                }
                swapped = true
                guard Darwin.fsync(eraseDescriptor) == 0 else {
                    throw EraseIntentStoreError.writeFailed
                }
                if borrowsColdObservation {
                    coldOwnPublishingName = Self.preparationName
                    coldOwnPublishedIdentity = replacementIdentity
                    coldPublishedVerified = false
                    coldExpectedPreparationBytes = replacementData
                }
                try verifyPublishedPolicy(
                    .journal,
                    name: Self.preparationName,
                    failure: .writeFailed,
                    expectedIdentity: replacementIdentity
                )
                try verifyPublishedPolicy(
                    .journalTemporary,
                    name: Self.preparationNextName,
                    failure: .writeFailed,
                    expectedIdentity: current.identity
                )
                guard let published = try readIfPresent(Self.preparationName),
                      let displaced = try readIfPresent(Self.preparationNextName),
                      published.identity == replacementIdentity,
                      published.data == replacementData,
                      displaced.identity == current.identity,
                      displaced.data == expectedData else {
                    throw EraseIntentStoreError.writeFailed
                }
                try removeExact(Self.preparationNextName, expected: displaced)
                if borrowsColdObservation {
                    coldOwnPublishingName = nil
                    coldOwnPublishedIdentity = nil
                    coldDisplacedBytes = nil
                    coldDisplacedFact = nil
                    coldPublishedVerified = false
                    coldOwnTemporaryName = nil
                    coldOwnTemporaryIdentity = nil
                    coldOwnTemporaryBytes = nil
                }
                swapped = false
                try verifyAuthority()
            } catch {
                if borrowsColdObservation {
                    // A failed or ambiguous swap is never rolled back by an
                    // ordinary pathname repair in a cold operation.
                    coldEffectUncertain = true
                    throw error
                }
                if swapped {
                    do {
                        if let published = try readIfPresent(Self.preparationName),
                           let displaced = try readIfPresent(Self.preparationNextName),
                           published.identity == replacementIdentity,
                           published.data == replacementData,
                           displaced.identity == current.identity,
                           displaced.data == expectedData {
                            _ = Darwin.renameatx_np(
                                eraseDescriptor,
                                Self.preparationNextName,
                                eraseDescriptor,
                                Self.preparationName,
                                UInt32(RENAME_SWAP)
                            )
                            _ = Darwin.fsync(eraseDescriptor)
                        }
                    } catch {
                        // Preserve uncertain state for recovery.
                    }
                }
                try? removeIfExact(
                    Self.preparationNextName,
                    expected: replacementIdentity
                )
                throw error
            }        }

    }

    func removePreparation(expected: ErasePreparationV2,
        requiredHeldIdentity: (device: UInt64, inode: UInt64)? = nil) throws {
        try verifyAuthority()
        try verifyExistingPolicy(.journal, name: Self.preparationName)
        let data = try encodePreparation(expected)
        guard let current = try readIfPresent(Self.preparationName) else {
            throw EraseIntentStoreError.preparationMissing
        }
        guard current.data == data else {
            throw EraseIntentStoreError.preparationMismatch
        }
        if let requiredHeldIdentity {
            guard UInt64(current.identity.device) == requiredHeldIdentity.device,
                  UInt64(current.identity.inode) == requiredHeldIdentity.inode else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        try removeExact(Self.preparationName, expected: current)
        try verifyAuthority()
    }

    func create(_ value: EraseIntentV1) throws {
        let registry = try GenerationLeaseRegistryV1(applicationSupportURL: applicationSupportURL)
        try registry.withNoMigrationReservation { try createWithoutMigrationReservation(value) }
    }

    private func createWithoutMigrationReservation(_ value: EraseIntentV1) throws {
        guard !borrowsColdObservation else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try AssetLocatorEraseIntentEnrollmentV1.validate()
        try verifyAuthority()
        try verifyExistingPolicy(.journal, name: Self.intentName)
        try verifyExistingPolicy(.journalTemporary, name: Self.nextName)
        guard try readIfPresent(Self.intentName) == nil,
              try readIfPresent(Self.nextName) == nil else {
            throw EraseIntentStoreError.intentAlreadyExists
        }
        let data = try encode(value)
        try withOriginalCanonicalSourceEffect(name: Self.intentName,
            expectedBytes: nil, replacementBytes: data) {
            let temporaryIdentity = try createLeaf(Self.nextName, data: data)
            var published = false
            do {
                markOriginalCanonicalEffectEntry()
                guard Darwin.renameatx_np(
                    eraseDescriptor,
                    Self.nextName,
                    eraseDescriptor,
                    Self.intentName,
                    UInt32(RENAME_EXCL)
                ) == 0 else {
                    throw EraseIntentStoreError.writeFailed
                }
                published = true
                guard Darwin.fsync(eraseDescriptor) == 0 else {
                    throw EraseIntentStoreError.writeFailed
                }
                try verifyPublishedPolicy(
                    .journal,
                    name: Self.intentName,
                    failure: .writeFailed,
                    expectedIdentity: temporaryIdentity
                )
                guard let publishedValue = try readIfPresent(Self.intentName),
                      publishedValue.identity == temporaryIdentity,
                      publishedValue.data == data else {
                    throw EraseIntentStoreError.writeFailed
                }
                try verifyAuthority()
            } catch {
                if published {
                    try? removeExact(
                        Self.intentName,
                        expected: (data: data, identity: temporaryIdentity)
                    )
                }
                throw error
            }        }

    }

    func replace(
        expected: EraseIntentV1,
        with replacement: EraseIntentV1
    ) throws {
        // An original owner with a published physical roster must project
        // every owned phase CAS through its retained operation. The generic
        // replacement has no witness for the changed Erase-root full fact.
        guard originalAuxiliaryPublishedReceipt == nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let registry = try GenerationLeaseRegistryV1(applicationSupportURL: applicationSupportURL)
        try registry.withNoMigrationReservation {
            try replaceWithoutMigrationReservation(expected: expected, with: replacement)
        }
    }

    /// The retained cold operation supplies its existing Support EX and
    /// Registry G interval. No creating Registry constructor is legal here.
    /// The same typed operation owns the borrowed Erase-root descriptors and
    /// the one-way result of this canonical phase CAS.
    @MainActor
    func requireSchema2ColdPhaseCASCut(
        expected: EraseIntentV1,
        replacement: EraseIntentV1,
        operation: EraseColdPreparationOperationV1
    ) throws -> Schema2ColdPhaseCASCutV1 {
        try operation.requireSchema2ColdIntentStore(self)
        guard borrowsColdObservation, !coldEffectUncertain,
              !coldCloseAttempted, !coldClosed,
              expected.schemaVersion == 2,
              ((expected.phase == .pointerSwitched &&
                replacement == expected.advancing(to: .sessionActivated)) ||
               (expected.phase == .emptyGenerationPrepared &&
                replacement == expected.advancing(to: .pointerSwitched))) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try verifyAuthority()
        let expectedData = try encode(expected)
        let replacementData = try encode(replacement)
        let current = try load()
        if current == expected {
            let nextIsPrefix = coldCapturedOpaqueNextBytes.map {
                replacementData.starts(with: $0)
            } ?? true
            guard coldExpectedIntentBytes == expectedData,
                  nextIsPrefix,
                  (coldCapturedOpaqueNextBytes == nil)
                    == (coldCapturedOpaqueNextFact == nil) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return .pending(nextBytes: coldCapturedOpaqueNextBytes,
                nextFact: coldCapturedOpaqueNextFact)
        }
        if current == replacement {
            guard coldExpectedIntentBytes == replacementData,
                  coldCapturedOpaqueNextBytes == nil ||
                    coldCapturedOpaqueNextBytes == expectedData,
                  (coldCapturedOpaqueNextBytes == nil)
                    == (coldCapturedOpaqueNextFact == nil) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return .published(
                displacedBytes: coldCapturedOpaqueNextBytes,
                displacedFact: coldCapturedOpaqueNextFact)
        }
        throw EraseIntentStoreError.invalidAuthority
    }

    @MainActor
    func replaceSchema2ColdPreparedPhase(expected: EraseIntentV1,
        with replacement: EraseIntentV1,
        operation: EraseColdPreparationOperationV1) throws {
        guard borrowsColdObservation, !coldEffectUncertain,
              !coldCloseAttempted, !coldClosed,
              expected.schemaVersion == 2,
              expected.phase == .emptyGenerationPrepared,
              replacement == expected.advancing(to: .pointerSwitched),
              coldCapturedOpaqueNextBytes == nil,
              coldCapturedOpaqueNextFact == nil,
              coldPointerOriginalControlCut == nil,
              coldPointerPhasePublishedControlRoot == nil,
              let preparation = try loadPreparation() else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let before = try requireSchema2ColdCanonicalControls(intent: expected,
            preparation: preparation, operation: operation)
        var entered = false
        do {
            try operation.withSchema2ColdPreparedPhaseMutation(expected: expected,
                replacement: replacement, store: self) {
                guard try self.requireSchema2ColdCanonicalControls(intent: expected,
                    preparation: preparation, operation: operation).eraseRoot == before.eraseRoot,
                      try self.requireSchema2ColdPhaseCASCut(expected: expected,
                        replacement: replacement, operation: operation)
                        == .pending(nextBytes: nil, nextFact: nil) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                entered = true
                try self.replaceWithoutMigrationReservation(expected: expected,
                    with: replacement)
                let after = try self.requireSchema2ColdCanonicalControls(intent: replacement,
                    preparation: preparation, operation: operation)
                guard after.names == before.names,
                      after.preparationBytes == before.preparationBytes,
                      after.eraseRoot.device == before.eraseRoot.device,
                      after.eraseRoot.inode == before.eraseRoot.inode,
                      after.eraseRoot.mode == before.eraseRoot.mode,
                      after.eraseRoot.user == before.eraseRoot.user,
                      after.eraseRoot.group == before.eraseRoot.group,
                      after.eraseRoot.links == before.eraseRoot.links else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
        } catch {
            if entered { coldEffectUncertain = true }
            throw error
        }
    }

    @MainActor
    func replaceSchema2ColdPointerPhase(
        expected: EraseIntentV1,
        with replacement: EraseIntentV1,
        operation: EraseColdPreparationOperationV1
    ) throws {
        guard borrowsColdObservation,
              expected.schemaVersion == 2,
              expected.phase == .pointerSwitched,
              replacement == expected.advancing(to: .sessionActivated),
              !coldEffectUncertain, !coldCloseAttempted, !coldClosed else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try operation.requireSchema2ColdIntentStore(self)
        let firstCut = try requireSchema2ColdPhaseCASCut(
            expected: expected, replacement: replacement,
            operation: operation)
        if let retained = coldPointerOriginalControlCut {
            let controls = try requireSchema2ColdCanonicalControls(
                intent: expected, preparation: retained.preparation,
                operation: operation)
            guard retained.intent == expected,
                  controls.intentBytes == retained.intentBytes,
                  controls.preparationBytes == retained.preparationBytes,
                  controls.eraseRoot == retained.eraseRoot,
                  controls.names == retained.names,
                  coldPointerPhasePublishedControlRoot == nil,
                  coldProjectedOriginalRetiredFacts.isEmpty,
                  coldVerifiedOriginalRetiredDispositions.isEmpty else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        var enteredCanonicalCAS = false
        do {
            try operation.withSchema2ColdPointerPhaseMutation(
                expected: expected, replacement: replacement, store: self) {
                guard try self.requireSchema2ColdPhaseCASCut(
                    expected: expected, replacement: replacement,
                    operation: operation) == firstCut else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                enteredCanonicalCAS = true
                switch firstCut {
                case .pending:
                    if self.coldCapturedOpaqueNextBytes != nil {
                        try self.removeCapturedOpaqueNextForColdCAS()
                    }
                    try self.replaceWithoutMigrationReservation(
                        expected: expected, with: replacement)
                case .published:
                    if self.coldCapturedOpaqueNextBytes != nil {
                        try self.removeCapturedOpaqueNextForColdCAS()
                    }
                }
                if let retained = self.coldPointerOriginalControlCut {
                    let controls = try self.requireSchema2ColdCanonicalControls(
                        intent: replacement, preparation: retained.preparation,
                        operation: operation)
                    guard controls.names == retained.names,
                          controls.preparationBytes == retained.preparationBytes,
                          controls.eraseRoot.device == retained.eraseRoot.device,
                          controls.eraseRoot.inode == retained.eraseRoot.inode,
                          controls.eraseRoot.mode == retained.eraseRoot.mode,
                          controls.eraseRoot.user == retained.eraseRoot.user,
                          controls.eraseRoot.group == retained.eraseRoot.group,
                          controls.eraseRoot.links == retained.eraseRoot.links else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    self.coldPointerPhasePublishedControlRoot = controls.eraseRoot
                }
            }
            guard try load() == replacement,
                  coldCapturedOpaqueNextBytes == nil else {
                throw EraseIntentStoreError.intentMismatch
            }
            if let retained = coldPointerOriginalControlCut {
                let controls = try requireSchema2ColdCanonicalControls(
                    intent: replacement, preparation: retained.preparation,
                    operation: operation)
                guard controls.eraseRoot == coldPointerPhasePublishedControlRoot,
                      controls.names == retained.names,
                      controls.preparationBytes == retained.preparationBytes else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
        } catch {
            // Once the canonical writer entered, a failed postproof or close
            // cannot permit a second CAS on the same borrowed owner.
            if enteredCanonicalCAS { coldEffectUncertain = true }
            throw error
        }
    }

    /// Capture the actual first R parent before target work. Later DATA
    /// reproof uses only this operation's completed temporary/roster effect.
    /// No surviving parent or control leaf becomes a replacement baseline.
    @MainActor
    func requireSchema2ColdFirstActivatedEntryControlCut(
        firstIntent: EraseIntentV1,
        preparation: ErasePreparationV2,
        operation: EraseColdPreparationOperationV1
    ) throws -> (firstRoot: EraseColdControlLeafFactV1,
                 firstNames: [String],
                 currentRoot: EraseColdControlLeafFactV1,
                 currentNames: [String],
                 phaseCut: Schema2ColdPhaseCASCutV1) {
        try operation.requireSchema2ColdIntentStore(self)
        guard borrowsColdObservation, !coldEffectUncertain,
              !coldCloseAttempted, !coldClosed,
              firstIntent.schemaVersion == 2,
              firstIntent.phase == .sessionActivated,
              preparation.matches(firstIntent),
              coldPointerOriginalControlCut == nil,
              coldCapturedOpaqueAuxiliaryRosterBytes != nil,
              !coldCapturedOpaqueAuxiliaryRosterNextPresent else {
            throw EraseIntentStoreError.invalidAuthority
        }
        if coldFirstActivatedEntryControlCut == nil {
            let (first, heldStore, _, _, _, _, _) =
                try operation.requireSchema2ColdOriginalContinuation()
            guard heldStore === self, first.intent == firstIntent,
                  first.preparation == preparation,
                  first.observed.intent == firstIntent,
                  first.observed.preparation == preparation,
                  first.observed.opaqueAuxiliaryRosterPresent,
                  !first.observed.opaqueAuxiliaryRosterNextPresent,
                  let phaseCut = first.phaseCut,
                  case .published = phaseCut,
                  operation.schema2ColdTargetValidationAttempt == nil,
                  operation.schema2ColdActivatedTargetAttempt == nil,
                  coldFirstActivatedEntrySettledCut == nil,
                  coldRosterPublication == nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let controls = try requireSchema2ColdCanonicalControls(
                intent: firstIntent, preparation: preparation,
                operation: operation)
            let flags = try coldRootFlagsMatching(controls.eraseRoot)
            guard try requireSchema2ColdPhaseCASCut(
                    expected: firstIntent.advancing(to: .pointerSwitched),
                    replacement: firstIntent, operation: operation) == phaseCut,
                  try coldRootFact() == controls.eraseRoot,
                  try coldNamesChecked() == controls.names else {
                throw EraseIntentStoreError.invalidAuthority
            }
            coldFirstActivatedEntryControlCut = .init(
                operationIdentity: ObjectIdentifier(operation),
                intent: firstIntent, preparation: preparation,
                intentBytes: controls.intentBytes,
                preparationBytes: controls.preparationBytes,
                firstRoot: controls.eraseRoot, firstNames: controls.names,
                rootFlags: flags, phaseCut: phaseCut)
        }
        guard let retained = coldFirstActivatedEntryControlCut,
              retained.operationIdentity == ObjectIdentifier(operation),
              retained.intent == firstIntent,
              retained.preparation == preparation else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var expectedRoot = retained.firstRoot
        var expectedNames = retained.firstNames
        if let settled = coldFirstActivatedEntrySettledCut {
            guard settled.operationIdentity == retained.operationIdentity,
                  settled.intentBytes == retained.intentBytes,
                  settled.preparationBytes == retained.preparationBytes,
                  settled.firstRoot == retained.firstRoot,
                  settled.firstNames == retained.firstNames,
                  settled.rootFlags == retained.rootFlags,
                  operation.hasSchema2ColdActivatedEntryTempSettled else {
                throw EraseIntentStoreError.invalidAuthority
            }
            expectedRoot = settled.settledRoot
            expectedNames = settled.settledNames
        } else {
            guard !operation.hasSchema2ColdActivatedEntryTempSettled else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        if let receipt = coldRosterPublication {
            guard coldFirstActivatedEntrySettledCut != nil,
                  receipt.store === self, receipt.operation === operation,
                  !coldRosterInFlight,
                  receipt.originalRoot == expectedRoot,
                  receipt.intentBytes == retained.intentBytes,
                  receipt.preparationBytes == retained.preparationBytes,
                  let projected = receipt.postPublishedRoot,
                  let bytes = coldOwnRosterBytes,
                  let fact = coldOwnRosterFact,
                  receipt.publishedFact == fact,
                  let leaf = try readColdLeafIfPresent(Self.rosterName,
                    maximumBytes: bytes.count), leaf.data == bytes else {
                throw EraseIntentStoreError.invalidAuthority
            }
            var named = stat()
            guard Darwin.fstatat(eraseDescriptor, Self.rosterName, &named,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  EraseColdControlLeafFactV1(named) == fact else {
                throw EraseIntentStoreError.invalidAuthority
            }
            expectedRoot = projected
            expectedNames = (expectedNames + [Self.rosterName]).sorted()
        }
        let controls = try requireSchema2ColdCanonicalControls(
            intent: firstIntent, preparation: preparation,
            operation: operation)
        guard controls.intentBytes == retained.intentBytes,
              controls.preparationBytes == retained.preparationBytes,
              controls.eraseRoot == expectedRoot,
              controls.names == expectedNames,
              try coldRootFlagsMatching(controls.eraseRoot) == retained.rootFlags,
              try coldRootFact() == controls.eraseRoot,
              try coldNamesChecked() == controls.names else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return (retained.firstRoot, retained.firstNames,
            controls.eraseRoot, controls.names, retained.phaseCut)
    }

    private func coldRootFlagsMatching(_ fact: EraseColdControlLeafFactV1)
        throws -> UInt32 {
        var held = stat(), named = stat()
        guard Darwin.fstat(eraseDescriptor, &held) == 0,
              Darwin.fstatat(applicationSupportDescriptor, Self.directoryName,
                &named, AT_SYMLINK_NOFOLLOW) == 0,
              EraseColdControlLeafFactV1(held) == fact,
              EraseColdControlLeafFactV1(named) == fact,
              held.st_flags == named.st_flags else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return held.st_flags
    }

    private func requireFirstActivatedAuxiliarySurvivor(
        root: EraseColdControlLeafFactV1, names: [String]
    ) throws {
        guard let bytes = coldCapturedOpaqueAuxiliaryRosterBytes,
              let fact = coldCapturedOpaqueAuxiliaryRosterFact,
              let policy = coldCapturedOpaqueAuxiliaryRosterPolicy,
              !coldCapturedOpaqueAuxiliaryRosterNextPresent,
              coldProjectedAuxiliaryRosterFact == nil,
              coldVerifiedAuxiliaryDisposition == nil,
              !coldObservedAuxiliaryPolicyInFlight,
              try coldRootFact() == root,
              try coldNamesChecked() == names,
              let read = try readColdLeafIfPresent(Self.auxiliaryRosterName,
                maximumBytes: Self.maximumJournalBytes), read.data == bytes else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var named = stat()
        guard Darwin.fstatat(eraseDescriptor, Self.auxiliaryRosterName, &named,
                AT_SYMLINK_NOFOLLOW) == 0,
              EraseColdControlLeafFactV1(named) == fact,
              try observeBorrowedColdPolicy(.journal,
                at: applicationSupportURL.appendingPathComponent(
                    policyRelativePath(Self.auxiliaryRosterName))) == policy,
              try coldRootFact() == root,
              try coldNamesChecked() == names else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    /// A first authenticated R entry can retain a displaced exact P leaf.
    /// It never reruns the phase CAS: the operation's checked R owner holds
    /// EX/G and permits only this captured temporary's one-way removal.
    @MainActor
    func settleSchema2ColdActivatedEntryTemporary(
        pending: EraseIntentV1,
        published: EraseIntentV1,
        operation: EraseColdPreparationOperationV1
    ) throws {
        guard borrowsColdObservation,
              pending.schemaVersion == 2,
              pending.phase == .pointerSwitched,
              published == pending.advancing(to: .sessionActivated),
              !coldEffectUncertain, !coldCloseAttempted, !coldClosed else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try operation.requireSchema2ColdIntentStore(self)
        let firstCut = try requireSchema2ColdPhaseCASCut(
            expected: pending, replacement: published,
            operation: operation)
        guard case .published = firstCut else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var entered = false
        var settledCut: Schema2ColdFirstActivatedEntrySettledCutV1?
        let retained = coldFirstActivatedEntryControlCut
        do {
            try operation.withSchema2ColdActivatedEntryTempCleanup(
                pending: pending, published: published, store: self) {
                guard try self.requireSchema2ColdPhaseCASCut(
                    expected: pending, replacement: published,
                    operation: operation) == firstCut else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                if let retained {
                    guard retained.operationIdentity == ObjectIdentifier(operation),
                          retained.intent == published,
                          retained.phaseCut == firstCut,
                          coldFirstActivatedEntrySettledCut == nil else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    let controls = try self.requireSchema2ColdCanonicalControls(
                        intent: published, preparation: retained.preparation,
                        operation: operation)
                    guard controls.intentBytes == retained.intentBytes,
                          controls.preparationBytes == retained.preparationBytes,
                          controls.eraseRoot == retained.firstRoot,
                          controls.names == retained.firstNames,
                          try self.coldRootFlagsMatching(controls.eraseRoot)
                            == retained.rootFlags else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    try self.requireFirstActivatedAuxiliarySurvivor(
                        root: controls.eraseRoot, names: controls.names)
                }
                entered = true
                if self.coldCapturedOpaqueNextBytes != nil {
                    try self.removeCapturedOpaqueNextForColdCAS()
                }
                if let retained {
                    let controls = try self.requireSchema2ColdCanonicalControls(
                        intent: published, preparation: retained.preparation,
                        operation: operation)
                    guard case .published(let displaced, let displacedFact) = firstCut,
                          (displaced == nil) == (displacedFact == nil),
                          retained.firstNames.contains(Self.nextName)
                            == (displaced != nil),
                          controls.intentBytes == retained.intentBytes,
                          controls.preparationBytes == retained.preparationBytes,
                          controls.names == retained.firstNames.filter({
                            $0 != Self.nextName }),
                          controls.eraseRoot.device == retained.firstRoot.device,
                          controls.eraseRoot.inode == retained.firstRoot.inode,
                          controls.eraseRoot.mode == retained.firstRoot.mode,
                          controls.eraseRoot.user == retained.firstRoot.user,
                          controls.eraseRoot.group == retained.firstRoot.group,
                          (displaced == nil ||
                            (retained.firstRoot.links ==
                                nlink_t(2 + retained.firstNames.count) &&
                             controls.eraseRoot.links ==
                                nlink_t(2 + controls.names.count)) ||
                            (retained.firstRoot.links == 2 &&
                             controls.eraseRoot.links == 2)),
                          try self.coldRootFlagsMatching(controls.eraseRoot)
                            == retained.rootFlags,
                          displaced != nil || controls.eraseRoot == retained.firstRoot else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    try self.requireFirstActivatedAuxiliarySurvivor(
                        root: controls.eraseRoot, names: controls.names)
                    settledCut = .init(
                        operationIdentity: retained.operationIdentity,
                        intentBytes: controls.intentBytes,
                        preparationBytes: controls.preparationBytes,
                        firstRoot: retained.firstRoot, firstNames: retained.firstNames,
                        settledRoot: controls.eraseRoot, settledNames: controls.names,
                        rootFlags: retained.rootFlags)
                }
            }
            guard try load() == published,
                  coldCapturedOpaqueNextBytes == nil else {
                throw EraseIntentStoreError.intentMismatch
            }
            if let retained {
                guard let settledCut,
                      operation.hasSchema2ColdActivatedEntryTempSettled,
                      settledCut.firstRoot == retained.firstRoot,
                      settledCut.firstNames == retained.firstNames else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                let controls = try requireSchema2ColdCanonicalControls(
                    intent: published, preparation: retained.preparation,
                    operation: operation)
                guard controls.intentBytes == settledCut.intentBytes,
                      controls.preparationBytes == settledCut.preparationBytes,
                      controls.eraseRoot == settledCut.settledRoot,
                      controls.names == settledCut.settledNames,
                      try coldRootFlagsMatching(controls.eraseRoot) == settledCut.rootFlags else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                try requireFirstActivatedAuxiliarySurvivor(
                    root: controls.eraseRoot, names: controls.names)
                coldFirstActivatedEntrySettledCut = settledCut
            }
        } catch {
            if entered { coldEffectUncertain = true }
            throw error
        }
    }

    /// Remove only the exact old interrupted leaf after the Router has
    /// rechecked this cut under the same physical EX and Registry G. A
    /// pending Simulator shape receives its own checked complete request on
    /// this exact held/named leaf before unlink; the request cannot rebase
    /// bytes, inode or metadata. No pathname-only cleanup is used.
    private func removeCapturedOpaqueNextForColdCAS() throws {
        guard borrowsColdObservation,
              let expected = coldCapturedOpaqueNextBytes,
              let fact = coldCapturedOpaqueNextFact,
              coldActiveFD == nil, coldUncertainFDs.isEmpty else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try requireCapturedOpaqueNextNoRepair()
        let url = applicationSupportURL.appendingPathComponent(
            policyRelativePath(Self.nextName))
        try ProtectedFilePolicyV1.verifyEraseColdTemporalPolicyWithCheckedRequest(
            .journalTemporary, at: url,
            retainUncertainDescriptor: { uncertain in
                self.coldUncertainFDs.append(uncertain)
            }, unchangedWitness: {
                try self.requireCapturedOpaqueNextNoRepair()
                return fact
            })
        try requireCapturedOpaqueNextNoRepair()
        let fd = Darwin.openat(eraseDescriptor, Self.nextName,
            O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
        guard fd >= 0 else { throw EraseIntentStoreError.invalidAuthority }
        coldActiveFD = fd
        do {
            var held = stat(), named = stat()
            guard Darwin.fstat(fd, &held) == 0,
                  Darwin.fstatat(eraseDescriptor, Self.nextName,
                      &named, AT_SYMLINK_NOFOLLOW) == 0,
                  EraseColdControlLeafFactV1(held) == fact,
                  EraseColdControlLeafFactV1(named) == fact,
                  Darwin.lseek(fd, 0, SEEK_SET) == 0 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            var bytes = Data()
            var buffer = [UInt8](repeating: 0, count: 16 * 1024)
            while true {
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.read(fd, $0.baseAddress, $0.count)
                }
                if count > 0 { bytes.append(contentsOf: buffer.prefix(count)) }
                else if count == 0 { break }
                else if errno != EINTR {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            guard bytes == expected,
                  Darwin.fstat(fd, &held) == 0,
                  Darwin.fstatat(eraseDescriptor, Self.nextName,
                      &named, AT_SYMLINK_NOFOLLOW) == 0,
                  EraseColdControlLeafFactV1(held) == fact,
                  EraseColdControlLeafFactV1(named) == fact,
                  Darwin.unlinkat(eraseDescriptor, Self.nextName, 0) == 0,
                  Darwin.fsync(eraseDescriptor) == 0 else {
                throw EraseIntentStoreError.writeFailed
            }
            var absent = stat()
            guard Darwin.fstat(fd, &held) == 0,
                  held.st_dev == fact.device,
                  held.st_ino == fact.inode,
                  held.st_nlink == 0,
                  Darwin.fstatat(eraseDescriptor, Self.nextName,
                      &absent, AT_SYMLINK_NOFOLLOW) != 0,
                  errno == ENOENT else {
                throw EraseIntentStoreError.writeFailed
            }
            try closeColdActiveChecked()
            coldCapturedOpaqueNextBytes = nil
            coldCapturedOpaqueNextFact = nil
        } catch {
            let failure = error
            if coldActiveFD != nil { try closeColdActiveChecked() }
            coldEffectUncertain = true
            throw failure
        }
    }

    /// The V949 original ticket already owns its Registry G and Support EX.
    /// Reuse the incumbent exact phase CAS without constructing a second
    /// Registry or admitting a producer between sealed-source proof and effect.
    @MainActor
    func replaceForOriginalRecoveryFirstEffect(
        expected: EraseIntentV1,
        with replacement: EraseIntentV1,
        permit: OriginalEraseRecoveryFirstEffectPermitV1,
        support: StoreTemporalPhysicalRootExclusionV1,
        firstObservation: OriginalRecoveryObservation
    ) throws -> OriginalRecoveryFirstPointerCASReceiptV1 {
        guard let originalRecoveryCheckedIO,
              expected.schemaVersion == 2,
              expected.phase == .emptyGenerationPrepared,
              firstObservation.intent == expected,
              replacement == expected.advancing(to: .pointerSwitched) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try permit.requireHeld()
        let retain: (Int32) -> Void = { [self] in
            retainOriginalRecoveryUncertainDescriptor($0)
        }
        let before = try Self.observeOriginalRecoveryNoCreate(
            support: support, applicationSupportURL: applicationSupportURL,
            io: originalRecoveryCheckedIO,
            retainUncertainDescriptor: retain)
        guard before == firstObservation else {
            throw EraseIntentStoreError.invalidAuthority
        }
        // The following concrete Store effect creates the reserved temp,
        // swaps it with the canonical intent, fsyncs the held Erase parent,
        // verifies both leaves, removes the displaced temp, and reproves
        // authority. Only its exact completed postimage may project the
        // Erase parent's size/mtime/ctime.
        try replaceWithoutMigrationReservation(
            expected: expected, with: replacement)
        try permit.requireHeld()
        let after = try Self.observeOriginalRecoveryNoCreate(
            support: support, applicationSupportURL: applicationSupportURL,
            io: originalRecoveryCheckedIO,
            retainUncertainDescriptor: retain)
        guard after.intent == replacement,
              after.sameOwnedFirstCASNonIntentNamespace(as: before),
              after.eraseNames == before.eraseNames else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try originalRecoveryCheckedIO.requireSettled()
        return OriginalRecoveryFirstPointerCASReceiptV1(
            store: self, before: before, after: after)
    }

    /// Fixed Erase completion boundary after the original registry namespace
    /// has been retired. The actual support EX and exact operation proof take
    /// the place of creating a new registry; canonical CAS remains unchanged.
    @MainActor
    func replaceAfterRegistryRetirement(
        expected: EraseIntentV1,
        with replacement: EraseIntentV1,
        retirement: ErasedRegistryRetirementProofV1
    ) throws {
        try requireRetirementRoot(retirement)
        try retirement.requireCleanupPhaseWrite(expected: expected, replacement: replacement)
        try replaceWithoutMigrationReservation(expected: expected, with: replacement)
        try requireRetirementRoot(retirement)
        try retirement.requireCleanupPhaseWrite(expected: expected, replacement: replacement)
    }

    private func replaceWithoutMigrationReservation(
        expected: EraseIntentV1, with replacement: EraseIntentV1
    ) throws {
#if DEBUG
        if originalAuxiliaryPhaseTracingForTesting {
            print("ORIGINAL_AUX_PHASE_V1 stage=generic-authority-enter")
        }
#endif
        try verifyAuthority()
#if DEBUG
        if originalAuxiliaryPhaseTracingForTesting {
            print("ORIGINAL_AUX_PHASE_V1 stage=generic-authority-complete")
        }
#endif
        try verifyExistingPolicy(.journal, name: Self.intentName)
#if DEBUG
        if originalAuxiliaryPhaseTracingForTesting {
            print("ORIGINAL_AUX_PHASE_V1 stage=generic-intent-policy-complete")
        }
#endif
        try verifyExistingPolicy(.journalTemporary, name: Self.nextName)
#if DEBUG
        if originalAuxiliaryPhaseTracingForTesting {
            print("ORIGINAL_AUX_PHASE_V1 stage=generic-temp-policy-complete")
        }
#endif
        let expectedData = try encode(expected)
        let replacementData = try encode(replacement)
        guard sameOperation(expected, replacement),
              replacement.phase == nextPhase(after: expected.phase),
              let current = try readIfPresent(Self.intentName),
              current.data == expectedData,
              try readIfPresent(Self.nextName) == nil else {
            throw EraseIntentStoreError.intentMismatch
        }
#if DEBUG
        if originalAuxiliaryPhaseTracingForTesting {
            print("ORIGINAL_AUX_PHASE_V1 stage=generic-preimage-complete")
        }
#endif
        if borrowsColdObservation {
            guard let coldExpectedIntentFact,
                  coldExpectedIntentBytes == expectedData else {
                throw EraseIntentStoreError.invalidAuthority
            }
            coldDisplacedBytes = expectedData
            coldDisplacedFact = coldExpectedIntentFact
        }
        try withOriginalCanonicalSourceEffect(name: Self.intentName,
            expectedBytes: expectedData, replacementBytes: replacementData) {
            let replacementIdentity = try createLeaf(
                Self.nextName,
                data: replacementData
            )
    #if DEBUG
            if originalAuxiliaryPhaseTracingForTesting {
                print("ORIGINAL_AUX_PHASE_V1 stage=generic-temp-written")
            }
    #endif
            var swapped = false
            do {
                markOriginalCanonicalEffectEntry()
                guard Darwin.renameatx_np(
                    eraseDescriptor,
                    Self.nextName,
                    eraseDescriptor,
                    Self.intentName,
                    UInt32(RENAME_SWAP)
                ) == 0 else {
                    throw EraseIntentStoreError.writeFailed
                }
                swapped = true
    #if DEBUG
                if originalAuxiliaryPhaseTracingForTesting {
                    print("ORIGINAL_AUX_PHASE_V1 stage=generic-swapped")
                }
    #endif
                guard Darwin.fsync(eraseDescriptor) == 0 else {
                    throw EraseIntentStoreError.writeFailed
                }
    #if DEBUG
                if originalAuxiliaryPhaseTracingForTesting {
                    print("ORIGINAL_AUX_PHASE_V1 stage=generic-parent-synced")
                }
    #endif
                if borrowsColdObservation {
                    coldOwnPublishingName = Self.intentName
                    coldOwnPublishedIdentity = replacementIdentity
                    coldPublishedVerified = false
                    coldExpectedIntentBytes = replacementData
                }
                try verifyPublishedPolicy(
                    .journal,
                    name: Self.intentName,
                    failure: .writeFailed,
                    expectedIdentity: replacementIdentity
                )
                try verifyPublishedPolicy(
                    .journalTemporary,
                    name: Self.nextName,
                    failure: .writeFailed,
                    expectedIdentity: current.identity
                )
                guard
                      let published = try readIfPresent(Self.intentName),
                      let displaced = try readIfPresent(Self.nextName),
                      published.identity == replacementIdentity,
                      published.data == replacementData,
                      displaced.identity == current.identity,
                      displaced.data == expectedData else {
                    throw EraseIntentStoreError.writeFailed
                }
                try removeExact(Self.nextName, expected: displaced)
    #if DEBUG
                if originalAuxiliaryPhaseTracingForTesting {
                    print("ORIGINAL_AUX_PHASE_V1 stage=generic-displaced-removed")
                }
    #endif
                if borrowsColdObservation {
                    coldOwnPublishingName = nil
                    coldOwnPublishedIdentity = nil
                    coldDisplacedBytes = nil
                    coldDisplacedFact = nil
                    coldPublishedVerified = false
                    coldOwnTemporaryName = nil
                    coldOwnTemporaryIdentity = nil
                    coldOwnTemporaryBytes = nil
                }
                swapped = false
                try verifyAuthority()
    #if DEBUG
                if originalAuxiliaryPhaseTracingForTesting {
                    print("ORIGINAL_AUX_PHASE_V1 stage=generic-complete")
                }
    #endif
            } catch {
                if borrowsColdObservation {
                    coldEffectUncertain = true
                    throw error
                }
                if swapped {
                    do {
                        if let published = try readIfPresent(Self.intentName),
                           let displaced = try readIfPresent(Self.nextName),
                           published.identity == replacementIdentity,
                           published.data == replacementData,
                           displaced.identity == current.identity,
                           displaced.data == expectedData {
                            _ = Darwin.renameatx_np(
                                eraseDescriptor,
                                Self.nextName,
                                eraseDescriptor,
                                Self.intentName,
                                UInt32(RENAME_SWAP)
                            )
                            _ = Darwin.fsync(eraseDescriptor)
                        }
                    } catch {
                        // Preserve the exact failure and leave uncertain state for recovery.
                    }
                }
                try? removeIfExact(
                    Self.nextName,
                    expected: replacementIdentity
                )
                throw error
            }        }

    }

    func remove(expected: EraseIntentV1) throws {
        try verifyAuthority()
        try verifyExistingPolicy(.journal, name: Self.intentName)
        let data = try encode(expected)
        guard let current = try readIfPresent(Self.intentName) else {
            throw EraseIntentStoreError.intentMissing
        }
        guard current.data == data else {
            throw EraseIntentStoreError.intentMismatch
        }
        try removeExact(Self.intentName, expected: current)
        try verifyAuthority()
    }
}

private extension EraseIntentStore {
    func coldRootFact() throws -> EraseColdControlLeafFactV1 {
        guard borrowsColdObservation,
              !coldCloseAttempted, !coldClosed,
              coldActiveFD == nil, coldUncertainFDs.isEmpty else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var held = stat(), named = stat()
        guard Darwin.fstat(eraseDescriptor, &held) == 0,
              Darwin.fstatat(applicationSupportDescriptor,
                Self.directoryName, &named,
                AT_SYMLINK_NOFOLLOW) == 0,
              held.st_mode & S_IFMT == S_IFDIR,
              EraseColdControlLeafFactV1(held)
                == EraseColdControlLeafFactV1(named) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return EraseColdControlLeafFactV1(held)
    }

    func policyRelativePath(_ name: String) -> String {
        "\(Self.directoryName)/\(name)"
    }

    func observeBorrowedColdPolicy(_ kind: OwnedFileKindV1,
        at url: URL) throws -> TemporalPolicyObservationV1 {
        guard borrowsColdObservation, !coldCloseAttempted, !coldClosed,
              coldUncertainFDs.isEmpty, !coldEffectUncertain else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(
            kind, at: url, retainUncertainDescriptor: { descriptor in
                // A failed close is terminal; never retry the numeric FD.
                self.coldUncertainFDs.append(descriptor)
            })
    }

    func verifyExistingPolicy(
        _ kind: OwnedFileKindV1,
        name: String
    ) throws {
        do {
            try verifyAuthority()
            if let originalRecoveryCheckedIO {
                var named = stat()
                if Darwin.fstatat(eraseDescriptor, name, &named,
                                  AT_SYMLINK_NOFOLLOW) != 0 {
                    guard errno == ENOENT else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    return
                }
                try originalRecoveryCheckedIO.withOpen(parent: eraseDescriptor,
                    name: name, flags: O_RDONLY | O_NONBLOCK) { descriptor in
                    let expected = try Self.fileIdentity(descriptor)
                    let url = applicationSupportURL
                        .appendingPathComponent(Self.directoryName, isDirectory: true)
                        .appendingPathComponent(name)
                    _ = try ProtectedFilePolicyV1
                        .verifyEraseColdTemporalPolicyWithCheckedRequest(
                            kind, at: url,
                            retainUncertainDescriptor: { [self] in
                                retainOriginalRecoveryUncertainDescriptor($0)
                            },
                            unchangedWitness: {
                                try self.originalRecoveryPolicyWitness(
                                    name: name, descriptor: descriptor,
                                    expected: expected)
                            })
                }
                try verifyAuthority()
                return
            }
            if borrowsColdObservation {
                guard (kind == .journal &&
                    [Self.intentName, Self.preparationName].contains(name)) ||
                    (kind == .journalTemporary &&
                    [Self.nextName, Self.preparationNextName].contains(name)) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                // Cold observation may never repair an existing policy or
                // use the ordinary unchecked-close descriptor path.
                _ = try readColdLeafIfPresent(name)
                return
            }
            do {
                try originalCanonicalSourceIO.withOpen(parent: eraseDescriptor,
                    name: name, flags: O_RDONLY) { descriptor in
                    let expected = try Self.fileIdentity(descriptor)
                    try applyOriginalCanonicalPolicy(
                        kind, at: applicationSupportURL
                            .appendingPathComponent(Self.directoryName, isDirectory: true)
                            .appendingPathComponent(name),
                        authorityCheck: {
                            try self.verifyAuthority()
                            try self.verifyLeaf(name, descriptor: descriptor, expected: expected)
                        })
                }
            } catch EraseIntentStoreError.intentMismatch { return }

        } catch {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    /// Tracks an actual normal Store policy request, rather than treating a
    /// settled validation/decode refusal as a failed writer. Called only with
    /// this Store's already retained descriptor/constructor source ownership.
    func markOriginalCanonicalEffectEntry() {
        if !borrowsColdObservation && originalRecoveryCheckedIO == nil {
            originalCanonicalSourceIO.markEffectEntry()
        }
    }

    func withOriginalCanonicalSourceEffect<Value>(name: String,
        expectedBytes: Data?, replacementBytes: Data?, _ body: () throws -> Value)
        throws -> Value {
        if borrowsColdObservation || originalRecoveryCheckedIO != nil {
            return try body()
        }
        return try originalCanonicalSourceIO.withEffect(name: name,
            expectedBytes: expectedBytes, replacementBytes: replacementBytes, body)
    }

    func applyOriginalCanonicalPolicy(_ kind: OwnedFileKindV1, at url: URL,
        authorityCheck: @escaping () throws -> Void) throws {
        try authorityCheck()
        var supportBefore = stat(), eraseBefore = stat()
        guard Darwin.fstat(applicationSupportDescriptor, &supportBefore) == 0,
              Darwin.fstat(eraseDescriptor, &eraseBefore) == 0 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        // The former relative-path policy helper pinned Support/Erase/leaf
        // device, inode and link count. Keep that same parent relationship
        // using this Store's retained parents, without unchecked helper pins.
        func guardedAuthority() throws {
            try authorityCheck()
            var support = stat(), erase = stat()
            guard Darwin.fstat(applicationSupportDescriptor, &support) == 0,
                  Darwin.fstat(eraseDescriptor, &erase) == 0,
                  support.st_dev == supportBefore.st_dev,
                  support.st_ino == supportBefore.st_ino,
                  support.st_nlink == supportBefore.st_nlink,
                  erase.st_dev == eraseBefore.st_dev,
                  erase.st_ino == eraseBefore.st_ino,
                  erase.st_nlink == eraseBefore.st_nlink else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        var effectStarted = false
        do {
            _ = try ProtectedFilePolicyV1.applyAndVerifyEraseColdPrivateWithCheckedClose(
                kind, at: url,
                retainUncertainDescriptor: { self.originalCanonicalSourceIO.retainUncertainDescriptor($0) },
                authorityCheck: guardedAuthority,
                beforeFirstEffect: { try guardedAuthority(); effectStarted = true })
        } catch {
            if effectStarted { originalCanonicalSourceIO.poison() }
            throw error
        }
    }

    func applyTemporaryPolicy(
        _ kind: OwnedFileKindV1,
        name: String,
        descriptor: Int32
    ) throws {
        do {
            let expected = try Self.fileIdentity(descriptor)
            if borrowsColdObservation {
                guard kind == .journalTemporary,
                      [Self.nextName, Self.preparationNextName,
                       Self.rosterNextName, Self.auxiliaryRosterNextName].contains(name),
                      coldOwnTemporaryName == name,
                      coldActiveFD == descriptor else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                let url = applicationSupportURL
                    .appendingPathComponent(Self.directoryName,
                        isDirectory: true)
                    .appendingPathComponent(name)
                try ProtectedFilePolicyV1
                    .applyAndVerifyEraseColdPrivateWithCheckedClose(
                        kind, at: url,
                        retainUncertainDescriptor: { uncertain in
                            // Never retry a failed close by numeric FD. The
                            // operation retains this Store and refuses later
                            // mutation or publication when this is nonempty.
                            self.coldUncertainFDs.append(uncertain)
                        },
                        authorityCheck: {
                            try self.requireColdActiveTemporary(
                                name: name, descriptor: descriptor,
                                expected: expected)
                        }, beforeFirstEffect: {
                            try self.requireColdActiveTemporary(
                                name: name, descriptor: descriptor,
                                expected: expected)
                        })
                return
            }
            try applyOriginalCanonicalPolicy(
                kind, at: applicationSupportURL
                    .appendingPathComponent(Self.directoryName, isDirectory: true)
                    .appendingPathComponent(name),
                authorityCheck: {
                    try self.verifyAuthority()
                    try self.verifyLeaf(name, descriptor: descriptor, expected: expected)
                })

        } catch {
            throw EraseIntentStoreError.writeFailed
        }
    }

    /// A newly O_EXCL-created cold temporary has an active writable FD, so
    /// the ordinary settled-store guard intentionally cannot run here. This
    /// check binds the sole operation-owned FD and named leaf before and after
    /// each policy effect without accepting a fresh descriptor as authority.
    private func requireColdActiveTemporary(
        name: String, descriptor: Int32, expected: Identity
    ) throws {
        guard borrowsColdObservation, !coldCloseAttempted, !coldClosed,
              !coldEffectUncertain, coldOwnTemporaryName == name,
              coldActiveFD == descriptor, coldUncertainFDs.isEmpty,
              coldEnumerationFD == nil, coldDirectoryStream == nil,
              !coldUncertainStreamClose else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try Self.requireDirectory(applicationSupportDescriptor,
            identity: applicationSupportIdentity)
        try Self.requireDirectory(eraseDescriptor,
            identity: eraseIdentity)
        var namedSupport = stat(), namedErase = stat()
        guard Darwin.lstat(applicationSupportURL.path,
                &namedSupport) == 0,
              namedSupport.st_mode & S_IFMT == S_IFDIR,
              Identity(device: namedSupport.st_dev,
                  inode: namedSupport.st_ino)
                == applicationSupportIdentity,
              Darwin.fstatat(applicationSupportDescriptor,
                  Self.directoryName, &namedErase,
                  AT_SYMLINK_NOFOLLOW) == 0,
              namedErase.st_mode & S_IFMT == S_IFDIR,
              Identity(device: namedErase.st_dev,
                  inode: namedErase.st_ino) == eraseIdentity else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try verifyLeaf(name, descriptor: descriptor, expected: expected)
    }

    private func verifyLeaf(
        _ name: String,
        descriptor: Int32,
        expected: Identity
    ) throws {
        guard try Self.fileIdentity(descriptor) == expected else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var info = stat()
        guard Darwin.fstatat(
            eraseDescriptor,
            name,
            &info,
            AT_SYMLINK_NOFOLLOW
        ) == 0,
              (info.st_mode & S_IFMT) == S_IFREG,
              info.st_nlink == 1,
              Identity(device: info.st_dev, inode: info.st_ino) == expected else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    private func verifyPublishedPolicy(
        _ kind: OwnedFileKindV1,
        name: String,
        failure: EraseIntentStoreError,
        expectedIdentity: Identity
    ) throws {
        if let originalRecoveryCheckedIO {
            do {
                try originalRecoveryCheckedIO.withOpen(
                    parent: eraseDescriptor, name: name,
                    flags: O_RDONLY | O_NONBLOCK) { descriptor in
                    let url = applicationSupportURL
                        .appendingPathComponent(Self.directoryName, isDirectory: true)
                        .appendingPathComponent(name)
                    _ = try ProtectedFilePolicyV1
                        .verifyEraseColdTemporalPolicyWithCheckedRequest(
                            kind, at: url,
                            retainUncertainDescriptor: { [self] in
                                retainOriginalRecoveryUncertainDescriptor($0)
                            },
                            unchangedWitness: {
                                try self.originalRecoveryPolicyWitness(
                                    name: name, descriptor: descriptor,
                                    expected: expectedIdentity)
                            })
                }
                try verifyAuthority()
                return
            } catch { throw failure }
        }
        if borrowsColdObservation {
            do {
                guard let published = try readColdLeafIfPresent(name),
                      published.identity == expectedIdentity else {
                    throw failure
                }
                return
            } catch { throw failure }
        }
        var policyEffectStarted = false
        do {
            try originalCanonicalSourceIO.withOpen(parent: eraseDescriptor,
                name: name, flags: O_RDONLY) { descriptor in
                try verifyAuthority()
                try verifyLeaf(name, descriptor: descriptor, expected: expectedIdentity)
                _ = try ProtectedFilePolicyV1.verifyEraseColdPrivateWithCheckedClose(
                    kind, at: applicationSupportURL
                        .appendingPathComponent(Self.directoryName, isDirectory: true)
                        .appendingPathComponent(name),
                    retainUncertainDescriptor: { self.originalCanonicalSourceIO.retainUncertainDescriptor($0) },
                    beforeCompleteProtectionRequest: {
                        try self.verifyAuthority()
                        try self.verifyLeaf(name, descriptor: descriptor, expected: expectedIdentity)
                        policyEffectStarted = true
                    })
                try verifyAuthority()
                try verifyLeaf(name, descriptor: descriptor, expected: expectedIdentity)
            }
        } catch {
            if policyEffectStarted { originalCanonicalSourceIO.poison() }
            throw failure
        }
    }

    private func originalRecoveryPolicyWitness(
        name: String, descriptor: Int32, expected: Identity
    ) throws -> OriginalRecoveryPolicyWitness {
        try verifyAuthority()
        try verifyLeaf(name, descriptor: descriptor, expected: expected)
        var held = stat(), named = stat()
        guard Darwin.fstat(descriptor, &held) == 0,
              Darwin.fstatat(eraseDescriptor, name, &named,
                             AT_SYMLINK_NOFOLLOW) == 0,
              RetirementLeafFact(held) == RetirementLeafFact(named),
              let readback = try readIfPresent(name),
              readback.identity == expected,
              let originalRecoveryCheckedIO else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return OriginalRecoveryPolicyWitness(
            fact: RetirementLeafFact(held), bytes: readback.data,
            names: try originalRecoveryCheckedIO.names(in: eraseDescriptor))
    }

    func verifyAuthority() throws {
        guard !originalAuxiliaryRetirementFailed,
              !originalRecoveryCloseAttempted, !coldCloseAttempted, !coldClosed,
              (!originalAuxiliaryPublicationStarted ||
                originalAuxiliaryPublishedReceipt != nil),
              !originalAuxiliaryPublicationUncertain,
              (!originalRetiredCommitmentStarted ||
                originalRetiredCommitmentReceipt != nil),
              !originalRetiredCommitmentUncertain,
              (!originalRetiredStageIdentityStarted ||
                originalRetiredStageIdentityReceipt != nil),
              !originalRetiredStageIdentityUncertain,
              originalAuxiliaryActiveFD == nil,
              originalAuxiliaryUncertainFDs.isEmpty,
              originalAuxiliaryEnumerationFD == nil,
              originalAuxiliaryDirectoryStream == nil,
              !originalAuxiliaryUncertainStreamClose,
              coldActiveFD == nil, coldUncertainFDs.isEmpty,
              !coldEffectUncertain, !coldRosterInFlight,
              coldEnumerationFD == nil,
              coldDirectoryStream == nil, !coldUncertainStreamClose else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try originalCanonicalSourceIO.requireNoUncertainty()
        guard !originalCanonicalReadFailed, originalCanonicalReadIO == nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try Self.requireDirectory(
            applicationSupportDescriptor,
            identity: applicationSupportIdentity
        )
        try Self.requireDirectory(eraseDescriptor, identity: eraseIdentity)
        if let originalRecoveryCheckedIO {
            guard originalRecoveryUncertainPolicyDescriptors.isEmpty else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try originalRecoveryCheckedIO.requireSettled()
            var named = stat()
            guard Darwin.fstatat(applicationSupportDescriptor,
                      Self.directoryName, &named, AT_SYMLINK_NOFOLLOW) == 0,
                  (named.st_mode & S_IFMT) == S_IFDIR,
                  named.st_dev == eraseIdentity.device,
                  named.st_ino == eraseIdentity.inode else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return
        }
        if borrowsColdObservation {
            var support = stat(), erase = stat(), heldBefore = stat()
            guard Darwin.lstat(applicationSupportURL.path, &support) == 0,
                  support.st_mode & S_IFMT == S_IFDIR,
                  support.st_dev == applicationSupportIdentity.device,
                  support.st_ino == applicationSupportIdentity.inode,
                  Darwin.fstat(eraseDescriptor, &heldBefore) == 0,
                  Darwin.fstatat(applicationSupportDescriptor,
                      Self.directoryName, &erase, AT_SYMLINK_NOFOLLOW) == 0,
                  erase.st_mode & S_IFMT == S_IFDIR,
                  erase.st_dev == eraseIdentity.device,
                  erase.st_ino == eraseIdentity.inode,
                  EraseColdControlLeafFactV1(erase)
                    == EraseColdControlLeafFactV1(heldBefore) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let names = try coldNamesChecked()
            var heldAfter = stat(), namedAfter = stat()
            guard Darwin.fstat(eraseDescriptor, &heldAfter) == 0,
                  Darwin.fstatat(applicationSupportDescriptor,
                      Self.directoryName, &namedAfter,
                      AT_SYMLINK_NOFOLLOW) == 0,
                  EraseColdControlLeafFactV1(heldBefore)
                    == EraseColdControlLeafFactV1(heldAfter),
                  EraseColdControlLeafFactV1(heldAfter)
                    == EraseColdControlLeafFactV1(namedAfter) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            guard names.allSatisfy({
                $0 == Self.intentName || $0 == Self.preparationName ||
                    $0 == coldOwnTemporaryName ||
                    ($0 == Self.rosterName &&
                        (coldOwnRosterFact != nil ||
                            coldCapturedOpaqueRosterPresent)) ||
                    ($0 == Self.rosterNextName &&
                        coldCapturedOpaqueRosterNextPresent &&
                        !coldObservedRosterTempSettled) ||
                    ($0 == Self.auxiliaryRosterName &&
                        (coldAuxiliaryOriginBytes != nil ||
                         coldOwnPublishingName == Self.auxiliaryRosterName)) ||
                    ($0 == Self.originalRetiredCommitmentName &&
                        coldCapturedOpaqueOriginalRetired[$0] != nil) ||
                    ($0 == Self.originalRetiredCommitmentNextName &&
                        coldCapturedOpaqueOriginalRetired[$0] != nil) ||
                    ($0 == Self.originalRetiredStageIdentityName &&
                        coldCapturedOpaqueOriginalRetired[$0] != nil) ||
                    ($0 == Self.originalRetiredStageIdentityNextName &&
                        coldCapturedOpaqueOriginalRetired[$0] != nil) ||
                    ($0 == Self.auxiliaryRosterNextName &&
                        coldCapturedOpaqueAuxiliaryRosterNextPresent) ||
                    ($0 == Self.nextName &&
                        coldCapturedOpaqueNextBytes != nil)
            }) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            if let coldOwnRosterFact {
                var roster = stat()
                guard names.contains(Self.rosterName),
                      Darwin.fstatat(eraseDescriptor,
                        Self.rosterName, &roster,
                        AT_SYMLINK_NOFOLLOW) == 0,
                      EraseColdControlLeafFactV1(roster)
                        == coldOwnRosterFact,
                      roster.st_mode & S_IFMT == S_IFREG,
                      roster.st_nlink == 1 else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            try requireCapturedOpaqueNextNoRepair()
            return
        }
        let reopenedApp = try originalCanonicalSourceIO.openPath(
            applicationSupportURL.path, flags: O_RDONLY | O_DIRECTORY)
        do {
            guard try Self.directoryIdentity(reopenedApp) == applicationSupportIdentity else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try originalCanonicalSourceIO.withOpen(parent: reopenedApp,
                name: Self.directoryName, flags: O_RDONLY | O_DIRECTORY) { reopenedErase in
                guard try Self.directoryIdentity(reopenedErase) == eraseIdentity else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            try originalCanonicalSourceIO.closeOwnedOnce(reopenedApp)
        } catch {
            let failure = error
            try originalCanonicalSourceIO.closeIfOwnedOnce(reopenedApp)
            throw failure
        }
    }

    func encode(_ value: EraseIntentV1) throws -> Data {
        do { return try EraseIntentCodecV1.encode(value) }
        catch { throw EraseIntentStoreError.invalidIntent }
    }

    func decode(_ data: Data) throws -> EraseIntentV1 {
        do { return try EraseIntentCodecV1.decode(data) }
        catch { throw EraseIntentStoreError.invalidIntent }
    }

    func encodePreparation(_ value: ErasePreparationV2) throws -> Data {
        do { return try ErasePreparationCodecV2.encode(value) }
        catch { throw EraseIntentStoreError.invalidPreparation }
    }

    func decodePreparation(_ data: Data) throws -> ErasePreparationV2 {
        do { return try ErasePreparationCodecV2.decode(data) }
        catch { throw EraseIntentStoreError.invalidPreparation }
    }

    func isPreparationTransition(
        _ current: ErasePreparationV2,
        _ next: ErasePreparationV2
    ) -> Bool {
        current.oldPointer == next.oldPointer
            && current.sourceLedger == next.sourceLedger
            && current.targetGenerationID == next.targetGenerationID
            && current.targetWorkspaceID == next.targetWorkspaceID
            && current.targetReplicaID == next.targetReplicaID
            && current.targetPointer == nil
            && next.targetPointer != nil
    }

    func sameOperation(_ lhs: EraseIntentV1, _ rhs: EraseIntentV1) -> Bool {
        lhs.auxiliaryRoots == rhs.auxiliaryRoots
            && lhs.eraseID == rhs.eraseID
            && lhs.generationIDsToDelete == rhs.generationIDsToDelete
            && lhs.newGenerationID == rhs.newGenerationID
            && lhs.oldGenerationID == rhs.oldGenerationID
            && lhs.oldPointer == rhs.oldPointer
            && lhs.schemaVersion == rhs.schemaVersion
            && lhs.sourceLedger == rhs.sourceLedger
            && lhs.targetEmptyProof == rhs.targetEmptyProof
            && lhs.targetPointer == rhs.targetPointer
    }

    func nextPhase(after phase: EraseIntentPhaseV1) -> EraseIntentPhaseV1? {
        switch phase {
        case .emptyGenerationPrepared: .pointerSwitched
        case .pointerSwitched: .sessionActivated
        case .sessionActivated: .cleanupComplete
        case .cleanupComplete: nil
        }
    }

    private func readIfPresent(
        _ name: String
    ) throws -> (data: Data, identity: Identity)? {
        if let originalRecoveryCheckedIO {
            var named = stat()
            if Darwin.fstatat(eraseDescriptor, name, &named,
                              AT_SYMLINK_NOFOLLOW) != 0 {
                guard errno == ENOENT else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                return nil
            }
            return try originalRecoveryCheckedIO.withOpen(
                parent: eraseDescriptor, name: name,
                flags: O_RDONLY | O_NONBLOCK) { descriptor in
                var before = stat(), after = stat(), namedAfter = stat()
                guard Darwin.fstat(descriptor, &before) == 0,
                      before.st_mode & S_IFMT == S_IFREG,
                      before.st_nlink == 1, before.st_size >= 0,
                      before.st_size <= 1_048_576,
                      before.st_dev == named.st_dev,
                      before.st_ino == named.st_ino else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                var data = Data()
                var buffer = [UInt8](repeating: 0, count: 16 * 1024)
                while true {
                    let count = buffer.withUnsafeMutableBytes {
                        Darwin.read(descriptor, $0.baseAddress, $0.count)
                    }
                    if count > 0 {
                        guard data.count <= 1_048_576 - count else {
                            throw EraseIntentStoreError.invalidAuthority
                        }
                        data.append(contentsOf: buffer.prefix(count))
                    } else if count == 0 { break }
                    else if errno != EINTR {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                }
                guard Darwin.fstat(descriptor, &after) == 0,
                      Darwin.fstatat(eraseDescriptor, name, &namedAfter,
                                     AT_SYMLINK_NOFOLLOW) == 0,
                      RetirementLeafFact(before) == RetirementLeafFact(after),
                      RetirementLeafFact(before) == RetirementLeafFact(namedAfter),
                      data.count == Int(before.st_size) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                return (data, Identity(device: before.st_dev,
                                       inode: before.st_ino))
            }
        }
        if borrowsColdObservation {
            return try readColdLeafIfPresent(name)
        }
        do {
            return try originalCanonicalSourceIO.withOpen(parent: eraseDescriptor,
                name: name, flags: O_RDONLY) { descriptor in
            var before = stat()
            guard Darwin.fstat(descriptor, &before) == 0,
                  (before.st_mode & S_IFMT) == S_IFREG,
                  before.st_nlink == 1 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            var data = Data()
            var buffer = [UInt8](repeating: 0, count: 16 * 1024)
            while true {
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.read(descriptor, $0.baseAddress, $0.count)
                }
                if count > 0 {
                    data.append(contentsOf: buffer.prefix(count))
                    guard data.count <= Self.maximumJournalBytes else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                } else if count == 0 {
                    break
                } else if errno != EINTR {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            var after = stat()
            guard Darwin.fstat(descriptor, &after) == 0,
                  before.st_dev == after.st_dev,
                  before.st_ino == after.st_ino,
                  before.st_size == after.st_size,
                  data.count == Int(after.st_size) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return (
                data,
                Identity(device: after.st_dev, inode: after.st_ino)
            )
            }
        } catch EraseIntentStoreError.intentMismatch { return nil }
    }

    private func closeColdActiveChecked() throws {
        guard let descriptor = coldActiveFD else {
            throw EraseIntentStoreError.invalidAuthority
        }
        coldActiveFD = nil
        if Darwin.close(descriptor) != 0 {
            coldUncertainFDs.append(descriptor)
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    private func coldNamesChecked() throws -> [String] {
        guard borrowsColdObservation, coldEnumerationFD == nil,
              coldDirectoryStream == nil, !coldUncertainStreamClose,
              coldUncertainFDs.isEmpty else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let duplicate = Darwin.openat(eraseDescriptor, ".",
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
        guard duplicate >= 0 else { throw EraseIntentStoreError.invalidAuthority }
        coldEnumerationFD = duplicate
        guard let stream = Darwin.fdopendir(duplicate) else {
            coldEnumerationFD = nil
            if Darwin.close(duplicate) != 0 {
                coldUncertainFDs.append(duplicate)
            }
            throw EraseIntentStoreError.invalidAuthority
        }
        coldEnumerationFD = nil
        coldDirectoryStream = stream
        var names: [String] = []
        errno = 0
        while let entry = Darwin.readdir(stream) {
            guard let name = OwnedStorageDirectoryEntryNameV1.decode(entry) else {
                coldDirectoryStream = nil
                if Darwin.closedir(stream) != 0 {
                    coldUncertainStreamClose = true
                }
                throw EraseIntentStoreError.invalidAuthority
            }
            if name != "." && name != ".." { names.append(name) }
            errno = 0
        }
        let readErrno = errno
        coldDirectoryStream = nil
        guard Darwin.closedir(stream) == 0 else {
            coldUncertainStreamClose = true
            throw EraseIntentStoreError.invalidAuthority
        }
        guard readErrno == 0 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return names.sorted()
    }

    /// The original next leaf is observed byte-for-byte and inode-for-inode,
    /// including an empty/prefix write. It is never decoded or accepted as
    /// the replacement phase by this reader. The typed EX/G replay owns that
    /// later decision and must consume this same captured fact.
    private func requireCapturedOpaqueNextNoRepair() throws {
        guard borrowsColdObservation, coldActiveFD == nil,
              coldUncertainFDs.isEmpty, !coldEffectUncertain else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let name = Self.nextName
        guard let expectedBytes = coldCapturedOpaqueNextBytes else {
            var missing = stat()
            if coldOwnTemporaryName != name {
                guard Darwin.fstatat(eraseDescriptor, name, &missing,
                    AT_SYMLINK_NOFOLLOW) != 0, errno == ENOENT else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            return
        }
        guard coldOwnTemporaryName == nil,
              let expectedFact = coldCapturedOpaqueNextFact else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let fd = Darwin.openat(eraseDescriptor, name,
            O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
        guard fd >= 0 else { throw EraseIntentStoreError.invalidAuthority }
        coldActiveFD = fd
        do {
            var held = stat(), named = stat()
            guard Darwin.fstat(fd, &held) == 0,
                  Darwin.fstatat(eraseDescriptor, name, &named,
                      AT_SYMLINK_NOFOLLOW) == 0,
                  held.st_mode & S_IFMT == S_IFREG,
                  held.st_nlink == 1,
                  EraseColdControlLeafFactV1(held) == expectedFact,
                  EraseColdControlLeafFactV1(named) == expectedFact,
                  Darwin.lseek(fd, 0, SEEK_SET) == 0 else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let url = applicationSupportURL.appendingPathComponent(
                policyRelativePath(name))
            let beforePolicy = try observeBorrowedColdPolicy(
                .journalTemporary, at: url)
            guard beforePolicy.device == UInt64(held.st_dev),
                  beforePolicy.inode == UInt64(held.st_ino) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            var data = Data()
            var buffer = [UInt8](repeating: 0, count: 16 * 1024)
            while true {
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.read(fd, $0.baseAddress, $0.count)
                }
                if count > 0 {
                    data.append(contentsOf: buffer.prefix(count))
                    guard data.count <= Self.maximumJournalBytes else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                } else if count == 0 { break }
                else if errno != EINTR {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            var after = stat(), afterNamed = stat()
            let afterPolicy = try observeBorrowedColdPolicy(
                .journalTemporary, at: url)
            guard data == expectedBytes,
                  Darwin.fstat(fd, &after) == 0,
                  Darwin.fstatat(eraseDescriptor, name,
                      &afterNamed, AT_SYMLINK_NOFOLLOW) == 0,
                  EraseColdControlLeafFactV1(after) == expectedFact,
                  EraseColdControlLeafFactV1(afterNamed) == expectedFact,
                  afterPolicy == beforePolicy else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try closeColdActiveChecked()
        } catch {
            let failure = error
            if coldActiveFD != nil { try closeColdActiveChecked() }
            throw failure
        }
    }

    private func requireColdActiveLeafUnchanged(
        name: String, descriptor: Int32,
        fact: EraseColdControlLeafFactV1, bytes: Data
    ) throws {
        guard borrowsColdObservation, coldActiveFD == descriptor,
              coldUncertainFDs.isEmpty, !coldEffectUncertain,
              bytes.count == Int(fact.size) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try Self.requireDirectory(applicationSupportDescriptor,
            identity: applicationSupportIdentity)
        try Self.requireDirectory(eraseDescriptor,
            identity: eraseIdentity)
        var namedSupport = stat(), namedErase = stat()
        guard Darwin.lstat(applicationSupportURL.path,
                &namedSupport) == 0,
              namedSupport.st_mode & S_IFMT == S_IFDIR,
              Identity(device: namedSupport.st_dev,
                  inode: namedSupport.st_ino)
                == applicationSupportIdentity,
              Darwin.fstatat(applicationSupportDescriptor,
                  Self.directoryName, &namedErase,
                  AT_SYMLINK_NOFOLLOW) == 0,
              namedErase.st_mode & S_IFMT == S_IFDIR,
              Identity(device: namedErase.st_dev,
                  inode: namedErase.st_ino) == eraseIdentity else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var held = stat(), named = stat()
        guard Darwin.fstat(descriptor, &held) == 0,
              Darwin.fstatat(eraseDescriptor, name, &named,
                  AT_SYMLINK_NOFOLLOW) == 0,
              EraseColdControlLeafFactV1(held) == fact,
              EraseColdControlLeafFactV1(named) == fact,
              Darwin.lseek(descriptor, 0, SEEK_SET) == 0 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var reread = Data()
        var buffer = [UInt8](repeating: 0, count: 16 * 1024)
        while true {
            let count = buffer.withUnsafeMutableBytes {
                Darwin.read(descriptor, $0.baseAddress, $0.count)
            }
            if count > 0 { reread.append(contentsOf: buffer.prefix(count)) }
            else if count == 0 { break }
            else if errno != EINTR {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        guard reread == bytes,
              Darwin.fstat(descriptor, &held) == 0,
              Darwin.fstatat(eraseDescriptor, name, &named,
                  AT_SYMLINK_NOFOLLOW) == 0,
              EraseColdControlLeafFactV1(held) == fact,
              EraseColdControlLeafFactV1(named) == fact else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    private func readColdLeafIfPresent(_ name: String,
        maximumBytes: Int = EraseIntentStore.maximumJournalBytes)
        throws -> (data: Data, identity: Identity)? {
        guard !coldCloseAttempted, !coldClosed,
              coldActiveFD == nil, coldUncertainFDs.isEmpty,
              !coldEffectUncertain,
              [Self.intentName, Self.nextName,
               Self.preparationName, Self.preparationNextName,
               Self.rosterName, Self.rosterNextName,
               Self.auxiliaryRosterName,
               Self.originalRetiredCommitmentName,
               Self.originalRetiredStageIdentityName].contains(name),
              maximumBytes > 0 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        if name == Self.rosterName || name == Self.rosterNextName {
            guard coldRosterPublication != nil,
                  coldRosterInFlight || coldOwnRosterFact != nil else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
        let descriptor = Darwin.openat(eraseDescriptor, name,
            O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
        if descriptor < 0, errno == ENOENT {
            if name == Self.intentName &&
                (coldExpectedIntentBytes != nil || coldExpectedIntentFact != nil) {
                throw EraseIntentStoreError.invalidAuthority
            }
            if name == Self.preparationName &&
                (coldExpectedPreparationBytes != nil || coldExpectedPreparationFact != nil) {
                throw EraseIntentStoreError.invalidAuthority
            }
            return nil
        }
        guard descriptor >= 0 else { throw EraseIntentStoreError.invalidAuthority }
        coldActiveFD = descriptor
        do {
            var before = stat()
            guard Darwin.fstat(descriptor, &before) == 0,
                  before.st_mode & S_IFMT == S_IFREG,
                  before.st_nlink == 1,
                  before.st_size >= 0,
                  before.st_size <= off_t(maximumBytes) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let beforeFact = EraseColdControlLeafFactV1(before)
            let kind: OwnedFileKindV1 =
                [Self.nextName, Self.preparationNextName,
                 Self.rosterNextName, Self.auxiliaryRosterNextName].contains(name)
                    ? .journalTemporary : .journal
            let policyURL = applicationSupportURL.appendingPathComponent(
                policyRelativePath(name))
            let beforePolicy = try observeBorrowedColdPolicy(kind,
                at: policyURL)
            guard beforePolicy.device == UInt64(before.st_dev),
                  beforePolicy.inode == UInt64(before.st_ino) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            var data = Data()
            var buffer = [UInt8](repeating: 0, count: 16 * 1024)
            while true {
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.read(descriptor, $0.baseAddress, $0.count)
                }
                if count > 0 {
                    data.append(contentsOf: buffer.prefix(count))
                    guard data.count <= maximumBytes else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                } else if count == 0 { break }
                else if errno != EINTR {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            var after = stat(), named = stat()
            guard Darwin.fstat(descriptor, &after) == 0,
                  EraseColdControlLeafFactV1(after) == beforeFact,
                  data.count == Int(after.st_size),
                  Darwin.fstatat(eraseDescriptor, name,
                      &named, AT_SYMLINK_NOFOLLOW) == 0,
                  EraseColdControlLeafFactV1(named) == beforeFact else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let ownUnpublishedTemporary =
                name == coldOwnTemporaryName &&
                    coldOwnPublishingName == nil &&
                    coldOwnTemporaryIdentity
                        == Identity(device: after.st_dev,
                            inode: after.st_ino) &&
                    coldOwnTemporaryBytes == data
            let ownPublishedCanonical =
                name == coldOwnPublishingName &&
                    coldOwnPublishedIdentity
                        == Identity(device: after.st_dev,
                            inode: after.st_ino) &&
                    ((name == Self.intentName &&
                        coldExpectedIntentBytes == data) ||
                     (name == Self.preparationName &&
                        coldExpectedPreparationBytes == data) ||
                     (name == Self.rosterName &&
                        coldOwnRosterBytes == data) ||
                     (name == Self.auxiliaryRosterName &&
                        coldOwnPreparedAuxiliaryBytes == data))
            // The original owner's record is first-captured opaque data.
            // A pending policy cannot authorize an effect here; only the
            // decoded, operation-bound checked request below can promote it.
            let opaqueOriginalAuxiliary =
                name == Self.auxiliaryRosterName &&
                coldAuxiliaryOriginBytes == data &&
                (beforeFact == (coldProjectedAuxiliaryRosterFact ??
                    coldAuxiliaryOriginFact) ||
                    (coldObservedAuxiliaryPolicyInFlight &&
                        coldAuxiliaryOriginFact.map {
                            beforeFact.device == $0.device &&
                            beforeFact.inode == $0.inode &&
                            beforeFact.mode == $0.mode &&
                            beforeFact.user == $0.user &&
                            beforeFact.group == $0.group &&
                            beforeFact.links == $0.links &&
                            beforeFact.size == $0.size &&
                            beforeFact.modifiedSeconds
                                == $0.modifiedSeconds &&
                            beforeFact.modifiedNanoseconds
                                == $0.modifiedNanoseconds
                        } == true))
            var prospectiveDisposition:
                ProtectedFileVerificationDispositionV1?
            if beforePolicy.state == .pendingSimulatorRequest {
                guard ownUnpublishedTemporary ||
                        ownPublishedCanonical ||
                        (opaqueOriginalAuxiliary &&
                            beforePolicy ==
                                coldAuxiliaryOriginPolicy) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                if !opaqueOriginalAuxiliary {
                    prospectiveDisposition = try ProtectedFilePolicyV1
                    .verifyEraseColdTemporalPolicyWithCheckedRequest(
                        kind, at: policyURL,
                        retainUncertainDescriptor: { uncertain in
                            self.coldUncertainFDs.append(uncertain)
                        }, unchangedWitness: {
                            try self.requireColdActiveLeafUnchanged(
                                name: name, descriptor: descriptor,
                                fact: beforeFact, bytes: data)
                            return beforeFact
                        })
                }
            }
            let afterPolicy = try observeBorrowedColdPolicy(kind,
                at: policyURL)
            guard afterPolicy.device == UInt64(after.st_dev),
                  afterPolicy.inode == UInt64(after.st_ino),
                  afterPolicy.state == .strictComplete ||
                    (afterPolicy.state == .pendingSimulatorRequest &&
                     (prospectiveDisposition
                        == .simulatorFileProtectionUnsupported ||
                      (opaqueOriginalAuxiliary &&
                        afterPolicy == beforePolicy))),
                  Darwin.fstat(descriptor, &after) == 0,
                  Darwin.fstatat(eraseDescriptor, name,
                      &named, AT_SYMLINK_NOFOLLOW) == 0,
                  EraseColdControlLeafFactV1(after) == beforeFact,
                  EraseColdControlLeafFactV1(named) == beforeFact else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let expectedFact = name == Self.intentName
                ? coldExpectedIntentFact : name == Self.preparationName
                    ? coldExpectedPreparationFact : nil
            if name == Self.intentName || name == Self.preparationName {
                if coldOwnPublishingName == name && !coldPublishedVerified {
                    guard let coldOwnPublishedIdentity,
                          coldOwnPublishedIdentity.device == after.st_dev,
                          coldOwnPublishedIdentity.inode == after.st_ino else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                } else {
                    guard expectedFact == beforeFact else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                }
            }
            if (name == Self.nextName && coldOwnPublishingName == Self.intentName) ||
                (name == Self.preparationNextName &&
                    coldOwnPublishingName == Self.preparationName) {
                guard let coldDisplacedBytes, let coldDisplacedFact,
                      data == coldDisplacedBytes,
                      beforeFact.device == coldDisplacedFact.device,
                      beforeFact.inode == coldDisplacedFact.inode,
                      beforeFact.mode == coldDisplacedFact.mode,
                      beforeFact.links == coldDisplacedFact.links,
                      beforeFact.size == coldDisplacedFact.size,
                      beforeFact.modifiedSeconds == coldDisplacedFact.modifiedSeconds,
                      beforeFact.modifiedNanoseconds == coldDisplacedFact.modifiedNanoseconds else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            try closeColdActiveChecked()
            if name == Self.intentName &&
                coldExpectedIntentBytes != data {
                throw EraseIntentStoreError.invalidAuthority
            }
            if name == Self.preparationName &&
                coldExpectedPreparationBytes != data {
                throw EraseIntentStoreError.invalidAuthority
            }
            if coldOwnPublishingName == name {
                if name == Self.intentName { coldExpectedIntentFact = beforeFact }
                else if name == Self.preparationName {
                    coldExpectedPreparationFact = beforeFact
                }
                coldPublishedVerified = true
            }
            return (data, Identity(device: after.st_dev, inode: after.st_ino))
        } catch {
            let failure = error
            if coldActiveFD != nil { try closeColdActiveChecked() }
            throw failure
        }
    }

    private func createLeaf(_ name: String, data: Data) throws -> Identity {
        if let originalRecoveryCheckedIO {
            return try originalRecoveryCheckedIO.withOpen(
                parent: eraseDescriptor, name: name,
                flags: O_WRONLY | O_CREAT | O_EXCL,
                mode: mode_t(0o600)) { descriptor in
                let expected = try Self.fileIdentity(descriptor)
                do {
                    try applyTemporaryPolicy(.journalTemporary,
                        name: name, descriptor: descriptor)
                    try data.withUnsafeBytes { raw in
                        guard let base = raw.baseAddress else { return }
                        var offset = 0
                        while offset < raw.count {
                            let count = Darwin.write(descriptor,
                                base.advanced(by: offset), raw.count - offset)
                            if count > 0 { offset += count }
                            else if errno != EINTR {
                                throw EraseIntentStoreError.writeFailed
                            }
                        }
                    }
                    guard Darwin.fsync(descriptor) == 0,
                          let written = try readIfPresent(name),
                          written.identity == expected,
                          written.data == data else {
                        throw EraseIntentStoreError.writeFailed
                    }
                    return expected
                } catch {
                    try? removeIfExact(name, expected: expected)
                    throw error
                }
            }
        }
        if borrowsColdObservation {
            return try createColdLeaf(name, data: data)
        }
        guard data.count <= Self.maximumJournalBytes else {
            throw EraseIntentStoreError.writeFailed
        }
        return try originalCanonicalSourceIO.withOpen(parent: eraseDescriptor,
            name: name, flags: O_WRONLY | O_CREAT | O_EXCL,
            mode: mode_t(0o600), openFailure: .writeFailed) { descriptor in
            let expectedIdentity = try Self.fileIdentity(descriptor)
            do {
                try applyTemporaryPolicy(
                    .journalTemporary,
                    name: name,
                    descriptor: descriptor
                )
                try data.withUnsafeBytes { raw in
                    guard let base = raw.baseAddress else { return }
                    var offset = 0
                    while offset < raw.count {
                        let count = Darwin.write(
                            descriptor,
                            base.advanced(by: offset),
                            raw.count - offset
                        )
                        if count > 0 {
                            offset += count
                        } else if errno != EINTR {
                            throw EraseIntentStoreError.writeFailed
                        }
                    }
                }
                guard Darwin.fsync(descriptor) == 0 else {
                    throw EraseIntentStoreError.writeFailed
                }
                guard let written = try readIfPresent(name),
                      written.identity == expectedIdentity,
                      written.data == data else {
                    throw EraseIntentStoreError.writeFailed
                }
                return written.identity
            } catch {
                let failure = error
                do { try removeIfExact(name, expected: expectedIdentity) }
                catch { originalCanonicalSourceIO.poison() }
                throw failure
            }
        }
    }

    private func createColdLeaf(_ name: String, data: Data,
        maximumBytes: Int = EraseIntentStore.maximumJournalBytes) throws -> Identity {
        guard [Self.nextName, Self.preparationNextName,
               Self.rosterNextName, Self.auxiliaryRosterNextName].contains(name),
              data.count <= maximumBytes,
              coldOwnTemporaryName == nil,
              coldActiveFD == nil, coldUncertainFDs.isEmpty,
              !coldEffectUncertain else {
            throw EraseIntentStoreError.invalidAuthority
        }
        coldOwnTemporaryName = name
        let descriptor = Darwin.openat(eraseDescriptor, name,
            O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW | O_CLOEXEC,
            mode_t(0o600))
        guard descriptor >= 0 else {
            coldOwnTemporaryName = nil
            throw EraseIntentStoreError.writeFailed
        }
        coldActiveFD = descriptor
        do {
            let expected = try Self.fileIdentity(descriptor)
            coldOwnTemporaryIdentity = expected
            try applyTemporaryPolicy(.journalTemporary,
                name: name, descriptor: descriptor)
            try data.withUnsafeBytes { raw in
                guard let base = raw.baseAddress else { return }
                var offset = 0
                while offset < raw.count {
                    let count = Darwin.write(descriptor,
                        base.advanced(by: offset), raw.count - offset)
                    if count > 0 { offset += count }
                    else if errno != EINTR {
                        throw EraseIntentStoreError.writeFailed
                    }
                }
            }
            guard Darwin.fsync(descriptor) == 0 else {
                throw EraseIntentStoreError.writeFailed
            }
            coldOwnTemporaryBytes = data
            try closeColdActiveChecked()
            guard let written = try readColdLeafIfPresent(name,
                maximumBytes: maximumBytes),
                  written.identity == expected,
                  written.data == data else {
                throw EraseIntentStoreError.writeFailed
            }
            return expected
        } catch {
            let failure = error
            if coldActiveFD != nil { try closeColdActiveChecked() }
            coldEffectUncertain = true
            throw failure
        }
    }

    private func removeIfExact(_ name: String, expected: Identity) throws {
        guard let current = try readIfPresent(name), current.identity == expected else {
            throw EraseIntentStoreError.cleanupFailed
        }
        try withOriginalCanonicalSourceEffect(name: name,
            expectedBytes: current.data, replacementBytes: nil) {
            markOriginalCanonicalEffectEntry()
            guard Darwin.unlinkat(eraseDescriptor, name, 0) == 0,
                  Darwin.fsync(eraseDescriptor) == 0,
                  case nil = try readIfPresent(name) else {
                throw EraseIntentStoreError.cleanupFailed
            }
        }
    }

    private func removeExact(
        _ name: String,
        expected: (data: Data, identity: Identity)
    ) throws {
        guard let current = try readIfPresent(name),
              current.identity == expected.identity, current.data == expected.data else {
            throw EraseIntentStoreError.cleanupFailed
        }
        try withOriginalCanonicalSourceEffect(name: name,
            expectedBytes: expected.data, replacementBytes: nil) {
            markOriginalCanonicalEffectEntry()
            guard Darwin.unlinkat(eraseDescriptor, name, 0) == 0,
                  Darwin.fsync(eraseDescriptor) == 0 else {
                throw EraseIntentStoreError.cleanupFailed
            }
            guard case nil = try readIfPresent(name) else {
                throw EraseIntentStoreError.cleanupFailed
            }
        }
    }

    private static func directoryIdentity(_ descriptor: Int32) throws -> Identity {
        var info = stat()
        guard Darwin.fstat(descriptor, &info) == 0,
              (info.st_mode & S_IFMT) == S_IFDIR else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return Identity(device: info.st_dev, inode: info.st_ino)
    }

    private static func fileIdentity(_ descriptor: Int32) throws -> Identity {
        var info = stat()
        guard Darwin.fstat(descriptor, &info) == 0,
              (info.st_mode & S_IFMT) == S_IFREG,
              info.st_nlink == 1 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return Identity(device: info.st_dev, inode: info.st_ino)
    }

    private static func requireDirectory(
        _ descriptor: Int32,
        identity: Identity
    ) throws {
        guard try directoryIdentity(descriptor) == identity else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }
}

/// C32 keeps assistance candidates outside every durable and derived surface;
/// only explicit acceptance may reach the existing canonical writer/receipt path.
enum C32AssistanceCompatibility_Deletion_EraseIntentStore {
    enum ProposalDispositionV1: Sendable {
        case nonpersistentUnverifiedExcludedFromStorageSearchReportBackup
    }

    enum AcceptanceDispositionV1: Sendable {
        case durableThroughExistingCanonicalWriter
    }

    static func disposition(
        for proposal: AssistanceProposalV1
    ) throws -> ProposalDispositionV1 {
        try proposal.validate()
        guard !AssistancePersistenceEnrollmentV1.proposalIsPersistent,
              !AssistancePersistenceEnrollmentV1.rejectedProposalCorpusIsPersistent else {
            throw AssistanceContractFailureV1.nonCanonicalData
        }
        switch proposal.verificationState {
        case .unverified:
            return .nonpersistentUnverifiedExcludedFromStorageSearchReportBackup
        }
    }

    static func disposition(
        for receipt: AssistanceAcceptanceReceiptV1
    ) throws -> AcceptanceDispositionV1 {
        try receipt.validate()
        guard AssistancePersistenceEnrollmentV1.durableModelCount == 1 else {
            throw AssistanceContractFailureV1.invalidReceipt
        }
        return .durableThroughExistingCanonicalWriter
    }

    static let capabilityScratchIsDiscardedOnTerminalReview = true
    static let manualFallbackRemainsAvailable = true
    static let interruptionNeverPromotesAProposal = true
    static let createsParallelStoreOrWriter = false
}

enum C33TemporalEvidenceConformance_FieldEvidenceApp_Infrastructure_Deletion_EraseIntentStore_swift {
    static let durableFamilyCount = TemporalEvidencePersistenceEnrollmentV1.durableModelCount
    static func validate(clip: TemporalEvidenceClipV1,
                         anchor: TimecodedEvidenceAnchorV1) throws {
        try clip.validateIntrinsic()
        try anchor.validate(clip: clip)
        guard durableFamilyCount == 2 else {
            throw TemporalEvidenceContractFailureV1.invalidValue
        }
    }
}

enum C45AcceptedLabelEraseStoreBoundaryV1 { static let durableSnapshotCountParticipatesInEraseInventory=true }

enum C46OperationalContactBoundary_42{static let assetOrSiteCascadeDeletesPartyContacts=false;static let workspaceEraseOwnsRows=true}
enum C47ActivityContractEraseStoreBoundaryV2 { static let durableRowInventoryCount=5;static let releasedCompletedSnapshotUsesExistingFileInventory=true;static let conformanceReceiptsCreateNoRows=true }

enum C48PortableExchangeEraseIntentStoreEnrollmentV2 {
    static let rootName = PortableExchangeSessionStoreLayoutV2.directoryName
    static let protectedFileKinds: Set<OwnedFileKindV1> = [
        .portableExchangeSessionFile,
        .portableExchangeJournalFile,
        .portableExchangeQuarantineFile,
    ]
    static func validate() throws {
        guard rootName == "PortableReviewExchangeV2",
              protectedFileKinds.count == 3 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try PortableExchangeProtectedFilePolicyV2.validate()
    }
}
// C52_BOUNDARY_ANCHOR: canonical-service-request-erase

enum C53AssetServiceReliabilityEraseIntentStorePolicyV1 {
    static let durableFamilies = AssetServiceReliabilityPersistenceEnrollmentV1.durableFamilies
    static let ownsFilesystemPayload = false

    static func validate() throws {
        try AssetServiceReliabilityPersistenceEnrollmentV1.validate()
        guard durableFamilies.count == 7,
              !ownsFilesystemPayload,
              C53AssetServiceReliabilityEraseIntentBoundaryV1.validate() else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }
}

// The original P publisher has its own checked transient ownership. The
// ordinary journal APIs deliberately remain unchanged for their callers.
private extension EraseIntentStore {
    func closeOriginalAuxiliaryActiveChecked() throws {
        guard let descriptor = originalAuxiliaryActiveFD else {
            throw EraseIntentStoreError.invalidAuthority
        }
        originalAuxiliaryActiveFD = nil
        if Darwin.close(descriptor) != 0 {
            originalAuxiliaryUncertainFDs.append(descriptor)
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    func originalAuxiliaryRootFactAndNames(allowActive: Bool = false)
        throws -> (EraseColdControlLeafFactV1, [String], uid_t, gid_t) {
        guard !borrowsColdObservation,
              (allowActive || originalAuxiliaryActiveFD == nil),
              originalAuxiliaryEnumerationFD == nil,
              originalAuxiliaryDirectoryStream == nil,
              originalAuxiliaryUncertainFDs.isEmpty,
              !originalAuxiliaryUncertainStreamClose else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try Self.requireDirectory(applicationSupportDescriptor,
            identity: applicationSupportIdentity)
        try Self.requireDirectory(eraseDescriptor, identity: eraseIdentity)
        var support = stat(), heldBefore = stat(), namedBefore = stat()
        guard Darwin.lstat(applicationSupportURL.path, &support) == 0,
              support.st_mode & S_IFMT == S_IFDIR,
              support.st_dev == applicationSupportIdentity.device,
              support.st_ino == applicationSupportIdentity.inode,
              Darwin.fstat(eraseDescriptor, &heldBefore) == 0,
              Darwin.fstatat(applicationSupportDescriptor,
                Self.directoryName, &namedBefore,
                AT_SYMLINK_NOFOLLOW) == 0,
              heldBefore.st_mode & S_IFMT == S_IFDIR,
              EraseColdControlLeafFactV1(heldBefore)
                == EraseColdControlLeafFactV1(namedBefore) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let duplicate = Darwin.openat(eraseDescriptor, ".",
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
        guard duplicate >= 0 else { throw EraseIntentStoreError.invalidAuthority }
        originalAuxiliaryEnumerationFD = duplicate
        guard let stream = Darwin.fdopendir(duplicate) else {
            originalAuxiliaryEnumerationFD = nil
            if Darwin.close(duplicate) != 0 {
                originalAuxiliaryUncertainFDs.append(duplicate)
            }
            throw EraseIntentStoreError.invalidAuthority
        }
        originalAuxiliaryEnumerationFD = nil
        originalAuxiliaryDirectoryStream = stream
        var names: [String] = []
        errno = 0
        while let entry = Darwin.readdir(stream) {
            guard let name = OwnedStorageDirectoryEntryNameV1.decode(entry) else {
                originalAuxiliaryDirectoryStream = nil
                if Darwin.closedir(stream) != 0 {
                    originalAuxiliaryUncertainStreamClose = true
                }
                throw EraseIntentStoreError.invalidAuthority
            }
            if name != "." && name != ".." { names.append(name) }
            errno = 0
        }
        let readError = errno
        originalAuxiliaryDirectoryStream = nil
        guard Darwin.closedir(stream) == 0 else {
            originalAuxiliaryUncertainStreamClose = true
            throw EraseIntentStoreError.invalidAuthority
        }
        guard readError == 0 else { throw EraseIntentStoreError.invalidAuthority }
        var heldAfter = stat(), namedAfter = stat()
        guard Darwin.fstat(eraseDescriptor, &heldAfter) == 0,
              Darwin.fstatat(applicationSupportDescriptor,
                Self.directoryName, &namedAfter,
                AT_SYMLINK_NOFOLLOW) == 0,
              EraseColdControlLeafFactV1(heldBefore)
                == EraseColdControlLeafFactV1(heldAfter),
              EraseColdControlLeafFactV1(heldAfter)
                == EraseColdControlLeafFactV1(namedAfter) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return (EraseColdControlLeafFactV1(heldAfter), names.sorted(),
            heldAfter.st_uid, heldAfter.st_gid)
    }

    func requireOriginalAuxiliaryRoot(
        names expectedNames: [String],
        exact expectedFact: EraseColdControlLeafFactV1?,
        allowActive: Bool = false
    ) throws -> EraseColdControlLeafFactV1 {
        let (fact, names, user, group) = try originalAuxiliaryRootFactAndNames(
            allowActive: allowActive)
        guard names == expectedNames.sorted() else {
            throw EraseIntentStoreError.invalidAuthority
        }
        if let expectedFact, fact != expectedFact {
            throw EraseIntentStoreError.invalidAuthority
        }
        if let projected = originalAuxiliaryProjectedRoot {
            guard fact == projected,
                  originalAuxiliaryRootUser == user,
                  originalAuxiliaryRootGroup == group else {
                throw EraseIntentStoreError.invalidAuthority
            }
        } else {
            guard expectedFact == nil,
                  names == [Self.intentName,
                    Self.preparationName].sorted() else {
                throw EraseIntentStoreError.invalidAuthority
            }
            originalAuxiliaryProjectedRoot = fact
            originalAuxiliaryRootUser = user
            originalAuxiliaryRootGroup = group
        }
        let supportedAllEntries = UInt64(fact.links)
            == UInt64(2 + names.count)
        let supportedSubdirectories = UInt64(fact.links) == 2
        if let law = originalAuxiliaryRootLinkLaw {
            guard (law == 1 && supportedAllEntries) ||
                  (law == 0 && supportedSubdirectories) else {
                throw EraseIntentStoreError.invalidAuthority
            }
        } else {
            // If the first two-entry cut distinguishes the filesystem laws,
            // retain the actual one. Neither rule permits an arbitrary link
            // count change after our owned O_EXCL/rename transition.
            guard supportedAllEntries || supportedSubdirectories else {
                throw EraseIntentStoreError.invalidAuthority
            }
            originalAuxiliaryRootLinkLaw = supportedAllEntries ? 1 : 0
        }
        return fact
    }

    /// The only full-Fact projection points follow this operation's exact
    /// O_EXCL or no-replace rename. A caller may not call the normal census
    /// with an absent expected Fact to adopt arbitrary directory metadata.
    func projectOriginalAuxiliaryRootAfterOwnedNameEffect(
        prior: EraseColdControlLeafFactV1,
        names expectedNames: [String],
        allowActive: Bool
    ) throws -> EraseColdControlLeafFactV1 {
        guard originalAuxiliaryProjectedRoot == prior,
              originalAuxiliaryPublicationStarted,
              expectedNames.sorted() == [Self.intentName,
                Self.preparationName,
                allowActive ? Self.auxiliaryRosterNextName
                    : Self.auxiliaryRosterName].sorted() else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let (next, names, user, group) = try
            originalAuxiliaryRootFactAndNames(allowActive: allowActive)
        guard names == expectedNames.sorted(),
              next.device == prior.device,
              next.inode == prior.inode,
              next.mode == prior.mode,
              originalAuxiliaryRootUser == user,
              originalAuxiliaryRootGroup == group,
              (originalAuxiliaryRootLinkLaw == 0 && next.links == 2 ||
                originalAuxiliaryRootLinkLaw == 1 &&
                    UInt64(next.links) == UInt64(2 + names.count)) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        originalAuxiliaryProjectedRoot = next
        return next
    }

    func readOriginalAuxiliaryLeaf(
        _ name: String, maximumBytes: Int
    ) throws -> (Data, EraseColdControlLeafFactV1)? {
        guard originalAuxiliaryActiveFD == nil,
              originalAuxiliaryUncertainFDs.isEmpty else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let descriptor = Darwin.openat(eraseDescriptor, name,
            O_RDONLY | O_NOFOLLOW | O_NONBLOCK | O_CLOEXEC)
        if descriptor < 0, errno == ENOENT { return nil }
        guard descriptor >= 0 else { throw EraseIntentStoreError.invalidAuthority }
        originalAuxiliaryActiveFD = descriptor
        do {
            var before = stat(), named = stat()
            guard Darwin.fstat(descriptor, &before) == 0,
                  Darwin.fstatat(eraseDescriptor, name, &named,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  before.st_mode & S_IFMT == S_IFREG,
                  before.st_nlink == 1,
                  EraseColdControlLeafFactV1(before)
                    == EraseColdControlLeafFactV1(named),
                  before.st_size >= 0,
                  before.st_size <= off_t(maximumBytes) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            var bytes = Data()
            var buffer = [UInt8](repeating: 0, count: 16 * 1024)
            while true {
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.read(descriptor, $0.baseAddress, $0.count)
                }
                if count > 0 {
                    bytes.append(contentsOf: buffer.prefix(count))
                    guard bytes.count <= maximumBytes else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                } else if count == 0 { break }
                else if errno != EINTR {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            var after = stat(), namedAfter = stat()
            guard Darwin.fstat(descriptor, &after) == 0,
                  Darwin.fstatat(eraseDescriptor, name,
                    &namedAfter, AT_SYMLINK_NOFOLLOW) == 0,
                  EraseColdControlLeafFactV1(before)
                    == EraseColdControlLeafFactV1(after),
                  EraseColdControlLeafFactV1(after)
                    == EraseColdControlLeafFactV1(namedAfter),
                  bytes.count == Int(after.st_size) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let fact = EraseColdControlLeafFactV1(after)
            try closeOriginalAuxiliaryActiveChecked()
            return (bytes, fact)
        } catch {
            let failure = error
            if originalAuxiliaryActiveFD != nil {
                try closeOriginalAuxiliaryActiveChecked()
            }
            throw failure
        }
    }

    private func requireOriginalAuxiliaryActiveTemporary(
        descriptor: Int32, identity: Identity,
        names: [String]
    ) throws {
        guard originalAuxiliaryActiveFD == descriptor,
              originalAuxiliaryUncertainFDs.isEmpty,
              let projected = originalAuxiliaryProjectedRoot else {
            throw EraseIntentStoreError.invalidAuthority
        }
        _ = try requireOriginalAuxiliaryRoot(names: names,
            exact: projected, allowActive: true)
        var held = stat(), named = stat()
        guard Darwin.fstat(descriptor, &held) == 0,
              Darwin.fstatat(eraseDescriptor,
                Self.auxiliaryRosterNextName, &named,
                AT_SYMLINK_NOFOLLOW) == 0,
              held.st_dev == identity.device,
              held.st_ino == identity.inode,
              named.st_dev == identity.device,
              named.st_ino == identity.inode,
              held.st_mode == named.st_mode,
              held.st_mode & S_IFMT == S_IFREG,
              held.st_mode & 0o777 == 0o600,
              held.st_nlink == 1, named.st_nlink == 1,
              held.st_size == 0, named.st_size == 0 else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    func requireOriginalAuxiliaryControlLeaves(
        intent: (Data, EraseColdControlLeafFactV1),
        preparation: (Data, EraseColdControlLeafFactV1)
    ) throws {
        guard let currentIntent = try readOriginalAuxiliaryLeaf(
                Self.intentName, maximumBytes: intent.0.count),
              let currentPreparation = try readOriginalAuxiliaryLeaf(
                Self.preparationName,
                maximumBytes: preparation.0.count) else {
#if DEBUG
            if originalAuxiliaryPhaseTracingForTesting {
                print("ORIGINAL_AUX_PHASE_V1 refusal=control-leaf-presence")
            }
#endif
            throw EraseIntentStoreError.invalidAuthority
        }
        guard currentIntent.0 == intent.0,
              currentIntent.1 == intent.1 else {
#if DEBUG
            if originalAuxiliaryPhaseTracingForTesting {
                print("ORIGINAL_AUX_PHASE_V1 refusal=intent-control")
            }
#endif
            throw EraseIntentStoreError.invalidAuthority
        }
        guard currentPreparation.0 == preparation.0,
              currentPreparation.1 == preparation.1 else {
#if DEBUG
            if originalAuxiliaryPhaseTracingForTesting {
                print("ORIGINAL_AUX_PHASE_V1 refusal=preparation-control")
            }
#endif
            throw EraseIntentStoreError.invalidAuthority
        }
    }
}

@MainActor
extension EraseIntentStore {
    /// Records the exact operation-owned private Data stage inode before
    /// Factory may rename it to the canonical retired-pointer temp. The
    /// Factory receipt, rather than caller-provided path/stat data, is the
    /// authority for this second, distinct G-held publication.
    func publishOriginalRecoveryRetiredStageIdentity(
        stage: OriginalEraseRecoveryRetiredStageReceiptV1,
        sourceAuthority: StoreRestoreGenerationAuthority,
        commitment: OriginalRecoveryRetiredCommitmentReceiptV1,
        namespace: OriginalEraseRecoveryNamespaceSnapshotV1,
        replacementBytes: Data,
        operation: EraseRouterOperationV1,
        owner: StoreOriginalEraseRecoveryPreOpenOwnerV1,
        registry: GenerationLeaseRegistryV1,
        activity: GenerationTemporalActivityHandleV1,
        permit: OriginalEraseRecoveryRetiredStagePermitV1,
        support: StoreTemporalPhysicalRootExclusionV1,
        io: EraseAbortCheckedSnapshotIOV1,
        retainUncertainDescriptor: (Int32) -> Void
    ) throws -> OriginalRecoveryRetiredStageIdentityReceiptV1 {
        guard let roster = originalAuxiliaryPublishedReceipt,
              roster.operation === operation,
              originalRetiredCommitmentReceipt === commitment,
              originalRetiredStageIdentityReceipt == nil,
              !originalRetiredStageIdentityStarted,
              !originalRetiredStageIdentityUncertain,
              !originalAuxiliaryPhaseInFlight,
              !originalAuxiliaryPhaseUncertain,
              let intent = commitment.first.intent,
              intent.schemaVersion == 2,
              intent.phase == .emptyGenerationPrepared,
              namespace.retiredState == .prior,
              stage.intent == intent,
              stage.firstDataFact == namespace.data,
              stage.privateStageName == commitment.record.privateStageName,
              stage.canonicalBytesSHA256 == commitment.record
                .replacementSHA256,
              stage.stageFact.size == off_t(replacementBytes.count),
              stage.checkedSettled,
              let beforeRoot = originalAuxiliaryProjectedRoot,
              beforeRoot == commitment.projectedRoot else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try permit.requireHeld()
        try owner.requireRetainedOriginalRecoveryStoreEffect(
            registry: registry, activity: activity, support: support)
        try commitment.requireBound(operation: operation, owner: owner,
            namespace: namespace, replacementBytes: replacementBytes)
        try stage.requireBound(authority: sourceAuthority,
            operation: operation, owner: owner,
            commitment: commitment, namespace: namespace,
            replacementBytes: replacementBytes)
        let first = try Self.observeOriginalRecoveryNoCreate(
            support: support, applicationSupportURL: applicationSupportURL,
            io: io, retainUncertainDescriptor: retainUncertainDescriptor)
        guard first == commitment.published,
              first.eraseNames == [Self.intentName,
                Self.preparationName, Self.auxiliaryRosterName,
                Self.originalRetiredCommitmentName].sorted(),
              let commitmentLeaf = first.leaves.first(where: {
                $0.name == Self.originalRetiredCommitmentName }),
              commitmentLeaf.data == commitment.canonicalBytes,
              let firstEraseOwner = first.eraseOwnership else {
            throw EraseIntentStoreError.invalidAuthority
        }
        typealias Fact = OriginalRecoveryRetiredCommitmentRecordV1.Fact
        let stageRecord = OriginalRecoveryRetiredStageIdentityRecordV1(
            schemaVersion: 1,
            eraseID: intent.eraseID.uuidString.lowercased(),
            commitmentSHA256: StoreMigrationCanonicalJSONV1.sha256(
                commitment.canonicalBytes),
            commitmentFact: Fact(device: commitmentLeaf.fact.device,
                inode: commitmentLeaf.fact.inode,
                mode: commitmentLeaf.fact.mode,
                links: commitmentLeaf.fact.links,
                user: commitmentLeaf.ownership.user,
                group: commitmentLeaf.ownership.group,
                size: commitmentLeaf.fact.size,
                modifiedSeconds: commitmentLeaf.fact.modifiedSeconds,
                modifiedNanoseconds:
                    commitmentLeaf.fact.modifiedNanoseconds,
                changedSeconds: commitmentLeaf.fact.changedSeconds,
                changedNanoseconds:
                    commitmentLeaf.fact.changedNanoseconds),
            firstDataFact: Fact(namespace.data),
            firstDataChildren:
                OriginalRecoveryRetiredStageIdentityRecordV1
                    .children(namespace.dataChildren),
            afterDataFact: Fact(stage.afterDataFact),
            afterDataNames: (namespace.dataNames +
                [stage.privateStageName]).sorted(),
            privateStageName: stage.privateStageName,
            canonicalTempName: commitment.record.canonicalTempName,
            stageFact: Fact(stage.stageFact),
            stagePolicyDisposition:
                stage.policyDisposition == .verifiedComplete
                    ? "verifiedComplete"
                    : "simulatorFileProtectionUnsupported",
            replacementSHA256: stage.canonicalBytesSHA256)
        try stageRecord.validate()
        let bytes = try StoreMigrationCanonicalJSONV1.encode(stageRecord)
        guard bytes.count <= Self.maximumJournalBytes * 3 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let firstNames = first.eraseNames
        let tempNames = (firstNames +
            [Self.originalRetiredStageIdentityNextName]).sorted()
        let publishedNames = (firstNames +
            [Self.originalRetiredStageIdentityName]).sorted()
        do { return try operation.withOriginalRecoveryRetiredStageIdentityInsideHeldG(
            store: self, expected: intent, commitment: commitment,
            registry: registry, activity: activity,
            permit: permit) {
            try stage.requireBound(authority: sourceAuthority,
                operation: operation, owner: owner,
                commitment: commitment, namespace: namespace,
                replacementBytes: replacementBytes)
            try commitment.requireBound(operation: operation, owner: owner,
                namespace: namespace, replacementBytes: replacementBytes)
            try requireOriginalEraseAuxiliaryPublishedRoster(roster)
            guard try requireOriginalAuxiliaryRoot(
                    names: firstNames, exact: beforeRoot) == beforeRoot else {
                throw EraseIntentStoreError.invalidAuthority
            }
            originalRetiredStageIdentityStarted = true
            do {
                let eraseURL = applicationSupportURL
                    .appendingPathComponent(Self.directoryName,
                        isDirectory: true)
                let tempURL = eraseURL.appendingPathComponent(
                    Self.originalRetiredStageIdentityNextName)
                var ownIdentity: Identity?
                let (disposition, root) = try io.withOpen(parent: eraseDescriptor,
                    name: Self.originalRetiredStageIdentityNextName,
                    flags: O_WRONLY | O_CREAT | O_EXCL,
                    mode: mode_t(0o600)) { descriptor in
                    let identity = try Self.fileIdentity(descriptor)
                    ownIdentity = identity
                    let (root, names, user, group) = try
                        originalAuxiliaryRootFactAndNames()
                    guard names == tempNames,
                          root.device == beforeRoot.device,
                          root.inode == beforeRoot.inode,
                          root.mode == beforeRoot.mode,
                          originalAuxiliaryRootUser == user,
                          originalAuxiliaryRootGroup == group,
                          (originalAuxiliaryRootLinkLaw == 0 &&
                            root.links == 2 ||
                           originalAuxiliaryRootLinkLaw == 1 &&
                            UInt64(root.links) == UInt64(2 + names.count)) else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    let disposition = try ProtectedFilePolicyV1
                        .applyAndVerifyEraseColdPrivateWithCheckedClose(
                            .journalTemporary, at: tempURL,
                            retainUncertainDescriptor: { [self] in
                                retainOriginalRecoveryUncertainDescriptor($0)
                            }, authorityCheck: {
                                var held = stat(), named = stat()
                                guard Darwin.fstat(descriptor, &held) == 0,
                                      Darwin.fstatat(eraseDescriptor,
                                        Self.originalRetiredStageIdentityNextName,
                                        &named, AT_SYMLINK_NOFOLLOW) == 0,
                                      held.st_dev == identity.device,
                                      held.st_ino == identity.inode,
                                      held.st_mode & S_IFMT == S_IFREG,
                                      held.st_mode & 0o777 == 0o600,
                                      held.st_nlink == 1,
                                      held.st_size == 0,
                                      held.st_uid == Darwin.getuid(),
                                      held.st_gid == firstEraseOwner.group,
                                      held.st_uid == named.st_uid,
                                      held.st_gid == named.st_gid,
                                      EraseColdControlLeafFactV1(held)
                                        == EraseColdControlLeafFactV1(named),
                                      let bracket = try?
                                        originalAuxiliaryRootFactAndNames(),
                                      bracket.0 == root,
                                      bracket.1 == tempNames,
                                      bracket.2 == firstEraseOwner.user,
                                      bracket.3 == firstEraseOwner.group else {
                                    throw EraseIntentStoreError.invalidAuthority
                                }
                            })
                    try bytes.withUnsafeBytes { raw in
                        guard let base = raw.baseAddress else {
                            throw EraseIntentStoreError.writeFailed
                        }
                        var offset = 0
                        while offset < raw.count {
                            let count = Darwin.write(descriptor,
                                base.advanced(by: offset), raw.count - offset)
                            if count > 0 { offset += count }
                            else if count == 0 || errno != EINTR {
                                throw EraseIntentStoreError.writeFailed
                            }
                        }
                    }
                    guard Darwin.fsync(descriptor) == 0 else {
                        throw EraseIntentStoreError.writeFailed
                    }
                    return (disposition, root)
                }
                guard let ownIdentity,
                      let temporary = try readOriginalAuxiliaryLeaf(
                        Self.originalRetiredStageIdentityNextName,
                        maximumBytes: bytes.count),
                      temporary.0 == bytes,
                      temporary.1.device == ownIdentity.device,
                      temporary.1.inode == ownIdentity.inode else {
                    throw EraseIntentStoreError.writeFailed
                }
                let beforeRename = try originalAuxiliaryRootFactAndNames()
                guard beforeRename.0 == root,
                      beforeRename.1 == tempNames,
                      beforeRename.2 == firstEraseOwner.user,
                      beforeRename.3 == firstEraseOwner.group,
                      Darwin.renameatx_np(eraseDescriptor,
                        Self.originalRetiredStageIdentityNextName,
                        eraseDescriptor,
                        Self.originalRetiredStageIdentityName,
                        UInt32(RENAME_EXCL)) == 0 else {
                    throw EraseIntentStoreError.writeFailed
                }
                let (afterRoot, names, user, group) = try
                    originalAuxiliaryRootFactAndNames()
                guard names == publishedNames,
                      afterRoot.device == beforeRoot.device,
                      afterRoot.inode == beforeRoot.inode,
                      afterRoot.mode == beforeRoot.mode,
                      originalAuxiliaryRootUser == user,
                      originalAuxiliaryRootGroup == group,
                      (originalAuxiliaryRootLinkLaw == 0 &&
                        afterRoot.links == 2 ||
                       originalAuxiliaryRootLinkLaw == 1 &&
                        UInt64(afterRoot.links)
                            == UInt64(2 + names.count)),
                      Darwin.fsync(eraseDescriptor) == 0,
                      try originalAuxiliaryRootFactAndNames().0 == afterRoot,
                      let published = try readOriginalAuxiliaryLeaf(
                        Self.originalRetiredStageIdentityName,
                        maximumBytes: bytes.count),
                      published.0 == bytes,
                      published.1.device == temporary.1.device,
                      published.1.inode == temporary.1.inode,
                      published.1.mode == temporary.1.mode,
                      published.1.links == temporary.1.links,
                      published.1.size == temporary.1.size else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                let policy = try ProtectedFilePolicyV1
                    .observeTemporalPolicyWithCheckedClose(.journal,
                        at: eraseURL.appendingPathComponent(
                            Self.originalRetiredStageIdentityName),
                        retainUncertainDescriptor: { [self] in
                            retainOriginalRecoveryUncertainDescriptor($0)
                        })
                guard policy.device == UInt64(published.1.device),
                      policy.inode == UInt64(published.1.inode),
                      policy.linkCount == UInt64(published.1.links),
                      policy.backupExcluded == true,
                      (policy.state == .strictComplete ||
                       (policy.state == .pendingSimulatorRequest &&
                        disposition == .simulatorFileProtectionUnsupported)) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                let after = try Self.observeOriginalRecoveryNoCreate(
                    support: support,
                    applicationSupportURL: applicationSupportURL,
                    io: io,
                    retainUncertainDescriptor: retainUncertainDescriptor)
                guard after.sameOwnedRetiredStageNonRecordNamespace(
                        as: first),
                      let observedRecord = after.leaves.first(where: {
                        $0.name == Self.originalRetiredStageIdentityName }),
                      observedRecord.data == bytes,
                      observedRecord.fact.device == published.1.device,
                      observedRecord.fact.inode == published.1.inode,
                      observedRecord.fact.mode == published.1.mode,
                      observedRecord.fact.links == published.1.links,
                      observedRecord.fact.size == published.1.size,
                      observedRecord.fact.modifiedSeconds
                        == published.1.modifiedSeconds,
                      observedRecord.fact.modifiedNanoseconds
                        == published.1.modifiedNanoseconds,
                      observedRecord.fact.changedSeconds
                        == published.1.changedSeconds,
                      observedRecord.fact.changedNanoseconds
                        == published.1.changedNanoseconds else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                originalAuxiliaryProjectedRoot = afterRoot
                let receipt = OriginalRecoveryRetiredStageIdentityReceiptV1(
                    store: self, operation: operation, owner: owner,
                    commitment: commitment, stage: stage,
                    namespace: namespace,
                    replacementBytes: replacementBytes,
                    record: stageRecord, canonicalBytes: bytes,
                    recordFact: published.1,
                    first: first, published: after,
                    projectedRoot: afterRoot, support: support)
                originalRetiredStageIdentityReceipt = receipt
                try io.requireSettled()
                return receipt
            } catch {
                originalRetiredStageIdentityUncertain = true
                throw error
            }
        }
        } catch {
            if originalRetiredStageIdentityStarted {
                originalRetiredStageIdentityUncertain = true
            }
            throw error
        }
    }

    func requireOriginalRecoveryRetiredStageIdentity(
        _ receipt: OriginalRecoveryRetiredStageIdentityReceiptV1
    ) throws {
        guard originalRetiredStageIdentityReceipt === receipt,
              receipt.store === self,
              receipt.checkedSettled,
              !originalRetiredStageIdentityUncertain,
              !originalAuxiliaryPhaseInFlight,
              !originalAuxiliaryPhaseUncertain,
              originalAuxiliaryProjectedRoot == receipt.projectedRoot,
              let roster = originalAuxiliaryPublishedReceipt,
              let io = originalRecoveryCheckedIO else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try requireOriginalEraseAuxiliaryPublishedRoster(roster)
        try receipt.record.validate()
        guard try StoreMigrationCanonicalJSONV1.encode(receipt.record)
                == receipt.canonicalBytes,
              let leaf = try readOriginalAuxiliaryLeaf(
                Self.originalRetiredStageIdentityName,
                maximumBytes: receipt.canonicalBytes.count),
              leaf.0 == receipt.canonicalBytes,
              leaf.1 == receipt.recordFact,
              let physical = try? originalAuxiliaryRootFactAndNames(),
              physical.0 == receipt.projectedRoot,
              physical.1 == receipt.published.eraseNames else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try io.requireSettled()
    }

    /// Publishes the prospective P-cut record before Factory may create its
    /// retired-pointer temp. Only this operation's original Store, roster,
    /// retained EX and checked G scope can perform the one-way publication.
    func publishOriginalRecoveryRetiredCommitment(
        namespace: OriginalEraseRecoveryNamespaceSnapshotV1,
        replacementBytes: Data,
        sourceAuthority: StoreRestoreGenerationAuthority,
        operation: EraseRouterOperationV1,
        owner: StoreOriginalEraseRecoveryPreOpenOwnerV1,
        registry: GenerationLeaseRegistryV1,
        activity: GenerationTemporalActivityHandleV1,
        permit: OriginalEraseRecoveryRetiredCommitmentPermitV1,
        support: StoreTemporalPhysicalRootExclusionV1,
        firstObservation: OriginalRecoveryObservation,
        io: EraseAbortCheckedSnapshotIOV1,
        retainUncertainDescriptor: (Int32) -> Void
    ) throws -> OriginalRecoveryRetiredCommitmentReceiptV1 {
        guard let roster = originalAuxiliaryPublishedReceipt,
              roster.operation === operation,
              let intent = firstObservation.intent,
              intent.schemaVersion == 2,
              intent.phase == .emptyGenerationPrepared,
              firstObservation.preparation?.matches(intent) == true,
              namespace.retiredState == .prior,
              !originalRetiredCommitmentStarted,
              originalRetiredCommitmentReceipt == nil,
              !originalRetiredCommitmentUncertain,
              !originalAuxiliaryPhaseInFlight,
              !originalAuxiliaryPhaseUncertain,
              originalAuxiliaryProjectedIntentBytes == (try encode(intent)),
              let beforeRoot = originalAuxiliaryProjectedRoot,
              let firstIntent = firstObservation.leaves.first(where: {
                $0.name == Self.intentName }),
              let firstPreparation = firstObservation.leaves.first(where: {
                $0.name == Self.preparationName }),
              let firstRoster = firstObservation.leaves.first(where: {
                $0.name == Self.auxiliaryRosterName }),
              let firstErase = firstObservation.eraseFact,
              let firstEraseOwnership = firstObservation.eraseOwnership,
              replacementBytes.count <= 1_048_576 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try owner.requireRetainedOriginalRecoveryStoreEffect(
            registry: registry, activity: activity, support: support)
        try permit.requireHeld()
        try requireOriginalEraseAuxiliaryPublishedRoster(roster)
        let before = try Self.observeOriginalRecoveryNoCreate(
            support: support, applicationSupportURL: applicationSupportURL,
            io: io, retainUncertainDescriptor: retainUncertainDescriptor)
        guard before == firstObservation else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try before.requireOriginalAuxiliaryRoster(roster, store: self,
            operation: operation, seal: roster.seal)
        let complete = try StoreMigrationCanonicalJSONV1.decodeCanonical(
            RetiredPointerV1.self, from: replacementBytes)
        let prior = try StoreMigrationCanonicalJSONV1.decodeCanonical(
            RetiredPointerV1.self, from: namespace.retiredBytes)
        try StorePointerSchemaRegistry.requireRetired(complete.schemaVersion)
        guard complete.schemaVersion == prior.schemaVersion,
              complete.generationIDs == intent.generationIDsToDelete.map({
                $0.uuidString.lowercased() }),
              prior.generationIDs == intent.generationIDsToDelete
                .filter({ $0 != intent.oldGenerationID })
                .map({ $0.uuidString.lowercased() }),
              namespace.currentFact.device == namespace.data.device,
              namespace.retiredFact.device == namespace.data.device,
              firstObservation.supportDevice == Int64(applicationSupportIdentity.device),
              firstObservation.supportInode == UInt64(applicationSupportIdentity.inode) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        typealias Fact = OriginalRecoveryRetiredCommitmentRecordV1.Fact
        func leafFact(_ leaf: OriginalRecoveryObservation.Leaf) -> Fact {
            Fact(device: leaf.fact.device, inode: leaf.fact.inode,
                mode: leaf.fact.mode, links: leaf.fact.links,
                user: leaf.ownership.user, group: leaf.ownership.group,
                size: leaf.fact.size,
                modifiedSeconds: leaf.fact.modifiedSeconds,
                modifiedNanoseconds: leaf.fact.modifiedNanoseconds,
                changedSeconds: leaf.fact.changedSeconds,
                changedNanoseconds: leaf.fact.changedNanoseconds)
        }
        let firstSupport = firstObservation.supportFact
        let firstSupportOwner = firstObservation.supportOwnership
        let record = OriginalRecoveryRetiredCommitmentRecordV1(
            schemaVersion: 2,
            eraseID: intent.eraseID.uuidString.lowercased(),
            sourceGenerationID: intent.oldGenerationID.uuidString.lowercased(),
            targetGenerationID: intent.newGenerationID.uuidString.lowercased(),
            support: Fact(device: firstSupport.device,
                inode: firstSupport.inode, mode: firstSupport.mode,
                links: firstSupport.links,
                user: firstSupportOwner.user, group: firstSupportOwner.group,
                size: firstSupport.size,
                modifiedSeconds: firstSupport.modifiedSeconds,
                modifiedNanoseconds: firstSupport.modifiedNanoseconds,
                changedSeconds: firstSupport.changedSeconds,
                changedNanoseconds: firstSupport.changedNanoseconds),
            supportNames: firstObservation.supportNames,
            erase: Fact(device: firstErase.device,
                inode: firstErase.inode, mode: firstErase.mode,
                links: firstErase.links,
                user: firstEraseOwnership.user,
                group: firstEraseOwnership.group, size: firstErase.size,
                modifiedSeconds: firstErase.modifiedSeconds,
                modifiedNanoseconds: firstErase.modifiedNanoseconds,
                changedSeconds: firstErase.changedSeconds,
                changedNanoseconds: firstErase.changedNanoseconds),
            firstEraseNames: firstObservation.eraseNames,
            intentBytes: firstIntent.data, intentFact: leafFact(firstIntent),
            preparationBytes: firstPreparation.data,
            preparationFact: leafFact(firstPreparation),
            auxiliaryRosterBytes: firstRoster.data,
            auxiliaryRosterFact: leafFact(firstRoster),
            namespace: .init(namespace),
            privateStageName: ".retired.json.original-erase-\(intent.eraseID.uuidString.lowercased()).stage",
            canonicalTempName: ".retired.json.restore-next",
            firstPrivateStageAbsent: true,
            firstCanonicalTempAbsent: true,
            replacementBytes: replacementBytes,
            replacementSHA256: StoreMigrationCanonicalJSONV1.sha256(
                replacementBytes))
        try record.validate()
        let bytes = try StoreMigrationCanonicalJSONV1.encode(record)
        guard bytes.count <= Self.maximumJournalBytes * 3 else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let firstNames = [Self.intentName, Self.preparationName,
            Self.auxiliaryRosterName].sorted()
        let tempNames = (firstNames +
            [Self.originalRetiredCommitmentNextName]).sorted()
        let publishedNames = (firstNames +
            [Self.originalRetiredCommitmentName]).sorted()
        guard firstObservation.eraseNames == firstNames,
              beforeRoot.device == firstErase.device,
              beforeRoot.inode == firstErase.inode,
              beforeRoot.mode == firstErase.mode,
              beforeRoot.links == firstErase.links,
              beforeRoot.size == firstErase.size,
              beforeRoot.modifiedSeconds == firstErase.modifiedSeconds,
              beforeRoot.modifiedNanoseconds == firstErase.modifiedNanoseconds,
              beforeRoot.changedSeconds == firstErase.changedSeconds,
              beforeRoot.changedNanoseconds == firstErase.changedNanoseconds,
              try requireOriginalAuxiliaryRoot(
                names: firstNames, exact: beforeRoot) == beforeRoot else {
            throw EraseIntentStoreError.invalidAuthority
        }
        do { return try operation.withOriginalRecoveryRetiredCommitmentInsideHeldG(
            store: self, expected: intent, registry: registry,
            activity: activity, permit: permit) {
            // Reobserve the held/named Data parents and both exact canonical
            // leaves inside this same G, immediately before the Erase effect.
            // A caller-supplied snapshot alone is never a first-image proof.
            guard try sourceAuthority.originalRecoveryNamespaceSnapshot(
                    intent: intent) == namespace else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try owner.requireObservationUnchangedInsideOriginalRecoveryG()
            try requireOriginalEraseAuxiliaryPublishedRoster(roster)
            guard try requireOriginalAuxiliaryRoot(
                    names: firstNames, exact: beforeRoot) == beforeRoot else {
                throw EraseIntentStoreError.invalidAuthority
            }
            originalRetiredCommitmentStarted = true
            do {
                let eraseURL = applicationSupportURL
                    .appendingPathComponent(Self.directoryName,
                        isDirectory: true)
                let tempURL = eraseURL.appendingPathComponent(
                    Self.originalRetiredCommitmentNextName)
                var ownIdentity: Identity?
                let (disposition, root) = try io.withOpen(parent: eraseDescriptor,
                    name: Self.originalRetiredCommitmentNextName,
                    flags: O_WRONLY | O_CREAT | O_EXCL,
                    mode: mode_t(0o600)) { descriptor in
                    let identity = try Self.fileIdentity(descriptor)
                    ownIdentity = identity
                    let (root, names, user, group) = try
                        originalAuxiliaryRootFactAndNames()
                    guard names == tempNames,
                          root.device == beforeRoot.device,
                          root.inode == beforeRoot.inode,
                          root.mode == beforeRoot.mode,
                          originalAuxiliaryRootUser == user,
                          originalAuxiliaryRootGroup == group,
                          (originalAuxiliaryRootLinkLaw == 0 &&
                            root.links == 2 ||
                           originalAuxiliaryRootLinkLaw == 1 &&
                            UInt64(root.links) == UInt64(2 + names.count)) else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    let disposition = try ProtectedFilePolicyV1
                        .applyAndVerifyEraseColdPrivateWithCheckedClose(
                            .journalTemporary, at: tempURL,
                            retainUncertainDescriptor: { [self] in
                                retainOriginalRecoveryUncertainDescriptor($0)
                            }, authorityCheck: {
                                var held = stat(), named = stat()
                                guard Darwin.fstat(descriptor, &held) == 0,
                                      Darwin.fstatat(eraseDescriptor,
                                        Self.originalRetiredCommitmentNextName,
                                        &named, AT_SYMLINK_NOFOLLOW) == 0,
                                      held.st_dev == identity.device,
                                      held.st_ino == identity.inode,
                                      held.st_mode & S_IFMT == S_IFREG,
                                      held.st_mode & 0o777 == 0o600,
                                      held.st_nlink == 1,
                                      held.st_size == 0,
                                      held.st_uid == Darwin.getuid(),
                                      held.st_gid == firstEraseOwnership.group,
                                      held.st_uid == named.st_uid,
                                      held.st_gid == named.st_gid,
                                      EraseColdControlLeafFactV1(held)
                                        == EraseColdControlLeafFactV1(named),
                                      let bracket = try?
                                        originalAuxiliaryRootFactAndNames(),
                                      bracket.0 == root,
                                      bracket.1 == tempNames,
                                      bracket.2 == firstEraseOwnership.user,
                                      bracket.3 == firstEraseOwnership.group else {
                                    throw EraseIntentStoreError.invalidAuthority
                                }
                            })
                    try bytes.withUnsafeBytes { raw in
                        guard let base = raw.baseAddress else {
                            throw EraseIntentStoreError.writeFailed
                        }
                        var offset = 0
                        while offset < raw.count {
                            let count = Darwin.write(descriptor,
                                base.advanced(by: offset), raw.count - offset)
                            if count > 0 { offset += count }
                            else if count == 0 || errno != EINTR {
                                throw EraseIntentStoreError.writeFailed
                            }
                        }
                    }
                    guard Darwin.fsync(descriptor) == 0 else {
                        throw EraseIntentStoreError.writeFailed
                    }
                    return (disposition, root)
                }
                guard let ownIdentity,
                      let temporary = try readOriginalAuxiliaryLeaf(
                        Self.originalRetiredCommitmentNextName,
                        maximumBytes: bytes.count),
                      temporary.0 == bytes,
                      temporary.1.device == ownIdentity.device,
                      temporary.1.inode == ownIdentity.inode else {
                    throw EraseIntentStoreError.writeFailed
                }
                let beforeRename = try originalAuxiliaryRootFactAndNames()
                guard beforeRename.0 == root,
                      beforeRename.1 == tempNames,
                      beforeRename.2 == firstEraseOwnership.user,
                      beforeRename.3 == firstEraseOwnership.group,
                      Darwin.renameatx_np(eraseDescriptor,
                        Self.originalRetiredCommitmentNextName,
                        eraseDescriptor,
                        Self.originalRetiredCommitmentName,
                        UInt32(RENAME_EXCL)) == 0 else {
                    throw EraseIntentStoreError.writeFailed
                }
                let (afterRoot, names, user, group) = try
                    originalAuxiliaryRootFactAndNames()
                guard names == publishedNames,
                      afterRoot.device == beforeRoot.device,
                      afterRoot.inode == beforeRoot.inode,
                      afterRoot.mode == beforeRoot.mode,
                      originalAuxiliaryRootUser == user,
                      originalAuxiliaryRootGroup == group,
                      (originalAuxiliaryRootLinkLaw == 0 &&
                        afterRoot.links == 2 ||
                       originalAuxiliaryRootLinkLaw == 1 &&
                        UInt64(afterRoot.links)
                            == UInt64(2 + names.count)),
                      Darwin.fsync(eraseDescriptor) == 0,
                      try originalAuxiliaryRootFactAndNames().0 == afterRoot,
                      let published = try readOriginalAuxiliaryLeaf(
                        Self.originalRetiredCommitmentName,
                        maximumBytes: bytes.count),
                      published.0 == bytes,
                      published.1.device == temporary.1.device,
                      published.1.inode == temporary.1.inode,
                      published.1.mode == temporary.1.mode,
                      published.1.links == temporary.1.links,
                      published.1.size == temporary.1.size else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                let policy = try ProtectedFilePolicyV1
                    .observeTemporalPolicyWithCheckedClose(
                        .journal, at: eraseURL.appendingPathComponent(
                            Self.originalRetiredCommitmentName),
                        retainUncertainDescriptor: { [self] in
                            retainOriginalRecoveryUncertainDescriptor($0)
                        })
                guard policy.device == UInt64(published.1.device),
                      policy.inode == UInt64(published.1.inode),
                      policy.linkCount == UInt64(published.1.links),
                      policy.backupExcluded == true,
                      (policy.state == .strictComplete ||
                       (policy.state == .pendingSimulatorRequest &&
                        disposition == .simulatorFileProtectionUnsupported)) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                let after = try Self.observeOriginalRecoveryNoCreate(
                    support: support, applicationSupportURL: applicationSupportURL,
                    io: io, retainUncertainDescriptor:
                        retainUncertainDescriptor)
                guard after.sameOwnedRetiredCommitmentNonRecordNamespace(
                        as: before),
                      let observedRecord = after.leaves.first(where: {
                        $0.name == Self.originalRetiredCommitmentName }),
                      observedRecord.data == bytes,
                      observedRecord.fact.device == published.1.device,
                      observedRecord.fact.inode == published.1.inode,
                      observedRecord.fact.mode == published.1.mode,
                      observedRecord.fact.links == published.1.links,
                      observedRecord.fact.size == published.1.size,
                      observedRecord.fact.modifiedSeconds
                        == published.1.modifiedSeconds,
                      observedRecord.fact.modifiedNanoseconds
                        == published.1.modifiedNanoseconds,
                      observedRecord.fact.changedSeconds
                        == published.1.changedSeconds,
                      observedRecord.fact.changedNanoseconds
                        == published.1.changedNanoseconds else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                originalAuxiliaryProjectedRoot = afterRoot
                let receipt = OriginalRecoveryRetiredCommitmentReceiptV1(
                    store: self, operation: operation, owner: owner,
                    namespace: namespace, replacementBytes: replacementBytes,
                    record: record, canonicalBytes: bytes,
                    recordFact: published.1,
                    first: before, published: after,
                    projectedRoot: afterRoot, support: support)
                originalRetiredCommitmentReceipt = receipt
                try io.requireSettled()
                return receipt
            } catch {
                originalRetiredCommitmentUncertain = true
                throw error
            }
        }
        } catch {
            // The Registry's post-effect census can fail after a fully
            // published leaf. No caller may then reuse this receipt.
            if originalRetiredCommitmentStarted {
                originalRetiredCommitmentUncertain = true
            }
            throw error
        }
    }

    func requireOriginalRecoveryRetiredCommitment(
        _ receipt: OriginalRecoveryRetiredCommitmentReceiptV1
    ) throws {
        guard originalRetiredCommitmentReceipt === receipt,
              !originalRetiredStageIdentityUncertain,
              (!originalRetiredStageIdentityStarted
                || originalRetiredStageIdentityReceipt != nil),
              receipt.store === self,
              receipt.checkedSettled,
              !originalRetiredCommitmentUncertain,
              !originalAuxiliaryPhaseInFlight,
              !originalAuxiliaryPhaseUncertain,
              originalAuxiliaryProjectedRoot ==
                (originalRetiredStageIdentityReceipt?.projectedRoot
                    ?? receipt.projectedRoot),
              let roster = originalAuxiliaryPublishedReceipt,
              let io = originalRecoveryCheckedIO else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try requireOriginalEraseAuxiliaryPublishedRoster(roster)
        try receipt.record.validate()
        guard try StoreMigrationCanonicalJSONV1.encode(receipt.record)
                == receipt.canonicalBytes,
              let leaf = try readOriginalAuxiliaryLeaf(
                Self.originalRetiredCommitmentName,
                maximumBytes: receipt.canonicalBytes.count),
              leaf.0 == receipt.canonicalBytes,
              leaf.1 == receipt.recordFact,
              let physical = try? originalAuxiliaryRootFactAndNames(),
              physical.0 == originalAuxiliaryProjectedRoot,
              physical.1 == (originalRetiredStageIdentityReceipt?
                .published.eraseNames ?? receipt.published.eraseNames) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try io.requireSettled()
    }

    /// This is an in-memory ownership check for the narrow interval after
    /// full roster preflight and before Registry acquires G. Ordinary roster
    /// reproof continues to reject every in-flight call.
    func requireOriginalEraseAuxiliaryPhaseInFlight(
        receipt: OriginalAuxiliaryRosterPublicationReceiptV1,
        operation: EraseRouterOperationV1,
        expected: EraseIntentV1,
        replacement: EraseIntentV1
    ) throws {
        guard originalAuxiliaryPhaseInFlight,
              !originalAuxiliaryPhaseUncertain,
              originalAuxiliaryPublishedReceipt === receipt,
              receipt.store === self,
              receipt.operation === operation,
              receipt.checkedSettled,
              originalAuxiliaryProjectedIntentBytes == (try encode(expected)),
              replacement == expected.advancing(to:
                expected.phase == .emptyGenerationPrepared
                    ? .pointerSwitched : .sessionActivated),
              expected.phase == .emptyGenerationPrepared
                || expected.phase == .pointerSwitched else {
            throw EraseIntentStoreError.invalidAuthority
        }
    }

    /// Projects only this Store's checked P→Q or Q→R intent CAS. The immutable
    /// roster leaf and preparation keep their first full facts; a failed or
    /// ambiguous phase effect permanently withholds later auxiliary effects.
    func replaceOriginalEraseAuxiliaryPhase(
        expected: EraseIntentV1,
        with replacement: EraseIntentV1,
        operation: EraseRouterOperationV1
    ) throws {
#if DEBUG
        originalAuxiliaryPhaseTracingForTesting = true
        defer { originalAuxiliaryPhaseTracingForTesting = false }
        print("ORIGINAL_AUX_PHASE_V1 stage=entry")
#endif
        guard let receipt = originalAuxiliaryPublishedReceipt,
              receipt.operation === operation else {
#if DEBUG
            print("ORIGINAL_AUX_PHASE_V1 refusal=receipt-binding")
#endif
            throw EraseIntentStoreError.invalidAuthority
        }
        guard
              !originalRetiredStageIdentityUncertain,
              (!originalRetiredStageIdentityStarted
                || originalRetiredStageIdentityReceipt != nil),
              !originalAuxiliaryPhaseInFlight,
              !originalAuxiliaryPhaseUncertain else {
#if DEBUG
            print("ORIGINAL_AUX_PHASE_V1 refusal=phase-state")
#endif
            throw EraseIntentStoreError.invalidAuthority
        }
        guard
              expected.schemaVersion == 2,
              (expected.phase == .emptyGenerationPrepared
                && replacement == expected.advancing(to: .pointerSwitched)
                || expected.phase == .pointerSwitched
                && replacement == expected.advancing(to: .sessionActivated)) else {
#if DEBUG
            print("ORIGINAL_AUX_PHASE_V1 refusal=phase-lineage")
#endif
            throw EraseIntentStoreError.invalidAuthority
        }
        guard
              let beforeRoot = originalAuxiliaryProjectedRoot,
              let beforeIntent = originalAuxiliaryProjectedIntentBytes,
              let beforeIntentFact = originalAuxiliaryProjectedIntentFact else {
#if DEBUG
            print("ORIGINAL_AUX_PHASE_V1 refusal=projected-controls")
#endif
            throw EraseIntentStoreError.invalidAuthority
        }
        guard beforeIntent == (try encode(expected)) else {
#if DEBUG
            print("ORIGINAL_AUX_PHASE_V1 refusal=intent-bytes")
#endif
            throw EraseIntentStoreError.invalidAuthority
        }
#if DEBUG
        print("ORIGINAL_AUX_PHASE_V1 stage=store-guard-complete")
#endif
        try operation.requireOriginalEraseAuxiliaryPhaseOwner(
            store: self, expected: expected, replacement: replacement)
#if DEBUG
        print("ORIGINAL_AUX_PHASE_V1 stage=router-owner-complete")
#endif
        try requireOriginalEraseAuxiliaryPublishedRoster(receipt)
#if DEBUG
        print("ORIGINAL_AUX_PHASE_V1 stage=roster-preflight-complete")
#endif
        let names = ([Self.intentName, Self.preparationName,
            Self.auxiliaryRosterName] +
            (originalRetiredCommitmentReceipt == nil ? [] :
                [Self.originalRetiredCommitmentName]) +
            (originalRetiredStageIdentityReceipt == nil ? [] :
                [Self.originalRetiredStageIdentityName])).sorted()
        let phaseAdmission = try operation.admitOriginalEraseAuxiliaryPhaseCAS(
            store: self, expected: expected, replacement: replacement)
        originalAuxiliaryPhaseInFlight = true
        do {
#if DEBUG
            print("ORIGINAL_AUX_PHASE_V1 stage=registry-cas-enter")
#endif
            try operation.withOriginalEraseAuxiliaryPhaseCAS(
                admission: phaseAdmission,
                store: self, expected: expected,
                replacement: replacement) {
#if DEBUG
                print("ORIGINAL_AUX_PHASE_V1 stage=generic-cas-enter")
#endif
                try replaceWithoutMigrationReservation(
                    expected: expected, with: replacement)
#if DEBUG
                print("ORIGINAL_AUX_PHASE_V1 stage=generic-cas-complete")
#endif
                let (afterRoot, afterNames, user, group) = try
                    originalAuxiliaryRootFactAndNames()
#if DEBUG
                print("ORIGINAL_AUX_PHASE_V1 stage=post-root-observed")
#endif
                guard afterNames == names,
                      afterRoot.device == beforeRoot.device,
                      afterRoot.inode == beforeRoot.inode,
                      afterRoot.mode == beforeRoot.mode,
                      afterRoot.links == beforeRoot.links,
                      originalAuxiliaryRootUser == user,
                      originalAuxiliaryRootGroup == group,
                      let nextIntent = try readOriginalAuxiliaryLeaf(
                        Self.intentName,
                        maximumBytes: (try encode(replacement)).count),
                      nextIntent.0 == (try encode(replacement)),
                      nextIntent.1 != beforeIntentFact,
                      let rosterLeaf = try readOriginalAuxiliaryLeaf(
                        Self.auxiliaryRosterName,
                        maximumBytes: receipt.canonicalBytes.count),
                      rosterLeaf.0 == receipt.canonicalBytes,
                      rosterLeaf.1 == receipt.recordFact,
                      let preparationLeaf = try readOriginalAuxiliaryLeaf(
                        Self.preparationName,
                        maximumBytes: receipt.preparationBytes.count),
                      preparationLeaf.0 == receipt.preparationBytes,
                      preparationLeaf.1 == receipt.preparationFact else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                originalAuxiliaryProjectedRoot = afterRoot
                originalAuxiliaryProjectedIntentBytes = nextIntent.0
                originalAuxiliaryProjectedIntentFact = nextIntent.1
                originalAuxiliaryPhaseInFlight = false
            }
#if DEBUG
            print("ORIGINAL_AUX_PHASE_V1 stage=registry-cas-complete")
#endif
            try requireOriginalEraseAuxiliaryPublishedRoster(receipt)
#if DEBUG
            print("ORIGINAL_AUX_PHASE_V1 stage=final-roster-complete")
#endif
        } catch {
#if DEBUG
            switch error {
            case EraseIntentStoreError.retirementPolicyEffectUnavailable:
                print("ORIGINAL_AUX_PHASE_V1 error=retirement-policy")
            case EraseIntentStoreError.invalidAuthority:
                print("ORIGINAL_AUX_PHASE_V1 error=invalid-authority")
            case EraseIntentStoreError.invalidIntent:
                print("ORIGINAL_AUX_PHASE_V1 error=invalid-intent")
            case EraseIntentStoreError.invalidPreparation:
                print("ORIGINAL_AUX_PHASE_V1 error=invalid-preparation")
            case EraseIntentStoreError.intentAlreadyExists:
                print("ORIGINAL_AUX_PHASE_V1 error=intent-already-exists")
            case EraseIntentStoreError.intentMissing:
                print("ORIGINAL_AUX_PHASE_V1 error=intent-missing")
            case EraseIntentStoreError.intentMismatch:
                print("ORIGINAL_AUX_PHASE_V1 error=intent-mismatch")
            case EraseIntentStoreError.preparationAlreadyExists:
                print("ORIGINAL_AUX_PHASE_V1 error=preparation-already-exists")
            case EraseIntentStoreError.preparationMissing:
                print("ORIGINAL_AUX_PHASE_V1 error=preparation-missing")
            case EraseIntentStoreError.preparationMismatch:
                print("ORIGINAL_AUX_PHASE_V1 error=preparation-mismatch")
            case EraseIntentStoreError.writeFailed:
                print("ORIGINAL_AUX_PHASE_V1 error=write-failed")
            case EraseIntentStoreError.cleanupFailed:
                print("ORIGINAL_AUX_PHASE_V1 error=cleanup-failed")
            default:
                print("ORIGINAL_AUX_PHASE_V1 error=other")
            }
#endif
            originalAuxiliaryPhaseUncertain = true
            throw error
        }
    }

    /// The same original-P Store publishes its P→Q CAS inside the private
    /// recovery owner's already held G. Its first roster, preparation and
    /// complete lease cohort remain the original operation's witnesses;
    /// there is no second Store or nested Registry acquisition.
    func replaceOriginalEraseAuxiliaryPhaseForOriginalRecovery(
        expected: EraseIntentV1,
        with replacement: EraseIntentV1,
        operation: EraseRouterOperationV1,
        owner: StoreOriginalEraseRecoveryPreOpenOwnerV1,
        registry: GenerationLeaseRegistryV1,
        activity: GenerationTemporalActivityHandleV1,
        permit: OriginalEraseRecoveryFirstEffectPermitV1,
        support: StoreTemporalPhysicalRootExclusionV1,
        firstObservation: OriginalRecoveryObservation,
        io: EraseAbortCheckedSnapshotIOV1,
        retainUncertainDescriptor: (Int32) -> Void
    ) throws -> OriginalRecoveryFirstPointerCASReceiptV1 {
        guard let roster = originalAuxiliaryPublishedReceipt,
              roster.operation === operation,
              !originalRetiredStageIdentityUncertain,
              (!originalRetiredStageIdentityStarted
                || originalRetiredStageIdentityReceipt != nil),
              expected.schemaVersion == 2,
              expected.phase == .emptyGenerationPrepared,
              replacement == expected.advancing(to: .pointerSwitched),
              firstObservation.intent == expected,
              !originalAuxiliaryPhaseInFlight,
              !originalAuxiliaryPhaseUncertain,
              originalAuxiliaryProjectedIntentBytes == (try encode(expected)),
              originalAuxiliaryProjectedRoot != nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try owner.requireRetainedOriginalRecoveryStoreEffect(
            registry: registry, activity: activity, support: support)
        try permit.requireHeld()
        try requireOriginalEraseAuxiliaryPublishedRoster(roster)
        let before = try Self.observeOriginalRecoveryNoCreate(
            support: support, applicationSupportURL: applicationSupportURL,
            io: io, retainUncertainDescriptor: retainUncertainDescriptor)
        guard before == firstObservation else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try before.requireOriginalAuxiliaryRoster(roster, store: self,
            operation: operation, seal: roster.seal)
        originalAuxiliaryPhaseInFlight = true
        do {
            let after = try operation.withOriginalRecoveryAuxiliaryPhaseInsideHeldG(
                store: self, expected: expected,
                replacement: replacement, registry: registry,
                activity: activity, permit: permit) {
                try replaceWithoutMigrationReservation(
                    expected: expected, with: replacement)
                try permit.requireHeld()
                let observed = try Self.observeOriginalRecoveryNoCreate(
                    support: support, applicationSupportURL: applicationSupportURL,
                    io: io, retainUncertainDescriptor: retainUncertainDescriptor)
                guard observed.intent == replacement,
                      observed.sameOwnedFirstCASNonIntentNamespace(as: before),
                      observed.eraseNames == before.eraseNames else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                let names = ([Self.intentName, Self.preparationName,
                    Self.auxiliaryRosterName] +
                    (originalRetiredCommitmentReceipt == nil ? [] :
                        [Self.originalRetiredCommitmentName]) +
                    (originalRetiredStageIdentityReceipt == nil ? [] :
                        [Self.originalRetiredStageIdentityName])).sorted()
                let (root, observedNames, user, group) = try
                    originalAuxiliaryRootFactAndNames()
                guard observedNames == names,
                      let priorRoot = originalAuxiliaryProjectedRoot,
                      root.device == priorRoot.device,
                      root.inode == priorRoot.inode,
                      root.mode == priorRoot.mode,
                      root.links == priorRoot.links,
                      originalAuxiliaryRootUser == user,
                      originalAuxiliaryRootGroup == group,
                      let nextIntent = try readOriginalAuxiliaryLeaf(
                        Self.intentName,
                        maximumBytes: (try encode(replacement)).count),
                      nextIntent.0 == (try encode(replacement)),
                      nextIntent.1 != originalAuxiliaryProjectedIntentFact,
                      let rosterLeaf = try readOriginalAuxiliaryLeaf(
                        Self.auxiliaryRosterName,
                        maximumBytes: roster.canonicalBytes.count),
                      rosterLeaf.0 == roster.canonicalBytes,
                      rosterLeaf.1 == roster.recordFact,
                      let preparationLeaf = try readOriginalAuxiliaryLeaf(
                        Self.preparationName,
                        maximumBytes: roster.preparationBytes.count),
                      preparationLeaf.0 == roster.preparationBytes,
                      preparationLeaf.1 == roster.preparationFact else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                originalAuxiliaryProjectedRoot = root
                originalAuxiliaryProjectedIntentBytes = nextIntent.0
                originalAuxiliaryProjectedIntentFact = nextIntent.1
                return observed
            }
            try io.requireSettled()
            originalAuxiliaryPhaseInFlight = false
            try requireOriginalEraseAuxiliaryPublishedRoster(roster)
            return OriginalRecoveryFirstPointerCASReceiptV1(
                store: self, before: before, after: after)
        } catch {
            originalAuxiliaryPhaseUncertain = true
            throw error
        }
    }

    func requireOriginalEraseAuxiliaryPublishedRoster(
        _ receipt: OriginalAuxiliaryRosterPublicationReceiptV1
    ) throws {
#if DEBUG
        if originalAuxiliaryPhaseTracingForTesting {
            print("ORIGINAL_AUX_PHASE_V1 stage=roster-reproof-enter")
        }
#endif
        guard let projectedRoot = originalAuxiliaryProjectedRoot,
              !originalRetiredStageIdentityUncertain,
              (!originalRetiredStageIdentityStarted
                || originalRetiredStageIdentityReceipt != nil),
              let projectedIntentBytes = originalAuxiliaryProjectedIntentBytes,
              let projectedIntentFact = originalAuxiliaryProjectedIntentFact,
              !originalAuxiliaryPhaseInFlight,
              !originalAuxiliaryPhaseUncertain else {
#if DEBUG
            if originalAuxiliaryPhaseTracingForTesting {
                print("ORIGINAL_AUX_PHASE_V1 refusal=roster-projection-state")
            }
#endif
            throw EraseIntentStoreError.invalidAuthority
        }
        guard !borrowsColdObservation,
              originalAuxiliaryPublicationStarted,
              !originalAuxiliaryPublicationUncertain,
              originalAuxiliaryPublishedReceipt === receipt,
              receipt.store === self,
              receipt.checkedSettled,
              originalAuxiliaryActiveFD == nil,
              originalAuxiliaryUncertainFDs.isEmpty,
              originalAuxiliaryTemporaryDisposition != nil else {
#if DEBUG
            if originalAuxiliaryPhaseTracingForTesting {
                print("ORIGINAL_AUX_PHASE_V1 refusal=roster-publication-state")
            }
#endif
            throw EraseIntentStoreError.invalidAuthority
        }
#if DEBUG
        if originalAuxiliaryPhaseTracingForTesting {
            print("ORIGINAL_AUX_PHASE_V1 stage=roster-state-complete")
        }
#endif
        let names = ([Self.intentName, Self.preparationName,
            Self.auxiliaryRosterName] +
            (originalRetiredCommitmentReceipt == nil ? [] :
                [Self.originalRetiredCommitmentName]) +
            (originalRetiredStageIdentityReceipt == nil ? [] :
                [Self.originalRetiredStageIdentityName])).sorted()
        guard try requireOriginalAuxiliaryRoot(
                names: names, exact: projectedRoot)
                == projectedRoot else {
#if DEBUG
            if originalAuxiliaryPhaseTracingForTesting {
                print("ORIGINAL_AUX_PHASE_V1 refusal=roster-root-before")
            }
#endif
            throw EraseIntentStoreError.invalidAuthority
        }
#if DEBUG
        if originalAuxiliaryPhaseTracingForTesting {
            print("ORIGINAL_AUX_PHASE_V1 stage=roster-root-before-complete")
        }
#endif
        guard let leaf = try readOriginalAuxiliaryLeaf(
                Self.auxiliaryRosterName,
                maximumBytes: receipt.canonicalBytes.count),
              leaf.0 == receipt.canonicalBytes,
              leaf.1 == receipt.recordFact else {
#if DEBUG
            if originalAuxiliaryPhaseTracingForTesting {
                print("ORIGINAL_AUX_PHASE_V1 refusal=roster-leaf")
            }
#endif
            throw EraseIntentStoreError.invalidAuthority
        }
#if DEBUG
        if originalAuxiliaryPhaseTracingForTesting {
            print("ORIGINAL_AUX_PHASE_V1 stage=roster-leaf-complete")
        }
#endif
        guard try requireOriginalAuxiliaryRoot(
                names: names, exact: projectedRoot)
                == projectedRoot else {
#if DEBUG
            if originalAuxiliaryPhaseTracingForTesting {
                print("ORIGINAL_AUX_PHASE_V1 refusal=roster-root-after")
            }
#endif
            throw EraseIntentStoreError.invalidAuthority
        }
#if DEBUG
        if originalAuxiliaryPhaseTracingForTesting {
            print("ORIGINAL_AUX_PHASE_V1 stage=roster-root-after-complete")
        }
#endif
        try requireOriginalAuxiliaryControlLeaves(
            intent: (projectedIntentBytes, projectedIntentFact),
            preparation: (receipt.preparationBytes,
                receipt.preparationFact))
#if DEBUG
        if originalAuxiliaryPhaseTracingForTesting {
            print("ORIGINAL_AUX_PHASE_V1 stage=roster-controls-complete")
        }
#endif
        let policy = try ProtectedFilePolicyV1
            .observeTemporalPolicyWithCheckedClose(
                .journal,
                at: applicationSupportURL
                    .appendingPathComponent(Self.directoryName,
                        isDirectory: true)
                    .appendingPathComponent(Self.auxiliaryRosterName),
                retainUncertainDescriptor: { uncertain in
                    self.originalAuxiliaryUncertainFDs.append(uncertain)
                })
        guard policy.device == UInt64(receipt.recordFact.device),
              policy.inode == UInt64(receipt.recordFact.inode),
              policy.linkCount == UInt64(receipt.recordFact.links),
              policy.backupExcluded == true,
              (policy.state == .strictComplete ||
                (policy.state == .pendingSimulatorRequest &&
                 originalAuxiliaryTemporaryDisposition
                    == .simulatorFileProtectionUnsupported)) else {
#if DEBUG
            if originalAuxiliaryPhaseTracingForTesting {
                print("ORIGINAL_AUX_PHASE_V1 refusal=roster-policy")
            }
#endif
            throw EraseIntentStoreError.invalidAuthority
        }
#if DEBUG
        if originalAuxiliaryPhaseTracingForTesting {
            print("ORIGINAL_AUX_PHASE_V1 stage=roster-policy-complete")
        }
#endif
        guard try requireOriginalAuxiliaryRoot(
                names: names, exact: projectedRoot)
                == projectedRoot else {
#if DEBUG
            if originalAuxiliaryPhaseTracingForTesting {
                print("ORIGINAL_AUX_PHASE_V1 refusal=roster-final-root")
            }
#endif
            throw EraseIntentStoreError.invalidAuthority
        }
#if DEBUG
        if originalAuxiliaryPhaseTracingForTesting {
            print("ORIGINAL_AUX_PHASE_V1 stage=roster-reproof-complete")
        }
#endif
    }

    /// This accepts only the original, retained prepared-P owner. It is a
    /// prospective record before any target pointer or auxiliary mutation;
    /// an observed R survivor cut never enters this writer.
    func publishOriginalEraseAuxiliaryRoster(
        seal: EraseSchema2OriginalAuxiliaryRosterPublicationSealV1,
        intent: EraseIntentV1,
        preparation: ErasePreparationV2,
        operation: EraseRouterOperationV1,
        coordinator: StoreSessionCoordinator
    ) throws -> OriginalAuxiliaryRosterPublicationReceiptV1 {
        guard !borrowsColdObservation,
              !originalAuxiliaryPublicationStarted,
              originalAuxiliaryPublishedReceipt == nil,
              originalAuxiliaryActiveFD == nil,
              originalAuxiliaryUncertainFDs.isEmpty,
              !originalAuxiliaryPublicationUncertain,
              intent.schemaVersion == 2,
              intent.phase == .emptyGenerationPrepared,
              preparation.matches(intent),
              !seal.canonicalBytes.isEmpty,
              seal.canonicalSHA256 ==
                StoreMigrationCanonicalJSONV1.sha256(seal.canonicalBytes),
              seal.canonicalBytes.count <= Self.maximumJournalBytes else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try operation.requireOriginalAuxiliaryRosterSourceFactsBeforeRename(
            seal: seal, store: self)
        let initialNames = [Self.intentName,
            Self.preparationName].sorted()
        let temporaryNames = [Self.intentName,
            Self.preparationName,
            Self.auxiliaryRosterNextName].sorted()
        let publishedNames = [Self.intentName,
            Self.preparationName,
            Self.auxiliaryRosterName].sorted()
        let beforeRoot = try requireOriginalAuxiliaryRoot(
            names: initialNames, exact: nil)
        guard let firstIntent = try readOriginalAuxiliaryLeaf(
                Self.intentName, maximumBytes: Self.maximumJournalBytes),
              let firstPreparation = try readOriginalAuxiliaryLeaf(
                Self.preparationName,
                maximumBytes: Self.maximumJournalBytes),
              firstIntent.0 == (try encode(intent)),
              firstPreparation.0 == (try encodePreparation(preparation)),
              try requireOriginalAuxiliaryRoot(
                names: initialNames, exact: beforeRoot) == beforeRoot else {
            throw EraseIntentStoreError.invalidAuthority
        }
        originalAuxiliaryPublicationStarted = true
        let eraseURL = applicationSupportURL
            .appendingPathComponent(Self.directoryName, isDirectory: true)
        // A checked complete request may authenticate an exact pinned DEBUG
        // Simulator policy disposition. Raw pending is never publication
        // authority, and every request is bracketed by the first full cut.
        for (name, kind, bytes, fact) in [
            (Self.intentName, OwnedFileKindV1.journal,
                firstIntent.0, firstIntent.1),
            (Self.preparationName, OwnedFileKindV1.journal,
                firstPreparation.0, firstPreparation.1),
        ] {
            _ = try ProtectedFilePolicyV1
                .verifyEraseColdTemporalPolicyWithCheckedRequest(
                    kind, at: eraseURL.appendingPathComponent(name),
                    retainUncertainDescriptor: { descriptor in
                        self.originalAuxiliaryUncertainFDs.append(descriptor)
                    }, unchangedWitness: {
                        guard try self.requireOriginalAuxiliaryRoot(
                                names: initialNames,
                                exact: beforeRoot) == beforeRoot,
                              let leaf = try self.readOriginalAuxiliaryLeaf(
                                name, maximumBytes: bytes.count),
                              leaf.0 == bytes,
                              leaf.1 == fact else {
                            throw EraseIntentStoreError.invalidAuthority
                        }
                        return fact
                    })
        }
        _ = try ProtectedFilePolicyV1
            .verifyEraseColdTemporalPolicyWithCheckedRequest(
                .stagingDirectory, at: eraseURL,
                retainUncertainDescriptor: { descriptor in
                    self.originalAuxiliaryUncertainFDs.append(descriptor)
                }, unchangedWitness: {
                    try self.requireOriginalAuxiliaryRoot(
                        names: initialNames, exact: beforeRoot)
                })
        try operation.requireOriginalAuxiliaryRosterSourceFactsBeforeRename(
            seal: seal, store: self)
        guard try requireOriginalAuxiliaryRoot(
                names: initialNames, exact: beforeRoot) == beforeRoot else {
            throw EraseIntentStoreError.invalidAuthority
        }

        // From here even an O_EXCL failure leaves this one publication
        // attempt terminal. Retain every ambiguous close rather than retrying
        // a numeric descriptor or reading a replacement as our own temp.
        do {
            let descriptor = Darwin.openat(eraseDescriptor,
                Self.auxiliaryRosterNextName,
                O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW | O_CLOEXEC,
                mode_t(0o600))
            guard descriptor >= 0 else {
                throw EraseIntentStoreError.writeFailed
            }
            originalAuxiliaryActiveFD = descriptor
            let identity = try Self.fileIdentity(descriptor)
            let afterOpenRoot = try
                projectOriginalAuxiliaryRootAfterOwnedNameEffect(
                    prior: beforeRoot,
                    names: temporaryNames, allowActive: true)
            try requireOriginalAuxiliaryActiveTemporary(
                descriptor: descriptor, identity: identity,
                names: temporaryNames)
            originalAuxiliaryTemporaryDisposition = try ProtectedFilePolicyV1
                .applyAndVerifyEraseColdPrivateWithCheckedClose(
                    .journalTemporary,
                    at: eraseURL.appendingPathComponent(
                        Self.auxiliaryRosterNextName),
                    retainUncertainDescriptor: { uncertain in
                        self.originalAuxiliaryUncertainFDs.append(uncertain)
                    }, authorityCheck: {
                        try self.requireOriginalAuxiliaryActiveTemporary(
                            descriptor: descriptor, identity: identity,
                            names: temporaryNames)
                    }, beforeFirstEffect: {
                        try self.requireOriginalAuxiliaryActiveTemporary(
                            descriptor: descriptor, identity: identity,
                            names: temporaryNames)
                    })
            guard try requireOriginalAuxiliaryRoot(
                names: temporaryNames, exact: afterOpenRoot,
                allowActive: true) == afterOpenRoot else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try seal.canonicalBytes.withUnsafeBytes { raw in
                guard let base = raw.baseAddress else {
                    throw EraseIntentStoreError.writeFailed
                }
                var offset = 0
                while offset < raw.count {
                    let count = Darwin.write(descriptor,
                        base.advanced(by: offset), raw.count - offset)
                    if count > 0 { offset += count }
                    else if errno != EINTR {
                        throw EraseIntentStoreError.writeFailed
                    }
                }
            }
            guard Darwin.fsync(descriptor) == 0 else {
                throw EraseIntentStoreError.writeFailed
            }
            try closeOriginalAuxiliaryActiveChecked()
            let afterTemporaryRoot = try requireOriginalAuxiliaryRoot(
                names: temporaryNames, exact: afterOpenRoot)
            guard let temporary = try readOriginalAuxiliaryLeaf(
                    Self.auxiliaryRosterNextName,
                    maximumBytes: seal.canonicalBytes.count),
                  temporary.0 == seal.canonicalBytes,
                  temporary.1.device == identity.device,
                  temporary.1.inode == identity.inode,
                  temporary.1.mode & S_IFMT == S_IFREG,
                  temporary.1.links == 1,
                  try requireOriginalAuxiliaryRoot(
                    names: temporaryNames,
                    exact: afterTemporaryRoot) == afterTemporaryRoot else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try operation.requireOriginalAuxiliaryRosterSourceFactsBeforeRename(
                seal: seal, store: self)
            try requireOriginalAuxiliaryControlLeaves(
                intent: firstIntent, preparation: firstPreparation)
            guard try requireOriginalAuxiliaryRoot(
                    names: temporaryNames,
                    exact: afterTemporaryRoot) == afterTemporaryRoot,
                  Darwin.renameatx_np(eraseDescriptor,
                    Self.auxiliaryRosterNextName,
                    eraseDescriptor, Self.auxiliaryRosterName,
                    UInt32(RENAME_EXCL)) == 0,
                  Darwin.fsync(eraseDescriptor) == 0 else {
                throw EraseIntentStoreError.writeFailed
            }
            let afterPublishedRoot = try
                projectOriginalAuxiliaryRootAfterOwnedNameEffect(
                    prior: afterTemporaryRoot,
                    names: publishedNames, allowActive: false)
            guard let published = try readOriginalAuxiliaryLeaf(
                    Self.auxiliaryRosterName,
                    maximumBytes: seal.canonicalBytes.count),
                  published.0 == seal.canonicalBytes,
                  published.1.device == temporary.1.device,
                  published.1.inode == temporary.1.inode,
                  published.1.mode == temporary.1.mode,
                  published.1.links == temporary.1.links,
                  published.1.size == temporary.1.size,
                  try requireOriginalAuxiliaryRoot(
                    names: publishedNames,
                    exact: afterPublishedRoot) == afterPublishedRoot else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let publishedPolicy = try ProtectedFilePolicyV1
                .observeTemporalPolicyWithCheckedClose(
                    .journal,
                    at: eraseURL.appendingPathComponent(
                        Self.auxiliaryRosterName),
                    retainUncertainDescriptor: { uncertain in
                        self.originalAuxiliaryUncertainFDs.append(uncertain)
                    })
            guard publishedPolicy.device == UInt64(published.1.device),
                  publishedPolicy.inode == UInt64(published.1.inode),
                  publishedPolicy.linkCount == UInt64(published.1.links),
                  publishedPolicy.backupExcluded == true,
                  (publishedPolicy.state == .strictComplete ||
                    (publishedPolicy.state == .pendingSimulatorRequest &&
                     originalAuxiliaryTemporaryDisposition
                        == .simulatorFileProtectionUnsupported)),
                  try requireOriginalAuxiliaryRoot(
                    names: publishedNames,
                    exact: afterPublishedRoot) == afterPublishedRoot else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try operation.requireOriginalAuxiliaryRosterSourceFactsBeforeRename(
                seal: seal, store: self)
            try requireOriginalAuxiliaryControlLeaves(
                intent: firstIntent, preparation: firstPreparation)
            guard try requireOriginalAuxiliaryRoot(
                    names: publishedNames,
                    exact: afterPublishedRoot) == afterPublishedRoot else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let receipt = OriginalAuxiliaryRosterPublicationReceiptV1(
                store: self, operation: operation, seal: seal,
                beforeRoot: beforeRoot,
                afterRoot: afterPublishedRoot,
                recordFact: published.1,
                intent: firstIntent,
                preparation: firstPreparation)
            originalAuxiliaryProjectedIntentBytes = firstIntent.0
            originalAuxiliaryProjectedIntentFact = firstIntent.1
            originalAuxiliaryPublishedReceipt = receipt
            return receipt
        } catch {
            let failure = error
            if originalAuxiliaryActiveFD != nil {
                do { try closeOriginalAuxiliaryActiveChecked() }
                catch {
                    originalAuxiliaryPublicationUncertain = true
                    throw error
                }
            }
            originalAuxiliaryPublicationUncertain = true
            throw failure
        }
    }
}

// The ordinary Store initializer may create FieldEvidenceErase and its load()
// may promote or unlink a pending leaf. Original recovery needs the opposite
// contract before its first source validation: a complete, no-create witness
// under the already retained Support-root EX.
extension EraseIntentStore {
    struct OriginalRecoveryObservation: Equatable {
        fileprivate struct Ownership: Equatable {
            let user: uid_t
            let group: gid_t

            init(_ value: stat) {
                user = value.st_uid
                group = value.st_gid
            }
        }
        fileprivate struct Leaf: Equatable {
            let name: String
            let fact: RetirementLeafFact
            let ownership: Ownership
            let data: Data
            let policy: TemporalPolicyObservationV1
        }
        let supportDevice: Int64
        let supportInode: UInt64
        fileprivate let supportFact: RetirementLeafFact
        fileprivate let supportOwnership: Ownership
        fileprivate let supportNames: [String]
        fileprivate let eraseFact: RetirementLeafFact?
        fileprivate let eraseOwnership: Ownership?
        fileprivate let erasePolicy: TemporalPolicyObservationV1?
        fileprivate let eraseNames: [String]
        fileprivate let leaves: [Leaf]
        let intent: EraseIntentV1?
        let preparation: ErasePreparationV2?

        /// Bind the additional physical leaf to the already published
        /// original-operation P roster. Its presence alone is data, never
        /// authority to reconstruct a roster from current survivors.
        @MainActor
        func requireOriginalAuxiliaryRoster(
            _ receipt: OriginalAuxiliaryRosterPublicationReceiptV1,
            store: EraseIntentStore,
            operation: EraseRouterOperationV1,
            seal: EraseSchema2OriginalAuxiliaryRosterPublicationSealV1
        ) throws {
            try receipt.requireBound(store: store, operation: operation,
                seal: seal)
            guard let leaf = leaves.first(where: {
                    $0.name == EraseIntentStore.auxiliaryRosterName
                }),
                (eraseNames == [EraseIntentStore.intentName,
                    EraseIntentStore.preparationName,
                    EraseIntentStore.auxiliaryRosterName].sorted() ||
                 eraseNames == [EraseIntentStore.intentName,
                    EraseIntentStore.preparationName,
                    EraseIntentStore.auxiliaryRosterName,
                    EraseIntentStore.originalRetiredCommitmentName].sorted() ||
                 eraseNames == [EraseIntentStore.intentName,
                    EraseIntentStore.preparationName,
                    EraseIntentStore.auxiliaryRosterName,
                    EraseIntentStore.originalRetiredCommitmentName,
                    EraseIntentStore.originalRetiredStageIdentityName].sorted()),
                leaf.data == receipt.canonicalBytes,
                leaf.fact.device == receipt.recordFact.device,
                leaf.fact.inode == receipt.recordFact.inode,
                leaf.fact.mode == receipt.recordFact.mode,
                leaf.fact.links == receipt.recordFact.links,
                leaf.fact.size == receipt.recordFact.size,
                leaf.fact.modifiedSeconds ==
                    receipt.recordFact.modifiedSeconds,
                leaf.fact.modifiedNanoseconds ==
                    receipt.recordFact.modifiedNanoseconds,
                leaf.fact.changedSeconds ==
                    receipt.recordFact.changedSeconds,
                leaf.fact.changedNanoseconds ==
                    receipt.recordFact.changedNanoseconds,
                leaf.ownership.user == Darwin.getuid(),
                leaf.ownership.group == Darwin.getgid() else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }

        /// Data-only cold replay projection. A matching durable record does
        /// not adopt a Data temp or mint a new original operation capability.
        func observedOriginalRetiredCommitment()
            throws -> OriginalRecoveryRetiredCommitmentRecordV1? {
            guard let leaf = leaves.first(where: {
                $0.name == EraseIntentStore.originalRetiredCommitmentName
            }) else { return nil }
            let record = try OriginalRecoveryRetiredCommitmentRecordV1
                .decodeCanonical(leaf.data)
            typealias Fact = OriginalRecoveryRetiredCommitmentRecordV1.Fact
            func fact(_ leaf: Leaf) -> Fact {
                Fact(device: leaf.fact.device, inode: leaf.fact.inode,
                    mode: leaf.fact.mode, links: leaf.fact.links,
                    user: leaf.ownership.user, group: leaf.ownership.group,
                    size: leaf.fact.size,
                    modifiedSeconds: leaf.fact.modifiedSeconds,
                    modifiedNanoseconds: leaf.fact.modifiedNanoseconds,
                    changedSeconds: leaf.fact.changedSeconds,
                    changedNanoseconds: leaf.fact.changedNanoseconds)
            }
            guard let intent,
                  intent.schemaVersion == 2,
                  intent.phase == .emptyGenerationPrepared,
                  record.eraseID == intent.eraseID.uuidString.lowercased(),
                  record.sourceGenerationID
                    == intent.oldGenerationID.uuidString.lowercased(),
                  record.targetGenerationID
                    == intent.newGenerationID.uuidString.lowercased(),
                  record.support.device == supportDevice,
                  record.support.inode == supportInode,
                  record.support == Fact(device: supportFact.device,
                    inode: supportFact.inode, mode: supportFact.mode,
                    links: supportFact.links,
                    user: supportOwnership.user,
                    group: supportOwnership.group,
                    size: supportFact.size,
                    modifiedSeconds: supportFact.modifiedSeconds,
                    modifiedNanoseconds: supportFact.modifiedNanoseconds,
                    changedSeconds: supportFact.changedSeconds,
                    changedNanoseconds: supportFact.changedNanoseconds),
                  record.supportNames == supportNames,
                  ((record.firstEraseNames +
                    [EraseIntentStore.originalRetiredCommitmentName]).sorted()
                    == eraseNames ||
                   (record.firstEraseNames +
                    [EraseIntentStore.originalRetiredCommitmentName,
                     EraseIntentStore.originalRetiredStageIdentityName])
                    .sorted() == eraseNames),
                  let eraseFact,
                  record.erase.device == Int64(eraseFact.device),
                  record.erase.inode == UInt64(eraseFact.inode),
                  record.erase.mode == UInt32(eraseFact.mode),
                  let p = leaves.first(where: {
                    $0.name == EraseIntentStore.intentName }),
                  let preparation = leaves.first(where: {
                    $0.name == EraseIntentStore.preparationName }),
                  let roster = leaves.first(where: {
                    $0.name == EraseIntentStore.auxiliaryRosterName }),
                  p.data == record.intentBytes,
                  fact(p) == record.intentFact,
                  preparation.data == record.preparationBytes,
                  fact(preparation) == record.preparationFact,
                  roster.data == record.auxiliaryRosterBytes,
                  fact(roster) == record.auxiliaryRosterFact,
                  fact(leaf).device == Int64(eraseFact.device),
                  fact(leaf).size == Int64(leaf.data.count) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return record
        }

        /// Data-only cross-binding of the two durable Erase controls. A fresh
        /// owner must still prove the recorded Data inode under its own EX/G.
        func observedOriginalRetiredStageIdentity()
            throws -> OriginalRecoveryRetiredStageIdentityRecordV1? {
            guard let stageLeaf = leaves.first(where: {
                $0.name == EraseIntentStore.originalRetiredStageIdentityName
            }) else { return nil }
            guard let first = try observedOriginalRetiredCommitment(),
                  let commitmentLeaf = leaves.first(where: {
                    $0.name == EraseIntentStore.originalRetiredCommitmentName
                  }) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let record = try OriginalRecoveryRetiredStageIdentityRecordV1
                .decodeCanonical(stageLeaf.data)
            let fact = commitmentLeaf.fact
            let ownership = commitmentLeaf.ownership
            guard record.eraseID == first.eraseID,
                  record.commitmentSHA256 ==
                    StoreMigrationCanonicalJSONV1.sha256(
                        commitmentLeaf.data),
                  record.commitmentFact ==
                    OriginalRecoveryRetiredCommitmentRecordV1.Fact(
                        device: fact.device, inode: fact.inode,
                        mode: fact.mode, links: fact.links,
                        user: ownership.user, group: ownership.group,
                        size: fact.size,
                        modifiedSeconds: fact.modifiedSeconds,
                        modifiedNanoseconds: fact.modifiedNanoseconds,
                        changedSeconds: fact.changedSeconds,
                        changedNanoseconds: fact.changedNanoseconds),
                  record.replacementSHA256 == first.replacementSHA256,
                  record.firstDataFact == first.namespace.data,
                  record.firstDataChildren == [
                    OriginalRecoveryRetiredStageIdentityRecordV1.Child(
                        name: "current.json", kind: "regular",
                        fact: first.namespace.currentFact),
                    OriginalRecoveryRetiredStageIdentityRecordV1.Child(
                        name: "generations", kind: "directory",
                        fact: first.namespace.installedParent),
                    OriginalRecoveryRetiredStageIdentityRecordV1.Child(
                        name: "retired.json", kind: "regular",
                        fact: first.namespace.retiredFact)],
                  first.namespace.dataNames == ["current.json",
                    "generations", "retired.json"],
                  record.privateStageName == first.privateStageName,
                  record.canonicalTempName == first.canonicalTempName else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return record
        }

        /// Policy requests may change only the protection observation. The
        /// first held objects, complete physical facts, names and bytes stay
        /// fixed until the authenticated first-effect permit is consumed.
        fileprivate func samePhysicalNamespace(
            as prior: OriginalRecoveryObservation
        ) -> Bool {
            supportDevice == prior.supportDevice
                && supportInode == prior.supportInode
                && supportFact == prior.supportFact
                && supportOwnership == prior.supportOwnership
                && supportNames == prior.supportNames
                && eraseFact == prior.eraseFact
                && eraseOwnership == prior.eraseOwnership
                && eraseNames == prior.eraseNames
                && leaves.count == prior.leaves.count
                && zip(leaves, prior.leaves).allSatisfy { pair in
                    pair.0.name == pair.1.name
                        && pair.0.fact == pair.1.fact
                        && pair.0.ownership == pair.1.ownership
                        && pair.0.data == pair.1.data
                }
                && intent == prior.intent
                && preparation == prior.preparation
        }

        /// Only the Store's checked create/swap/unlink/fsync phase CAS may
        /// change Erase directory size and timestamps. Every stable parent
        /// field and every unrelated child remains the first exact object.
        fileprivate func sameOwnedFirstCASNonIntentNamespace(
            as prior: OriginalRecoveryObservation
        ) -> Bool {
            guard let beforeErase = prior.eraseFact,
                  let afterErase = eraseFact else { return false }
            return supportDevice == prior.supportDevice
                && supportInode == prior.supportInode
                && supportFact == prior.supportFact
                && supportOwnership == prior.supportOwnership
                && supportNames == prior.supportNames
                && afterErase.device == beforeErase.device
                && afterErase.inode == beforeErase.inode
                && afterErase.mode == beforeErase.mode
                && afterErase.links == beforeErase.links
                && eraseOwnership == prior.eraseOwnership
                && erasePolicy == prior.erasePolicy
                && eraseNames == prior.eraseNames
                && preparation == prior.preparation
                && leaves.filter { $0.name != EraseIntentStore.intentName }
                    == prior.leaves.filter { $0.name != EraseIntentStore.intentName }
        }

        /// This Store's O_EXCL/no-replace publication may add exactly its
        /// commitment leaf. The first three leaves and held Support identity
        /// remain byte-for-byte and full-fact identical.
        fileprivate func sameOwnedRetiredCommitmentNonRecordNamespace(
            as prior: OriginalRecoveryObservation
        ) -> Bool {
            guard let beforeErase = prior.eraseFact,
                  let afterErase = eraseFact else { return false }
            return supportDevice == prior.supportDevice
                && supportInode == prior.supportInode
                && supportFact == prior.supportFact
                && supportOwnership == prior.supportOwnership
                && supportNames == prior.supportNames
                && afterErase.device == beforeErase.device
                && afterErase.inode == beforeErase.inode
                && afterErase.mode == beforeErase.mode
                && eraseOwnership == prior.eraseOwnership
                && erasePolicy == prior.erasePolicy
                && eraseNames == (prior.eraseNames +
                    [EraseIntentStore.originalRetiredCommitmentName]).sorted()
                && leaves.filter {
                    $0.name != EraseIntentStore.originalRetiredCommitmentName
                } == prior.leaves
                && intent == prior.intent
                && preparation == prior.preparation
        }

        fileprivate func sameOwnedRetiredStageNonRecordNamespace(
            as prior: OriginalRecoveryObservation
        ) -> Bool {
            guard let beforeErase = prior.eraseFact,
                  let afterErase = eraseFact else { return false }
            return supportDevice == prior.supportDevice
                && supportInode == prior.supportInode
                && supportFact == prior.supportFact
                && supportOwnership == prior.supportOwnership
                && supportNames == prior.supportNames
                && afterErase.device == beforeErase.device
                && afterErase.inode == beforeErase.inode
                && afterErase.mode == beforeErase.mode
                && eraseOwnership == prior.eraseOwnership
                && erasePolicy == prior.erasePolicy
                && eraseNames == (prior.eraseNames +
                    [EraseIntentStore.originalRetiredStageIdentityName]).sorted()
                && leaves.filter {
                    $0.name != EraseIntentStore.originalRetiredStageIdentityName
                } == prior.leaves
                && intent == prior.intent
                && preparation == prior.preparation
        }
    }

    /// Only the held Store's completed P→Q CAS can mint this receipt. The
    /// exact postimage is then independently reobserved by the original owner
    /// before it closes its first-effect Store and releases G.
    struct OriginalRecoveryFirstPointerCASReceiptV1 {
        fileprivate let store: EraseIntentStore
        fileprivate let before: OriginalRecoveryObservation
        fileprivate let after: OriginalRecoveryObservation

        fileprivate init(store: EraseIntentStore,
                         before: OriginalRecoveryObservation,
                         after: OriginalRecoveryObservation) {
            self.store = store; self.before = before; self.after = after
        }

        func requirePublishedObservation(
            _ observed: OriginalRecoveryObservation,
            expected: OriginalRecoveryObservation,
            store: EraseIntentStore
        ) throws {
            guard self.store === store,
                  before == expected,
                  after == observed,
                  observed.sameOwnedFirstCASNonIntentNamespace(as: expected),
                  let intent = expected.intent,
                  observed.intent == intent.advancing(to: .pointerSwitched),
                  observed.eraseNames == expected.eraseNames else {
                throw EraseIntentStoreError.invalidAuthority
            }
        }
    }

    @MainActor
    final class OriginalRecoveryRetiredCommitmentReceiptV1 {
        struct EraseProjectionV1 {
            let beforeRoot: OriginalRecoveryRetiredCommitmentRecordV1.Fact
            let afterRoot: EraseColdControlLeafFactV1
            let firstNames: [String]
            let publishedNames: [String]
            let recordBytes: Data
            let recordFact: EraseColdControlLeafFactV1
        }
        fileprivate weak var store: EraseIntentStore?
        fileprivate weak var operation: EraseRouterOperationV1?
        fileprivate weak var owner: StoreOriginalEraseRecoveryPreOpenOwnerV1?
        fileprivate let namespace: OriginalEraseRecoveryNamespaceSnapshotV1
        fileprivate let replacementBytes: Data
        fileprivate let record: OriginalRecoveryRetiredCommitmentRecordV1
        fileprivate let canonicalBytes: Data
        fileprivate let recordFact: EraseColdControlLeafFactV1
        fileprivate let first: OriginalRecoveryObservation
        fileprivate let published: OriginalRecoveryObservation
        fileprivate let projectedRoot: EraseColdControlLeafFactV1
        fileprivate let support: StoreTemporalPhysicalRootExclusionV1
        fileprivate let checkedSettled: Bool

        fileprivate init(store: EraseIntentStore,
            operation: EraseRouterOperationV1,
            owner: StoreOriginalEraseRecoveryPreOpenOwnerV1,
            namespace: OriginalEraseRecoveryNamespaceSnapshotV1,
            replacementBytes: Data,
            record: OriginalRecoveryRetiredCommitmentRecordV1,
            canonicalBytes: Data,
            recordFact: EraseColdControlLeafFactV1,
            first: OriginalRecoveryObservation,
            published: OriginalRecoveryObservation,
            projectedRoot: EraseColdControlLeafFactV1,
            support: StoreTemporalPhysicalRootExclusionV1) {
            self.store = store; self.operation = operation
            self.owner = owner; self.namespace = namespace
            self.replacementBytes = replacementBytes
            self.record = record; self.canonicalBytes = canonicalBytes
            self.recordFact = recordFact
            self.first = first; self.published = published
            self.projectedRoot = projectedRoot
            self.support = support
            checkedSettled = true
        }

        func requireBound(operation: EraseRouterOperationV1,
            owner: StoreOriginalEraseRecoveryPreOpenOwnerV1,
            namespace: OriginalEraseRecoveryNamespaceSnapshotV1,
            replacementBytes: Data) throws {
            guard self.operation === operation, self.owner === owner,
                  self.namespace == namespace,
                  self.replacementBytes == replacementBytes,
                  checkedSettled, let store else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try store.requireOriginalRecoveryRetiredCommitment(self)
        }

        func requirePublishedObservation(
            firstObservation: OriginalRecoveryObservation,
            operation: EraseRouterOperationV1,
            owner: StoreOriginalEraseRecoveryPreOpenOwnerV1,
            namespace: OriginalEraseRecoveryNamespaceSnapshotV1,
            replacementBytes: Data
        ) throws -> OriginalRecoveryObservation {
            try requireBound(operation: operation, owner: owner,
                namespace: namespace, replacementBytes: replacementBytes)
            guard first == firstObservation, let store,
                  let io = store.originalRecoveryCheckedIO else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let observed = try EraseIntentStore.observeOriginalRecoveryNoCreate(
                support: support,
                applicationSupportURL: store.applicationSupportURL,
                io: io,
                retainUncertainDescriptor: { [store] in
                    store.retainOriginalRecoveryUncertainDescriptor($0)
                })
            guard observed == published,
                  observed.sameOwnedRetiredCommitmentNonRecordNamespace(
                    as: first) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return observed
        }

        func requireEraseProjection(
            operation: EraseRouterOperationV1,
            owner: StoreOriginalEraseRecoveryPreOpenOwnerV1,
            namespace: OriginalEraseRecoveryNamespaceSnapshotV1,
            replacementBytes: Data
        ) throws -> EraseProjectionV1 {
            try requireBound(operation: operation, owner: owner,
                namespace: namespace, replacementBytes: replacementBytes)
            return EraseProjectionV1(beforeRoot: record.erase,
                afterRoot: projectedRoot,
                firstNames: record.firstEraseNames,
                publishedNames: published.eraseNames,
                recordBytes: canonicalBytes, recordFact: recordFact)
        }

        func requireReservedDataStageNames(
            operation: EraseRouterOperationV1,
            owner: StoreOriginalEraseRecoveryPreOpenOwnerV1,
            namespace: OriginalEraseRecoveryNamespaceSnapshotV1,
            replacementBytes: Data
        ) throws -> (privateStageName: String,
                     canonicalTempName: String) {
            try requireBound(operation: operation, owner: owner,
                namespace: namespace, replacementBytes: replacementBytes)
            guard record.firstPrivateStageAbsent,
                  record.firstCanonicalTempAbsent,
                  !namespace.dataNames.contains(record.privateStageName),
                  !namespace.dataNames.contains(record.canonicalTempName) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return (record.privateStageName, record.canonicalTempName)
        }
    }

    @MainActor
    final class OriginalRecoveryRetiredStageIdentityReceiptV1 {
        fileprivate weak var store: EraseIntentStore?
        fileprivate weak var operation: EraseRouterOperationV1?
        fileprivate weak var owner: StoreOriginalEraseRecoveryPreOpenOwnerV1?
        fileprivate weak var commitment:
            OriginalRecoveryRetiredCommitmentReceiptV1?
        fileprivate weak var stage: OriginalEraseRecoveryRetiredStageReceiptV1?
        fileprivate let namespace: OriginalEraseRecoveryNamespaceSnapshotV1
        fileprivate let replacementBytes: Data
        fileprivate let record: OriginalRecoveryRetiredStageIdentityRecordV1
        fileprivate let canonicalBytes: Data
        fileprivate let recordFact: EraseColdControlLeafFactV1
        fileprivate let first: OriginalRecoveryObservation
        fileprivate let published: OriginalRecoveryObservation
        fileprivate let projectedRoot: EraseColdControlLeafFactV1
        fileprivate let support: StoreTemporalPhysicalRootExclusionV1
        fileprivate let checkedSettled: Bool

        fileprivate init(store: EraseIntentStore,
            operation: EraseRouterOperationV1,
            owner: StoreOriginalEraseRecoveryPreOpenOwnerV1,
            commitment: OriginalRecoveryRetiredCommitmentReceiptV1,
            stage: OriginalEraseRecoveryRetiredStageReceiptV1,
            namespace: OriginalEraseRecoveryNamespaceSnapshotV1,
            replacementBytes: Data,
            record: OriginalRecoveryRetiredStageIdentityRecordV1,
            canonicalBytes: Data,
            recordFact: EraseColdControlLeafFactV1,
            first: OriginalRecoveryObservation,
            published: OriginalRecoveryObservation,
            projectedRoot: EraseColdControlLeafFactV1,
            support: StoreTemporalPhysicalRootExclusionV1) {
            self.store = store; self.operation = operation
            self.owner = owner; self.commitment = commitment
            self.stage = stage; self.namespace = namespace
            self.replacementBytes = replacementBytes
            self.record = record; self.canonicalBytes = canonicalBytes
            self.recordFact = recordFact
            self.first = first; self.published = published
            self.projectedRoot = projectedRoot; self.support = support
            checkedSettled = true
        }

        func requireBound(operation: EraseRouterOperationV1,
            owner: StoreOriginalEraseRecoveryPreOpenOwnerV1,
            commitment: OriginalRecoveryRetiredCommitmentReceiptV1,
            stage: OriginalEraseRecoveryRetiredStageReceiptV1,
            namespace: OriginalEraseRecoveryNamespaceSnapshotV1,
            replacementBytes: Data) throws {
            guard self.operation === operation, self.owner === owner,
                  self.commitment === commitment, self.stage === stage,
                  self.namespace == namespace,
                  self.replacementBytes == replacementBytes,
                  checkedSettled, let store else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try store.requireOriginalRecoveryRetiredStageIdentity(self)
        }

        func requirePublishedObservation(
            firstObservation: OriginalRecoveryObservation,
            operation: EraseRouterOperationV1,
            owner: StoreOriginalEraseRecoveryPreOpenOwnerV1,
            commitment: OriginalRecoveryRetiredCommitmentReceiptV1,
            stage: OriginalEraseRecoveryRetiredStageReceiptV1,
            namespace: OriginalEraseRecoveryNamespaceSnapshotV1,
            replacementBytes: Data
        ) throws -> OriginalRecoveryObservation {
            try requireBound(operation: operation, owner: owner,
                commitment: commitment, stage: stage,
                namespace: namespace, replacementBytes: replacementBytes)
            guard first == firstObservation, let store,
                  let io = store.originalRecoveryCheckedIO else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let observed = try EraseIntentStore.observeOriginalRecoveryNoCreate(
                support: support,
                applicationSupportURL: store.applicationSupportURL,
                io: io,
                retainUncertainDescriptor: { [store] in
                    store.retainOriginalRecoveryUncertainDescriptor($0)
                })
            guard observed == published,
                  observed.sameOwnedRetiredStageNonRecordNamespace(
                    as: first) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return observed
        }
    }

    @MainActor
    static func observeOriginalRecoveryNoCreate(
        support: StoreTemporalPhysicalRootExclusionV1,
        applicationSupportURL: URL,
        io: EraseAbortCheckedSnapshotIOV1,
        retainUncertainDescriptor: (Int32) -> Void
    ) throws -> OriginalRecoveryObservation {
        try io.requireSettled()
        let result = try support.withOriginalEraseRecoverySupport(
            at: applicationSupportURL) { supportFD -> OriginalRecoveryObservation in
            var heldSupport = stat(), namedSupport = stat()
            guard Darwin.fstat(supportFD, &heldSupport) == 0,
                  Darwin.lstat(applicationSupportURL.path, &namedSupport) == 0,
                  heldSupport.st_mode & S_IFMT == S_IFDIR,
                  RetirementLeafFact(namedSupport)
                    == RetirementLeafFact(heldSupport),
                  OriginalRecoveryObservation.Ownership(namedSupport)
                    == OriginalRecoveryObservation.Ownership(heldSupport) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let supportFact = RetirementLeafFact(heldSupport)
            let supportOwnership = OriginalRecoveryObservation.Ownership(heldSupport)
            let supportNames = try io.names(in: supportFD)
            var namedErase = stat()
            if Darwin.fstatat(supportFD, directoryName,
                              &namedErase, AT_SYMLINK_NOFOLLOW) != 0 {
                guard errno == ENOENT,
                      !supportNames.contains(directoryName) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                var heldAfter = stat(), namedAfter = stat(), absent = stat()
                guard Darwin.fstat(supportFD, &heldAfter) == 0,
                      Darwin.lstat(applicationSupportURL.path,
                          &namedAfter) == 0,
                      RetirementLeafFact(heldAfter) == supportFact,
                      RetirementLeafFact(namedAfter) == supportFact,
                      OriginalRecoveryObservation.Ownership(heldAfter)
                        == supportOwnership,
                      OriginalRecoveryObservation.Ownership(namedAfter)
                        == supportOwnership,
                      try io.names(in: supportFD) == supportNames,
                      Darwin.fstatat(supportFD, directoryName,
                          &absent, AT_SYMLINK_NOFOLLOW) != 0,
                      errno == ENOENT else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                let observation = OriginalRecoveryObservation(
                    supportDevice: Int64(heldSupport.st_dev),
                    supportInode: UInt64(heldSupport.st_ino),
                    supportFact: supportFact,
                    supportOwnership: supportOwnership,
                    supportNames: supportNames,
                    eraseFact: nil, eraseOwnership: nil,
                    erasePolicy: nil,
                    eraseNames: [], leaves: [],
                    intent: nil, preparation: nil)
            }
            guard namedErase.st_mode & S_IFMT == S_IFDIR,
                  supportNames.contains(directoryName) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            return try io.withOpen(parent: supportFD, name: directoryName,
                                   flags: O_RDONLY | O_DIRECTORY) { eraseFD in
                var heldErase = stat()
                guard Darwin.fstat(eraseFD, &heldErase) == 0,
                      RetirementLeafFact(namedErase) == RetirementLeafFact(heldErase),
                      OriginalRecoveryObservation.Ownership(namedErase)
                        == OriginalRecoveryObservation.Ownership(heldErase) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                let eraseFact = RetirementLeafFact(heldErase)
                let eraseOwnership = OriginalRecoveryObservation.Ownership(heldErase)
                let eraseURL = applicationSupportURL.appendingPathComponent(directoryName)
                let names = try io.names(in: eraseFD)
                let erasePolicy = try ProtectedFilePolicyV1
                    .observeTemporalPolicyWithCheckedClose(
                        .stagingDirectory, at: eraseURL,
                        retainUncertainDescriptor: retainUncertainDescriptor)
                var policyHeldErase = stat(), policyNamedErase = stat()
                guard Darwin.fstat(eraseFD, &policyHeldErase) == 0,
                      Darwin.fstatat(supportFD, directoryName,
                          &policyNamedErase, AT_SYMLINK_NOFOLLOW) == 0,
                      RetirementLeafFact(policyHeldErase) == eraseFact,
                      RetirementLeafFact(policyNamedErase) == eraseFact,
                      OriginalRecoveryObservation.Ownership(policyHeldErase)
                        == eraseOwnership,
                      OriginalRecoveryObservation.Ownership(policyNamedErase)
                        == eraseOwnership,
                      try io.names(in: eraseFD) == names,
                      erasePolicy.device == UInt64(heldErase.st_dev),
                      erasePolicy.inode == UInt64(heldErase.st_ino),
                      erasePolicy.linkCount == UInt64(heldErase.st_nlink),
                      erasePolicy.mode == UInt16(heldErase.st_mode) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                // Pending leaves require a separate authenticated cut. This
                // read-only owner never promotes, unlinks or accepts them.
                guard Set(names).isSubset(of: [intentName,
                        preparationName, auxiliaryRosterName,
                        originalRetiredCommitmentName,
                        originalRetiredStageIdentityName]),
                      !names.contains(nextName),
                      !names.contains(preparationNextName) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                func readLeaf(_ name: String) throws -> OriginalRecoveryObservation.Leaf? {
                    let maximumBytes =
                        (name == auxiliaryRosterName ||
                         name == originalRetiredCommitmentName ||
                         name == originalRetiredStageIdentityName)
                        ? maximumJournalBytes * 3 : 1_048_576
                    var named = stat()
                    if Darwin.fstatat(eraseFD, name, &named,
                                      AT_SYMLINK_NOFOLLOW) != 0 {
                        guard errno == ENOENT, !names.contains(name) else {
                            throw EraseIntentStoreError.invalidAuthority
                        }
                        return nil
                    }
                    guard names.contains(name) else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    return try io.withOpen(parent: eraseFD, name: name,
                                           flags: O_RDONLY | O_NONBLOCK) { fileFD in
                        var before = stat(), after = stat(), namedAfter = stat()
                        guard Darwin.fstat(fileFD, &before) == 0,
                              RetirementLeafFact(before) == RetirementLeafFact(named),
                              OriginalRecoveryObservation.Ownership(before)
                                == OriginalRecoveryObservation.Ownership(named),
                              before.st_mode & S_IFMT == S_IFREG,
                              before.st_nlink == 1,
                              before.st_size >= 0,
                              before.st_size <= off_t(maximumBytes) else {
                            throw EraseIntentStoreError.invalidAuthority
                        }
                        var data = Data()
                        var buffer = [UInt8](repeating: 0, count: 16 * 1024)
                        while true {
                            let count = buffer.withUnsafeMutableBytes {
                                Darwin.read(fileFD, $0.baseAddress, $0.count)
                            }
                            if count > 0 {
                                guard data.count <= maximumBytes - count else {
                                    throw EraseIntentStoreError.invalidAuthority
                                }
                                data.append(contentsOf: buffer.prefix(count))
                            } else if count == 0 { break }
                            else if errno != EINTR {
                                throw EraseIntentStoreError.invalidAuthority
                            }
                        }
                        guard Darwin.fstat(fileFD, &after) == 0,
                              Darwin.fstatat(eraseFD, name, &namedAfter,
                                             AT_SYMLINK_NOFOLLOW) == 0,
                              RetirementLeafFact(before) == RetirementLeafFact(after),
                              RetirementLeafFact(before) == RetirementLeafFact(namedAfter),
                              OriginalRecoveryObservation.Ownership(before)
                                == OriginalRecoveryObservation.Ownership(after),
                              OriginalRecoveryObservation.Ownership(before)
                                == OriginalRecoveryObservation.Ownership(namedAfter),
                              data.count == Int(before.st_size) else {
                            throw EraseIntentStoreError.invalidAuthority
                        }
                        let policy = try ProtectedFilePolicyV1
                            .observeTemporalPolicyWithCheckedClose(
                                .journal, at: eraseURL.appendingPathComponent(name),
                                retainUncertainDescriptor: retainUncertainDescriptor)
                        var policyHeld = stat(), policyNamed = stat()
                        guard Darwin.fstat(fileFD, &policyHeld) == 0,
                              Darwin.fstatat(eraseFD, name, &policyNamed,
                                  AT_SYMLINK_NOFOLLOW) == 0,
                              RetirementLeafFact(policyHeld) == RetirementLeafFact(before),
                              RetirementLeafFact(policyNamed) == RetirementLeafFact(before),
                              OriginalRecoveryObservation.Ownership(policyHeld)
                                == OriginalRecoveryObservation.Ownership(before),
                              OriginalRecoveryObservation.Ownership(policyNamed)
                                == OriginalRecoveryObservation.Ownership(before),
                              try io.names(in: eraseFD) == names,
                              policy.device == UInt64(before.st_dev),
                              policy.inode == UInt64(before.st_ino),
                              policy.linkCount == UInt64(before.st_nlink),
                              policy.mode == UInt16(before.st_mode) else {
                            throw EraseIntentStoreError.invalidAuthority
                        }
                        return OriginalRecoveryObservation.Leaf(
                            name: name, fact: RetirementLeafFact(before),
                            ownership: OriginalRecoveryObservation.Ownership(before),
                            data: data, policy: policy)
                    }
                }
                let intentLeaf = try readLeaf(intentName)
                let preparationLeaf = try readLeaf(preparationName)
                let auxiliaryLeaf = try readLeaf(auxiliaryRosterName)
                let commitmentLeaf = try readLeaf(
                    originalRetiredCommitmentName)
                let stageIdentityLeaf = try readLeaf(
                    originalRetiredStageIdentityName)
                if let commitmentLeaf {
                    _ = try OriginalRecoveryRetiredCommitmentRecordV1
                        .decodeCanonical(commitmentLeaf.data)
                }
                if let stageIdentityLeaf {
                    guard commitmentLeaf != nil else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                    _ = try OriginalRecoveryRetiredStageIdentityRecordV1
                        .decodeCanonical(stageIdentityLeaf.data)
                }
                let intent = try intentLeaf.map { try EraseIntentCodecV1.decode($0.data) }
                let preparation = try preparationLeaf.map {
                    try ErasePreparationCodecV2.decode($0.data)
                }
                var namedEraseAfter = stat(), supportAfter = stat(),
                    namedSupportAfter = stat()
                guard Darwin.fstatat(supportFD, directoryName,
                                      &namedEraseAfter, AT_SYMLINK_NOFOLLOW) == 0,
                      Darwin.fstat(supportFD, &supportAfter) == 0,
                      Darwin.lstat(applicationSupportURL.path,
                          &namedSupportAfter) == 0,
                      RetirementLeafFact(namedEraseAfter) == eraseFact,
                      RetirementLeafFact(supportAfter) == supportFact,
                      RetirementLeafFact(namedSupportAfter) == supportFact,
                      OriginalRecoveryObservation.Ownership(namedEraseAfter)
                        == eraseOwnership,
                      OriginalRecoveryObservation.Ownership(supportAfter)
                        == supportOwnership,
                      OriginalRecoveryObservation.Ownership(namedSupportAfter)
                        == supportOwnership,
                      try io.names(in: eraseFD) == names,
                      try io.names(in: supportFD) == supportNames else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                let observation = OriginalRecoveryObservation(
                    supportDevice: Int64(heldSupport.st_dev),
                    supportInode: UInt64(heldSupport.st_ino),
                    supportFact: supportFact,
                    supportOwnership: supportOwnership,
                    supportNames: supportNames,
                    eraseFact: eraseFact, eraseOwnership: eraseOwnership,
                    erasePolicy: erasePolicy,
                    eraseNames: names,
                    leaves: [intentLeaf, preparationLeaf,
                        auxiliaryLeaf, commitmentLeaf,
                        stageIdentityLeaf].compactMap { $0 }
                        .sorted { $0.name < $1.name },
                    intent: intent, preparation: preparation)
                if stageIdentityLeaf != nil {
                    guard try observation.observedOriginalRetiredStageIdentity()
                        != nil else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                }
                return observation
            }
        }
        try io.requireSettled()
        return result
    }

    /// The first scan above is observation-only. Once the original owner has
    /// authenticated its P intent, preparation, private source and external
    /// controls, this exact G-held permit may request complete protection on
    /// the three first-captured Erase controls. Each request is bound to the
    /// same full physical facts and bytes; only its policy observation may be
    /// projected, and a raw pending observation is never effect authority.
    @MainActor
    static func completeOriginalRecoveryObservedPoliciesForFirstEffect(
        support: StoreTemporalPhysicalRootExclusionV1,
        applicationSupportURL: URL,
        io: EraseAbortCheckedSnapshotIOV1,
        expected: OriginalRecoveryObservation,
        permit: OriginalEraseRecoveryFirstEffectPermitV1,
        retainUncertainDescriptor: (Int32) -> Void
    ) throws -> OriginalRecoveryObservation {
        try permit.requireHeld()
        try io.requireSettled()
        guard expected.intent?.phase == .emptyGenerationPrepared,
              expected.eraseFact != nil,
              expected.erasePolicy != nil,
              expected.eraseNames.contains(intentName),
              Set(expected.eraseNames).isSubset(of: [intentName,
                  preparationName, auxiliaryRosterName,
                  originalRetiredCommitmentName,
                  originalRetiredStageIdentityName]),
              expected.eraseNames.contains(preparationName)
                == (expected.preparation != nil),
              expected.leaves.map(\.name) == expected.eraseNames else {
            throw EraseIntentStoreError.invalidAuthority
        }
        func read() throws -> OriginalRecoveryObservation {
            try observeOriginalRecoveryNoCreate(
                support: support, applicationSupportURL: applicationSupportURL,
                io: io, retainUncertainDescriptor: retainUncertainDescriptor)
        }
        var projected = expected
        guard try read() == expected else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let eraseURL = applicationSupportURL.appendingPathComponent(directoryName)
        let leafTargets: [(String?, OwnedFileKindV1, URL)] =
            expected.eraseNames.map { name in
                (name, OwnedFileKindV1.journal,
                 eraseURL.appendingPathComponent(name))
            }
        let targets: [(String?, OwnedFileKindV1, URL)] =
            [(nil, .stagingDirectory, eraseURL)] + leafTargets
        for (name, kind, url) in targets {
            try permit.requireHeld()
            guard try read() == projected else {
                throw EraseIntentStoreError.invalidAuthority
            }
            let disposition = try ProtectedFilePolicyV1
                .verifyEraseColdTemporalPolicyWithCheckedRequest(
                    kind, at: url,
                    retainUncertainDescriptor: retainUncertainDescriptor,
                    unchangedWitness: {
                        let observed = try read()
                        guard observed.samePhysicalNamespace(as: expected) else {
                            throw EraseIntentStoreError.invalidAuthority
                        }
                        return true
                    })
            let after = try read()
            guard after.samePhysicalNamespace(as: expected),
                  after.supportFact == projected.supportFact,
                  after.supportNames == projected.supportNames,
                  after.eraseNames == projected.eraseNames else {
                throw EraseIntentStoreError.invalidAuthority
            }
            if let name {
                guard after.erasePolicy == projected.erasePolicy,
                      after.leaves.count == projected.leaves.count else {
                    throw EraseIntentStoreError.invalidAuthority
                }
                for (old, updated) in zip(projected.leaves, after.leaves)
                    where old.name != name {
                    guard old == updated else {
                        throw EraseIntentStoreError.invalidAuthority
                    }
                }
                guard let updated = after.leaves.first(where: { $0.name == name }),
                      updated.policy.state ==
                        (disposition == .verifiedComplete
                            ? .strictComplete : .pendingSimulatorRequest) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            } else {
                guard after.leaves == projected.leaves,
                      after.erasePolicy?.state ==
                        (disposition == .verifiedComplete
                            ? .strictComplete : .pendingSimulatorRequest) else {
                    throw EraseIntentStoreError.invalidAuthority
                }
            }
            projected = after
        }
        try permit.requireHeld()
        try io.requireSettled()
        guard try read() == projected else {
            throw EraseIntentStoreError.invalidAuthority
        }
        return projected
    }
}

// DIAGNOSTICS_CLOSED_DURABLE_GRAMMAR_V4_BEGIN
/// Pure prospective V4 DATA. The incumbent Reader/Namespace decoders remain
/// exact and reject this separate domain; this codec cannot issue an effect.
enum ColdEraseSchema2DiagnosticsJournalCodecV4 {
    static let maximumRecipeBytes: UInt64 = 524_288
    private static var magic: Data {
        var value = Data("FE_COLD_FRAME_V1".utf8)
        value.append(Data(repeating: 0, count: 16 - value.count)); return value
    }
    struct Header: Equatable {
        let kind: ColdEraseControlBinaryV1.FrameHeader.Kind
        let sequence: UInt64
        let recipeBytes: UInt64
        let previousFrameSHA256: Data
        var changedFactCount: UInt64 { kind == .request ? 1 : 3 }
        var totalBytes: UInt64 { 1_024 + recipeBytes }
    }
    private static func append(_ word: UInt64, to data: inout Data) {
        var raw = word.littleEndian; withUnsafeBytes(of: &raw) { data.append(contentsOf: $0) }
    }
    private static func word(_ data: Data, _ offset: Int) throws -> UInt64 {
        guard offset >= 0, offset <= data.count - 8 else { throw EraseIntentStoreError.invalidAuthority }
        var value: UInt64 = 0
        for index in 0..<8 { value |= UInt64(data[data.startIndex + offset + index]) << UInt64(index * 8) }
        return value
    }
    static func frameHeader(kind: ColdEraseControlBinaryV1.FrameHeader.Kind,
        sequence: UInt64, recipeBytes: UInt64, previousFrameSHA256: Data) throws -> Data {
        guard sequence > 0, sequence <= ColdErasePostContentBinaryV4.maximumTaskCount,
              previousFrameSHA256.count == 32,
              (kind == .request && recipeBytes > 0 && recipeBytes <= maximumRecipeBytes)
                || (kind == .observation && recipeBytes == 0) else { throw EraseIntentStoreError.invalidAuthority }
        var data = magic
        for value in [UInt64(1), kind.rawValue, sequence, UInt64(1), UInt64(864), recipeBytes,
            kind == .request ? UInt64(1) : UInt64(3), UInt64(3)] { append(value, to: &data) }
        data.append(previousFrameSHA256); data.append(Data(repeating: 0, count: 16))
        guard data.count == 128 else { throw EraseIntentStoreError.invalidAuthority }
        return data
    }
    static func decodeFrameHeader(_ bytes: Data) throws -> Header {
        guard bytes.count == 128, Data(bytes.prefix(16)) == magic,
              try word(bytes, 16) == 1,
              let kind = ColdEraseControlBinaryV1.FrameHeader.Kind(rawValue: try word(bytes, 24)),
              try word(bytes, 40) == 1, try word(bytes, 48) == 864,
              try word(bytes, 72) == 3,
              bytes.suffix(16).allSatisfy({ $0 == 0 }) else { throw EraseIntentStoreError.invalidAuthority }
        let value = Header(kind: kind, sequence: try word(bytes, 32), recipeBytes: try word(bytes, 56),
            previousFrameSHA256: Data(bytes[bytes.startIndex + 80..<bytes.startIndex + 112]))
        guard try word(bytes, 64) == value.changedFactCount,
              try frameHeader(kind: kind, sequence: value.sequence, recipeBytes: value.recipeBytes,
                previousFrameSHA256: value.previousFrameSHA256) == bytes else { throw EraseIntentStoreError.invalidAuthority }
        return value
    }
    static func payload(_ value: ColdErasePostContentBinaryV2.PayloadFields) throws -> Data {
        try ColdErasePostContentBinaryV2.payloadFields(value)
    }
    static func decodePayload(_ bytes: Data, header: Header) throws -> ColdErasePostContentBinaryV2.PayloadFields {
        let value = try ColdErasePostContentBinaryV2.decodePayloadFields(bytes)
        let w = value.words
        guard w.count == 16, value.facts.count == 4, value.digests.count == 12,
              w[0] == 1, w[1] == 1, w[2] == 1,
              Double(bitPattern: w[3]).isFinite, w[4] >= 1_056,
              w[5] > 0, w[5] <= maximumRecipeBytes,
              w[4] <= ColdErasePostContentBinaryV4.maximumProgressBytes,
              w[7] <= UInt64(UInt32.max), w[8] <= UInt64(UInt32.max), w[12] <= UInt64(UInt32.max),
              w[9] == (header.kind == .request ? 1 : 2),
              w[14] == header.changedFactCount, w[15] == 0,
              value.facts[0][2] & UInt64(S_IFMT) == UInt64(S_IFDIR),
              value.facts[3].allSatisfy({ $0 == 0 }),
              value.digests[11].allSatisfy({ $0 == 0 }),
              value.digests[4] == value.digests[10],
              try payload(value) == bytes else { throw EraseIntentStoreError.invalidAuthority }
        if header.kind == .request {
            guard header.recipeBytes == w[5], w[6] == 0, w[8] == 0,
                  w[10] == 0, w[11] == 0, w[12] == 0, w[13] == 0,
                  value.facts[1].allSatisfy({ $0 == 0 }), value.facts[2].allSatisfy({ $0 == 0 }),
                  value.digests[2].allSatisfy({ $0 == 0 }),
                  value.digests[7].allSatisfy({ $0 == 0 }),
                  value.digests[8].allSatisfy({ $0 == 0 }) else { throw EraseIntentStoreError.invalidAuthority }
        } else {
            guard header.recipeBytes == 0, w[6] > 0, w[13] > 0,
                  value.facts[1][2] & UInt64(S_IFMT) == UInt64(S_IFDIR),
                  value.facts[2][2] & UInt64(S_IFMT) == UInt64(S_IFREG),
                  value.facts[2][2] & 0o7777 == 0o600,
                  value.facts[2][5] == 1, value.facts[2][6] == w[5] else { throw EraseIntentStoreError.invalidAuthority }
