        }
        guard Data(baseline.finalize()) == (try ColdEraseControlBinaryV1.rawSHA256(storage.before.sha256)),
              let initialFrame = storage.before.lastCompleteFrameSHA256 else { throw EraseIntentStoreError.invalidAuthority }
