            guard let headerBytes = rawHeader, headerBytes == actual.header else { throw EraseIntentStoreError.invalidAuthority }
            let header = try ColdEraseSchema2DiagnosticsJournalCodecV4.decodeFrameHeader(headerBytes)
            guard header.previousFrameSHA256 == previous, header.sequence == storage.before.requestCount + 1,
                  (index == 0 && header.kind == .request) || (index == 1 && header.kind == .observation) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try io.withRead(offset: offset + 128, count: 864) { rawPayload = Data($0) }
            guard let bytes = rawPayload, bytes == actual.payload else { throw EraseIntentStoreError.invalidAuthority }
            let fields = try ColdEraseSchema2DiagnosticsJournalCodecV4.decodePayload(bytes, header: header)
