                guard index == 0, header.recipeBytes == recipe.byteCount else { throw EraseIntentStoreError.invalidAuthority }
                var cursor: UInt64 = 0
                while cursor < recipe.byteCount {
                    let count = Int(min(65_536, recipe.byteCount - cursor))
                    try recipe.withChunk(offset: cursor, count: count) { expected in
                        try io.withRead(offset: offset + 992 + cursor, count: count) { observed in
                            guard observed.elementsEqual(expected) else { throw EraseIntentStoreError.invalidAuthority }
