@MainActor fileprivate enum ColdEraseSchema2ReaderJournalCodecV4 {
    static func word(_ value: UInt64, at offset: Int, into bytes: inout Data) throws {
        guard offset >= 0, bytes.count - offset >= 8 else { throw EraseIntentStoreError.invalidAuthority }
        for index in 0..<8 { bytes[bytes.startIndex + offset + index] = UInt8(truncatingIfNeeded: value >> UInt64(index * 8)) }
