            if index == 7 || index == 9 {
                guard let value = Int64(field), String(value) == String(field) else { throw EraseIntentStoreError.invalidAuthority }
                result.append(UInt64(bitPattern: value))
            } else {
                guard let value = UInt64(field), String(value) == String(field) else { throw EraseIntentStoreError.invalidAuthority }
                result.append(value)
