        guard value.count == 32, (0..<12).contains(ordinal), bytes.count == 864 else { throw EraseIntentStoreError.invalidAuthority }
        bytes.replaceSubrange((480 + ordinal * 32)..<(512 + ordinal * 32), with: value)
