    private static func domain(_ text: String) throws -> Data {
        var raw = Data(text.utf8); guard raw.count <= 32 else { throw EraseIntentStoreError.invalidAuthority }
        raw.append(Data(repeating: 0, count: 32 - raw.count)); return raw
