        hash.update(data: prior); update(recipeOffset, hash: &hash); update(recipeCount, hash: &hash)
        hash.update(data: recipeSHA); return Data(hash.finalize())
    }
    static func afterState(role: UInt64, payload: Data, prior: Data, requestID: Data) throws -> Data {
        guard (1...2).contains(role), payload.count == 864, prior.count == 32, requestID.count == 32,
              payload[512..<576].allSatisfy({ $0 == 0 }) else { throw EraseIntentStoreError.invalidAuthority }
