        update(1, hash: &hash); update(role, hash: &hash); hash.update(data: prior)
        hash.update(data: requestID); hash.update(data: payload); return Data(hash.finalize())
    }
    static func payload(role: UInt64, before: Bool, selected: ColdEraseSchema2ReaderJournalInputV4.Record?,
        heldUnlinked: String?, parent: ColdEraseSchema2ReaderJournalInputV4.Record,
        countBefore: UInt64, countAfter: UInt64, recipeOffset: UInt64, recipeCount: UInt64,
