                let cut = try ranges.captureReaderCurrentJournalControlCutV4(currentOwner: self)
                let actual = try ColdEraseSchema2CompletedNamespaceControlPublicationSourceV4(owner: self,
                    request: request, receipt: receipt, cut: cut, projection: projection)
                namespacePublicationSourceV4 = actual // before caller retention/postproof; Source callback grants no effects
