enum ColdEraseSchema2RatingJournalCodecV4 {
    enum Task: UInt64 { case preferences = 1, cooldown = 2 }
    struct Header: Equatable {
        let kind: ColdEraseControlBinaryV1.FrameHeader.Kind
        let task: Task
        let sequence: UInt64
        let recipeBytes: UInt64
        let previousFrameSHA256: Data
        var totalBytes: UInt64 { 1_024 + recipeBytes }
    }
    private static var magic: Data {
        var value = Data("FE_COLD_FRAME_V1".utf8)
