    private static func append(_ value: UInt64, to data: inout Data) {
        var word = value.littleEndian; withUnsafeBytes(of: &word) { data.append(contentsOf: $0) }
    }
    private static func word(_ data: Data, _ offset: Int) throws -> UInt64 {
        guard offset >= 0, offset <= data.count - 8 else { throw EraseIntentStoreError.invalidAuthority }
        var value: UInt64 = 0
        for index in 0..<8 { value |= UInt64(data[data.startIndex + offset + index]) << UInt64(8 * index) }
        return value
    }
    static func frameHeader(kind: ColdEraseControlBinaryV1.FrameHeader.Kind, task: Task,
        sequence: UInt64, recipeBytes: UInt64, previousFrameSHA256: Data) throws -> Data {
        guard sequence > 0, sequence <= ColdErasePostContentBinaryV4.maximumTaskCount,
              previousFrameSHA256.count == 32,
              (task == .preferences && recipeBytes == 0)
                || (task == .cooldown && kind == .request && recipeBytes > 0 && recipeBytes <= 65_536)
                || (task == .cooldown && kind == .observation && recipeBytes == 0) else {
            throw EraseIntentStoreError.invalidAuthority
        }
        var bytes = magic
        for value in [UInt64(1), kind.rawValue, sequence, task.rawValue, UInt64(864), recipeBytes, UInt64(1), UInt64(4)] {
            append(value, to: &bytes)
        }
        bytes.append(previousFrameSHA256); bytes.append(Data(repeating: 0, count: 16))
        guard bytes.count == 128 else { throw EraseIntentStoreError.invalidAuthority }; return bytes
    }
    static func decodeFrameHeader(_ bytes: Data) throws -> Header {
        guard bytes.count == 128, Data(bytes.prefix(16)) == magic, try word(bytes, 16) == 1,
              let kind = ColdEraseControlBinaryV1.FrameHeader.Kind(rawValue: try word(bytes, 24)),
              let task = Task(rawValue: try word(bytes, 40)), try word(bytes, 48) == 864,
              try word(bytes, 64) == 1, try word(bytes, 72) == 4,
              bytes.suffix(16).allSatisfy({ $0 == 0 }) else { throw EraseIntentStoreError.invalidAuthority }
        let header = Header(kind: kind, task: task, sequence: try word(bytes, 32), recipeBytes: try word(bytes, 56),
            previousFrameSHA256: Data(bytes[bytes.startIndex + 80..<bytes.startIndex + 112]))
        guard try frameHeader(kind: kind, task: task, sequence: header.sequence,
            recipeBytes: header.recipeBytes, previousFrameSHA256: header.previousFrameSHA256) == bytes else {
            throw EraseIntentStoreError.invalidAuthority
