    }
    static func payload(_ fields: ColdErasePostContentBinaryV2.PayloadFields) throws -> Data {
        try ColdErasePostContentBinaryV2.payloadFields(fields)
    }
    static func decodePayload(_ bytes: Data, header: Header) throws -> ColdErasePostContentBinaryV2.PayloadFields {
        let fields = try ColdErasePostContentBinaryV2.decodePayloadFields(bytes)
        let w = fields.words, d = fields.digests
        guard w.count == 16, fields.facts.count == 4, d.count == 12,
              w[0] == 1, w[1] == header.task.rawValue, w[2] == 1,
              w[7] <= UInt64(UInt32.max), w[9] == (header.kind == .request ? 1 : 2),
              w[11] == 0, w[12] == 0, w[13] == 0, w[14] == 1, w[15] == 0,
              fields.facts[0][2] & UInt64(S_IFMT) == UInt64(S_IFDIR),
              fields.facts.dropFirst().allSatisfy({ $0.allSatisfy({ $0 == 0 }) }),
              d[4] == d[10], d[11].allSatisfy({ $0 == 0 }),
              try payload(fields) == bytes else { throw EraseIntentStoreError.invalidAuthority }
