            guard w[10] == 0, d[2].allSatisfy({ $0 == 0 }) else { throw EraseIntentStoreError.invalidAuthority }
        } else { guard w[10] == 1 || w[10] == 2 else { throw EraseIntentStoreError.invalidAuthority } }
