            guard w[3] == 0, w[4] == 0, w[5] == 0, w[6] == 0, w[8] == 0,
                  d[4].allSatisfy({ $0 == 0 }), d[7].allSatisfy({ $0 == 0 }) else {
                throw EraseIntentStoreError.invalidAuthority
            }
