        var d = fields.digests; d[1] = Data(repeating: 0, count: 32); d[2] = Data(repeating: 0, count: 32)
        var hash = SHA256(); hash.update(data: Data("FE_COLD_RATING_REQUEST_V4\0".utf8))
        hash.update(data: try payload(.init(words: fields.words, facts: fields.facts, digests: d)))
        return Data(hash.finalize())
    }
    static func afterState(_ fields: ColdErasePostContentBinaryV2.PayloadFields) throws -> Data {
        var d = fields.digests; d[2] = Data(repeating: 0, count: 32)
        var hash = SHA256(); hash.update(data: Data("FE_COLD_RATING_OBSERVATION_V4\0".utf8))
        hash.update(data: try payload(.init(words: fields.words, facts: fields.facts, digests: d)))
        return Data(hash.finalize())
