    init(request: ColdEraseSchema2RatingRequestV4, candidate: ColdEraseRatingCandidateV1) {
        cells = .init(request: request, candidate: candidate, byteCount: 0,
            sha256: Data(), initializationEntered: false, initialized: false, borrowing: false)
