        var choiceEntered = false
        var encodingEntered = false
        var observationReserved = false
        var restorationReserved = false
        var candidate: ColdEraseRatingCandidateV1?
        var existing: ColdEraseRatingExistingCooldownV1?
        var absent: ColdEraseRatingAbsentLookupV1?
        var actualCASReturn: RatingLedgerPersistenceReceiptV1?
        var checked: ColdEraseRatingCheckedReceiptV1?
