              storage.currentControl.source.request.storage.owner === storage.owner,
              storage.currentControl.source.operation === storage.operation else { throw EraseIntentStoreError.invalidAuthority }
    }
    private func bound(plan: ColdEraseSchema2RatingPlanV1, owner: ColdEraseSchema2TerminalOwnerV1,
        operation: EraseColdPreparationOperationV1, adapter: PreferencesAdapterV1) throws {
        try memory()
        guard storage.plan === plan, storage.owner === owner, storage.operation === operation,
              storage.source.adapter === adapter, plan.operationID == operation.retainedColdOperationIDForComparison,
