        // This frame never calls plan.requireHeld or owner.requireRatingPlan.
    }
    fileprivate func poison(_ error: Error) {
        if storage.failure == nil { storage.failure = error }
        storage.request?.poisonOnUncertainEffect(); storage.currentControl.poison(error)
        storage.owner.poisonOnUncertainEffect()
