    func retainActualProducerFailureV4(_ error: Error) {
        // This callback can only permanently poison the actual retained
        // producer. The Main orchestrator lends its reached primary error
        // before any subsequent owner/fault proof; no effect grant is issued.
        poison(error)
    }
    private func validateChosen(_ state: RatingRequestAttemptLedgerStateV1) throws {
        try state.validate()
        guard state.schemaVersion == 1, state.revision == 1, state.attempts.isEmpty,
              case .erasedCooldown(let erasedAt, let until) = state.origin,
              erasedAt.timeIntervalSince1970.isFinite, until.timeIntervalSince1970.isFinite,
              until.timeIntervalSince(erasedAt) == 365 * 86400,
              state.clockHighWatermarkUTC == erasedAt else { throw RatingEligibilityFailureV1.invalidValue }
