    func bindPlan(_ plan: ColdEraseSchema2RatingPlanV1, owner: ColdEraseSchema2TerminalOwnerV1, operation: EraseColdPreparationOperationV1, adapter: PreferencesAdapterV1) throws {
        guard storage.plan == nil else { throw RatingEligibilityFailureV1.staleState }
        storage.plan = plan
        try bound(plan: plan, owner: owner, operation: operation, adapter: adapter)
    }
    func requireBound(plan: ColdEraseSchema2RatingPlanV1, owner: ColdEraseSchema2TerminalOwnerV1, operation: EraseColdPreparationOperationV1, adapter: PreferencesAdapterV1, persistentDomainName: String) throws {
        try bound(plan: plan, owner: owner, operation: operation, adapter: adapter)
