@MainActor fileprivate final class ColdEraseSchema2DiagnosticsWindowRetirementV4 {
    fileprivate enum Phase { case retained, retiring, returned }
    fileprivate struct Cells {
        weak var request: ColdEraseSchema2DiagnosticsRequestV1?
        let fencedRead: UnsafeMutableRawPointer
        let fencedWrite: UnsafeMutableRawPointer
        var read: UnsafeMutableRawPointer?
        var write: UnsafeMutableRawPointer?
        var phase = Phase.retained
        var readReturned = false
        var writeReturned = false
    }
    fileprivate var cells: Cells
    fileprivate static var declaredBackingBytes: UInt64 { UInt64(MemoryLayout<Cells>.stride) }
    fileprivate init(request: ColdEraseSchema2DiagnosticsRequestV1,
        read: UnsafeMutableRawPointer, write: UnsafeMutableRawPointer) {
        cells = .init(request: request, fencedRead: read, fencedWrite: write, read: read, write: write)
    }
    fileprivate func retire(request: ColdEraseSchema2DiagnosticsRequestV1) throws {
        guard cells.request === request, request.storage.windowRetirementV4 === self,
              cells.phase == .retained, !cells.readReturned, !cells.writeReturned,
              let read = cells.read, let write = cells.write, read != write,
              read == cells.fencedRead, write == cells.fencedWrite,
              request.storage.readWindow == read, request.storage.writeWindow == write,
              request.storage.allocatedWindows == 2 * 65_536,
              !request.storage.readbackLoan, request.storage.activeIO == nil,
              request.storage.contentFrames.isEmpty else { throw EraseIntentStoreError.invalidAuthority }
        try request.requireClosedDiagnosticsRetirementOperandsV4()
        cells.phase = .retiring // sole retirement fence before either pointer detaches
        request.storage.readWindow = nil; request.storage.writeWindow = nil
        cells.read = nil; cells.write = nil
        read.deallocate(); cells.readReturned = true // actual nonthrowing return, before any later proof
        write.deallocate(); cells.writeReturned = true
        request.storage.allocatedWindows = 0
        cells.phase = .returned
    }
    fileprivate func requireReturned(request: ColdEraseSchema2DiagnosticsRequestV1) throws {
        guard cells.request === request, request.storage.windowRetirementV4 === self,
              cells.phase == .returned, cells.readReturned, cells.writeReturned,
              cells.read == nil, cells.write == nil, cells.fencedRead != cells.fencedWrite,
              request.storage.readWindow == nil, request.storage.writeWindow == nil,
              request.storage.allocatedWindows == 0, !request.storage.readbackLoan else {
            throw EraseIntentStoreError.invalidAuthority
        }
        // The fenced addresses are historical DATA only and are never dereferenced.
    }
}

