    fileprivate static let maximumResources = (7 * 10 + 2 * 10 + 10 + 16) * 9 + 96
    fileprivate static let maximumCursors = (7 * 10 + 2 * 10 + 10 + 16) * 3 + 32
    fileprivate static func entryCapacity(progressByteCount: UInt64, coreByteCount: UInt64) throws -> Int {
        guard progressByteCount >= 64, progressByteCount <= ColdErasePostContentBinaryV4.maximumProgressBytes,
              coreByteCount > 0, coreByteCount <= ColdEraseControlBinaryV1.maximumContinuationBytes else {
            throw EraseIntentStoreError.invalidAuthority
        }
        // Three stream cells are reused only after their genuine returned step
        // is positively consumed. Stable resource/open/stat/EOF/close/history
        // cells never reuse an index. Exhaustion refuses before another call.
        return maximumResources * 48 // stable open/stat/EOF/fsync/close/name cells per fixed resource ceiling
    }
    fileprivate static func declaredBackingBytes(progressByteCount: UInt64, coreByteCount: UInt64,
        pathUTF8Count: UInt64, canonicalRByteCount: UInt64) throws -> UInt64 {
        let count = try entryCapacity(progressByteCount: progressByteCount, coreByteCount: coreByteCount)
        guard canonicalRByteCount > 0, canonicalRByteCount <= 100_663_296 else { throw EraseIntentStoreError.invalidAuthority }
        let cCount = try ColdEraseControlBinaryV1.adding(canonicalRByteCount,
            UInt64(EraseIntentPhaseV1.cleanupComplete.rawValue.utf8.count))
        guard cCount >= UInt64(EraseIntentPhaseV1.sessionActivated.rawValue.utf8.count) else { throw EraseIntentStoreError.invalidAuthority }
        let cMaximum = cCount - UInt64(EraseIntentPhaseV1.sessionActivated.rawValue.utf8.count)
        return try ColdEraseControlBinaryV1.adding(
            UInt64(MemoryLayout<Storage>.stride + MemoryLayout<Storage>.alignment - 1),
            ColdEraseControlBinaryV1.multiplying(UInt64(count), UInt64(MemoryLayout<Entry?>.stride)),
            ColdEraseControlBinaryV1.multiplying(UInt64(maximumResources), UInt64(MemoryLayout<Resource?>.stride)),
            65_536, UInt64(6 * MemoryLayout<IncomingControl?>.stride),
            UInt64(2 * 64 * MemoryLayout<String>.stride + 2 * MemoryLayout<[String]>.stride), 2 * 64 * 255,
            // TERMINAL_OWNED_PARENT_COMPLETE_SOURCE_WORK_CENSUS_V4_BEGIN
            // Pay the finite named call-position tree, including loaded
            // optional operands, parameters and result cells. This sum is a
            // conservative Source bound, not a compiler-lifetime/arena credit.
            UInt64((2 + 1 + 1 + 1 + 2 + 1 + 2) * MemoryLayout<OwnedChildParentProjectionV3>.stride
                + (3 + 2) * MemoryLayout<OwnedChildParentProjectionV3?>.stride
                ),
            UInt64((4 + 4 * 7 + 3 + 6 + 1 + 4 + 3 + 4) * MemoryLayout<Resource>.stride
                + (8 + 1 + 2 + 2 + 1 + 1 + 2) * MemoryLayout<Resource?>.stride
                ),
            UInt64((17 + 6 * 2 + 4 * 4 + 5 + 5 + 3) * MemoryLayout<Entry>.stride
                + (11 + 6 + 4 * 4 + 5 + 5 + 3) * MemoryLayout<Entry?>.stride
                ),
            UInt64(7 * (MemoryLayout<RemovalV4>.stride + MemoryLayout<RemovalV4?>.stride)
                + 61 * MemoryLayout<Fact>.stride + 6 * MemoryLayout<Fact?>.stride
                + 29 * MemoryLayout<stat>.stride + 8 * MemoryLayout<stat?>.stride
                + 16 * MemoryLayout<EraseColdControlLeafFactV1>.stride
                ),
            UInt64(18 * MemoryLayout<[String]>.stride + 6 * MemoryLayout<[String]?>.stride
                + 144 * MemoryLayout<Int?>.stride + 16 * MemoryLayout<String>.stride
                + 4 * MemoryLayout<OwnedChildParentKindV3>.stride
                + 2 * MemoryLayout<nlink_t>.stride + MemoryLayout<Int64>.stride
                + 2 * MemoryLayout<Int32>.stride
                ),
            UInt64(2 * MemoryLayout<ColdEraseSchema2TerminalCanonicalReplacementReceiptV4.Cells>.stride
                + 3 * MemoryLayout<IncomingControl>.stride + 2 * MemoryLayout<IncomingControl?>.stride),
            // TERMINAL_OWNED_PARENT_COMPLETE_SOURCE_WORK_CENSUS_V4_END
            ColdEraseSchema2TerminalCanonicalReplacementReceiptV4.declaredBackingBytes,
            ColdEraseSchema2TerminalRecipeV4.declaredBackingBytes,
            ColdEraseControlBinaryV1.multiplying(7, ColdEraseSchema2TerminalPreparedControlV4.declaredBackingBytes),
            UInt64(7 * MemoryLayout<ColdEraseSchema2TerminalPreparedControlV4?>.stride),
            ColdEraseSchema2TerminalPublicationReceiptV4.declaredBackingBytes,
            ColdEraseSchema2TerminalDiagnosticsPolicyRequestV4.declaredBackingBytes,
            ColdEraseSchema2TerminalRatingCanonicalWorkspaceV4.declaredBackingBytes,
            UInt64(8 * MemoryLayout<RemovalV4?>.stride),
            ColdEraseSchema2TerminalControlCloseReceiptV1.declaredBackingBytes,
            ColdEraseRetainedControlFileV1.declaredSyscallBackingBytes,
            ColdEraseSchema2ReaderRecipePinV4.terminalWindowRetirementBackingBytesV4,
            ColdEraseSchema2TerminalReleaseProofV1.terminalStoredBackingBytesV4,
            ColdEraseSchema2TerminalManifestCloseReceiptV1.terminalStoredBackingBytesV4,
            ColdEraseControlBinaryV1.multiplying(cMaximum, 2),
            ColdEraseControlBinaryV1.multiplying(pathUTF8Count, 4),
            UInt64(4 * MemoryLayout<SHA256>.stride + 4 * MemoryLayout<SHA256.Digest>.stride
                + 4 * MemoryLayout<stat>.stride + MemoryLayout<statfs>.stride
                + MemoryLayout<dirent>.stride + 18 * MemoryLayout<String>.stride
                + maximumCursors * 64 * MemoryLayout<String>.stride
                + maximumCursors * MemoryLayout<[String]>.stride), UInt64(maximumCursors * 9 * 255), 6 * 64)
        // Real typed/workspace backing only. Headers/Foundation/allocator/VM,
        // referenced historical recipes and whole admission remain separate.
    }
    fileprivate init(owner: ColdEraseSchema2TerminalOwnerV1, operation: EraseColdPreparationOperationV1,
        ranges: ColdEraseScratchPayloadRangesV1, store: EraseIntentStore,
        control: ColdEraseSchema2PostNamespaceCurrentControlOwnerV4,
        diagnostics: ColdEraseSchema2CompletedDiagnosticsHistoricalReceiptV4,
        projection: ColdEraseSchema2PostContentCurrentJournalOwnerV4.CurrentProgressProjection,
        charge: UInt64, entryCapacity: Int) {
        storage = .init(owner: owner, operation: operation, ranges: ranges, store: store,
            control: control, diagnostics: diagnostics, projection: projection,
            source: control.source, entryCapacity: entryCapacity,
            resourceCapacity: Self.maximumResources, charge: charge)
        // SAME instance is retained by Range and Main before allocation or IO.
    }
    func requireRetainedAssociation(owner: ColdEraseSchema2TerminalOwnerV1,
        operation: EraseColdPreparationOperationV1, ranges: ColdEraseScratchPayloadRangesV1,
        store: EraseIntentStore, control: ColdEraseSchema2PostNamespaceCurrentControlOwnerV4,
        diagnostics: ColdEraseSchema2CompletedDiagnosticsHistoricalReceiptV4) throws {
        guard storage.owner === owner, storage.operation === operation,
              storage.ranges === ranges, storage.store === store,
              storage.control === control, storage.diagnostics === diagnostics,
              storage.failure == nil, storage.phase != .uncertain, storage.charge > 0,
              control.source === storage.source, storage.source.ranges === ranges,
              storage.source.operation === operation, storage.source.transferredOwner.storage.store === store else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try diagnostics.requireHistoricalAssociation(owner: owner, operation: operation,
            control: control, projection: storage.projection)
        // No old Common.current, Reader physical pin or Control.current call.
    }
    private func memory() throws {
        try requireRetainedAssociation(owner: storage.owner, operation: storage.operation,
            ranges: storage.ranges, store: storage.store, control: storage.control,
            diagnostics: storage.diagnostics)
        try storage.ranges.requireRetainedTerminalEnteredControlIOV4(self)
        try storage.owner.requireTerminalEnteredControlFrameV4(self, operation: storage.operation,
            ranges: storage.ranges, store: storage.store)
    }
    fileprivate func poison(_ error: Error) {
        if storage.failure == nil { storage.failure = error }
        storage.phase = .uncertain; storage.owner.poisonOnUncertainEffect()
        storage.ranges.poison(); storage.control.poison(error)
        // All positive FDs, pointer cells, raw failures and charge survive.
        // There is no numeric close retry or failure-driven deallocation.
    }
    fileprivate func allocateAndCaptureIncoming() throws {
        do {
            try memory()
            guard storage.phase == .retained, storage.entries == nil,
                  storage.resources == nil, storage.window == nil else { throw EraseIntentStoreError.invalidAuthority }
            storage.phase = .incoming
            storage.incomingControls = .allocate(capacity: 6)
            storage.incomingControls!.initialize(repeating: nil, count: 6)
            for ordinal in 0..<6 {
                try storage.control.withTerminalIncomingControlV4(diagnostics: storage.diagnostics, ordinal: ordinal) { actual in
                    self.storage.incomingControls![ordinal] = actual
                    try actual.requireAssociation(control: self.storage.control, diagnostics: self.storage.diagnostics)
                }
            }
            storage.removals = .allocate(capacity: 8)
            storage.removals!.initialize(repeating: nil, count: 8)
            storage.preparedControls = .allocate(capacity: 7)
            storage.preparedControls!.initialize(repeating: nil, count: 7)
            storage.entries = .allocate(capacity: storage.entryCapacity)
            storage.entries!.initialize(repeating: nil, count: storage.entryCapacity)
            storage.enteredCount = 3 // three genuine read/write/capacity streaming cells
            storage.resources = .allocate(capacity: storage.resourceCapacity)
            storage.resources!.initialize(repeating: nil, count: storage.resourceCapacity)
            storage.window = .allocate(byteCount: 65_536, alignment: MemoryLayout<UInt64>.alignment)
            storage.windowAllocatedByteCountV4 = 65_536 // actual positive allocation before later proof
            let support = try open(parentDescriptor: storage.source.context.support,
                parentOrdinal: nil, name: ".", directory: true)
            storage.supportOrdinal = support // actual owned positive return before any postproof
            let supportFact = try capture(ordinal: support,
                namedURL: storage.source.context.eraseURL.deletingLastPathComponent())
            storage.incomingSupport = supportFact
            try storage.owner.withTerminalIncomingSupportNamesV4(io: self, operation: storage.operation,
                diagnostics: storage.diagnostics,
                directoryName: storage.diagnostics.request.diagnosticsURL.lastPathComponent) { actual in
                self.storage.incomingSupportNames = actual // same returned namespace before fallible postproof
            }
            guard let supportNames = storage.incomingSupportNames, supportNames.count <= 9 else { throw EraseIntentStoreError.invalidAuthority }
            let firstSupportNames = try names(ordinal: support, expected: supportNames, namedURL: storage.source.context.eraseURL.deletingLastPathComponent())
            let secondSupportNames = try names(ordinal: support, expected: supportNames, namedURL: storage.source.context.eraseURL.deletingLastPathComponent())
            try requirePositiveCursorClose(firstSupportNames); try requirePositiveCursorClose(secondSupportNames)
            guard supportFact.full == storage.diagnostics.supportFact,
                  supportFact.flags == storage.diagnostics.supportFlags else { throw EraseIntentStoreError.invalidAuthority }
            let erase = try open(parentDescriptor: storage.source.context.erase,
                parentOrdinal: nil, name: ".", directory: true)
            storage.eraseOrdinal = erase
            let eraseFact = try capture(ordinal: erase, namedURL: storage.source.context.eraseURL)
            storage.incomingErase = eraseFact
            let origin = try storage.control.requireTerminalIncomingEraseOriginV4(diagnostics: storage.diagnostics)
            guard eraseFact == origin,
                  supportFact.full.device == eraseFact.full.device,
                  eraseFact.full.mode & S_IFMT == S_IFDIR,
                  eraseFact.full.links > 0 else { throw EraseIntentStoreError.invalidAuthority }
            // Root flags are actual same-return DATA, not an invented historical
            // flag. The genuine current Cut already fixes the incoming full11.
            let rating = storage.diagnostics.request.storage.plan.storage.completedRating
            try ColdEraseSchema2TerminalRatingCanonicalWorkspaceV4.withUninitialized(completed: rating) { actual in
                self.storage.ratingWorkspace = actual // actual returned owner before encoder or postproof
            }
            guard let workspace = storage.ratingWorkspace else { throw EraseIntentStoreError.invalidAuthority }
            try workspace.initialize(completed: rating)
            try memory(); storage.phase = .readyR
        } catch { poison(error); throw error }
    }
    private func enter(_ kind: Kind, descriptor: Int32 = -1, secondDescriptor: Int32 = -1,
        resourceOrdinal: Int = -1, offset: UInt64 = 0, requested: Int = 0) throws -> Int {
        try memory()
        guard storage.pending == nil, storage.enteredCount < storage.entryCapacity,
              let cells = storage.entries, requested >= 0 else { throw EraseIntentStoreError.invalidAuthority }
        let streamed = kind == .read || kind == .write || kind == .capacity
        let index = kind == .read ? 0 : (kind == .write ? 1 : (kind == .capacity ? 2 : storage.enteredCount))
        if streamed {
            guard cells[index] == nil || cells[index]!.consumed else { throw EraseIntentStoreError.invalidAuthority }
        } else {
            guard cells[index] == nil else { throw EraseIntentStoreError.invalidAuthority }
            storage.enteredCount += 1
        }
        let sequence = try ColdEraseControlBinaryV1.adding(storage.kernelEntrySequence, 1)
        cells[index] = Entry(sequence: sequence, kind: kind, descriptor: descriptor, secondDescriptor: secondDescriptor,
            resourceOrdinal: resourceOrdinal, offset: offset, requested: requested)
        storage.kernelEntrySequence = sequence; storage.pending = index
        return index
    }
    private func returned(_ index: Int, _ result: Int64, _ savedErrno: Int32,
        information: stat? = nil, filesystem: statfs? = nil,
        stream: UnsafeMutablePointer<DIR>? = nil, name: dirent? = nil) throws {
        guard storage.pending == index, let cells = storage.entries,
              index >= 0, index < storage.enteredCount, var cell = cells[index],
              cell.result == nil, cell.savedErrno == nil else { throw EraseIntentStoreError.invalidAuthority }
        cell.result = result; cell.savedErrno = savedErrno; cell.information = information
        cell.filesystem = filesystem; cell.returnedStream = stream; cell.returnedName = name
        cells[index] = cell // raw values BEFORE memory, named proof or success test
    }
    private func consume(_ index: Int, expected: Int64) throws {
        guard storage.pending == index, let cells = storage.entries,
              var cell = cells[index], cell.result == expected, cell.savedErrno != nil,
              !cell.consumed else { throw EraseIntentStoreError.invalidAuthority }
        try memory()
        guard cell.sequence == (try ColdEraseControlBinaryV1.adding(storage.consumedKernelSequence, 1)) else { throw EraseIntentStoreError.invalidAuthority }
        if cell.kind == .read || cell.kind == .write {
            guard expected > 0, cell.resourceOrdinal >= 0, cell.resourceOrdinal < storage.resourceCount else { throw EraseIntentStoreError.invalidAuthority }
            if cell.kind == .read {
                storage.resources![cell.resourceOrdinal]!.consumedReadBytes = try ColdEraseControlBinaryV1.adding(
                    storage.resources![cell.resourceOrdinal]!.consumedReadBytes, UInt64(expected))
                storage.resources![cell.resourceOrdinal]!.consumedReadReturns += 1
            } else {
                storage.resources![cell.resourceOrdinal]!.consumedWriteBytes = try ColdEraseControlBinaryV1.adding(
                    storage.resources![cell.resourceOrdinal]!.consumedWriteBytes, UInt64(expected))
                storage.resources![cell.resourceOrdinal]!.consumedWriteReturns += 1
            }
        }
        if cell.kind == .capacity { storage.consumedCapacityReturns = try ColdEraseControlBinaryV1.adding(storage.consumedCapacityReturns, 1) }
        cell.consumed = true; cells[index] = cell
        storage.consumedKernelSequence = cell.sequence; storage.pending = nil
    }
    fileprivate func resource(_ ordinal: Int) throws -> Resource {
        guard ordinal >= 0, ordinal < storage.resourceCount, let rows = storage.resources,
              let value = rows[ordinal] else { throw EraseIntentStoreError.invalidAuthority }; return value
    }
    private func retainResource(_ name: String, parentOrdinal: Int?, cursor: Bool) throws -> Int {
        try memory()
        guard !name.isEmpty, !name.utf8.contains(0), name == "." || (!name.contains("/") && name.utf8.count <= 255),
              storage.resourceCount < storage.resourceCapacity, let rows = storage.resources else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let ordinal = storage.resourceCount; guard rows[ordinal] == nil else { throw EraseIntentStoreError.invalidAuthority }
        rows[ordinal] = Resource(name: name, parentOrdinal: parentOrdinal, cursor: cursor)
        storage.resourceCount += 1; return ordinal
    }
    fileprivate func open(parentDescriptor: Int32, parentOrdinal: Int?, name: String,
        directory: Bool, writing: Bool = false, exclusive: Bool = false, cursor: Bool = false) throws -> Int {
        let ordinal = try retainResource(name, parentOrdinal: parentOrdinal, cursor: cursor)
        guard parentDescriptor >= 0, !exclusive || writing else { throw EraseIntentStoreError.invalidAuthority }
        if let parentOrdinal { guard try resource(parentOrdinal).descriptor == parentDescriptor else { throw EraseIntentStoreError.invalidAuthority } }
        if writing {
            guard (storage.phase == .replacingR && name == EraseIntentStore.terminalCanonicalTemporaryNameV4)
                || (storage.phase == .publishingK && name == Self.terminalTemporaryName) else { throw EraseIntentStoreError.invalidAuthority }
        }
        var flags = O_NOFOLLOW | O_CLOEXEC | O_NONBLOCK
        flags |= writing ? O_RDWR : O_RDONLY
        if directory { flags |= O_DIRECTORY }
        if exclusive { flags |= O_CREAT | O_EXCL }
        let index = try enter(.open, descriptor: parentDescriptor, resourceOrdinal: ordinal, requested: Int(flags))
        let result = Darwin.openat(parentDescriptor, name, flags, mode_t(0o600)), saved = errno
        storage.resources![ordinal]!.open = index
        if result >= 0 { storage.resources![ordinal]!.descriptor = result } // OWN actual positive FD before any fallible return recorder
        try returned(index, Int64(result), saved)
        guard result >= 0 else { throw EraseIntentStoreError.invalidAuthority }
        try consume(index, expected: Int64(result)); return ordinal
    }
    fileprivate func capture(ordinal: Int, namedURL: URL? = nil) throws -> Fact {
        let row = try resource(ordinal)
        guard row.descriptor >= 0, row.stream == nil, !row.closed else { throw EraseIntentStoreError.invalidAuthority }
        let heldIndex = try enter(.heldStat, descriptor: row.descriptor, resourceOrdinal: ordinal)
        var held = stat(); let result = Darwin.fstat(row.descriptor, &held), saved = errno
        try returned(heldIndex, Int64(result), saved, information: held)
        storage.resources![ordinal]!.heldStat = heldIndex
        let fact = Fact(held); storage.resources![ordinal]!.fact = fact
        guard result == 0 else { throw EraseIntentStoreError.invalidAuthority }
        try consume(heldIndex, expected: 0)
        if let namedURL {
            let index = try enter(.namedStat, resourceOrdinal: ordinal)
            var named = stat(); let raw = Darwin.lstat(namedURL.path, &named), error = errno
            try returned(index, Int64(raw), error, information: named)
            storage.resources![ordinal]!.namedStat = index
            guard raw == 0, Fact(named) == fact else { throw EraseIntentStoreError.invalidAuthority }
            try consume(index, expected: 0)
        } else if let parentOrdinal = row.parentOrdinal {
            let parent = try resource(parentOrdinal)
            guard parent.descriptor >= 0 else { throw EraseIntentStoreError.invalidAuthority }
            let index = try enter(.namedStat, descriptor: parent.descriptor, resourceOrdinal: ordinal)
            var named = stat(); let raw = Darwin.fstatat(parent.descriptor, row.name, &named, AT_SYMLINK_NOFOLLOW), error = errno
            try returned(index, Int64(raw), error, information: named)
            storage.resources![ordinal]!.namedStat = index
            guard raw == 0, Fact(named) == fact else { throw EraseIntentStoreError.invalidAuthority }
            try consume(index, expected: 0)
        }
        return fact
    }
    fileprivate func hashExactly(ordinal: Int, expectedByteCount: UInt64,
        expectedSHA256: String) throws {
        let row = try resource(ordinal)
        guard row.descriptor >= 0, let window = storage.window,
              let before = row.fact, before.full.mode & S_IFMT == S_IFREG,
              before.full.links == 1, before.full.size >= 0,
              UInt64(before.full.size) == expectedByteCount else { throw EraseIntentStoreError.invalidAuthority }
        var hash = SHA256(), offset: UInt64 = 0
        while offset < expectedByteCount {
            guard let position = off_t(exactly: offset) else { throw EraseIntentStoreError.invalidAuthority }
            let count = Int(min(65_536, expectedByteCount - offset))
            let index = try enter(.read, descriptor: row.descriptor, resourceOrdinal: ordinal, offset: offset, requested: count)
            let result = Darwin.pread(row.descriptor, window, count, position), saved = errno
            try returned(index, Int64(result), saved)
            guard result > 0, result <= count else { throw EraseIntentStoreError.invalidAuthority }
            try consume(index, expected: Int64(result))
            hash.update(bufferPointer: UnsafeRawBufferPointer(start: window, count: result))
            offset += UInt64(result)
        }
        let digest = hash.finalize()
        storage.resources![ordinal]!.digest = digest; storage.resources![ordinal]!.rawByteCount = offset
        guard Data(digest) == (try ColdEraseControlBinaryV1.rawSHA256(expectedSHA256)),
              let end = off_t(exactly: expectedByteCount) else { throw EraseIntentStoreError.invalidAuthority }
        let eof = try enter(.eof, descriptor: row.descriptor, resourceOrdinal: ordinal, offset: expectedByteCount, requested: 1)
        let result = Darwin.pread(row.descriptor, window, 1, end), saved = errno
        try returned(eof, Int64(result), saved); storage.resources![ordinal]!.eof = eof
        guard result == 0 else { throw EraseIntentStoreError.invalidAuthority }; try consume(eof, expected: 0)
        guard try capture(ordinal: ordinal) == before else { throw EraseIntentStoreError.invalidAuthority }
    }
    fileprivate func synchronize(ordinal: Int) throws {
        let row = try resource(ordinal); guard row.descriptor >= 0 else { throw EraseIntentStoreError.invalidAuthority }
        let index = try enter(.synchronize, descriptor: row.descriptor, resourceOrdinal: ordinal)
        let result = Darwin.fsync(row.descriptor), saved = errno; try returned(index, Int64(result), saved)
        storage.resources![ordinal]!.synchronization = index
        guard result == 0 else { throw EraseIntentStoreError.invalidAuthority }; try consume(index, expected: 0)
    }
    fileprivate func closeOnce(ordinal: Int) throws {
        let row = try resource(ordinal)
        guard !row.closed, row.close == nil, row.descriptor >= 0, row.stream == nil else { throw EraseIntentStoreError.invalidAuthority }
        let index = try enter(.close, descriptor: row.descriptor, resourceOrdinal: ordinal)
        storage.resources![ordinal]!.descriptor = -1 // detached before sole entry
        storage.resources![ordinal]!.close = index
        let result = Darwin.close(row.descriptor), saved = errno; try returned(index, Int64(result), saved)
        guard result == 0 else { throw EraseIntentStoreError.invalidAuthority }
        try consume(index, expected: 0); storage.resources![ordinal]!.closed = true
    }
    fileprivate func requirePositiveClose(ordinal: Int) throws {
        let row = try resource(ordinal)
        guard row.closed, row.descriptor == -1, row.stream == nil, let index = row.close,
              let entry = storage.entries?[index], entry.kind == .close,
              entry.resourceOrdinal == ordinal, entry.descriptor >= 0,
              entry.result == 0, entry.savedErrno != nil, entry.consumed else { throw EraseIntentStoreError.invalidAuthority }
    }
}
