// TERMINAL_INCOMING_ACTUAL_CURRENT_ORIGIN_V4_BEGIN
extension ColdEraseSchema2PostNamespaceCurrentControlOwnerV4 {
    fileprivate func requireTerminalIncomingEraseOriginV4(
        diagnostics: ColdEraseSchema2CompletedDiagnosticsHistoricalReceiptV4)
        throws -> ColdEraseSchema2TerminalEnteredControlIOV4.Fact {
        guard diagnostics.control === self, diagnostics.request === storage.diagnosticsCurrentV4.request,
              diagnostics.projection === storage.diagnosticsCurrentV4.projection,
              let cut = storage.currentCut, let epoch = storage.currentEpoch,
              epoch.storage.cut === cut, epoch.storage.checked,
              epoch.storage.currentProjectionV4 === diagnostics.projection,
              let row = try epoch.storage.rows.row(1),
              let held = row.storage.parentHeld, let named = row.storage.parentNamed,
              held.storage.kind == .heldRoot, named.storage.kind == .namedRoot,
              held.storage.result == 0, named.storage.result == 0,
              held.storage.savedErrno != nil, named.storage.savedErrno != nil,
              held.storage.consumed, named.storage.consumed,
              let a = held.storage.fact, let b = named.storage.fact,
              ColdEraseSchema2TerminalEnteredControlIOV4.Fact(a)
                == ColdEraseSchema2TerminalEnteredControlIOV4.Fact(b),
              EraseColdControlLeafFactV1(a) == cut.eraseRoot else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try diagnostics.requireHistoricalAssociation(owner: diagnostics.cells.owner,
            operation: diagnostics.cells.operation, control: self, projection: diagnostics.projection)
        try row.requireClosed()
        return .init(a)
        // Exact retained returned current epoch stat, including flags. A fresh
        // later root stat cannot replace this incoming authority.
    }
}

extension ColdEraseScratchPayloadRangesV1 {
    fileprivate struct TerminalEnteredStoredCellsV4 {
        var creationEntered = false
        var io: ColdEraseSchema2TerminalEnteredControlIOV4?
        var receipt: ColdEraseSchema2CompletedDiagnosticsHistoricalReceiptV4?
        var projection: ColdEraseSchema2PostContentCurrentJournalOwnerV4.CurrentProgressProjection?
        var charge: UInt64 = 0
        var issuanceReturned = false
    }
    fileprivate func requireRetainedTerminalEnteredControlIOV4(
        _ io: ColdEraseSchema2TerminalEnteredControlIOV4) throws {
        guard state == .postContent, oldScratchAccessFenced,
              terminalEnteredV4.creationEntered, terminalEnteredV4.io === io,
              terminalEnteredV4.charge > 0, let diagnostics = terminalEnteredV4.receipt,
              let projection = terminalEnteredV4.projection,
              let control = postNamespaceCurrentControlsV4.owner,
              diagnostics.control === control, diagnostics.projection === projection else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try io.requireRetainedAssociation(owner: diagnostics.cells.owner, operation: operation,
            ranges: self, store: store, control: control, diagnostics: diagnostics)
    }
    func beginTerminalEnteredControlIOV4(owner: ColdEraseSchema2TerminalOwnerV1,
        operation: EraseColdPreparationOperationV1, store: EraseIntentStore)
        throws -> ColdEraseSchema2TerminalEnteredControlIOV4 {
        guard self.operation === operation, self.store === store,
              !terminalEnteredV4.creationEntered, terminalEnteredV4.io == nil,
              let control = postNamespaceCurrentControlsV4.owner else { throw EraseIntentStoreError.invalidAuthority }
        terminalEnteredV4.creationEntered = true // once before any current callback
        do {
            let pathCount = UInt64(control.source.context.eraseURL.path.utf8.count)
            let charge = try ColdEraseSchema2TerminalEnteredControlIOV4.declaredBackingBytes(
                progressByteCount: control.progressByteCount, coreByteCount: control.coreByteCount,
                pathUTF8Count: pathCount,
                canonicalRByteCount: UInt64(control.source.transferredOwner.storage.first.intentBytes.count))
            try control.reserveContinuationConsumerBacking(owner: owner, operation: operation,
                ranges: self, store: store, additionalBytes: charge)
            terminalEnteredV4.charge = charge
            try control.withCompletedDiagnosticsCurrentV4(owner: owner, operation: operation) { actual, projection in
                self.terminalEnteredV4.receipt = actual
                self.terminalEnteredV4.projection = projection // BOTH actual returns before any fallible predicate
                guard actual.control === control, actual.projection === projection,
                      actual.cells.owner === owner, actual.cells.operation === operation else { throw EraseIntentStoreError.invalidAuthority }
                let count = try ColdEraseSchema2TerminalEnteredControlIOV4.entryCapacity(
                    progressByteCount: projection.byteCount, coreByteCount: control.coreByteCount)
                let io = ColdEraseSchema2TerminalEnteredControlIOV4(owner: owner, operation: operation,
                    ranges: self, store: store, control: control, diagnostics: actual,
                    projection: projection, charge: charge, entryCapacity: count)
                self.terminalEnteredV4.io = io // before Main postproof or any pointer allocation
                try owner.retainTerminalEnteredControlIOV4(io, operation: operation, ranges: self,
                    store: store, control: control, diagnostics: actual)
            }
            guard let actual = terminalEnteredV4.io else { throw EraseIntentStoreError.invalidAuthority }
            // The real current borrower has positively returned before any IO
            // owner allocation and before any subsequent C/K mechanical entry.
            try actual.allocateAndCaptureIncoming()
            try requireRetainedTerminalEnteredControlIOV4(actual)
            terminalEnteredV4.issuanceReturned = true
            return actual
        } catch {
            terminalEnteredV4.io?.poison(error); poison(); control.poison(error); throw error
        }
    }
}
// TERMINAL_INCOMING_ACTUAL_CURRENT_ORIGIN_V4_END

// TERMINAL_INCOMING_SAME_RETURN_LEAF_DATA_V4_BEGIN
extension EraseIntentStore {
    fileprivate static var terminalCanonicalIntentNameV4: String { intentName }
    fileprivate static var terminalCanonicalTemporaryNameV4: String { nextName }
}
extension ColdEraseSchema2TerminalEnteredControlIOV4 {
    fileprivate struct IncomingControl {
        let control: ColdEraseSchema2PostNamespaceCurrentControlOwnerV4
        let diagnostics: ColdEraseSchema2CompletedDiagnosticsHistoricalReceiptV4
        let epoch: ColdEraseSchema2TransferredControlOwnerV1.Epoch
        let resource: ColdEraseSchema2TransferredControlOwnerV1.Resource
        let ordinal: Int
        let name: String
        let fact: Fact
        let policy: TemporalPolicyObservationV1
        let byteCount: UInt64
        let sha256: String
        @MainActor fileprivate func requireAssociation(control: ColdEraseSchema2PostNamespaceCurrentControlOwnerV4,
            diagnostics: ColdEraseSchema2CompletedDiagnosticsHistoricalReceiptV4) throws {
            guard self.control === control, self.diagnostics === diagnostics,
                  epoch.storage.checked, epoch.storage.currentProjectionV4 === diagnostics.projection,
                  resource === (try epoch.storage.rows.row(UInt64(ordinal + 1))),
                  resource.storage.name == name, resource.storage.expectedByteCount == byteCount,
                  resource.storage.expectedFact == fact.full,
                  let a = resource.storage.held, let b = resource.storage.named,
                  a.storage.kind == .heldLeaf, b.storage.kind == .namedLeaf,
                  a.storage.result == 0, b.storage.result == 0,
                  a.storage.savedErrno != nil, b.storage.savedErrno != nil,
                  a.storage.consumed, b.storage.consumed,
                  let x = a.storage.fact, let y = b.storage.fact,
                  Fact(x) == fact, Fact(y) == fact,
                  resource.storage.beforePolicy?.storage.checked == true,
                  resource.storage.afterPolicy?.storage.checked == true,
                  case .returned(let first)? = resource.storage.beforePolicy?.storage.result,
                  case .returned(let last)? = resource.storage.afterPolicy?.storage.result,
                  first == policy, last == policy, let actualDigest = resource.storage.digest,
                  Data(actualDigest) == (try ColdEraseControlBinaryV1.rawSHA256(sha256)) else {
                throw EraseIntentStoreError.invalidAuthority
            }
            try resource.requireClosed()
            try diagnostics.requireHistoricalAssociation(owner: diagnostics.cells.owner,
                operation: diagnostics.cells.operation, control: control, projection: diagnostics.projection)
            // All actual row resource returns are retained; no physical FD reentry.
        }
    }
    @discardableResult fileprivate func proveIncomingControlPrefix() throws -> (first: Int, second: Int) {
        do {
            guard storage.phase == .readyR, let incoming = storage.incomingControls else { throw EraseIntentStoreError.invalidAuthority }
            let root = try eraseOrdinal, support = try supportOrdinal
            guard try capture(ordinal: support, namedURL: storage.source.context.eraseURL.deletingLastPathComponent()) == incomingSupport,
                  try capture(ordinal: root, namedURL: storage.source.context.eraseURL) == incomingErase else { throw EraseIntentStoreError.invalidAuthority }
            let first = try names(ordinal: root, expected: storage.source.names, namedURL: storage.source.context.eraseURL)
            try requirePositiveCursorClose(first)
            for ordinal in 0..<6 {
                guard let actual = incoming[ordinal] else { throw EraseIntentStoreError.invalidAuthority }
                try actual.requireAssociation(control: storage.control, diagnostics: storage.diagnostics)
                let leaf = try open(parentDescriptor: try resource(root).descriptor, parentOrdinal: root,
                    name: actual.name, directory: false)
                guard try capture(ordinal: leaf) == actual.fact else { throw EraseIntentStoreError.invalidAuthority }
                try observePolicy(ordinal: leaf, expected: actual.policy)
                try hashExactly(ordinal: leaf, expectedByteCount: actual.byteCount, expectedSHA256: actual.sha256)
                try observePolicy(ordinal: leaf, expected: actual.policy)
                try closeOnce(ordinal: leaf); try requirePositiveClose(ordinal: leaf)
                guard try capture(ordinal: root, namedURL: storage.source.context.eraseURL) == incomingErase else { throw EraseIntentStoreError.invalidAuthority }
            }
            let second = try names(ordinal: root, expected: storage.source.names, namedURL: storage.source.context.eraseURL)
            try requirePositiveCursorClose(second)
            guard try capture(ordinal: root, namedURL: storage.source.context.eraseURL) == incomingErase,
                  try capture(ordinal: support, namedURL: storage.source.context.eraseURL.deletingLastPathComponent()) == incomingSupport else { throw EraseIntentStoreError.invalidAuthority }
            return (first, second)
        } catch { poison(error); throw error }
    }
}
extension ColdEraseSchema2PostNamespaceCurrentControlOwnerV4 {
    fileprivate func withTerminalIncomingControlV4(
        diagnostics: ColdEraseSchema2CompletedDiagnosticsHistoricalReceiptV4, ordinal: Int,
        _ body: (ColdEraseSchema2TerminalEnteredControlIOV4.IncomingControl) throws -> Void) throws {
        guard ordinal >= 0, ordinal < 6, diagnostics.control === self,
              diagnostics.request === storage.diagnosticsCurrentV4.request,
              diagnostics.projection === storage.diagnosticsCurrentV4.projection,
              let cut = storage.currentCut, let epoch = storage.currentEpoch,
              epoch.storage.checked, epoch.storage.cut === cut,
              epoch.storage.currentProjectionV4 === diagnostics.projection,
              let row = try epoch.storage.rows.row(UInt64(ordinal + 1)),
              let held = row.storage.held, let raw = held.storage.fact,
              let digest = row.storage.digest,
              case .returned(let policy)? = row.storage.afterPolicy?.storage.result else {
            throw EraseIntentStoreError.invalidAuthority
        }
        let actual = ColdEraseSchema2TerminalEnteredControlIOV4.IncomingControl(control: self,
            diagnostics: diagnostics, epoch: epoch, resource: row, ordinal: ordinal,
            name: row.storage.name, fact: .init(raw), policy: policy,
            byteCount: row.storage.expectedByteCount,
            sha256: try ColdEraseControlBinaryV1.hexSHA256(Data(digest)))
        try actual.requireAssociation(control: self, diagnostics: diagnostics); try body(actual)
        try actual.requireAssociation(control: self, diagnostics: diagnostics)
    }
}
