// TERMINAL_ACTUAL_DIAGNOSTICS_SUPPORT_CREATE_HISTORY_V4_BEGIN
extension ColdEraseSchema2CompletedDiagnosticsHistoricalReceiptV4 {
    func requireActualHistoricalSupportCreationV4(issuer: ColdEraseDiagnosticsEffectIssuerV1,
        outcome: ColdDiagnosticsPrimitiveOutcomeV1) throws {
        guard cells.issuer === issuer, outcome.intent.ioIdentity == ObjectIdentifier(cells.io),
              outcome.intent.operationID == cells.io.operationID, outcome.intent.kind == .createDirectory,
              case .syscall(let result, _) = outcome.result, result == 0,
              let after = outcome.after, after.supportFact == supportFact,
              after.directoryFact == directoryFact, outcome.intent.before?.directoryFact == nil else {
            throw EraseIntentStoreError.invalidAuthority
        }
        try requireHistoricalAssociation(owner: cells.owner, operation: cells.operation,
            control: cells.control, projection: cells.projection)
        // Main lends SAME retained capacitySupportProjection positive outcome.
        // The checked content/parent and final two postimages independently
        // bind it to this exact completed receipt; no caller-supplied success.
    }
}
