// TERMINAL_ACTUAL_CURSOR_POLICY_AND_RETURNED_EFFECT_V4_BEGIN
extension ColdEraseSchema2TerminalEnteredControlIOV4 {
    fileprivate func names(ordinal: Int, expected: [String], namedURL: URL?) throws -> Int {
        guard expected.count <= 9, expected == expected.sorted() else {
            throw EraseIntentStoreError.invalidAuthority
        }
        for index in 1..<max(1, expected.count) {
            guard expected[index - 1] < expected[index] else { throw EraseIntentStoreError.invalidAuthority }
        }
        guard storage.cursorCount < UInt64(Self.maximumCursors) else { throw EraseIntentStoreError.invalidAuthority }
        storage.cursorCount += 1 // charge was fixed before any of these arrays/cursors
        let parent = try resource(ordinal)
        let before = try capture(ordinal: ordinal, namedURL: namedURL)
        let cursorOrdinal = try open(parentDescriptor: parent.descriptor, parentOrdinal: ordinal,
            name: ".", directory: true, cursor: true)
        guard try capture(ordinal: cursorOrdinal) == before else { throw EraseIntentStoreError.invalidAuthority }
        let row = try resource(cursorOrdinal)
        let adoption = try enter(.adoptCursor, descriptor: row.descriptor, resourceOrdinal: cursorOrdinal)
        let stream = Darwin.fdopendir(row.descriptor), saved = errno
        storage.resources![cursorOrdinal]!.adoption = adoption
        if let stream {
            storage.resources![cursorOrdinal]!.stream = stream
            storage.resources![cursorOrdinal]!.descriptor = -1 // transferred ownership only on actual positive adoption
        }
        try returned(adoption, stream == nil ? -1 : 0, saved, stream: stream)
        guard let stream else { throw EraseIntentStoreError.invalidAuthority }
        try consume(adoption, expected: 0)
        storage.resources![cursorOrdinal]!.names = []
        storage.resources![cursorOrdinal]!.names!.reserveCapacity(9)
        guard storage.resources![cursorOrdinal]!.names!.capacity <= 64 else { throw EraseIntentStoreError.invalidAuthority }
        var seen: UInt16 = 0, dots: UInt8 = 0, requests = 0
        while true {
            guard requests < expected.count + 3 else { throw EraseIntentStoreError.invalidAuthority }
            requests += 1
            let index = try enter(.readName, resourceOrdinal: cursorOrdinal)
            errno = 0; let raw = Darwin.readdir(stream), error = errno
            let copied = raw?.pointee
            try returned(index, raw == nil ? 0 : 1, error, name: copied)
            if raw == nil { storage.resources![cursorOrdinal]!.eof = index }
            guard raw != nil || error == 0 else { throw EraseIntentStoreError.invalidAuthority }
            try consume(index, expected: raw == nil ? 0 : 1)
            guard var value = copied else { break }
            guard value.d_namlen > 0, value.d_namlen <= 255 else { throw EraseIntentStoreError.invalidAuthority }
            try withUnsafeBytes(of: &value.d_name) { bytes in
                let count = Int(value.d_namlen)
                guard count < bytes.count, bytes[count] == 0 else { throw EraseIntentStoreError.invalidAuthority }
                let name = UnsafeRawBufferPointer(rebasing: bytes[0..<count])
                if count == 1, name[0] == 46 { guard dots & 1 == 0 else { throw EraseIntentStoreError.invalidAuthority }; dots |= 1; storage.resources![cursorOrdinal]!.actualDirectoryDotsV3 = dots; return }
                if count == 2, name[0] == 46, name[1] == 46 { guard dots & 2 == 0 else { throw EraseIntentStoreError.invalidAuthority }; dots |= 2; storage.resources![cursorOrdinal]!.actualDirectoryDotsV3 = dots; return }
                guard let index = expected.firstIndex(where: { $0.utf8.elementsEqual(name) }), index < 9 else { throw EraseIntentStoreError.invalidAuthority }
                let bit = UInt16(1) << index
                guard seen & bit == 0 else { throw EraseIntentStoreError.invalidAuthority }; seen |= bit
                storage.resources![cursorOrdinal]!.names!.append(expected[index]) // retained before parent postproof
                guard storage.resources![cursorOrdinal]!.names!.capacity <= 64 else { throw EraseIntentStoreError.invalidAuthority }
            }
            guard try capture(ordinal: ordinal, namedURL: namedURL) == before else { throw EraseIntentStoreError.invalidAuthority }
        }
        let close = try enter(.closeCursor, resourceOrdinal: cursorOrdinal)
        storage.resources![cursorOrdinal]!.stream = nil // detached before sole closedir
        storage.resources![cursorOrdinal]!.close = close
        let result = Darwin.closedir(stream), error = errno; try returned(close, Int64(result), error)
        guard result == 0 else { throw EraseIntentStoreError.invalidAuthority }; try consume(close, expected: 0)
        storage.resources![cursorOrdinal]!.closed = true
        storage.resources![cursorOrdinal]!.names!.sort()
        guard seen == (UInt16(1) << expected.count) - 1,
              try resource(cursorOrdinal).names == expected,
              try capture(ordinal: ordinal, namedURL: namedURL) == before else { throw EraseIntentStoreError.invalidAuthority }
        return cursorOrdinal
    }
    fileprivate func requirePositiveCursorClose(_ ordinal: Int) throws {
        let row = try resource(ordinal)
        guard row.cursor, row.closed, row.stream == nil, row.descriptor == -1,
              let adoption = row.adoption, let a = storage.entries?[adoption],
              a.kind == .adoptCursor, a.result == 0, a.savedErrno != nil, a.returnedStream != nil, a.consumed,
              let eof = row.eof, let e = storage.entries?[eof], e.kind == .readName,
              e.result == 0, e.savedErrno == 0, e.consumed,
              let close = row.close, let c = storage.entries?[close], c.kind == .closeCursor,
              c.result == 0, c.savedErrno != nil, c.consumed else { throw EraseIntentStoreError.invalidAuthority }
    }
    fileprivate func observePolicy(ordinal: Int, expected: TemporalPolicyObservationV1) throws {
        let row = try resource(ordinal)
        guard row.parentOrdinal == (try eraseOrdinal), let first = row.fact,
              first.full.mode & S_IFMT == S_IFREG, first.full.links == 1 else { throw EraseIntentStoreError.invalidAuthority }
        let url = storage.source.context.eraseURL.appendingPathComponent(row.name)
        guard try capture(ordinal: ordinal) == first else { throw EraseIntentStoreError.invalidAuthority }
        storage.resources![ordinal]!.policyFaultRoot = try capture(ordinal: try eraseOrdinal, namedURL: storage.source.context.eraseURL)
        storage.resources![ordinal]!.policyFaultSupport = try capture(ordinal: try supportOrdinal, namedURL: storage.source.context.eraseURL.deletingLastPathComponent())
        do {
            guard storage.resources![ordinal]!.policyReadEntries < 2 else { throw EraseIntentStoreError.invalidAuthority }
            storage.resources![ordinal]!.policyReadEntries += 1 // entered before actual getter
            let returned = try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(.journal, at: url,
                retainUncertainDescriptor: { actual in self.retainUncertainPolicyDescriptor(actual) })
            if storage.resources![ordinal]!.policyBefore == nil { storage.resources![ordinal]!.policyBefore = returned }
            else { storage.resources![ordinal]!.policyAfter = returned } // both real getter returns before proofs
            guard returned == expected, try capture(ordinal: ordinal) == first,
                  returned.device == UInt64(first.full.device), returned.inode == UInt64(first.full.inode),
                  returned.mode == UInt16(first.full.mode), returned.linkCount == 1,
                  returned.backupExcluded == true, returned.isDirectory == false,
                  storage.uncertainPolicyCallbackCount == 0 else { throw EraseIntentStoreError.invalidAuthority }
        } catch {
            storage.resources![ordinal]!.policyFailure = error
            // The real primary error stays retained. These actual own-resource
            // postchecks run before outer poison, never grant a retry/effect.
            do { try requireActualPolicyFaultResource(ordinal: ordinal, first: first) }
            catch { storage.resources![ordinal]!.policySecondaryFailure = error }
            throw error
        }
    }
    fileprivate func observeActualBornControlPolicyV4(ordinal: Int, bornOrdinal: Int) throws -> TemporalPolicyObservationV1 {
        let row = try resource(ordinal), born = try resource(bornOrdinal)
        guard row.parentOrdinal == (try eraseOrdinal), row.descriptor >= 0,
              let first = row.fact, born.policyApplicationEntered, born.policySetterEntered,
              case .success(let application)? = born.policyApplication, born.policyFailure == nil,
              storage.uncertainPolicyCallbackCount == 0,
              first.full.device == born.fact?.full.device, first.full.inode == born.fact?.full.inode,
              first.full.mode == born.fact?.full.mode, first.full.user == born.fact?.full.user,
              first.full.group == born.fact?.full.group, first.flags == born.fact?.flags,
              first.full.mode & S_IFMT == S_IFREG, first.full.links == 1 else { throw EraseIntentStoreError.invalidAuthority }
        let url = storage.source.context.eraseURL.appendingPathComponent(row.name)
        storage.resources![ordinal]!.policyFaultRoot = try capture(ordinal: try eraseOrdinal, namedURL: storage.source.context.eraseURL)
        storage.resources![ordinal]!.policyFaultSupport = try capture(ordinal: try supportOrdinal, namedURL: storage.source.context.eraseURL.deletingLastPathComponent())
        do {
            guard row.policyReadEntries < 2 else { throw EraseIntentStoreError.invalidAuthority }
            storage.resources![ordinal]!.policyReadEntries += 1
            let returned = try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(.journal, at: url,
                retainUncertainDescriptor: { self.retainUncertainPolicyDescriptor($0) })
            if storage.resources![ordinal]!.policyBefore == nil { storage.resources![ordinal]!.policyBefore = returned }
            else { storage.resources![ordinal]!.policyAfter = returned }
            guard returned.device == UInt64(first.full.device), returned.inode == UInt64(first.full.inode),
                  returned.mode == UInt16(first.full.mode), returned.linkCount == 1,
                  returned.isDirectory == false, returned.backupExcluded == true,
                  application != .verifiedComplete || returned.state == .strictComplete,
                  returned == storage.resources![ordinal]!.policyBefore,
                  try capture(ordinal: ordinal) == first, storage.uncertainPolicyCallbackCount == 0 else { throw EraseIntentStoreError.invalidAuthority }
            return returned // DATA joins a genuine new born setter/checked return, never a pending enum grant
        } catch {
            storage.resources![ordinal]!.policyFailure = error
            do { try requireActualPolicyFaultResource(ordinal: ordinal, first: first) }
            catch { storage.resources![ordinal]!.policySecondaryFailure = error }
            throw error
        }
    }
    private func retainUncertainPolicyDescriptor(_ actual: Int32) {
        let occurrence = storage.uncertainPolicyCallbackCount
        storage.uncertainPolicyCallbackCount += 1
        if occurrence == 0 { storage.uncertainPolicyDescriptor0 = actual }
        else if occurrence == 1 { storage.uncertainPolicyDescriptor1 = actual }
        storage.ranges.retainUncertainPolicyDescriptor(actual)
        // Do not call the normal frame from the callback, clear ownership or
        // close an ambiguous number. The outer operation poisons after raw proof.
    }
    fileprivate func absent(parentOrdinal: Int, name: String) throws -> Int {
        let parent = try resource(parentOrdinal)
        let index = try enter(.namedStat, descriptor: parent.descriptor)
        var value = stat(); let result = Darwin.fstatat(parent.descriptor, name, &value, AT_SYMLINK_NOFOLLOW), saved = errno
        try returned(index, Int64(result), saved, information: value)
        guard result == -1, saved == ENOENT else { throw EraseIntentStoreError.invalidAuthority }
        try consume(index, expected: -1); return index
    }
    fileprivate func writeExactly(ordinal: Int, offset: UInt64, bytes: UnsafeRawBufferPointer) throws {
        let row = try resource(ordinal)
        guard storage.phase == .replacingR || storage.phase == .publishingK,
              row.descriptor >= 0, bytes.count > 0, bytes.count <= 65_536 else { throw EraseIntentStoreError.invalidAuthority }
        var consumed = 0
        while consumed < bytes.count {
            let position = try ColdEraseControlBinaryV1.adding(offset, UInt64(consumed))
            guard let actual = off_t(exactly: position) else { throw EraseIntentStoreError.invalidAuthority }
            try requireCapacityForActualGrowth(UInt64(bytes.count - consumed))
            let index = try enter(.write, descriptor: row.descriptor, resourceOrdinal: ordinal,
                offset: position, requested: bytes.count - consumed)
            let result = Darwin.pwrite(row.descriptor, bytes.baseAddress!.advanced(by: consumed), bytes.count - consumed, actual), saved = errno
            try returned(index, Int64(result), saved)
            guard result > 0, result <= bytes.count - consumed else { throw EraseIntentStoreError.invalidAuthority }
            try consume(index, expected: Int64(result)); consumed += result
        }
    }
    fileprivate func swapCanonicalTemporary(_ ordinal: Int) throws -> Int {
        let row = try resource(ordinal), root = try resource(try eraseOrdinal)
        guard storage.phase == .replacingR, row.name == EraseIntentStore.terminalCanonicalTemporaryNameV4,
              row.parentOrdinal == (try eraseOrdinal), row.descriptor >= 0,
              row.synchronization != nil else { throw EraseIntentStoreError.invalidAuthority }
        let index = try enter(.rename, descriptor: root.descriptor, secondDescriptor: root.descriptor,
            resourceOrdinal: ordinal)
        let result = Darwin.renameatx_np(root.descriptor, row.name, root.descriptor,
            EraseIntentStore.terminalCanonicalIntentNameV4, UInt32(RENAME_SWAP)), saved = errno
        try returned(index, Int64(result), saved)
        guard result == 0 else { throw EraseIntentStoreError.invalidAuthority }; try consume(index, expected: 0)
        return index
    }
}
// TERMINAL_ACTUAL_CURSOR_POLICY_AND_RETURNED_EFFECT_V4_END
// TERMINAL_ACTUAL_CANONICAL_R_TO_C_V4_BEGIN
/// Privately minted after the SAME entered canonical swap, fsync, exact C and
/// displaced-R physical read/hash/EOF, two finite scans and checked C close.
/// It retains canonical C for streamed K; it grants no K or final settlement.
@MainActor final class ColdEraseSchema2TerminalCanonicalReplacementReceiptV4 {
    fileprivate struct Cells {
        let io: ColdEraseSchema2TerminalEnteredControlIOV4
        let original: EraseIntentV1
        let completed: EraseIntentV1
        var canonicalBytes: Data?
        var rawRetirementEnteredV4 = false
        var rawRetirementReturnedV4 = false
        let canonicalFact: ColdEraseSchema2TerminalEnteredControlIOV4.Fact
        let displacedFact: ColdEraseSchema2TerminalEnteredControlIOV4.Fact
        let parentFact: ColdEraseSchema2TerminalEnteredControlIOV4.Fact
        let canonicalOrdinal: Int
        let displacedOrdinal: Int
        let swap: Int
        let synchronization: Int
        let firstScan: Int
        let secondScan: Int
        let displacedHeld: Int
        let displacedNamed: Int
        let displacedEOF: Int
        let byteCount: UInt64
        let sha256: String
        var borrowing = false
    }
    private var cells: Cells
    fileprivate static var declaredBackingBytes: UInt64 {
        UInt64(MemoryLayout<Cells>.stride + MemoryLayout<Cells>.alignment - 1 + 64)
    }
    fileprivate init(io: ColdEraseSchema2TerminalEnteredControlIOV4, original: EraseIntentV1,
        completed: EraseIntentV1, bytes: Data, canonicalFact: ColdEraseSchema2TerminalEnteredControlIOV4.Fact,
        displacedFact: ColdEraseSchema2TerminalEnteredControlIOV4.Fact,
        parentFact: ColdEraseSchema2TerminalEnteredControlIOV4.Fact,
        canonicalOrdinal: Int, displacedOrdinal: Int, swap: Int, synchronization: Int,
        firstScan: Int, secondScan: Int, displacedHeld: Int, displacedNamed: Int, displacedEOF: Int, sha256: String) {
        cells = .init(io: io, original: original, completed: completed, canonicalBytes: bytes,
            canonicalFact: canonicalFact, displacedFact: displacedFact, parentFact: parentFact,
            canonicalOrdinal: canonicalOrdinal, displacedOrdinal: displacedOrdinal,
            swap: swap, synchronization: synchronization, firstScan: firstScan, secondScan: secondScan,
            displacedHeld: displacedHeld, displacedNamed: displacedNamed, displacedEOF: displacedEOF,
            byteCount: UInt64(bytes.count), sha256: sha256)
    }
    fileprivate var canonicalResourceOrdinalV4: Int { cells.canonicalOrdinal }
    var canonicalIntent: EraseIntentV1 { cells.completed }
    var canonicalByteCount: UInt64 { cells.byteCount }
    var canonicalSHA256: String { cells.sha256 }
    fileprivate var canonicalFact: ColdEraseSchema2TerminalEnteredControlIOV4.Fact { cells.canonicalFact }
    fileprivate var displacedFact: ColdEraseSchema2TerminalEnteredControlIOV4.Fact { cells.displacedFact }
    fileprivate var parentFact: ColdEraseSchema2TerminalEnteredControlIOV4.Fact { cells.parentFact }
    func requireHistoricalAssociation(io: ColdEraseSchema2TerminalEnteredControlIOV4) throws {
        guard cells.io === io, cells.original.schemaVersion == 2,
              cells.original.phase == .sessionActivated, cells.completed == cells.original.advancing(to: .cleanupComplete),
              cells.completed.phase == .cleanupComplete, cells.byteCount > 0 else { throw EraseIntentStoreError.invalidAuthority }
        if cells.rawRetirementEnteredV4 {
            guard cells.rawRetirementReturnedV4, cells.canonicalBytes == nil, !cells.borrowing else { throw EraseIntentStoreError.invalidAuthority }
            try io.requireActualCanonicalRawRetirementV4(self)
        } else {
            guard !cells.rawRetirementReturnedV4, let bytes = cells.canonicalBytes,
                  UInt64(bytes.count) == cells.byteCount else { throw EraseIntentStoreError.invalidAuthority }
        }
        try io.requireHistoricalCanonicalReplacementV4(self, cells: cells)
