    func withTerminalCanonicalRatingInputsV4(
        _ body: (ColdEraseRatingCandidateV1, ColdEraseRatingCheckedReceiptV1) throws -> Void) throws {
        guard let candidate = cells.request.storage.candidate, let checked = cells.request.storage.checkedReceipt else {
            throw EraseIntentStoreError.invalidAuthority
