            guard cells[index] == nil else { throw EraseIntentStoreError.invalidAuthority }
            cells[index] = Entry(sequence: sequence, kind: kind, descriptor: descriptor,
                secondDescriptor: -1, resourceOrdinal: ordinal, offset: 0, requested: 0)
