            guard let parent = row.parentOrdinal, try resource(parent).descriptor >= 0 else { throw EraseIntentStoreError.invalidAuthority }
            br = Darwin.fstatat(try resource(parent).descriptor, row.name, &b, AT_SYMLINK_NOFOLLOW)
