    fileprivate func requireActualPolicyFaultResource(ordinal: Int, first: Fact) throws {
        let row = try resource(ordinal)
        guard let root = row.policyFaultRoot, let support = row.policyFaultSupport else { throw EraseIntentStoreError.invalidAuthority }
        try faultStat(ordinal: ordinal, owner: ordinal, expected: first,
            allowEnteredSetterCTime: row.policySetterEntered)
