            guard let request = storage.kPolicyRequest, actualRoot == request.cells.directoryOrdinal else { throw EraseIntentStoreError.invalidAuthority }
            try faultStat(ordinal: actualRoot, owner: ordinal, namedURL: storage.diagnostics.request.diagnosticsURL,
