extension ColdEraseSchema2TerminalEnteredControlIOV4 {
    fileprivate func requireCapacityForActualGrowth(_ additionalBytes: UInt64) throws {
        try memory()
        let retained = try storage.ranges.terminalRetainedBackingBytesV4(self)
        guard let reserve = UInt64(exactly: StoragePreflightService.reserveBytes) else { throw OwnedStorageLedgerFailureV1.capacityUnavailable }
        let sum = try ColdEraseControlBinaryV1.adding(additionalBytes, retained, reserve)
        guard sum <= UInt64(Int64.max) else { throw OwnedStorageLedgerFailureV1.capacityUnavailable }
        let support = try resource(try supportOrdinal)
        guard support.descriptor >= 0,
              try capture(ordinal: try supportOrdinal, namedURL: storage.source.context.eraseURL.deletingLastPathComponent()) == incomingSupport else {
            throw EraseIntentStoreError.invalidAuthority
