        guard result == 0, let blocks = UInt64(exactly: filesystem.f_bavail),
              let blockSize = UInt64(exactly: filesystem.f_bsize), blockSize > 0 else {
            throw OwnedStorageLedgerFailureV1.capacityUnavailable
        }
        let available = blocks.multipliedReportingOverflow(by: blockSize)
        guard !available.overflow, available.partialValue <= UInt64(Int64.max),
              available.partialValue >= sum else { throw OwnedStorageLedgerFailureV1.capacityUnavailable }
        try consume(entry, expected: 0)
        guard try capture(ordinal: try supportOrdinal, namedURL: storage.source.context.eraseURL.deletingLastPathComponent()) == incomingSupport else {
            throw EraseIntentStoreError.invalidAuthority
        }
