              bo1.descriptor == beforeHeld.descriptor, bo2.descriptor == beforeHeld.descriptor,
              a1.descriptor == beforeHeld.descriptor, a2.descriptor == beforeHeld.descriptor,
              b1.sequence < b2.sequence, b2.sequence < beforeHeld.sequence,
              beforeHeld.sequence < beforeNamed.sequence, beforeNamed.sequence < primitive.sequence,
              primitive.sequence < a1.sequence, a1.sequence < ac1.sequence,
              ac1.sequence < a2.sequence, a2.sequence < ac2.sequence,
              ac2.sequence < afterHeld.sequence, afterHeld.sequence < afterNamed.sequence,
              value.childBefore.full.mode & S_IFMT == S_IFREG, value.childBefore.full.links == 1,
              value.childBefore.full.device == value.before.full.device else { throw EraseIntentStoreError.invalidAuthority }
        switch value.kind {
        case .canonicalExclusiveBirth:
            guard storage.canonicalBirthParentV3 == value, storage.cTemporaryOrdinal == value.childOrdinal,
                  value.childName == EraseIntentStore.terminalCanonicalTemporaryNameV4,
                  primitive.kind == .open, try resource(value.childOrdinal).open == value.primitive,
                  let returned = primitive.result, let returnedDescriptor = Int32(exactly: returned), returnedDescriptor >= 0,
                  primitive.requested == Int(O_NOFOLLOW | O_CLOEXEC | O_NONBLOCK | O_RDWR | O_CREAT | O_EXCL),
                  childHeld.descriptor == returnedDescriptor, childHeld.sequence > primitive.sequence,
                  childNamed.sequence > childHeld.sequence,
                  value.childBefore.full.mode & 0o7777 == 0o600, value.childBefore.full.size == 0,
                  !beforeNames.contains(value.childName), afterNames.count == beforeNames.count + 1 else { throw EraseIntentStoreError.invalidAuthority }
            var index = 0, own = 0
            for name in afterNames {
                if name == value.childName { own += 1 }
                else { guard index < beforeNames.count, beforeNames[index] == name else { throw EraseIntentStoreError.invalidAuthority }; index += 1 }
            }
            guard own == 1, index == beforeNames.count else { throw EraseIntentStoreError.invalidAuthority }
        case .returnedRegularChildUnlink(let role):
            guard role >= 0, role < 8, let actual = storage.removals?[role],
                  actual.ownedParentProjectionV3 == value, actual.ordinal == value.childOrdinal,
                  actual.unlink == value.primitive, actual.name == value.childName,
                  actual.parentBefore == value.before, actual.parentAfter == value.after,
                  actual.before == value.childBefore, primitive.kind == .unlink, primitive.result == 0,
                  let synchronization = actual.synchronization, let sync = storage.entries?[synchronization],
                  sync.resourceOrdinal == value.rootOrdinal, sync.descriptor == beforeHeld.descriptor,
                  sync.sequence > primitive.sequence, let absent = actual.absent,
                  let absence = storage.entries?[absent], absence.descriptor == beforeHeld.descriptor,
                  absence.sequence > sync.sequence, childHeld.sequence < primitive.sequence,
                  childNamed.sequence < primitive.sequence,
                  !afterNames.contains(value.childName), beforeNames.count == afterNames.count + 1 else { throw EraseIntentStoreError.invalidAuthority }
            try requireActualReturnedRemovalKernelV3(role)
            var index = 0, own = 0
            for name in beforeNames {
                if name == value.childName { own += 1 }
                else { guard index < afterNames.count, afterNames[index] == name else { throw EraseIntentStoreError.invalidAuthority }; index += 1 }
            }
            guard own == 1, index == afterNames.count else { throw EraseIntentStoreError.invalidAuthority }
        }
        if value.after.full.links == value.before.full.links { return } // unchanged-link incumbent equality
        // Changed links are accepted only by a structural relation proved on
        // BOTH actual closed snapshots under SAME parent. The two additions
        // are actual unique returned '.' and '..' entries, not an inferred
        // unlink decrement or a filesystem stamp. An unsupported relation
        // refuses after the actual projection has already been retained.
        guard firstBefore.actualDirectoryDotsV3 == 3, secondBefore.actualDirectoryDotsV3 == 3,
              firstAfter.actualDirectoryDotsV3 == 3, secondAfter.actualDirectoryDotsV3 == 3,
              let expectedBefore = nlink_t(exactly: beforeNames.count + 2),
              let expectedAfter = nlink_t(exactly: afterNames.count + 2),
              value.before.full.links == expectedBefore, value.after.full.links == expectedAfter else {
            throw EraseIntentStoreError.invalidAuthority
        }
        // This per-operation Source predicate supplies no native filesystem,
        // toolchain, recovery, VM/admission or gate qualification receipt.
    }
}
// TERMINAL_ACTUAL_OWNED_CHILD_PARENT_PROJECTION_V3_END
